#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define MCP3008_ADDR 0x68
#define GPIO8        18
#define GPIO10       19
#define GPIO9        21
#define GPIO11       23

#define SPI_DEVICE "/dev/i2c-1"
#define SENSOR_CHANNEL 0

volatile sig_atomic_t should_exit = 0;

void cleanup_spi(void);
void read_mcp3008(uint8_t channel);
void setup_spi_and_sensor();
void handle_signals(int signum);

int main() {
    struct gpiod_dir gpio_dir;
    int spi_fd;
    uint8_t data;

    // Setup GPIO for MCP3008
    if (gpiod_direction_output(GPIO8, 1) != 0) {
        fprintf(stderr, "Error setting GPIO8 (BCM) as output for CE0\n");
        return EXIT_FAILURE;
    }

    if (gpiod_direction_output(GPIO10, 1) != 0) {
        fprintf(stderr, "Error setting GPIO10 (BCM) as output for MOSI\n");
        return EXIT_FAILURE;
    }

    if (gpiod_direction_output(GPIO9, 0) != 0) {
        fprintf(stderr, "Error setting GPIO9 (BCM) as input for MISO\n");
        return EXIT_FAILURE;
    }

    if (gpiod_direction_output(GPIO11, 1) != 0) {
        fprintf(stderr, "Error setting GPIO11 (BCM) as output for SCLK\n");
        return EXIT_FAILURE;
    }

    // Setup SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device %s\n", SPI_DEVICE);
        return EXIT_FAILURE;
    }

    setup_spi_and_sensor();

    while (!should_exit) {
        // Read moisture sensor
        read_mcp3008(SENSOR_CHANNEL);

        // Print raw ADC value and timestamp
        time_t now = time(NULL);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        printf("Raw ADC value: %u, Time: %s\n", data, localtime_r(&now, &timeinfo).tm_hour ":" localtime_r(&now, &timeinfo).tm_min ":" localtime_r(&now, &timeinfo).tm_sec);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    cleanup_spi();

    return EXIT_SUCCESS;
}

void cleanup_spi(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

void read_mcp3008(uint8_t channel) {
    uint16_t command = (MCP3008_ADDR << 4) | (channel & 0x0F);
    uint16_t data_out = 0;

    if (write(spi_fd, &command, 2) != 2) {
        fprintf(stderr, "Error writing to MCP3008\n");
        return;
    }

    if (read(spi_fd, &data_out, 1) != 1) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return;
    }

    data = (data_out >> 8) | (data_out & 0x00FF);
}

void setup_spi_and_sensor() {
    struct spi_ioc_transfer transfers[] = {
        // Transfer to select the MCP3008
        {
            .tx_buf = &MCP3008_ADDR,
            .rx_buf = NULL,
            .len = sizeof(MCP3008_ADDR),
            .delay_usecs = 0,
        },
        // Transfer to read from MCP3008
        {
            .tx_buf = NULL,
            .rx_buf = &data_out,
            .len = sizeof(uint16_t),
            .delay_usecs = 10000,
        },
    };

    int rc = spi_ioc_transfer(spi_fd, transfers, 2);
    if (rc != 2) {
        fprintf(stderr, "Error during SPI transfer\n");
        cleanup_spi();
        exit(EXIT_FAILURE);
    }
}

void handle_signals(int signum) {
    should_exit = 1;
}

