#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <ads1115.h>

#define ADS1115_I2C_ADDR 0x48  // Default address for ADS1115
#define MLX91219_ADDR_GND 0x00  // ADDR pin tied to GND

// MLX91219 configuration constants
#define MLX91219_CONFIG_GAIN_4_096 0b0001  // Gain of ±4.096V
#define MLX91219_CONFIG_MODE_SINGLE_SHOT 0b0100  // Single-shot mode

// GPIO pins
#define SDA_GPIO 2  // BCM GPIO2
#define SCL_GPIO 3  // BCM GPIO3

// ADS1115 configuration
#define ADS1115_CONFIG_MODE_SINGLE_ENDED 0x00  // Single-ended input
#define ADS1115_CONFIG_SAMPLING_RATE_128_SPS 0x07  // 128 SPS

// Function prototypes
void handleSIGINT(int signum);
int ads1115_init();
int ads1115_read(uint16_t channel);
float mlx91219_current_to_amperes(uint16_t raw_value);

int main() {
    // Initialize GPIO for I2C
    int sda_gpio_direction = gpiod_direction_output(SDA_GPIO, 1);
    int scl_gpio_direction = gpiod_direction_output(SCL_GPIO, 1);

    if (sda_gpio_direction != GPIO_OUTPUT_ACTIVE || scl_gpio_direction != GPIO_OUTPUT_ACTIVE) {
        fprintf(stderr, "Failed to configure GPIO for I2C\n");
        return EXIT_FAILURE;
    }

    // Initialize ADS1115
    ads1115_context ads1115_ctx;
    int ads1115_init_result = ads1115_init(&ads1115_ctx);

    if (ads1115_init_result != ADS1115_OK) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    ads1115_config_t config = {
        .mode = ADS1115_CONFIG_MODE_SINGLE_ENDED,
        .gain = MLX91219_CONFIG_GAIN_4_096,
        .sampling_rate = ADS1115_CONFIG_SAMPLING_RATE_128_SPS
    };

    ads1115_set_config(&ads1115_ctx, &config);

    // Main loop
    while (1) {
        uint16_t raw_value;
        int read_result = ads1115_read(ADS1115_CHANNEL_A0, &raw_value);

        if (read_result != ADS1115_OK) {
            fprintf(stderr, "Error reading ADS1115\n");
            break;
        }

        float current_in_amperes = mlx91219_current_to_amperes(raw_value);

        printf("Current: %.2f A\n", current_in_amperes);

        usleep(500 * 1000);  // Sleep for 500 ms
    }

    // Clean up on SIGINT
    handleSIGINT(SIGINT);

    return EXIT_SUCCESS;
}

// Function to handle SIGINT (Ctrl+C)
void handleSIGINT(int signum) {
    // Close ADS1115 handle and cleanup
    ads1115_close(&ads1115_ctx);

    // Release GPIO pins
    gpiod_set_value(SDA_GPIO, 0);
    gpiod_set_value(SCL_GPIO, 0);

    // Exit the program
    exit(0);
}

// Function to initialize ADS1115
int ads1115_init(ads1115_context *ctx) {
    int ret = ads1115_open(ctx, ADS1115_I2C_ADDR);

    if (ret != ADS1115_OK) {
        fprintf(stderr, "Failed to open ADS1115\n");
        return ret;
    }

    return ADS1115_OK;
}

// Function to read from ADS1115
int ads1115_read(uint16_t channel, uint16_t *data) {
    int ret = ads1115_read_single(ctx, channel, data);

    if (ret != ADS1115_OK) {
        fprintf(stderr, "Error reading ADS1115\n");
        return ret;
    }

    return ADS1115_OK;
}

// Convert raw value to current in amperes
float mlx91219_current_to_amperes(uint16_t raw_value) {
    // Assuming the full-scale range of MLX91219 is 32V (±16V) and gain is 4.096V
    // Full-scale raw value = 32V / 4096 = 0x8000
    // Therefore, 1 A = 0x8000 / 32 = 0x200

    return (float)raw_value / 0x200;
}

