#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO4 27
#define GPIO8 7
#define MCP3008_CHANNEL 0

int main() {
    // GPIO setup
    int gpio4 = gpiod_open(GPIO4, GPIO_MODE_INPUT);
    if (gpio4 < 0) {
        fprintf(stderr, "Error opening GPIO4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int gpio8 = gpiod_open(GPIO8, GPIO_MODE_OUTPUT);
    if (gpio8 < 0) {
        fprintf(stderr, "Error opening GPIO8: %s\n", strerror(errno));
        gpiod_close(gpio4);
        return EXIT_FAILURE;
    }

    // Set GPIO4 as input and GPIO8 as output
    gpiod_direction_input(gpio4);
    gpiod_direction_output(gpio8, 1, 1);

    // MCP3008 setup
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_close(gpio4);
        gpiod_close(gpio8);
        return EXIT_FAILURE;
    }

    struct spi_i2c_dev *spi;
    int rc = spi_bcm2835_setup(&spi, SPI_DEVICE, SPI_SPEED);
    if (rc < 0) {
        fprintf(stderr, "Error setting up SPI: %s\n", strerror(rc));
        close(spi_fd);
        gpiod_close(gpio4);
        gpiod_close(gpio8);
        return EXIT_FAILURE;
    }

    // Initialize MCP3008
    if (mcp3008_init(spi) < 0) {
        fprintf(stderr, "Error initializing MCP3008: %s\n", mcp3008_get_error());
        spi_bcm2835_free(spi);
        close(spi_fd);
        gpiod_close(gpio4);
        gpiod_close(gpio8);
        return EXIT_FAILURE;
    }

    // Flame sensor setup
    uint8_t flame_detected = 0;
    if (gpiod_read(gpio4, &flame_detected, sizeof(flame_detected)) < 0) {
        fprintf(stderr, "Error reading GPIO4: %s\n", strerror(errno));
        mcp3008_free(spi);
        spi_bcm2835_free(spi);
        close(spi_fd);
        gpiod_close(gpio4);
        gpiod_close(gpio8);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read MCP3008
        int adc_value;
        if (mcp3008_read(spi, MCP3008_CHANNEL) < 0) {
            fprintf(stderr, "Error reading MCP3008: %s\n", mcp3008_get_error());
            continue;
        }
        adc_value = (adc_value * 3.3) / 1024; // Convert to voltage level

        // Calculate temperature (approximation)
        float temperature = adc_value * 5.0 / 1024.0; // Assuming a simple linear relationship

        // Log data
        struct tm timeinfo;
        time_t rawtime = time(NULL);
        localtime_r(&rawtime, &timeinfo);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        char line[256];
        sprintf(line, "%s,%d,%f\n", timestamp, flame_detected, temperature);

        // Open or append to flame_data.csv
        int fd = fopen("flame_data.csv", "a+");
        if (fd == NULL) {
            fprintf(stderr, "Error opening or appending to flame_data.csv: %s\n", strerror(errno));
            continue;
        }

        // Write to file
        if (fwrite(line, sizeof(line[0]), strlen(line), fd) != strlen(line)) {
            fprintf(stderr, "Error writing to flame_data.csv: %s\n", strerror(errno));
            fclose(fd);
            continue;
        }

        fclose(fd);

        // Ensure resources are released on SIGINT
        signal(SIGINT, SIG_DFL);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on normal exit
    mcp3008_free(spi);
    spi_bcm2835_free(spi);
    close(spi_fd);
    gpiod_close(gpio4);
    gpiod_close(gpio8);

    return EXIT_SUCCESS;
}

