            fclose(fd);
            continue;
        }

        fclose(fd);

        // Ensure resources are released on SIGINT
        signal(SIGINT, SIG_DFL);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on normal exit
    mcp3008_free(spi);
    spi_bcm2835_free(spi);
    close(spi_fd);
    gpiod_close(gpio4);
    gpiod_close(gpio8);

