int main() {
    // Initialize GPIO for fan control
    int gpio_fan_fd = open_gpio(GPIO_FAN_PIN);
    if (gpio_fan_fd == -1) {
        perror("Failed to open GPIO pin for fan control");
        return EXIT_FAILURE;
    }

    // Initialize SPI and ADC
    int spidev_fd = open(SPI_DEVICE, O_RDWR);
    if (spidev_fd == -1) {
        perror("Failed to open SPI device");
        close_gpio(gpio_fan_fd);
        return EXIT_FAILURE;
    }

    struct iio_simple_device *mcp3008_device;
    int ret = iio_simple_device_create("mcp3008", spidev_fd, &mcp3008_device);
    if (ret) {
        perror("Failed to create MCP3008 device");
        close(spidev_fd);
        close_gpio(gpio_fan_fd);
        return EXIT_FAILURE;
    }

    // Set up SPI parameters
    ret = iio_simple_device_set_property(mcp3008_device, "clock-frequency", "1000000");
    if (ret) {
