        iio_simple_device_destroy(mcp3008_device);
        close(spidev_fd);
        close_gpio(gpio_fan_fd);
        return EXIT_FAILURE;
    }

    // Set initial fan state to LOW
    set_gpio_low(gpio_fan_fd);

