            fprintf(stderr, "Sensor absent condition detected\n");
            continue;
        }

        double current = (data->data[0] * 3.3 + data->data[1] / 8.0); // Convert ADC value to current

        // Log current to file
        log_current_to_file(current);

        // Control the fan based on current reading
        setup_and_control_fan(current);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on SIGINT or SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Wait for interrupt
    while (1) {}

    return EXIT_SUCCESS;
}

