void setup_and_control_fan(double current) {
    if (current > THRESHOLD_CURRENT) {
        set_gpio_high(gpio_fan_fd); // Turn fan ON
    } else {
        set_gpio_low(gpio_fan_fd); // Turn fan OFF
    }
}

// Function to open GPIO pin
int open_gpio(int gpio_num) {
    int fd = -1;
    char name[] = "gpio";
    if (sysfs_exists("/sys/class/gpio/export", "gpio" + gpio_num)) {
        fd = open("/sys/class/gpio/export", O_WRONLY);
        if (fd == -1) {
            perror("Failed to export GPIO pin");
            return fd;
        }
        write(fd, "gpio" + gpio_num, strlen("gpio" + gpio_num));
        fd = open("/sys/class/gpio/gpio" + gpio_num, O_RDONLY);
        if (fd == -1) {
            perror("Failed to open GPIO pin");
            return fd;
        }
    } else {
        // Fall back to chip 0
        fd = open("/sys/class/gpio/gpio0", O_RDONLY);
        if (fd == -1) {
            perror("Failed to open GPIO pin (chip 0)");
            return fd;
        }
        write(fd, "export", 5);
        write(fd, "direction", 8);
        write(fd, "out", 3);
        write(fd, "value", (gpio_num == GPIO_FAN_PIN) ? "1" : "0", 4);
    }
    return fd;
}

// Function to close GPIO pin
void close_gpio(int gpio_fd) {
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
}

