int sysfs_exists(const char *path, const char *file) {
    char *dir = malloc(strlen(path) + strlen(file) + 2);
    if (!dir) {
        perror("malloc failed");
        return -1;
    }
    strcpy(dir, path);
    strcat(dir, "/");
    strcat(dir, file);
    if (access(dir, F_OK) == 0) {
        free(dir);
        return 1;
    } else {
        free(dir);
        return 0;
    }
}

