void cleanup() {
    // Close SPI device and release resources
    close(spidev_fd);
    iio_simple_device_destroy(mcp3008_device);

    // Close GPIO file descriptor
    close_gpio(gpio_fan_fd);

    // Ensure fan is turned OFF
    set_gpio_low(gpio_fan_fd);
}

