    // No specific GPIO setup needed for this program
}

// Function to setup I2C
void setup_i2c() {
    int ret;

    // Initialize I2C
    ret = i2c_init(I2C_BUS_NUM);
    if (ret != 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", i2c_errstr(ret));
        exit(EXIT_FAILURE);
    }

