    char filename[256];
    time_t now;
    struct tm *timeinfo;
    FILE *file;

    // Format the timestamp and filename
    now = time(nullptr);
    timeinfo = localtime(&now);
    strftime(filename, sizeof(filename), "co_log_%Y-%m-%d_%H%M%S.txt", timeinfo);

    // Open the file for appending
    file = fopen(filename, "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging: %s\n", strerror(errno));
        return;
    }

    // Write the timestamp and ppm value to the file
    fprintf(file, "%s: %.2f ppm\n", asctime(timeinfo), ppm);
