        case -EBUSY:
            return "EBUSY";
        case -ENODEV:
            return "ENODEV";
        case -ENXIO:
            return "ENXIO";
        default:
            return "Unknown I2C error";
    }
}

char *gpiod_errstr(int err) {
    switch (err) {
        case -1:
            return "Initialization failed";
        default:
            return "Unknown GPIO error";
    }
}

