#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod.h>

#define MIC1_GPIO 8 // CE0 on GPIO8 (BCM)
#define MIC2_GPIO 9 // CE1 on GPIO9 (BCM)
#define MISO_GPIO 9 // MISO on GPIO9 (BCM)
#define MOSI_GPIO 10 // MOSI on GPIO10 (BCM)
#define SCLK_GPIO 11 // SCLK on GPIO11 (BCM)
#define LED_GPIO 27 // LED on GPIO27 (BCM)

#define SPI0_BASE 0
#define MCP3008_ADDR 0x01

#define HIGH_THRESHOLD 1000 // Arbitrary high threshold for RMS level

volatile sig_atomic_t sigint_received = 0;

void setup_gpios(void) {
    int mic1_ce = gpiod_open(MIC1_GPIO, GPIOD_OUT_INIT_LOW);
    int mic2_ce = gpiod_open(MIC2_GPIO, GPIOD_OUT_INIT_LOW);
    int led = gpiod_open(LED_GPIO, GPIOD_OUT_INIT_LOW);

    if (mic1_ce < 0 || mic2_ce < 0 || led < 0) {
        perror("Failed to open GPIO pins");
        exit(EXIT_FAILURE);
    }

    gpiod_set_value(mic1_ce, 1); // Set CE0 high
    gpiod_set_value(mic2_ce, 1); // Set CE1 high

    gpiod_set_value(led, 0); // Turn LED off initially
}

void cleanup_gpios(void) {
    gpiod_set_value(mic1_ce, 0); // Release CE0
    gpiod_set_value(mic2_ce, 0); // Release CE1
    gpiod_set_value(led, 0); // Turn LED off

    gpiod_close(mic1_ce);
    gpiod_close(mic2_ce);
    gpiod_close(led);
}

void setup_spi(void) {
    struct spi_device *spi;
    int spi_master;

    spi_master = spi_bcm2835_get_master();

    if (spi_master < 0) {
        perror("Failed to get SPI master");
        exit(EXIT_FAILURE);
    }

    spi = spi_bcm2835_select_device(spi_master, SPI0_BASE);

    if (spi == NULL) {
        perror("Failed to select SPI0");
        exit(EXIT_FAILURE);
    }

    if (mcp3008_write_reg(spi, MCP3008_ADDR, MCP3008_REG_MODE_8) < 0) {
        perror("Failed to set MCP3008 to mode 8");
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi(void) {
    if (spi) {
        spi_bcm2835_free(spi);
        spi = NULL;
    }
}

void sample_and_compute_rms(int adc_channel, uint16_t *data) {
    int i;
    *data = 0;

    for (i = 0; i < 1; i++) { // One sample per channel
        if (mcp3008_read_adc(spi, adc_channel) < 0) {
            perror("Failed to read ADC");
            exit(EXIT_FAILURE);
        }

        *data += (uint16_t)mcp3008_read_adc(spi, adc_channel);
    }

    *data /= 1; // Since we only took one sample per channel
    int16_t rms = (int16_t)sqrt((*data * 0.5)); // Compute RMS

    if (rms > HIGH_THRESHOLD) {
        // Trigger LED if RMS exceeds threshold
        gpiod_set_value(led, 1); // Turn LED on
        usleep(500 * 1000); // Keep LED on for 500ms
        gpiod_set_value(led, 0); // Turn LED off
    }
}

void handle_sigint(int signum) {
    sigint_received = 1;
    // Clean up and exit
    cleanup_gpios();
    cleanup_spi();
    exit(EXIT_SUCCESS);
}

int main(void) {
    setup_gpios();
    setup_spi();
    signal(SIGINT, handle_sigint);

    uint16_t mic1_data[100];
    uint16_t mic2_data[100];
    struct stat stat_buf;
    char filename[256];
    FILE *file;
    time_t timestamp;

    // Open file for writing
    snprintf(filename, sizeof(filename), "audio_events.csv");
    file = fopen(filename, "a+");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    // Get initial timestamp
    time(&timestamp);

    for (int i = 0; i < 100; i++) {
        if (sigint_received) {
            // Handle SIGINT by cleaning up and exiting
            cleanup_gpios();
            cleanup_spi();
            fclose(file);
            exit(EXIT_SUCCESS);
        }

        // Sample and compute RMS for each microphone
        sample_and_compute_rms(0, mic1_data + i);
        sample_and_compute_rms(1, mic2_data + i);

        // Write to file
        fprintf(file, "%ld,%d,%d\n", timestamp, mic1_data[i], mic2_data[i]);

        // Increment timestamp
        time(&timestamp);
    }

    fclose(file);

    cleanup_gpios();
    cleanup_spi();

    return 0;
}

