#include <stdint.h>

#define I2C_BUS_NUM 1
#define TCS34725_ADDR 0x20
#define TCS34725_REG_ID 0x00
#define TCS34725_REG_CLEAR 0x20
#define TCS34725_REG_RED 0x21
#define TCS34725_REG_GREEN 0x22
#define TCS34725_REG_BLUE 0x23

// Function prototypes
void initialize_sensor();
void read_sensor_values(uint8_t* clear, uint8_t* red, uint8_t* green, uint8_t* blue);
void write_sensor_reg(uint8_t reg, uint8_t value);
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize the sensor
    initialize_sensor();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // File descriptor for the CSV log file
    int csv_fd = -1;
    char filename[256];
    snprintf(filename, sizeof(filename), "color_log.csv");
    csv_fd = open(filename, O_CREAT | O_APPEND | O_WRONLY, 0644);

    if (csv_fd == -1) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    // Header row
    char header[256] = "YYYY-MM-DD HH:MM:SS,clear,red,green,blue";
    if (write(csv_fd, header, sizeof(header)) != sizeof(header)) {
        perror("Failed to write header to CSV file");
        close(csv_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read sensor values
        uint8_t clear_value, red_value, green_value, blue_value;
        read_sensor_values(&clear_value, &red_value, &green_value, &blue_value);

        // Format and write data to CSV
        char timestamp[256];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        char data[256];
        sprintf(data, "%s,%u,%u,%u,%u", timestamp, clear_value, red_value, green_value, blue_value);

        if (write(csv_fd, data, strlen(data)) != strlen(data)) {
            perror("Failed to write data to CSV file");
            break; // Exit loop on write failure
        }

        // Sleep for 1 second without blocking signals
        struct timespec ts;
        ts.tv_sec = 1;
        ts.tv_nsec = 0;

        if (clock_nanosleep(CLOCK_REALTIME, &ts, NULL, NULL) == -1) {
            perror("Failed to sleep");
            break; // Exit loop on sleep failure
        }
    }

    // Cleanup on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close I2C handle and CSV file
    close(csv_fd);
    cleanup();

    return 0;
}

// Function to initialize the sensor
void initialize_sensor() {
    int i2c_fd;
    struct gpiod_i2c_bus *i2c_bus;

    // Open I2C bus 1
    i2c_bus = gpiod_i2c_bus_open(I2C_BUS_NUM);
    if (!i2c_bus) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS_NUM);
        exit(EXIT_FAILURE);
    }

    // Open the TCS34725 device
    i2c_fd = gpiod_i2c_open(i2c_bus, TCS34725_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open TCS34725 device on I2C bus %d\n", I2C_BUS_NUM);
        gpiod_i2c_bus_close(i2c_bus);
        exit(EXIT_FAILURE);
    }

    // Check if the sensor's ID register matches the expected value
    uint8_t id_reg;
    write_sensor_reg(TCS34725_REG_ID, 0x34); // Expected value for Adafruit TCS34725
    if (read_sensor_reg(TCS34725_REG_ID) != 0x34) {
        fprintf(stderr, "Sensor ID does not match expected value. Exiting...\n");
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_bus_close(i2c_bus);
        exit(EXIT_FAILURE);
    }

    // Success
    printf("Sensor initialized successfully.\n");
}

// Function to read sensor values
void read_sensor_values(uint8_t* clear_value, uint8_t* red_value, uint8_t* green_value, uint8_t* blue_value) {
    // Write to clear register
    write_sensor_reg(TCS34725_REG_CLEAR, 0x07); // Clear filter

    // Wait at least 3 ms after power-on before reading
    usleep(3000);

    // Read values
    if (gpiod_i2c_read(i2c_fd, TCS34725_REG_CLEAR, clear_value, 1) < 1) {
        fprintf(stderr, "Failed to read clear value. Retrying...\n");
        return;
    }
    if (gpiod_i2c_read(i2c_fd, TCS34725_REG_RED, red_value, 1) < 1) {
        fprintf(stderr, "Failed to read red value. Retrying...\n");
        return;
    }
    if (gpiod_i2c_read(i2c_fd, TCS34725_REG_GREEN, green_value, 1) < 1) {
        fprintf(stderr, "Failed to read green value. Retrying...\n");
        return;
    }
    if (gpiod_i2c_read(i2c_fd, TCS34725_REG_BLUE, blue_value, 1) < 1) {
        fprintf(stderr, "Failed to read blue value. Retrying...\n");
        return;
    }
}

// Function to write to a sensor register
void write_sensor_reg(uint8_t reg, uint8_t value) {
    if (gpiod_i2c_write(i2c_fd, reg, value, 1) < 1) {
        fprintf(stderr, "Failed to write to register. Retrying...\n");
        return;
    }
    printf("Wrote to register %02X with value %02X\n", reg, value);
}

// Function to cleanup and close resources
void cleanup() {
    // Close I2C handle
    gpiod_i2c_close(i2c_fd);
    gpiod_i2c_bus_close(i2c_bus);

    // Close CSV file
    close(csv_fd);
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Close I2C handle and CSV file
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

