void cleanup_gpios();
void setup_spi();
void cleanup_spi();
void read_current_from_adc(uint8_t channel);
void handle_overcurrent();
void write_to_log_file(const char *message);
void handle_interrupts(int signum);

int main() {
    // Initialize GPIOs
    setup_gpios();

    // Setup SPI
    setup_spi();

    // Signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Main loop
    while (1) {
        // Sample current
        uint16_t adc_value = read_current_from_adc(MLX91211_ANALOG_CHANNEL);

        // Convert ADC value to amperes
        float current_amps = adc_value * 0.0625; // Assuming a full-scale range of 4V and a gain of 64

        // Check for overcurrent
        if (current_amps > 10.0) {
            handle_overcurrent();
        }

        // Write to log file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_to_log_file("Current: %.2f A, Timestamp: %s\n", current_amps, timestamp);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    cleanup_spi();
    cleanup_gpios();

    return 0;
}

// Function to setup GPIOs
void setup_gpios() {
    int gpio8_fd = gpiod_open(GPIO8_PIN, GPIOD_OPEN_RW);
    if (gpio8_fd < 0) {
        perror("gpiod_open(GPIO8_PIN)");
        exit(EXIT_FAILURE);
    }

    int gpio11_fd = gpiod_open(GPIO11_PIN, GPIOD_OPEN_R);
    if (gpio11_fd < 0) {
        perror("gpiod_open(GPIO11_PIN)");
        gpiod_close(gpio8_fd);
        exit(EXIT_FAILURE);
    }

    int gpio10_fd = gpiod_open(GPIO10_PIN, GPIOD_OPEN_R);
    if (gpio10_fd < 0) {
        perror("gpiod_open(GPIO10_PIN)");
        gpiod_close(gpio11_fd);
        gpiod_close(gpio8_fd);
        exit(EXIT_FAILURE);
    }

    int gpio9_fd = gpiod_open(GPIO9_PIN, GPIOD_OPEN_R);
    if (gpio9_fd < 0) {
        perror("gpiod_open(GPIO9_PIN)");
        gpiod_close(gpio10_fd);
        gpiod_close(gpio11_fd);
        gpiod_close(gpio8_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_set_data_direction(gpio8_fd, GPIOD_DATA_OUT);
    gpiod_write(gpio8_fd, 1, GPIO_ACTIVE_HIGH);

    gpiod_set_data_direction(gpio11_fd, GPIOD_DATA_OUT);
    gpiod_set_direction(gpio11_fd, GPIOD_DIR_OUT);

    gpiod_set_data_direction(gpio10_fd, GPIOD_DATA_IN);
    gpiod_set_direction(gpio10_fd, GPIOD_DIR_IN);

    gpiod_set_data_direction(gpio9_fd, GPIOD_DATA_IN);
    gpiod_set_direction(gpio9_fd, GPIOD_DIR_IN);

    gpiod_close(gpio9_fd);
    gpiod_close(gpio10_fd);
    gpiod_close(gpio11_fd);
    gpiod_close(gpio8_fd);
