    gpiod_close(gpiod_get_fd(GPIO8_PIN));
    gpiod_close(gpiod_get_fd(GPIO11_PIN));
    gpiod_close(gpiod_get_fd(GPIO10_PIN));
    gpiod_close(gpiod_get_fd(GPIO9_PIN));
}

// Function to setup SPI
void setup_spi() {
    int spi_fd = gpiod_open(GPIO11_PIN, GPIOD_OPEN_R);
    if (spi_fd < 0) {
        perror("gpiod_open(GPIO11_PIN for SPI)");
        exit(EXIT_FAILURE);
    }

    struct gpiod_spi_config spi_config = {
