#define MCP3008_ADDR 0x7E
#define SPI0_NAME "spi0"
#define CE_GPIO_NUM 8
#define SCLK_GPIO_NUM 11
#define MOSI_GPIO_NUM 10
#define MISO_GPIO_NUM 9
#define GPIO27_NUM 27
#define MAX_CURRENT 10.0

volatile sig_atomic_t should_exit = 0;

void handle_overcurrent() {
    gpio_set_value(GPIO27_NUM, GPIO_HIGH);
    fprintf(stderr, "OVERCURRENT EVENT DETECTED!\n");
    exit(1);
}

void cleanup_resources() {
    if (gpiod_is_valid(GPIO27_NUM)) {
        gpio_free(GPIO27_NUM);
    }

    if (gpiod_is_valid(CE_GPIO_NUM)) {
        gpio_free(CE_GPIO_NUM);
    }

    if (gpiod_is_valid(SCLK_GPIO_NUM)) {
        gpio_free(SCLK_GPIO_NUM);
    }

    if (gpiod_is_valid(MOSI_GPIO_NUM)) {
        gpio_free(MOSI_GPIO_NUM);
    }

    if (gpiod_is_valid(MISO_GPIO_NUM)) {
        gpio_free(MISO_GPIO_NUM);
    }

    if (libgpiod_spi_device_is_valid(SPI0_NAME)) {
        libgpiod_spi_device_remove(SPI0_NAME);
    }
}

int main() {
    struct spi_device *spi;
    int spi_fd;
    int adc_channel = 0;
    int adc_value;
    time_t now;
    char buffer[128];
    FILE *log_file = fopen("current_log.txt", "a+");

    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent double handling
    signal(SIGTERM, SIG_IGN);

    while (!should_exit) {
        // Check for termination signals
        if (should_exit) {
            cleanup_resources();
            break;
        }

        // Read current
        spi = libgpiod_spi_device_lookup(SPI0_NAME);
        if (!spi) {
            fprintf(stderr, "Failed to find SPI device %s\n", SPI0_NAME);
            continue;
        }

        spi_fd = libgpiod_spi_device_open(spi);
        if (spi_fd < 0) {
            fprintf(stderr, "Failed to open SPI device %s\n", SPI0_NAME);
            libgpiod_spi_device_remove(spi);
            continue;
        }

        // Configure SPI
        libgpiod_spi_set_mode(spi_fd, 0); // SPI mode 0
        libgpiod_spi_set_speed(spi_fd, 1000000); // 1 MHz

        // Set CE pin high
        gpio_set_value(CE_GPIO_NUM, GPIO_HIGH);

        // Perform SPI transfer
        adc_value = libgpiod_spi_transfer(spi_fd, MCP3008_ADDR, adc_channel, 1);

        // Check for SPI transfer errors
        if (adc_value < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Convert ADC value to current
        float current = adc_value * (MAX_CURRENT / 1023.0);

        // Check for invalid ADC values
        if (current > MAX_CURRENT) {
            handle_overcurrent();
        }

        // Log current with timestamp
        now = time(NULL);
        sprintf(buffer, "%ld %f\n", (long)now, current);
        fwrite(buffer, sizeof(buffer), 1, log_file);

        // Set CE pin low
        gpio_set_value(CE_GPIO_NUM, GPIO_LOW);

        // Close SPI device after each reading to avoid resource leaks
        libgpiod_spi_device_close(spi_fd);
    }

    fclose(log_file);

    // Clean up on exit
    cleanup_resources();

    return EXIT_SUCCESS;
}

