#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_ALARM 4

#define SAMPLE_RATE_HZ 1
#define MAX_ATTEMPTS 5

int main() {
    struct gpiod_dir gpio_dir;
    struct gpiod_cdg gpio_cdg;
    int spi_fd;
    int ret;
    unsigned int voltage;
    time_t timestamp;
    char buffer[100];
    FILE *log_file;

    // Initialize GPIO for CE0
    if (gpiod_cdg_init(&gpio_cdg, GPIO_CE0) < 0) {
        fprintf(stderr, "Error initializing GPIO CE0\n");
        return EXIT_FAILURE;
    }

    // Set GPIO CE0 as output
    if (gpiod_set_direction(&gpio_dir, GPIO_CE0, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error setting GPIO CE0 direction\n");
        gpiod_cdg_cleanup(&gpio_cdg);
        return EXIT_FAILURE;
    }

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        return EXIT_FAILURE;
    }

    // Initialize libgpiod SPI
    if (libgpiod_spi_setup(spi_fd, 1000000, SPI_MODE_0) < 0) {
        fprintf(stderr, "Error initializing SPI\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file for writing
    if ((log_file = fopen("co_log.txt", "a")) == NULL) {
        fprintf(stderr, "Error opening log file\n");
        libgpiod_spi_teardown(spi_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read voltage from MCP3008
        voltage = 0;
        for (int i = 0; i < MAX_ATTEMPTS; ++i) {
            if ((ret = libgpiod_spi_transfer(spi_fd, 0x01, 0, &voltage)) < 0) {
                fprintf(stderr, "Error reading from MCP3008: %s\n", libgpiod_spi_get_error(spi_fd));
                usleep(1000000); // Wait 1 second
                continue;
            }
            break; // Success
        }

        if (i == MAX_ATTEMPTS) {
            fprintf(stderr, "Failed to read from MCP3008 after %d attempts\n", MAX_ATTEMPTS);
            break;
        }

        // Convert voltage to voltage level
        if (voltage >= 2048) {
            // Voltage exceeds 2.5V, set GPIO alarm HIGH
            if (gpiod_set_value(&gpio_dir, GPIO_ALARM, 1) < 0) {
                fprintf(stderr, "Error setting GPIO alarm HIGH\n");
                break;
            }
        } else {
            // Voltage does not exceed 2.5V, set GPIO alarm LOW
            if (gpiod_set_value(&gpio_dir, GPIO_ALARM, 0) < 0) {
                fprintf(stderr, "Error setting GPIO alarm LOW\n");
                break;
            }
        }

        // Get current time
        timestamp = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", buffer);
        sprintf(buffer + strlen(buffer), "%f", (float)voltage * 3.3 / 4096); // Assuming 3.3V reference voltage

        // Write to log file
        if (fprintf(log_file, "%s,Voltage: %.2f V\n", buffer, (float)voltage * 3.3 / 4096) < 0) {
            fprintf(stderr, "Error writing to log file\n");
            break;
        }

        // Close resources on SIGINT or SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error setting signal handlers\n");
            break;
        }

        // SIGINT or SIGTERM handler
        void sig_handler(int signum) {
            fclose(log_file);
            libgpiod_spi_teardown(spi_fd);
            close(spi_fd);
            gpiod_cdg_cleanup(&gpio_cdg);
            printf("SIGINT or SIGTERM received, cleaning up\n");
        }

        // Install signal handler
        if (signal(SIGINT, sig_handler) == SIG_ERR || signal(SIGTERM, sig_handler) == SIG_ERR) {
            fprintf(stderr, "Error installing signal handlers\n");
            break;
        }
    }

    // Cleanup on normal exit
    libgpiod_spi_teardown(spi_fd);
    close(spi_fd);
    gpiod_cdg_cleanup(&gpio_cdg);

    return EXIT_SUCCESS;
}

