#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS_NUM 1
#define ADS1115_ADDR 0x48
#define MLX90830_REG_PRESSURE 0x00

#define GPIO2_NUM 2
#define GPIO3_NUM 3

// ADS1115 configuration
#define ADS1115_GAIN 1
#define ADS1115_MODE_12BIT

// I2C device file path
#define I2C_DEVICE "/dev/i2c-1"

// GPIO direction and value constants
#define GPIO_DIR_OUT GPIO_OUTPUT_DIR_OUT
#define GPIO_VALUE_HIGH 1

// Function prototypes
void setup_io();
void cleanup_io();
int read_ads1115(uint8_t command);
void handle_signal(int signum);

int main() {
    // Initialize GPIO pins for SDA and SCL
    setup_io();

    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Open I2C device
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C device");
        return EXIT_FAILURE;
    }

    // ADS1115 configuration register write
    uint8_t config_reg = (ADS1115_MODE_12BIT << ADS1115_CONFIG_REG_MODE_SHIFT);
    if (write(i2c_fd, &config_reg, 1) != 1) {
        perror("Error writing to ADS1115 configuration register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO pins for SDA and SCL
    if (gpio_direction_output(GPIO2_NUM, GPIO2_NUM) != 0 ||
        gpio_direction_output(GPIO3_NUM, GPIO3_NUM) != 0) {
        perror("Error setting GPIO direction");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO pins to high (enabling pull-up resistors)
    if (gpio_set_value(GPIO2_NUM) != GPIO_VALUE_HIGH ||
        gpio_set_value(GPIO3_NUM) != GPIO_VALUE_HIGH) {
        perror("Error setting GPIO values");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t pressure;
        time_t now = time(NULL);
        struct tm timeinfo;
        char timestamp[50];

        // Read pressure from MLX90830
        if (read_ads1115(MLX90830_REG_PRESSURE) != 1) {
            perror("Error reading pressure");
            continue;
        }

        pressure = (uint16_t)read_ads1115_data();

        // Validate pressure range
        if (pressure < 0 || pressure > 10000) {
            fprintf(stderr, "Invalid pressure reading: %d\n", pressure);
            continue;
        }

        // Format ISO 8601 timestamp
        timeinfo = *localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

        // Write to file
        FILE *pressure_log = fopen("pressure_log.txt", "a+");
        if (!pressure_log) {
            perror("Error opening pressure log file");
            break; // Exit on failure
        }

        fprintf(pressure_log, "%s, %d\n", timestamp, pressure);
        fclose(pressure_log);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup_io();

    return EXIT_SUCCESS;
}

// Function to setup GPIO pins
void setup_io() {
    // Set GPIO2 and GPIO3 as output
    if (gpio_export(GPIO2_NUM, GPIO2_NUM) != 0 ||
        gpio_export(GPIO3_NUM, GPIO3_NUM) != 0) {
        perror("Error exporting GPIO pins");
        return;
    }

    // Set GPIO2 and GPIO3 to high (pull-up)
    if (gpio_direction_output(GPIO2_NUM, GPIO_DIR_OUT) != 0 ||
        gpio_direction_output(GPIO3_NUM, GPIO_DIR_OUT) != 0) {
        perror("Error setting GPIO direction");
        return;
    }

    if (gpio_set_value(GPIO2_NUM) != GPIO_VALUE_HIGH ||
        gpio_set_value(GPIO3_NUM) != GPIO_VALUE_HIGH) {
        perror("Error setting GPIO values");
        return;
    }
}

// Function to cleanup GPIO pins
void cleanup_io() {
    // Unexport GPIO2 and GPIO3
    if (gpio_unexport(GPIO2_NUM) != 0 ||
        gpio_unexport(GPIO3_NUM) != 0) {
        perror("Error unexporting GPIO pins");
    }

    // Set GPIO2 and GPIO3 to input (default state)
    if (gpio_direction_input(GPIO2_NUM) != 0 ||
        gpio_direction_input(GPIO3_NUM) != 0) {
        perror("Error setting GPIO direction");
    }
}

// Function to read from ADS1115
int read_ads1115(uint8_t command) {
    uint8_t buffer[2];
    int bytes_read;

    // Write command to ADS1115
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Error writing to ADS1115");
        return -1;
    }

    // Read response
    bytes_read = read(i2c_fd, buffer, 2);
    if (bytes_read != 2) {
        perror("Error reading from ADS1115");
        return -1;
    }

    return bytes_read;
}

// Function to handle SIGINT (Ctrl+C)
void handle_signal(int signum) {
    // Graceful shutdown
    printf("Received SIGINT, shutting down...\n");
    close(i2c_fd);
    cleanup_io();
    exit(EXIT_SUCCESS);
}

