// Function to setup SPI and GPIO
void setup_spi_and_gpios() {
    // Open SPI device
    int spi_fd = open(MCP3208_SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI device
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &MCP3208_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set clock frequency
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3208_CLOCK_FREQ_MHZ) < 0) {
        perror("Failed to set SPI clock frequency");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set data size to 8 bits
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &MCP3208_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins for CE, SCLK, MOSI, MISO
    gpiod_set_data_direction(GPIO8, GPIO_OUT);
    gpiod_set_value(GPIO8, 1); // CE high

    gpiod_set_data_direction(GPIO11, GPIO_OUT);
    gpiod_set_value(GPIO11, 1); // SCLK high

    gpiod_set_data_direction(GPIO10, GPIO_OUT);
    gpiod_set_value(GPIO10, 1); // MOSI high

    gpiod_set_data_direction(GPIO9, GPIO_IN);
    gpiod_set_pull_mode(GPIO9, GPIOD_PULLUP); // MISO

    // Open GPIO files
    int gpio_sclk_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_sclk_fd == -1) {
        perror("Failed to open GPIO chip 4");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int gpio_mosi_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_mosi_fd == -1) {
        perror("Failed to open GPIO chip 4");
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int gpio_miso_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_miso_fd == -1) {
        perror("Failed to open GPIO chip 4");
        close(gpio_mosi_fd);
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins
    if (gpio_request(GPIO11, "SCLK") < 0) {
        perror("Failed to request GPIO 11");
        close(gpio_miso_fd);
        close(gpio_mosi_fd);
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set_value(GPIO11, 1);

    if (gpio_request(GPIO10, "MOSI") < 0) {
        perror("Failed to request GPIO 10");
        gpio_release(GPIO11);
        close(gpio_miso_fd);
        close(gpio_mosi_fd);
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set_value(GPIO10, 1);

    if (gpio_request(GPIO9, "MISO") < 0) {
        perror("Failed to request GPIO 9");
        gpio_release(GPIO10);
        gpio_release(GPIO11);
        close(gpio_miso_fd);
        close(gpio_mosi_fd);
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set_value(GPIO9, 0); // MISO input

    if (gpio_request(GPIO8, "CE") < 0) {
        perror("Failed to request GPIO 8");
        gpio_release(GPIO9);
        gpio_release(GPIO10);
        gpio_release(GPIO11);
        close(gpio_miso_fd);
        close(gpio_mosi_fd);
        close(gpio_sclk_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set_value(GPIO8, 1); // CE high

    // Keep GPIOs until program ends
    gpio_set_debounce_time(GPIO11, 0);
    gpio_set_debounce_time(GPIO10, 0);
    gpio_set_debounce_time(GPIO9, 0);
    gpio_set_debounce_time(GPIO8, 0);
}

// Function to cleanup SPI and GPIO resources
void cleanup() {
    // Close SPI device
    close(spi_fd);

    // Release GPIOs
    gpio_release(GPIO11);
    gpio_release(GPIO10);
    gpio_release(GPIO9);
    gpio_release(GPIO8);

    // Close GPIO file descriptors
    close(gpio_miso_fd);
    close(gpio_mosi_fd);
    close(gpio_sclk_fd);
}

// Function to read temperature from MCP3208
void read_temperature() {
    // Set CE low to start conversion
    gpio_set_value(GPIO8, 0);
    usleep(5); // Wait for conversion to start

    // Read conversion result
    uint16_t raw_adc_value = mcp3208_read();

    // Check if conversion was successful
    if (raw_adc_value == 0) {
        printf("Conversion failed\n");
        return;
    }

    // Convert raw ADC value to temperature
    float temperature_celsius = adc_to_temp(raw_adc_value);

    // Check if temperature is within valid range
    if (temperature_celsius < -40.0 || temperature_celsius > 125.0) {
        printf("Temperature out of range (-40°C to 125°C)\n");
        return;
    }

    // Write temperature to log file
    write_to_log_file(time(nullptr), temperature_celsius);
}

// Function to convert ADC value to temperature in Celsius
float adc_to_temp(uint16_t adc_value) {
    return (adc_value - TMP36_OFFSET) * TMP36_SLOPE / 1024.0;
}

// Function to write to the temperature log file
