    FILE *log_file = fopen(TEMP_LOG_FILE_PATH, "a+");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.1f\n", timestamp, temperature_celsius);
    fclose(log_file);
}

