#define SI1172_ADDR 0x4C

// Si1172 registers offsets
#define REG_IR_RAW_ADDR 0x00
#define REG_RED_RAW_ADDR 0x01

// Proxy values for HR and SpO₂ (IR and RED ADC values)
#define HR_PROXY IR_RAW
#define SP02_PROXY RED_RAW

// Error flags
#define ERROR_FLAGAbsentUninit 2
#define ERROR_FLAGReadError 1

