void init_si1172();
void read_si1172(uint16_t *ir_raw, uint16_t *red_raw);
void handle_interrupt(int signum);
void cleanup();

int main() {
    // Initialize Si1172 sensor
    init_si1172();

    // File for logging data
    const char *log_file = "biometric_log.csv";
    FILE *log_file_handle = fopen(log_file, "a+");
    if (log_file_handle == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Variables to hold sensor data
    uint16_t ir_raw, red_raw;
    int error_flag = 0;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_si1172(&ir_raw, &red_raw) == 0) {
            // No error, log the data
            time_t now = time(NULL);
            struct tm timeinfo;
            localtime_r(&now, &timeinfo);

            // Format the timestamp
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            // Write to log file
            fprintf(log_file_handle, "%s,%d,%d,%d\n", timestamp, ir_raw, red_raw, error_flag);

            // Flush the log file buffer
            fflush(log_file_handle);
        } else {
            // Error occurred, log the error flag
            error_flag = (read_si1172 == GPIOD_ERROR_TIMEOUT) ? ERROR_FLAGAbsentUninit : ERROR_FLAGReadError;
            fprintf(log_file_handle, "%s,%d,%d,%d\n", "ERROR", 0, 0, error_flag);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on SIGINT (Ctrl+C)
    signal(SIGINT, handle_interrupt);

    // Graceful shutdown
    cleanup();

    return 0;
}

// Function to initialize the Si1172 sensor
void init_si1172() {
    // Open I2C bus
    int i2c_fd = gpiod_i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open the Si1172 device
    int si1172_fd = gpiod_i2c_open_device(i2c_fd, SI1172_ADDR);
    if (si1172_fd < 0) {
        perror("Failed to open Si1172 device");
        gpiod_i2c_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize the sensor
    uint8_t init_cmd[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (gpiod_i2c_transfer(i2c_fd, si1172_fd, 1, init_cmd, 7) != 7) {
        perror("Failed to initialize Si1172");
        gpiod_i2c_close(si1172_fd);
        gpiod_i2c_close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read raw IR and RED values from Si1172
void read_si1172(uint16_t *ir_raw, uint16_t *red_raw) {
    uint8_t read_cmd[] = {0x03, 0x00, 0x00}; // Read IR and RED raw values

    // Transfer command to read data
    if (gpiod_i2c_transfer(i2c_fd, si1172_fd, 1, read_cmd, 3, NULL, 0) != 3) {
        return GPIOD_ERROR_TIMEOUT;
    }

    // Read the raw data
    *ir_raw = gpiod_i2c_read(i2c_fd, si1172_fd, REG_IR_RAW_ADDR, 2);
    *red_raw = gpiod_i2c_read(i2c_fd, si1172_fd, REG_RED_RAW_ADDR, 2);

    return 0;
}

