#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define MCP3008_ADDR 0x7E

#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define FLOW_THRESHOLD 0.0

#define LOG_FILE_PATH "flow_log.csv"
#define TIMESTAMP_PRECISION 6

void spi_setup(struct spi_device *spi, int speed, int mode, int channel) {
    struct spi_ioc_transfer xfer[2];

    xfer[0].tx_buf = (unsigned long)&(MCP3008_ADDR);
    xfer[0].len = sizeof(MCP3008_ADDR);
    xfer[0].delay_usecs = 0;
    xfer[0].speed_hz = speed;
    xfer[0].cs_change = 1;
    xfer[0].cs_low = 1;
    xfer[0].mode = mode;

    xfer[1].tx_buf = (unsigned long)&(0x00); // dummy transfer
    xfer[1].len = 1;
    xfer[1].delay_usecs = 0;
    xfer[1].speed_hz = speed;
    xfer[1].cs_change = 1;
    xfer[1].cs_low = 0;
    xfer[1].mode = mode;

    if (spi_write(spi, xfer, 2) < 0) {
        fprintf(stderr, "Error setting up SPI device\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int fd;
    struct spi_device *spi;
    uint16_t adc_value;
    char timestamp[17];
    float flow_rate;
    ssize_t bytes_written;

    // Initialize GPIO library
    if (gpiod_get_device(NULL) < 0) {
        fprintf(stderr, "Error initializing GPIO library\n");
        return EXIT_FAILURE;
    }

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening SPI device\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    spi = spi_device_new_fd(fd);
    if (!spi) {
        fprintf(stderr, "Error initializing SPI device\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up SPI parameters
    spi_setup(spi, SPI_SPEED, SPI_MODE, SPI_CHANNEL);

    // Initialize log file
    if ((fd = fopen(LOG_FILE_PATH, "a")) == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE_PATH);
        close(fd);
        spi_device_free(spi);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = spi_transfer(spi, MCP3008_ADDR, 0x00, 0x00, 0); // Read channel 0

        // Convert ADC value to flow rate
        flow_rate = (adc_value * FLOW_MAX) / 1024.0;

        // Check for valid flow rate and sensor presence
        if (flow_rate < FLOW_THRESHOLD || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
        } else if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent: ADC value is 0 or 1023\n");
        } else {
            // Format timestamp and flow rate
            time_t rawtime;
            struct tm *timeinfo;
            char buffer[23];

            rawtime = time(NULL);
            timeinfo = localtime(&rawtime);

            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S.%06u", timeinfo);
            strcat(buffer, ",flow_rate=");
            sprintf(buffer + strlen(buffer), "%f", flow_rate);

            // Write to log file
            if ((bytes_written = fwrite(buffer, 1, sizeof(buffer), fd)) != sizeof(buffer)) {
                fprintf(stderr, "Error writing to log file: %zd\n", bytes_written);
                break; // Exit on fatal error
            }

            // Flush log file
            fflush(fd);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on exit
    fclose(fd);
    spi_device_free(spi);

    return EXIT_SUCCESS;
}

// SPI transfer function
int spi_transfer(struct spi_device *spi, uint8_t cmd, uint8_t cs_change, uint8_t cs_low, uint16_t data_out, uint16_t data_in) {
    struct spi_ioc_transfer xfer[2];

    xfer[0].tx_buf = (unsigned long)&(cmd);
    xfer[0].len = sizeof(cmd);
    xfer[0].delay_usecs = 0;
    xfer[0].speed_hz = SPI_SPEED;
    xfer[0].cs_change = cs_change;
    xfer[0].cs_low = cs_low;
    xfer[0].mode = SPI_MODE;

    xfer[1].rx_buf = (unsigned long)&(data_in);
    xfer[1].len = sizeof(data_in);
    xfer[1].delay_usecs = 0;
    xfer[1].speed_hz = SPI_SPEED;
    xfer[1].cs_change = cs_change;
    xfer[1].cs_low = !cs_low;
    xfer[1].mode = SPI_MODE;

    return spi_write(spi, xfer, 2);
}

