#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <stdbool.h>
#include <inttypes.h>

#define I2C_BUS_NUM 1
#define SENSOR_ADDR 0x5C
#define COMMAND_REG 0x00
#define DATA_REG 0x01
#define CRC_REG 0x02

#define FILE_NAME "environmental_data.csv"
#define SAMPLE_INTERVAL_MS 5000

// Calibration coefficients from TDK ICP-10125 datasheet
#define PRESSURE_COEFFICIENT 0.000048
#define TEMPERATURE_COEFFICIENT 0.000121

// Sensor data structure
typedef struct {
    uint16_t pressure_MSB;
    uint16_t pressure_LSB;
    uint16_t temperature_MSB;
    uint16_t temperature_LSB;
    uint16_t crc;
} SensorData;

// Function prototypes
void openI2CDevice();
void sendCommandAndReadData(SensorData *data);
void convertSensorData(SensorData *data);
void writeToCSV(const char *message);
void handleInterruptSignals(int signum);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize variables
    SensorData data;
    int i2c_fd = -1;
    int csv_file_fd = -1;
    bool running = true;

    // Signal handlers
    struct sigaction intHandler, termHandler;
    sigaction(SIGINT, &intHandler, NULL);
    sigaction(SIGTERM, &termHandler, NULL);

    // Main loop
    while (running) {
        // Open I2C device
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
            sleep(5000); // Retry after 5 seconds
        }

        // Send command and read data
        if (sendCommandAndReadData(&data) < 0) {
            fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
            sleep(5000); // Retry after 5 seconds
        }

        // Convert sensor data
        convertSensorData(&data);

        // Write to CSV file
        writeToCSV("timestamp,%d,%d,%d,%d,%d", data.temperature_MSB, data.temperature_LSB, data.pressure_MSB, data.pressure_LSB, data.crc);

        // Display data
        printf("Temperature: %.2f°C\nPressure: %.2f Pa\n", data.temperature, data.pressure);

        // Sleep for 5 seconds
        sleep(SAMPLE_INTERVAL_MS);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to open I2C device
void openI2CDevice() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return;
    }

    // Check if device is present
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Error accessing I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        return;
    }
}

// Function to send command and read data
int sendCommandAndReadData(SensorData *data) {
    // Write command to set high-precision measurement
    if (write(i2c_fd, &COMMAND_REG, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion
    usleep(100); // Approximate delay for conversion

    // Read data
    if (read(i2c_fd, data, sizeof(SensorData)) != sizeof(SensorData)) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to convert sensor data
void convertSensorData(SensorData *data) {
    // Convert pressure and temperature from ADC to physical units
    data->pressure = ((data->pressure_MSB << 8) | data->pressure_LSB) * PRESSURE_COEFFICIENT;
    data->temperature = ((data->temperature_MSB << 8) | data->temperature_LSB) * TEMPERATURE_COEFFICIENT;
}

// Function to write to CSV file
void writeToCSV(const char *message) {
    char buffer[256];
    sprintf(buffer, "%s\n", message);
    if (csv_file_fd < 0) {
        csv_file_fd = open(FILE_NAME, "a+");
    }
    if (fwrite(buffer, 1, strlen(buffer), csv_file_fd) != strlen(buffer)) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
    }
}

// Signal handlers
void handleInterruptSignals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = false;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file_fd >= 0) {
        fclose(csv_file_fd);
        remove(FILE_NAME); // Optionally remove the CSV file
    }
}

