#include <linux/iio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MOISTURE_LOG_FILE "moisture_log.txt"

// Function prototypes
void initialize_gpiod();
void initialize_spi();
void read_adc_value(uint8_t channel);
void handle_spi_error(const char *operation);
void handle_file_io_error(const char *operation);
void cleanup_resources();
void main_loop();

int main() {
    // Initialize gpiod and SPI
    initialize_gpiod();
    initialize_spi();

    // Main infinite loop
    while (1) {
        main_loop();
        usleep(6000000); // Sleep for 60 seconds
    }

    // Clean up resources on exit
    cleanup_resources();

    return 0;
}

// Function to initialize gpiod
void initialize_gpiod() {
    int ret;

    // Initialize gpiod
    ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Check if GPIO 0 (CE0) is available
    struct gpio_desc *ce0_desc;
    ret = gpiod_get_desc_by_number(0, &ce0_desc);
    if (ret != 0) {
        fprintf(stderr, "Failed to get GPIO 0: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set GPIO 0 as output
    ret = gpiod_direction_output(ce0_desc, 1);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO 0 as output: %s\n", gpiod_errstr(ret));
        gpiod_free_desc(&ce0_desc);
        exit(EXIT_FAILURE);
    }
}

// Function to initialize SPI
void initialize_spi() {
    int spi_fd;
    struct spi_device *spi_dev;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Get SPI device structure
    ret = spi_open(spi_fd, SPI_DEVICE, &spi_dev);
    if (ret != 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spi_errstr(ret));
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI mode (mode 0: CPOL=0, CPHA=0)
    ret = spi_set_mode(spi_dev, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", spi_errstr(ret));
        spi_close(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set chip select pin (CE0)
    ret = spi_set_cs(spi_dev, ce0_desc, 1);
    if (ret != 0) {
        fprintf(stderr, "Failed to set CS pin: %s\n", spi_errstr(ret));
        spi_close(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read ADC value from MCP3008
void read_adc_value(uint8_t channel) {
    uint16_t value;
    int ret;

    // Prepare SPI message
    uint8_t message[3] = {0x01, (channel & 0x07), 0x00};

    // Write to MCP3008
    ret = write(spi_fd, message, 3);
    if (ret != 3) {
        handle_spi_error("write");
        return;
    }

    // Read from MCP3008
    ret = read(spi_fd, &value, 2);
    if (ret != 2) {
        handle_spi_error("read");
        return;
    }

    // Ensure valid ADC value
    if (value > 1023 || value < 0) {
        fprintf(stderr, "Invalid ADC value: %d\n", value);
        return;
    }

    // Convert 10-bit value to integer
    int adc_value = value / 1024;

    // Print the value
    printf("ADC value: %d\n", adc_value);
}

// Handle SPI transfer errors
void handle_spi_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, spi_errstr(spi_errno()));
    // Clean up resources
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Handle file I/O errors
void handle_file_io_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, strerror(errno));
    // Clean up resources
    cleanup_resources();
    exit(EXIT_FAILURE);
}

// Function to clean up resources
void cleanup_resources() {
    // Close SPI device
    spi_close(spi_dev);
    close(spi_fd);

    // Release GPIO descriptor
    gpiod_free_desc(&ce0_desc);
}

// Main loop function
void main_loop() {
    struct timespec ts;
    time_t rawtime;
    uint16_t adc_value;

    // Get current time
    time(&rawtime);
    ts.tv_sec = rawtime;
    ts.tv_nsec = 0;

    // Open moisture_log_file for appending
    int log_fd = open(MOISTURE_LOG_FILE, O_APPEND | O_WRONLY | O_CREAT, 0644);
    if (log_fd == -1) {
        handle_file_io_error("open");
        return;
    }

    // Write timestamp and ADC value to the log file
    char timestamp[23];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", &ts);
    fprintf(log_fd, "%s,%d\n", timestamp, adc_value);

    // Close log file after writing
    close(log_fd);

    // Sleep for 60 seconds
    usleep(6000000);
}

