            .len = 1,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 0
        },
        // Wait for conversion to complete
        {
            .tx_buf = (unsigned char *)&(0x00), // No data to send
            .rx_buf = (unsigned char *)&(0),    // Receive the 10-bit result
            .len = 1,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 8,
            .cs_change = 1,
            .delay_usecs = 10000 // Wait for 10ms
        }
    };

    ret = gpiod_spi_transfer(spi_fd, transfers, 2);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", gpiod_spi_error(spi_fd));
        return ret;
    }

    // Convert the 10-bit ADC value to a percentage
    return (gpiod_spi_rx_buf(spi_fd)[0] << 8) | gpiod_spi_rx_buf(spi_fd)[1] / 1024.0 * 100.0;
}

