void write_json_entry(char *timestamp, double water_level) {
    FILE *fp = fopen("water_levels.json", "a+");
    if (!fp) {
        fprintf(stderr, "Failed to open water_levels.json for writing: %s\n", strerror(errno));
        return;
    }

    // Write JSON object
    fprintf(fp, "[{\"timestamp\":\"%s\", \"water_level\":%.1f}]\\n", timestamp, water_level);
    fclose(fp);
}

// Signal handler to clean up on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Stop main loop
    exit(0);
}

// Function to clean up resources
void cleanup_resources(void) {
    if (json_file) {
        fclose(json_file);
        json_file = NULL;
    }

    if (spi_fd > 0) {
        gpiod_spi_close(spi_fd);
        spi_fd = -1;
    }

    // Close GPIO file descriptors
    gpiod_close(GPIO_MISO);
    gpiod_close(GPIO_MOSI);
    gpiod_close(GPIO_SCLK);
    gpiod_close(GPIO_CE0);
}

// Calculate the water level percentage from the 10-bit ADC value
double calculate_water_level_percentage() {
    // Assuming the full-scale voltage is 3.3V for MCP3008
    return (gpiod_spi_rx_buf(spi_fd)[0] << 8) | gpiod_spi_rx_buf(spi_fd)[1] / 1024.0 * 3300.0; // Convert to volts
}

