void spi_setup() {
    int spi_fd;
    struct spi_device *spi_dev;

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("open SPI device failed");
        return;
    }

    // Request SPI device
    if ((spi_dev = gpiod_request_device(spi_fd, GPIOD_SPIDEV)) == NULL) {
        perror("gpiod_request_device failed");
        close(spi_fd);
        return;
    }

    // Set SPI mode
    if (ioctl(spi_fd, GPIOD_IOCTL_SETMODE, GPIOD_MODE_0) < 0) {
        perror("GPIOD_IOCTL_SETMODE failed");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        return;
    }

    // Set CE pin as output
    if (gpiod_direction_output(gpiod_get_device_by_pin(CE_PIN), 1) < 0) {
        perror("gpiod_direction_output for CE pin failed");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        return;
    }

    // Set SCLK, MOSI, MISO pins as outputs
    for (int pin : {SCLK_PIN, MOSI_PIN, MISO_PIN}) {
        if (gpiod_direction_output(gpiod_get_device_by_pin(pin), 1) < 0) {
            perror("gpiod_direction_output for SPI pins failed");
            gpiod_release_device(spi_dev);
            close(spi_fd);
            return;
        }
    }

    gpiod_release_device(spi_dev);
}

