        perror("SPI transfer failed");
        return -1;
    }

    bytes_written = read(spi_fd, tx_buffer, sizeof(tx_buffer));
    if (bytes_written != sizeof(tx_buffer)) {
        perror("SPI transfer failed");
        return -1;
    }

    return tx_buffer[0]; // Return the received data
}

