int main(int argc, char **argv) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s <SPI_channel> <ADC_channel> <min_calib> <max_calib> <moisture_threshold> <interval> <msmtp_config>\n", argv[0]);
        return 1;
    }

    // Extract command-line arguments
    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_calib = atoi(argv[3]);
    int max_calib = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int log_interval_secs = atoi(argv[6]);
    char *msmtp_config_path = argv[7];

    // Initialize GPIO and SPI
    spi_setup();
    adc_init();

    // Main loop
    while (1) {
        struct timeval now;
        struct tm *timeinfo;
        int moisture_percent;
        int moisture_read;

        gettimeofday(&now, NULL);
        timeinfo = localtime(&now.tv_sec);

        // Read moisture level
        moisture_read = adc_read(adc_channel, &moisture_percent);

        // Check for error and retry
        if (moisture_read == -1) {
            fprintf(stderr, "Error reading moisture sensor: %s\n", strerror(errno));
            continue;
        }

        // Log moisture level if within calibration range and below threshold
        if (moisture_percent >= min_calib && moisture_percent <= max_calib && moisture_percent < moisture_threshold) {
            char log_entry[256];
            strftime(log_entry, sizeof(log_entry), "%F %T, ", timeinfo);
            sprintf(log_entry + strlen("%F %T, "), "%.1f", moisture_percent);
            FILE *file = fopen("plant_data.txt", "a");
            if (file == NULL) {
                perror("Failed to open plant_data.txt for append");
                continue;
            }
            fprintf(file, "%s\n", log_entry);
            fclose(file);

            // Send email alert
            email_alert("Moisture level below threshold: " "%" "f", moisture_percent);
            fclose(msmtp_config_path);

            // Check msmtp exit status
            int msmtp_status = system("msmtp -a " MSMTCP_CONFIG_PATH " -t " EMAIL_TO " < /dev/null");
            if (msmtp_status != 0) {
                fprintf(stderr, "msmtp failed with status %d: %s\n", msmtp_status, strerror(msmtp_status));
            }
        }

        // Sleep for the specified interval
        usleep(log_interval_secs * 1000 * 1000);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Final cleanup
    cleanup();

    return 0;
}

// SPI setup function
void spi_setup() {
    int spi_fd;
    struct spi_device *spi_device;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return;
    }

    // Configure SPI device
    spi_device = gpiod_spi_open(spi_fd, SPI_CHANNEL, 500000, GPIOD_SPI_MODE_0);
    if (!spi_device) {
        fprintf(stderr, "Failed to configure SPI device: %s\n", gpiod_error_string());
        close(spi_fd);
        return;
    }

    gpiod_set_data_direction(spi_device, GPIOD_DATA_direction_INOUT);
    gpiod_spi_set_cs(spi_device, MCP3008_CS_GPIO);
}

// ADC initialization function
void adc_init() {
    int adc_fd;
    struct spi_ioc_transfer transfers[2];

    // Open ADC device
    adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd == -1) {
        perror("Failed to open ADC device");
        return;
    }

    // Prepare SPI transfer for MCP3008 command
    transfers[0].tx_buf = (unsigned char[]) {0x01, 0x08}; // Start conversion, single-ended mode
    transfers[0].rx_buf = NULL;
    transfers[0].len = 2;
    transfers[0].delay_usecs = 0;

    // Prepare SPI transfer for reading data
    transfers[1].tx_buf = NULL;
    transfers[1].rx_buf = (unsigned char *)(&adc_channel); // Channel to read
    transfers[1].len = 1;
    transfers[1].delay_usecs = 0;

    // Send command to start conversion
    if (gpiod_spi_transfer(adc_fd, transfers, 2) < 0) {
        fprintf(stderr, "Error sending command to MCP3008: %s\n", gpiod_error_string());
        close(adc_fd);
        return;
    }

    // Wait for conversion to complete
    usleep(100); // Small delay to ensure conversion is complete

    // Read ADC value
    if (gpiod_spi_transfer(adc_fd, transfers, 1) < 0) {
        fprintf(stderr, "Error reading from MCP3008: %s\n", gpiod_error_string());
        close(adc_fd);
        return;
    }

    // Close ADC device
    close(adc_fd);
}

