bool adc_read(uint16_t channel, int16_t *value) {
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd == -1) {
        perror("Failed to open ADC device");
        return false;
    }

    struct spi_ioc_transfer transfers[2];

    // Prepare SPI transfer for reading data
    transfers[0].tx_buf = NULL;
    transfers[0].rx_buf = (unsigned char *)(&channel); // Channel to read
    transfers[0].len = 1;
    transfers[0].delay_usecs = 0;

    // Prepare SPI transfer for reading data
    transfers[1].tx_buf = NULL;
    transfers[1].rx_buf = (unsigned char *)value; // Buffer to store value
    transfers[1].len = 1;
    transfers[1].delay_usecs = 0;

    // Send command to start conversion
    if (gpiod_spi_transfer(adc_fd, transfers, 2) < 0) {
        fprintf(stderr, "Error sending command to MCP3008: %s\n", gpiod_error_string());
        close(adc_fd);
        return false;
    }

    // Wait for conversion to complete
    usleep(100); // Small delay to ensure conversion is complete

    // Read ADC value
    if (gpiod_spi_transfer(adc_fd, transfers, 1) < 0) {
        fprintf(stderr, "Error reading from MCP3008: %s\n", gpiod_error_string());
        close(adc_fd);
        return false;
    }

    // Close ADC device
    close(adc_fd);
