int main(int argc, char **argv) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s <SPI_channel> <ADC_channel> <min_calib> <max_calib> <moisture_threshold> <interval> <msmtp_config>\n", argv[0]);
        return 1;
    }

    // Extract command-line arguments
    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_calib = atoi(argv[3]);
    int max_calib = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int log_interval_secs = atoi(argv[6]);
    char *msmtp_config_path = argv[7];

    // Initialize GPIO and SPI
    spi_setup();
    adc_init();

    // Main loop
    while (1) {
        struct timeval now;
        struct tm *timeinfo;
        int moisture_percent;
        int moisture_read;

        gettimeofday(&now, NULL);
        timeinfo = localtime(&now.tv_sec);

        // Read moisture level
        moisture_read = adc_read(adc_channel, &moisture_percent);

        // Check for error and retry
        if (moisture_read == -1) {
            fprintf(stderr, "Error reading moisture sensor: %s\n", strerror(errno));
            continue;
        }

        // Log moisture level if within calibration range and below threshold
        if (moisture_percent >= min_calib && moisture_percent <= max_calib && moisture_percent < moisture_threshold) {
            char log_entry[256];
            strftime(log_entry, sizeof(log_entry), "%F %T, ", timeinfo);
            sprintf(log_entry + strlen("%F %T, "), "%.1f", moisture_percent);
            FILE *file = fopen("plant_data.txt", "a");
            if (file == NULL) {
                perror("Failed to open plant_data.txt for append");
                continue;
            }
            fprintf(file, "%s\n", log_entry);
            fclose(file);

            // Send email alert
            email_alert("Moisture level below threshold: " "%" "f", moisture_percent);
            fclose(msmtp_config_path);

            // Check msmtp exit status
            int msmtp_status = system("msmtp -a " MSMTCP_CONFIG_PATH " -t " EMAIL_TO " < /dev/null");
            if (msmtp_status != 0) {
                fprintf(stderr, "msmtp failed with status %d: %s\n", msmtp_status, strerror(msmtp_status));
            }
        }

        // Sleep for the specified interval
        usleep(log_interval_secs * 1000 * 1000);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Final cleanup
    cleanup();

    return 0;
}

