    // Configure SPI device
    spi_device = gpiod_spi_open(spi_fd, SPI_CHANNEL, 500000, GPIOD_SPI_MODE_0);
    if (!spi_device) {
        fprintf(stderr, "Failed to configure SPI device: %s\n", gpiod_error_string());
        close(spi_fd);
        return;
    }

    gpiod_set_data_direction(spi_device, GPIOD_DATA_direction_INOUT);
