#define MCP3008_DEVICE "/dev/spidev0.0"
#define GPIO8 27 // BCM
#define GPIO10 19 // BCM
#define GPIO9 21 // BCM
#define GPIO11 23 // BCM

#define SPI_CLOCK_FREQ 1000000 // 1 MHz clock
#define SPI_MODE 0 // Mode 0 (CPOL=0, CPHA=0)
#define SPI_CHANNEL 0 // Channel 0

// MCP3008 control register bits
#define ADSC 0x01
#define ADSC_RESET 0x02

// MCP3008 data register bit mask
#define ADCH0 (1 << 0)

// Function prototypes
int spi_open_mcp3008();
int spi_write_mcp3008(uint8_t command, uint8_t data);
int spi_read_mcp3008(uint8_t command);

// MCP3008 configuration and read function
int mcp3008_read(uint8_t channel) {
    int ret;
    // Open SPI device
    int spi_fd = spi_open_mcp3008();
    if (spi_fd == -1) {
        perror("spi_open_mcp3008");
        return -1;
    }

    // Set SPI clock frequency
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_FREQ);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(spi_fd);
        return -1;
    }

    // Set SPI mode and polarity
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(spi_fd);
        return -1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_SPOL, &0); // CPOL=0
    if (ret < 0) {
        perror("ioctl(SPI_IOC_WR_SPOL)");
        close(spi_fd);
        return -1;
    }

    // Set CE0 high (active low)
    ret = gpio_write(GPIO8, 1); // Set GPIO8 high
    if (ret < 0) {
        perror("gpio_write(GPIO8)");
        close(spi_fd);
        return -1;
    }

    // Set CS low to select MCP3008
    ret = gpio_write(GPIO10, 0); // Set GPIO10 low
    if (ret < 0) {
        perror("gpio_write(GPIO10)");
        close(spi_fd);
        return -1;
    }

    // Send ADCH0 command to start conversion
    ret = spi_write_mcp3008(0x01, 0x00); // Start conversion on channel 0
    if (ret < 0) {
        perror("spi_write_mcp3008");
        close(spi_fd);
        return -1;
    }

    // Wait for conversion to complete
    while (gpio_read(GPIO9) & ADSC) { // Wait for ADSC bit to clear
        // No-op
    }

    // Read the 10-bit ADC value
    uint16_t adc_value = 0;
    ret = spi_read_mcp3008(0x03); // Read data register
    if (ret < 0) {
        perror("spi_read_mcp3008");
        close(spi_fd);
        return -1;
    }
    adc_value = (spi_read_mcp3008(0x00) << 8) | spi_read_mcp3008(0x00); // Read twice for 10-bit value

    // Calculate moisture percentage (assuming a linear relationship)
    int moisture_percentage = (adc_value * 100) / 1023;

    // Log the raw ADC value and moisture percentage
    printf("Raw ADC value: %hu\nMoisture percentage: %.1f%%\n", adc_value, moisture_percentage);

    // Set CE0 high to deselect MCP3008
    ret = gpio_write(GPIO10, 1); // Set GPIO10 high
    if (ret < 0) {
        perror("gpio_write(GPIO10)");
        close(spi_fd);
        return -1;
    }

    // Close SPI device
    close(spi_fd);

    return adc_value;
}

// SPI device open function
int spi_open_mcp3008() {
    int spi_fd;
    struct spi_device_id ids[] = {
        SPI_DEVICE(MCP3008_DEVICE),
        { .count = 0 }
    };

    spi_fd = open(MCP3008_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("open(MCP3008_DEVICE)");
        return -1;
    }

    // Check if the device was found
    if (ioctl(spi_fd, SPI_IOC_ID, &ids) < 0) {
        perror("SPI_IOC_ID");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

// SPI write function
int spi_write_mcp3008(uint8_t command, uint8_t data) {
    int ret;
    ret = write(spi_fd, &command, 1);
    if (ret != 1) {
        perror("write");
