    transfers[0].tx_buf = &MCP3008_ADDR;
    transfers[0].len = 1;
    transfers[0].speed_hz = SAMPLE_RATE;
    transfers[0].delay_usecs = 80;
    transfers[0].cs_change = 1;
    transfers[0].cs_low = 1;

    transfers[1].tx_buf = &channel;
    transfers[1].len = 1;
    transfers[1].speed_hz = SAMPLE_RATE;
    transfers[1].delay_usecs = 80;
    transfers[1].cs_change = 1;
    transfers[1].cs_low = 0;

