#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>

#define MCP3008_DEVICE "/dev/spidev0.0"
#define SPI_CLOCK_FREQ 1000000
#define SPI_MODE 0
#define NUM_CHANNELS 4

#define GPIO8 27

int main() {
    // Initialize variables
    int fd;
    struct spi_device *spi;
    char buffer[4];
    int ret;
    int channel;
    time_t timestamp;
    FILE *csv_file = NULL;
    char csv_filename[] = "environmental_data.csv";

    // Open SPI device
    fd = open(MCP3008_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Check if GPIO8 is configured as CE0
    if (gpio_request(GPIO8, "CE0") == -1) {
        perror("Failed to request GPIO8");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure GPIO8 as output
    if (gpio_export(GPIO8, GPIOF_DIR_OUT) == -1) {
        perror("Failed to export GPIO8");
        gpio_free(GPIO8);
        close(fd);
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    spi = spidev_open(MCP3008_DEVICE, SPI_CLOCK_FREQ);
    if (spi == NULL) {
        perror("Failed to open SPI device");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set SPI mode
    ret = spidev_set_mode(spi, SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        spidev_close(spi);
        close(fd);
        return EXIT_FAILURE;
    }

    // Loop indefinitely
    while (1) {
        // Read from MCP3008
        for (channel = 0; channel < NUM_CHANNELS; channel++) {
            buffer[0] = (channel << 5) | 0x01; // Single-ended mode, channel 0-3
            ret = write(fd, buffer, sizeof(buffer));
            if (ret != sizeof(buffer)) {
                perror("Failed to write to MCP3008");
                break;
            }

            ret = read(fd, buffer, sizeof(buffer));
            if (ret != sizeof(buffer)) {
                perror("Failed to read from MCP3008");
                break;
            }

            // Convert 10-bit ADC value to voltage
            int adc_value = buffer[0] & 0x1F;
            float voltage = (adc_value * 3.3) / 1024.0; // Assuming 3.3V reference voltage

            // Get current time
            timestamp = time(NULL);

            // Append to CSV file
            if ((csv_file = fopen(csv_filename, "a")) == NULL) {
                perror("Failed to open CSV file for appending");
                break;
            }
            fprintf(csv_file, "%ld,%f\n", timestamp, voltage);
            fclose(csv_file);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Handle SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main cleanup function
    void cleanup(int signum) {
        // Close SPI device
        spidev_close(spi);
        // Release GPIO
        gpio_free(GPIO8);
        // Close SPI device file descriptor
        close(fd);

        // Ensure no resources are leaked
        if (csv_file != NULL) {
            fclose(csv_file);
            csv_file = NULL;
        }
    }

    return EXIT_SUCCESS;
}

// Helper function to handle cleanup on signal
void cleanup(int signum) {
    // Implementation as per the main cleanup function
}

