#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define VH400_CHANNEL 0
#define SPI_SPEED 1000000
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define PUMP_GPIO 17
#define MOSI_GPIO 10
#define SCLK_GPIO 11
#define CE0_GPIO 0

volatile sig_atomic_t should_exit = 0;

struct moisture_reading {
    uint16_t value;
    time_t timestamp;
    int pump_state;
};

static struct moisture_reading buffer[BUFFER_SIZE];

static void pump_control(int value) {
    if (value < LOW_THRESHOLD) {
        gpiod_set_data_direction(PUMP_GPIO, GPIOD_OUT_HIGH);
        gpiod_write(PUMP_GPIO, 1);
    } else {
        gpiod_set_data_direction(PUMP_GPIO, GPIOD_OUT_LOW);
        gpiod_write(PUMP_GPIO, 0);
    }
}

static void spi_transfer(uint8_t mosi_data, uint8_t sclck, uint8_t miso_data) {
    gpiod_set_function(MOSI_GPIO, GPIOD_SPI_MOSI);
    gpiod_set_function(SCLK_GPIO, GPIOD_SPI_SCLK);
    gpiod_set_function(CE0_GPIO, GPIOD_SPI_CE0);

    gpiod_set_speed(SPI_SPEED);

    gpiod_write(MOSI_GPIO, mosi_data);
    gpiod_write(SCLK_GPIO, 1);
    gpiod_write(SCLK_GPIO, 0);

    if (gpiod_read(MISO_GPIO) == miso_data) {
        // SPI transfer successful
    } else {
        // SPI transfer failed
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }

    gpiod_set_function(MOSI_GPIO, GPIOD_IN);
    gpiod_set_function(SCLK_GPIO, GPIOD_NONE);
    gpiod_set_function(CE0_GPIO, GPIOD_NONE);
}

static void read_moisture() {
    spi_transfer(0x01, 0x00, 0); // Start conversion
    usleep(1000); // Wait for conversion to complete

    uint16_t value = 0;
    spi_transfer(0x00, 0x00, value); // Read ADC value

    buffer[buffer_index++] = (struct moisture_reading) {
        .value = value,
        .timestamp = time(NULL),
        .pump_state = (value < LOW_THRESHOLD) ? 1 : 0
    };

    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0; // Circular buffer
    }
}

static void print_buffer() {
    for (int i = 0; i < buffer_index; ++i) {
        printf("Moisture reading: %hu, Timestamp: %s, Pump State: %d\n",
               buffer[i].value, ctime(&buffer[i].timestamp), buffer[i].pump_state);
    }
}

int main(void) {
    struct gpiod_device *pump_device;
    struct gpiod_device *spi_ce0;
    struct gpiod_device *miso_device;
    struct gpiod_device *mosi_device;
    struct gpiod_device *sclk_device;
    int mosi_pin, sclk_pin, ce_pin;
    int spi_ce0_fd;
    int buffer_index = 0;

    // Initialize GPIO
    if ((pump_device = gpiod_get_device(PUMP_GPIO)) == NULL) {
        fprintf(stderr, "Error getting pump GPIO device\n");
        exit(EXIT_FAILURE);
    }

    if ((spi_ce0 = gpiod_get_device(CE0_GPIO)) == NULL) {
        fprintf(stderr, "Error getting SPI CE0 GPIO device\n");
        exit(EXIT_FAILURE);
    }

    if ((mosi_device = gpiod_get_device(MOSI_GPIO)) == NULL) {
        fprintf(stderr, "Error getting MOSI GPIO device\n");
        exit(EXIT_FAILURE);
    }

    if ((sclk_device = gpiod_get_device(SCLK_GPIO)) == NULL) {
        fprintf(stderr, "Error getting SCLK GPIO device\n");
        exit(EXIT_FAILURE);
    }

    if ((ce_pin = gpiod_get_pin_number(CE0_GPIO)) < 0) {
        fprintf(stderr, "Error getting CE0 pin number\n");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI interface
    if ((spi_ce0_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        exit(EXIT_FAILURE);
    }

    gpiod_set_function(ce_pin, GPIOD_OUT_HIGH);
    gpiod_write(ce_pin, 1);

    mosi_pin = gpiod_get_pin_number(MOSI_GPIO);
    sclk_pin = gpiod_get_pin_number(SCLK_GPIO);

    // Configure GPIO pins for SPI
    gpiod_set_function(mosi_pin, GPIOD_SPI_MOSI);
    gpiod_set_function(sclk_pin, GPIOD_SPI_SCLK);

    // Main loop
    while (!should_exit) {
        // Sample moisture every 5 seconds
        sleep(5);
        read_moisture();

        // Print buffer and reset index
        print_buffer();
        buffer_index = 0;

        // Handle SIGINT or SIGTERM
        if (should_exit) {
            break;
        }
    }

    // Clean up
    gpiod_set_function(mosi_pin, GPIOD_IN);
    gpiod_set_function(sclk_pin, GPIOD_NONE);
    gpiod_set_function(ce_pin, GPIOD_NONE);

    close(spi_ce0_fd);

    // Ensure pump is off
    pump_control(0);

    return 0;
}

