        buffer_index = 0;

        // Handle SIGINT or SIGTERM
        if (should_exit) {
            break;
        }
    }

    // Clean up
    gpiod_set_function(mosi_pin, GPIOD_IN);
    gpiod_set_function(sclk_pin, GPIOD_NONE);
    gpiod_set_function(ce_pin, GPIOD_NONE);

    close(spi_ce0_fd);

    // Ensure pump is off
    pump_control(0);

    return 0;
}
