#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MCP3008_ADDR 0x68
#define SPI0_BASE 0
#define CE0_GPIO_NUM 18

// MCP3008 configuration
#define MCP3008_MODE 0x00 // SPI mode 0
#define MCP3008_BITS 8    // 8-bit resolution

// GPIO setup for CE0
#define CE0_GPIO_ID GPIOD_ID_18
#define CE0_PIN      GPIOD_PIN_18

// SPI configuration
#define SPI_CLOCK_FREQ_HZ 1000000

// CSV file handling
#define CSV_FILE_NAME "analog_log.csv"
#define CSV_HEADER "Timestamp,Channel,Voltage"

// Function prototypes
void setup_spi();
void read_mcp3008(uint8_t channel);
void handle_spi_error(int error);
void cleanup();
void write_to_csv(const char *line);
void signal_handler(int signum);

int main() {
    struct gpiod_dir gpio_ce;
    struct gpiod_cdev *ce0_device;
    int spi_fd;
    uint8_t channel;
    int ret;
    time_t timestamp;
    char csv_line[256];

    // Initialize GPIO for CE0
    if (gpiod_get_data_dir(CE0_GPIO_ID, &gpio_ce) < 0) {
        fprintf(stderr, "Error getting GPIO direction for CE0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (gpiod_set_direction(CE0_GPIO_ID, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error setting CE0 GPIO direction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup SPI
    setup_spi();

    // Main loop
    while (1) {
        timestamp = time(NULL);
        channel = 0; // Start with channel 0

        // Write CE0 high to select MCP3008
        gpiod_set_value(CE0_GPIO_ID, 1);

        // Read voltage from MCP3008
        ret = read_mcp3008(channel);
        if (ret < 0) {
            handle_spi_error(ret);
            continue;
        }

        // Format CSV line
        snprintf(csv_line, sizeof(csv_line), "%s,%u,%u", ctime(&timestamp).ctime(), channel, ret / 3.3);

        // Write to CSV file
        write_to_csv(csv_line);

        // Delay before next reading
        usleep(500 * 1000); // 500 ms delay

        // Increment channel for next reading
        channel++;
        if (channel == 3) {
            channel = 0; // Wrap around to channel 0
        }
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup SPI
void setup_spi() {
    struct spi_ioc_transfer xfer[2];
    xfer[0].tx_buf = (unsigned long)&MCP3008_ADDR;
    xfer[0].len = sizeof(MCP3008_ADDR);
    xfer[0].speed_hz = SPI_CLOCK_FREQ_HZ;
    xfer[0].bits_per_word = MCP3008_BITS;
    xfer[0].cs_change = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = NULL; // No data to send
    xfer[1].len = 0;
    xfer[1].speed_hz = SPI_CLOCK_FREQ_HZ;
    xfer[1].bits_per_word = MCP3008_BITS;
    xfer[1].cs_change = 1;
    xfer[1].delay_usecs = 0;

    // Transfer configuration to MCP3008
    ret = spi_write(spi_fd, xfer, 2);
    if (ret < 0) {
        fprintf(stderr, "Error writing to MCP3008: %s\n", strerror(errno));
        return;
    }
}

// Function to read voltage from MCP3008
int read_mcp3008(uint8_t channel) {
    struct spi_ioc_transfer xfer[2];
    xfer[0].tx_buf = (unsigned long)&(MCP3008_ADDR | (channel << 5));
    xfer[0].len = MCP3008_BITS;
    xfer[0].speed_hz = SPI_CLOCK_FREQ_HZ;
    xfer[0].bits_per_word = MCP3008_BITS;
    xfer[0].cs_change = 1;
    xfer[0].delay_usecs = 0;

    xfer[1].tx_buf = NULL;
    xfer[1].len = 0;
    xfer[1].speed_hz = SPI_CLOCK_FREQ_HZ;
    xfer[1].bits_per_word = MCP3008_BITS;
    xfer[1].cs_change = 0; // CS is not changed
    xfer[1].delay_usecs = 100; // Small delay

    ret = spi_write(spi_fd, xfer, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading from MCP3008: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw value to voltage
    return (ret / 3.3) * 3.3; // Assuming 3.3V reference voltage
}

// Handle SPI communication errors
void handle_spi_error(int error) {
    fprintf(stderr, "SPI error: %s\n", strerror(error));
}

// Cleanup function
void cleanup() {
    // Close SPI device
    close(spi_fd);

    // Release GPIO
    gpiod_set_value(CE0_GPIO_ID, 0); // Set CE0 low

    // Release GPIO device
    gpiod_release(CE0_GPIO_ID);
}

// Function to write to CSV file
void write_to_csv(const char *line) {
    FILE *csv_file = fopen(CSV_FILE_NAME, "a+");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file for appending: %s\n", strerror(errno));
        return;
    }

    // Write line to CSV file
    if (fputs(line, csv_file) == EOF) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        fclose(csv_file);
        return;
    }

    // Close CSV file
    fclose(csv_file);
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    // Clean up on SIGINT
    cleanup();
    exit(EXIT_FAILURE);
}

