#define MCP3008_CS0_GPIO 8
#define MCP3008_CS1_GPIO 7
#define MCP3008_CS2_GPIO 25
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11

#define MCP3008_ADDR 0
#define SPI_SPEED 1000000

int main() {
    // GPIO setup for chip select lines
    int cs0_fd = gpiod_open(MCP3008_CS0_GPIO, GPIOD_OUT_INIT_LOW);
    int cs1_fd = gpiod_open(MCP3008_CS1_GPIO, GPIOD_OUT_INIT_LOW);
    int cs2_fd = gpiod_open(MCP3008_CS2_GPIO, GPIOD_OUT_INIT_LOW);

    // SPI setup
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Ensure SPI operates at 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set CS lines to output
    if (gpiod_set_data_direction(cs0_fd, GPIOD_DIR_OUT); cs0_fd < 0 ||
        gpiod_set_data_direction(cs1_fd, GPIOD_DIR_OUT); cs1_fd < 0 ||
        gpiod_set_data_direction(cs2_fd, GPIOD_DIR_OUT); cs2_fd < 0) {
        perror("Failed to set CS lines to output");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open or create CSV file for logging
    const char *csv_file = "soil_moisture_log.csv";
    int csv_fd = open(csv_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd == -1) {
        perror("Failed to open/write CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
    if (fwrite("timestamp,sensor1,sensor2,sensor3\n", 1, sizeof("timestamp,sensor1,sensor2,sensor3"), csv_fd) != 1) {
        perror("Failed to write header to CSV file");
        close(csv_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read from MCP3008 channels
        uint16_t sensor1 = read_mcp3008(spi_fd, MCP3008_ADDR, 0);
        uint16_t sensor2 = read_mcp3008(spi_fd, MCP3008_ADDR, 1);
        uint16_t sensor3 = read_mcp3008(spi_fd, MCP3008_ADDR, 2);

        // Check for errors
        if (sensor1 == 0 || sensor2 == 0 || sensor3 == 0) {
            fprintf(stderr, "Error reading from MCP3008\n");
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Write to CSV file
        if (fwrite(timestamp, 1, strlen(timestamp), csv_fd) != 1 ||
            fprintf(csv_fd, ",%u,%u,%u\n", sensor1, sensor2, sensor3) != 3) {
            perror("Failed to write to CSV file");
            break; // Exit on write error
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Handle SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Clean up
cleanup:
    // Close resources in reverse order of opening
    close(csv_fd);
    close(spi_fd);
    gpiod_set_data_direction(cs2_fd, GPIOD_DIR_INPUT); // Reset CS2
    gpiod_set_data_direction(cs1_fd, GPIOD_DIR_INPUT); // Reset CS1
    gpiod_set_data_direction(cs0_fd, GPIOD_DIR_INPUT); // Reset CS0
    gpiod_close(cs0_fd);
    gpiod_close(cs1_fd);
    gpiod_close(cs2_fd);

    return EXIT_SUCCESS;
}

// Function to read from MCP3008
uint16_t read_mcp3008(int spi_fd, uint8_t addr, uint8_t channel) {
    uint16_t data = 0;
    // Set the chip select low
    gpiod_write(cs_fd, 0); // Assuming cs_fd is the correct GPIO descriptor for the active CS line

    // Write the command and address to the MCP3008
    if (write(spi_fd, &addr, 1) != 1 || write(spi_fd, &channel, 1) != 1) {
        return 0; // Return 0 if any write fails
    }

    // Read 10-bit ADC value
    if (read(spi_fd, &data, 2) != 2) {
        return 0; // Return 0 if read fails
    }

    // Set the chip select high
    gpiod_write(cs_fd, 1);

    return data;
}

