#include <signal.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_ADDR 0x68
#define CE_PIN 8
#define SPI_SPEED 1000000

#define RELAY_PIN 18
#define THRESHOLD_PERCENT 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

volatile sig_atomic_t should_exit = 0;

void setup_spi() {
    int spi_fd;
    struct spi_device *spi;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi = gpiod_spi_open(spi_fd, SPI_SPEED, 0);
    if (!spi) {
        perror("Failed to open SPI device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_set_data_direction(spi, GPIOD_DATA_OUT);
    gpiod_set_polarity(RELAY_PIN, GPIOD_POLARITY_HIGH);
    gpiod_set_mode(RELAY_PIN, GPIOD_MODE_OUTPUT);

    gpiod_set_function(CE_PIN, GPIOD_FUNCTION GPIO);
    gpiod_write(CE_PIN, 1);

    // Initialize MCP3008
    gpiod_spi_transfer(spi, MCP3008_ADDR, 0x01, 0x00, 0); // Set channel to 0
}

void cleanup_spi() {
    gpiod_spi_transfer(spi, MCP3008_ADDR, 0x01, 0x00, 0); // Reset channel
    gpiod_spi_close(spi);
    close(spi_fd);
}

void pump_on(int duration) {
    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    while (clock_gettime(CLOCK_REALTIME, &end) - start < duration * 1000000) {
        // No-op
    }

    printf("Pump activated for %d ms\n", (int)((end.tv_sec * 1000000) + (end.tv_nsec / 1000)));
}

void pump_off() {
    gpiod_set_function(RELAY_PIN, GPIOD_FUNCTION_NONE);
    gpiod_write(RELAY_PIN, 0);
}

void read_moisture() {
    int value;
    int attempts = 3;

    while (attempts--) {
        gpiod_spi_transfer(spi, MCP3008_ADDR, 0x01, 0x00, &value);
        if (value != 0) {
            break;
        }
        usleep(1000); // 1 ms delay between attempts
    }

    float moisture_level = (float)value / 1024.0 * 3.0; // 0-3V range
    float threshold_level = THRESHOLD_PERCENT / 100.0 * 3.0;

    if (moisture_level < threshold_level) {
        pump_on(DEFAULT_PUMP_DURATION);
        printf("Moisture level below threshold, activating pump\n");
    } else {
        printf("Moisture level: %f%%\n", moisture_level * 100);
    }
}

void log_event(const char *message, const struct timespec *timestamp) {
    char log_entry[256];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", timestamp);
    sprintf(log_entry + strlen("%Y-%m-%d %H:%M:%S"), "Moisture: %f%% or Pump: Activated/Deactivated", (message == "Moisture level below threshold" ? moisture_level * 100 : (pump_on ? "Activated for " : "Deactivated after "));
    fprintf(stderr, "%s\n", log_entry);
}

int main(int argc, char **argv) {
    const char *threshold_str = "30";
    int threshold = atoi(threshold_str);
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "-t") == 0) {
                threshold = atoi(argv[i + 1]);
            } else if (strcmp(argv[i], "-d") == 0) {
                pump_duration = atoi(argv[i + 1]);
            } else if (strcmp(argv[i], "-s") == 0) {
                sleep_interval = atoi(argv[i + 1]);
            } else {
                fprintf(stderr, "Unknown option: %s\n", argv[i]);
                return EXIT_FAILURE;
            }
        }
    }

    setup_spi();
    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent immediate pump off
    signal(SIGTERM, SIG_DFL); // Restore default action for SIGTERM

    struct timespec sleep_duration;
    sleep_duration.tv_sec = sleep_interval;
    sleep_duration.tv_nsec = 0;

    while (!should_exit) {
        clock_gettime(CLOCK_REALTIME, &should_exit_ts);
        log_event("Checking moisture level", &should_exit_ts);
        read_moisture();
        clock_nanosleep(CLOCK_REALTIME, &sleep_duration, NULL, NULL);
    }

    pump_off();
    cleanup_spi();

    return EXIT_SUCCESS;
}

