#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define MAX4466_ADC_CHANNEL 0
#define SPI0_NAME "spi0"
#define CE0_GPIO 8
#define CLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9

#define THRESHOLD_VALUE 1023

// Function prototypes
void setup_gpios(void);
void cleanup_gpios(void);
void setup_spi(void);
void cleanup_spi(void);
void read_adc(uint16_t channel);
void detect_peak(int value);
void log_peak_event(const char *timestamp, int value);
void handle_signals(int signum);

int main() {
    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIOs
    setup_gpios();

    // Initialize SPI
    setup_spi();

    uint16_t adc_value;
    time_t now;
    char log_entry[256];

    while (1) {
        // Read ADC value
        read_adc(MAX4466_ADC_CHANNEL);

        // Check for peak detection
        if (adc_value > THRESHOLD_VALUE) {
            detect_peak(adc_value);
        }

        // Format and log the peak event
        now = time(NULL);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S.%f", &now);
        log_peak_event(log_entry, adc_value);

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up resources
    cleanup_spi();
    cleanup_gpios();

    return 0;
}

// Function to setup GPIOs
void setup_gpios(void) {
    gpiod_set_data_direction(GPIO_DIR_OUT, CE0_GPIO);
    gpiod_set_value(CE0_GPIO, 1);

    gpiod_set_data_direction(GPIO_DIR_OUT, CLK_GPIO);
    gpiod_set_value(CLK_GPIO, 1);

    gpiod_set_data_direction(GPIO_DIR_OUT, MOSI_GPIO);
    gpiod_set_value(MOSI_GPIO, 1);

    gpiod_set_data_direction(GPIO_DIR_IN, MISO_GPIO);
    gpiod_set_pull_mode(MISO_GPIO, GPIO_PULL_UP);
}

// Function to cleanup GPIOs
void cleanup_gpios(void) {
    gpiod_set_value(CE0_GPIO, 0);
    gpiod_set_value(CLK_GPIO, 0);
    gpiod_set_value(MOSI_GPIO, 0);
    gpiod_set_value(MISO_GPIO, 0);
}

// Function to setup SPI
void setup_spi(void) {
    int spi_dev;
    spi_dev = gpiod_get_device_by_name(SPI0_NAME);

    if (spi_dev == GPIOD-device-not-found) {
        fprintf(stderr, "Error: SPI device not found\n");
        exit(EXIT_FAILURE);
    }

    libgpiod_spi_config_t config;
    config.mode = LIBGPIOD_SPI_MODE_0;
    config.speed = 1000000; // 1 MHz

    if (libgpiod_spi_config(spi_dev, &config) < 0) {
        fprintf(stderr, "Error configuring SPI: %s\n", libgpiod_strerror(-1));
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup SPI
void cleanup_spi(void) {
    libgpiod_spi_unconfig(spi_dev);
    gpiod_put_device(spi_dev);
}

// Function to read ADC value from MAX4466
void read_adc(uint16_t channel) {
    uint16_t value;
    libgpiod_spi_transfer(spi_dev, channel, 0, &value, 1);
    if (value == 0) {
        fprintf(stderr, "Error reading ADC value\n");
        exit(EXIT_FAILURE);
    }
}

// Function to detect a peak
void detect_peak(int value) {
    if (value > THRESHOLD_VALUE) {
        log_peak_event("timestamp", value);
    }
}

// Function to log a peak event
void log_peak_event(const char *timestamp, int value) {
    FILE *log_file = fopen("/var/log/sound_events.log", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Unable to open log file for writing\n");
        return;
    }

    fprintf(log_file, "%s: %d\n", timestamp, value);
    fclose(log_file);
}

// Signal handler to clean up on SIGINT or SIGTERM
void handle_signals(int signum) {
    // Clean up resources
    cleanup_gpios();
    cleanup_spi();
    exit(EXIT_SUCCESS);
}

