#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <sys/syslog.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_BUS_NUM 1
#define SS49E_ADDR 0x48
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERTTEMPSTD 0x00
#define ADS1115_REG_CONVERTGAIN 0x01
#define ADS1115_REG_CONVERTDATA 0x02
#define SAMPLE_RATE_HZ 1
#define THRESHOLD_GAUSS 500

volatile sig_atomic_t shutdown_flag = 0;

// Circular buffer for rolling average
#define BUFFER_SIZE 100
uint16_t buffer[BUFFER_SIZE];

// ADC conversion gain and offset
uint16_t gain = 1; // Gain of 1 corresponds to 3.3V full scale
uint16_t offset = 0;

// GPIO pin for motor shutdown
#define GPIO27_PIN 27

int main() {
    // Initialize syslog
    openlog("hall_sensor_monitor", LOG_PID, LOG_USER);

    // Initialize GPIO
    gpiod_direction_output(GPIO27_PIN, 0);

    // Initialize I2C
    int i2c_dev = i2c_open(I2C_BUS_NUM, 0);
    if (i2c_dev < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Configure ADS1115
    i2c_smbus_write_word_data(i2c_dev, ADS1115_ADDR, ADS1115_REG_CONVERTGAIN | (gain << 8));
    i2c_smbus_write_word_data(i2c_dev, ADS1115_ADDR, ADS1115_REG_CONVERTTEMPSTD | (offset << 8));

    // Start monitoring loop
    signal(SIGINT, handleInterrupt);
    signal(SIGTERM, handleInterrupt);
    while (1) {
        // Read from SS49E
        int result = i2c_smbus_read_word_data(i2c_dev, SS49E_ADDR, 0x00);
        if (result < 0) {
            syslog(LOG_WARNING, "Failed to read from SS49E");
            continue;
        }

        // Convert raw value to magnetic field strength
        uint16_t raw_value = result;
        float magnetic_field = (float)raw_value / (float)65535.0 * 3.3; // Assuming full scale is 3.3V

        // Check for out-of-range values
        if (magnetic_field < 0.0 || magnetic_field > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Out-of-range magnetic field value: %f Gauss", magnetic_field);
            continue;
        }

        // Store in circular buffer
        buffer[(buffer % BUFFER_SIZE)++] = raw_value;

        // Compute rolling average
        float rolling_average = 0.0;
        for (int i = 0; i < BUFFER_SIZE; ++i) {
            rolling_average += buffer[i];
        }
        rolling_average /= BUFFER_SIZE;

        // Check threshold
        if (rolling_average > THRESHOLD_GAUSS) {
            syslog(LOG_INFO, "Threshold exceeded: %f Gauss", rolling_average);
            shutdown_flag = 1;
            gpiod_set_value(GPIO27_PIN, 1); // Drive GPIO27 HIGH
        }

        // Handle interrupts
        if (shutdown_flag) {
            gpiod_set_value(GPIO27_PIN, 0); // Drive GPIO27 LOW on exit
            syslog(LOG_INFO, "Motor shutdown triggered");
            shutdown_flag = 0;
        }

        // Sleep to maintain 1 Hz sample rate
        usleep(SAMPLE_RATE_HZ * 1000000);
    }

    // Clean up on exit
    syslog(LOG_INFO, "Exiting...");
    i2c_close(i2c_dev);
    gpiod_cleanup();

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void handleInterrupt(int signum) {
    shutdown_flag = 1;
}

