#include <fcntl.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_ADDR 0x68
#define VH400_THRESHOLD 300
#define RELAY_GPIO 18
#define WATERING_INTERVAL 60

// GPIO descriptor for the relay
struct gpio_desc *relay;

// SPI device context
struct spi_device *spi;
struct spi_ioc_transfer *tx;
int count = 1;

// Function prototypes
void setup_spi();
void read_adc(int channel);
void handle_watering_event(int value);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIO for the relay
    if ((relay = gpiochip_open(GPIOD, GPIO_NUM_18)) == NULL) {
        perror("Failed to open GPIO 18");
        exit(EXIT_FAILURE);
    }

    // Setup SPI
    setup_spi();

    // Main loop
    while (1) {
        // Wait for the next watering interval
        sleep(WATERING_INTERVAL);

        // Read ADC value
        read_adc(0);

        // Check if watering is needed
        if (read_adc_value < VH400_THRESHOLD) {
            handle_watering_event(read_adc_value);
        }

        // Handle signals
        if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
            perror("Failed to install signal handlers");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to setup SPI
void setup_spi() {
    int spi_fd;
    struct spi_device_id ids[] = {
        SPI_DEVICE_ID(MCP3008_ADDR),
        { .count = 0 }
    };

    spi_fd = spi_open(SPI_DEVICE, &ids[0], SPI_MODE_0);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    spi_set_bitrate(spi, 1000000); // 1 MHz
}

// Function to read ADC value from MCP3008
void read_adc(int channel) {
    struct spi_ioc_transfer tx[] = {
        SPI_IOC_MESSAGE(1),
        SPI_IOTX(channel),
        SPI_IOC_MESSAGE(1),
    };

    tx->tx_buf = (unsigned char *) &channel;
    tx->rx_buf = (unsigned char *) &count;

    if (spi_transfer(spi, tx, 1) < 0) {
        fprintf(stderr, "Error reading from MCP3008\n");
        return;
    }

    if (count == 0) {
        fprintf(stderr, "No data received from MCP3008\n");
        return;
    }

    // Convert 10-bit value to integer
    int adc_value = (count * 1024) / 4096;
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return;
    }

    // Handle watering event
    handle_watering_event(adc_value);
}

// Function to handle watering event
void handle_watering_event(int value) {
    // Activate relay for 10 seconds
    gpio_request(relay, "water_pump");
    if (gpio_direction_output(relay, 1) == 0) {
        perror("Failed to set relay as output");
        gpio_free(relay);
        return;
    }

    struct timespec timeout = { .tv_sec = 10, .tv_nsec = 0 };
    nanosleep(&timeout, NULL);

    // Deactivate relay
    gpio_free(relay);
}

// Function to handle signals
void handle_signal(int signum) {
    // Immediately turn off the pump
    gpio_request(relay, "water_pump");
    if (gpio_direction_output(relay, 0) == 0) {
        perror("Failed to turn off relay");
        return;
    }

    // Release resources and exit
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Release SPI device
    spi_close(spi);

    // Release GPIO descriptor
    gpio_free(relay);
}

// Helper function to perform SPI transfer
int spi_transfer(struct spi_device *spi, struct spi_ioc_transfer *tx, int tx_count) {
    int ret = spi_write(spi, tx->tx_buf, tx->len, tx->delay);
    if (ret < 0) {
        fprintf(stderr, "SPI write error: %d\n", ret);
        return ret;
    }

    int rx_count = spi_read(spi, tx->rx_buf, tx->len, tx->delay);
    if (rx_count < 0) {
        fprintf(stderr, "SPI read error: %d\n", rx_count);
        return rx_count;
    }

    return 0;
}

