// MCP3008 configuration
#define ADC_CHANNEL 0
#define ADC_MODE 0
#define ADC_FREQ_MHZ 1

// GPIO setup
#define PWM_GPIO GPIO18
#define PWM_FREQ_KHZ 1000

// Global variables
struct gpiod_device *spi_dev;
struct gpiod_channel *spi_channel;
int spi_fd;
uint8_t adc_data[1];
int pwm_duty_cycle = 0;

// SIGINT/SIGTERM handler
void signal_handler(int signum) {
    gpiod_channel_set_data(spi_channel, 0); // Stop PWM
    gpiod_channel_unexport(spi_channel);
    gpiod_device_unexport(spi_dev);
    close(spi_fd);
    exit(0);
}

int main() {
    // Initialize GPIO for SPI and PWM
    if (gpiod_export(PWM_GPIO, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error exporting GPIO %u\n", PWM_GPIO);
        return EXIT_FAILURE;
    }

    // Open SPI device
    spi_fd = open(SPI0_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s\n", SPI0_DEVICE);
        return EXIT_FAILURE;
    }

    // Initialize MCP3008 SPI configuration
    if (i2c_smbus_write_byte_data(-1, MCP3008_ADDR, 0x01) != 1) {
        fprintf(stderr, "Error setting MCP3008 to config mode\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI frequency
    if (i2c_smbus_write_byte_data(-1, MCP3008_ADDR, 0x02 | (ADC_FREQ_MHZ << 1) | ADC_MODE | (ADC_CHANNEL << 5))) != 1) {
        fprintf(stderr, "Error setting SPI frequency and mode\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Export SPI channel
    spi_dev = gpiod_get_device_by_path(SPI0_DEVICE);
    if (!spi_dev) {
        fprintf(stderr, "Error getting SPI device\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    spi_channel = gpiod_channel_get_by_name(spi_dev, "CE0");
    if (!spi_channel) {
        fprintf(stderr, "Error getting SPI channel CE0\n");
        gpiod_device_unexport(spi_dev);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set CE0 as output
    if (gpiod_channel_set_direction(spi_channel, GPIOD_OUT_HIGH) < 0) {
        fprintf(stderr, "Error setting CE0 direction\n");
        gpiod_channel_unexport(spi_channel);
        gpiod_device_unexport(spi_dev);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // SIGINT/SIGTERM handler registration
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read ADC value
        if (i2c_smbus_read_byte_data(-1, MCP3008_ADDR, 0x03) != ADC_CHANNEL) {
            fprintf(stderr, "Error reading ADC value\n");
            continue;
        }
        adc_data[0] = i2c_smbus_read_byte_data(-1, MCP3008_ADDR, 0x00);

        // Convert ADC value to PWM duty cycle
        pwm_duty_cycle = (adc_data[0] * 1024) / 4096;

        // Set PWM duty cycle
        if (gpiod_set_value(PWM_GPIO, pwm_duty_cycle) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle\n");
            continue;
        }

        // Print ADC reading and PWM value
        printf("ADC reading: %hu\n", adc_data[0]);
        printf("PWM duty cycle: %u\n", pwm_duty_cycle);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    gpiod_channel_set_data(spi_channel, 0); // Stop PWM
    gpiod_channel_unexport(spi_channel);
    gpiod_device_unexport(spi_dev);
    close(spi_fd);

    return EXIT_SUCCESS;
}

