void read_analog_values(int channel);
void convert_digital_to_analog(int value);
void write_to_csv(const char *data);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Check if gpiod library is initialized correctly
    if (gpiod_is_valid()) {
        printf("gpiod library initialized successfully.\n");
    } else {
        perror("gpiod initialization failed");
        return EXIT_FAILURE;
    }

    // Attempt to open SPI device
    int spi_fd = open(SPI0_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("SPI device open failed");
        return EXIT_FAILURE;
    }

    // Initialize MCP3008 configuration
    struct spi_i2c_device_id mcp3008_ids[] = {
        SPI_I2C_DEVICE_ID(MCP3008_ADDR, 0),
        { }
    };

    int rc = spi_register_board_info(mcp3008_ids, 1);
    if (rc != 0) {
        fprintf(stderr, "Failed to register MCP3008 device: %d\n", rc);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read analog values
        read_analog_values(0);
        read_analog_values(1);
        read_analog_values(2);

        // Convert and append to CSV
        char data[1024];
        sprintf(data, "%s,%f,%f,%f\n", 
                // Timestamp
                ctime(&time(NULL)),
                // Channel 0 voltage
                convert_digital_to_analog(gpio_read_raw(0)),
                // Channel 1 voltage
                convert_digital_to_analog(gpio_read_raw(1)),
                // Channel 2 voltage
                convert_digital_to_analog(gpio_read_raw(2)));

        write_to_csv(data);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Cleanup on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close SPI device and release resources
    cleanup();

    return EXIT_SUCCESS;
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_FAILURE); // Exit with failure for consistency
}

// Function to read analog values from MCP3008
void read_analog_values(int channel) {
    int value;
    // Set the channel and trigger the conversion
    gpio_set_direction(channel, GPIO_DIR_OUT);
    gpio_write(channel, 1);

    // Wait for conversion to complete
    usleep(10000);

    // Read the 10-bit value
    value = gpio_read(channel);

    // Convert 10-bit value to voltage
    convert_digital_to_analog(value);
}

// Function to convert 10-bit digital value to voltage
void convert_digital_to_analog(int value) {
    float voltage = (value * VREF) / 1024.0;
    printf("Analog voltage on channel %d: %f V\n", channel, voltage);
}

// Function to write data to CSV file
void write_to_csv(const char *data) {
    FILE *csv_file = fopen("sensor_data.csv", "a+");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(csv_file, "%s", data);
    fclose(csv_file);
}

// Function to clean up resources
void cleanup() {
    // Close SPI device
    close(spi_fd);

    // Unregister MCP3008 device
    spi_unregister_board_info(MCP3008_ADDR, 1);

    // Release gpiod resources
    gpiod_unexport_all();
}

