#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define MAX9814_ADC_CHANNEL 0
#define VIBRATION_MOTOR_GPIO_17 17
#define VIBRATION_MOTOR_GPIO_27 27
#define THRESHOLD_NOISE_LEVEL 500
#define PWM_FREQ_HZ 100
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "vibration_log.txt"

volatile sig_atomic_t sigIntReceived = 0;

// Function prototypes
void setup_spi();
void setup_motors();
void start_sampling();
void handle_vibration_event(uint16_t noise_level);
void cleanup();
void error_handler(const char *operation, int error);

int main() {
    // Initialize signal handlers
    signal(SIGINT, &handle_int);
    signal(SIGTERM, &handle_int);

    // Setup logging
    FILE *log_file = fopen(LOG_FILE, "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Setup SPI
    setup_spi();

    // Setup motors and PWM
    setup_motors();

    // Start sampling and processing
    start_sampling();

    // Run the main loop until interrupted
    while (!sigIntReceived) {
        // Sample noise level
        uint16_t noise_level;
        if (gpiod_c_read(SPI_DEVICE, MAX9814_ADC_CHANNEL, &noise_level, sizeof(noise_level)) < 0) {
            error_handler("gpiod_c_read", -1);
            continue;
        }

        // Check if noise level exceeds threshold
        if (noise_level > THRESHOLD_NOISE_LEVEL) {
            handle_vibration_event(noise_level);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    // Close log file
    fclose(log_file);

    return 0;
}

// Function to setup SPI
void setup_spi() {
    struct spi_device *spi;
    int spi_fd;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    spi = gpiod_spi_open(spi_fd, 0, 0, 0, 0, 0, 0, 0);
    if (spi == NULL) {
        error_handler("gpiod_spi_open", -1);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_spi_set_mode(spi, GPIOD_SPI_MODE_0);
    gpiod_spi_set_speed(spi, 1000000); // 1 MHz
}

// Function to setup motors and PWM
void setup_motors() {
    struct gpio_desc *motor17 = gpiod_get_desc(VIBRATION_MOTOR_GPIO_17);
    struct gpio_desc *motor27 = gpiod_get_desc(VIBRATION_MOTOR_GPIO_27);

    if (motor17 == NULL || motor27 == NULL) {
        fprintf(stderr, "Failed to get GPIO descriptors for motors\n");
        exit(EXIT_FAILURE);
    }

    // Configure GPIOs as outputs
    if (gpiod_direction_output(motor17, 0) != 0) {
        error_handler("gpiod_direction_output", -1, motor17);
        gpiod_free_desc(motor17);
        motor17 = NULL;
    }

    if (gpiod_direction_output(motor27, 0) != 0) {
        error_handler("gpiod_direction_output", -1, motor27);
        gpiod_free_desc(motor27);
        motor27 = NULL;
    }

    // Setup PWM
    pwm_config_t pwm_config = {
        .frequency = PWM_FREQ_HZ,
        .duty_cycle = 50, // 50% duty cycle for 3V output
    };

    if (gpiod_pwm_init(motor17, &pwm_config) < 0) {
        error_handler("gpiod_pwm_init", -1, motor17);
        gpiod_free_desc(motor17);
        motor17 = NULL;
    }

    if (gpiod_pwm_init(motor27, &pwm_config) < 0) {
        error_handler("gpiod_pwm_init", -1, motor27);
        gpiod_free_desc(motor27);
        motor27 = NULL;
    }
}

// Function to handle vibration event
void handle_vibration_event(uint16_t noise_level) {
    if (noise_level > THRESHOLD_NOISE_LEVEL) {
        fprintf(log_file, "Vibration event at %lu\n", noise_level);
        sigIntReceived = 1; // Set flag to exit on next iteration
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop motors
    if (motor17) {
        gpiod_pwm_stop(motor17);
        gpiod_free_desc(motor17);
        motor17 = NULL;
    }

    if (motor27) {
        gpiod_pwm_stop(motor27);
        gpiod_free_desc(motor27);
        motor27 = NULL;
    }

    // Close SPI device
    gpiod_spi_close(spi);
    close(spi_fd);
    spi = NULL;

    // Close log file
    fclose(log_file);
    log_file = NULL;
}

// Error handling function
void error_handler(const char *operation, int error) {
    fprintf(stderr, "Error during %s: %d\n", operation, error);
    cleanup();
    exit(EXIT_FAILURE);
}

