#include <inttypes.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <errno.h>

#define MAX9814_ADC_CHANNEL 0
#define BH1750_I2C_ADDR 0x23
#define BH1750_READ_TIMEOUT_MS 180

// Constants for SPI and I2C device paths
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"

// GPIO pin for MAX9814 CS (MCP3008 CE0)
#define MAX9814_CS_GPIO 18

// Function prototypes
void initialize_sensors();
void read_max9814();
void read_bh1750();
void write_to_csv(const char *line);
void handle_errors(int error_code);
void cleanup_resources();

int main() {
    // Initialize global variables
    FILE *csv_file = NULL;
    int sound_level_db = 0;
    int light_level_lux = 0;
    int error_code = 0;

    // Signal handlers for graceful shutdown
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = cleanup_resources;
    sigaction(SIGINT, &int_handler, NULL);
    sigaction(SIGTERM, &term_handler, NULL);

    // Main loop
    while (1) {
        // Record timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read sensors and handle errors
        error_code = read_max9814();
        if (error_code != 0) {
            handle_errors(error_code);
            continue;
        }

        error_code = read_bh1750();
        if (error_code != 0) {
            handle_errors(error_code);
            continue;
        }

        // Write to CSV file
        write_to_csv(timestamp ":sound_level_db:%d :light_level_lux:%d :error_code:%d\n",
                     sound_level_db, light_level_lux, error_code);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    cleanup_resources();

    return 0;
}

// Function to initialize sensors
void initialize_sensors() {
    // Initialize MCP3008 SPI
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfers[] = {
        // MCP3008 configuration and read command
        {
            .tx_buf = (unsigned char[]) {0x01, 0x00, 0x00, 0x00, 0x00, // Command: Start conversion
                                            0x01, 0x00}, // Channel: 0
            .rx_buf = (unsigned char[3]),
            .len = 8,
        },
        // Wait for conversion to complete
        {
            .tx_buf = (unsigned char[]) {0x00}, // Command: No operation
            .rx_buf = (unsigned char[3]),
            .len = 3,
        },
    };

    gpiod_set_data_direction(MAX9814_CS_GPIO, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_write(MAX9814_CS_GPIO, GPIOD_OUT_LOW);

    if (gpiod_spi_transfer(spi_fd, transfers, 2) < 0) {
        perror("Failed to communicate with MCP3008");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize BH1750 on I2C
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // BH1750 configuration
    i2c_set_speed(i2c_fd, 100000); // 100kHz
    if (i2c_transfer(i2c_fd, &BH1750_I2C_ADDR, 1, (uint8_t []) {0x00}, 1, NULL) != 1) {
        perror("Failed to communicate with BH1750");
        close(i2c_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Read light level
    read_bh1750();
}

// Function to read MAX9814 through MCP3008
int read_max9814() {
    int adc_value = 0;
    // Send command to start conversion
    gpiod_set_value(MAX9814_CS_GPIO, GPIOD_HIGH);
    usleep(1000); // Wait for MCP3008 to start conversion

    // Read the ADC value
    gpiod_set_value(MAX9814_CS_GPIO, GPIOD_LOW);
    adc_value = (gpiod_c_read(SPI_DEVICE, 0) >> 2) & 0x3F; // Read the 10-bit value

    // Convert ADC value to dB
    float sound_level_db = (ADC_MAX / 1024.0) * LOG10(2) * adc_value;
    sound_level_db = 20 * log10(sound_level_db) / log10(10);

    return 0; // No error
}

// Function to read BH1750 light level
int read_bh1750() {
    uint8_t data[2];
    int i2c_ret = i2c_transfer(i2c_fd, &BH1750_I2C_ADDR, 0x07, // Read light level command
                                data, 2, NULL);
    if (i2c_ret != 2) {
        perror("Failed to read BH1750");
        return -1; // Set error code
    }

    light_level_lux = (data[0] << 8) | data[1]; // Combine the two bytes

    return 0; // No error
}

// Function to write to CSV file
void write_to_csv(const char *line) {
    if (csv_file == NULL) {
        csv_file = fopen("tamper_log.csv", "a+");
        if (csv_file == NULL) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
    }

    if (fputs(line, csv_file) == NULL) {
        perror("Failed to write to CSV file");
        fclose(csv_file);
        exit(EXIT_FAILURE);
    }

    fclose(csv_file);
}

// Function to handle errors and set error code
void handle_errors(int error_code) {
    // Log or handle the error code as necessary
    // Example: fprintf(stderr, "Error: %d\n", error_code);
}

// Function to cleanup resources on SIGINT/SIGTERM
void cleanup_resources() {
    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close SPI file descriptor
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close CSV file
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

