#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_ADDR 0x48
#define VH400_THRESHOLD 30

// MCP3008 configuration
#define MCP3008_CONFIG (1 << MCP3008_MODE_0)

// GPIO pins
#define GPIO_PUMP BCM_GPIO_17
#define CE0_GPIO BCM_GPIO_7

// SPI device path
#define SPI_DEVICE "/dev/spidev0.0"

// Function prototypes
void setup_spi();
void setup_gpio();
void read_moisture();
void handle_signal(int signum);
void release_resources();

int main() {
    // Initialize GPIO and SPI
    setup_spi();
    setup_gpio();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Check moisture every 60 seconds
        struct timespec timestamp;
        clock_gettime(CLOCK_REALTIME, &timestamp);
        uint64_t timestamp_ms = timestamp.tv_sec * 1000 + timestamp.tv_nsec / 1000000;

        if ((timestamp_ms - last_moisture_check) >= 60000) {
            read_moisture();
            last_moisture_check = timestamp_ms;
        }

        // Sleep for the remainder of the second
        usleep(1000000 - (timestamp_ms - last_moisture_check));
    }

    // Release resources on exit
    release_resources();

    return 0;
}

// Function to setup SPI
void setup_spi() {
    int spi_fd;
    struct spi_device *spi_dev;

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("open SPI device");
        exit(EXIT_FAILURE);
    }

    // Check if SPI device is supported
    if (gpiod_is_valid_device(SPI_DEVICE)) {
        printf("SPI device is valid\n");
    } else {
        fprintf(stderr, "SPI device not valid\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request SPI device
    if ((spi_dev = gpiod_request_device(SPI_DEVICE, GPIOD_FLAG_NO_WAIT)) == NULL) {
        fprintf(stderr, "Failed to request SPI device\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI parameters
    if (ioctl(spi_fd, GPIOD_IOCTL_SET_SPEED, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set CE0 GPIO as output
    if (gpio_direction_output(CE0_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set CE0 as output\n");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Enable SPI clock
    if (gpiod_enable_pin(CE0_GPIO) < 0) {
        fprintf(stderr, "Failed to enable CE0 GPIO\n");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Configure MCP3008
    if (ioctl(spi_fd, GPIOD_IOCTL_WRITE_REG, (void *)MCP3008_ADDR | MCP3008_CONFIG)) {
        fprintf(stderr, "Failed to configure MCP3008\n");
        gpiod_release_device(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    printf("SPI and MCP3008 initialized successfully\n");
}

// Function to setup GPIO for the relay
void setup_gpio() {
    int relay_gpio;

    // Open GPIO pin for the relay
    if ((relay_gpio = gpio_open(GPIO_PUMP, GPIO_OUTPUT_HIGH)) < 0) {
        perror("Failed to open GPIO pin");
        exit(EXIT_FAILURE);
    }

    // Set the relay GPIO as active high
    if (gpio_direction_output(GPIO_PUMP, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %u as output\n", GPIO_PUMP);
        gpio_close(relay_gpio);
        exit(EXIT_FAILURE);
    }

    printf("GPIO %u setup for relay\n", GPIO_PUMP);
}

// Function to read moisture level
void read_moisture() {
    int ret;
    uint16_t data;

    // Write to MCP3008 to start conversion
    if (ioctl(spi_fd, GPIOD_IOCTL_WRITE_REG, (void *)MCP3008_ADDR | 0x01) < 0) {
        fprintf(stderr, "Failed to start conversion\n");
        return;
    }

    // Wait for conversion to complete
    usleep(10);

    // Read the moisture level data
    if ((ret = read(spi_fd, &data, 2)) != 2) {
        if (ret == -1) {
            perror("Read error");
            return;
        } else {
            fprintf(stderr, "Failed to read data, got %d bytes\n", ret);
            return;
        }
    }

    // Check if the read was successful and moisture is below threshold
    if (data < VH400_THRESHOLD) {
        // Activate the relay to turn on the water pump
        gpio_write(relay_gpio, 1);
        printf("Moisture level below threshold, activating pump\n");
    } else {
        // Deactivate the relay to turn off the water pump
        gpio_write(relay_gpio, 0);
        printf("Moisture level above threshold, deactivating pump\n");
    }

    // Release CE0 GPIO
    gpiod_disable_pin(CE0_GPIO);

    // Close SPI device on error
    close(spi_fd);
}

// Signal handler to turn off the pump and release resources
void handle_signal(int signum) {
    // Turn off the pump
    gpio_write(GPIO_PUMP, 0);

    // Release resources
    release_resources();
}

// Function to release resources
void release_resources() {
    // Release GPIO
    gpio_close(GPIO_PUMP);

    // Release SPI device
    gpiod_release_device(spi_dev);

    // Close SPI device file descriptor
    close(spi_fd);
}

