        // Data out (channel select)
        SPI_IOC_MESSAGE(1),
        { .len = 1, .bits = 8, .delay_usecs = 0, .data = (uint8_t)(channel) },
        // Read ADC value
        SPI_IOC_MESSAGE(1),
        { .len = 2, .delay_usecs = 10000 },
        // Stop condition
        SPI_IOC_MESSAGE(1),
