// Constants for SPI communication
#define SPI_SPEED 1000000
#define SPI_MODE 0 // Mode 0: Master Transmits First, Slave Transmits Second

// GPIO setup
#define GPIO_RELAY_NAME "gpio17"
#define GPIO_RELAY_DIR GPIO_OUT
#define GPIO_RELAY_TYPE GPIO_BCM

// SPI setup
#define MCP3008_ADDR 0x48

// Function prototypes
void setup_spi();
void read_adc(uint16_t);
void handle_relay(int value);
void log_detection(char *timestamp);
void cleanup();

int main() {
    // Initialize GPIO and SPI
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    if (setup_spi() < 0) {
        perror("setup_spi");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Poll the ADC every 100ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 100 / 1000;
        ts.tv_nsec += (100 % 1000) * 1000000;
        clock_nanosleep(CLOCK_REALTIME, &ts, NULL, NULL);

        // Read ADC value
        uint16_t adc_value = 0;
        if (read_adc(adc_value) < 0) {
            perror("read_adc");
            continue;
        }

        // Check if distance is below 20 cm
        if (adc_value < 1024 / 2) {
            handle_relay(1); // Energize the relay
            log_detection(__func__);
            sleep(DEBOUNCE_TIME); // Debounce delay
        } else {
            handle_relay(0); // De-energize the relay
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to setup SPI
void setup_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_device_id ids[] = {
        SPI_DEVICE_ID(MCP3008_ADDR),
        { .count = 0 }
    };

    int err = spi_device_add_table(&ids, 1);
    if (err < 0) {
        perror("spi_device_add_table");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI parameters
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_set_data_direction(GPIO_RELAY_NAME, GPIO_RELAY_DIR);
}

// Function to read ADC value from MCP3008
int read_adc(uint16_t *adc_value) {
    int ret;
    struct spi_ioc_transfer transfers[] = {
        // Start condition, send address, send mode (0 for master-out-first)
        SPI_IOC_MESSAGE(1),
        { .tx_buf = (unsigned long)&SENSOR_ADDR, .len = sizeof(SENSOR_ADDR) },
        { .rx_buf = adc_value, .len = sizeof(*adc_value) },
    };

    ret = spi_transfer(spi_fd, transfers, 1);
    if (ret < 0) {
        perror("spi_transfer");
        return -1;
    }

    return 0;
}

// Function to handle the relay
void handle_relay(int value) {
    int ret = gpiod_set_value(GPIO_RELAY_NAME, value, GPIO_RELAY_DIR);
    if (ret < 0) {
        perror("gpiod_set_value");
    }
}

// Function to log detection event with timestamp
void log_detection(char *timestamp) {
    FILE *file = fopen("door_events.log", "a+");
    if (!file) {
        perror("fopen door_events.log");
        return;
    }

    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

// Function to cleanup resources
void cleanup() {
    gpiod_cleanup();
    close(spi_fd);
}

// Helper function for SPI transfer
int spi_transfer(int fd, struct spi_ioc_transfer *tx, int tx_count) {
    int ret = -ENOSYS;
    if (ioctl(fd, SPI_IOC_MESSAGE(tx_count), tx) < 0) {
        ret = errno;
    }

    return ret;
}

