#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <sys/time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_ADDR 0x68
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8

#define MAX_READ_ATTEMPTS 5
#define BACKOFF_MULT 2

// MCP3008 control register bits
#define ADSC 0x01
#define ADSTART 0x02
#define ADCLK 0x04
#define ADLATCH 0x08

// SPI command byte for single-ended mode, channel 0
#define MCP3008_CMD_SINGLE_ENDED 0x01

// Function prototypes
void spi_init();
int spi_read(int fd, unsigned char cmd);
void close_spi();
void handle_signal(int signum);

int main() {
    int fd;
    int attempts = 0;
    int ret;
    struct timeval start, diff;
    unsigned int adc_value;
    float moisture_percentage;
    char buffer[128];

    // Initialize SPI
    spi_init();

    while (1) {
        // Attempt to open SPI device
        fd = open(SPI_DEVICE, O_RDWR);
        if (fd == -1) {
            perror("open");
            continue;
        }

        // Set SPI parameters
        ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
        if (ret != 0) {
            perror("ioctl: SPI_IOC_WR_MAX_SPEED_HZ");
            close_spi();
            break;
        }

        ret = ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE);
        if (ret != 0) {
            perror("ioctl: SPI_IOC_WR_MODE");
            close_spi();
            break;
        }

        // Set CE pin as output
        gpiod_set_data_direction(GPIO8, GPIOD_DIR_OUT);
        gpiod_write(GPIO8, 0); // Set CE0 low

        // Main loop
        gettimeofday(&start, NULL);
        while (1) {
            // Attempt to read from MCP3008
            for (attempts = 0; attempts < MAX_READ_ATTEMPTS; ++attempts) {
                adc_value = spi_read(fd, MCP3008_CMD_SINGLE_ENDED);
                if (adc_value != 0) {
                    break;
                }

                // Exponential backoff
                usleep(attempts * BACKOFF_MULT * 1000);
            }

            if (attempts == MAX_READ_ATTEMPTS) {
                // Failed to read, log error
                snprintf(buffer, sizeof(buffer), "Error reading sensor at %s", gmtime(&start.tv_sec).ctime());
                fprintf(stderr, "%s\n", buffer);
                continue;
            }

            // Convert ADC value to moisture percentage
            moisture_percentage = (float)adc_value / 1023.0 * 100;

            // Format timestamp and ADC value
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &start);
            sprintf(buffer + strlen(buffer), " %u", adc_value);

            // Write to file
            FILE *file = fopen("soil_data.txt", "a");
            if (file) {
                fprintf(file, "%s\n", buffer);
                fclose(file);
            } else {
                perror("fopen");
            }

            // Wait for 5 seconds
            sleep(5);
        }

        // Close SPI device and release resources
        close_spi();
    }

    return 0;
}

// Function to initialize SPI
void spi_init() {
    int spi_fd;
    struct spi_device_id ids[] = {
        SPI_DEVICE,
        { }
    };

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd == -1) {
        perror("spi_open");
        exit(EXIT_FAILURE);
    }

    // Set the CE pin as output
    gpiod_set_direction(GPIO8, GPIOD_DIR_OUT);

    // Set CE0 high (not used as chip select)
    gpiod_write(GPIO8, 1);
}

// Function to read from MCP3008
int spi_read(int fd, unsigned char cmd) {
    unsigned char data[1];
    int ret;

    // Set ADSTART bit to start conversion
    data[0] = (cmd | ADSTART);

    // Write command to MCP3008
    ret = write(fd, data, 1);
    if (ret != 1) {
        perror("write to MCP3008");
        return 0; // Return 0 to indicate failure
    }

    // Wait for conversion to complete
    usleep(10 * 1000); // Wait for ~10ms

    // Read converted data
    ret = read(fd, data, 1);
    if (ret != 1) {
        perror("read from MCP3008");
        return 0; // Return 0 to indicate failure
    }

    return data[0];
}

// Function to close SPI and release resources
void close_spi() {
    if (fd != -1) {
        close(fd);
        spi_close(spi_fd);
    }

    // Set CE pin as input (optional, for cleanup)
    gpiod_set_direction(GPIO8, GPIOD_DIR_IN);
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Gracefully shut down SPI and exit
    close_spi();
    exit(EXIT_SUCCESS);
}

