#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <stdint.h>

#define GPIO_NUM_CE0 8
#define SPI_CHANNEL 0
#define SPI_SPEED_MHZ 1000000
#define SPI_MODE 0
#define MAX_READ_ATTEMPTS 3

// Constants for MCP3008
#define MCP3008_ADDR 0x68
#define ADC_CHANNEL 0

// GPIO Pin Definitions
static const struct gpio_desc *spi_ce0 = gpiod_get_desc(GPIO_NUM_CE0);

// Function prototypes
void setup_spi();
int read_adc(uint8_t channel);
void classify_reading(uint16_t adc_value);
void append_to_log(const char *message);
void handle_interrupts(int signum);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize SPI
    setup_spi();

    while (1) {
        uint16_t adc_value;
        int attempts = 0;

        do {
            attempts++;
            if (attempts > MAX_READ_ATTEMPTS) {
                fprintf(stderr, "Failed to read ADC after %d attempts.\n", attempts);
                break;
            }

            adc_value = read_adc(SPI_CHANNEL);
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Sensor absent condition detected.\n");
                break;
            }

            classify_reading(adc_value);
            append_to_log("Alcohol level: %.2f ppm at %s\n", adc_value / 1023.0, ctime(&time(NULL)));
        } while (adc_value != 0 && attempts < MAX_READ_ATTEMPTS);

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent condition persists.\n");
            break;
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Graceful shutdown on SIGINT or SIGTERM
    handle_interrupts(SIGINT);
    handle_interrupts(SIGTERM);

    cleanup();

    return 0;
}

// Function to setup SPI
void setup_spi() {
    int spi_fd;
    struct spi_device *spi_device;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    spi_device = spi_open(spi_fd, SPI_SPEED_MHZ, SPI_MODE);
    if (!spi_device) {
        fprintf(stderr, "Failed to configure SPI device\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set CE0 as output
    gpiod_direction_output(spi_ce0, 1); // High for CE0
    if (gpiod_get_value(spi_ce0) != 1) {
        fprintf(stderr, "Failed to set CE0 high\n");
        spi_close(spi_device);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Enable SPI clock
    spi_write(spi_device, MCP3008_ADDR | (1 << ADC_CHANNEL), 1);
    if (spi_read(spi_device, 1) != 0x80) {
        fprintf(stderr, "Failed to enable SPI clock\n");
        spi_close(spi_device);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set single-ended mode and channel 0
    spi_write(spi_device, 0x01, 1); // Single-ended mode
    spi_write(spi_device, 0x00, 1); // Channel 0

    // Close SPI device after configuration
    spi_close(spi_device);
    close(spi_fd);
}

// Function to read the ADC value
int read_adc(uint8_t channel) {
    int ret;
    uint8_t cmd = 0x01 | (channel & 0x07);

    // Set CE0 low to start the transfer
    gpiod_set_value(spi_ce0, 0); // Low for CE0

    // Write command and address to the MCP3008
    ret = spi_write(spi_fd, cmd, 1);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed: %d\n", ret);
        return -1;
    }

    // Read the 10-bit ADC value
    ret = spi_read(spi_fd, 1);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1;
    }

    // Set CE0 high to end the transfer
    gpiod_set_value(spi_ce0, 1); // High for CE0

    return (spi_read(spi_fd, 1) >> 4) & 0x0F;
