#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11
#define ADC_CHANNEL 0
#define SAMPLE_RATE_HZ 1000
#define VREF 3300 // in mV

// Constants for SPI configuration
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_CLOCK_FREQ_HZ 1000000

// GPIO control functions
void gpio_set_high(int gpio) {
    if (gpio == GPIO_CE0) {
        if (ioctl(gpio, GPIO_SET, GPIO_HIGH) < 0) {
            perror("Error setting GPIO high");
            exit(EXIT_FAILURE);
        }
    }
}

void gpio_set_low(int gpio) {
    if (gpio == GPIO_CE0) {
        if (ioctl(gpio, GPIO_SET, GPIO_LOW) < 0) {
            perror("Error setting GPIO low");
            exit(EXIT_FAILURE);
        }
    }
}

// ADC and SPI initialization
int spi_fd = -1;
uint32_t spi_config = SPI_MODE | SPI_BITS_PER_WORD | SPI_MAX_CLOCK_FREQ_HZ;

void spi_init() {
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpio_set_low(GPIO_CE0); // Ensure CE0 is low before configuring SPI
}

void spi_cleanup() {
    gpio_set_high(GPIO_CE0); // Release CE0 after finishing
    close(spi_fd);
}

// ADC read function
uint32_t adc_read(uint8_t channel) {
    uint32_t value = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config) < 0) {
        perror("Error setting SPI mode");
        return 0;
    }

    gpio_set_low(GPIO_CE0); // Assert CE0
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_CLOCK_FREQ_HZ) < 0) {
        perror("Error setting SPI clock speed");
        gpio_set_high(GPIO_CE0);
        return 0;
    }

    gpio_set_high(GPIO_CE0); // De-assert CE0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_config) < 0) {
        perror("Error setting SPI mode back");
        return 0;
    }

    if (ioctl(spi_fd, SPI_IOC_READ_BLEN, &channel) < 0) {
        perror("Error reading ADC channel");
        return 0;
    }

    if (ioctl(spi_fd, SPI_IOC_WRITE_DATA, &channel) < 0) {
        perror("Error writing to ADC");
        return 0;
    }

    if (read(spi_fd, &value, sizeof(uint32_t)) != sizeof(uint32_t)) {
        perror("Error reading from ADC");
        return 0;
    }

    return value;
}

// Main program
int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize SPI and GPIO
    spi_init();

    uint32_t adc_value;
    int fd = open("audio_log.txt", O_WRONLY | O_CREAT, 0666);
    if (fd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    clockid_t clock_id = CLOCK_MONOTONIC_RAW;
    struct timespec ts;
    struct timespec ts_start;

    while (1) {
        // Get current time in nanoseconds
        if (clock_gettime(clock_id, &ts) == -1) {
            perror("Error getting monotonic clock time");
            break;
        }

        // Calculate the next sample time
        ts_start = ts;
        ts.tv_sec += 1 / SAMPLE_RATE_HZ;
        ts.tv_nsec += (1 / SAMPLE_RATE_HZ) * 1000000000;

        // Wait until the next sample time
        if (nanosleep(&ts, NULL) < 0) {
            perror("Error sleeping");
            break;
        }

        // Read ADC value and write to log file
        adc_value = adc_read(ADC_CHANNEL);
        if (fprintf(fd, "%" PRIuNS "|%" PRIu32 "\n", (uint64_t)(ts.tv_nsec / 1000), adc_value) == -1) {
            perror("Error writing to log file");
            break;
        }

        // Flush the log file after each write
        if (fflush(fd) == -1) {
            perror("Error flushing log file");
            break;
        }
    }

    // Cleanup on exit
    spi_cleanup();

    return 0;
}

// SIGINT and SIGTERM handler
void cleanup(int signum) {
    gpio_set_high(GPIO_CE0); // Release CE0
    close(spi_fd);
    close(fd);
    printf("Exiting due to signal.\n");
    exit(EXIT_SUCCESS);
}

