#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define SPI_CLOCK_FREQ_MHZ 1000
#define SPI_MODE SINGLE_ENDED
#define DELAY_MS 100

volatile sig_atomic_t sigint_received = 0;

void cleanup_resources(void) {
    if (gpiod_is_valid(GPIOD_SPI0)) {
        gpiod_unexport(GPIOD_SPI0);
    }
    if (access("gas_log.txt", F_OK) != -1) {
        remove("gas_log.txt");
    }
}

void sigint_handler(int signum) {
    sigint_received = 1;
}

int main(void) {
    struct gpiod_spi_link *spi_link;
    int spi_fd;
    uint8_t spi_transfer[2] = {0x01, 0x00}; // Command to read ADC
    int adc_value;
    time_t now;
    char buffer[100];
    FILE *log_file;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Attempt to open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR | O_CLOEXEC)) == -1) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Initialize SPI link
    if (gpiod_spi_link_open(spi_fd, SPI_MODE) == -1) {
        perror("Failed to initialize SPI link");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Export SPI0
    if (gpiod_export(GPIOD_SPI0, GPIOD_SPI0_BASE, 0, 0, 0) == -1) {
        perror("Failed to export SPI0");
        gpiod_spi_link_close(spi_link);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set SPI clock frequency
    if (gpiod_spi_set_clock(spi_link, SPI_CLOCK_FREQ_MHZ) == -1) {
        perror("Failed to set SPI clock frequency");
        gpiod_unexport(GPIOD_SPI0);
        gpiod_spi_link_close(spi_link);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO for CE0
    if (gpiod_export(GPIOD_CEC0, GPIOD_CEC0_BASE, 0, 0, 0) == -1) {
        perror("Failed to export CE0");
        gpiod_unexport(GPIOD_SPI0);
        gpiod_spi_link_close(spi_link);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file for appending
    if ((log_file = fopen("gas_log.txt", "a+")) == NULL) {
        perror("Failed to open log file");
        gpiod_unexport(GPIOD_CEC0);
        gpiod_unexport(GPIOD_SPI0);
        gpiod_spi_link_close(spi_link);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (!sigint_received) {
        // Read timestamp
        now = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read ADC value
        spi_transfer[1] = ADC_CHANNEL; // Select channel 0
        if (gpiod_spi_transfer(spi_link, spi_transfer, 2, 1000) == -1) {
            perror("SPI transfer failed");
            continue;
        }
        adc_value = spi_transfer[1]; // ADC value is returned in the second byte

        // Print to console
        printf("Voltage: %u mV, PPM: 0 (placeholder)\n", adc_value);
        printf("Timestamp: %s\n", buffer);

        // Append to log file
        fprintf(log_file, "Timestamp: %s, Voltage: %u mV, PPM: 0 (placeholder)\n", buffer, adc_value);

        // Delay for 1 second
        usleep(1000000);
    }

    // Clean up resources on SIGINT
    if (!sigint_received) {
        cleanup_resources();
    }

    // Close log file and SPI device
    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

