#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CS GPIO_NUM_8
#define MCP3008_MOSI GPIO_NUM_10
#define MCP3008_MISO GPIO_NUM_9
#define MCP3008_SCLK GPIO_NUM_11

#define ADXL335_XOUT 0
#define ADXL335_YOUT 1
#define ADXL335_ZOUT 2

#define BUFFER_SIZE 1024
#define REFERENCE_VOLTAGE 3300.0

// Kalman filter parameters
#define KF_STATE_SIZE 3
#define KF observation noise std dev 0.01 // 1% of full scale g
#define KF process noise std dev 0.001 // 0.1% of full scale g

// Kalman filter state and covariance matrices
double kalman_state[KF_STATE_SIZE];
double kalman_covariance[3][3];

// SPI transaction buffer
uint8_t spi_transfer_buffer[BUFFER_SIZE];

// MCP3008 configuration
int mcp3008_fd;
struct spi_device *spi;
struct spi_ioc_transfer mcp3008_config[] = {
    SPI_IOC_MESSAGE(1),
    {
        .tx_buf = (unsigned long)&(0x01), // Set CS low
        .rx_buf = NULL,
        .len = 1,
        .delay_usecs = 0,
    },
    { .tx_buf = NULL, .rx_buf = NULL, .len = 0, .delay_usecs = 0 },
};

int main() {
    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = cleanup;
    sigaction(SIGTERM, &term_handler, NULL);

    // Initialize SPI
    if ((spi = spi_open(SPI_DEVICE, SPI_MODE_0)) == NULL) {
        perror("spi_open");
        return EXIT_FAILURE;
    }

    // Open MCP3008
    mcp3008_fd = open("/dev/mcp3008", O_RDWR);
    if (mcp3008_fd == -1) {
        perror("open /dev/mcp3008");
        spi_close(spi);
        return EXIT_FAILURE;
    }

    // Map the MCP3008 memory region
    void *mcp3008_mem = mmap(0, 0x2000, PROT_READ | PROT_WRITE, MAP_SHARED, mcp3008_fd, 0);
    if (mcp3008_mem == MAP_FAILED) {
        perror("mmap MCP3008 memory");
        close(mcp3008_fd);
        spi_close(spi);
        return EXIT_FAILURE;
    }

    // Initialize Kalman filter
    kalman_init(kalman_state, KF_STATE_SIZE, kalman_covariance, KF_STATE_SIZE, KF);

    // Main loop
    while (1) {
        // Read MCP3008 configuration register to check CS
        struct spi_ioc_transfer transfer = {
            .tx_buf = (unsigned long)&(0x06), // Read configuration register
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
        };
        if (spi_transfer(spi, mcp3008_config, 1, &transfer, spi_transfer_buffer, 1) < 1) {
            perror("SPI transfer error");
            continue;
        }
        if (transfer.status == 0) {
            // CS is high, sensor not connected or failed
            printf("Sensor not detected or failed.\n");
            continue;
        }

        // Read ADC values
        for (int channel = ADXL335_XOUT; channel <= ADXL335_ZOUT; channel++) {
            struct spi_ioc_transfer adc_transfer = {
                .tx_buf = (unsigned long)&channel, // Select channel
                .rx_buf = spi_transfer_buffer,
                .len = 1,
                .delay_usecs = 0,
            };
            if (spi_transfer(spi, mcp3008_config, 1, &adc_transfer, spi_transfer_buffer, 1) < 1) {
                perror("ADC read error");
                continue;
            }

            uint16_t adc_value = (spi_transfer_buffer[0] << 8) | spi_transfer_buffer[1];
            adc_value /= (REFERENCE_VOLTAGE / 1024.0); // Convert to volts

            // Apply Kalman filter
            double prediction = kalman_predict(kalman_state, kalman_covariance);
            double measurement = prediction + (adc_value * KF);
            double kalman_gain = kalman_update(kalman_state, kalman_covariance, measurement);

            // Print smoothed acceleration in g
            printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", kalman_gain[0], kalman_gain[1], kalman_gain[2]);
        }

        usleep(100000); // 10 Hz sampling rate
    }

    // Cleanup
    printf("Exiting...\n");
    // Close resources
    close(mcp3008_fd);
    spi_close(spi);
    munmap(mcp3008_mem, 0x2000);

    return EXIT_SUCCESS;
}

// Helper function to perform SPI transactions
int spi_transfer(struct spi_device *spi, const struct spi_ioc_transfer *tx_buf, int tx_count, struct spi_ioc_transfer *rx_buf, uint8_t *rx_data, int rx_count) {
    int total_transfers = tx_count + rx_count;
    int transferred = 0;

    for (int i = 0; i < total_transfers; i++) {
        struct spi_ioc_transfer *transfer = &tx_buf[i] ? &tx_buf[i] : rx_buf[i];
        if (transfer->len == 0) {
            continue;
        }

        if (spi_transfer(spi, &transfer->tx_buf[transfer->len], 1, &transfer, transfer->rx_buf, transfer->len) < 1) {
            return -1;
        }

        if (transfer->len) {
            transferred += transfer->len;
        }

        if (rx_data) {
            rx_data[transferred] = transfer->rx_buf[0];
            transferred++;
        }
    }

    return transferred;
}

// Kalman filter functions (definitions only, actual implementation omitted for brevity)
