#include <gpiod.h>

#define SENSOR_1_GPIO_NUM 4
#define SENSOR_2_GPIO_NUM 17
#define SENSOR_3_GPIO_NUM 27

#define GPIO_MAX_VALUE 1023
#define MAGNETIC_FIELD_MAX 100.0
#define MAGNETIC_FIELD_MIN -100.0

FILE *magnetic_log_file;

void setup_gpios(void) {
    int sensor1_ret, sensor2_ret, sensor3_ret;
    struct gpiod_dir *sensor1_dir, *sensor2_dir, *sensor3_dir;

    sensor1_dir = gpiod_open(SENSOR_1_GPIO_NUM, GPIOD_DIR_IN);
    sensor2_dir = gpiod_open(SENSOR_2_GPIO_NUM, GPIOD_DIR_IN);
    sensor3_dir = gpiod_open(SENSOR_3_GPIO_NUM, GPIOD_DIR_IN);

    if (sensor1_dir == NULL || sensor2_dir == NULL || sensor3_dir == NULL) {
        fprintf(stderr, "Error opening GPIO pins for sensors.\n");
        exit(EXIT_FAILURE);
    }

    sensor1_ret = gpiod_direction_input(sensor1_dir);
    sensor2_ret = gpiod_direction_input(sensor2_dir);
    sensor3_ret = gpiod_direction_input(sensor3_dir);

    if (sensor1_ret != 0 || sensor2_ret != 0 || sensor3_ret != 0) {
        fprintf(stderr, "Error setting GPIO pins to input mode.\n");
        gpiod_close(sensor1_dir);
        gpiod_close(sensor2_dir);
        gpiod_close(sensor3_dir);
        exit(EXIT_FAILURE);
    }

    magnetic_log_file = fopen("magnetic_log.txt", "a+");
    if (magnetic_log_file == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing.\n");
        gpiod_close(sensor1_dir);
        gpiod_close(sensor2_dir);
        gpiod_close(sensor3_dir);
        exit(EXIT_FAILURE);
    }
}

void read_sensors_and_log(void) {
    int sensor1_value, sensor2_value, sensor3_value;
    struct gpiod_value_read *sensor1_read, *sensor2_read, *sensor3_read;

    sensor1_read = gpiod_get_value(sensor1_dir);
    sensor2_read = gpiod_get_value(sensor2_dir);
    sensor3_read = gpiod_get_value(sensor3_dir);

    sensor1_value = sensor1_read->val;
    sensor2_value = sensor2_read->val;
    sensor3_value = sensor3_read->val;

    if (sensor1_value > GPIO_MAX_VALUE || sensor1_value < 0) {
        fprintf(stderr, "Sensor 1 value out of range: %d\n", sensor1_value);
        return;
    }

    if (sensor2_value > GPIO_MAX_VALUE || sensor2_value < 0) {
        fprintf(stderr, "Sensor 2 value out of range: %d\n", sensor2_value);
        return;
    }

    if (sensor3_value > GPIO_MAX_VALUE || sensor3_value < 0) {
        fprintf(stderr, "Sensor 3 value out of range: %d\n", sensor3_value);
        return;
    }

    float sensor1_mT = (float) sensor1_value / GPIO_MAX_VALUE * MAGNETIC_FIELD_MAX;
    float sensor2_mT = (float) sensor2_value / GPIO_MAX_VALUE * MAGNETIC_FIELD_MAX;
    float sensor3_mT = (float) sensor3_value / GPIO_MAX_VALUE * MAGNETIC_FIELD_MAX;

    if (sensor1_mT < MAGNETIC_FIELD_MIN || sensor1_mT > MAGNETIC_FIELD_MAX) {
        fprintf(stderr, "Sensor 1 magnetic field out of range: %.2f mT\n", sensor1_mT);
        return;
    }

    if (sensor2_mT < MAGNETIC_FIELD_MIN || sensor2_mT > MAGNETIC_FIELD_MAX) {
        fprintf(stderr, "Sensor 2 magnetic field out of range: %.2f mT\n", sensor2_mT);
        return;
    }

    if (sensor3_mT < MAGNETIC_FIELD_MIN || sensor3_mT > MAGNETIC_FIELD_MAX) {
        fprintf(stderr, "Sensor 3 magnetic field out of range: %.2f mT\n", sensor3_mT);
        return;
    }

    char log_line[256];
    sprintf(log_line, "sensor1_mT,sensor2_mT,sensor3_mT,%f,%f,%f", sensor1_mT, sensor2_mT, sensor3_mT);
    fprintf(magnetic_log_file, "%s\n", log_line);
    fflush(magnetic_log_file);
}

void cleanup_and_exit(int sig) {
    if (magnetic_log_file != NULL) {
        fclose(magnetic_log_file);
        magnetic_log_file = NULL;
    }

    gpiod_close(sensor1_dir);
    gpiod_close(sensor2_dir);
    gpiod_close(sensor3_dir);

    printf("Exiting due to SIGINT.\n");
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, cleanup_and_exit);

    setup_gpios();

    while (1) {
        read_sensors_and_log();
        usleep(100000); // Sleep for 100 milliseconds
    }

    return 0;
}

