#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define MCP3008_ADDR 0x68
#define SPI_CLOCK_FREQ 500000
#define SPI_MODE 0
#define ADC_CHANNEL 0

#define PUMP_GPIO 17
#define PUMP_ON_THRESHOLD 30

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO and SPI
    int pump_fd = gpiod_open(PUMP_GPIO, GPIO_OUTPUT);
    if (pump_fd < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", PUMP_GPIO, strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_direction_output(pump_fd, 1); // Set GPIO17 to active high

    int spi_fd = gpiod_open(SPI_DEVICE_NAME, GPIOD_OPEN_FLAG_NO_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_close(pump_fd);
        return EXIT_FAILURE;
    }

    // Configure SPI
    struct spi_config spi_config = {
        .speed_hz = SPI_CLOCK_FREQ,
        .bits_per_word = 8,
        .cs_change = 0,
        .max_speed_hz = SPI_CLOCK_FREQ,
        .mode = SPI_MODE,
    };

    if (libgpiod_spi_setup(spi_fd, MCP3008_ADDR, &spi_config) < 0) {
        fprintf(stderr, "Error configuring SPI for MCP3008: %s\n", libgpiod_spi_get_error(spi_fd));
        gpiod_close(spi_fd);
        gpiod_close(pump_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for pump control
    gpiod_set_direction(pump_fd, GPIO_OUTPUT);

    // File descriptor for logging
    int log_fd = fopen("watering.log", "a+");
    if (log_fd == NULL) {
        fprintf(stderr, "Error opening logging file: %s\n", strerror(errno));
        gpiod_close(spi_fd);
        gpiod_close(pump_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Check for signals
        if (should_exit) {
            fprintf(log_fd, "Program terminated by signal.\n");
            gpiod_set_value(pump_fd, 0); // Turn off pump
            break;
        }

        // Read ADC value
        uint16_t adc_value;
        if (libgpiod_spi_transfer(spi_fd, MCP3008_ADDR, ADC_CHANNEL, 1, &adc_value) < 0) {
            fprintf(log_fd, "Error reading ADC: %s\n", libgpiod_spi_get_error(spi_fd));
            continue;
        }

        float moisture_level = adc_value / 1024.0 * 100.0; // Convert to percentage

        if (moisture_level < PUMP_ON_THRESHOLD) {
            fprintf(log_fd, "Moisture level below threshold, turning on pump.\n");
            gpiod_set_value(pump_fd, 1); // Turn on pump
        } else {
            fprintf(log_fd, "Moisture level above threshold, turning off pump.\n");
            gpiod_set_value(pump_fd, 0); // Turn off pump
        }

        // Log timestamped events
        struct timeval now;
        gettimeofday(&now, NULL);
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &now);
        fprintf(log_fd, "Event: %s\n", buffer);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fprintf(log_fd, "Program terminated.\n");
    fclose(log_fd);
    gpiod_close(spi_fd);
    gpiod_close(pump_fd);

    return EXIT_SUCCESS;
}

