#define MCP3008_DEVICE "/dev/spidev0.0"
#define CHANNELS 3
#define BUFFER_SIZE (CHANNELS * 1)  // 1 byte per channel

// Function prototypes
void handle_signal(int signum);
int open_spi_device();
int setup_mcp3008();
void read_analog_values();
void write_to_csv(const char* filename, const uint8_t* data, size_t size);
void close_spi_and_file_resources();

// Main function
int main() {
    // Install SIGINT handler
    signal(SIGINT, handle_signal);

    // Attempt to open the SPI device
    int spi_fd = open_spi_device();
    if (spi_fd == -1) {
        perror("Error opening SPI device");
        return EXIT_FAILURE;
    }

    // Initialize MCP3008
    if (setup_mcp3008() == -1) {
        perror("Error setting up MCP3008");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read analog values
        read_analog_values();

        // Write to CSV file
        write_to_csv("sensor_data.csv", (const uint8_t*)mcp3008_data, BUFFER_SIZE);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close resources on exit
    close_spi_and_file_resources();

    return EXIT_SUCCESS;
}

// SIGINT handler
void handle_signal(int signum) {
    // Close the SPI device and CSV file
    close_spi_and_file_resources();
    exit(EXIT_FAILURE);
}

// Function to open SPI device
int open_spi_device() {
    int spi_fd = -1;
    char dev_name[10] = "/dev/spidev0.0";

    // Open SPI device
    spi_fd = open(dev_name, O_RDWR);
    if (spi_fd == -1) {
        perror("Error opening SPI device");
        return spi_fd;
    }

    // Check if we can claim exclusive access
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &((uint32_t)1000000)) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

// Function to setup MCP3008
int setup_mcp3008() {
    int ret = 0;
    struct gpiod_dir *mcp3008_dir;
    struct gpiod_cdev *mcp3008_cdev;

    // Find the MCP3008 device
    mcp3008_dir = gpiod_find("MCP3008", GPIOD_ANY_INSTANCE);
    if (!mcp3008_dir) {
        perror("Failed to find MCP3008 device");
        return -1;
    }

    // Open the MCP3008 device
    mcp3008_cdev = gpiod_open(mcp3008_dir);
    if (!mcp3008_cdev) {
        perror("Failed to open MCP3008 device");
        gpiod_remove(mcp3008_dir);
        return -1;
    }

    // Set the channel address
    ret = gpiod_set_value(mcp3008_cdev, 0, 0x0); // Channel 0
    if (ret < 0) {
        perror("Failed to set channel address");
        gpiod_remove(mcp3008_cdev);
        close(spi_fd);
        return -1;
    }

    ret = gpiod_set_value(mcp3008_cdev, 1, 0x1); // Channel 1
    if (ret < 0) {
        perror("Failed to set channel address");
        gpiod_remove(mcp3008_cdev);
        close(spi_fd);
        return -1;
    }

    ret = gpiod_set_value(mcp3008_cdev, 2, 0x2); // Channel 2
    if (ret < 0) {
        perror("Failed to set channel address");
        gpiod_remove(mcp3008_cdev);
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read analog values from MCP3008
void read_analog_values() {
    uint8_t mcp3008_data[CHANNELS];

    // Read data from MCP3008
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(CHANNELS), mcp3008_data) < 0) {
        perror("Error reading from MCP3008");
        exit(EXIT_FAILURE);
    }

    // Store the data for CSV writing
    mcp3008_data[0] = (uint8_t)(mcp3008_data[0] << 6); // Shift to correct format
    mcp3008_data[1] = mcp3008_data[1];
    mcp3008_data[2] = mcp3008_data[2];
}

// Function to write to CSV file
void write_to_csv(const char* filename, const uint8_t* data, size_t size) {
    FILE *file = fopen(filename, "a+");
    if (!file) {
        perror("Error opening CSV file");
        return;
    }

    // Write data to CSV file
    fprintf(file, "%u,%u,%u\n", data[0], data[1], data[2]);

    // Close the file
    fclose(file);
}

// Function to close SPI and file resources
void close_spi_and_file_resources() {
    // Close SPI device
    close(spi_fd);

    // Close CSV file
    fclose(file);
}

