void* gpiod_handle = dlopen(GPIOD_LIB, RTLD_LAZY);
if (!gpiod_handle) {
    fprintf(stderr, "Failed to load libgpiod: %s\n", dlerror());
    exit(EXIT_FAILURE);
}

