#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <mosquitto.h>
#include <json.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT "1883"
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17 // BCM 17 corresponds to physical pin 11

// GPIO descriptor
struct gpiod_device *gpiodev;
gpiod_pin_handle pin_handle;

// MQTT client structure
MosquittoClient *mqtt_client;
MosquittoConnectOptions connect_options;
MosquittoMessage *message;
char *mqtt_topic = MQTT_TOPIC;

// JSON parsing context
json_object *json_obj;
json_error_t error;

// Signal handlers
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Clean shutdown
        gpiod_stop(gpiodev);
        mosquitto_disconnect(mqtt_client, 0);
        mosquitto_free(mqtt_client);
        gpiod_device_free(gpiodev);
        exit(0);
    }
}

int main() {
    // Initialize GPIO
    gpiodev = gpiod_get_by_name("gpiochip0");
    if (!gpiodev) {
        fprintf(stderr, "Failed to get GPIO controller\n");
        return EXIT_FAILURE;
    }

    pin_handle = gpiod_get_pin(gpiodev, GPIO_PIN);
    if (!pin_handle) {
        fprintf(stderr, "Failed to get GPIO pin %u\n", GPIO_PIN);
        gpiod_device_free(gpiodev);
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    connect_options.username_pw_set(MQTT_CLIENT_ID, MQTT_CLIENT_PASSWORD);
    mqtt_client = mosquitto_new();
    if (!mqtt_client) {
        fprintf(stderr, "Failed to create MQTT client\n");
        mosquitto_free(mqtt_client);
        return EXIT_FAILURE;
    }

    // Signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // MQTT connection attempt with exponential backoff
        int attempts = 0;
        do {
            struct timeval backoff_time;
            backoff_time.tv_sec = attempts * 1; // Start at 1 second
            backoff_time.tv_usec = 0;
            gettimeofday(&backoff_time, NULL);

            // Connect to MQTT broker
            if (mosquitto_connect(mqtt_client, MQTT_BROKER, MQTT_PORT, &connect_options) == 0) {
                // Subscribe to the topic
                if (mosquitto_subscribe(mqtt_client, MQTT_TOPIC, 0) == 0) {
                    // Start JSON parsing loop
                    json_obj = json_loads(NULL);
                    while (json_obj) {
                        if (json_obj->type != JSON_OBJECT) {
                            fprintf(stderr, "Invalid JSON payload: expected object\n");
                            json_obj = json_decref(json_obj);
                            continue;
                        }

                        if (json_object_get_int(json_obj, "led_state") == NULL) {
                            fprintf(stderr, "JSON payload missing 'led_state' key\n");
                            json_obj = json_decref(json_obj);
                            continue;
                        }

                        bool led_state = (int)json_object_get_int(json_obj, "led_state") == 1;

                        // Control GPIO based on LED state
                        if (led_state) {
                            gpiod_set_value(pin_handle, GPIOD_DIR_OUT_HIGH);
                        } else {
                            gpiod_set_value(pin_handle, GPIOD_DIR_OUT_LOW);
                        }

                        // Free JSON object
                        json_obj = json_decref(json_obj);
                    }

                    // Reset JSON parsing context
                    json_obj = NULL;
                } else {
