#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define ALARM_GPIO 18
#define SOUND_SENSOR_GPIO 17
#define DELAY_MS 100

volatile sig_atomic_t should_exit = 0;

void alarm_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO driver
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing GPIO driver\n");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    if (gpiod_open(GPIOD_ANY_ID) < 0) {
        fprintf(stderr, "Error opening GPIO chip\n");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    if (gpiod_request(GPIOD_OUT_INIT_LOW, ALARM_GPIO) < 0 ||
        gpiod_request(GPIOD_IN, SOUND_SENSOR_GPIO) < 0) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set alarm GPIO as output
    if (gpiod_direction_output(ALARM_GPIO, 1) < 0) {
        fprintf(stderr, "Error setting alarm GPIO as output\n");
        gpiod_unrequest(ALARM_GPIO);
        gpiod_unrequest(SOUND_SENSOR_GPIO);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read sound sensor
        int sound_detected = gpiod_read(SOUND_SENSOR_GPIO);
        if (sound_detected == 0) {
            printf("Sound detected: LOW\n");
            // Trigger alarm
            gpiod_set_value(ALARM_GPIO, 1);
            sleep(1);
            gpiod_set_value(ALARM_GPIO, 0);
            printf("Alarm triggered\n");
        } else {
            printf("Sound detected: HIGH\n");
        }

        // Delay
        sleep(DELAY_MS);
    }

    // Clean up GPIO resources
    gpiod_unrequest(ALARM_GPIO);
    gpiod_unrequest(SOUND_SENSOR_GPIO);
    gpiod_cleanup();

    // Exit on Ctrl+C or SIGTERM
    struct sigaction sa;
    sa.sa_handler = alarm_handler;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return EXIT_SUCCESS;
}

