volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handle_signal(int signum);
void setup_vibration_monitor();
void teardown_vibration_monitor();
void log_event(const char *message);
void shutdown_raspberry_pi();

// Main function
int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIO and log file
    setup_vibration_monitor();

    // Main loop
    while (!should_exit) {
        // Wait for a falling edge event
        gpiod_eventfd_read(gpiod_get_fd("/dev/gpiochip0", GPIOD_OPEN_BY_NAME), "vibration-monitor", GPIODedge_FALLING, NULL);

        // Check if an event occurred
        if (gpiod_eventfd_read(gpiod_get_fd("/dev/gpiochip0", GPIOD_OPEN_BY_NAME), "vibration-monitor", GPIODedge_NONE, NULL) != 0) {
            perror("gpiod_eventfd_read");
            continue;
        }

        // Log the event and initiate shutdown
        log_event("Vibration detected at: " __TIME__);
        shutdown_raspberry_pi();

        // Check if shutdown command was successful
        if (system("sudo shutdown -h now") != 0) {
            perror("shutdown -h now");
        }
    }

    // Tear down GPIO and log file
    teardown_vibration_monitor();

    return 0;
}

// Signal handler to set the exit flag
void handle_signal(int signum) {
    should_exit = 1;
}

// Function to setup vibration monitor and log file
void setup_vibration_monitor() {
    // Open /dev/gpiochip0
    int gpiochip_fd = open("/dev/gpiochip0", O_RDONLY);
    if (gpiochip_fd == -1) {
        perror("open /dev/gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line with the consumer label "vibration-monitor"
    struct gpiod_cconsumer cconsumer;
    memset(&ccconsumer, 0, sizeof(ccconsumer));
    cconsumer.consumer_name = "vibration-monitor";
    if (gpiod_cconsumer_request(gpiochip_fd, &ccconsumer) == -1) {
        perror("gpiod_cconsumer_request");
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Obtain the GPIO line
    struct gpiod_line line;
    if (gpiod_line_request(gpiochip_fd, &ccconsumer, &line) == -1) {
        perror("gpiod_line_request");
        gpiod_cconsumer_release(gpiochip_fd, &ccconsumer);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Configure the line for falling-edge detection
    if (gpiod_line_config(gpiochip_fd, &line, GPIODedge_FALLING, 0) == -1) {
        perror("gpiod_line_config");
        gpiod_line_release(gpiochip_fd, &line);
        gpiod_cconsumer_release(gpiochip_fd, &ccconsumer);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file for appending
    char log_path[256] = "/var/log/vibration_shutdown.log";
    int log_file_fd = open(log_path, O_APPEND | O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (log_file_fd == -1) {
        perror("open log file");
        close(gpiochip_fd);
        gpiod_line_release(gpiochip_fd, &line);
        gpiod_cconsumer_release(gpiochip_fd, &ccconsumer);
        exit(EXIT_FAILURE);
    }

    // Ensure the log file is writable
    if (fchmod(log_file_fd, S_IRUSR | S_IWUSR) == -1) {
        perror("fchmod");
        close(log_file_fd);
        close(gpiochip_fd);
        gpiod_line_release(gpiochip_fd, &line);
        gpiod_cconsumer_release(gpiochip_fd, &ccconsumer);
        exit(EXIT_FAILURE);
    }
}

// Function to teardown vibration monitor and log file
void teardown_vibration_monitor() {
    // Release the GPIO line
    gpiod_line_release(gpiochip_fd, &line);

    // Release the consumer
    gpiod_cconsumer_release(gpiochip_fd, &ccconsumer);

    // Close the GPIO chip
    close(gpiochip_fd);

    // Close the log file
    close(log_file_fd);
}

// Function to log an event with timestamp
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm tm_now;
    localtime_r(&now, &tm_now);

    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", &tm_now);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);

    // Write to the log file
    if (write(log_file_fd, log_message, strlen(log_message)) != strlen(log_message)) {
        perror("write to log file");
    }
}

// Function to initiate a system shutdown
void shutdown_raspberry_pi() {
    // Invoke shutdown command
    system("sudo shutdown -h now");
}

