int main() {
    struct spi_device *spi_dev;
    int spi_fd;
    int ret;
    float temp;
    uint8_t data[1];

    // Initialize GPIO for CE0
    if (gpiod_direction_output(GPIOD_PIN_MCP3008_CS, 0) != 0) {
        fprintf(stderr, "Error setting CE0 pin as output\n");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, &cleanup_spi_and_exit);
    signal(SIGTERM, &cleanup_spi_and_exit);

    while (1) {
        // Read temperature every 5 seconds
        struct timespec timeout = { .tv_sec = 5, .tv_nsec = 0 };
        ret = nanosleep(&timeout, NULL);

        if (ret == -1) {
            fprintf(stderr, "Error during nanosleep\n");
            continue;
        }

        // Initialize SPI device
        if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) == -1) {
            fprintf(stderr, "Error opening SPI device\n");
            continue;
        }

        if (gpiod_is_valid_device("/dev/spidev0.0") == 0) {
            fprintf(stderr, "Error: SPI device not valid\n");
            close(spi_fd);
            continue;
        }

        if (gpiod_add_device(spi_fd) != 0) {
            fprintf(stderr, "Error adding SPI device\n");
            close(spi_fd);
            continue;
        }

        // Initialize MCP3008
        if (gpiod_write(spi_fd, MCP3008_SCLK, GPIOD_OUT_HIGH) != 0 ||
            gpiod_write(spi_fd, MCP3008_MISO, GPIOD_IN_FLOATING) != 0 ||
            gpiod_write(spi_fd, MCP3008_MOSI, GPIOD_OUT_HIGH) != 0 ||
            gpiod_write(spi_fd, MCP3008_CS, GPIOD_OUT_LOW) != 0) {
            fprintf(stderr, "Error initializing MCP3008\n");
            close(spi_fd);
            continue;
        }

        // Read temperature
        gpiod_write(spi_fd, MCP3008_CS, GPIOD_OUT_HIGH);
        ret = gpiod_read(spi_fd, MCP3008_MISO, data, 1);

        if (ret != 1) {
            fprintf(stderr, "Error reading from MCP3008\n");
            continue;
        }

        temp = *(float *)data * 500.0 / 1024.0; // Convert 10-bit ADC value to Celsius

        // Print temperature
        printf("Temperature: %.2f °C\n", temp);

        // Store temperature in circular buffer
        buffer[BUFFER_SIZE - 1] = temp;

        // Check if buffer wrap-around is needed
        if (BUFFER_SIZE == 1) {
            // Overwrite the oldest entry
            buffer[0] = temp;
        }

        // Write buffer to file
        if ((spi_fd_log = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR)) == -1) {
            fprintf(stderr, "Error opening file for logging: %s\n", strerror(errno));
            continue;
        }

        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (write(spi_fd_log, &buffer[i], sizeof(float)) != sizeof(float)) {
                fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
                close(spi_fd_log);
                break;
            }
        }

        close(spi_fd_log);
    }

    return 0;
}

// Circular buffer for temperature readings
float buffer[BUFFER_SIZE];

