#define TMP36_OFFSET 460 // TMP36 offset voltage in mV
#define TMP36_SLOPE  3930 // TMP36 slope in mV/°C

#define MCP4725_ADDR 0x48 // Default address
#define MCP4725_WRITE_ENABLE 0x00 // Write enable command

#define SPI_SPEED 500000 // SPI clock speed in Hz

void spi_init(uint8_t cs) {
    // Set SPI clock speed
    bcm2835_spi_set_clock(SPI_SPEED);

    // Set SPI mode
    bcm2835_spi_set_mode(SPI_MODE);

    // Set chip select pin
    bcm2835_spi_set_cs_pin(cs);

    // Initialize SPI
    if (bcm2835_spi_init() < 0) {
        perror("SPI initialization failed");
        exit(EXIT_FAILURE);
    }
