    // Close SPI and I2C interfaces
    spi_deinit();
    i2c_deinit();

    // Close log file
    fclose(log_file);

    // Terminate driver resources (if applicable)
    // Note: Direct SPI/I2C access does not require explicit termination

    printf("SIGINT received. Exiting...\n");
    exit(EXIT_SUCCESS);
}

