    int ret;

    // Initialize SPI device
    ret = gpiod_open(&gpiod_spi_device, GPIOD_OPEN_MODE_MASTER);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", gpiod_error_string(ret));
        return -1;
    }

    // Set the clock speed
    ret = gpiod_set_speed(gpiod_spi_device, SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI clock speed: %s\n", gpiod_error_string(ret));
        gpiod_close(gpiod_spi_device);
        return -1;
    }

    // Set CE0 pin as output
    ret = gpiod_direction_output(CE0_GPIO_NUM, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure CE0 pin: %s\n", gpiod_error_string(ret));
        gpiod_close(gpiod_spi_device);
        return -1;
    }

    // Open SPI device file
