    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_close(gpiod_spi_device);
        return -1;
    }

    return 0;
}

// Function to send data over SPI
int spi_transfer(uint8_t data) {
