// Function prototypes
void setup_relay(int pin);
void teardown_relay(int pin);
void handle_signal(int signum);

// Global variables
gpiod_device *gpiod;
int relay_pins[] = {17, 22, 23, 24};

// Main function
int main(void) {
    // Initialize libgpiod
    gpiod = gpiod_open(GPIOD_DIR_DEV, "gpiochip0");
    if (gpiod == NULL) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", gpiod_errstr(gpiod));
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup relay pins
    for (int i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); i++) {
        setup_relay(relay_pins[i]);
    }

    // Main loop
    while (1) {
        // Activate and deactivate each relay in sequence
        for (int i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); i++) {
            gpiod_set_value(gpiod, relay_pins[i], GPIOD_VALUE_HIGH);
            sleep(1);

            gpiod_set_value(gpiod, relay_pins[i], GPIOD_VALUE_LOW);
            sleep(1);
        }
    }

    // Teardown relay pins on exit
    for (int i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); i++) {
        teardown_relay(relay_pins[i]);
    }

    // Close the GPIO device
    gpiod_close(gpiod);

    return EXIT_SUCCESS;
}

// Function to setup a relay pin
void setup_relay(int pin) {
    if (gpiod_is_valid_pin(gpiod, pin)) {
        gpiod_direction_output(gpiod, pin, 1); // Set pin as output
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", pin);
        exit(EXIT_FAILURE);
    }
}

// Function to teardown a relay pin
void teardown_relay(int pin) {
    gpiod_set_value(gpiod, pin, GPIOD_VALUE_LOW); // Ensure the pin is low
    gpiod_direction_input(gpiod, pin); // Set pin as input
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Deactivate all relays on receiving SIGINT or SIGTERM
    for (int i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); i++) {
        teardown_relay(relay_pins[i]);
    }

    // Clean exit
    exit(EXIT_SUCCESS);
}

