#define SPI_DEVICE "/dev/spidev0.0" // Assuming SPI is on SPI0.0
#define ADC_CHANNEL 0
#define THRESHOLD_VALUE 512
#define LED_GPIO 16
#define DEBOUNCE_DELAY_MS 100 // Debounce delay in milliseconds

// Function prototypes
void spi_setup();
int read_adc_value(int channel);
void handle_spi_error(const char *operation);
void handle_gpio_error(const char *operation);
void debounce();
void log_event(const char *message, time_t timestamp);
void cleanup();

int main() {
    // Initialize GPIO and SPI
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_get_name(gpiod_get_error()));
        handle_gpio_error("gpiod_init");
        return EXIT_FAILURE;
    }

    if (spidev_open(SPI_DEVICE, 0) == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", spidev_errstr(SPIDEV_ERR));
        handle_spi_error("spidev_open");
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up GPIO for LED
    if (gpiod_direction_output(LED_GPIO, 1) == -1) {
        fprintf(stderr, "Error setting LED GPIO: %s\n", gpiod_get_name(gpiod_get_error()));
        handle_gpio_error("gpiod_direction_output");
        spidev_close(SPI_DEVICE);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up SPI for MCP3008
    spi_setup();

    // Main loop
    while (1) {
        // Sample ADC
        int adc_value = read_adc_value(ADC_CHANNEL);

        // Check if value exceeds threshold
        if (adc_value > THRESHOLD_VALUE) {
            debounce();
            if (adc_value > THRESHOLD_VALUE) {
                log_event("Sound threshold exceeded at: ", time(NULL));
                // Turn on LED
                gpiod_set_value(LED_GPIO, 1);
                sleep(500); // Keep LED on for 500ms
                gpiod_set_value(LED_GPIO, 0); // Turn off LED
                sleep(DEBOUNCE_DELAY_MS); // Apply debounce delay
            }
        }
    }

    // Clean up on SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop continues indefinitely
    while (1) {
        // Placeholder for other tasks
        sleep(1); // Simulate other tasks
    }

    return 0;
}

// Function to set up SPI for MCP3008
void spi_setup() {
    int spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", spidev_errstr(SPIDEV_ERR));
        handle_spi_error("spidev_open");
        return;
    }

    struct spi_ioc_transfer transfers[] = {
        // Transfer settings for MCP3008
        {
            .tx_buf = (unsigned char *)&ADC_CHANNEL, // Transfer command
            .rx_buf = NULL, // No receive buffer needed
            .len = sizeof(unsigned char),
            .delay_usecs = 0,
            .speed_hz = 1000000, // 1 MHz
            .mode = SPI_MODE_0,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
        // Read data from MCP3008
        {
            .tx_buf = NULL, // No transmit buffer
            .rx_buf = (unsigned char *)&ADC_VALUE, // Receive buffer for data
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .mode = SPI_MODE_0,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
    };

    int ntransfers = sizeof(transfers) / sizeof(transfers[0]);

    if (spidev_transfer(spi_fd, transfers, ntransfers) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        handle_spi_error("spidev_transfer");
        spidev_close(spi_fd);
        return;
    }
}

// Function to read ADC value from MCP3008
int read_adc_value(int channel) {
    // Set the ADC channel
    gpiod_set_value(GPIO_CE0, 0); // Set CE0 low to select MCP3008

    // Perform SPI transfer to read ADC value
    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL, // No transmit buffer
        .rx_buf = (unsigned char *)&channel, // Receive buffer for command
        .len = sizeof(unsigned char),
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .mode = SPI_MODE_0,
        .cs_change = 1,
        .cs_low_for_trans = 1,
    };

    int spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", spidev_errstr(SPIDEV_ERR));
        return -1;
    }

    if (spidev_transfer(spi_fd, &transfer, 1) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        spidev_close(spi_fd);
        return -1;
    }

    // Read the actual ADC value
    struct spi_ioc_transfer adc_transfer = {
        .tx_buf = NULL, // No transmit buffer
        .rx_buf = (unsigned char *)&ADC_VALUE, // Receive buffer for data
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .mode = SPI_MODE_0,
        .cs_change = 1,
        .cs_low_for_trans = 1,
    };

    if (spidev_transfer(spi_fd, &adc_transfer, 1) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        spidev_close(spi_fd);
        return -1;
    }

    return ADC_VALUE; // Return the read ADC value
}

// Handle SPI transfer errors
void handle_spi_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, spidev_errstr(spidev_transferred(-1)));
}

// Handle GPIO operation errors
void handle_gpio_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, gpiod_get_name(gpiod_get_error()));
}

// Debounce function to prevent multiple triggers from a single event
void debounce() {
    static time_t last_trigger = time(NULL);
    static int debounce_count = 0;

    if (time(NULL) - last_trigger >= (DEBOUNCE_DELAY_MS * 1000)) {
        debounce_count = 0;
        last_trigger = time(NULL);
    }

    if (debounce_count++ < 5) {
        sleep(1); // Wait for a short period
    } else {
        // Debounce triggered, reset count
        debounce_count = 0;
    }
}

// Function to log an event with timestamp
void log_event(const char *message, time_t timestamp) {
    char log_file[256];
    snprintf(log_file, sizeof(log_file), "sound_events.log");

    FILE *log_file_ptr = fopen(log_file, "a+");
    if (!log_file_ptr) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file);
        return;
    }

    fprintf(log_file_ptr, "%s at %s\n", message, ctime(&timestamp));
    fclose(log_file_ptr);
}

// Function to clean up resources on SIGINT
void cleanup() {
    // Close SPI device
    spidev_close(SPI_DEVICE);

    // Uninitialize GPIO
    gpiod_exit();

    // Turn off LED
    gpiod_set_value(LED_GPIO, 0);
}

// Placeholder for ADC value read from MCP3008
unsigned char ADC_VALUE;

// Ensure ADC_VALUE is not used uninitialized
static_assert(sizeof(ADC_VALUE) == 1, "ADC_VALUE size must be 1 byte");

