        // Read data from MCP3008
        {
            .tx_buf = NULL, // No transmit buffer
            .rx_buf = (unsigned char *)&ADC_VALUE, // Receive buffer for data
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .mode = SPI_MODE_0,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
    };

    int ntransfers = sizeof(transfers) / sizeof(transfers[0]);

    if (spidev_transfer(spi_fd, transfers, ntransfers) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        handle_spi_error("spidev_transfer");
