// Function to read ADC value from MCP3008
int read_adc_value(int channel) {
    // Set the ADC channel
    gpiod_set_value(GPIO_CE0, 0); // Set CE0 low to select MCP3008

    // Perform SPI transfer to read ADC value
    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL, // No transmit buffer
        .rx_buf = (unsigned char *)&channel, // Receive buffer for command
        .len = sizeof(unsigned char),
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .mode = SPI_MODE_0,
        .cs_change = 1,
        .cs_low_for_trans = 1,
    };

    int spi_fd = spidev_open(SPI_DEVICE, 0);
    if (spi_fd == -1) {
        fprintf(stderr, "Error opening SPI device: %s\n", spidev_errstr(SPIDEV_ERR));
        return -1;
    }

    if (spidev_transfer(spi_fd, &transfer, 1) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        spidev_close(spi_fd);
        return -1;
    }

    // Read the actual ADC value
    struct spi_ioc_transfer adc_transfer = {
        .tx_buf = NULL, // No transmit buffer
        .rx_buf = (unsigned char *)&ADC_VALUE, // Receive buffer for data
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .mode = SPI_MODE_0,
        .cs_change = 1,
        .cs_low_for_trans = 1,
    };

    if (spidev_transfer(spi_fd, &adc_transfer, 1) == -1) {
        fprintf(stderr, "Error during SPI transfer: %s\n", spidev_errstr(spidev_transferred(spi_fd)));
        spidev_close(spi_fd);
        return -1;
    }

    return ADC_VALUE; // Return the read ADC value
