void handle_spi_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, spidev_errstr(spidev_transferred(-1)));
}

// Handle GPIO operation errors
void handle_gpio_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, gpiod_get_name(gpiod_get_error()));
}

// Debounce function to prevent multiple triggers from a single event
void debounce() {
    static time_t last_trigger = time(NULL);
    static int debounce_count = 0;

    if (time(NULL) - last_trigger >= (DEBOUNCE_DELAY_MS * 1000)) {
        debounce_count = 0;
        last_trigger = time(NULL);
    }

    if (debounce_count++ < 5) {
        sleep(1); // Wait for a short period
    } else {
        // Debounce triggered, reset count
        debounce_count = 0;
    }
}

// Function to log an event with timestamp
void log_event(const char *message, time_t timestamp) {
    char log_file[256];
    snprintf(log_file, sizeof(log_file), "sound_events.log");

    FILE *log_file_ptr = fopen(log_file, "a+");
    if (!log_file_ptr) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file);
        return;
    }

    fprintf(log_file_ptr, "%s at %s\n", message, ctime(&timestamp));
    fclose(log_file_ptr);
}

