#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0" // Assuming SPI is on SPI0.0
#define ADC_CHANNEL 0
#define RELAY_GPIO 17 // BCM 17 corresponds to GPIO17
#define THRESHOLD_PERCENT 30 // Threshold for moisture level

// MCP3008 configuration
#define MCP3008_ADDR 0x68

// GPIO setup
#define CE_GPIO 11 // GPIO11 for CE0
#define SCLK_GPIO 10 // GPIO10 for SCLK
#define MOSI_GPIO 9  // GPIO9 for MOSI

// Function prototypes
void spi_init();
int adc_read(uint8_t channel);
void relay_control(bool state);
void log_message(const char *msg);
void cleanup();

int main() {
    // Initialize SPI and ADC
    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO for CE, SCLK, MOSI
    if (gpiod_direction_output(GPIOD_ID_CE_GPIO, 1) < 0 ||
        gpiod_direction_output(GPIOD_ID_SCLK_GPIO, 1) < 0 ||
        gpiod_direction_output(GPIOD_ID_MOSI_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to configure GPIO pins.\n");
        return EXIT_FAILURE;
    }

    // Open log file for appending
    const char *log_file = "soil_moisture.log";
    int log_fd = open(log_file, O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Sample moisture every 60 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        if ((ts.tv_sec - last_sample_time.tv_sec) * 1000 + (ts.tv_nsec - last_sample_time.tv_nsec) / 1000000 >= 60) {
            last_sample_time = ts;
            uint16_t adc_value = adc_read(ADC_CHANNEL);
            float moisture_percentage = adc_value / 1024.0 * 100.0;
            bool pump_state = moisture_percentage < THRESHOLD_PERCENT;

            log_message("Timestamp: %s Moisture: %.1f%% Pump: %s", ctime(&ts.tv_sec), moisture_percentage, pump_state ? "ON" : "OFF");

            // Control relay based on moisture level
            relay_control(pump_state);

            // Close log file and release GPIO on SIGINT
            atexit(cleanup);
        }
    }

    return EXIT_SUCCESS;
}

// Function to initialize SPI
void spi_init() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", SPI_DEVICE);
        return;
    }

    struct spi_ioc_transfer transfers[] = {
        // Transfer to select CE0
        {
            .tx_buf = (unsigned char[]) { 0x01 }, // Select CE0
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000, // 1 MHz
            .bits_per_word = 8,
            .mode = SPI_MODE_0,
        },
        // Actual ADC read transfer
        {
            .tx_buf = (unsigned char[]) { MCP3008_ADDR, 0x01 }, // Select MCP3008, Single-ended mode
            .rx_buf = (unsigned char *) &adc_value,
            .len = 1,
            .delay_usecs = 50,
            .speed_hz = 100000, // 100 kHz
            .bits_per_word = 10, // 10 bits
            .mode = SPI_MODE_0,
        },
        // Transfer to deselect CE
        {
            .tx_buf = (unsigned char[]) { 0x00 }, // Deselect CE
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000, // 1 MHz
            .bits_per_word = 8,
            .mode = SPI_MODE_0,
        },
    };

    int ret = spi_write(spi_fd, transfers, ARRAY_SIZE(transfers));
    if (ret != ARRAY_SIZE(transfers)) {
        fprintf(stderr, "SPI transfer failed.\n");
        close(spi_fd);
        return;
    }
}

// Function to read ADC value
int adc_read(uint8_t channel) {
    // Set the channel and perform the read
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned char[]) { MCP3008_ADDR, 0x80 | channel }, // Set channel and start conversion
        .rx_buf = (unsigned char *) &adc_value,
        .len = 1,
        .delay_usecs = 50,
        .speed_hz = 100000, // 100 kHz
        .bits_per_word = 10, // 10 bits
        .mode = SPI_MODE_0,
    };

    int ret = spi_write(SPI_DEVICE, &transfer, 1);
    if (ret != 1) {
        fprintf(stderr, "ADC read failed.\n");
        return -1;
    }

    return adc_value; // Return the ADC value
}

// Function to control the relay
void relay_control(bool state) {
    if (gpiod_is_valid(GPIOD_ID_RELAY_GPIO)) {
        if (state) {
            gpiod_set_value(GPIOD_ID_RELAY_GPIO, 1);
        } else {
            gpiod_set_value(GPIOD_ID_RELAY_GPIO, 0);
        }
    } else {
        fprintf(stderr, "Relay GPIO not valid.\n");
    }
}

// Function to log a message
void log_message(const char *msg) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &time(NULL));
    fprintf(log_fd, "%s: %s\n", buffer, msg);
}

// Function to perform cleanup on SIGINT
void cleanup() {
    // Turn off the pump
    relay_control(false);

    // Close the log file
    close(log_fd);

    // Release all GPIO resources
    gpiod_set_value(GPIOD_ID_CE_GPIO, 0);
    gpiod_set_value(GPIOD_ID_SCLK_GPIO, 0);
    gpiod_set_value(GPIOD_ID_MOSI_GPIO, 0);

    // Close SPI device
    close(SPI_DEVICE);
}

