#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_MAX_TRANSFER_SIZE 256

#define MCP3008_DOUT_GPIO 10
#define MCP3008_DIN_GPIO 9
#define MCP3008_CLK_GPIO 11
#define MCP3008_CS_GPIO 8

#define DRV5055_VOUT_ADC_CHANNEL 0

#define LOG_FILE "magnetic_log.txt"

volatile sig_atomic_t should_exit = 0;

void cleanup_resources(void) {
    if (fd_spi) {
        close(fd_spi);
        fd_spi = -1;
    }
    if (fd_log) {
        fclose(fd_log);
        fd_log = -1;
    }
    gpio_free(GPIOD, MCP3008_DOUT_GPIO);
    gpio_free(GPIOD, MCP3008_DIN_GPIO);
    gpio_free(GPIOD, MCP3008_CLK_GPIO);
    gpio_free(GPIOD, MCP3008_CS_GPIO);
}

void handle_signal(int signum) {
    should_exit = 1;
}

int main(void) {
    struct spi_device_id spi_ids[] = {
        SPI_DEVICE,
        { .modalias = NULL }
    };

    int fd_spi;
    struct spi_board_info spi_info;
    spi_info.mode = SPI_MODE;
    spi_info.max_speed_hz = SPI_SPEED;
    spi_info.bus_num = 0;
    spi_info.chip_select = 0;
    spi_info.cs_change = 0;
    spi_info.cs_high = 0;
    spi_info.mode_flags = SPI_MODE;

    if (ioctl(fd_spi, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd_spi, 0) == MAP_FAILED) {
        perror("mmap");
        return EXIT_FAILURE;
    }

    spi_info.controller_data = (void *)SPI_DEVICE;
    if (spi_register_board_info(&spi_info, sizeof(spi_ids)) < 0) {
        perror("spi_register_board_info");
        return EXIT_FAILURE;
    }

    fd_log = fopen(LOG_FILE, "a+");
    if (fd_log == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        uint8_t adc_data;
        int ret;

        ret = spi_write_read(fd_spi, 0x00, 1, &adc_data);
        if (ret < 0) {
            fprintf(stderr, "Error reading from MCP3008: %s\n", strerror(errno));
            continue;
        }

        // Convert raw ADC value to magnetic field strength
        int magnetic_field_strength = (adc_data * 3.3 / 1024.0);

        // Format and print to log file
        char timestamp[23];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", localtime(&now));
        char line[256];
        sprintf(line, "%s,%f", timestamp, magnetic_field_strength * 1000.0); // Convert to mT with two decimals

        fprintf(fd_log, "%s\n", line);

        // Release GPIO lines if interrupted
        if (signal(SIGINT) == SIG_IGN) {
            signal(SIGINT, handle_signal);
        }
        if (signal(SIGTERM) == SIG_IGN) {
            signal(SIGTERM, handle_signal);
        }
    }

    cleanup_resources();
    return EXIT_SUCCESS;
}

// SPI write and read helper function
int spi_write_read(int fd, uint8_t command, uint8_t num_samples, uint8_t *data) {
    int ret;
    ret = write(fd, &command, 1);
    if (ret != 1) {
        return ret;
    }

    ret = write(fd, data, num_samples * sizeof(uint8_t));
    if (ret != num_samples * sizeof(uint8_t)) {
        return ret;
    }

    ret = read(fd, data, num_samples * sizeof(uint8_t));
    if (ret != num_samples * sizeof(uint8_t)) {
        return ret;
    }

    return ret;
}

