#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <stdint.h>

#define SPI0_BASE 0
#define CE0 27
#define GPIO8 24
#define GPIO9 18
#define GPIO10 17
#define GPIO11 22
#define GPIO21 7

#define ADC_CHANNEL 0
#define THRESHOLD_MAGNETIC_FIELD 10.0
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t sigint_received = 0;

void cleanup_and_exit(int signum) {
    if (gpiod_is_valid(GPIO21)) {
        gpiod_write(GPIO21, 0);
    }
    if (gpiod_is_valid(GPIO8) && gpiod_is_valid(GPIO9) && gpiod_is_valid(GPIO10) && gpiod_is_valid(GPIO11)) {
        gpiod_unexport(SPI0_BASE);
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    exit(signum);
}

void setup_spi() {
    int spi_device;
    struct spi_device_id *id_table = NULL;

    id_table = &spi_device_id;
    spi_device_id.id_table = (unsigned long *)id_table;

    spi_device = gpiod_create_spi(SPI0_BASE, CE0, GPIO8, GPIO9, GPIO10, GPIO11, 0, NULL);
    if (SPI_DEVICE_INVALID == spi_device) {
        fprintf(stderr, "Failed to create SPI device\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_is_valid(spi_device)) {
        gpiod_export(spi_device);
    } else {
        fprintf(stderr, "Failed to export SPI device\n");
        exit(EXIT_FAILURE);
    }
}

void setup_adc() {
    int adc_device;
    struct spi_device *spi;
    struct mcp3008_config config;

    spi = gpiod_get_device(spi_device);
    if (!spi) {
        fprintf(stderr, "Failed to get SPI device\n");
        exit(EXIT_FAILURE);
    }

    config.speed_hz = 1000000; // 1 MHz
    config.mode = MCP3008_MODE_0; // Normal mode
    adc_device = mcp3008_init(spi, &config);
    if (MCP3008_DEVICE_INVALID == adc_device) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_is_valid(adc_device)) {
        gpiod_export(adc_device);
    } else {
        fprintf(stderr, "Failed to export MCP3008 device\n");
        exit(EXIT_FAILURE);
    }
}

void read_adc_and_handle_threshold() {
    int value;
    struct timespec timestamp;

    if (mcp3008_read(adc_device, ADC_CHANNEL, &value) != MCP3008_SUCCESS) {
        fprintf(stderr, "Failed to read ADC value\n");
        return;
    }

    value /= 1024.0; // Convert to voltage
    double magnetic_field = (value * 3.3) / 65536.0; // Assuming 3.3V reference voltage and 12-bit ADC

    if (magnetic_field > THRESHOLD_MAGNETIC_FIELD) {
        gpiod_write(GPIO21, 1); // Turn on LED
    } else {
        gpiod_write(GPIO21, 0); // Turn off LED
    }

    time(&timestamp);
    char buffer[50];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timestamp);
    fprintf(fp, "Magnetic field: %.2f mT at %s\n", magnetic_field, buffer);

    sigint_received = 0; // Clear flag for next interval
}

int main() {
    signal(SIGINT, cleanup_and_exit);

    setup_spi();
    setup_adc();

    FILE *fp = fopen("magnetic_log.txt", "a+");
    if (!fp) {
        fprintf(stderr, "Failed to open magnetic_log.txt for writing\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_adc_and_handle_threshold();
        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait for 100 ms
    }

    return 0;
}

