// Function prototypes
int spi_open_mcp3008();
void spi_close_mcp3008();
int read_mcp3008(int channel);
void handle_sigint(int signum);

int main() {
    // Initialize variables
    char buffer[256];
    char timestamp[19];
    int adc_value;
    int fd;
    int ret;
    struct tm tm;
    time_t now;

    // Open SPI device
    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Initialize MCP3008
    if (spi_open_mcp3008(fd, SPI_CHANNEL, CHIP_ENABLE, SPI_SPEED) < 0) {
        perror("Failed to initialize MCP3008");
        close(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Get current time
        now = time(NULL);
        localtime_r(&now, &tm);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        // Attempt to read ADC value
        if ((ret = read_mcp3008(SOIL_MOISTURE_PIN)) == -1) {
            // Read failed, log error
