            write(1, buffer, strlen(buffer));
        } else {
            // Read successful, log value
            sprintf(buffer, "%s %d\n", timestamp, ret);
            write(1, buffer, strlen(buffer));
        }

        // Handle SIGINT
        if (signal(SIGINT, handle_sigint) == SIG_ERR) {
            perror("Failed to install SIGINT handler");
            break; // Exit on error
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up on SIGINT
    handle_sigint(SIGINT);

    // Close SPI device
    spi_close_mcp3008();

    return EXIT_SUCCESS;
}

// Function to open MCP3008 SPI device
int spi_open_mcp3008(int fd, int channel, int chip_enable, int speed) {
    int ret;

    // Set SPI mode
    ret = ioctl(fd, SPI_IOC_WR_MODE, &channel);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    // Set chip enable
    ret = ioctl(fd, SPI_IOC_WR_CS_HIGH, &chip_enable);
    if (ret < 0) {
        perror("Failed to set chip enable");
        return -1;
    }

    // Set clock speed
    ret = ioctl(fd, SPI_IOC_WR_BAUDRATE, &speed);
    if (ret < 0) {
        perror("Failed to set clock speed");
        return -1;
    }

    return 0;
}

// Function to close MCP3008 SPI device
void spi_close_mcp3008() {
    // Close SPI device
    close("/dev/spidev0.0");
}

// Function to read MCP3008 ADC value
int read_mcp3008(int channel) {
    int value = 0;
    struct spi_ioc_transfer transfers[] = {
        // Transfer setup
        SPI_IOC_MESSAGE(1),
        // Data out (MCP3008 to SPI), MSB first
        SPI_IOC_DATA_OUT(&channel),
        // Data in (SPI to MCP3008), MSB first
        SPI_IOC_DATA_IN(&value, 1),
    };

    // Execute the transfer
    int ret = spi_write_transfer(fd, transfers, 1);
    if (ret < 0) {
        return -1; // Read failed
    }

    return value;
}

// SIGINT handler
void handle_sigint(int signum) {
    // Clean up
    spi_close_mcp3008();
    // Terminate the program
    exit(EXIT_FAILURE);
}

