#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO17 17 // BCM numbering

// Constants for MCP3008 configuration
#define MCP3008_ADDR 0x68
#define MCP3008_CMD_READ 0x01

// Function prototypes
void setup_spi();
void setup_gpio();
void read_current();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Check if SPI device exists
    if ((open(SPI_DEVICE, O_RDWR) == -1) || (fcntl(SPI_DEVICE, FIONBIO) == -1)) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Setup GPIO for GPIO17
    setup_gpio();

    // Main loop
    while (1) {
        read_current();
        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

// Function to setup SPI communication
void setup_spi() {
    struct spi_ioc_transfer xfer[2];
    xfer[0].tx_buf = (unsigned long)&MCP3008_CMD_READ; // Send command
    xfer[0].rx_buf = NULL; // No receive buffer
    xfer[0].len = sizeof(MCP3008_CMD_READ);
    xfer[0].delay_usecs = 0;
    xfer[0].speed_hz = 1000000; // 1 MHz

    xfer[1].tx_buf = NULL; // No transmit buffer
    xfer[1].rx_buf = (unsigned long *)&(uint16_t{0}); // Receive data
    xfer[1].len = sizeof(uint16_t);
    xfer[1].delay_usecs = 10000; // Wait for conversion
    xfer[1].speed_hz = 1000000; // 1 MHz

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    // Transfer command to MCP3008
    if (write(spi_fd, xfer, sizeof(xfer)) != sizeof(xfer)) {
        perror("Error sending command to MCP3008");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for conversion
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), xfer) != 1) {
        perror("Error reading from MCP3008");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Close SPI device
    close(spi_fd);
}

// Function to setup GPIO for GPIO17
void setup_gpio() {
    int gpio_fd = open(GPIO17, O_RDWR);
    if (gpio_fd == -1) {
        perror("Error opening GPIO");
        exit(EXIT_FAILURE);
    }

