#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <gpiod.h>
#include <mcp3008.h>

// Global variables
volatile sig_atomic_t interrupt_requested = 0;
FILE *current_log_file = NULL;
mcp3008_t adc;

// Function prototypes
void handle_spi_error(void);
void handle_adc_out_of_range(uint16_t value);
void handle_file_open_error(int error_code);
void cleanup_resources(void);

// Main function
int main(void) {
    // Initialize GPIO and MCP3008
    if (gpiod_direction_output(GPIOD_PIN_8, 1) != 0) {
        fprintf(stderr, "Error setting GPIO8 as output for MCP3008 CE0\n");
        return 1;
    }
    if (gpiod_direction_output(GPIOD_PIN_10, 1) != 0) {
        fprintf(stderr, "Error setting GPIO10 as output for SPI MOSI\n");
        return 1;
    }
    if (gpiod_direction_output(GPIOD_PIN_9, 1) != 0) {
        fprintf(stderr, "Error setting GPIO9 as output for SPI MISO\n");
        return 1;
    }
    if (gpiod_direction_output(GPIOD_PIN_11, 1) != 0) {
        fprintf(stderr, "Error setting GPIO11 as output for SPI SCLK\n");
        return 1;
    }

    if (mcp3008_init(&adc, MCP3008_CS0, 1000000) != 0) {
        fprintf(stderr, "Error initializing MCP3008\n");
        return 1;
    }

    // Open log file for appending
    if ((current_log_file = fopen("current_log.txt", "a")) == NULL) {
        handle_file_open_error(errno);
        mcp3008_free(&adc);
        return 1;
    }

    // Main loop
    while (1) {
        if (interrupt_requested) {
            break;
        }

        // Sample the current sensor
        uint16_t adc_value;
        if (mcp3008_read(&adc, 0) != 0) {
            handle_spi_error();
            continue;
        }

        adc_value = mcp3008_getConvertedValue(&adc);

        // Check if the ADC value is within range
        if (adc_value < 0 || adc_value > 1023) {
            handle_adc_out_of_range(adc_value);
            continue;
        }

        // Convert ADC value to current
        float voltage = adc_value / 1023.0 * 5.0;
        float current = voltage / 1024.0; // Assuming 0-5V range and 0-20A full scale

        // Format and write to log file
        char timestamp[23];
        time_t now = time(NULL);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", &timeinfo);
        sprintf(timestamp + strlen(timestamp) - 6, "%6.2f A", current);

        fprintf(current_log_file, "%s %d\n", timestamp, current);

        fflush(current_log_file);
    }

    // Cleanup resources
    cleanup_resources();

    return 0;
}

// Handle SPI transfer errors
void handle_spi_error(void) {
    fprintf(stderr, "SPI transfer error occurred\n");
    exit(1);
}

// Handle ADC out of range values
void handle_adc_out_of_range(uint16_t value) {
    fprintf(stderr, "ADC value out of range: %d\n", value);
    continue;
}

// Handle file open errors
void handle_file_open_error(int error_code) {
    fprintf(stderr, "Error opening log file: %s\n", strerror(error_code));
    mcp3008_free(&adc);
    exit(1);
}

// Cleanup resources
void cleanup_resources(void) {
    if (current_log_file != NULL) {
        fclose(current_log_file);
        current_log_file = NULL;
    }
    mcp3008_free(&adc);
}

