#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_1_GPIO_NUM 4
#define SENSOR_2_GPIO_NUM 17

// Function prototypes
void setup_gpios(void);
void read_sensors_and_debounce(int gpio, int debounce_count, int* state);
void handle_int(int signum);
void cleanup_gpios(void);

// Main function
int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Signal handler for SIGINT
    signal(SIGINT, handle_int);

    // Main loop
    while (1) {
        // Read sensors and debounce
        int state_1, state_2;
        read_sensors_and_debounce(SENSOR_1_GPIO_NUM, 5, &state_1);
        read_sensors_and_debounce(SENSOR_2_GPIO_NUM, 5, &state_2);

        // Log sensor states
        printf("Sensor 1: %s\n", state_1 == 0 ? "0" : "1");
        printf("Sensor 2: %s\n", state_2 == 0 ? "0" : "1");

        // Check for both sensors detecting an object
        if (state_1 == 0 && state_2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up GPIO on SIGINT
    cleanup_gpios();

    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    int sensor_1_mode = GPIO_ACTIVE_LOW;
    int sensor_2_mode = GPIO_ACTIVE_LOW;

    // Check if GPIO pins are valid
    if (gpiod_is_valid(SENSOR_1_GPIO_NUM, GPIO_ACTIVE_LOW) == 0) {
        fprintf(stderr, "Error: GPIO4 is not valid for active low mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_is_valid(SENSOR_2_GPIO_NUM, GPIO_ACTIVE_LOW) == 0) {
        fprintf(stderr, "Error: GPIO17 is not valid for active low mode\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins with internal pull-up
    if (gpiod_direction_output(SENSOR_1_GPIO_NUM, sensor_1_mode) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO4\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_output(SENSOR_2_GPIO_NUM, sensor_2_mode) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO17\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read sensors and debounce
void read_sensors_and_debounce(int gpio, int debounce_count, int* state) {
    int readings[debounce_count];
    int i;

    // Read sensor state multiple times with debounce
    for (i = 0; i < debounce_count; i++) {
        if (gpiod_get_value gpio == 0) {
            readings[i] = 1; // Object detected
        } else {
            readings[i] = 0; // No object detected
        }
    }

    // Determine the majority state
    *state = (readings[0] == readings[1] && readings[0] == readings[2] && readings[0] == readings[3] && readings[0] == readings[4]) ? 0 : 1;
}

// Signal handler for SIGINT
void handle_int(int signum) {
    // Clean up GPIO resources
    cleanup_gpios();
    exit(EXIT_SUCCESS);
}

