int main() {
    // Initialize libgpiod
    initialize_libgpiod();

    // Set up GPIO pin for PIR sensor
    gpio_item *pir_gpio_item = NULL;
    int pir_gpio_fd = -1;
    if (gpio_request(PIR_GPIO, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO %d: %s\n", PIR_GPIO, strerror(errno));
        return EXIT_FAILURE;
    }
    pir_gpio_item = gpio_request_one(PIR_GPIO, GPIO_IN, GPIO_PUD_DOWN);
    if (!pir_gpio_item) {
        fprintf(stderr, "Failed to request GPIO %d: %s\n", PIR_GPIO, strerror(errno));
        gpio_free(PIR_GPIO);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        struct timespec timeout;
        timeout.tv_sec = 0;
        timeout.tv_nsec = POLL_INTERVAL_MS * 1000000;

        // Poll GPIO pin
        if (gpio_input_value(pir_gpio_item) == GPIO_HIGH) {
            handle_motion_detection(pir_gpio_item);
        }

        // Wait for the debounce period
        nanosleep(&timeout, NULL);

        // Check if motion was detected and confirmed
        if (motion_detected) {
            take_photo(SECURITY_CAM_DIR "/motion_" TIME_TO_STRING(time(nullptr)) ".jpg");
            motion_detected = false;
        }
    }

    // Cleanup
    cleanup_libgpiod();

    return EXIT_SUCCESS;
}

