    libgpiod_uninit();
}

// Function to handle motion detection
void handle_motion_detection(gpio_item *pir_gpio) {
    int state = gpio_input_value(pir_gpio);
    if (state == GPIO_HIGH) {
        motion_detected = true;
        // Apply debounce delay
        usleep(DEBOUNCE_MS * 1000);
        // Re-read to confirm motion
        state = gpio_input_value(pir_gpio);
        if (state == GPIO_HIGH) {
            motion_detected = true;
        } else {
            motion_detected = false;
        }
    }
}

