    // Launch libcamera-still using fork and execvp
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid == 0) { // Child process
        if (execvp("libcamera-still", &argv[0]) < 0) {
            perror("execvp");
            _exit(EXIT_FAILURE);
