#include <libgpiod/csi.h>

#define CAMERA_DEVICE "/dev/video0" // Default CSI bus device
#define BUFFER_SIZE 1024 * 1024 // 1MB buffer size
#define IMAGE_FILE_PREFIX "image_"
#define MAX_IMAGE_COUNT 1000 // Maximum number of images to save

// Function prototypes
void setup_camera(const char *device);
void handle_signal(int signum);
void capture_and_save_image();
void cleanup_resources();

int main(int argc, char **argv) {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Check if the correct number of arguments is provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <camera_device>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Set the camera device from the command line argument
    const char *device = argc > 2 ? argv[2] : CAMERA_DEVICE;

    // Initialize the camera
    setup_camera(device);

    // Main loop for capturing and saving images
    int image_count = 1;
    while (image_count <= MAX_IMAGE_COUNT) {
        capture_and_save_image();
        image_count++;
    }

    // Clean up resources
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to set up the camera
void setup_camera(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct gpiod_csi_device *csi_dev;
    int ret = gpiod_csi_device_open(fd, GPIOD_CSI_DEVICE_FLAG_NONE);
    if (ret < 0) {
        perror("gpiod_csi_device_open");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Configure the camera for 8-bit grayscale
    ret = gpiod_csi_config(csi_dev, GPIOD_CSI_CFG_ENABLE, 0x00000001);
    if (ret < 0) {
        perror("gpiod_csi_config");
        gpiod_csi_device_close(csi_dev);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_csi_device_close(csi_dev);
    close(fd);
}

// Function to handle signals
void handle_signal(int signum) {
    // Stop the camera and clean up resources
    capture_and_save_image();
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

// Function to capture and save an image
void capture_and_save_image() {
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return;
    }

    struct gpiod_csi_device *csi_dev;
    int ret = gpiod_csi_device_open(fd, GPIOD_CSI_DEVICE_FLAG_NONE);
    if (ret < 0) {
        perror("gpiod_csi_device_open");
        close(fd);
        return;
    }

    // Map the buffer for memory-mapped streaming
    char *mapped_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_buffer == MAP_FAILED) {
        perror("mmap");
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Configure the camera for memory-mapped streaming
    ret = gpiod_csi_config(csi_dev, GPIOD_CSI_CFG_MMAP, 0x00000001);
    if (ret < 0) {
        perror("gpiod_csi_config");
        munmap(mapped_buffer, BUFFER_SIZE);
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Start streaming
    ret = gpiod_csi_start(csi_dev);
    if (ret < 0) {
        perror("gpiod_csi_start");
        munmap(mapped_buffer, BUFFER_SIZE);
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Capture and save the image
    char filename[20];
    sprintf(filename, "%s%03d.pgm", IMAGE_FILE_PREFIX, image_count);

    // Dequeue the frame
    while (1) {
        // Check for EAGAIN
        if (ret = gpiod_csi_dequeue(csi_dev, mapped_buffer, BUFFER_SIZE) == -1 && errno == EAGAIN) {
            select(2, NULL, NULL, NULL, NULL); // 2-second timeout
            continue;
        }

        // Save the image
        if (fwrite(mapped_buffer, 1, BUFFER_SIZE, fopen(filename, "wb")) != BUFFER_SIZE) {
            perror("fwrite");
            gpiod_csi_stop(csi_dev);
            munmap(mapped_buffer, BUFFER_SIZE);
            gpiod_csi_device_close(csi_dev);
            close(fd);
            return;
        }

        // Unmap the buffer after saving
        munmap(mapped_buffer, BUFFER_SIZE);
    }

    // Stop the camera
    gpiod_csi_stop(csi_dev);
    gpiod_csi_device_close(csi_dev);
    close(fd);
}

// Function to clean up resources
void cleanup_resources() {
