// Function to capture and save an image
void capture_and_save_image() {
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return;
    }

    struct gpiod_csi_device *csi_dev;
    int ret = gpiod_csi_device_open(fd, GPIOD_CSI_DEVICE_FLAG_NONE);
    if (ret < 0) {
        perror("gpiod_csi_device_open");
        close(fd);
        return;
    }

    // Map the buffer for memory-mapped streaming
    char *mapped_buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_buffer == MAP_FAILED) {
        perror("mmap");
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Configure the camera for memory-mapped streaming
    ret = gpiod_csi_config(csi_dev, GPIOD_CSI_CFG_MMAP, 0x00000001);
    if (ret < 0) {
        perror("gpiod_csi_config");
        munmap(mapped_buffer, BUFFER_SIZE);
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Start streaming
    ret = gpiod_csi_start(csi_dev);
    if (ret < 0) {
        perror("gpiod_csi_start");
        munmap(mapped_buffer, BUFFER_SIZE);
        gpiod_csi_device_close(csi_dev);
        close(fd);
        return;
    }

    // Capture and save the image
    char filename[20];
    sprintf(filename, "%s%03d.pgm", IMAGE_FILE_PREFIX, image_count);

    // Dequeue the frame
    while (1) {
        // Check for EAGAIN
        if (ret = gpiod_csi_dequeue(csi_dev, mapped_buffer, BUFFER_SIZE) == -1 && errno == EAGAIN) {
            select(2, NULL, NULL, NULL, NULL); // 2-second timeout
            continue;
        }

        // Save the image
        if (fwrite(mapped_buffer, 1, BUFFER_SIZE, fopen(filename, "wb")) != BUFFER_SIZE) {
            perror("fwrite");
            gpiod_csi_stop(csi_dev);
            munmap(mapped_buffer, BUFFER_SIZE);
            gpiod_csi_device_close(csi_dev);
            close(fd);
            return;
        }

        // Unmap the buffer after saving
        munmap(mapped_buffer, BUFFER_SIZE);
    }

    // Stop the camera
    gpiod_csi_stop(csi_dev);
    gpiod_csi_device_close(csi_dev);
    close(fd);
