// Function to capture and send a frame
void capture_and_send_frame(uint8_t *buffer) {
    Header header;
    header.frame_index = ++frame_index;
    header.fragment_index = 0;
    header.total_fragments = 1;
    header.payload_size = BUFFER_SIZE;

    // Send UDP packets
    for (int fragment = 0; fragment < (BUFFER_SIZE / 65); ++fragment) {
        uint32_t fragment_offset = fragment * 65;
        uint32_t fragment_size = std::min(BUFFER_SIZE - fragment_offset, 65);

        memcpy(&header, buffer + fragment_offset, sizeof(Header));
        uint8_t *fragment_data = buffer + fragment_offset + sizeof(Header);

        if (sendto(socket, fragment_data, fragment_size, 0, (struct sockaddr *) &target_addr, sizeof(target_addr)) < 0) {
            perror("sendto failed");
            break;
        }
    }

    // Unmap the buffer and free memory
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        munmap(buffer_map[i], BUFFER_SIZE);
        buffer_map[i] = NULL;
    }
    buffer = NULL;
}

