#include <signal.h>
#include <libgpiod.h>
#include <v4l2.h>

#define VIDEO_DEVICE "/dev/video0"
#define MJPEG_WIDTH 192
#define MJPEG_HEIGHT 144
#define BUFFER_COUNT 4

// Function prototypes
void handle_signal(int signum);
void cleanup_resources(void);

int main(int argc, char *argv[]) {
    // Initialize libgpiod for GPIO operations (not used in this specific script)
    libgpiod_init();

    // Signal handler to stop the process gracefully
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the video device
    int fd = open(VIDEO_DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Check if the device supports video capture and streaming
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & (V4L2_CAP_VIDEO_CAPTURE | V4L2_CAP_STREAMING))) {
        fprintf(stderr, "Device does not support video capture or streaming.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the pixel format to MJPEG
    struct v4l2_format fmt;
    fmt.type = V4L2_PIX_FMT_MJPEG;
    fmt.width = MJPEG_WIDTH;
    fmt.height = MJPEG_HEIGHT;
    fmt.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOCS_FMT, &fmt) < 0) {
        perror("VIDIOCS_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request four MMAP buffers
    struct v4l2_requestbuffers reqbuf;
    reqbuf.count = BUFFER_COUNT;
    if (ioctl(fd, VIDIOCSREQUEST, &reqbuf) < 0) {
        perror("VIDIOCSREQUEST");
        close(fd);
        return EXIT_FAILURE;
    }

    // Open the output file for writing
    FILE *file = fopen("image.jpg", "wb");
    if (!file) {
        perror("fopen");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    void *buffers[BUFFER_COUNT];
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_buffer buf;
        buf.index = i;
        if (ioctl(fd, VIDIOCGBUF, &buf) < 0) {
            perror("VIDIOCGBUF");
            fclose(file);
            close(fd);
            return EXIT_FAILURE;
        }
        buffers[i] = mmap(NULL, buf.memory.size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.memory.moffset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            fclose(file);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOCMCAPTURE, 0) < 0) {
        perror("VIDIOCMCAPTURE");
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            munmap(buffers[i], buf.memory.size);
        }
        fclose(file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a single frame
    struct v4l2_buffer dequeued_buf;
    if (ioctl(fd, VIDIOCGBUF, &dequeued_buf) < 0) {
        perror("VIDIOCGBUF");
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            munmap(buffers[i], buf.memory.size);
        }
        fclose(file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify bytesused is greater than zero
    if (dequeued_buf.bytesused == 0) {
        fprintf(stderr, "No data available in the dequeued buffer.\n");
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            munmap(buffers[i], buf.memory.size);
        }
        fclose(file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Write the raw MJPEG bytes to the file
    size_t bytes_written = fwrite(dequeued_buf.mdata, 1, dequeued_buf.bytesused, file);
    if (bytes_written != dequeued_buf.bytesused) {
        fprintf(stderr, "Failed to write MJPEG data to file.\n");
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            munmap(buffers[i], buf.memory.size);
        }
        fclose(file);
        close(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming and clean up resources
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        munmap(buffers[i], buf.memory.size);
    }
    fclose(file);
    close(fd);

    return EXIT_SUCCESS;
}

// Signal handler to stop the process gracefully
void handle_signal(int signum) {
    // Stop streaming
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        munmap(buffers[i], buf.memory.size);
    }
    close(fd);

    // Clean up and exit
    fclose(file);
    exit(EXIT_FAILURE);
}

// Function to cleanup resources
void cleanup_resources(void) {
    // Close the file and device file descriptor
    fclose(file);
    close(fd);
}

