#define PWM_FREQ 50 /* 50 Hz PWM frequency */
#define PWM_MIN_WIDTH 1 /* Minimum pulse width in ms */
#define PWM_MAX_WIDTH 2 /* Maximum pulse width in ms */
#define SERVO_MIN 25 /* Minimum servo position */
#define SERVO_MAX 125 /* Maximum servo position */
#define STEP_SIZE 5 /* Step size for servo adjustment */

#define GPIO4_NUM 7  /* BCM 4 */
#define GPIO5_NUM 17 /* BCM 5 */
#define GPIO6_NUM 11 /* BCM 6 */
#define GPIO7_NUM 12 /* BCM 7 */
#define GPIO8_NUM 13 /* BCM 8 */
#define GPIO9_NUM 21 /* BCM 9 */

volatile int pan_direction = 0; /* 1 for left, -1 for right */
volatile int tilt_direction = 0; /* 1 for up, -1 for down */

int main() {
    struct gpiod_dir_config dir_config;
    struct gpiod pwm;
    int rc;

    /* Initialize GPIO for PWM output */
    rc = gpiod_dir_config(&dir_config, GPIO4_NUM, GPIOD_OUT_HIGH);
    if (rc != 0) {
        fprintf(stderr, "Error configuring GPIO4: %d\n", rc);
        return EXIT_FAILURE;
    }

    rc = gpiod_open(&pwm, GPIO4_NUM, &dir_config);
    if (rc != 0) {
        fprintf(stderr, "Error opening GPIO4 PWM: %d\n", rc);
        gpiod_dir_config_free(&dir_config);
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for button inputs */
    rc = gpiod_dir_config(&dir_config, GPIO6_NUM, GPIOD_IN_PULLUP);
    if (rc != 0) {
        fprintf(stderr, "Error configuring GPIO6: %d\n", rc);
        gpiod_close(&pwm);
        gpiod_dir_config_free(&dir_config);
        return EXIT_FAILURE;
    }

    rc = gpiod_open(&pwm_buttons, GPIO6_NUM, &dir_config);
    if (rc != 0) {
        fprintf(stderr, "Error opening GPIO6: %d\n", rc);
        gpiod_dir_config_free(&dir_config);
        gpiod_close(&pwm);
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for servo control */
    rc = gpiod_open(&pwm_servo, GPIO5_NUM, &dir_config);
    if (rc != 0) {
        fprintf(stderr, "Error opening GPIO5: %d\n", rc);
        gpiod_close(&pwm_buttons);
        gpiod_dir_config_free(&dir_config);
        gpiod_close(&pwm);
        return EXIT_FAILURE;
    }

    /* Initialize servos to mid position */
    int pan_value = SERVO_MIN + (SERVO_MAX - SERVO_MIN) / 2;
    int tilt_value = SERVO_MIN + (SERVO_MAX - SERVO_MIN) / 2;

    pwm.config = gpiod_configPWM(1000, PWM_FREQ);
    pwm.value = (uint32_t)pan_value * 1000 / PWM_MAX_WIDTH;
    rc = gpiod_set_value(&pwm_servo, &pwm);
    if (rc != 0) {
        fprintf(stderr, "Error setting pan servo: %d\n", rc);
        gpiod_close(&pwm_servo);
        gpiod_close(&pwm_buttons);
        gpiod_dir_config_free(&dir_config);
        gpiod_close(&pwm);
        return EXIT_FAILURE;
    }

    pwm.value = (uint32_t)tilt_value * 1000 / PWM_MAX_WIDTH;
    rc = gpiod_set_value(&pwm_servo, &pwm);
    if (rc != 0) {
        fprintf(stderr, "Error setting tilt servo: %d\n", rc);
        gpiod_close(&pwm_servo);
        gpiod_close(&pwm_buttons);
        gpiod_dir_config_free(&dir_config);
        gpiod_close(&pwm);
        return EXIT_FAILURE;
    }

    /* Signal handler for SIGINT */
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; /* Ignore SIGINT */
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        /* Poll buttons */
        rc = gpiod_read(&pwm_buttons, 1, 1, NULL);
        if (rc != 0) {
            fprintf(stderr, "Error reading buttons: %d\n", rc);
            break;
        }

        int tilt_button_state = (gpiod_read(&pwm_buttons, GPIO6_NUM, 1, NULL)[0] == 0);
        int pan_button_state = (gpiod_read(&pwm_buttons, GPIO8_NUM, 1, NULL)[0] == 0);

        if (tilt_button_state && tilt_direction == 0) {
            tilt_direction = 1; /* Tilt up */
        } else if (!tilt_button_state && tilt_direction != 0) {
            tilt_direction = 0; /* Tilt down */
        }

        if (pan_button_state && pan_direction == 0) {
            pan_direction = 1; /* Pan left */
        } else if (!pan_button_state && pan_direction != 0) {
            pan_direction = 0; /* Pan right */
        }

        /* Adjust servo positions */
        if (tilt_direction != 0) {
            int tilt_value = SERVO_MIN + (tilt_direction * STEP_SIZE) % (SERVO_MAX - SERVO_MIN) + SERVO_MIN;
            pwm.value = (uint32_t)tilt_value * 1000 / PWM_MAX_WIDTH;
            rc = gpiod_set_value(&pwm_servo, &pwm);
            if (rc != 0) {
                fprintf(stderr, "Error setting tilt servo: %d\n", rc);
                break;
            }
        }

        if (pan_direction != 0) {
            int pan_value = SERVO_MIN + (pan_direction * STEP_SIZE) % (SERVO_MAX - SERVO_MIN) + SERVO_MIN;
            pwm.value = (uint32_t)pan_value * 1000 / PWM_MAX_WIDTH;
            rc = gpiod_set_value(&pwm_servo, &pwm);
            if (rc != 0) {
                fprintf(stderr, "Error setting pan servo: %d\n", rc);
                break;
            }
        }

        /* Poll servos for actual position if needed */

        /* Sleep for 50 ms */
        usleep(50000);
    }

    /* Clean up on SIGINT */
    rc = gpiod_close(&pwm_buttons);
    if (rc != 0) {
        fprintf(stderr, "Error closing GPIO6: %d\n", rc);
    }

    rc = gpiod_close(&pwm_servo);
    if (rc != 0) {
        fprintf(stderr, "Error closing GPIO5: %d\n", rc);
