            char filename[256];
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            sprintf(filename, "capture_%04d%02d%02d.jpg", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday);
            FILE *file = fopen(filename, "wb");
