        av_frame_free(&yuv_frame);
        avcodec_free_context(&yuv_ctx);
        return;
    }

    // Queue the processed frame for output
    if (av_interleaved_write_frame(outctx, &packet) < 0) {
        fprintf(stderr, "Failed to write JPEG frame: %s\n", av_err2str(outctx->error));
        av_packet_unref(&packet);
        av_frame_free(&yuv_frame);
        avcodec_free_context(&yuv_ctx);
        av_frame_free(&yuv_frame);
        avformat_free_stream(&outstream);
        return;
