        return;
    }

    // Decode YUV to RGB
    if (avcodec_decode_video2(yuv_ctx, yuv_frame, &got_frame, NULL) < 0) {
        fprintf(stderr, "Failed to decode YUV to RGB: %s\n", av_err2str(avcodec_get_error()));
        av_frame_free(&yuv_frame);
        avcodec_free_context(&yuv_ctx);
        return;
    }

    if (got_frame) {
        // Process the image with a blur filter (example: simple averaging)
        int width = yuv_frame->width;
        int height = yuv_frame->height;
        uint8_t *yuv_pixels = (uint8_t *)yuv_frame->data;
        uint8_t *rgb_pixels = (uint8_t *)av_frame_get_data(yuv_frame);

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                uint8_t yu = yuv_pixels[0];
                uint8_t yv = yuv_pixels[1];
                uint8_t ru = yuv_pixels[2];
                uint8_t rv = yuv_pixels[3];

                // Simple blur filter: average with neighbors
                int avg_r = (ru + (x > 0 && x < width - 1) ? rgb_pixels[x+1][0] : 0) +
                             (ru + (x < width - 1 && x > 0) ? rgb_pixels[x-1][0] : 0) / 2;
                int avg_g = (rg + (x > 0 && x < width - 1) ? rgb_pixels[x+1][1] : 0) +
                             (rg + (x < width - 1 && x > 0) ? rgb_pixels[x-1][1] : 0) / 2;
                int avg_b = (rb + (y > 0 && y < height - 1) ? rgb_pixels[y+1][2] : 0) +
                             (rb + (y < height - 1 && y > 0) ? rgb_pixels[y-1][2] : 0) / 2;

                rgb_pixels[y * width + x] = av_make_YCrCb_to_RGB16(avg_r, avg_g, avg_b);
            }
        }

        // Encode RGB to JPEG
        AVOutputFormat *outfmt;
        AVStream *outstream;
        if ((outfmt = av_guess_format("jpeg", NULL, NULL)) == NULL) {
            fprintf(stderr, "Failed to guess output format: %s\n", av_err2str(avcodec_get_error()));
            av_frame_free(&yuv_frame);
            avcodec_free_context(&yuv_ctx);
            return;
        }

        if ((outstream = avformat_new_stream(avctx, outfmt)) == NULL) {
            fprintf(stderr, "Failed to create output stream: %s\n", av_err2str(avcodec_get_error()));
            av_frame_free(&yuv_frame);
            avcodec_free_context(&yuv_ctx);
            return;
        }

        outstream->codecpar->codec_type = AVMEDIA_TYPE_VIDEO;
        outstream->codecpar->codec_id = outfmt->video_codec;
        outstream->codecpar->width = yuv_frame->width;
        outstream->codecpar->height = yuv_frame->height;
        outstream->time_base = yuv_ctx->time_base;

        if (avcodec_parameters_from_context(outstream->codecpar, yuv_ctx) < 0) {
            fprintf(stderr, "Failed to copy parameters from YUV context: %s\n", av_err2str(avcodec_get_error()));
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
            return;
        }

        if (avcodec_open2(outstream->codec, outfmt->codec, NULL) < 0) {
            fprintf(stderr, "Failed to open JPEG codec: %s\n", av_err2str(avcodec_get_error()));
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
            return;
        }

        AVPacket packet;
        packet.size = sizeof(AVPacket);
        packet.data = (uint8_t *)&packet;

        AVStream *instream = avctx->streams[0];
        AVFrame *inframe = av_frame_alloc();
        if (!inframe) {
            fprintf(stderr, "Failed to allocate input frame: %s\n", av_err2str(avcodec_get_error()));
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
            return;
        }

        if (avcodec_parameters_from_context(inframe->format, instream->codecpar) < 0) {
            fprintf(stderr, "Failed to copy input parameters: %s\n", av_err2str(avcodec_get_error()));
            av_frame_free(&inframe);
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
            return;
        }

        if (avcodec_decode_video2(outstream->codec, inframe, &got_frame, &packet) < 0) {
            fprintf(stderr, "Failed to decode YUV to JPEG: %s\n", av_err2str(outstream->codec->error));
            av_frame_free(&inframe);
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
            return;
        }

        if (got_frame) {
            // Write the JPEG image to a file
            char filename[256];
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            sprintf(filename, "capture_%04d%02d%02d.jpg", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday);
            FILE *file = fopen(filename, "wb");
            if (!file) {
                fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
                av_packet_unref(&packet);
                av_frame_free(&inframe);
                avcodec_free_context(&yuv_ctx);
                av_frame_free(&yuv_frame);
                avformat_free_stream(&outstream);
                return;
            }

            if (avio_write(outctx, &packet, packet.size) < 0) {
                fprintf(stderr, "Failed to write JPEG data to file: %s\n", avio_error(outctx));
                fclose(file);
                av_packet_unref(&packet);
                av_frame_free(&inframe);
                avcodec_free_context(&yuv_ctx);
                av_frame_free(&yuv_frame);
                avformat_free_stream(&outstream);
                return;
            }

            fclose(file);

            av_packet_unref(&packet);
            av_frame_free(&inframe);
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
        } else {
            fprintf(stderr, "No frame to process.\n");
            av_frame_free(&inframe);
            avcodec_free_context(&yuv_ctx);
            av_frame_free(&yuv_frame);
            avformat_free_stream(&outstream);
        }
    } else {
        fprintf(stderr, "Failed to decode YUV to RGB: %s\n", av_err2str(yuv_ctx->error));
        av_frame_free(&yuv_frame);
        avcodec_free_context(&yuv_ctx);
        return;
    }

    // Queue the processed frame for output
    if (av_interleaved_write_frame(outctx, &packet) < 0) {
        fprintf(stderr, "Failed to write JPEG frame: %s\n", av_err2str(outctx->error));
        av_packet_unref(&packet);
        av_frame_free(&yuv_frame);
        avcodec_free_context(&yuv_ctx);
        av_frame_free(&yuv_frame);
        avformat_free_stream(&outstream);
        return;
    }
}

