#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <video4linux2.h>

#define VIDEO_DEVICE "/dev/video0"

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_frame_format frame_fmt;
    struct v4l2_frame_interval interval;
    int i, supported_resolutions = 0, supported_frame_intervals = 0;
    int focus_auto;

    // Check if the device node exists
    if (access(VIDEO_DEVICE, F_OK) == -1) {
        perror("Accessing device node");
        return 1;
    }

    // Open the device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Opening device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    printf("Device capabilities:\n");
    printf("  Card type: %s\n", cap.card.type);
    printf("  Bus info: %s\n", cap.bus.info);

    // Check if the device supports frame sizes and intervals
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        printf("Note: This device does not support video capture.\n");
        close(fd);
        return 0; // Exit with 0 since it's not a fatal error
    }

    // Enumerate supported frame sizes
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("VIDIOC_ENUM_FMT");
        close(fd);
        return 1;
    }

    printf("Supported frame sizes:\n");
    for (i = 0; i < fmt.count; i++) {
        frame_fmt = fmt.formats[i];
        printf("  %dx%d (%d bytes)\n", frame_fmt.width, frame_fmt.height, frame_fmt.pixelformat);
        supported_resolutions++;
    }

    // Enumerate frame intervals for each supported frame size
    for (i = 0; i < supported_resolutions; i++) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &interval) < 0) {
            perror("VIDIOC_ENUM_FRAMEINTERVALS");
            close(fd);
            return 1;
        }

        printf("Frame intervals for %dx%d:\n", frame_fmt.width, frame_fmt.height);
        for (int j = 0; j < interval.count; j++) {
            printf("  %d fps\n", interval.intervals[j].min);
            supported_frame_intervals++;
        }

        printf("\n");
    }

    // Query V4L2_CID_FOCUS_AUTO
    if (ioctl(fd, VIDIOC_QUERYCTRL, &cap) < 0) {
        perror("VIDIOC_QUERYCTRL");
        close(fd);
        return 1;
    }

    focus_auto = cap.capabilities & V4L2_CID_FOCUS_AUTO;

    if (focus_auto == 0) {
        printf("Note: Autofocus is not supported.\n");
    } else {
        printf("Autofocus is supported.\n");
    }

    // Close the device
    close(fd);

    return 0;
}

