// Function to initialize libgpiod
void initialize_libgpiod() {
    struct gpiod_chip *chip;
    int ret;

    // Open the GPIO controller
    chip = gpiod_open(GPIOD, "r");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO controller: %s\n", gpiod_get_name(chip));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins for PWM
    ret = gpiod_set_data_direction(GPIO4_NUM, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO4 direction: %s\n", gpiod_get_name(GPIO4_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
