        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_mode(GPIO5_NUM, GPIOD_MODE_PWM);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO5 mode: %s\n", gpiod_get_name(GPIO5_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins for buttons with internal pull-up resistors
    ret = gpiod_set_pull_mode(GPIO6_NUM, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO6 pull mode: %s\n", gpiod_get_name(GPIO6_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_pull_mode(GPIO7_NUM, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO7 pull mode: %s\n", gpiod_get_name(GPIO7_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_pull_mode(GPIO8_NUM, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO8 pull mode: %s\n", gpiod_get_name(GPIO8_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_pull_mode(GPIO9_NUM, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO9 pull mode: %s\n", gpiod_get_name(GPIO9_NUM));
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    // Success
    printf("libgpiod initialized successfully.\n");
}

// Function to setup servos and buttons
void setup_servos_and_buttons() {
    // Initialize servo pulse widths to center position
    int pan_servo_pwm = gpiod_get_value_u16(GPIO4_NUM);
    int tilt_servo_pwm = gpiod_get_value_u16(GPIO5_NUM);

    gpiod_set_value_u16(GPIO4_NUM, CENTER_PULSE_WIDTH);
    gpiod_set_value_u16(GPIO5_NUM, CENTER_PULSE_WIDTH);

    // Button states (active low, pull-up enabled)
    int up_button_state = gpiod_get_value(GPIO6_NUM);
    int down_button_state = gpiod_get_value(GPIO7_NUM);
    int left_button_state = gpiod_get_value(GPIO8_NUM);
    int right_button_state = gpiod_get_value(GPIO9_NUM);

    // Assuming button press is detected by a falling edge
    up_button_state = !up_button_state;
    down_button_state = !down_button_state;
    left_button_state = !left_button_state;
    right_button_state = !right_button_state;
}

// Function to handle button presses
void handle_button_presses() {
    int pan_movement = 0;
    int tilt_movement = 0;

    // Check button states
    if (up_button_state) {
        tilt_movement = -1; // Move tilt down
    } else if (down_button_state) {
        tilt_movement = 1; // Move tilt up
    }

    if (left_button_state) {
        pan_movement = -1; // Move pan left
    } else if (right_button_state) {
        pan_movement = 1; // Move pan right
    }

    // Adjust servo pulse widths within the allowed range
    adjust_servo_pulse_width(GPIO4_NUM, pan_movement);
    adjust_servo_pulse_width(GPIO5_NUM, tilt_movement);
}

// Function to adjust servo pulse width
void adjust_servo_pulse_width(int servo_gpio, int movement) {
    int current_pwm = gpiod_get_value_u16(servo_gpio);
    int new_pwm;

    // Clamp the pulse width within the allowed range
    if (movement > 0) {
        new_pwm = MIN_PULSE_WIDTH + (movement * PULSE_INCREMENT);
    } else if (movement < 0) {
        new_pwm = MAX_PULSE_WIDTH - (abs(movement) * PULSE_INCREMENT);
    } else {
        new_pwm = current_pwm; // No movement
    }

    // Ensure the new PWM value is within the valid range
    if (new_pwm < MIN_PULSE_WIDTH) {
        new_pwm = MIN_PULSE_WIDTH;
    } else if (new_pwm > MAX_PULSE_WIDTH) {
        new_pwm = MAX_PULSE_WIDTH;
    }

    // Set the new PWM value
    gpiod_set_value_u16(servo_gpio, new_pwm);
}

// Function to cleanup and exit on signal
void cleanup_and_exit(int signum) {
    // Stop PWM on both servo pins
    gpiod_set_value_u16(GPIO4_NUM, 1000); // Minimum pulse width
    gpiod_set_value_u16(GPIO5_NUM, 1000); // Minimum pulse width

    // Release resources
    gpiod_close(GPIOD);

    // Exit
    exit(EXIT_SUCCESS);
}

