#include <unistd.h>
#include <gpiod.h>

#define PIR_GPIO 17
#define IMAGES_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

// Function prototypes
void setup_gpiod();
void handle_motion();
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize GPIO
    setup_gpiod();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Check for motion
        if (gpiod_event_get(&gpiod0, PIR_GPIO, GPIOD_EVENT_EDGE_FALLING) != 0) {
            handle_motion();
        }

        // Sleep to debounce
        usleep(50000); // 50 ms debounce

        // Check for interrupt signals
        if (waitpid(-1, NULL, 0) == -1) {
            perror("waitpid");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup GPIO
void setup_gpiod() {
    int ret;

    // Open GPIO driver
    ret = gpiod_open(&gpiod0, GPIOD_OPEN_BY_NAME);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", gpiod_errstr(gpiod0));
        exit(EXIT_FAILURE);
    }

    // Claim GPIO17 as input with edge detection
    ret = gpiod_request(gpiod0, PIR_GPIO, GPIOD_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to claim GPIO %d: %s\n", PIR_GPIO, gpiod_errstr(gpiod0));
        gpiod_close(gpiod0);
        exit(EXIT_FAILURE);
    }

    // Set up edge detection
    ret = gpiod_set_direction(gpiod0, PIR_GPIO, GPIOD_DIR_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", PIR_GPIO, gpiod_errstr(gpiod0));
        gpiod_release(gpiod0, PIR_GPIO);
        gpiod_close(gpiod0);
        exit(EXIT_FAILURE);
    }

    // Enable edge detection
    ret = gpiod_set_edge(gpiod0, PIR_GPIO, GPIOD_EDGE_FALLING);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d edge detection: %s\n", PIR_GPIO, gpiod_errstr(gpiod0));
        gpiod_release(gpiod0, PIR_GPIO);
        gpiod_close(gpiod0);
        exit(EXIT_FAILURE);
    }
}

// Function to handle motion
void handle_motion() {
    char filename[100];
    time_t now;
    struct tm *timeinfo;
    char command[256];

    // Generate filename
    now = time(NULL);
    timeinfo = localtime(&now);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", timeinfo);

    // Construct the command for capturing the image
