#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <video4linux2.h>
#include <errno.h>

#define VIDEO_DEVICE "/dev/video0"
#define VIDEO_FORMAT V4L2_PIX_FMT_YUYV
#define VIDEO_WIDTH 640
#define VIDEO_HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define BUFFER_SIZE (VIDEO_WIDTH * VIDEO_HEIGHT * 2)

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Stopping capture...\n");
        close(fd);
        munmap(buffer, BUFFER_SIZE);
        fclose(out_file);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers reqbuf;
    struct v4l2_buffer buf;
    char *buffer;
    FILE *out_file;
    fd_set readfds;
    int ret, rv;
    ssize_t bytes_written;

    // Open the video device
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device supports the requested format
    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE &&
        cap.capabilities & V4L2_CAP_FMT_YUYV) {
        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = VIDEO_WIDTH;
        fmt.fmt.pix.height = VIDEO_HEIGHT;
        fmt.fmt.pix.pixelformat = VIDEO_FORMAT;
        fmt.fmt.pix.field = V4L2_FIELD_NONE;

        if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
            perror("VIDIOC_S_FMT");
            close(fd);
            return EXIT_FAILURE;
        }
    } else {
        fprintf(stderr, "Device does not support the requested format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request memory-mapped buffers
    reqbuf.count = 1;
    reqbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    reqbuf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &reqbuf) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    // Allocate and map the buffer
    buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    // Open output file
    out_file = fopen("cropped.yuv", "wb");
    if (out_file == NULL) {
        perror("fopen");
        munmap(buffer, BUFFER_SIZE);
        close(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    while (1) {
        struct timeval tv;
        fd_set readfds;
        int ready;

        // Set a 2-second timeout
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        FD_SET(fd, &readfds);

        // Wait for a frame
        if (select(fd + 1, &readfds, NULL, NULL, &tv) == -1) {
            perror("select");
            break; // Exit on error or timeout
        }

        // Check if a frame is available
        if (FD_ISSET(fd, &readfds)) {
            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                continue; // Retry on EINTR
            }

            // Verify the captured frame matches the requested format
            if (buf.format.pixelformat != VIDEO_FORMAT ||
                buf.width != VIDEO_WIDTH || buf.height != VIDEO_HEIGHT) {
                fprintf(stderr, "Captured frame format does not match requested\n");
                break; // Exit on mismatch
            }

            // Copy YUYV macroblocks to avoid color corruption
            for (int y = 0; y < VIDEO_HEIGHT; y++) {
                for (int x = 0; x < VIDEO_WIDTH; x += 2) {
                    unsigned char *pY = (unsigned char *)buffer + y * VIDEO_WIDTH * 2 + x * 2;
                    unsigned char *pU = pY + 1;
                    unsigned char *pYNext = pY + VIDEO_WIDTH * 2 + x * 2;
                    unsigned char *pUNext = pU + 1;

                    // Copy Y, U, Y, V macroblocks
                    fwrite(pY, 1, 1, out_file);
                    fwrite(pU, 1, 1, out_file);
                    fwrite(pYNext, 1, 1, out_file);
                    fwrite(pUNext, 1, 1, out_file);
                }
            }

            // Crop the captured frame
            for (int y = 0; y < CROP_HEIGHT; y++) {
                for (int x = 0; x < CROP_WIDTH; x++) {
                    unsigned char *pY = (unsigned char *)buffer + y * VIDEO_WIDTH * 2 + x * 2;
                    fwrite(pY, 1, 1, out_file);
                }
            }

            // Check the number of bytes written
            bytes_written = fwrite(buffer, 1, BUFFER_SIZE, out_file);
            if (bytes_written != BUFFER_SIZE) {
                perror("fwrite");
                break; // Exit on error
            }

            // Print the number of bytes written for verification
            printf("Wrote %zu bytes\n", bytes_written);
        } else if (errno != EINTR) {
            perror("select");
            break; // Exit on other errors
        }
    }

    // Clean up on SIGINT/SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Unmap the buffer
    munmap(buffer, BUFFER_SIZE);

    // Close the file descriptor and the output file
    close(fd);
    fclose(out_file);

    return EXIT_SUCCESS;
}

