#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define SERVO_PIN_PAN 17
#define SERVO_PIN_TILT 18

#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

#define STEP_SIZE 5

void setup_servos(gpiod_device *gpiod) {
    if (gpiod_open(gpiod, GPIOD_OPEN_READ_WRITE) < 0) {
        fprintf(stderr, "Error: Failed to open GPIO device\n");
        exit(1);
    }

    gpiod_set_data_direction(gpiod, GPIOD_DATA_OUT);
    gpiod_set_mode(gpiod, SERVO_PIN_PAN, GPIOD_MODE_PWM_OUTPUT);
    gpiod_set_freq(gpiod, SERVO_PIN_PAN, 50000); // 50 Hz

    gpiod_set_mode(gpiod, SERVO_PIN_TILT, GPIOD_MODE_PWM_OUTPUT);
    gpiod_set_freq(gpiod, SERVO_PIN_TILT, 50000); // 50 Hz

    gpiod_set_value(gpiod, SERVO_PIN_PAN, SERVO_MIN_ANGLE);
    gpiod_set_value(gpiod, SERVO_PIN_TILT, SERVO_MIN_ANGLE);
}

void move_servo(gpiod_device *gpiod, int pin, int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: Out-of-range angle for servo\n");
        return;
    }

    gpiod_set_value(gpiod, pin, (angle * 100) / SERVO_MAX_ANGLE);
}

void cleanup_servos(gpiod_device *gpiod) {
    gpiod_set_value(gpiod, SERVO_PIN_PAN, SERVO_MIN_ANGLE);
    gpiod_set_value(gpiod, SERVO_PIN_TILT, SERVO_MIN_ANGLE);

    gpiod_close(gpiod);
}

void handle_signal(int signum) {
    printf("SIGINT received, terminating...\n");
    cleanup_servos(gpiod_device_get_by_label("gpiochip0"));
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiod_device *gpiod;
    if (gpiod_device_open("gpiochip0", "r") < 0) {
        fprintf(stderr, "Error: Failed to open GPIO controller\n");
        exit(1);
    }

    setup_servos(gpiod);

    while (1) {
        int key = getchar();

        if (key == 'q') {
            printf("Exiting...\n");
            cleanup_servos(gpiod);
            break;
        }

        if (key == '\n') {
            // Handle arrow keys
            if (key == '\e[A') {
                move_servo(gpiod, SERVO_PIN_PAN, SERVO_MIN_ANGLE + STEP_SIZE);
            } else if (key == '\e[B') {
                move_servo(gpiod, SERVO_PIN_PAN, SERVO_MIN_ANGLE - STEP_SIZE);
            } else if (key == '\e[D') {
                move_servo(gpiod, SERVO_PIN_TILT, SERVO_MIN_ANGLE + STEP_SIZE);
            } else if (key == '\e[C') {
                move_servo(gpiod, SERVO_PIN_TILT, SERVO_MIN_ANGLE - STEP_SIZE);
            }
        }

        usleep(100000); // 100 ms delay
    }

    return 0;
}

