        bcm2835_gpio_write(GPIO_NUM_RANGES[i], 0);
    }

    for (int i = 0; i < NUM_COLS; ++i) {
        bcm2835_gpio_fsel(GPIO_COL_PINS[i], BCM2835_GPIO_FSEL_INIT);
        bcm2835_gpio_config(GPIO_COL_PINS[i], BCM2835_GPIO_CONFIG_INPUT);
