#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>
#include <time.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

// GPIO pins configuration
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}

// Function prototypes
void setup_gpios(void);
void cleanup_gpios(void);
void handle_signal(int signum);
void draw_column(int column);
void delay_ms(int ms);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Draw columns
        for (int column = 0; column < NUM_COLS; column++) {
            draw_column(column);
            usleep(DELAY_MS * 1000); // Convert delay to microseconds
        }

        // Delay for 150ms between columns
        usleep(DELAY_MS * 1000);
    }

    // Clean up GPIO on exit
    cleanup_gpios();

    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    struct gpiod_chip *chip;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIOD_ANY_ID, GPIOD_OPEN_FLAG_NONE);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_get_name(chip));
        exit(EXIT_FAILURE);
    }

    // Initialize row and column GPIO pins
    for (int i = 0; i < NUM_ROWS; i++) {
        ret = gpiod_pin_configure(chip, ROW_PINS[i], GPIOD_PIN_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure row pin %d: %s\n", ROW_PINS[i], gpiod_get_name(chip));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        ret = gpiod_pin_configure(chip, COL_PINS[i], GPIOD_PIN_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure column pin %d: %s\n", COL_PINS[i], gpiod_get_name(chip));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    gpiod_chip_close(chip);
}

// Function to cleanup GPIO pins
void cleanup_gpios(void) {
    struct gpiod_chip *chip;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open(GPIOD_ANY_ID, GPIOD_OPEN_FLAG_NONE);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_get_name(chip));
        return;
    }

    // Set all row pins to output and all column pins to input
    for (int i = 0; i < NUM_ROWS; i++) {
        ret = gpiod_pin_configure(chip, ROW_PINS[i], GPIOD_PIN_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure row pin %d: %s\n", ROW_PINS[i], gpiod_get_name(chip));
            gpiod_chip_close(chip);
            return;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        ret = gpiod_pin_configure(chip, COL_PINS[i], GPIOD_PIN_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure column pin %d: %s\n", COL_PINS[i], gpiod_get_name(chip));
            gpiod_chip_close(chip);
            return;
        }
    }

    gpiod_chip_close(chip);
}

// Signal handler to clean up GPIO on SIGINT or SIGTERM
void handle_signal(int signum) {
    cleanup_gpios();
    exit(EXIT_SUCCESS);
}

// Function to draw a single column
void draw_column(int column) {
    // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
    for (int i = 0; i < NUM_COLS; i++) {
        if (i != column) {
            gpiod_pin_write(chip, COL_PINS[i], 1); // HIGH
        }
    }

    // Set the column cathode LOW to light the LEDs
    gpiod_pin_write(chip, COL_PINS[column], 0); // LOW

    // Set the corresponding row anodes HIGH to light the LEDs
    for (int i = 0; i < NUM_ROWS; i++) {
        if (i == (column % NUM_ROWS)) {
            gpiod_pin_write(chip, ROW_PINS[i], 1); // HIGH
        }
    }

    // Wait for 150ms delay
    delay_ms(DELAY_MS);
}

// Function to delay for a specified number of milliseconds
void delay_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

