        ret = gpiod_pin_configure(chip, COL_PINS[i], GPIOD_PIN_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to configure column pin %d: %s\n", COL_PINS[i], gpiod_get_name(chip));
            gpiod_chip_close(chip);
            return;
        }
    }

    gpiod_chip_close(chip);
}

// Signal handler to clean up GPIO on SIGINT or SIGTERM
