    exit(EXIT_SUCCESS);
}

// Function to draw a single column
void draw_column(int column) {
    // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
    for (int i = 0; i < NUM_COLS; i++) {
        if (i != column) {
            gpiod_pin_write(chip, COL_PINS[i], 1); // HIGH
        }
    }

    // Set the column cathode LOW to light the LEDs
    gpiod_pin_write(chip, COL_PINS[column], 0); // LOW

    // Set the corresponding row anodes HIGH to light the LEDs
    for (int i = 0; i < NUM_ROWS; i++) {
        if (i == (column % NUM_ROWS)) {
            gpiod_pin_write(chip, ROW_PINS[i], 1); // HIGH
        }
    }

    // Wait for 150ms delay
    delay_ms(DELAY_MS);
}

// Function to delay for a specified number of milliseconds
void delay_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000;
    nanosleep(&ts, NULL);
}
