#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>

#define I2C_ADDR 0x40 // Assuming the MLX75031 is at address 0x40
#define I2C_DEVICE "/dev/i2c-1" // Raspberry Pi Zero W I2C bus

// Function prototypes
void init_sensor();
void read_distance(int fd);
void handle_interrupt(int signum);
void cleanup();

int main() {
    // Initialize global variables
    FILE *depth_log = NULL;
    int i2c_fd = -1;
    int attempt = 0;

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Attempt to read distance every 100ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 100 / 1000;
        ts.tv_nsec += (100 - (100 % 1000)) * 1000000;

        // Attempt to read distance
        attempt++;
        if (attempt > 5) {
            fprintf(stderr, "Failed to communicate with sensor after 5 attempts.\n");
            break;
        }

        init_sensor();
        read_distance(i2c_fd);

        // Write to CSV file
        if (depth_log == NULL) {
            // Create CSV file if it doesn't exist
            depth_log = fopen("depth_log.csv", "w");
            if (depth_log == NULL) {
                perror("Failed to open CSV file");
                exit(EXIT_FAILURE);
            }
            fprintf(depth_log, "timestamp,depth\n");
            fflush(depth_log);
        }
        fprintf(depth_log, "%ld,%ld\n", ts.tv_sec, (long)read_distance(i2c_fd));
        fflush(depth_log);

        // Close file and I2C handle on SIGINT
        if (SIGINT == sa.sa_handler) {
            cleanup();
            break;
        }
    }

    // Cleanup on normal exit
    cleanup();

    return 0;
}

// Function to initialize the sensor
void init_sensor() {
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Verify I2C bus open
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // No specific driver library used, perform raw I2C transactions
}

// Function to read distance from the sensor
int read_distance(int fd) {
    int ret;
    uint8_t buf[2];

    // Send start condition
    ret = write(fd, &I2C_START, 1);
    if (ret != 1) {
        perror("Failed to send start condition");
        return -1;
    }

    // Write address and read command
    ret = write(fd, &I2C_ADDR, 1);
    if (ret != 1) {
        perror("Failed to write address");
        return -1;
    }
    ret = write(fd, &I2C_READ_CMD, 1);
    if (ret != 1) {
        perror("Failed to write read command");
        return -1;
    }

    // Read response
    ret = read(fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read response");
        return -1;
    }

    // Check if the read was successful
    if (buf[0] != I2C_ACK) {
        // Sensor did not acknowledge, return -1
        return -1;
    }

    // Read the distance data
    ret = read(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to read distance data");
        return -1;
    }

    // Distance data is in the first byte of the response
    return buf[0];
}

// Signal handler for SIGINT
void handle_interrupt(int signum) {
    // Perform cleanup and exit
    fprintf(stderr, "SIGINT received, performing graceful shutdown...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    if (depth_log != NULL) {
        fclose(depth_log);
        depth_log = NULL;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// I2C control commands
#define I2C_START 0b00010000
#define I2C_READ_CMD 0b00000001
#define I2C_ACK 0b00000010

