#define SI1145_I2C_ADDR 0x5A // Default I2C address for Si1145
#define SI1145_REG_PROXIMITY 0x00 // Proximity sensor register
#define SI1145_REG_AMBIENT_LIGHT 0x01 // Ambient light sensor register

FILE *logFile = NULL;
int i2cDev = -1;
si1145_t *sensor = NULL;

void setup_si1145(si1145_t *sensor) {
    if (si1145_init(sensor, SI1145_I2C_ADDR) != SI1145_OK) {
        fprintf(stderr, "Failed to initialize Si1145 sensor.\n");
        exit(1);
    }
}

void handle_signal(int signum) {
    if (sensor != NULL) {
        si1145_stop(sensor);
        si1145_deinit(sensor);
    }

    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }

    printf("SIGINT received. Closing I2C and terminating.\n");
    gpiod_i2c_stop(i2cDev);
    gpiod_i2c_unexport(i2cDev);
    sensor = NULL;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus 1
    i2cDev = gpiod_i2c_open(1, GPIOD_OPEN_READONLY);
    if (i2cDev == -1) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        exit(1);
    }

    // Initialize the sensor
    sensor = si1145_create();
    if (sensor == NULL) {
        fprintf(stderr, "Failed to create Si1145 sensor instance.\n");
        exit(1);
    }

    setup_si1145(sensor);

    // Open log file
    logFile = fopen("biometric_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file 'biometric_log.txt'.\n");
        exit(1);
    }

    time_t now = time(NULL);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);

    while (1) {
        // Read proximity and ambient light
        uint16_t proximity = si1145_read(sensor, SI1145_REG_PROXIMITY);
        uint16_t ambient_light = si1145_read(sensor, SI1145_REG_AMBIENT_LIGHT);

        // Append to log file
        fprintf(logFile, "%s, Proximity: %hu, Ambient Light: %hu\n", timestamp, proximity, ambient_light);

        // Sleep for 500ms
        sleep(0.5);

        // Check for SIGINT
        if (sigpending(&sa.sa_mask) != 0) {
            // Handle SIGINT
            handle_signal(SIGINT);
        }
    }

    // Clean up on exit
    if (sensor != NULL) {
        si1145_stop(sensor);
        si1145_deinit(sensor);
        sensor = NULL;
    }

    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }

    gpiod_i2c_close(i2cDev);
    gpiod_i2c_unexport(i2cDev);

