    if (i2cDev == -1) {
        fprintf(stderr, "Failed to open I2C bus 1.\n");
        exit(1);
    }

    // Initialize the sensor
    sensor = si1145_create();
    if (sensor == NULL) {
        fprintf(stderr, "Failed to create Si1145 sensor instance.\n");
        exit(1);
    }

    setup_si1145(sensor);

    // Open log file
    logFile = fopen("biometric_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file 'biometric_log.txt'.\n");
        exit(1);
    }

    time_t now = time(NULL);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);

    while (1) {
