        sleep(0.5);

        // Check for SIGINT
        if (sigpending(&sa.sa_mask) != 0) {
            // Handle SIGINT
            handle_signal(SIGINT);
        }
    }

    // Clean up on exit
    if (sensor != NULL) {
        si1145_stop(sensor);
        si1145_deinit(sensor);
        sensor = NULL;
    }

    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }

    gpiod_i2c_close(i2cDev);
    gpiod_i2c_unexport(i2cDev);

    return 0;
}
