}

// Function to detect a falling edge on the IR sensor
void detect_falling_edge(int gpio) {
    // Read the current value of the sensor
    int current_value = gpiod_read(gpio);

    // Check if the sensor value has changed from HIGH to LOW
    if (current_value == 0 && gpiod_get_last_value(gpio) == 1) {
        // Write detection to log file
        char log_entry[256];
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);

        // Format the log entry
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%SZ Object detected", &tm_now);

        // Open the log file for appending
        FILE *log_file = fopen("proximity.log", "a+");
        if (!log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }

        // Write the log entry
        fprintf(log_file, "%s\n", log_entry);

        // Close the log file
        fclose(log_file);

        // Reset the last value for the next detection
        gpiod_set_last_value(gpio, 0);
    }
}

