void setup_gpios(void) {
    int ret;

    // Initialize GPIO
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set TRIGGER pin as output
    ret = gpiod_direction_output(gpiod_get_index(TRIGGER_PIN), 1);
    if (ret != 0) {
        fprintf(stderr, "Failed to set TRIGGER pin as output: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set ECHO pin as input
    ret = gpiod_direction_input(gpiod_get_index(ECHO_PIN));
    if (ret != 0) {
        fprintf(stderr, "Failed to set ECHO pin as input: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins for 5V logic level shift
    ret = gpiod_set_direction(gpiod_get_index(TRIGGER_PIN), GPIO_ACTIVE_LOW);
    if (ret != 0) {
        fprintf(stderr, "Failed to set TRIGGER pin direction: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_direction(gpiod_get_index(ECHO_PIN), GPIO_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ECHO pin direction: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set up voltage divider
    ret = gpiod_set_pull_mode(gpiod_get_index(ECHO_PIN), GPIO_PULL_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ECHO pin pull mode: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

void send_trigger_pulse(void) {
    int ret;

    // Trigger pulse
    ret = gpiod_write(gpiod_get_index(TRIGGER_PIN), 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to trigger pulse: %s\n", gpiod_errstr(ret));
        return;
    }

    // Wait for 10 microseconds
    usleep(10000);
    ret = gpiod_write(gpiod_get_index(TRIGGER_PIN), 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to deactivate trigger: %s\n", gpiod_errstr(ret));
    }
}

void read_echo(void) {
    int ret;
    unsigned long start_time, echo_time;

    // Start timer
    start_time = micros();

    // Send trigger pulse
    send_trigger_pulse();

    // Wait for echo to rise
    while ((ret = gpiod_read(gpiod_get_index(ECHO_PIN))) == 0) {
        if (micros() - start_time > 30000) {
            fprintf(stderr, "Echo not detected within 30ms, timeout.\n");
            return;
        }
        usleep(100);
    }

    // Record the time when echo is detected
    echo_time = micros();

    // Wait for echo pulse width
    while ((ret = gpiod_read(gpiod_get_index(ECHO_PIN))) == 1) {
        if (micros() - echo_time > 30000) {
            fprintf(stderr, "Echo pulse width timeout.\n");
            return;
        }
        usleep(100);
    }

    // Compute distance
    float distance = (echo_time / 58.0) * 34300.0; // Speed of sound in air (approx. 34300 m/s) * time / 2
    distance /= 1000.0; // Convert to cm

    // Check distance validity
    if (distance < 0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %f cm\n", distance);
        return;
    }
}

void handle_sigint_sigterm(int signum) {
    if (logFile != NULL) {
        fclose(logFile);
        logFile = NULL;
    }

    // Release GPIO resources
    gpiod_cleanup();

    fprintf(stderr, "Graceful shutdown triggered. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main(void) {
    setup_gpios();

    while (1) {
        read_echo();
        if (distance < MIN_DISTANCE) {
            snprintf(logMessage, sizeof(logMessage), "Time to water the plant! Distance: %.1f cm at %Y-%m-%dT%H:%M:%S", distance, localtime_r(&time(NULL), &tm));
            fprintf(logFile, "%s\n", logMessage);
        } else {
            snprintf(logMessage, sizeof(logMessage), "Distance: %.1f cm at %Y-%m-%dT%H:%M:%S", distance, localtime_r(&time(NULL), &tm));
            fprintf(logFile, "%s\n", logMessage);
        }

        // Check for signals
        if (signal(SIGINT, handle_sigint_sigterm) == SIG_ERR || signal(SIGTERM, handle_sigint_sigterm) == SIG_ERR) {
            fprintf(stderr, "Failed to install signal handlers.\n");
            exit(EXIT_FAILURE);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    return 0;
}
