#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <ctype.h>
#include <signal.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDRESS 0x4C
#define PROXIMITY_REGISTER 0x00

volatile bool running = true;

void handle_signal(int signum) {
    running = false;
}

int main() {
    // Initialize GPIO and I2C
    int i2c_fd;
    struct gpiod_dir *i2c_dir;
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (gpiod_open(&i2c_dir, I2C_DEVICE) < 0) {
        perror("Failed to open GPIO device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open CSV file for appending
    char csv_file_path[100] = "heartrate.csv";
    FILE *csv_file = fopen(csv_file_path, "a+");
    if (!csv_file) {
        perror("Failed to open CSV file");
        fclose(i2c_fd);
        gpiod_stop(i2c_dir);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Convert timestamp to ISO 8601 string
        time_t now = time(NULL);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Read proximity data register
        uint8_t proximity_data;
        if (i2c_smbus_read_byte_data(i2c_fd, SENSOR_ADDRESS, PROXIMITY_REGISTER) < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            continue;
        }

        // Convert proximity data to BPM
        // Assuming a calibration factor of 1 for simplicity
        int bmp = proximity_data;

        // Append to CSV file
        fprintf(csv_file, "%s,%d\n", timestamp, bmp);
        fflush(csv_file);

        // Sleep for 100ms
        usleep(100000);
    }

    // Close resources
    fclose(csv_file);
    gpiod_stop(i2c_dir);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

