#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <stdint.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER_PIN 23

// Constants for VL53L0X register addresses
#define REG_STATUS          0x00
#define REG_INTERRUPT_STATUS 0x01

// Function prototypes
void init_gpiod();
void init_i2c();
void cleanup();
void handle_sigint(int signum);
void measure_distance();
void write_to_log_file(const char *timestamp, double distance_mm);

int main() {
    srand(time(NULL));

    // Initialize GPIO and I2C
    init_gpiod();
    init_i2c();

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        measure_distance();
        write_to_log_file(time(NULL), (double)gpiod_get_value_raw(GPIO_TRIGGER_PIN));
    }

    // Cleanup on SIGINT
    cleanup();

    return 0;
}

// Function to initialize GPIO
void init_gpiod() {
    int ret;

    // Initialize GPIO driver
    ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_get_error_string());
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 17 as input with falling edge trigger and pull-up
    ret = gpiod_set_data_direction(GPIO_TRIGGER_PIN, GPIOD_DIR_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO 17 direction: %s\n", gpiod_get_error_string());
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_pull_up_down(GPIO_TRIGGER_PIN, GPIOD_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO 17: %s\n", gpiod_get_error_string());
        exit(EXIT_FAILURE);
    }
}

// Function to initialize I2C
void init_i2c() {
    int fd;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening I2C bus 1: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Check if sensor is present
    uint8_t data[1];
    if (write(fd, data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L0X: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Sensor present check (assuming the sensor responds with 0x00)
    if (data[0] != 0x00) {
        fprintf(stderr, "VL53L0X sensor not found.\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set I2C address and enable I2C communication
    i2c_smbus_write_byte_data(fd, VL53L0X_ADDR, I2C_SLAVE);
    if (i2c_smbus_write_byte_data(fd, VL53L0X_ADDR, 0x20) != 1) {
        fprintf(stderr, "Error writing to VL53L0X: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    close(fd);

    // Release GPIO resources
    gpiod_exit();
}

// SIGINT handler
void handle_sigint(int signum) {
    // Graceful shutdown
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to measure distance
void measure_distance() {
    uint8_t data[2];
    int ret;

    // Write to trigger the measurement
    ret = gpiod_set_value(GPIO_TRIGGER_PIN, 0); // Set GPIO 17 to low
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO 17: %s\n", gpiod_get_error_string());
