    // Initialize GPIO
    setup_gpios();

    // Handle SIGINT
    signal(SIGINT, handle_signal);

    FILE* log_file = fopen("obstacle_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    char buffer[128];
    time_t now;
    struct tm timeinfo;
    while (1) {
        // Read sensors and log data
        read_sensors_and_log(1, log_file);
        read_sensors_and_log(2, log_file);

        // Sleep for 100 milliseconds
        usleep(100000);

        // Update timestamp
        now = time(NULL);
        localtime_r(&now, &timeinfo);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);

        fprintf(log_file, "Sensor 1: %s, Sensor 2: %s\n", buffer, buffer);
    }

    // Clean up
    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    int rc;

    // Initialize GPIO
    rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpiod_errstr(rc));
        return;
    }

    // Set GPIO pins for sensor 1 and sensor 2
    rc = gpiod_export SENSOR_1_GPIO_NUM, GPIOD_OUT_INIT_LOW;
    if (rc != 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", SENSOR_1_GPIO_NUM, gpiod_errstr(rc));
        return;
    }

    rc = gpiod_export SENSOR_2_GPIO_NUM, GPIOD_OUT_INIT_LOW;
    if (rc != 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", SENSOR_2_GPIO_NUM, gpiod_errstr(rc));
        return;
    }

    // Set GPIO pins to output mode
    rc = gpiod_direction_output(SENSOR_1_GPIO_NUM, 1);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", SENSOR_1_GPIO_NUM, gpiod_errstr(rc));
        return;
    }

    rc = gpiod_direction_output(SENSOR_2_GPIO_NUM, 1);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", SENSOR_2_GPIO_NUM, gpiod_errstr(rc));
        return;
    }
}

