    if (value == 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", sensor, gpiod_errstr(gpiod_get(sensor)));
        return;
    }

    // Log the binary reading
    fprintf(log_file, "Sensor %d: %d\n", sensor, value);
