int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len);
void cleanup();

// Main function
int main() {
    // Initialize I2C
    i2c_init();

    // Open the log file for appending
    int log_fd = fopen(FILE_PATH, "a+");
    if (log_fd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // SIGINT handler
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = cleanup;
    sigemptyset(&sigint_handler.sa_mask);
    sigint_handler.sa_flags = 0;
    if (sigaction(SIGINT, &sigint_handler, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }

    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Attempt to read proximity and ambient light data
        uint8_t proximity_data[1];
        uint8_t ambient_light_data[1];

        for (int i = 0; i < 3; ++i) {
            int proximity_ret = i2c_read(SI1182_ADDR, SI1182_REG_PROXIMITY, proximity_data, 1);
            if (proximity_ret == 0) {
                break;
            }

            // Retry if read failed
            usleep(1000);
        }

        for (int i = 0; i < 3; ++i) {
            int ambient_light_ret = i2c_read(SI1182_ADDR, SI1182_REG_AMBIENT_LIGHT, ambient_light_data, 1);
            if (ambient_light_ret == 0) {
                break;
            }

            // Retry if read failed
            usleep(1000);
        }

        if (i2c_read(SI1182_ADDR, 0x00, NULL, 0) != 0) {
            // Bus error, log an error message
            fprintf(log_fd, "Error: I2C bus error detected.\n");
        } else {
            // Successfully read bus status
            uint8_t status = i2c_read(SI1182_ADDR, 0x00, NULL, 1)[0];
            if (status & 0x01) {
                // Sensor not present
                fprintf(log_fd, "Warning: Si1182 sensor not detected.\n");
            } else {
                // Sensor present and operational
                fprintf(log_fd, "Proximity: %hu, Ambient Light: %hu\n", proximity_data[0], ambient_light_data[0]);
            }
        }

        // Write to log file
        fprintf(log_fd, "%s", timestamp);

        // Sleep for 500ms
        usleep(SAMPLE_INTERVAL_MS * 1000);

        // Close and release resources on SIGINT
    }

    // Close log file and release resources
    fclose(log_fd);
    i2c_cleanup();

    return EXIT_SUCCESS;
}

// I2C initialization function
void i2c_init() {
    int i2c_fd = -1;
    struct i2c_dev *i2c_dev;

    // Open I2C bus 1
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return;
    }

    // Create I2C device structure
    i2c_dev = i2c_new_device(i2c_fd, SI1182_ADDR);
    if (!i2c_dev) {
        perror("Failed to create I2C device");
        close(i2c_fd);
        return;
    }

    // Set I2C device options
    i2c_set_timeout(i2c_dev, 1000); // 1 second timeout
}

// I2C write function
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data) {
    int ret = i2c_transfer(i2c_dev, &addr, 1, &reg, 1, &data, 1);
    if (ret < 1) {
        perror("I2C write failed");
        return -1;
    }
    return ret;
}

// I2C read function
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = i2c_transfer(i2c_dev, &addr, 1, &reg, 1, data, len);
    if (ret < len) {
        perror("I2C read failed");
        return -1;
    }
    return ret;
}

