#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define I2C_BUS_NUM 1
#define GPIO_PIN_NUM 17
#define THRESHOLD_DEFAULT 100

#define WHO_AM_I_REG 0x0F
#define TOF_REG 0x20

int main(int argc, char **argv) {
    // Check if the required number of arguments is provided
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Parse the threshold from the command line
    int threshold = atoi(argv[1]);

    // Initialize GPIO
    int gpio_fd = gpiod_open(GPIO_PIN_NUM, GPIOD_OPEN_READ);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Initialize libgpiod GPIO context
    struct gpiod_cdev *gpio_context = gpiod_get_cdev(gpio_fd);
    if (!gpio_context) {
        perror("gpiod_get_cdev");
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO pin as output
    if (gpiod_direction_output(gpio_context, GPIO_PIN_NUM, 1) < 0) {
        perror("gpiod_direction_output");
        gpiod_put_cdev(gpio_context);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    int i2c_fd = i2c_open(I2C_BUS_NUM, I2C_FLAG_DEFAULT);
    if (i2c_fd < 0) {
        perror("i2c_open");
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Open the log file for appending
    char log_filename[100] = "tof_log.txt";
    FILE *log_file = fopen(log_filename, "a+");
    if (!log_file) {
        perror("fopen");
        i2c_close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Read WHO_AM_I register to verify sensor presence
    uint8_t whoami;
    if (i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        fclose(log_file);
        i2c_close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }
    whoami = (uint8_t)i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG);
    if (whoami != 0x58) {
        fprintf(stderr, "Invalid WHO_AM_I value 0x%X\n", whoami);
        fclose(log_file);
        i2c_close(i2c_fd);
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read TOF distance measurement
        uint32_t tof_distance;
        if (i2c_smbus_read_word_data(i2c_fd, TOF_REG) != 0) {
            fprintf(stderr, "Error reading TOF distance\n");
            fclose(log_file);
            i2c_close(i2c_fd);
            gpiod_close(gpio_fd);
            return EXIT_FAILURE;
        }
        tof_distance = (uint32_t)i2c_smbus_read_word_data(i2c_fd, TOF_REG);

        // Check if distance is below threshold
        if (tof_distance < threshold) {
            // Light up the LED
            gpiod_set_value(gpio_context, GPIO_PIN_NUM, 1);
            // Log the reading with timestamp
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "Distance: %u mm at %s\n", tof_distance, timestamp);
        } else {
            // Turn off the LED
            gpiod_set_value(gpio_context, GPIO_PIN_NUM, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Cleanup on exit
    gpiod_put_cdev(gpio_context);
    gpiod_close(gpio_fd);
    i2c_close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

