#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define SENSOR_ADDR 0x20 // Omron B5L-LD50-07050 I2C address
#define COMMAND_FRAME 0x01 // Command frame for measurement request
#define RESPONSE_LENGTH 15 // Length of the response frame
#define DISTANCE_OFFSET 11 // Offset for distance in response frame
#define DISTANCE_WIDTH 2 // Width of the distance value in response frame

// Function prototypes
void handle_signal(int signum);
int i2c_open_device(const char *device_path);
void i2c_write(int fd, uint8_t *data, size_t len);
void i2c_read(int fd, uint8_t *data, size_t len);
int main(void) {
    // Initialize GPIO and I2C
    gpiod_init();

    // SIGINT handler
    signal(SIGINT, handle_signal);

    // Open I2C device
    int i2c_fd = i2c_open_device("/dev/i2c-1");
    if (i2c_fd == -1) {
        perror("i2c_open_device");
        return EXIT_FAILURE;
    }

    // Variables for sensor communication
    uint8_t command_frame[4] = { COMMAND_FRAME, 0x00, 0x00, 0x00 };
    uint8_t response[RESPONSE_LENGTH];
    uint16_t distance;
    int cycle_count = 10;
    int delay_ms = 100;
    double average_distance = 0.0;
    time_t current_time;
    FILE *log_file = NULL;

    // Main loop
    for (int cycle = 0; cycle < cycle_count; ++cycle) {
        // Send measurement command
        if (i2c_write(i2c_fd, command_frame, sizeof(command_frame)) != sizeof(command_frame)) {
            perror("i2c_write command frame");
            break;
        }

        // Wait for response
        usleep(10000); // 10 ms delay

        // Read response
        if (i2c_read(i2c_fd, response, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
            perror("i2c_read response");
            break;
        }

        // Verify header byte
        if (response[0] != 0x01) {
            fprintf(stderr, "Invalid header byte in response\n");
            break;
        }

        // Extract distance
        distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
        average_distance += distance;

        // Log data if average distance is less than 1000 mm
        if (average_distance < 1000) {
            current_time = time(NULL);
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &current_time);
            log_file = fopen("intrusion_log.txt", "a");
            if (log_file == NULL) {
                perror("fopen intrusion_log.txt");
                break;
            }
            fprintf(log_file, "Timestamp: %s, Average Distance: %.1f mm\n", timestamp, average_distance / cycle_count);
            fclose(log_file);
        }

        // Close I2C file descriptor and release resources on SIGINT
        if (signal(SIGINT, SIG_DFL) == SIG_ERR) {
            perror("Restoring SIGINT handler");
            break;
        }

        // Delay before next cycle
        usleep(delay_ms * 1000);
    }

    // Close I2C file descriptor and release resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Restore SIGINT handler
    signal(SIGINT, handle_signal);

    return EXIT_SUCCESS;
}

// SIGINT handler function
void handle_signal(int signum) {
    // Close I2C file descriptor and log file
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release resources
    gpiod_cleanup();
    exit(EXIT_FAILURE);
}

// Function to open I2C device
int i2c_open_device(const char *device_path) {
    int fd;
    struct gpiod_i2c_chip *chip;

    // Open I2C device
    fd = open(device_path, O_RDWR);
    if (fd == -1) {
        perror("open I2C device");
        return -1;
    }

    // Get I2C chip
    chip = gpiod_i2c_chip_open(fd);
    if (!chip) {
        perror("gpiod_i2c_chip_open");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write to I2C device
void i2c_write(int fd, uint8_t *data, size_t len) {
    struct gpiod_i2c_msg msg;
    int ret;

    msg.addr = SENSOR_ADDR;
    msg.flags = GPIOD_I2C_M_RD;
    msg.len = len;
    msg.data = data;

    ret = gpiod_i2c_transfer(fd, &msg, 1);
    if (ret != len) {
        perror("gpiod_i2c_transfer write");
    }
}

// Function to read from I2C device
void i2c_read(int fd, uint8_t *data, size_t len) {
    struct gpiod_i2c_msg msg;
    int ret;

    msg.addr = SENSOR_ADDR;
    msg.flags = GPIOD_I2C_M_RD;
    msg.len = len;
    msg.data = data;

    ret = gpiod_i2c_transfer(fd, &msg, 1);
    if (ret != len) {
        perror("gpiod_i2c_transfer read");
    }
}

