#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define VL53L0X_I2C_ADDR 0x29
#define RESULT_REG 0x20
#define MODEL_ID_REG 0x21

#define TIMEOUT_MS 100
#define POLL_INTERVAL_MS 500

void cleanup_i2c(struct i2c_client *client) {
    i2c_unregister_client(client);
    close(client->adapter->fd);
    free(client);
}

int main() {
    // Initialize GPIO
    int rc = gpiod_get_device_by_name("i2c-1", NULL);
    if (rc < 0) {
        fprintf(stderr, "Error getting I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C device
    struct i2c_adapter *adapter = gpiod_get_device_by_name("i2c-1", NULL);
    struct i2c_client *client;
    int rc = i2c_new_clientAdapter(adapter, &client);
    if (rc < 0) {
        fprintf(stderr, "Error creating I2C client: %s\n", strerror(errno));
        gpiod_put_device(rc, "i2c-1");
        return EXIT_FAILURE;
    }

    // Verify sensor presence and model ID
    uint8_t model_id;
    rc = i2c_smbus_read_byte_data(client, MODEL_ID_REG, &model_id);
    if (rc < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        i2c_unregister_client(client);
        gpiod_put_device(rc, "i2c-1");
        return EXIT_FAILURE;
    }
    if (model_id != 0x58) { // Expected value for VL53L0X
        fprintf(stderr, "Sensor model ID mismatch. Expected 0x58, got 0x%02X\n", model_id);
        i2c_unregister_client(client);
        gpiod_put_device(rc, "i2c-1");
        return EXIT_FAILURE;
    }

    // Main loop
    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent immediate exit
    signal(SIGTERM, SIG_DFL); // Restore default action for SIGTERM

    while (1) {
        // Poll the sensor
        uint16_t distance;
        rc = i2c_smbus_read_word_data(client, RESULT_REG, &distance);
        if (rc < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            continue; // Continue to next iteration
        }

        // Print distance
        char timestamp[50];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(stdout, "%s Distance: %d mm\n", timestamp, distance / 100.0);

        usleep(TIMEOUT_MS * 1000); // 100 ms delay
    }

    // Cleanup on SIGINT or SIGTERM
    printf("Shutting down...\n");
    i2c_unregister_client(client);
    cleanup_i2c(client);
    exit(EXIT_SUCCESS);
}

