#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c.h>

#define SI1182_ADDR 0x40 // Assuming the Si1182 is at the default address 0x40
#define I2C_BUS_NUM 1   // Using I2C bus 1 (GPIO2 SDA / GPIO3 SCL)

// Function prototypes
void setup_i2c();
void read_proximity_data();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Read proximity data every 500ms
        read_proximity_data();
        usleep(500 * 1000); // 500ms delay
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    int rc;

    // Initialize I2C bus
    rc = i2c_init(I2C_BUS_NUM);
    if (rc < 0) {
        fprintf(stderr, "Error initializing I2C bus: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for I2C bus
    rc = gpiod_get_data_dir(GPIOD_DIR_IN, GPIOD_ID_I2C_SDA, 1);
    if (rc < 0) {
        fprintf(stderr, "Error getting data direction for SDA: %d\n", rc);
        exit(EXIT_FAILURE);
    }
    rc = gpiod_get_data_dir(GPIOD_DIR_IN, GPIOD_ID_I2C_SCL, 1);
    if (rc < 0) {
        fprintf(stderr, "Error getting data direction for SCL: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    // Check if I2C initialization was successful
    if (i2c_check_bus(I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Error checking I2C bus: %d\n", i2c_get_error());
