#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MLX75030_ADDR 0x40

// Function prototypes
void handle_signal(int signum);
int open_i2c_device(const char *device_path);
void close_i2c_device(int fd);
int i2c_write(int fd, const void *buf, size_t size);
int i2c_read(int fd, void *buf, size_t size);

int main() {
    int fd;
    struct sigaction sa;
    struct timeval tv;
    long tv_ms = 500;
    char buffer[1]; // Assuming the sensor only sends a single byte for simplicity

    // Set up signal handler for SIGINT and SIGTERM
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Attempt to open the I2C device
    fd = open_i2c_device(I2C_DEVICE);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Check if the device is present and set as the I2C slave
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close_i2c_device(fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Prepare for sleep
        tv.tv_sec = tv_ms / 1000;
        tv.tv_usec = (tv_ms % 1000) * 1000;

        // Attempt to read from the sensor
        if (i2c_read(fd, buffer, 1) == -1) {
            perror("Failed to read from sensor");
            continue; // Continue to next cycle
        }

        // Print the distance measurement
        printf("Distance: %d mm\n", buffer[0]);

        // Sleep for 500 ms
        nanosleep(&tv, NULL);
    }

    // Close the I2C file descriptor on exit
    close_i2c_device(fd);

    return 0;
}

// Signal handler to close I2C file descriptor and exit gracefully
void handle_signal(int signum) {
    close_i2c_device(-1); // Close the file descriptor even if it's -1 (already closed)
    exit(0); // Exit with status 0
}

// Function to open the I2C device
int open_i2c_device(const char *device_path) {
    int fd = open(device_path, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

// Function to close the I2C file descriptor
void close_i2c_device(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

// Function to write to the I2C device
int i2c_write(int fd, const void *buf, size_t size) {
    if (ioctl(fd, I2C_WRITE, buf) == -1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read from the I2C device
int i2c_read(int fd, void *buf, size_t size) {
    if (ioctl(fd, I2C_READ, buf) == -1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

