void read_opt3101(uint8_t reg);
void handle_signal(int signum);

int main() {
    // Initialize GPIO and I2C
    if (gpiod_open() < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    if (i2c_check_driver_available("i2c-bcm2708") < 0) {
        fprintf(stderr, "I2C driver not available.\n");
        exit(EXIT_FAILURE);
    }

    setup_i2c();

    // Install signal handler for SIGINT (Ctrl-C)
    signal(SIGINT, handle_signal);

    while (1) {
        // Read OPT3101 every 500ms
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 500000 };
        if (nanosleep(&timeout, NULL) < 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }

        read_opt3101(OPT3101_REG_TIME_OF_FLIGHT);
        read_opt3101(OPT3101_REG_AMBIENT_LIGHT);
        read_opt3101(OPT3101_REG_ERROR_FLAGS);

        // Check for errors and print results
        if (read_opt3101(OPT3101_REG_ERROR_FLAGS) & 0x01) {
            printf("Error detected on OPT3101.\n");
        }

        printf("Distance: %u cm\n", read_opt3101(OPT3101_REG_TIME_OF_FLIGHT) / 100);
        printf("Ambient Light: %u lux\n", read_opt3101(OPT3101_REG_AMBIENT_LIGHT));
    }

    // Clean up resources on exit
    close(i2c_devfd);
    gpiod_close();

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    int i2c_devfd = -1;
    struct i2c_dev *i2c_dev;

    // Open I2C bus
    i2c_devfd = open("/dev/i2c-1", O_RDWR);
    if (i2c_devfd < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    // Get I2C device structure
    i2c_dev = i2c_get_device(i2c_devfd, I2C_ADDR);
    if (!i2c_dev) {
        perror("i2c_get_device");
        exit(EXIT_FAILURE);
    }

    // Enable I2C clock stretching
    i2c_set_option(i2c_dev, I2C_OPT_CLOCK_STRETCHING);
}

// Function to read from OPT3101
void read_opt3101(uint8_t reg) {
    uint8_t buf[2];

    // Write register address
    i2c_smbus_write_byte_data(i2c_dev, I2C_ADDR, reg);

    // Read data
    if (i2c_smbus_read_byte_data(i2c_dev, I2C_ADDR, reg) != 0) {
        perror("i2c_smbus_read_byte_data");
        exit(EXIT_FAILURE);
    }

    buf[0] = i2c_smbus_read_byte_data(i2c_dev, I2C_ADDR);
    buf[1] = 0; // Assuming the OPT3101 sends 1 byte of data

    // Handle data
    switch (reg) {
        case OPT3101_REG_TIME_OF_FLIGHT:
            printf("Distance: %u cm\n", buf[0] / 100);
            break;
        case OPT3101_REG_AMBIENT_LIGHT:
            printf("Ambient Light: %u lux\n", buf[0]);
            break;
        case OPT3101_REG_ERROR_FLAGS:
            if (buf[0] & 0x01) {
                printf("Error detected on OPT3101.\n");
            }
            break;
        default:
            printf("Unknown register read.\n");
    }
}

