#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN    18

// HC-SR04 operates at 5V, Raspberry Pi GPIO is 3.3V tolerant.
// A 1kΩ resistor is recommended on the echo line to protect the Pi.
// This is handled within the gpiod library call.

// Constants for HC-SR04
#define MAX_RANGE_MS 200

// Function prototypes
void setup_gpiod();
void read_distance();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Attempt to initialize gpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errmsg());
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    setup_gpiod();

    // Main loop
    while (1) {
        read_distance();
        sleep(1); // Read once per second
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize GPIO pins
void setup_gpiod() {
    // Initialize GPIO pins
    gpiod_set_data_direction(TRIGGER_PIN, GPIO_DIR_OUT);
    gpiod_set_data_direction(ECHO_PIN, GPIO_DIR_IN);

    // Set trigger pin to output
    gpiod_set_value(TRIGGER_PIN, 1);

    // Set echo pin to input
    gpiod_set_pull_mode(ECHO_PIN, GPIO_PULLDOWN);
}

// Function to read distance using HC-SR04
void read_distance() {
    // Trigger the sensor
    gpiod_set_value(TRIGGER_PIN, 0);
    usleep(10000); // 10 µs pulse

    // Wait for echo
    struct timespec timeout = { 0, MAX_RANGE_MS * 1000000 }; // 200 ms timeout
    while (1) {
        if (gpiod_get_value(ECHO_PIN) == 1) {
            // Echo detected
            break;
        }

        // Check if timeout occurred
        if (clock_gettime(CLOCK_REALTIME, &timeout) && timeout.tv_sec > 0) {
            fprintf(stderr, "Echo timeout after %ld ms\n", timeout.tv_sec * 1000);
            return;
        }
    }

    // Read pulse duration
    uint32_t pulse_duration = 0;
    gpiod_get_value(ECHO_PIN, &pulse_duration);

    // Check if pulse duration is valid
    if (pulse_duration <= 0 || pulse_duration > 38000) {
