void handle_signals(int signum);
void read_sensor_state(void);
void toggle_buzzer(int state);
void log_state_transition(const char *timestamp, int state);
void cleanup(void);

int main(void) {
    struct gpiod_chip *chip;
    int sensor_pin, buzzer_pin;
    int sensor_state;
    char buffer[256];
    time_t now;

    // Set up GPIOs
    setup_gpios();

    // Main loop
    while (1) {
        // Read sensor state
        read_sensor_state();

        // Check sensor state
        if (sensor_state == SENSOR_LOW) {
            // Obstacle detected, toggle buzzer
            toggle_buzzer(BUZZER_ON);
        } else {
            // No obstacle, turn off buzzer
            toggle_buzzer(BUZZER_OFF);
        }

        // Log state transition
        log_state_transition(now, sensor_state);

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up on exit
    handle_signals(SIGINT);
    handle_signals(SIGTERM);

    cleanup();

    return 0;
}

void setup_gpios(void) {
    // Open GPIO chip
    chip = gpiod_chip_open(GPIOD_CHIP_RASPBERRY_PI_4, GPIOD_OPEN_BY_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    sensor_pin = gpiod_request(chip, SENSOR_GPIO, GPIOD_REQUEST_MODE_INPUT);
    if (sensor_pin < 0) {
        perror("gpiod_request");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_pin = gpiod_request(chip, BUZZER_GPIO, GPIOD_REQUEST_MODE_OUTPUT);
    if (buzzer_pin < 0) {
        perror("gpiod_request");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set buzzer GPIO to active high
    gpiod_direction_output(buzzer_pin, BUZZER_ON);
}

