    int sensor_value;

    // Read sensor state
    sensor_value = gpiod_read(chip, sensor_pin);
    if (sensor_value < 0) {
        perror("gpiod_read");
        return;
    }

    // Sensor presents active-low signal
    sensor_state = sensor_value == SENSOR_HIGH ? SENSOR_LOW : SENSOR_HIGH;
}

