    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s: Sensor state transition to %d\n", formatted_timestamp, state);
    fclose(file);
}

void cleanup(void) {
    // Release GPIO lines
    gpiod_release(sensor_pin);
    gpiod_release(buzzer_pin);

    // Close GPIO chip
    gpiod_chip_close(chip);
}

