#include <string.h>
#include <gpiod.h>
#include <sys/time.h>

#define CH201_I2C_ADDR 0x29
#define CH201_REG_MEASURE 0x00
#define LED_GPIO 18
#define MAX_READ_ATTEMPTS 3

// Function prototypes
void handle_signal(int signum);
void setup_gpiod();
void read_distance_from_ch201(uint8_t *distance);
void blink_led(int on);
void cleanup();

int main() {
    // Initialize GPIO
    setup_gpiod();

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t distance[1];
    struct timeval start, end;
    int blink_state = 0;
    int read_attempts = 0;

    while (1) {
        // Blink LED
        blink_led(blink_state);

        // Attempt to read distance from CH201
        read_attempts = 0;
        do {
            if (read_distance_from_ch201(distance) < 0) {
                // Handle I2C read failure
                if (read_attempts++ >= MAX_READ_ATTEMPTS) {
                    printf("Failed to read from CH201 after %d attempts.\n", read_attempts);
                    break;
                }
                usleep(10000); // 10ms delay
            } else {
                // Successfully read distance
                break;
            }
        } while (read_attempts < MAX_READ_ATTEMPTS);

        // Process distance reading
        gettimeofday(&start, NULL);
        // Assuming distance is in cm and we want to blink faster as distance decreases
        int blink_frequency = 100 / (distance[0] * 10); // Adjust sensitivity as needed
        blink_led(blink_frequency);

        // Log timestamp and distance
        gettimeofday(&end, NULL);
        char buffer[256];
        sprintf(buffer, "Distance: %u cm at %s\n", distance[0], ctime(&end.tv_sec));
        printf("%s", buffer);

        // Clean up and prepare for next iteration
        cleanup();
    }

    // Clean up GPIO on exit
    cleanup();

    return 0;
}

// SIGINT and SIGTERM handler
void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

// Setup GPIO
void setup_gpiod() {
    int led_fd = gpiod_open(LED_GPIO, GPIOD_OPEN_READWRITE);
    if (led_fd < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(led_fd, 1); // Set GPIO 18 to output
}

// Read distance from CH201
int read_distance_from_ch201(uint8_t *distance) {
    int fd = gpiod_open(0, GPIOD_OPEN_I2C);
    if (fd < 0) {
        perror("gpiod_open");
        return -1;
    }

    uint8_t addr = CH201_I2C_ADDR;
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = sizeof(distance),
        .buf = distance
    };

    int ret = i2c_transfer(fd, &msg, 1);
    if (ret != 1) {
        perror("i2c_transfer");
        gpiod_close(fd);
        return -1;
    }

    gpiod_close(fd);
    return 0;
}

// Blink LED
void blink_led(int on) {
    int state = on ? 1 : 0;
    gpiod_set_value(LED_GPIO, state);
    usleep(500000); // 500ms delay for half-cycle blink
}

// Cleanup function
void cleanup() {
    gpiod_close(LED_GPIO);
    gpiod_remove(LED_GPIO);
}

