        .flags = 0,
        .len = 1,
        .buf = (void *)reg
    };

    int ret = i2c_transfer(fd, &msg, 1);
    if (ret < 0) {
        perror("I2C write error");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

