#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>

#define SENSOR_1_GPIO_NUM 17
#define SENSOR_2_GPIO_NUM 27

#define DEBOUNCE_MS 50
#define POLL_MS 10

#define FILE_PATH "proximity_log.txt"
#define EVENT_DETECTED "DETECTED"
#define EVENT_CLEARED "CLEARED"

// Function prototypes
void setup_sensors(gpiod_device *gpiod);
void poll_sensors(gpiod_device *gpiod);
void log_event(gpiod_device *gpiod, int sensor_id, const char *event_type);
void cleanup(gpiod_device *gpiod);

int main(void) {
    gpiod_device *gpiod;
    int sensor_1, sensor_2;
    int status;

    // Initialize GPIO
    gpiod = gpiod_open(GPIOD_DIR_DEV, "gpiochip0");
    if (gpiod == NULL) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins for sensors
    setup_sensors(gpiod);

    // Main loop
    while (1) {
        // Poll sensors
        poll_sensors(gpiod);

        // Log events
        if (sensor_1 != 0) {
            log_event(gpiod, 1, EVENT_DETECTED);
        }
        if (sensor_2 != 0) {
            log_event(gpiod, 2, EVENT_DETECTED);
        }

        // Sleep for 10ms
        usleep(POLL_MS * 1000);
    }

    // Clean up
    cleanup(gpiod);

    gpiod_close(gpiod);

    return EXIT_SUCCESS;
}

// Function to setup GPIO pins for sensors
void setup_sensors(gpiod_device *gpiod) {
    // Check if GPIO pins are available
    if (gpiod_is_valid_pin(gpiod, SENSOR_1_GPIO_NUM)) {
        sensor_1 = gpiod_get_pin(gpiod, SENSOR_1_GPIO_NUM);
        if (gpiod_direction_input(sensor_1)) {
            fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_1_GPIO_NUM);
            return;
        }
    } else {
        fprintf(stderr, "GPIO %d not available\n", SENSOR_1_GPIO_NUM);
        return;
    }

    if (gpiod_is_valid_pin(gpiod, SENSOR_2_GPIO_NUM)) {
        sensor_2 = gpiod_get_pin(gpiod, SENSOR_2_GPIO_NUM);
        if (gpiod_direction_input(sensor_2)) {
            fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_2_GPIO_NUM);
            return;
        }
    } else {
        fprintf(stderr, "GPIO %d not available\n", SENSOR_2_GPIO_NUM);
        return;
    }
}

// Function to poll sensors and debounce
void poll_sensors(gpiod_device *gpiod) {
    int sensor_1_state, sensor_2_state;
    struct timeval now;

    // Get current time
    gettimeofday(&now, NULL);

    // Read sensor states
    if (gpiod_get_value_input_raw(gpiod, sensor_1) == 0) {
        sensor_1_state = 0;
    } else {
        sensor_1_state = 1;
    }

    if (gpiod_get_value_input_raw(gpiod, sensor_2) == 0) {
        sensor_2_state = 0;
    } else {
        sensor_2_state = 1;
    }

    // Debounce
    if (sensor_1_state != last_sensor_1_state) {
        last_sensor_1_state = sensor_1_state;
        if (sensor_1_state == 0) {
            log_event(gpiod, 1, EVENT_CLEARED);
        }
    }

    if (sensor_2_state != last_sensor_2_state) {
        last_sensor_2_state = sensor_2_state;
        if (sensor_2_state == 0) {
            log_event(gpiod, 2, EVENT_CLEARED);
        }
    }

    // Sleep for debounce duration
    usleep(DEBOUNCE_MS * 1000);
}

// Function to log events
void log_event(gpiod_device *gpiod, int sensor_id, const char *event_type) {
    char buffer[256];
    struct tm tm;
    time_t now = time(NULL);

    // Format timestamp
    localtime_r(&now, &tm);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Append sensor ID and event type
    sprintf(buffer + strlen(buffer), "%d-%s", sensor_id, event_type);

    // Open log file for appending
    int log_fd = open(FILE_PATH, O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return;
    }

    // Write to log file
    if (write(log_fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to write to log file");
        close(log_fd);
        return;
    }

    close(log_fd);
}

// Function to cleanup resources
void cleanup(gpiod_device *gpiod) {
    // Release GPIO pins
    if (sensor_1 != 0) {
        gpiod_release_pin(gpiod, sensor_1);
    }
    if (sensor_2 != 0) {
        gpiod_release_pin(gpiod, sensor_2);
    }

    gpiod_close(gpiod);
}

