#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <stdint.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TDF_SLAVE_ADDRESS 0x29
#define MEAS_STATUS_REGISTER 0x00

// Helper function to perform write then read on I2C
int i2c_write_then_read(int fd, uint8_t slave_addr, uint8_t write_reg, uint8_t write_data, uint8_t read_reg, uint8_t *read_data, int timeout_ms) {
    struct timeval timeout;
    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_usec = (timeout_ms % 1000) * 1000;

    if (ioctl(fd, I2C_SLAVE, slave_addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return -1;
    }

    if (write(fd, &write_data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, read_data, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Main function
int main() {
    int fd;
    uint8_t distance;
    struct timeval now;
    char csv_line[256];
    FILE *csv_file;

    // Initialize GPIO library
    if (pigpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_error());
        return 1;
    }

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, TDF_SLAVE_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Initialize time structure
    gettimeofday(&now, NULL);

    // Loop indefinitely
    while (1) {
        // Perform I2C write then read operation
        if (i2c_write_then_read(fd, TDF_SLAVE_ADDRESS, MEAS_STATUS_REGISTER, 0, MEAS_STATUS_REGISTER, &distance, 50000) < 0) {
            fprintf(stderr, "Error reading from TDK CH-101: %s\n", strerror(errno));
            continue; // Skip this sample
        }

        // Convert distance to millimeters
        distance *= 100;

        // Format ISO 8601 timestamp and distance for CSV
        snprintf(csv_line, sizeof(csv_line), "%s,%d", asctime(&now), distance);

        // Open or append to CSV file
        if ((csv_file = fopen("distance_log.csv", "a")) == NULL) {
            fprintf(stderr, "Error opening/append to CSV file: %s\n", strerror(errno));
            continue; // Skip this sample
        }

        // Write to CSV file
        if (fprintf(csv_file, "%s\n", csv_line) == -1) {
            fclose(csv_file);
            fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
            return 1;
        }

        // Close CSV file and wait before next sample
        fclose(csv_file);
        usleep(500000); // 500 ms delay

        // Handle SIGINT and SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
            return 1;
        }
    }

    // Clean up on exit
    close(fd);
    pigpio_cleanup();

    return 0;
}

