#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>

#define MLX75030_I2C_ADDR 0x28 // Default address for MLX75030
#define MLX75030_REG_MEASUREMENT 0x00 // Measurement register

// Function prototypes
void handleSIGINT(int signum);
int i2c_open_and_init();
int i2c_read(uint8_t address, uint8_t reg, uint8_t *data, size_t len);
int main(void);
void cleanup_and_exit(int status);

// Global variables
int i2c_handle = -1;
uint8_t measurement_data[1]; // Assuming single byte measurement for simplicity

// Function to handle SIGINT (Ctrl+C)
void handleSIGINT(int signum) {
    printf("Shutting down due to SIGINT...\n");
    cleanup_and_exit(EXIT_SUCCESS);
}

// Function to open and initialize I2C
int i2c_open_and_init() {
    int ret;
    struct i2c_dev *i2c_dev;

    // Attempt to open I2C device
    ret = i2c_open(1, &i2c_dev);
    if (ret < 0) {
        perror("i2c_open");
        return -1;
    }

    // Initialize the I2C device
    ret = i2c_master_init(i2c_dev);
    if (ret < 0) {
        perror("i2c_master_init");
        i2c_close(i2c_dev);
        return -1;
    }

    return 0;
}

// Function to read from the MLX75030 sensor
int i2c_read(uint8_t address, uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = len,
        .buf = data
    };

    // Attempt to read from the sensor
    ret = i2c_transfer(i2c_dev, &msg, 1);
    if (ret < 0) {
        perror("i2c_transfer");
        return -1;
    }

    return ret == len;
}

// Main function
int main(void) {
    signal(SIGINT, handleSIGINT);

    // Attempt to open and initialize I2C
    if (i2c_open_and_init() < 0) {
        perror("Failed to open I2C");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read measurement from sensor
        if (i2c_read(MLX75030_I2C_ADDR, MLX75030_REG_MEASUREMENT, measurement_data, 1) < 0) {
            // Retry up to 3 times with a delay
            for (int i = 0; i < 3; ++i) {
                usleep(10000); // 10 ms delay
                if (i2c_read(MLX75030_I2C_ADDR, MLX75030_REG_MEASUREMENT, measurement_data, 1) >= 0) {
                    break;
                }
            }

            // If still failed, log error and continue
            if (i == 3) {
                printf("Error reading from MLX75030 sensor.\n");
                continue;
            }

            // Successfully read measurement
            uint8_t measurement = measurement_data[0];
            struct timeval tv;
            gettimeofday(&tv, NULL);

            printf("Timestamp: %ld.%06ld, Measurement: %u\n",
                   tv.tv_sec, tv.tv_usec, measurement);
        }
        usleep(100000); // 100 ms delay
    }

    // Cleanup on exit
    cleanup_and_exit(EXIT_SUCCESS);

    return 0;
}

// Function to clean up and exit
void cleanup_and_exit(int status) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
        i2c_master_exit();
    }

    exit(status);
}

