    // Initialize I2C bus
    gpiod_i2c_bus = gpiod_i2c_new(I2C_BUS_NUMBER);
    if (gpiod_i2c_bus == GPIOD_ERROR) {
        fprintf(stderr, "Failed to initialize I2C bus: %s\n", gpiod_error_string(gpiod_i2c_get_error()));
