#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x52
#define BUZZER_GPIO 22

// Constants for VL53L1X register addresses and commands
#define VL53L1X_REG_CTRL_REG1 0x20
#define VL53L1X_REG_DIST_REG 0x21
#define VL53L1X_CMD_CONT_RANGING 0x00

// Error handling function
void i2c_error_handler(int error) {
    fprintf(stderr, "I2C error: %d\n", error);
    return;
}

// Function to configure and read from VL53L1X
int vl53l1x_init_and_read(uint8_t i2c_bus, uint8_t address) {
    int fd;
    struct i2c_dev *i2c_dev;
    int result;

    // Open I2C bus
    fd = open("/dev/i2c-" STR_TO_I2C_BUS_NAME(i2c_bus), O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        return -1;
    }

    // Create I2C device structure
    i2c_dev = i2c_devfd(fd);

    // Set I2C address
    i2c_set_address(i2c_dev, address);

    // Initialize VL53L1X
    result = i2c_smbus_write_byte_data(i2c_dev, address, VL53L1X_REG_CTRL_REG1);
    if (result != 0) {
        i2c_error_handler(result);
        close(fd);
        return -1;
    }

    // Set continuous ranging mode
    result = i2c_smbus_write_byte_data(i2c_dev, address, VL53L1X_CMD_CONT_RANGING);
    if (result != 0) {
        i2c_error_handler(result);
        close(fd);
        return -1;
    }

    // Return success
    return 0;
}

// Function to read distance from VL53L1X
double vl53l1x_read_distance(int fd) {
    int result;
    uint16_t distance;

    // Write to DIST_REG to initiate a distance measurement
    result = i2c_smbus_write_byte_data(fd, VL53L1X_I2C_ADDR, VL53L1X_REG_DIST_REG);
    if (result != 0) {
        perror("Failed to initiate distance measurement");
        return -1;
    }

    // Read distance
    result = i2c_smbus_read_word_data(fd, VL53L1X_REG_DIST_REG);
    if (result != 2) {
        perror("Failed to read distance");
        return -1;
    }

    // Convert 16-bit distance to millimeters
    distance = (result << 8) | i2c_smbus_read_byte_data(fd, VL53L1X_REG_DIST_REG);
    return distance / 100.0; // Convert to mm
}

// Function to handle buzzer GPIO
void activate_buzzer(int fd) {
    int buzzer_gpio = BCM_GPIO_NUM_TO_BCM_GPIO(BUZZER_GPIO);
    struct gpio_desc *buzzer_desc;

    // Open GPIO
    buzzer_desc = gpio_desc_lookup(buzzer_gpio);
    if (!buzzer_desc) {
        perror("Failed to find buzzer GPIO");
        return;
    }

    // Activate buzzer
    gpio_request(buzzer_desc, "buzzer");
    gpio_set_direction(buzzer_desc, GPIO_OUTPUT_ACTIVE);
    gpio_write(buzzer_desc, 1); // Activate buzzer
}

// Main function
int main() {
    struct sigaction sa;
    int fd_i2c, fd_buzzer;
    bool running = true;

    // Set up signal handler for SIGINT (Ctrl+C)
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C and buzzer
    if ((fd_i2c = open("/dev/i2c-" STR_TO_I2C_BUS_NAME(I2C_BUS), O_RDWR)) == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if ((fd_buzzer = gpio_open(BUZZER_GPIO, GPIO_MODE_OUTPUT, GPIO_FLAG_ACTIVE_LOW)) == -1) {
        perror("Failed to open buzzer GPIO");
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    // Initialize VL53L1X
    if (vl53l1x_init_and_read(I2C_BUS, VL53L1X_I2C_ADDR) != 0) {
        perror("Failed to initialize VL53L1X");
        close(fd_buzzer);
        close(fd_i2c);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read distance
        double distance_mm = vl53l1x_read_distance(fd_i2c);

        // Check if distance is below 100 mm
        if (distance_mm < 100.0) {
            activate_buzzer(fd_buzzer);
        } else {
            gpio_write(fd_buzzer, 0); // Deactivate buzzer
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up resources
    gpio_close(fd_buzzer);
    close(fd_i2c);

    return 0;
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    running = false;
}

// Helper function to convert string to I2C bus number
const char *STR_TO_I2C_BUS_NAME(int bus) {
    switch (bus) {
        case 0: return "0";
        case 1: return "1";
        default: return "Invalid I2C bus";
    }
}

