#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 17
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90

FILE *log_file = NULL;

void setup_log_file() {
    log_file = fopen("sensor_data.log", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_resources() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpiod_free_device(gpiod_get_device(GPIO_NUM_TRIGGER));
    gpiod_free_device(gpiod_get_device(GPIO_NUM_ECHO));
    gpiod_free_device(gpiod_get_device(GPIO_NUM_SERVO));
}

void handle_signal(int signum) {
    // Stop the loop and cleanup resources
    printf("Signal received, stopping...\n");
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        perror("gpiod_init failed");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    struct gpiod_device *trigger_dev = gpiod_get_device(GPIO_NUM_TRIGGER);
    struct gpiod_device *echo_dev = gpiod_get_device(GPIO_NUM_ECHO);
    struct gpiod_device *servo_dev = gpiod_get_device(GPIO_NUM_SERVO);

    if (gpiod_direction_output(trigger_dev, TRIGGER_GPIO, 1) < 0 ||
        gpiod_direction_output(echo_dev, ECHO_GPIO, GPIO_OUTPUT_OPEN_DRAIN) < 0 ||
        gpiod_direction_output(servo_dev, SERVO_GPIO, 1) < 0) {
        perror("Failed to configure GPIO pins");
        cleanup_resources();
        exit(EXIT_FAILURE);
    }

    setup_log_file();

    // SIGINT and SIGTERM handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Issue trigger pulse
        gpiod_set_value(trigger_dev, TRIGGER_GPIO, 1, 10 * 1000); // 10 microseconds

        // Wait for echo
        struct timespec timeout = { 50 * 1000, 0 }; // 50 milliseconds timeout
        int echo_time = gpiod_get_value_time_us(echo_dev, ECHO_GPIO);
        if (echo_time > 0) {
            // Valid echo received
            int distance_cm = (echo_time / (2 * 343)) - MIN_DISTANCE_CM; // Speed of sound in air (~343 m/s)
            int servo_angle = (distance_cm - MIN_DISTANCE_CM) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + SERVO_MIN_ANGLE;

            // Log the reading
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "Distance: %.2f cm, Angle: %d° at %s\n", distance_cm, servo_angle, timestamp);

            // Set servo angle
            gpiod_set_value(servo_dev, SERVO_GPIO, servo_angle);

            // Wait before next measurement
            usleep(200 * 1000); // 200 milliseconds
        } else {
            // Timeout, skip this reading
            continue;
        }
    }

    // Cleanup on normal exit
    cleanup_resources();

    return 0;
}

