    if (ioctl(fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to access I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    i2c_handle = fd;
}

// Function to setup GPIO
void setup_gpiod(void) {
    int gpio_handle;

    // Open GPIO device
    gpio_handle = gpiod_open(GPIO_Buzzer_PIN);
    if (gpio_handle < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
