    if (gpiod_direction_output(gpio_handle, 1) < 0) {
        perror("Failed to set GPIO as output");
        gpiod_close(gpio_handle);
        exit(EXIT_FAILURE);
    }

    // Keep GPIO handle
    (void) gpiod_get_value(gpio_handle); // To ensure the pin is updated
    gpio_handle = (void *)gpio_handle; // Store handle for cleanup
}

// Function to setup POSIX message queue
void setup_msg_queue(void) {
    msg_queue_id = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
    if (msg_queue_id == -1) {
        perror("Failed to create message queue");
        exit(EXIT_FAILURE);
    }
}

