    msg.msg_perm.uid = msg_perm.gid = 0; // Owner and group
    msg.msg_perm.mode = 0644; // Permissions
    msg.msg_lspid = getpid(); // Sender process ID
    msg.msg_lrpid = 0; // Receiver process ID (set to 0 for broadcast)
    msg.msg_stime = msg.msg_rtime = msg.msg_ctime = time(NULL); // Timestamps

    if (msgsnd(msg_queue_id, (void *)&msg, sizeof(msg), 0) < 0) {
        perror("Failed to send message to queue");
        return;
    }
}

