    // Close I2C device
    if (i2c_handle != -1) {
        close(i2c_handle);
        i2c_handle = -1;
    }

    // Close GPIO device
    if (gpio_handle != NULL) {
        gpiod_close(gpio_handle);
        gpio_handle = NULL;
    }

    // Remove message queue
    if (msg_queue_id != -1) {
        msg_unlink(msg_queue_id);
        msg_queue_id = -1;
    }
}

// Signal handler for SIGINT
void signal_handler(int signum) {
    // Clean up resources
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

