#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <gpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define BUZZER_GPIO 22

#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2

volatile uint32_t echo_time = 0;

void setup_gpios(void) {
    int ret;

    // Initialize GPIO library
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set trigger GPIO to output mode
    ret = gpiod_set_data_direction(TRIGGER_GPIO, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger GPIO direction: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set echo GPIO to input mode
    ret = gpiod_set_data_direction(ECHO_GPIO, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error setting echo GPIO direction: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set buzzer GPIO to output mode
    ret = gpiod_set_data_direction(BUZZER_GPIO, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer GPIO direction: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

void send_trigger_pulse(void) {
    gpiod_set_value(TRIGGER_GPIO, 1);
    usleep(10000); // 10 microseconds
    gpiod_set_value(TRIGGER_GPIO, 0);
}

void handle_echo(void) {
    uint32_t current_time;

    // Wait for echo signal
    current_time = micros();
    while (gpiod_get_value(ECHO_GPIO) == 0) {
        if (micros() - current_time > 2000000) { // 2ms timeout
            echo_time = 0; // Reset echo time if no echo is detected
            return;
        }
        current_time = micros();
    }

    echo_time = micros() - current_time; // Capture echo time
}

void measure_distance(void) {
    uint32_t distance_cm;

    // Ensure valid echo time
    if (echo_time == 0) {
        printf("Sensor absent or no echo detected.\n");
        return;
    }

    // Convert echo time to distance
    distance_cm = (echo_time * SPEED_OF_SOUND / 2) / 1000000.0;
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        printf("Invalid reading: distance out of range (%.1f cm)\n", distance_cm);
        return;
    }

    printf("Distance: %.1f cm\n", distance_cm);
}

void buzzer_control(uint32_t distance_cm) {
    if (distance_cm < 30) {
        gpiod_set_value(BUZZER_GPIO, 1); // Activate buzzer
    } else {
        gpiod_set_value(BUZZER_GPIO, 0); // Turn off buzzer
    }
}

void cleanup_resources(void) {
    gpiod_unexport_all();
}

int main(void) {
    struct sigaction sa;
    setup_gpios();

    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        send_trigger_pulse();
        handle_echo();
        measure_distance();
        buzzer_control(echo_time / 1000.0); // Convert to cm and control buzzer

        usleep(100000); // Sleep for 100ms
    }

    // Clean up on SIGINT
    sa.sa_handler = cleanup_resources;
    sigaction(SIGINT, &sa, NULL);

    return 0;
}

