#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24

// GPIO pin numbers correspond to physical pin numbers on the Raspberry Pi 4 Model B.
// Note: The ECHO line is 5V and must be level-shifted or divided for the Pi’s 3.3V tolerance.

// Constants for HC-SR04
#define TRIGGER_HIGH 1
#define TRIGGER_LOW 0
#define ECHO_THRESHOLD 100
#define TIMEOUT_THRESHOLD 30000
#define TIMEOUT_WINDOW 60000

// Function prototypes
void setup_gpiod();
void cleanup_gpiod();
void send_trigger();
void measure_distance(uint32_t rising_tick, uint32_t falling_tick);
void handle_interrupt(uint32_t timestamp);
void handle_signal(int signum);
void log_distance(const char *timestamp, double distance);

// Global variables
gpiod_device *trig_device;
gpiod_device *echo_device;
volatile uint32_t rising_tick = 0;
volatile uint32_t falling_tick = 0;
int is_interrupt_enabled = 0;

// Signal handlers
static void handler(int signum) {
    handle_signal(signum);
}

// Main function
int main() {
    // Initialize GPIO driver
    setup_gpiod();

    // Set up GPIO pins
    trig_device = gpiod_get_device_by_number(TRIGGER_PIN);
    echo_device = gpiod_get_device_by_number(ECHO_PIN);

    // Enable interrupts on the ECHO pin
    if (gpiod_is_valid(trig_device) && gpiod_is_valid(echo_device)) {
        gpiod_enable_interrupt(echo_device, GPIOD_EDGE_FALLING, &handle_interrupt);
        is_interrupt_enabled = 1;
    } else {
        fprintf(stderr, "Error: GPIO devices not valid.\n");
        exit(EXIT_FAILURE);
    }

    // Signal handler registration
    signal(SIGINT, handler);
    signal(SIGTERM, handler);

    // Main loop
    while (1) {
        // Send trigger pulse every 200ms
        send_trigger();
        usleep(200000);

        // Check for valid echo within timeout window
        if (is_interrupt_enabled) {
            uint32_t current_time = gpiod_get_time();
            if (falling_tick != 0 && current_time - rising_tick <= TIMEOUT_WINDOW) {
                measure_distance(rising_tick, falling_tick);
            } else {
                fprintf(stderr, "Warning: Timeout, no valid echo within %dms.\n", TIMEOUT_WINDOW);
            }
            falling_tick = 0; // Reset for next measurement
        } else {
            fprintf(stderr, "Warning: Interrupt not enabled.\n");
        }
    }

    // Clean shutdown on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Cleanup GPIO resources
    cleanup_gpiod();

    return 0;
}

// Function to send trigger pulse
void send_trigger() {
    gpiod_set_value(trig_device, TRIGGER_HIGH);
    usleep(10); // 10us pulse
    gpiod_set_value(trig_device, TRIGGER_LOW);
}

// Function to measure distance
void measure_distance(uint32_t rising_tick, uint32_t falling_tick) {
    uint32_t pulse_duration = falling_tick - rising_tick;

    // Handle tick wraparound
    if (pulse_duration > 0xFFFFFFFF) {
        pulse_duration -= 0xFFFFFFFF;
    }

    // Reject invalid readings
    if (pulse_duration < ECHO_THRESHOLD || pulse_duration > TIMEOUT_THRESHOLD) {
        fprintf(stderr, "Warning: Rejected measurement (%dus) - below threshold or timeout.\n", pulse_duration);
    } else {
        // Calculate distance
        double distance = (pulse_duration * 0.034 / 2.0); // Speed of sound in air (approx. 0.034 m/us)

        // Log distance with timestamp
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        log_distance(timestamp, distance);
    }
}

// Interrupt handler for falling edge on ECHO pin
void handle_interrupt(uint32_t timestamp) {
    rising_tick = timestamp; // Capture rising edge timestamp
    gpiod_clear_interrupt(echo_device); // Clear interrupt flag
}

// Signal handler function
void handle_signal(int signum) {
    // Perform clean shutdown
    if (is_interrupt_enabled) {
        gpiod_disable_interrupt(echo_device);
        is_interrupt_enabled = 0;
    }

    // Close log file
    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpiod_remove_device(trig_device);
    gpiod_remove_device(echo_device);

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Setup GPIO driver
void setup_gpiod() {
    int error = gpiod_init();
    if (error) {
        fprintf(stderr, "Error initializing gpiod: %s\n", gpiod_get_error_string());
        exit(EXIT_FAILURE);
    }
}

// Cleanup GPIO resources
void cleanup_gpiod() {
    gpiod_remove_device(trig_device);
    gpiod_remove_device(echo_device);
}

// Log distance to file and stdout
void log_distance(const char *timestamp, double distance) {
    char buffer[256];
    sprintf(buffer, "%s, %.2f m", timestamp, distance);
    fprintf(stderr, "%s\n", buffer); // Output to stdout
    fprintf(log_file, "%s\n", buffer); // Append to distance_log.txt
}

