#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INT_PIN 24
#define DETECT_THRESHOLD 50000  // 50 cm in microseconds
#define Hysteresis_THRESHOLD 60000 // 60 cm in microseconds

volatile sig_atomic_t sigIntReceived = 0;
volatile sig_atomic_t sigTermReceived = 0;

void cleanup_resources(void) {
    gpiod_free_pin(SERVO_PIN);
    gpiod_free_pin(VL53L1X_SHUTDOWN_PIN);
    gpiod_free_pin(VL53L1X_INT_PIN);
    gpiod_remove_device("/dev/i2c-1");
}

void handle_signals(int signum) {
    switch (signum) {
        case SIGINT:
            sigIntReceived = 1;
            break;
        case SIGTERM:
            sigTermReceived = 1;
            break;
        default:
            break;
    }
}

int main(void) {
    struct gpiod_dir *dir;
    struct gpiod_cdev *servo_cdev;
    struct gpiod_cdev *shutdown_cdev;
    struct gpiod_cdev *int_pin_cdev;
    struct gpiod_cdev *i2c_bus_cdev;
