    uint8_t model_id;
    rc = i2c_smbus_read_byte_data(i2c_bus_cdev, 0x29); // Read model ID register
    if (rc != 0) {
        fprintf(stderr, "Error reading model ID: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }
    model_id = buffer[0];

    if (model_id != 0x15) { // Check for expected model ID (0x15 for VL53L1X)
        fprintf(stderr, "Unsupported VL53L1X model detected (expected 0x15).\n");
        goto cleanup;
    }

    // Set up GPIO pins
    rc = gpiod_direction_output(servo_cdev, 0); // Close position (0)
    if (rc != 0) {
        fprintf(stderr, "Error setting servo pin direction: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }

    rc = gpiod_set_value(servo_cdev, 0); // Close gate
    if (rc != 0) {
        fprintf(stderr, "Error setting servo value: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }

    // Set up shutdown and interrupt pins
    rc = gpiod_direction_output(shutdown_cdev, 1); // High for shutdown
    if (rc != 0) {
        fprintf(stderr, "Error setting shutdown pin direction: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }

    rc = gpiod_set_value(shutdown_cdev, 1); // High for shutdown
    if (rc != 0) {
        fprintf(stderr, "Error setting shutdown pin value: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }

    rc = gpiod_direction_input(int_pin_cdev); // Set as input
    if (rc != 0) {
        fprintf(stderr, "Error setting interrupt pin direction: %s\n", gpiod_errstr(rc));
        goto cleanup;
    }

    // Install signal handlers
    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    // Main loop
    while (!sigIntReceived && !sigTermReceived) {
        timestamp = time(NULL);
        distance = measure_distance();

        if (distance < DETECT_THRESHOLD && distance > Hysteresis_THRESHOLD) {
            // Object detected within hysteresis range, open gate
            rc = gpiod_set_value(servo_cdev, 1); // Open position (1)
            if (rc != 0) {
                fprintf(stderr, "Error setting servo value to open gate: %s\n", gpiod_errstr(rc));
                goto cleanup;
            }
            fprintf(log_file, "Gate opened at %s, distance: %u cm\n", ctime(&timestamp), distance);
        } else {
            // Close gate if object is outside hysteresis range
            rc = gpiod_set_value(servo_cdev, 0); // Close position (0)
            if (rc != 0) {
                fprintf(stderr, "Error setting servo value to close gate: %s\n", gpiod_errstr(rc));
                goto cleanup;
            }
            fprintf(log_file, "Gate closed at %s, distance: %u cm\n", ctime(&timestamp), distance);
        }
    }

cleanup:
    // Release resources on exit
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close I2C device
    rc = gpiod_close(i2c_bus_cdev);
    if (rc != 0) {
        fprintf(stderr, "Error closing I2C bus: %s\n", gpiod_errstr(rc));
    }

    // Free GPIO pins
    gpiod_free_pin(servo_cdev);
    gpiod_free_pin(shutdown_cdev);
    gpiod_free_pin(int_pin_cdev);
    gpiod_remove_device(i2c_bus_cdev);

    // Clean up GPIO
    gpiod_cleanup();

    // Exit with appropriate status
    return EXIT_SUCCESS;
}

int measure_distance() {
    uint16_t distance;
    // Read distance from VL53L1X
    rc = i2c_smbus_read_word_data(i2c_bus_cdev, 0x34); // Read distance register
    if (rc != 0) {
        fprintf(stderr, "Error reading distance: %s\n", gpiod_errstr(rc));
        return -1; // Return -1 on error
    }
    distance = buffer[0];

    // Convert distance to centimeters
    return distance * 10; // VL53L1X returns distance in millimeters
}
