#define VL53L1X_I2C_BUS 1
#define VL53L1X_ADDR 0x52
#define GPIO_18 18
#define GPIO_19 27

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO
    int gpio18_fd = gpiod_open(GPIO_18, GPIO_OUTPUT);
    int gpio19_fd = gpiod_open(GPIO_19, GPIO_OUTPUT);

    // Initialize VL53L1X sensor
    libvl53l1x_vl53l1x_t *vl53l1x;
    int i2c_fd;
    int ret;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" VL53L1X_I2C_BUS, O_RDWR);

    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Initialize VL53L1X sensor
    ret = libvl53l1x_i2c_init(i2c_fd, VL53L1X_ADDR);

    if (ret != LIBVL53L1X_NO_ERROR) {
        fprintf(stderr, "Failed to initialize VL53L1X: %s\n", libvl53l1x_error_string(ret));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    vl53l1x = libvl53l1x_i2c_open(i2c_fd);

    if (vl53l1x == NULL) {
        fprintf(stderr, "Failed to open VL53L1X device\n");
        libvl53l1x_i2c_exit();
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Perform soft reset and configure timing budget
    ret = libvl53l1x_vl53l1x_soft_reset(vl53l1x);
    if (ret != LIBVL53L1X_NO_ERROR) {
        fprintf(stderr, "Failed to perform soft reset: %s\n", libvl53l1x_error_string(ret));
        libvl53l1x_close(vl53l1x);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure timing budget
    ret = libvl53l1x_vl53l1x_config_timing_budget(vl53l1x, LIBVL53L1X_TIMING_BUDGET_100MS);
    if (ret != LIBVL53L1X_NO_ERROR) {
        fprintf(stderr, "Failed to configure timing budget: %s\n", libvl53l1x_error_string(ret));
        libvl53l1x_close(vl53l1x);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start ranging
    ret = libvl53l1x_vl53l1x_start_ranging(vl53l1x);
    if (ret != LIBVL53L1X_NO_ERROR) {
        fprintf(stderr, "Failed to start ranging: %s\n", libvl53l1x_error_string(ret));
        libvl53l1x_close(vl53l1x);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Wait for ranging to complete
        ret = libvl53l1x_vl53l1x_get_ranging_result(vl53l1x);
        if (ret != LIBVL53L1X_NO_ERROR) {
            fprintf(stderr, "Failed to get ranging result: %s\n", libvl53l1x_error_string(ret));
            break;
        }

        // Read distance measurement
        float distance_mm;
        ret = libvl53l1x_vl53l1x_get_distance_raw(vl53l1x, &distance_mm);
        if (ret != LIBVL53L1X_NO_ERROR) {
            fprintf(stderr, "Failed to read distance: %s\n", libvl53l1x_error_string(ret));
            break;
        }

        // Check if object is within 20 cm
        if (distance_mm <= 200) {
            // Open gate
            gpiod_set_value(gpio18_fd, 1);
            gpiod_set_value(gpio19_fd, 0);

            // Log event
            char log_entry[256];
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S.%fZ", timeinfo);
            fprintf(stderr, "Opened gate at %s\n", log_entry);
        } else {
            // Close gate
            gpiod_set_value(gpio18_fd, 0);
            gpiod_set_value(gpio19_fd, 1);

            // Log event
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%dT%H:%M:%S.%fZ", timeinfo);
            fprintf(stderr, "Closed gate at %s\n", log_entry);
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Stop ranging
    ret = libvl53l1x_vl53l1x_stop_ranging(vl53l1x);
    if (ret != LIBVL53L1X_NO_ERROR) {
        fprintf(stderr, "Failed to stop ranging: %s\n", libvl53l1x_error_string(ret));
    }

    // Close I2C handle
    close(i2c_fd);

    // Clean up GPIO
    gpiod_close(gpio18_fd);
    gpiod_close(gpio19_fd);

    // Clean up VL53L1X
    libvl53l1x_vl53l1x_close(vl53l1x);
    libvl53l1x_i2c_exit();

    // Exit
    return EXIT_SUCCESS;
}

