                        while (!i2c_read_byte_data(i2c_fd, VL53L1X_ADDR, VL53L1X_REG_STATUS, &distance, 1)) {
                            // Poll status register until data-ready bit is set
                        }
                        distance = (distance << 8) | i2c_read_byte_data(i2c_fd, VL53L1X_ADDR, VL53L1X_REG_STATUS, NULL);
                        handle_distance(distance);
                    }
                }
            }

            // Check and handle motor state changes
            handle_motor_state_change(motor_state);
        }
        cleanup_resources();
    } else {
        // Parent process waits for child to finish
        wait(NULL);
    }

    return 0;
}

// Function to set up pigpio GPIO
void setup_pigpio() {
    int gpio17_mode = gpiod_open(GPIO17, GPIO_MODE_OUT);
    if (gpio17_mode < 0) {
        fprintf(stderr, "Error setting GPIO17 mode: %s\n", gpiod_error_str(gpio17_mode));
        exit(EXIT_FAILURE);
    }

    int gpio18_mode = gpiod_open(GPIO18, GPIO_MODE_OUT);
    if (gpio18_mode < 0) {
        fprintf(stderr, "Error setting GPIO18 mode: %s\n", gpiod_error_str(gpio18_mode));
        exit(EXIT_FAILURE);
    }

    int gpio24_mode = gpiod_open(GPIO24, GPIO_MODE_IN);
    if (gpio24_mode < 0) {
        fprintf(stderr, "Error setting GPIO24 mode: %s\n", gpiod_error_str(gpio24_mode));
        exit(EXIT_FAILURE);
    }

    gpiod_direction_input(GPIO17);
    gpiod_direction_input(GPIO18);
    gpiod_set_pull_up_down(GPIO24, GPIO_PULL_UP);
}

// Function to set up I2C
void setup_i2c() {
    i2c_fd = i2c_open(1, 400000); // Bus 1, 400 kHz
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", i2c_strerror(i2c_fd));
        exit(EXIT_FAILURE);
    }
}

// Function to clean up resources
void cleanup_resources() {
    gpiod_close(GPIO17);
    gpiod_close(GPIO18);
    gpiod_close(GPIO24);
    i2c_close(i2c_fd);
}

// Function to handle distance measurement
void handle_distance(uint16_t distance) {
    if (distance < THRESHOLD_MIN) {
        motor_state = MOTOR_FORWARD;
    } else if (distance > THRESHOLD_MAX) {
        motor_state = MOTOR_REVERSE;
    } else {
        motor_state = MOTOR_STOPPED;
    }

    // Log distance and motor state change
    printf("Distance: %u, Motor State: %s\n", distance, motor_state == MOTOR_FORWARD ? "Forward" : (motor_state == MOTOR_REVERSE ? "Reverse" : "Stopped"));
}

// Function to handle motor state changes
void handle_motor_state_change(MotorState state) {
    if (motor_state != state) {
        if (motor_state == MOTOR_FORWARD) {
            gpiod_set_value(GPIO17, 1);
            gpiod_set_value(GPIO18, 0);
        } else if (motor_state == MOTOR_REVERSE) {
            gpiod_set_value(GPIO17, 0);
            gpiod_set_value(GPIO18, 1);
        } else {
            gpiod_set_value(GPIO17, 0);
            gpiod_set_value(GPIO18, 0);
        }
        motor_state = state;
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup_resources();
    exit(EXIT_SUCCESS);
}
