#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_ADDR 0x29 // MPR121 I2C address
#define TOUCH_REG 0x00 // Touch status register
#define LED_GPIO_17 17
#define LED_GPIO_18 18
#define LED_GPIO_27 27
#define LED_GPIO_22 22

#define GPIO_NUM_TO_BCM(gpio_num) (gpio_to BCM_GPIO(gpio_num))

int main() {
    // Initialize GPIO
    int gpio17 = gpiod_open(GPIO_NUM_TO_BCM(LED_GPIO_17), GPIO_OUTPUT);
    int gpio18 = gpiod_open(GPIO_NUM_TO_BCM(LED_GPIO_18), GPIO_OUTPUT);
    int gpio27 = gpiod_open(GPIO_NUM_TO_BCM(LED_GPIO_27), GPIO_OUTPUT);
    int gpio22 = gpiod_open(GPIO_NUM_TO_BCM(LED_GPIO_22), GPIO_OUTPUT);

    // Initialize I2C
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize logging
    FILE *log_file = fopen("touch_sensor_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = cleanup;
    sigaction(SIGTERM, &term_handler, NULL);

    // Main loop
    while (1) {
        // Poll touch sensor
        uint8_t touch_data[12];
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            fprintf(stderr, "Failed to access I2C slave\n");
            continue;
        }

        // Read touch status
        if (ioctl(i2c_fd, I2C_READ, TOUCH_REG) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            continue;
        }

        // Soft reset sensor
        if (ioctl(i2c_fd, I2C_WRITE, TOUCH_REG | 0x01) < 0) {
            fprintf(stderr, "Failed to soft reset sensor\n");
            continue;
        }

        // Read back to verify
        if (ioctl(i2c_fd, I2C_READ, TOUCH_REG) < 0) {
            fprintf(stderr, "Failed to read back after reset\n");
            continue;
        }

        // Poll GPIO status
        uint8_t led_status = 0;
        if (gpiod_get_value_relaxed(gpio17) == 1) led_status |= 1 << 0;
        if (gpiod_get_value_relaxed(gpio18) == 1) led_status |= 1 << 1;
        if (gpiod_get_value_relaxed(gpio27) == 1) led_status |= 1 << 2;
        if (gpiod_get_value_relaxed(gpio22) == 1) led_status |= 1 << 3;

        // Check for proximity
        if (touch_data[0] || touch_data[1] || touch_data[2] || touch_data[3] ||
            touch_data[4] || touch_data[5] || touch_data[6] || touch_data[7] ||
            touch_data[8] || touch_data[9] || touch_data[10] || touch_data[11]) {
            // Log proximity event
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "Proximity detected at %s\n", timestamp);
            // Set LED pattern
            gpiod_set_value(gpio17, led_status & 1);
            gpiod_set_value(gpio18, led_status & 2);
            gpiod_set_value(gpio27, led_status & 4);
            gpiod_set_value(gpio22, led_status & 8);
        }

        // Sleep for 50ms
        usleep(50000);

        // Close and release resources on exit
        cleanup();
    }

    return 0;
}

// Cleanup function for SIGINT and SIGTERM
void cleanup() {
    // Release GPIO
    gpiod_release(gpio17);
    gpiod_release(gpio18);
    gpiod_release(gpio27);
    gpiod_release(gpio22);

    // Close I2C and log file descriptors
    close(i2c_fd);
    fclose(log_file);

    // Reset signal handlers
    sigaction(SIGINT, NULL, NULL);
    sigaction(SIGTERM, NULL, NULL);
}

