#include <stdint.h>
#include <stdbool.h>

#define MP121_I2C_ADDR 0x5A
#define LED_GPIO 27 // BCM 27

// MPR121 register addresses
#define MPR121_REG_FFI 0x00
#define MPR121_REG_SFI 0x01
#define MPR121_REG_ESI 0x02
#define MPR121_REG_DEBOUNCE 0x03
#define MPR121_REG_AFE_CONFIG 0x04
#define MPR121_REG_BASELINE_CONFIG 0x05

// GPIO pin for LED
#define LED_PIN -27

// Function prototypes
void setup_mpr121(void);
void configure_mp121_registers(uint8_t);
void monitor_proximity(void);
void handle_proximity_event(void);
void cleanup_resources(void);
void signal_handler(int signum);

int main(void) {
    // Initialize GPIO and I2C
    if (gpiod_open(GPIOD_DIR_OUTPUT, LED_PIN) < 0) {
        perror("Error opening GPIO pin for LED");
        return EXIT_FAILURE;
    }
    if (gpiod_direction_output(LED_GPIO, 1) < 0) {
        perror("Error setting LED GPIO direction");
        gpiod_close(LED_PIN);
        return EXIT_FAILURE;
    }

    if (i2c_open(I2C_DEV_I2C1) < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        monitor_proximity();
        usleep(100000); // Sleep for 100ms
    }

    // Clean up resources
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to setup MPR121
void setup_mpr121(void) {
    uint8_t buf[2];
    int fd;

    // Open MPR121 I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening MPR121 I2C device");
        return;
    }

    // Write device address to MPR121
    buf[0] = 0x00; // Start condition
    buf[1] = MP121_I2C_ADDR;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to MPR121");
        close(fd);
        return;
    }

    // Close I2C device
    close(fd);
}

// Function to configure MPR121 registers
void configure_mp121_registers(uint8_t reg) {
    uint8_t value;
    int fd;

    // Open MPR121 I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening MPR121 I2C device");
        return;
    }

    // Write register address
    buf[0] = 0x00; // Start condition
    buf[1] = reg;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing register address");
        close(fd);
        return;
    }

    // Read or write register value
    if (reg == MPR121_REG_FFI) {
        value = 0x01; // Enable FFI
    } else if (reg == MPR121_REG_SFI) {
        value = 0x01; // Enable SFI
    } else if (reg == MPR121_REG_ESI) {
        value = 0x01; // Enable ESI
    } else if (reg == MPR121_REG_DEBOUNCE) {
        value = 0x01; // Enable debounce
    } else if (reg == MPR121_REG_AFE_CONFIG) {
        value = 0x01; // Enable AFE
    } else if (reg == MPR121_REG_BASELINE_CONFIG) {
        value = 0x01; // Enable baseline filtering
    } else {
        perror("Invalid register");
        close(fd);
        return;
    }

    // Write register value
    if (write(fd, &value, 1) != 1) {
        perror("Error writing register value");
        close(fd);
        return;
    }

    // Close I2C device
    close(fd);
}

// Function to monitor proximity
void monitor_proximity(void) {
    uint8_t buf[2];
    int fd;
    struct timespec ts;

    // Open MPR121 I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening MPR121 I2C device");
        return;
    }

    // Read touch data
    buf[0] = 0x00; // Start condition
    buf[1] = MPR121_REG_READ_DATA; // Read data register
    if (write(fd, buf, 2) != 2) {
        perror("Error reading touch data");
        close(fd);
        return;
    }

    // Read response
    if (read(fd, buf, 2) != 2) {
        perror("Error reading touch data response");
        close(fd);
        return;
    }

    // Parse touch data
    uint8_t touch_status = buf[0] & 0x0F;
    uint8_t touch_data = buf[1] & 0x0F;

    // Check for proximity event
    if (touch_status & 0x01 && touch_data > 0) {
        handle_proximity_event();
    }

    // Close I2C device
    close(fd);

    // Log the event with timestamp
    time(&ts);
    char log_entry[100];
    sprintf(log_entry, "Proximity detected at %s", ctime(&ts));
    FILE *log_file = fopen("proximity.log", "a+");
    if (log_file) {
        fprintf(log_file, "%s\n", log_entry);
        fclose(log_file);
    }
}

// Function to handle proximity event
void handle_proximity_event(void) {
    // Turn on LED for 1 second
    struct timespec on_duration = { 1, 0 }; // 1 second
    if (nanosleep(&on_duration, NULL) == -1) {
        perror("Error sleeping");
        return;
    }

    // Turn off LED
    gpiod_set_value(LED_GPIO, 0);
}

// Function to cleanup resources
void cleanup_resources(void) {
    gpiod_close(LED_PIN);
    i2c_close(I2C_DEV_I2C1);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up resources immediately
    cleanup_resources();
    exit(EXIT_FAILURE);
}

