#include <signal.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define DIVIDER_RESISTOR 2000  // 2kΩ
#define SENSOR_THRESHOLD 58  // Minimum valid pulse width in microseconds

// Function to handle GPIO pin setup and ISR registration
static int setup_sensor(struct gpio_desc *trig, struct gpio_desc *echo) {
    int ret;

    // Set GPIO pins as outputs
    ret = gpiod_set_direction(trig, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting TRIG pin direction: %d\n", ret);
        return ret;
    }

    ret = gpiod_set_direction(echo, GPIO_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting ECHO pin direction: %d\n", ret);
        gpiod_set_direction(trig, GPIO_INPUT);  // Reset TRIG pin direction
        return ret;
    }

    // Configure TRIG pin for high level for 10us
    ret = gpiod_set_value(trig, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting TRIG pin value: %d\n", ret);
        gpiod_set_direction(trig, GPIO_INPUT);  // Reset TRIG pin direction
        return ret;
    }

    // Configure ECHO pin for interrupt on either edge
    ret = gpiod_request_edge_trigger(echo, GPIOD_EDGE_BOTH, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error requesting ECHO pin edge trigger: %d\n", ret);
        gpiod_set_direction(echo, GPIO_INPUT);  // Reset ECHO pin direction
        gpiod_set_direction(trig, GPIO_INPUT); // Reset TRIG pin direction
        return ret;
    }

    // Register ISR callback
    ret = gpiod_register_callback(echo, echo_isr, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error registering ECHO pin callback: %d\n", ret);
        gpiod_set_direction(echo, GPIO_INPUT);  // Reset ECHO pin direction
        gpiod_set_direction(trig, GPIO_INPUT); // Reset TRIG pin direction
        return ret;
    }

    return 0;
}

// Interrupt Service Routine (ISR)
static void echo_isr(struct gpio_desc *echo, u32 value, void *arg) {
    u32 timestamp;
    u32 pulse_width;
    int ret;

    // Capture the current time
    timestamp = time(NULL);
    if (timestamp == 0) {
        fprintf(stderr, "Timestamp wrap-around detected.\n");
        return;
    }

    // Read the echo pin value
    ret = gpiod_get_value(echo, &pulse_width);
    if (ret < 0) {
        fprintf(stderr, "Error reading ECHO pin value: %d\n", ret);
        return;
    }

    // Validate the pulse width
    if (pulse_width <= 0 || pulse_width > 25000) {
        fprintf(stderr, "Invalid pulse width detected: %u\n", pulse_width);
        return;
    }

    // Convert pulse width to distance
    float distance = (float)pulse_width * (340.29 / 1000000.0);  // Speed of sound in air

    // Log the distance and timestamp
    fprintf(stderr, "Distance: %.2f m at %u microseconds since epoch\n", distance, timestamp);

    // Clear the interrupt condition
    gpiod_set_value(echo, 0);
}

// Main function
int main() {
    struct gpio_desc *trig, *echo;
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing libgpiod: %d\n", ret);
        return EXIT_FAILURE;
    }

    // Set up TRIG and ECHO pins
    ret = setup_sensor(&trig, &echo);
    if (ret < 0) {
        fprintf(stderr, "Error setting up sensor: %d\n", ret);
        gpiod_cleanup();  // Clean up and exit
        return EXIT_FAILURE;
    }

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Do nothing intentionally
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Function to handle cleanup and graceful shutdown
void cleanup() {
    // Disable the ISR
    gpiod_unregister_callback(echo, echo_isr);

    // Close the log file
    FILE *log_file = fopen("distance_log.txt", "a+");
    if (log_file != NULL) {
        fprintf(log_file, "Shutting down...\n");
        fclose(log_file);
    }

    // Invoke the library's cleanup API call
    gpiod_cleanup();
}

