#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <linux/vl53l1x.h>

#define I2C_BUS_NUM 1
#define VL53L1X_ADDR 0x52
#define GPIO_XSHUT_PIN 27

volatile int sigIntReceived = 0;
volatile int sigTermReceived = 0;

void setup_gpiod() {
    int ret;
    struct gpio_desc *xshutdown_pin;

    /* Initialize GPIO library */
    ret = gpiod_get(&gpiod);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Open GPIO pin 27 as an output */
    ret = gpiod_get_pin(&xshutdown_pin, GPIO_NUM_27);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get GPIO pin 27: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Set GPIO pin 27 as output and high (active-low trigger for VL53L1X) */
    ret = gpiod_direction_output(xshutdown_pin, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pin 27 as output: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod() {
    if (xshutdown_pin) {
        gpiod_free_pin(xshutdown_pin);
    }
}

void setup_i2c() {
    int i2c_bus;
    struct i2c_dev *i2c_dev;
    int ret;

    /* Open I2C bus 1 */
    i2c_bus = I2C_BUS_NUM;
    ret = i2c_open(&i2c_bus, &i2c_dev);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d: %s", I2C_BUS_NUM, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    if (i2c_dev) {
        i2c_close(i2c_dev);
    }
}

void setup_vl53l1x() {
    struct vl53l1x_v *vl53l1x_device;
    int ret;

    /* Initialize VL53L1X driver */
    ret = vl53l1x_init();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X driver: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Open I2C device with the specified address */
    ret = vl53l1x_i2c_open(i2c_dev, VL53L1X_ADDR);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open VL53L1X I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    vl53l1x_device = vl53l1x_create();
    if (!vl53l1x_device) {
        syslog(LOG_ERR, "Failed to create VL53L1X device");
        exit(EXIT_FAILURE);
    }
}

void cleanup_vl53l1x() {
    if (vl53l1x_device) {
        vl53l1x_destroy(vl53l1x_device);
        vl53l1x_i2c_close(i2c_dev, VL53L1X_ADDR);
    }
}

void read_distance() {
    struct vl53l1x_time_of_flight_data_t data;
    int ret;

    /* Read distance */
    ret = vl53l1x_get_range(vl53l1x_device, &data);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        return;
    }

    double distance_mm = data.range_mm;
    int status = data.status;

    syslog(LOG_INFO, "Distance: %.1f mm, Status: %d", distance_mm, status);

