void setup_gpiod() {
    int ret;
    struct gpio_desc *xshutdown_pin;

    /* Initialize GPIO library */
    ret = gpiod_get(&gpiod);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Open GPIO pin 27 as an output */
    ret = gpiod_get_pin(&xshutdown_pin, GPIO_NUM_27);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get GPIO pin 27: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Set GPIO pin 27 as output and high (active-low trigger for VL53L1X) */
    ret = gpiod_direction_output(xshutdown_pin, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO pin 27 as output: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod() {
    if (xshutdown_pin) {
        gpiod_free_pin(xshutdown_pin);
    }
}

void setup_i2c() {
    int i2c_bus;
    struct i2c_dev *i2c_dev;
    int ret;

    /* Open I2C bus 1 */
    i2c_bus = I2C_BUS_NUM;
    ret = i2c_open(&i2c_bus, &i2c_dev);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d: %s", I2C_BUS_NUM, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
