#define VL53L1X_I2C_ADDR 0x52
#define GPIO24_PIN 24

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO
    int gpio_fd = gpiod_open(GPIO24_PIN, GPIO_OUTPUT_OPEN_DRAIN);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO24");
        return EXIT_FAILURE;
    }

    // Initialize VL53L1X sensor
    libvl53l1xvl_init();
    if (libvl53l1xvl_init_i2c(VL53L1X_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Initialize logging
    FILE *log_file = fopen("gate_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        libvl53l1xvl_deinit();
        gpiod_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Poll distance
        struct vl53l1x_time_of_flight_t tof;
        if (libvl53l1xvl_get_distance(&tof) < 0) {
            fprintf(log_file, "Error reading distance: %s\n", libvl53l1xvl_get_error_str());
            continue;
        }

        // Convert distance from mm to cm
        float distance_cm = (float)tof.ranging_data / 10.0;

        // Control the gate actuator
        if (distance_cm < 20.0) {
            if (gpiod_set_value(gpio_fd, GPIO_HIGH) < 0) {
                fprintf(log_file, "Error setting GPIO24 high: %s\n", strerror(errno));
            } else {
                fprintf(log_file, "Opening gate (distance < 20 cm)\n");
            }
        } else {
            if (gpiod_set_value(gpio_fd, GPIO_LOW) < 0) {
                fprintf(log_file, "Error setting GPIO24 low: %s\n", strerror(errno));
            } else {
                fprintf(log_file, "Closing gate (distance >= 20 cm)\n");
            }
        }

        // Log distance and gate state
        fprintf(log_file, "Time: %s, Distance: %.1f cm, Gate State: %s\n",
               ctime(&time(NULL)), distance_cm, (distance_cm < 20.0) ? "Open" : "Closed");

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    libvl53l1xvl_deinit();
    gpiod_close(gpio_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

