#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/time.h>

#define HC_SR04_TRIGGER_GPIO 23
#define HC_SR04_ECHO_GPIO 24
#define SERVO_GPIO 18

volatile sig_atomic_t interrupt_flag = 0;
volatile uint32_t pulse_width = 0;
volatile bool new_pulse = false;

#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_CENTER_ANGLE 90

#define DISTANCE_MIN_CM 2
#define DISTANCE_MAX_CM 400

void servo_set_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        angle = SERVO_CENTER_ANGLE;
    }
    gpiod_set_data(SERVO_GPIO, (angle * 180) / 255);
}

void handle_interrupt(gpiod_cdev_t cdev, uint32_t value) {
    if (value > 0) {
        // Echo detected
        uint32_t timestamp = clock_gettime(CLOCK_MONOTONIC, &time);
        uint32_t echo_time = timestamp - (gpiod_get_last_trigger_time(cdev) * 1000);
        echo_time *= 1000; // Convert to microseconds

        uint32_t pulse_width_us = (echo_time - 29) / 29; // 30ms - 1ms (minimum pulse width)
        pulse_width = (uint32_t)(pulse_width_us * 1000); // Convert to microseconds

        new_pulse = true;
    } else {
        // No echo
        pulse_width = 0;
        new_pulse = false;
    }

    interrupt_flag = 1;
}

int main() {
    struct gpiod_cdev *hc_sr04_cdev;
    struct gpiod_cdev *servo_cdev;
    FILE *distance_log = fopen("distance_log.csv", "a+");
    char buffer[256];
    int angle;

    if (gpiod_cdev_open(&hc_sr04_cdev, GPIOD_DIR_IN, HC_SR04_ECHO_GPIO) < 0) {
        perror("Failed to open HC-SR04 echo pin");
        return EXIT_FAILURE;
    }

    if (gpiod_cdev_open(&servo_cdev, GPIOD_DIR_OUT_INIT_HIGH, SERVO_GPIO) < 0) {
        perror("Failed to open servo motor pin");
        fclose(distance_log);
        gpiod_cdev_close(hc_sr04_cdev);
        return EXIT_FAILURE;
    }

    gpiod_set_callback(hc_sr04_cdev, handle_interrupt, NULL);

    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;

            // Filter distance with a 5-sample moving average
            static uint32_t last_five_distances[5] = {0};
            static int moving_average_index = 0;

            last_five_distances[moving_average_index++] = pulse_width;
            if (moving_average_index == 5) {
                int filtered_distance = 0;
                for (int i = 0; i < 5; i++) {
                    filtered_distance += last_five_distances[i];
                }
                filtered_distance /= 5;

                if (filtered_distance < DISTANCE_MIN_CM || filtered_distance > DISTANCE_MAX_CM) {
                    fprintf(distance_log, "%f, -1.0, 90\n", (double)filtered_distance);
                } else {
                    fprintf(distance_log, "%f, %f, %d\n", (double)filtered_distance / 100, servo_set_angle((int)((filtered_distance / 100) * 180)), gpiod_get_data_value(SERVO_GPIO));
                }

                moving_average_index = 0;
            }
        }

        // Main thread checks for new pulse width and updates servo angle
        while (!new_pulse) {
            usleep(10000); // Poll every 10ms
        }

        servo_set_angle(gpiod_get_data_value(SERVO_GPIO));

        // Handle SIGINT
        if (signal(SIGINT, SIG_IGN) == SIG_IGN) {
            signal(SIGINT, SIG_DFL); // Restore default SIGINT handler
        }

        if (interrupt_flag) {
            // Update the servo angle based on the new distance reading
            angle = servo_set_angle((int)((pulse_width / 1000) * 180));
            fprintf(distance_log, "%f, %f, %d\n", (double)(pulse_width / 1000), angle, angle);
        }

        // Flush the CSV file after each write
        fflush(distance_log);
    }

    // Clean up on SIGINT
    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent double cleanup

    fclose(distance_log);
    gpiod_cdev_close(hc_sr04_cdev);
    gpiod_cdev_close(servo_cdev);

    return EXIT_SUCCESS;
}

