#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define VL53L1X_I2C_ADDR 0x52
#define WARNING_GPIO 17 // BCM 17

// Sensor configuration settings
#define VL53L1X_CONFIG_DEFAULT 0x00
#define VL53L1X_CFG_ENABLE_SIGNAL_RATE_CHECK 0x01
#define VL53L1X_CFG_ENABLE_CROSS_TALK_COMPENSATION 0x02

// Buffer size for distance measurements
#define BUFFER_SIZE 10

volatile uint16_t distanceMeasurements[BUFFER_SIZE];

// Function prototypes
void vl53l1x_init(void);
void vl53l1x_read_distance(uint16_t *distance);
void setup_warning_led(void);
void cleanup(void);
void sigint_handler(int signum);

int main(void) {
    // Initialize GPIO for the warning LED
    setup_warning_led();

    // Signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read distance every 50 ms
        vl53l1x_read_distance(distanceMeasurements);
        // Check if distance is below warning threshold
        if (distanceMeasurements[0] < 200) {
            gpiod_set_value(WARNING_GPIO, 1); // Turn LED on
        } else {
            gpiod_set_value(WARNING_GPIO, 0); // Turn LED off
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    printf("SIGINT received, shutting down...\n");
    cleanup();
    exit(0);
}

// Function to initialize the VL53L1X sensor
void vl53l1x_init(void) {
    int fd;
    struct i2c_dev *i2c_dev;
    int ret;

