    gpio_dir.direction = GPIOD_DIR_OUT_INIT_LOW;
    gpio_csn.cs = GPIOD_CSN_DISABLE;
    gpio_pad.id = GPIOD_ID_HCSR04_TRIGGER;

    rc = gpiod_request(&gpio_dir, &gpio_csn, &gpio_pad);
