    rc = gpiod_read(HC_SR04_ECHO_GPIO, &value);
    if (rc != 0) {
        fprintf(stderr, "Failed to read echo pin: %d\n", rc);
        return;
    }

    duration = value.u64 - last_time;
    last_time = value.u64;

    float distance = (duration * SPEED_OF_SOUND / 2) / 58.0; // Distance calculation

    if (distance > MAX_DISTANCE_CM || distance < MIN_DISTANCE_CM) {
        current_freq = last_freq; // Preserve previous frequency
    } else {
        float freq = MIN_FREQ_HZ * pow(MAX_DISTANCE_CM / distance, -1 / LOG_BASE);
        current_freq = (uint32_t)round(freq * 1000.0 + 0.5); // Map to 200-2000 Hz
    }

    last_distance = distance;
}

void generate_audio(uint32_t freq) {
    struct timeval now, then;
    struct sigaction sa;
    uint32_t duty_cycle;

