    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gettimeofday(&now, NULL);
    while (1) {
        gettimeofday(&then, NULL);
        uint32_t elapsed_ms = (uint32_t)((now.tv_sec - then.tv_sec) * 1000 + (now.tv_usec - then.tv_usec) / 1000.0);

        duty_cycle = (uint16_t)(50 + (current_freq * elapsed_ms / 1000));

        gpiod_pwm_write(PWM_PIN, duty_cycle);
        usleep(1000 - elapsed_ms); // Wait for the next period
    }
}

int main() {
    setup_hcsr04();
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    measure_distance();

    generate_audio(current_freq);

    return 0;
}

