    uint16_t frequency = 0;

    while (1) {
        // Trigger the HC-SR04
        gpiod_set_value(GPIO_TRIGGER, GPIO_OUTPUT_LOW);
        usleep(10);
        gpiod_set_value(GPIO_TRIGGER, GPIO_OUTPUT_HIGH);
        usleep(10);
        gpiod_set_value(GPIO_TRIGGER, GPIO_INPUT);

