        exit(EXIT_FAILURE);
    }

    // Initialize PWM
    ret = gpiod_pwm_init(PWM0, PWM_POLARITY_HIGH, PWM_FREQ);
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize PWM: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

// Function to clean up libgpiod
void cleanup_libgpiod(void) {
    gpiod_exit();
}

