#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define PULSE_WIDTH_MICROS 10
#define TIMEOUT_MS 50
#define SLEEP_MS 500

volatile sig_atomic_t should_exit = 0;

void handle_SIGINT(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Configure trigger pin as output, initially low
    if (gpiod_direction_output(gpiod_get_device(), TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to configure trigger pin as output: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Configure echo pin as input
    if (gpiod_direction_input(gpiod_get_device(), ECHO_PIN) < 0) {
        fprintf(stderr, "Failed to configure echo pin as input: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Trigger the ultrasonic sensor
        gpiod_write(gpiod_get_device(), TRIGGER_PIN, 1); // High pulse
        usleep(PULSE_WIDTH_MICROS); // 10 microseconds
        gpiod_write(gpiod_get_device(), TRIGGER_PIN, 0); // Low

        // Start echo measurement with timeout
        int echo_duration_us = -1;
        if (gpiod_get_value_input_u32(gpiod_get_device(), ECHO_PIN) != 0) {
            echo_duration_us = gpiod_get_value_input_u32(gpiod_get_device(), ECHO_PIN);
        }

        // Convert microseconds to centimeters
        float distance_cm = (float)echo_duration_us * 0.034 / 2;

        // Check for valid reading and print message
        if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
            if (distance_cm < 10) {
                printf("Too close!\n");
            }
        }

        // Sleep for 500 milliseconds
        usleep(SLEEP_MS * 1000);

        // Handle SIGINT
        if (should_exit) {
            break;
        }
    }

    // Clean up GPIO resources
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

