#include <sys/types.h>
#include <errno.h>
#include <gpiod.h>

#define SI1175_ADDR 0x29 // Default I2C address for Si1175

// Function prototypes
void open_and_init_gpiod();
void close_and_cleanup();
void read_si1175(uint8_t *data, size_t len);
void write_to_log_file(const char *line);
void handle_interrupts(int signum);

int main() {
    // Initialize GPIO and setup I2C
    open_and_init_gpiod();

    // Variables
    uint8_t data[2]; // Buffer for light reading
    uint16_t als_visible;
    char timestamp[50];
    char line[256];
    int fd_log = -1; // File descriptor for log file

    // Main loop
    while (1) {
        // Sample ambient light every 5 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 5;
        clock_settime(CLOCK_REALTIME, &ts);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        // Read ALS value
        if (gpiod_c_read(SI1175_ADDR, 0x00, data, 2) == -1) {
            perror("gpiod_c_read");
            continue;
        }

        als_visible = (data[0] << 8) | data[1];
        sprintf(line, "%s,0x%04x", timestamp, als_visible);

        // Write to log file
        if ((fd_log = fopen("proximity_log.csv", "a")) == -1) {
            perror("fopen");
            continue;
        }
        write_to_log_file(line);
        fclose(fd_log);

        // Handle interrupts
        if (waitpid(-1, &status, WUNTRACED) == -1) {
            perror("waitpid");
            continue;
        }
        if (WIFSIGNALED(status)) {
            handle_interrupts(WTERMSIG(status));
        }
    }

    // Clean up on exit
    close_and_cleanup();

    return 0;
}

// Function to open and initialize gpiod
void open_and_init_gpiod() {
    int fd;
    if ((fd = gpiod_open(GPIOD_I2C0, GPIOD_DIR_RXD)) == -1) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    if (gpiod_c_open(fd, SI1175_ADDR) == -1) {
        perror("gpiod_c_open");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to close and cleanup resources
void close_and_cleanup() {
    if (fd_log != -1) {
        fclose(fd_log);
        fd_log = -1;
    }

    if (fd != -1) {
        gpiod_close(fd);
        gpiod_close(fd);
        close(fd);
        fd = -1;
    }
}

// Function to read from Si1175 sensor
void read_si1175(uint8_t *data, size_t len) {
    if (gpiod_c_read(fd, SI1175_ADDR, data, len) == -1) {
        perror("gpiod_c_read");
        exit(EXIT_FAILURE);
    }
}

// Function to write to the log file
void write_to_log_file(const char *line) {
    if (fd_log != -1) {
        fprintf(fd_log, "%s\n", line);
    }
}

// Function to handle interrupts (SIGINT, SIGTERM)
void handle_interrupts(int signum) {
    // Clean up and exit
    close_and_cleanup();
    exit(EXIT_SUCCESS);
}

