#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod/gpiod.h>

#define SI1120_ADDR 0x5A
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_CMD_RESET 0x01
#define SI1120_REG_ALS 0x02
#define SI1120_REG_PROX 0x03

#define MAX_ATTEMPTS 3
#define DELAY_BETWEEN_ATTEMPTS 10

// Function prototypes
void setup_si1120();
void read_si1120(uint16_t* als, uint16_t* prox);
void write_reg(uint8_t reg, uint8_t value);
void reset_si1120();
void print_timestamp_and_data(uint16_t als, uint16_t prox);
void handle_errors(const char* operation);
void cleanup();

int main() {
    int fd;
    struct stat sb;
    char buffer[256];
    uint16_t als, prox;
    time_t timestamp;
    char timestamp_str[50];

    // Initialize GPIO library
    if (gpiod_open() < 0) {
        fprintf(stderr, "Error initializing GPIO library: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }
    gpiod_free();

    // Attempt to open the log file
    fd = open("si1120_log.txt", O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    close(fd);

    // Attempt to create the log file
    if (stat("si1120_log.txt", &sb) == -1) {
        if (errno == ENOENT) {
            // File does not exist, proceed to create
            if (mkdir("si1120_log_dir", 0755) == -1) {
                fprintf(stderr, "Error creating directory for log file: %s\n", strerror(errno));
                return EXIT_FAILURE;
            }
        } else {
            fprintf(stderr, "Error stat'ing log file: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    // Main loop until SIGINT
    while (1) {
        // Attempt to read from the sensor
        for (int i = 0; i < MAX_ATTEMPTS; ++i) {
            reset_si1120();
            if (read_si1120(&als, &prox) == 0) {
                break;
            }
            usleep(DELAY_BETWEEN_ATTEMPTS * 1000);
        }

        if (i == MAX_ATTEMPTS) {
            fprintf(stderr, "Failed to read from Si1120 sensor after %d attempts.\n", MAX_ATTEMPTS);
            break;
        }

        // Convert timestamp to string
        time(&timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

        // Append data to log file
        sprintf(buffer, "%s, ALS: %04X, PROX: %04X\n", timestamp_str, als, prox);
        if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            break;
        }

        // Cleanup after each iteration
        cleanup();
    }

    // Close the log file descriptor
    close(fd);

    // Free resources
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup the Si1120 sensor
void setup_si1120() {
    // Reset the sensor
    write_reg(SI1120_REG_CMD_RESET, 0x01);

    // Verify part ID
    uint8_t part_id;
    read_reg(SI1120_REG_PART_ID, &part_id);
    if (part_id != 0x20) {
        fprintf(stderr, "Si1120 part ID mismatch. Expected 0x20, got 0x%02X\n", part_id);
        exit(EXIT_FAILURE);
    }

    // Initialize I2C communication
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C bus 1: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    gpiod_i2c_release(i2c_fd);
}

// Function to read data from the Si1120 sensor
void read_si1120(uint16_t* als, uint16_t* prox) {
    // Write command to read ALS and proximity
    write_reg(SI1120_REG_ALS, 0x01);
    write_reg(SI1120_REG_PROX, 0x01);

    // Read data
    uint8_t als_data, prox_data;
    read_reg(SI1120_REG_ALS, &als_data);
    read_reg(SI1120_REG_PROX, &prox_data);

    *als = (als_data << 8) | prox_data;
    *prox = (prox_data << 8) | als_data;
}

// Function to write to a register on the Si1120 sensor
void write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to Si1120 register: %s\n", strerror(errno));
        handle_errors("write_reg");
    }
}

// Function to reset the Si1120 sensor
void reset_si1120() {
    write_reg(SI1120_REG_CMD_RESET, 0x01);
    usleep(10); // Wait for reset to complete
}

// Function to handle errors and release resources
void handle_errors(const char* operation) {
    fprintf(stderr, "Error during %s operation.\n", operation);
    close(i2c_fd);
    exit(EXIT_FAILURE);
}

// Function to clean up resources
void cleanup() {
    // Close I2C handle
    close(i2c_fd);
    gpiod_i2c_release(i2c_fd);
}

