#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <stdint.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

volatile uint32_t echo_start_time = 0;
volatile uint32_t echo_end_time = 0;

void gpio_setup(void) {
    struct gpiod_dir gpio_dir;
    struct gpiod_export gpio_export;
    int ret;

    /* Initialize libgpiod */
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init() failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Configure GPIO17 (TRIGGER) as output */
    gpio_dir.direction = GPIOD_DIR_OUT_INIT_LOW;
    gpio_dir.config = GPIOD_CONFIG_ACTIVE_LOW;
    ret = gpiod_set_direction(TRIGGER_PIN, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "gpiod_set_direction(TRIGGER_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Configure GPIO18 (ECHO) as input with rising/falling edge alert */
    gpio_dir.direction = GPIOD_DIR_IN;
    ret = gpiod_set_direction(ECHO_PIN, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "gpiod_set_direction(ECHO_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Configure GPIO27 (BUZZER) as output */
    gpio_dir.direction = GPIOD_DIR_OUT_INIT_LOW;
    gpio_dir.config = GPIOD_CONFIG_ACTIVE_LOW;
    ret = gpiod_set_direction(BUZZER_PIN, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "gpiod_set_direction(BUZZER_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    /* Export GPIOs */
    gpio_export.info = GPIOD_EXPORT_INFO_NONE;
    ret = gpiod_export(TRIGGER_PIN, &gpio_export);
    if (ret < 0) {
        fprintf(stderr, "gpiod_export(TRIGGER_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_export(ECHO_PIN, &gpio_export);
    if (ret < 0) {
        fprintf(stderr, "gpiod_export(ECHO_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_export(BUZZER_PIN, &gpio_export);
    if (ret < 0) {
        fprintf(stderr, "gpiod_export(BUZZER_PIN) failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void send_trigger_pulse(void) {
    struct gpiod_value trigger_value;
    uint32_t timestamp;

    trigger_value.value = 1; // High pulse
    timestamp = gpiod_get_value_ns(TRIGGER_PIN, &trigger_value);
    echo_start_time = timestamp;

    trigger_value.value = 0; // Low pulse
    timestamp = gpiod_get_value_ns(TRIGGER_PIN, &trigger_value);
    echo_end_time = timestamp;

    // Compute the pulse width
    uint32_t pulse_width = (echo_end_time - echo_start_time);
}

void echo_interrupt_handler(struct gpiod_device *gpiod_dev, uint32_t edge, void *arg) {
    struct gpiod_export *export = arg;
    uint32_t timestamp;

    if (edge == GPIOD_EDGE_RISING) {
        // Record the rising edge timestamp
        timestamp = gpiod_get_value_ns(ECHO_PIN, NULL);
        echo_start_time = timestamp;
    } else if (edge == GPIOD_EDGE_FALLING) {
        // Record the falling edge timestamp
        timestamp = gpiod_get_value_ns(ECHO_PIN, NULL);
        echo_end_time = timestamp;
    }

    // Compute the echo pulse width
    uint32_t echo_pulse_width = (echo_end_time - echo_start_time);

