               // Distance = (pulse width in us) * 29.41 cm/us
               );
        last_time = timestamp;
    }

    // Activate buzzer if distance is less than 20 cm
    if (echo_pulse_width < 2000000) { // 20 cm in microseconds
        gpiod_set_value(BUZZER_PIN, 1); // High
    } else {
        gpiod_set_value(BUZZER_PIN, 0); // Low
    }
