#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>
#include <time.h>

#define TRIGGER_GPIO 4
#define ECHO_GPIO 17
#define SERVO_GPIO 18
#define MAX_DISTANCE 400  // Maximum measurable distance in cm
#define PULSE_MIN 500      // 500 microseconds for 0 degrees
#define PULSE_MAX 2500     // 2500 microseconds for 180 degrees
#define PULSE_INCREMENT 100 // Increment for each degree

// Function prototypes
void setup_gpios(void);
void measure_distance(void);
void rotate_servo(float distance);
void handle_interrupt(int signum);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Main loop
    while (1) {
        measure_distance();
        rotate_servo(measured_distance);
        usleep(100000); // Sleep for 100 ms
    }

    return 0;
}

// Function to initialize GPIO pins
void setup_gpios(void) {
    struct gpiod_dir_config dir_config;
    struct gpiod_set_config set_config;
    int trigger_pin, echo_pin, servo_pin;

    // Initialize GPIO driver
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIOD: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }

    // Configure trigger pin (GPIO 4)
    trigger_pin = gpiod_get_index_by_name("gpio4");
    if (trigger_pin == -1) {
        fprintf(stderr, "Failed to find GPIO 4: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }
    dir_config.direction = GPIOD_DIR_OUT_INIT_LOW;
    set_config.config = &dir_config;
    if (gpiod_set_config(trigger_pin, &set_config) < 0) {
        fprintf(stderr, "Failed to set GPIO 4 direction: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }

    // Configure echo pin (GPIO 17)
    echo_pin = gpiod_get_index_by_name("gpio17");
    if (echo_pin == -1) {
        fprintf(stderr, "Failed to find GPIO 17: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }
    dir_config.direction = GPIOD_DIR_IN;
    set_config.config = &dir_config;
    if (gpiod_set_config(echo_pin, &set_config) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 direction: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }

    // Configure servo pin (GPIO 18)
    servo_pin = gpiod_get_index_by_name("gpio18");
    if (servo_pin == -1) {
        fprintf(stderr, "Failed to find GPIO 18: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }
    dir_config.direction = GPIOD_DIR_OUT_INIT_LOW;
    set_config.config = &dir_config;
    if (gpiod_set_config(servo_pin, &set_config) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 direction: %s\n", gpiod_errstr());
        exit(EXIT_FAILURE);
    }
}

// Function to measure distance using HC-SR04
void measure_distance(void) {
    struct gpiod_value_read_config read_config;
    int echo_pin_value;
    float distance;

    // Set trigger pin high for 10 microseconds
    gpiod_set_value(TRIGGER_GPIO, 1, GPIOD_VALUE_ONESHOT);
    usleep(10);

    // Set trigger pin low
    gpiod_set_value(TRIGGER_GPIO, 0, GPIOD_VALUE_ONESHOT);

    // Wait for echo pin to go high
    read_config.reg = GPIOD_REG_VALUE;
    read_config.direction = GPIOD_DIR_IN;
    echo_pin_value = gpiod_get_value(echo_pin);
    while (echo_pin_value == 0) {
        usleep(10); // Short timeout to avoid blocking indefinitely
        echo_pin_value = gpiod_get_value(echo_pin);
    }

    // Calculate distance using the speed of sound
    distance = (echo_pin_value - 1000) * 0.034 / 2; // 34 cm/us

    // Handle echo timeout
    if (distance < 0) {
        distance = -1.0; // Return negative distance on timeout
        printf("Distance measurement timed out.\n");
    } else {
        printf("Distance: %.1f cm\n", distance);
    }
}

// Function to rotate servo based on distance
void rotate_servo(float distance) {
    float pulse_width = PULSE_MIN + (distance * PULSE_INCREMENT);
    if (pulse_width < PULSE_MIN || pulse_width > PULSE_MAX) {
        // Clamp the pulse width within valid range
        pulse_width = fminf(PULSE_MAX, fmaxf(PULSE_MIN, pulse_width));
    }

    // Set servo pin high for pulse width microseconds
    gpiod_set_value(SERVO_GPIO, 1, GPIOD_VALUE_ONESHOT);
    usleep(pulse_width);
    gpiod_set_value(SERVO_GPIO, 0, GPIOD_VALUE_ONESHOT);
}

// Signal handler for SIGINT
void handle_interrupt(int signum) {
    // Stop the GPIO operations
    gpiod_stop();
    printf("SIGINT received. Stopping operations and exiting...\n");
    exit(EXIT_SUCCESS);
}

