#include <sys/mman.h>
#include <sys/wait.h>
#include <gpiod.h>
#include <libgpiod/gpiod.h>

#define I2C_BUS_NUM 1
#define VL53L1X_ADDR 0x52
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_FAR 250
#define DISTANCE_THRESHOLD_CLOSE 200

// Constants for VL53L1X register addresses
#define VL53L1X_REG_MODEL_ID 0x15
#define VL53L1X_REG_timing_budget 0x16

// GPIO pin for servo control
#define SERVO_PWM_PIN 18

// Function prototypes
void setup_io();
void handle_interrupt(int signum);
void read_distance(uint16_t *distance);
void set_servo_pulse(uint32_t pulse_width);
void write_to_gate_log(const char *message, uint64_t timestamp);
void cleanup();

int main() {
    // Signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Initialize GPIO and I2C
    setup_io();

    // Main loop
    while (1) {
        // Read distance from VL53L1X
        uint16_t distance;
        read_distance(&distance);

        // Check distance and set servo pulse width
        if (distance > DISTANCE_THRESHOLD_FAR) {
            set_servo_pulse(1000);
        } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
            set_servo_pulse(2000);
        } else {
            // Smooth transition
            set_servo_pulse(1500);
        }

        // Write to gate log with timestamp
        write_to_gate_log("Gate state changed", clock_gettime(CLOCK_REALTIME, &((struct timespec *)NULL)->tv_sec) | (clock_gettime(CLOCK_REALTIME, &((struct timespec *)NULL)->tv_nsec) << 32));

        // Sleep for a short period to avoid excessive CPU usage
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIO and I2C
void setup_io() {
    // Initialize GPIO
    int gpio_dev_fd = gpiod_open(SERVO_PIN, GPIOD_OPEN_RWS);
    if (gpio_dev_fd < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    int i2c_dev_fd = i2c_open(I2C_BUS_NUM, I2C_FLAG_RDWR);
    if (i2c_dev_fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for I2C message buffer
    char i2c_message[16] = {0};
    uint8_t command = 0x00; // Start condition
    uint8_t register_address = 0x15; // Model ID register

    // Write to VL53L1X to verify model ID
    if (i2c_transfer(i2c_dev_fd, &command, 1, &i2c_message[0], 1, &register_address, 1, NULL, 0) != 1) {
        perror("i2c_transfer for model ID");
        exit(EXIT_FAILURE);
    }

    // Read model ID
    if (i2c_transfer(i2c_dev_fd, &command, 1, &i2c_message[0], 1, &register_address, 1, NULL, 0) != 1) {
        perror("i2c_transfer for model ID read");
        exit(EXIT_FAILURE);
    }

    // Check if the model ID matches the expected value
    if (i2c_message[0] != 0x53) {
        fprintf(stderr, "Incorrect model ID, exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Set timing budget
    i2c_message[0] = 0x01; // Write command
    i2c_message[1] = 0x16; // Timing budget register
    if (i2c_transfer(i2c_dev_fd, &command, 1, &i2c_message[0], 2, NULL, 0, NULL, 0) != 2) {
        perror("i2c_transfer for timing budget write");
        exit(EXIT_FAILURE);
    }

    // Close I2C and GPIO devices
    i2c_close(i2c_dev_fd);
    gpiod_close(gpio_dev_fd);
}

