void read_distance(uint16_t *distance) {
    char i2c_message[16] = {0};
    uint8_t command = 0x00; // Start condition
    uint8_t register_address = 0x30; // Distance register

    // Read distance register
    if (i2c_transfer(i2c_dev_fd, &command, 1, &i2c_message[0], 1, &register_address, 1, NULL, 0) != 1) {
        perror("i2c_transfer for distance read");
        return;
    }

    *distance = i2c_message[0]; // Distance is in the first byte
}

