#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18

#define TRIGGER_PIN -1
#define ECHO_PIN -1
#define SERVO_PIN -1

#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

void setup_gpios(gpiod_device *gpiod) {
    if (gpiod_open(gpiod, TRIGGER_PIN) < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", TRIGGER_GPIO, gpiod_errstr(gpiod));
        exit(EXIT_FAILURE);
    }
    gpiod_direction_output(gpiod, TRIGGER_GPIO, 1);

    if (gpiod_open(gpiod, ECHO_PIN) < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", ECHO_GPIO, gpiod_errstr(gpiod));
        gpiod_close(gpiod);
        exit(EXIT_FAILURE);
    }
    gpiod_direction_input(gpiod, ECHO_GPIO);

    if (gpiod_open(gpiod, SERVO_PIN) < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", SERVO_GPIO, gpiod_errstr(gpiod));
        gpiod_close(gpiod);
        exit(EXIT_FAILURE);
    }
    gpiod_direction_output(gpiod, SERVO_GPIO, 0); // Set servo to 0 degrees initially
}

void send_trigger(gpiod_device *gpiod) {
    if (gpiod_write(gpiod, TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error sending trigger pulse: %s\n", gpiod_errstr(gpiod));
        return;
    }
}

void measure_distance(gpiod_device *gpiod) {
    unsigned long start, end;
    int echo_level;

    gpiod_set_value(gpiod, ECHO_PIN, 0); // Ensure echo pin is low

    send_trigger(gpiod);

    start = micros();

    while (gpiod_read(gpiod, ECHO_PIN) == 0) {
        if (micros() - start > 50000) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            return;
        }
    }

    end = micros();
    echo_level = gpiod_read(gpiod, ECHO_PIN);

    if (echo_level == 0) {
        fprintf(stderr, "No echo detected.\n");
        return;
    }

    int distance = (echo_level * speed_of_sound / 2) / 58; // Assuming speed of sound in air is approximately 340 m/s

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        distance = -1.0; // Invalid distance
    }
}

void map_distance_to_angle(double distance, double &angle) {
    if (distance < MIN_DISTANCE) {
        angle = 0.0;
    } else if (distance > MAX_DISTANCE) {
        angle = 180.0;
    } else {
        angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE;
    }

    // Guard against invalid angles
    if (angle < 0.0 || angle > 180.0) {
        angle = 0.0; // Clamp to valid range
    }
}

void servo_angle(double angle) {
    if (gpiod_write(gpiod, SERVO_PIN, (unsigned int)angle) < 0) {
        fprintf(stderr, "Error setting servo angle: %s\n", gpiod_errstr(gpiod));
        return;
    }
}

void sigint_handler(int signum) {
    // Stop the servo and clean up
    servo_angle(0.0);
    gpiod_close(gpiod);
    exit(EXIT_SUCCESS);
}

int main() {
    gpiod_device *gpiod;
    double distance;
    double angle;

    setup_gpios(gpiod);

    signal(SIGINT, sigint_handler);

    while (1) {
        printf("Distance: %f cm, Angle: %f degrees\n", distance, angle);

        // Measure distance
        measure_distance(gpiod);

        // Map distance to angle
        map_distance_to_angle(distance, angle);

        // Control servo based on angle
        servo_angle(angle);

        usleep(100000); // 100 ms pause
    }

    return 0;
}

