#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdbool.h>

#define SI7005_I2C_ADDR 0x40 // Silicon Labs Si7005 I2C address
#define SI7005_CONFIG_REG 0x00 // CONFIG register address
#define SI7005_READ_REG_ADDR 0x01 // Address to read data from

// Function prototypes
void setup_si7005();
void read_si7005_data();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Attempt to open the I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO library
    if (gpiod_open() < 0) {
        perror("Failed to open GPIO library");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Setup Si7005 sensor
    setup_si7005();

    // Main loop
    while (1) {
        // Read data from Si7005 every 2 seconds
        read_si7005_data();
        sleep(2); // Wait for 2 seconds
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to setup Si7005 sensor
void setup_si7005() {
    struct gpiod_i2c_bus *i2c_bus;
    struct gpiod_i2c_device *i2c_device;

    // Open I2C bus
    i2c_bus = gpiod_i2c_bus_open("/dev/i2c-1", GPIOD_OPEN_FLAG_RDWR);
    if (!i2c_bus) {
        perror("Failed to open I2C bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open I2C device with the specified address
    i2c_device = gpiod_i2c_device_open(i2c_bus, SI7005_I2C_ADDR, GPIOD_OPEN_FLAG_RDWR);
    if (!i2c_device) {
        perror("Failed to open Si7005 device");
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write to CONFIG register
    uint8_t config_write;
    if (gpiod_i2c_transfer(i2c_device, &config_write, 1, SI7005_CONFIG_REG, 1) != 1) {
        perror("Failed to write to CONFIG register");
        gpiod_i2c_device_close(i2c_device);
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for 10 ms
    usleep(10000);

    // Write to read register address
    if (gpiod_i2c_transfer(i2c_device, &SI7005_READ_REG_ADDR, 1, SI7005_CONFIG_REG, 1) != 1) {
        perror("Failed to write to read register address");
        gpiod_i2c_device_close(i2c_device);
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for 10 ms
    usleep(10000);

    // Read data from Si7005
    uint8_t data;
    if (gpiod_i2c_transfer(i2c_device, &data, 1, SI7005_READ_REG_ADDR, 1) != 1) {
        perror("Failed to read data from Si7005");
        gpiod_i2c_device_close(i2c_device);
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Handle SIGINT
    handle_signal(SIGINT);
}

// Function to read data from Si7005 sensor
void read_si7005_data() {
    uint8_t data;
    // Write to read register address
    if (gpiod_i2c_transfer(i2c_device, &SI7005_READ_REG_ADDR, 1, SI7005_CONFIG_REG, 1) != 1) {
        perror("Failed to write to read register address");
        gpiod_i2c_device_close(i2c_device);
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for 10 ms
    usleep(10000);

    // Read data from Si7005
    if (gpiod_i2c_transfer(i2c_device, &data, 1, SI7005_READ_REG_ADDR, 1) != 1) {
        perror("Failed to read data from Si7005");
        gpiod_i2c_device_close(i2c_device);
        gpiod_i2c_bus_close(i2c_bus);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Log data to console
    printf("Humidity: %hu, Temperature: %hu\n", data, (data >> 8) & 0xFF);

    // Sleep for 2 seconds
    sleep(2);
}

// Function to handle SIGINT
void handle_signal(int signum) {
    // Clean up and exit
    printf("SIGINT received, shutting down gracefully...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    gpiod_i2c_device_close(i2c_device);
    // Close I2C bus
    gpiod_i2c_bus_close(i2c_bus);
    // Close I2C file descriptor
    close(i2c_fd);
    // Close GPIO library
    gpiod_close();
}

