void setup_i2c(void) {
    int fd;
    struct i2c_dev *i2c_dev;

    // Open I2C bus
    fd = gpiod_open(GPIOD_I2C, "i2c-1", GPIOD_OPEN_FLAG_RDWR);
    if (fd < 0) {
