    data.az = (int16_t)(data.data[4] << 8 | data.data[5]);
    data.gx = (int16_t)(data.data[6] << 8 | data.data[7]);
    data.gy = (int16_t)(data.data[8] << 8 | data.data[9]);
    data.gz = (int16_t)(data.data[10] << 8 | data.data[11]);
    data.temp = (int16_t)(data.data[12] << 8 | data.data[13]);

