#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/time.h>

#define SHT40_ADDR 0x40 // Sensor address
#define SHT40_CMD_TEMP_HUM 0x00 // Command for temperature and humidity
#define SHT40_CMD_HIGH_REP 0x01 // Command for high-repeatability measurement

#define SHT40_CRC_POLYNOMIAL 0x07 // CRC polynomial
#define SHT40_INIT_CRC 0xFF // Initial CRC value

#define I2C_BUS_NUM 1 // I2C bus number

// Function prototypes
void handle_signal(int signum);
void sht40_read(uint8_t command, uint8_t* data, size_t len);
void validate_crc(uint8_t* data, size_t len, uint8_t crc_init);
void print_temperature_humidity(const uint8_t* temperature, const uint8_t* humidity);
void cleanup();

int main() {
    // Initialize GPIO and I2C
    if (gpiod_open(I2C_BUS_NUM) < 0) {
        perror("gpiod_open");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Wait for 5 seconds
        struct timeval now;
        gettimeofday(&now, NULL);
        int64_t wait_time = 5000 - (now.tv_sec * 1000 + now.tv_usec);
        if (wait_time > 0) {
            usleep(wait_time);
        }

        // Attempt to read temperature and humidity
        uint8_t data[6]; // 2 bytes for temperature, 1 CRC, 2 bytes for humidity, 1 CRC
        sht40_read(SHT40_CMD_HIGH_REP, data, sizeof(data));

        // Validate CRC
        validate_crc(data, sizeof(data), SHT40_INIT_CRC);

        // Print temperature and humidity
        print_temperature_humidity(data + 0, data + 2);

        // Cleanup on exit
        cleanup();
    }

    // Close I2C and GPIO on exit
    gpiod_close();

    return EXIT_SUCCESS;
}

// Function to read data from SHT40 sensor
void sht40_read(uint8_t command, uint8_t* data, size_t len) {
    int fd;
    struct i2c_msg msg = {
        .addr = SHT40_ADDR,
        .flags = 0,
        .len = len,
        .buf = data
    };

    fd = i2c_master_send(I2C_BUS_NUM, &msg, 1);

    if (fd < 0) {
        fprintf(stderr, "Error sending I2C command: %s\n", strerror(errno));
        // Re-open I2C bus
        gpiod_stop(I2C_BUS_NUM);
        gpiod_start(I2C_BUS_NUM);
        fd = i2c_master_send(I2C_BUS_NUM, &msg, 1);
    }

    if (fd < 0) {
        fprintf(stderr, "Error reading from SHT40: %s\n", strerror(errno));
        // Re-open I2C bus
        gpiod_stop(I2C_BUS_NUM);
        gpiod_start(I2C_BUS_NUM);
        fd = i2c_master_send(I2C_BUS_NUM, &msg, 1);
    }

    if (fd < 0) {
        fprintf(stderr, "Failed to read from SHT40\n");
        exit(EXIT_FAILURE);
    }
}

// Function to validate CRC
void validate_crc(uint8_t* data, size_t len, uint8_t crc_init) {
    uint8_t crc = crc_init;
    for (size_t i = 0; i < len; ++i) {
        crc = (crc ^ data[i]) & 0x80;
        if (crc == 0) {
            break;
        }
        crc <<= 1;
        if (crc == 0x80) {
            crc = 0x80;
        }
    }

    if (crc != data[len - 2]) {
        fprintf(stderr, "CRC error detected in SHT40 response\n");
        exit(EXIT_FAILURE);
    }
}

// Function to print temperature and humidity
void print_temperature_humidity(const uint8_t* temperature, const uint8_t* humidity) {
    uint16_t temperature_value = (temperature[0] << 8) | temperature[1];
    uint16_t humidity_value = (humidity[0] << 8) | humidity[1];

    printf("Temperature: %.1f°C\n", (temperature_value / 16.0) * 100.0);
    printf("Humidity: %.1f%%\n", (humidity_value / 256.0) * 100.0);
}

// Function to perform cleanup and exit on signal
void handle_signal(int signum) {
    // Perform cleanup
    cleanup();

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to clean up resources
void cleanup() {
    // Close I2C handle
    if (i2c_master_fd != -1) {
        close(i2c_master_fd);
        i2c_master_fd = -1;
    }

    // Close GPIO handle
    if (gpiod_fd != -1) {
        close(gpiod_fd);
        gpiod_fd = -1;
    }
}

