#include <gpiod.h>
#include <stdio.h>

#define SENSOR_ADDR 0x5C // Sensirion STS30-DIS I2C address
#define I2C_BUS_NUM 1
#define SAMPLE_INTERVAL 5000 // 5 seconds

// Function prototypes
void i2c_init();
int i2c_read(uint8_t addr, uint8_t reg, uint8_t* data);
void i2c_release();
void handle_errors(const char* message);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize GPIO and I2C
    i2c_init();

    // File descriptors for logging
    int temp_log_fd = -1;
    int error_log_fd = -1;

    // Attempt to open files for writing
    temp_log_fd = fopen("enclosure_temp_log.txt", "a+");
    if (temp_log_fd == -1) {
        perror("Failed to open enclosure_temp_log.txt");
        exit(EXIT_FAILURE);
    }

    error_log_fd = fopen("error_log.txt", "a+");
    if (error_log_fd == -1) {
        perror("Failed to open error_log.txt");
        fclose(temp_log_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        struct timespec ts;
        time_t now = time(NULL);
        struct tm* timeinfo = localtime(&now);
        ts.tv_sec = now;
        ts.tv_nsec = (timeinfo->tm_sec * 1000000) + (timeinfo->tm_min * 1000000) + (timeinfo->tm_hour * 100000000);

        uint8_t temperature;
        int result = i2c_read(SENSOR_ADDR, 0x00, &temperature);

        if (result == 0) {
            // Successful read
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
            fprintf(temp_log_fd, "%s: %hu\n", timestamp, temperature);
        } else {
            // Error occurred during I2C read
            handle_errors("I2C read error");
        }

        // Sleep for the interval
        usleep(SAMPLE_INTERVAL * 1000000);

        // Check for termination signals
        if (signal(SIGINT) == SIG_IGN) {
            signal(SIGINT, SIG_DFL); // Restore default SIGINT handler
        }
        if (WIFEXITED(getpid())) {
            // Ctrl+C detected, perform cleanup
            cleanup();
            break;
        }
    }

    // Release resources
    i2c_release();

    // Close file descriptors
    fclose(temp_log_fd);
    fclose(error_log_fd);

    return 0;
}

