    int fd = gpio_i2c_open(I2C_BUS_NUM, GPIO_I2C_SPEED_100KHZ);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    i2c_release();
}

