int i2c_read(uint8_t addr, uint8_t reg, uint8_t* data) {
    int ret = -1;
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = 1,
        .buf = (void*)data
    };

    ret = gpio_i2c_transfer(fd, &msg, 1);
    if (ret < 0) {
        handle_errors("I2C transfer failed");
    } else if (ret != 1) {
        handle_errors("I2C transfer returned unexpected result");
    }

    return ret;
}

// Function to release I2C resources
void i2c_release() {
    gpio_i2c_close(fd);
}

// Function to handle and log error messages
void handle_errors(const char* message) {
    fprintf(error_log_fd, "%s\n", message);
}

// Function to perform cleanup and exit
void cleanup() {
    // Close file descriptors
    fclose(temp_log_fd);
    fclose(error_log_fd);

    // Release I2C and GPIO resources
    i2c_release();
}

