    uint16_t temp_MSB;
    uint16_t temp_LSB;
    uint8_t crc_temp;
    uint16_t hum_MSB;
    uint16_t hum_LSB;
    uint8_t crc_hum;
} sht40_data;

// Function to calculate CRC-8
uint8_t crc8(uint8_t *buf, uint8_t len) {
    uint8_t crc = crc8_init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= *buf++;
        for (uint8_t j = 0; j < 8; j++) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ crc8_poly;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

