    // Open I2C device
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Check if device was opened successfully
    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Log file descriptor
    FILE *log_file = fopen("sht40_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return EXIT_FAILURE;
    }

