        // Issue measurement command
        uint8_t cmd = SHT40_CMD_HIGH_REP;
        if (write(fd, &cmd, 1) != 1) {
            fprintf(log_file, "Failed to write command to SHT40\n");
            continue; // Retry on next cycle
        }

        // Wait for the response
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = SHT40_READ_TIMEOUT * 1000000 };
        if (nanosleep(&timeout, NULL) == -1) {
            perror("Failed to wait for SHT40 response");
            continue; // Retry on next cycle
        }

        // Read 6 bytes from the sensor
        uint8_t data[6];
        if (read(fd, data, 6) != 6) {
            fprintf(log_file, "Failed to read data from SHT40\n");
            continue; // Retry on next cycle
        }

        // Calculate CRC for temperature and humidity data
        uint8_t crc_temp = crc8(data, 4); // First 4 bytes are temperature
        uint8_t crc_hum = crc8(&data[4], 2); // Last 2 bytes are humidity

        // Validate CRCs
        if (data[3] != crc_temp || data[5] != crc_hum) {
            fprintf(log_file, "CRC error in SHT40 response\n");
            continue; // Retry on next cycle
        }

        // Extract temperature and humidity values
        sht40_data sht40_data;
        sht40_data.temp_MSB = (data[0] << 8) | data[1];
        sht40_data.temp_LSB = data[2];
        sht40_data.hum_MSB = (data[4] << 8) | data[5];

        // Convert temperature from 12-bit to Celsius
        float temp_celsius = ((float)sht40_data.temp_MSB << 8) | sht40_data.temp_LSB;
        temp_celsius /= 16384.0;
        temp_celsius -= 25.0; // Convert to Celsius

        // Convert humidity from 12-bit to percentage
        float humidity_percentage = ((float)sht40_data.hum_MSB << 8) | sht40_data.hum_LSB;
        humidity_percentage /= 4096.0;
        humidity_percentage *= 100.0;

        // Log timestamped temperature and humidity
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);
        fprintf(log_file, "Temperature: %.2f°C, Humidity: %.2f%% at %s\n", temp_celsius, humidity_percentage, timestamp);

        // Sleep for 5 seconds before next measurement
        sleep(5);
    }

    // Close I2C device and log file on SIGINT or SIGTERM
    int sig = 0;
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("Failed to ignore SIGINT");
    }
    if (signal(SIGTERM, SIG_IGN) == SIG_ERR) {
        perror("Failed to ignore SIGTERM");
    }

    close(fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

