                usleep(1000 * (pow(2, retry_count) - 1)); // Exponential backoff
                if (!gpiod_i2c_write(i2c_handle, SDP31_ADDR, SDP31_CMD_TRIGGER_CONTINUOUS_MEASUREMENT, 1)) {
                    fprintf(stderr, "Failed to trigger measurement after %d retry(s).\n", retry_count);
