        // Wait at least 1ms after triggering
        usleep(1000000);

        // Read measurement data
        if (!gpiod_i2c_read(i2c_handle, SDP31_ADDR, SDP31_REG_MEASUREMENT_DATA, 6, (void *)&response)) {
            fprintf(stderr, "Failed to read measurement data.\n");
            // Retry with exponential backoff
            int retry_count = 0;
            while (retry_count < 3) {
                usleep(1000000 * (pow(2, retry_count) - 1)); // Exponential backoff
                if (!gpiod_i2c_read(i2c_handle, SDP31_ADDR, SDP31_REG_MEASUREMENT_DATA, 6, (void *)&response)) {
                    fprintf(stderr, "Failed to read measurement data after %d retry(s).\n", retry_count);
                    break;
                }
                retry_count++;
            }
        }

        // Convert and append data to the log file
        convertAndAppendData(&response);

        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup on exit
    cleanup();

    // Close I2C handle and log file
    gpiod_i2c_close(i2c_handle);
    fclose(logfile);

    return EXIT_SUCCESS;
