int main() {
    // Initialize the SDP800 sensor
    init_sensirion();

    // Main loop
    while (1) {
        // Trigger continuous measurement
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
            perror("Error: i2c slave access");
            exit(EXIT_FAILURE);
        }
        if (ioctl(i2c_fd, I2C_WRITE, &SDP800_REG_MEASURE_CONT) == -1) {
            perror("Error: writing to SDP800");
            exit(EXIT_FAILURE);
        }

        // Wait approximately 45 ms
        usleep(45000);

        // Read data from SDP800
        uint8_t data[9];
        if (ioctl(i2c_fd, I2C_READ, data, sizeof(data)) == -1) {
            perror("Error: reading from SDP800");
            exit(EXIT_FAILURE);
        }

        // Validate CRC-8 words
        if (!crc8_valid(data, sizeof(data))) {
            fprintf(stderr, "CRC error detected in SDP800 data\n");
            continue;
        }

        // Process and log the data
        process_data(data[0], data[1]);

        // Sleep for 100 ms
        usleep(100000);

        // Handle SIGINT and SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            perror("Error: setting signal handlers");
            exit(EXIT_FAILURE);
        }
    }

    // Clean up resources
    cleanup();

    return 0;
