        exit(EXIT_FAILURE);
    }

    // Check if device is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error: accessing I2C slave");
        exit(EXIT_FAILURE);
    }
}

