    uint8_t data[9];
    // Read 9 bytes from the sensor
    if (ioctl(i2c_fd, I2C_READ, data, sizeof(data)) == -1) {
        perror("Error: reading from SDP800");
        exit(EXIT_FAILURE);
    }
}

void process_data(uint16_t pressure, uint16_t temperature) {
    char timestamp[50];
    time_t now = time(NULL);
    struct tm timeinfo;
    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    char line[256];
    sprintf(line, "%s,%d,%d", timestamp, pressure / 100.0, temperature / 10.0);

    // Open or create the file for writing
    FILE *file = fopen("airflow_data.txt", "a+");
    if (file == NULL) {
        perror("Error: opening file for writing");
        exit(EXIT_FAILURE);
    }

    // Write the line to the file
    if (fwrite(line, sizeof(line), 1, file) == 0) {
        perror("Error: writing to file");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    fclose(file);
}

