    uint8_t T_MSB;
    uint8_t T_LSB;
    uint8_t T_CRC;
    uint8_t RH_MSB;
    uint8_t RH_LSB;
    uint8_t RH_CRC;
} sht40_data;

// Function to calculate CRC-8
uint8_t sht40_crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = INITIAL_VALUE;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Function to read SHT40 data over I2C
int read_sht40_data(int fd) {
    struct i2c_msg msg = {
        .addr = SHT40_ADDR,
        .flags = 0,
        .len = sizeof(sht40_data),
        .buf = (void *)&(sht40_data{})
    };

    int ret = ioctl(fd, I2C_SLAVE, SHT40_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to select SHT40 address\n");
        return -1;
    }

    ret = ioctl(fd, I2C_RDWR, &msg);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to write command to SHT40\n");
        return -1;
