    ret = read(fd, (void *)&(sht40_data{}.buf), sizeof(sht40_data));
    if (ret != sizeof(sht40_data) || (ret == -1 && errno != EAGAIN)) {
        fprintf(stderr, "Error: Failed to read response from SHT40\n");
