#define SHT40_ADDR 0x40 // Fixed I2C address for SHT40
#define SHT40_CMD 0x00 // High repeatability measurement command
#define SHT40_READ_TIMEOUT 1000 // 1 second timeout for I2C read

// CRC-8 polynomial and initial value for SHT40
#define POLYNOMIAL 0x07
#define INITIAL_VALUE 0x00

// SHT40 data structure for the response
typedef struct {
    uint8_t T_MSB;
    uint8_t T_LSB;
    uint8_t T_CRC;
    uint8_t RH_MSB;
    uint8_t RH_LSB;
    uint8_t RH_CRC;
} sht40_data;

// Function to calculate CRC-8
uint8_t sht40_crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = INITIAL_VALUE;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Function to read SHT40 data over I2C
int read_sht40_data(int fd) {
    struct i2c_msg msg = {
        .addr = SHT40_ADDR,
        .flags = 0,
        .len = sizeof(sht40_data),
        .buf = (void *)&(sht40_data{})
    };

    int ret = ioctl(fd, I2C_SLAVE, SHT40_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to select SHT40 address\n");
        return -1;
    }

    ret = ioctl(fd, I2C_RDWR, &msg);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to write command to SHT40\n");
        return -1;
    }

    ret = read(fd, (void *)&(sht40_data{}.buf), sizeof(sht40_data));
    if (ret != sizeof(sht40_data) || (ret == -1 && errno != EAGAIN)) {
        fprintf(stderr, "Error: Failed to read response from SHT40\n");
        return -1;
    }

    // Calculate CRC and validate
    uint8_t crc_received = sht40_data{}.T_CRC;
    if (sht40_crc8(sht40_data{}.buf, 6) != crc_received) {
        fprintf(stderr, "Error: CRC mismatch, data not valid\n");
        return -1;
    }

    return 0;
}

// Function to write timestamped data to log file
void write_to_log_file(const char *timestamp, float temperature, float humidity) {
    char line[256];
    sprintf(line, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
    FILE *log_file = fopen("sht40_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file for writing\n");
        return;
    }
    fprintf(log_file, "%s", line);
    fclose(log_file);
}

