    int fd;
    struct timeval tv;
    char buffer[4]; // For storing timestamp
    float temperature, humidity;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        return 1;
    }

    // Set up a signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Get current time
        gettimeofday(&tv, NULL);

        // Convert time to a string
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tv);

        // Read temperature and humidity
        if (read_sht40_data(fd) < 0) {
            fprintf(stderr, "Error reading from SHT40 sensor\n");
            continue;
        }

        temperature = (sht40_data{}.T_MSB << 8) | sht40_data{}.T_LSB;
        humidity = ((sht40_data{}.RH_MSB << 4) | sht40_data{}.RH_LSB) / 16.0;

        // Write to log file
        write_to_log_file(buffer, temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on SIGINT (Ctrl+C)
    sa.sa_handler = SIG_DFL; // Restore default SIGINT behavior
    sigaction(SIGINT, &sa, NULL);

    // Close I2C file descriptor and log file
    close(fd);
    fclose(log_file);

    return 0;
}
