#define SI7021_ADDR 0x40 // I2C address of the Si7021 sensor
#define FAN_GPIO 18 // GPIO 18 for fan control
#define FAN_ON_THRESHOLD 28.0 // Temperature threshold to turn on fan
#define FAN_OFF_THRESHOLD 27.0 // Temperature threshold to turn off fan
#define MAX_READINGS 60 // Maximum size of the circular buffer

// Structure to hold sensor reading and timestamp
typedef struct {
    float temperature;
    time_t timestamp;
} SensorReading;

// Circular buffer for readings
static SensorReading readings[MAX_READINGS];

// Function prototypes
void setup_fan_control();
void read_sensor(float *temperature);
void handle_i2c_error(int error);
void handle_fan_hysteresis();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIO for fan control
    setup_fan_control();

    // Initialize I2C for sensor communication
    int i2c_fd = i2c_open(1, I2C_SLAVE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Check if the fan needs to be turned on due to temperature
        handle_fan_hysteresis();

        // Read sensor and handle I2C errors
        read_sensor(&readings[readings_idx]);

        // Print the reading and update the index
        printf("Temperature: %.1f°C at %s\n", readings[readings_idx].temperature, ctime(&readings[readings_idx].timestamp));
        readings_idx = (readings_idx + 1) % MAX_READINGS;

        // Sleep for 2 seconds
        sleep(2);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to set up fan control
void setup_fan_control() {
    struct gpiod_dir gpio_dir;
    struct gpiod_set gpio_set;

    // Open GPIO 18
    int fan_gpio = gpiod_open(FAN_GPIO, GPIO_DIR_OUT);
    if (fan_gpio < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", FAN_GPIO, gpiod_get_name(fan_gpio));
        exit(EXIT_FAILURE);
    }

    // Set up the GPIO direction and value
    gpio_dir.direction = GPIO_DIR_OUT;
    gpio_set.value = 1; // Active high
    gpiod_set_value(fan_gpio, &gpio_set);

    // Set up hysteresis
    gpio_set.value = 0; // Turn off fan
    gpiod_set_value(fan_gpio, &gpio_set);

    // Turn on fan when temperature exceeds threshold
    handle_fan_hysteresis();
}

// Function to read sensor data
void read_sensor(float *temperature) {
    int bytes_read;
    struct i2c_msg msg = {
        .addr = SI7021_ADDR,
        .flags = 0,
        .len = 2, // 2-byte temperature reading
        .buf = (unsigned char *)temperature
    };

    // Perform I2C transaction
    bytes_read = i2c_transfer(i2c_fd, &msg, 1);
    if (bytes_read != 2) {
        handle_i2c_error(bytes_read);
        return;
    }

    // Temperature is in two's complement format
    *temperature = (float) (*temperature & 0xFF) + ((*(temperature + 1) & 0xFF) << 8);
}

// Handle I2C errors
void handle_i2c_error(int error) {
    fprintf(stderr, "I2C transaction failed: %s\n", strerror(error));
    // Retry up to three times
    for (int retry = 0; retry < 3; ++retry) {
        if (i2c_transfer(i2c_fd, &msg, 1) == 2) {
            // Transaction was successful
            break;
        }
        sleep(100); // Wait before retrying
    }

    // Sensor absent condition
    if (retry == 3) {
        fprintf(stderr, "Sensor not found or not responding.\n");
        exit(EXIT_FAILURE);
    }
}

// Handle fan hysteresis logic
void handle_fan_hysteresis() {
    float current_temperature;

    // Read temperature from sensor
    read_sensor(&current_temperature);

    // Turn on fan if temperature exceeds threshold
    if (current_temperature > FAN_ON_THRESHOLD) {
        gpiod_set_value(FAN_GPIO, &gpio_set); // Turn fan on
    } else {
        gpiod_set_value(FAN_GPIO, &gpio_set); // Turn fan off
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Turn off the fan
    gpiod_set_value(FAN_GPIO, &gpio_set);

    // Close I2C handle
    i2c_close(i2c_fd);

    // Invoke cleanup function
    cleanup();
}

// Cleanup function
void cleanup() {
    // Close GPIO
    gpiod_close(FAN_GPIO);

    // Close I2C
    i2c_close(i2c_fd);
}

