    // Open GPIO 18
    int fan_gpio = gpiod_open(FAN_GPIO, GPIO_DIR_OUT);
    if (fan_gpio < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", FAN_GPIO, gpiod_get_name(fan_gpio));
        exit(EXIT_FAILURE);
    }

    // Set up the GPIO direction and value
    gpio_dir.direction = GPIO_DIR_OUT;
    gpio_set.value = 1; // Active high
    gpiod_set_value(fan_gpio, &gpio_set);

    // Set up hysteresis
    gpio_set.value = 0; // Turn off fan
    gpiod_set_value(fan_gpio, &gpio_set);

    // Turn on fan when temperature exceeds threshold
    handle_fan_hysteresis();
}

// Function to read sensor data
void read_sensor(float *temperature) {
    int bytes_read;
    struct i2c_msg msg = {
        .addr = SI7021_ADDR,
        .flags = 0,
        .len = 2, // 2-byte temperature reading
        .buf = (unsigned char *)temperature
    };

    // Perform I2C transaction
    bytes_read = i2c_transfer(i2c_fd, &msg, 1);
    if (bytes_read != 2) {
        handle_i2c_error(bytes_read);
        return;
    }

    // Temperature is in two's complement format
    *temperature = (float) (*temperature & 0xFF) + ((*(temperature + 1) & 0xFF) << 8);
}

// Handle I2C errors
void handle_i2c_error(int error) {
    fprintf(stderr, "I2C transaction failed: %s\n", strerror(error));
    // Retry up to three times
    for (int retry = 0; retry < 3; ++retry) {
        if (i2c_transfer(i2c_fd, &msg, 1) == 2) {
            // Transaction was successful
            break;
        }
        sleep(100); // Wait before retrying
    }

    // Sensor absent condition
    if (retry == 3) {
        fprintf(stderr, "Sensor not found or not responding.\n");
        exit(EXIT_FAILURE);
    }
}

// Handle fan hysteresis logic
void handle_fan_hysteresis() {
    float current_temperature;

    // Read temperature from sensor
    read_sensor(&current_temperature);

    // Turn on fan if temperature exceeds threshold
    if (current_temperature > FAN_ON_THRESHOLD) {
        gpiod_set_value(FAN_GPIO, &gpio_set); // Turn fan on
    } else {
        gpiod_set_value(FAN_GPIO, &gpio_set); // Turn fan off
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Turn off the fan
    gpiod_set_value(FAN_GPIO, &gpio_set);

    // Close I2C handle
    i2c_close(i2c_fd);

    // Invoke cleanup function
    cleanup();
}

// Cleanup function
void cleanup() {
    // Close GPIO
    gpiod_close(FAN_GPIO);

    // Close I2C
    i2c_close(i2c_fd);
}

