#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <stdint.h>

#define SCD40_ADDR 0x5A
#define SCD40_CMD_READ_DATA 0x02
#define SCD40_READ_DATA_BLOCK_SIZE 9
#define SCD40_CRC_POLYNOMIAL 0x08

// Sensor data structure
typedef struct {
    uint16_t co2_ppm;
    uint8_t temperature_c;
    uint8_t humidity_pct;
} SCD40_Data;

// CRC8 function
uint8_t crc8(uint8_t *buf, uint8_t len) {
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= buf[i];
        for (uint8_t j = 8; j; j--) {
            if (crc & 1) {
                crc = (crc >> 1) ^ 0x08;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize GPIO
    int gpio_dev = gpiod_get_device_by_name("BCM2835-I2C.1");
    if (gpio_dev == -1) {
        fprintf(stderr, "Error: Could not find I2C device.\n");
        return EXIT_FAILURE;
    }

    // Open I2C device
    int i2c_fd = open(gpiod_get_reg_path(gpio_dev), O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Could not open I2C device.\n");
        close(gpio_dev);
        return EXIT_FAILURE;
    }

    // Initialize libgpiod I2C driver
    if (gpiod_i2c_driver_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: Failed to initialize I2C driver.\n");
        close(i2c_fd);
        gpiod_uninit_driver(gpio_dev);
        return EXIT_FAILURE;
    }

    // Sensor configuration
    uint8_t command[] = { SCD40_CMD_READ_DATA };
    uint8_t data_ready_flag = 0x00;
    uint8_t crc8_init = 0xFF;
    uint8_t read_data_block[SCD40_READ_DATA_BLOCK_SIZE] = { 0 };

    // Log file setup
    char log_file_path[] = "/tmp/air_quality.log";
    FILE *log_file = fopen(log_file_path, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", log_file_path);
        fclose(i2c_fd);
        gpiod_uninit_driver(gpio_dev);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for at least 1 second before the first read
        struct timeval now;
        gettimeofday(&now, NULL);
        if (now.tv_sec < 1) {
            usleep(1000000); // Wait for 1 second
        }

        // Check data ready flag
        if (gpiod_i2c_read(gpio_dev, SCD40_ADDR, &data_ready_flag, 1) < 0) {
            fprintf(stderr, "Error: Failed to read data ready flag.\n");
            continue;
        }

        if (data_ready_flag == 0x00) {
            // Data not ready, continue waiting
            continue;
        }

        // Read data block
        if (gpiod_i2c_read(gpio_dev, SCD40_ADDR, read_data_block, SCD40_READ_DATA_BLOCK_SIZE) < 0) {
            fprintf(stderr, "Error: Failed to read data block.\n");
            continue;
        }

        // Verify CRC
        uint8_t crc = crc8(read_data_block, SCD40_READ_DATA_BLOCK_SIZE);
        if (crc != read_data_block[6] || crc != read_data_block[7]) {
            fprintf(stderr, "Error: CRC check failed.\n");
            continue;
        }

        // Extract data
        SCD40_Data data;
        data.co2_ppm = read_data_block[0];
        data.temperature_c = read_data_block[1];
        data.humidity_pct = read_data_block[2];

        // Append to log file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, %d, %d, %.1f\n", timestamp, data.co2_ppm, data.temperature_c, data.humidity_pct / 100.0);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // SIGINT handler
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Stop periodic measurement and clean up
    gpiod_i2c_write(gpio_dev, SCD40_ADDR, &SCD40_CMD_STOP_MEASUREMENT, 1);
    close(i2c_fd);
    gpiod_uninit_driver(gpio_dev);

    // Close log file
    fclose(log_file);

    return EXIT_SUCCESS;
}

