#include <stdint.h>

#define SHT35_ADDR 0x40 // I2C address of SHT35 sensor
#define SHT35_CMD 0x00 // Command for high-repeatability measurement
#define SHT35_TIMEOUT 1000 // 1 second timeout for I2C operations

// Sensor configuration and conversion constants
#define SHT35_TEMP_BITS 12
#define SHT35_HUMIDITY_BITS 8
#define SHT35_TEMP_OFFSET 0x04 // Offset for temperature data
#define SHT35_HUMIDITY_OFFSET 0x03 // Offset for humidity data
#define SHT35_CRC_BYTE 0x07 // CRC byte position

// Sensirion conversion formulas
#define SHT35_TO_HUMIDITY(raw_humidity) (((uint16_t)(raw_humidity) & 0x3F) * 125.0 / 256.0)
#define SHT35_TO_TEMPERATURE(raw_temperature) (((uint16_t)(raw_temperature - SHT35_TEMP_OFFSET) & 0xFF) * 0.0625)

// Sinusoidal offset parameters
#define OFFSET_AMPLITUDE 2.0
#define OFFSET_PERIOD_SECONDS 3600 // One hour

// GPIO driver initialization
int gpio_init(void);

// I2C driver initialization
int i2c_init(const char *i2c_bus);

// Function to read from SHT35 sensor
int sht35_read(uint8_t command, uint8_t *data, int len);

// Function to validate CRC for SHT35 data
int sht35_crc_check(const uint8_t *data, int len);

// Function to apply sinusoidal offset to temperature and humidity
void apply_offset(float *temperature, float *humidity);

// Main function
int main(void) {
    struct timespec start_time;
    struct stat file_status;
    int i2c_fd, gpio_fd;
    uint8_t sht35_data[6];
    int retries = 3;
    int rc;

    // Initialize GPIO and I2C
    gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = i2c_init("i2c-1");
    if (i2c_fd < 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Open the log file
    char filename[256] = "environmental_data.txt";
    if ((rc = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR)) < 0) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        close(i2c_fd);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Get the start time
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (1) {
        // Read temperature and humidity from SHT35
        if (sht35_read(SHT35_CMD, sht35_data, 6) < 0) {
            // Handle I2C read/write errors
            fprintf(stderr, "Failed to read from SHT35 after %d retries.\n", retries);
            apply_offset(&sht35_data[SHT35_TEMP_OFFSET], &sht35_data[SHT35_HUMIDITY_OFFSET]);
            snprintf(filename, sizeof(filename), "environmental_data.txt");
            fprintf(file_fd, "%s,%f,%f\n", "timestamp", start_time.tv_sec + (retries * OFFSET_PERIOD_SECONDS / 60), apply_offset(&sht35_data[SHT35_TEMP_OFFSET], &sht35_data[SHT35_HUMIDITY_OFFSET]));
            close(i2c_fd);
            close(gpio_fd);
            return EXIT_FAILURE;
        }

        // Validate CRC
        if (!sht35_crc_check(sht35_data, 6)) {
            // Handle CRC check failure
            fprintf(stderr, "CRC check failed for SHT35 data.\n");
            apply_offset(&sht35_data[SHT35_TEMP_OFFSET], &sht35_data[SHT35_HUMIDITY_OFFSET]);
            snprintf(filename, sizeof(filename), "environmental_data.txt");
            fprintf(file_fd, "%s,%f,%f\n", "timestamp", start_time.tv_sec + (retries * OFFSET_PERIOD_SECONDS / 60), apply_offset(&sht35_data[SHT35_TEMP_OFFSET], &sht35_data[SHT35_HUMIDITY_OFFSET]));
            close(i2c_fd);
            close(gpio_fd);
            return EXIT_FAILURE;
        }

        // Apply sinusoidal offset
        apply_offset(&sht35_data[SHT35_TEMP_OFFSET], &sht35_data[SHT35_HUMIDITY_OFFSET]);

        // Convert raw values to Celsius and percent RH
        float temperature_c = SHT35_TO_TEMPERATURE(sht35_data[SHT35_TEMP_BITS]);
        float humidity_percent = SHT35_TO_HUMIDITY(sht35_data[SHT35_HUMIDITY_BITS]);

        // Log the reading
        snprintf(filename, sizeof(filename), "environmental_data.txt");
        struct tm tm_now;
        time(&tm_now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);
        fprintf(file_fd, "%s,%f,%f\n", timestamp, temperature_c, humidity_percent);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close resources on exit
    close(file_fd);
    close(i2c_fd);
    close(gpio_fd);

    return EXIT_SUCCESS;
}

// Function to initialize GPIO driver
int gpio_init(void) {
    int gpio_dev;
    struct gpio_desc *gpio;

    // Open GPIO device
    gpio_dev = gpio_open("gpiochip0");
    if (gpio_dev < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", strerror(errno));
        return -1;
    }

    // Request access to the GPIO pins used by the SHT35
    gpio = gpio_request_array(gpio_dev, 2, GPIO_NUM_TO_NAME(7), GPIO_NUM_TO_NAME(8));
    if (gpio == NULL) {
        fprintf(stderr, "Error requesting GPIO pins: %s\n", strerror(errno));
        gpio_close(gpio_dev);
        return -1;
    }

    return gpio_dev;
}

// Function to initialize I2C driver
int i2c_init(const char *i2c_bus) {
    int i2c_fd;

    // Open I2C device
    i2c_fd = open("/dev/i2c-" + i2c_bus, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Perform I2C driver initialization (hypothetical function call)
    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

// Function to read from SHT35 sensor
int sht35_read(uint8_t command, uint8_t *data, int len) {
    int bytes_transferred;
    struct timeval timeout;

    // Set timeout for 1 second
    timeout.tv_sec = SHT35_TIMEOUT;
    timeout.tv_usec = 0;

    // Perform I2C read operation
    if (ioctl(i2c_fd, I2C_RDWR, (char *) &command) < 0) {
        fprintf(stderr, "Error writing command to SHT35: %s\n", strerror(errno));
        return -1;
    }

    bytes_transferred = write(i2c_fd, data, len);
    if (bytes_transferred != len) {
        fprintf(stderr, "Error reading from SHT35: %s\n", strerror(errno));
        return -1;
    }

    // Check for timeout
    if (timeout.tv_sec || (timeout.tv_usec / 1000) > 0) {
        fprintf(stderr, "I2C read timed out.\n");
        return -1;
    }

    return bytes_transferred;
}

// Function to validate CRC for SHT35 data
int sht35_crc_check(const uint8_t *data, int len) {
    uint8_t crc = 0;

    // Calculate CRC using polynomial 0x07
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }

    return crc == data[SHT35_CRC_BYTE];
}

// Function to apply sinusoidal offset to temperature and humidity
void apply_offset(float *temperature, float *humidity) {
    float time_in_seconds = (float)time(NULL) / 60.0; // Current time in minutes

    *temperature += OFFSET_AMPLITUDE * sin(2 * M_PI * time_in_seconds / OFFSET_PERIOD_SECONDS);
    *humidity += OFFSET_AMPLITUDE * sin(2 * M_PI * time_in_seconds / OFFSET_PERIOD_SECONDS) * 0.05;
}

