bool crc8_check(uint8_t data[], uint8_t len, uint8_t crc) {
    uint8_t crc_temp = crc;
    for (uint8_t i = 0; i < len; i++) {
        crc_temp = crc_temp ^ (data[i] >> (7 - i));
        if (crc_temp == 0) {
            return false;
        }
        crc_temp = crc_temp >> 1;
        if (crc_temp) {
            crc_temp = crc_temp ^ 0x07;
        }
    }
    return crc_temp == 0;
}

