            perror("write to SDP810");
            break; // Exit loop on error
        }

        // Wait for conversion time (assumed to be 10 ms)
        usleep(10000);

        // Read 9 bytes from the sensor
        uint8_t data[9];
        if (read(i2c_fd, data, 9) != 9) {
            perror("read from SDP810");
            break; // Exit loop on error
        }

        // Validate CRCs for pressure and temperature
        uint8_t crc_pressure = crc8(data + 0, 3);
        uint8_t crc_temperature = crc8(data + 3, 4);

        if (crc_pressure != data[2] || crc_temperature != data[6]) {
            fprintf(stderr, "CRC error detected\n");
            break; // Exit loop on CRC error
        }

        // Convert raw pressure and temperature to float
        float pressure = convertRawToFloat(data[0] | (data[1] << 8));
        float temperature = convertRawToFloat(data[3] | (data[4] << 8));

        // Log pressure and temperature to file
        if (write(file_fd, &pressure, sizeof(float)) != sizeof(float) ||
            write(file_fd, &temperature, sizeof(float)) != sizeof(float)) {
            perror("write to airflow.dat");
            break; // Exit loop on write error
        }

        // Print debug information
        printf("Pressure: %.2f Pa, Temperature: %.2f°C\n", pressure, temperature);
    }

    // Cleanup on SIGINT or SIGTERM
    cleanup();

    // Close resources
    close(i2c_fd);
    close(file_fd);

    return EXIT_SUCCESS;
}

// Function to perform graceful shutdown
void cleanup() {
    // Close file handle
    if (file_fd != -1) {
        close(file_fd);
    }

    // Terminate libgpiod
    gpiod_exit();
}

