volatile sig_atomic_t should_exit = false;

void error_log(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    fprintf(stderr, "Error at: %s", ctime(&time(NULL)));
    fprintf(stderr, "\n");
    fprintf(stderr, "Writing to environmental_data.txt...");
    fflush(stderr);
    FILE *log_file = fopen("environmental_data.txt", "a+");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }
    fprintf(log_file, "%s\n", msg);
    fclose(log_file);
}

int main() {
    struct timespec ts;
    int fd, i2c_fd;
    uint8_t buf[6];
    int pressure, temperature;
    time_t now;

    // Initialize GPIO
    gpiod_init();

    // Attempt to open the I2C device
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        error_log("Failed to open I2C device");
        return 1;
    }

    // Open log file for appending
    if ((log_file = fopen("environmental_data.txt", "a+")) == NULL) {
        error_log("Failed to open log file");
        close(fd);
        exit(1);
    }

    // Initialize the I2C device
