#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>
#include <signal.h>
#include <libgpiod.h>
#include <gpiod.h>
#include <stdint.h>

#define SCD30_I2C_ADDR 0x5C
#define SCD30_REG_CO2 0x00
#define SCD30_REG_TEMP 0x01
#define SCD30_REG_HUMIDITY 0x02

#define LOG_FILE_PATH "air_quality.log"
#define SAMPLE_INTERVAL_MS 5000

// Function prototypes
void handle_signal(int signum);
void read_scd30_data(uint8_t* data);
void process_and_log_data(uint8_t* data);
void close_and_cleanup();
void error_handler(const char* msg);

// Main function
int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        error_handler("Failed to initialize libgpiod");
        return EXIT_FAILURE;
    }

    // Open the I2C bus
    int i2c_fd = -1;
    if ((i2c_fd = i2c_open(0)) < 0) {
        error_handler("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set up the I2C device context
    struct i2c_dev *i2c_dev = i2c_new_device(i2c_fd, SCD30_I2C_ADDR);
    if (!i2c_dev) {
        error_handler("Failed to create I2C device context");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up the GPIO context for the SCD30
    struct gpio_desc *co2_pin = gpio_request_one(SCD30_REG_CO2, GPIO_IN, "SCD30 CO2 pin");
    if (!co2_pin) {
        error_handler("Failed to request GPIO for SCD30 CO2 pin");
        i2c_device_put(i2c_dev);
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Ventilation control states
    int ventilation_state = VENTILATION_OFF;

    // Main loop
    while (1) {
        // Sample data
        uint8_t data[3];
        read_scd30_data(data);

        // Process and log data
        process_and_log_data(data);

        // Check ventilation state based on CO₂ reading
        ventilation_state = determine_ventilation_state(data[0]);

        // Sleep for the interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up and exit
    close_and_cleanup();

    return EXIT_SUCCESS;
}

// Function to read data from the SCD30 sensor
void read_scd30_data(uint8_t* data) {
    int ret;
    // Write to the CO2 register
    ret = i2c_smbus_write_byte_data(i2c_dev, SCD30_REG_CO2, 0x00);
    if (ret < 0) {
        error_handler("Failed to write to SCD30 CO2 register");
        return;
    }

    // Read the CO2, temperature, and humidity data
    ret = i2c_smbus_read_i2c_block_data(i2c_dev, SCD30_REG_CO2, 3, data);
    if (ret != 3 || data[0] != 0x00 || data[1] != 0x00 || data[2] != 0x00) {
        error_handler("Failed to read from SCD30 sensor or CRC mismatch");
        return;
    }
}

// Function to process and log the data
void process_and_log_data(uint8_t* data) {
    uint8_t co2_ppm = data[0];
    uint8_t temp_c = (data[1] >> 4) | ((data[1] & 0x0F) << 4);
    uint8_t humidity_rh = (data[2] >> 4) | ((data[2] & 0x0F) << 4);

    // Format the data as a CSV line
    char csv_line[256];
    strftime(csv_line, sizeof(csv_line), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&time(NULL)));
    sprintf(csv_line + strlen(csv_line) - 1, "%d,%d,%d", co2_ppm, temp_c, humidity_rh);

    // Open the log file for appending
    FILE *log_file = fopen(LOG_FILE_PATH, "a+");
    if (!log_file) {
        error_handler("Failed to open log file for writing");
        return;
    }

    // Write the CSV line to the log file
    if (fwrite(csv_line, 1, sizeof(csv_line), log_file) != sizeof(csv_line)) {
        error_handler("Failed to write to log file");
        fclose(log_file);
        return;
    }

    // Flush the log file buffer
    fflush(log_file);

    // Close the log file
    fclose(log_file);
}

// Function to handle signals and perform cleanup
void handle_signal(int signum) {
    // Stop the periodic measurement
    while (1) {}

    // Close the I2C handle
    i2c_device_put(i2c_dev);

    // Close the log file
    fclose(log_file);

    // Invoke cleanup API call
    close_and_cleanup();
}

// Function to close resources and cleanup
void close_and_cleanup() {
    // Close the log file
    fclose(log_file);

    // Release the GPIO descriptor
    gpio_free(co2_pin);

    // Close the I2C bus
    i2c_close(i2c_fd);

    // Clean up libgpiod
    gpiod_shutdown();
}

// Error handling function
void error_handler(const char* msg) {
    fprintf(stderr, "%s\n", msg);
}

// Determine the ventilation state based on CO₂ ppm
int determine_ventilation_state(uint8_t co2_ppm) {
    if (co2_ppm < 800) {
        return VENTILATION_OFF;
    } else if (co2_ppm < 1200) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

// Ventilation state definitions
enum VentilationState {
    VENTILATION_OFF,
    VENTILATION_LOW,
    VENTILATION_HIGH
};

// Return code definitions
#define EXIT_SUCCESS 0
#define EXIT_FAILURE 1

