#define SDP32_REG_PRESSURE 0x00
#define SDP32_REG_TEMPERATURE 0x01
#define SDP32_REG_SCALE_FACTOR 0x02

#define SDP32_REG_SIZE 9
#define SDP32_CRC8_POLYNOMIAL 0x8D

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main(int argc, char **argv) {
    struct gpiod_device *i2c_dev;
    struct gpiod_cdev *i2c_cdev;
    int fd;
    int ret;
    uint8_t buffer[SDP32_REG_SIZE];
    uint8_t crc8(uint8_t data, uint8_t polynomial) {
        uint8_t crc = 0;
        for (int i = 0; i < 8; i++) {
            if ((crc ^ data) & 1) {
                crc = (crc >> 1) ^ polynomial;
            } else {
                crc >>= 1;
            }
            data >>= 1;
        }
        return crc;
    }

    // Initialize GPIO I2C
    if ((i2c_dev = gpiod_get_device_by_name("i2c-1")) == NULL) {
        fprintf(stderr, "Failed to find I2C bus.\n");
        return EXIT_FAILURE;
    }

    if ((i2c_cdev = gpiod_cdev_from_device(i2c_dev)) == NULL) {
        fprintf(stderr, "Failed to get I2C character device.\n");
        gpiod_device_put(i2c_dev);
        return EXIT_FAILURE;
    }

    fd = open(i2c_cdev->filename, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C device.\n");
        close(i2c_cdev->fd);
        gpiod_cdev_put(i2c_cdev);
        return EXIT_FAILURE;
    }

    // Set I2C address and mode
    ret = ioctl(fd, GPIOD_I2C_SLAVE, SDP32_ADDR);
    if (ret != 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        close(fd);
        gpiod_cdev_put(i2c_cdev);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read pressure data
        ret = read(fd, buffer, SDP32_REG_SIZE);
        if (ret != SDP32_REG_SIZE) {
            if (ret == 0) {
                fprintf(stderr, "Sensor not detected.\n");
                close(fd);
                gpiod_cdev_put(i2c_cdev);
                return EXIT_FAILURE;
            } else {
                fprintf(stderr, "I2C error: %d bytes read.\n", ret);
                close(fd);
                gpiod_cdev_put(i2c_cdev);
                return EXIT_FAILURE;
            }
        }

        // Verify CRC8 for pressure, temperature, and scale factor
        uint8_t pressure_crc8 = crc8(buffer[0], SDP32_CRC8_POLYNOMIAL);
        uint8_t temperature_crc8 = crc8(buffer[1], SDP32_CRC8_POLYNOMIAL);
        uint8_t scale_factor_crc8 = crc8(buffer[8], SDP32_CRC8_POLYNOMIAL);

        if (pressure_crc8 != buffer[2] || temperature_crc8 != buffer[3] || scale_factor_crc8 != buffer[9]) {
            fprintf(stderr, "CRC8 error in data.\n");
            close(fd);
            gpiod_cdev_put(i2c_cdev);
            return EXIT_FAILURE;
        }

        // Print reading with timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("Pressure: %02X%02X Temperature: %02X%02X Scale Factor: %02X%02X\n",
               buffer[0], buffer[1], buffer[3], buffer[4], buffer[8], buffer[9]);

        // Sleep for 1000ms (1s) or override with command-line argument
        sleep(1000);
    }

    // Clean up
    close(fd);
    gpiod_cdev_put(i2c_cdev);

    // Exit with code 0 on SIGINT or SIGTERM
    if (should_exit) {
        printf("Exiting on signal.\n");
        exit(0);
    }

    return EXIT_SUCCESS;
}

