#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/wait.h>

#define SENSIRION_SDP810_ADDR 0x5A
#define SENSIRION_SDP810_REG_PRESSURE 0x00
#define SENSIRION_SDP810_REG_TEMPERATURE 0x01
#define SENSIRION_SDP810_REG_SIZE 9

// CRC-8 polynomial and initial value
uint8_t crc8_poly = 0x07;
uint8_t crc8_init = 0xFF;

// Sensor data structure
typedef struct {
    uint8_t pressure;
    uint8_t temperature;
    uint8_t pressure_scale;
    uint8_t temperature_scale;
} SensorData;

// Function prototypes
void i2c_init();
void i2c_write(uint8_t address, uint8_t reg, uint8_t data);
uint8_t i2c_read(uint8_t address, uint8_t reg);
void cleanup();
void handle_signal(int signum);

int main() {
    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO for I2C
    gpiod_set_data_direction(GPIO_NUM_2, GPIOD_DIR_OUT);
    gpiod_set_data_direction(GPIO_NUM_3, GPIOD_DIR_OUT);

    // Initialize I2C
    i2c_init();

    // Main loop
    while (1) {
        // Wait for 1 second
        sleep(1);

        // Perform I2C read
        SensorData data;
        uint8_t crc_ok = i2c_read(SENSIRION_SDP810_ADDR, SENSIRION_SDP810_REG_PRESSURE, &data.pressure);
        if (!crc_ok) {
            fprintf(stderr, "CRC error reading pressure.\n");
            continue;
        }

        crc_ok = i2c_read(SENSIRION_SDP810_ADDR, SENSIRION_SDP810_REG_TEMPERATURE, &data.temperature);
        if (!crc_ok) {
            fprintf(stderr, "CRC error reading temperature.\n");
            continue;
        }

        // Validate CRC
        uint8_t calculated_crc = crc8(data.pressure ^ 0x00, data.pressure_scale ^ 0x00, crc8_init);
        if (calculated_crc != data.pressure & 0x80) {
            fprintf(stderr, "CRC mismatch for pressure.\n");
            continue;
        }

        calculated_crc = crc8(data.temperature ^ 0x00, data.temperature_scale ^ 0x00, crc8_init);
        if (calculated_crc != data.temperature & 0x80) {
            fprintf(stderr, "CRC mismatch for temperature.\n");
            continue;
        }

        // Log data
        printf("Pressure: %hu, Temperature: %hu, Pressure Scale: %hu, Temperature Scale: %hu\n",
               data.pressure, data.temperature, data.pressure_scale, data.temperature_scale);

        // Cleanup on SIGINT or SIGTERM
        handle_signal(SIGINT);
        handle_signal(SIGTERM);
    }

    // Clean up I2C and GPIO
    cleanup();

    return 0;
}

// Function to initialize I2C
void i2c_init() {
    int fd;
    struct gpiod_cdev *i2c_dev;

    // Open I2C bus 1
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Get the I2C device control handle
    i2c_dev = gpiod_cdev_get(fd);

    // Set the I2C clock frequency (e.g., 100kHz)
    if (ioctl(i2c_dev, GPIOD_I2C_SET_SPEED, 100000) < 0) {
        perror("Failed to set I2C speed");
        exit(EXIT_FAILURE);
    }
}

// Function to write to I2C
void i2c_write(uint8_t address, uint8_t reg, uint8_t data) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = 1,
        .buf = (void *)reg,
    };

    if (ioctl(i2c_dev, GPIOD_I2C_Transaction, &msg) < 0) {
        perror("Failed to write to I2C");
        exit(EXIT_FAILURE);
    }
}

// Function to read from I2C
uint8_t i2c_read(uint8_t address, uint8_t reg) {
    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = 1,
        .buf = (void *)&reg,
    };

    if (ioctl(i2c_dev, GPIOD_I2C_Transaction, &msg) < 0) {
        perror("Failed to read from I2C");
        return 0; // Return 0 to indicate error
    }

    return msg.len;
}

// Function to cleanup I2C and GPIO resources
void cleanup() {
    // Close I2C device handle
    close(fd);

    // Release the I2C device control handle
    gpiod_cdev_put(i2c_dev);

    // Cleanup GPIO
    gpiod_set_data_direction(GPIO_NUM_2, GPIOD_DIR_IN);
    gpiod_set_data_direction(GPIO_NUM_3, GPIOD_DIR_IN);
}

// Signal handler function
void handle_signal(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

