#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS_NUM 1
#define SDA_GPIO 2
#define SCL_GPIO 3

#define HDC1000_ADDR 0x40
#define TEMP_REG 0x88
#define HUMIDITY_REG 0x89

#define DELAY_MS 20
#define UPDATE_INTERVAL 5000

void handle_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int main() {
    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    int_handler.sa_handler = close_i2c_fd; // Close I2C file descriptor on SIGINT
    sigaction(SIGTERM, &int_handler, NULL);

    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = close_i2c_fd; // Close I2C file descriptor on SIGTERM
    sigaction(SIGTERM, &term_handler, NULL);

    // Initialize I2C
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        handle_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Check if device is present
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) == -1) {
        handle_error("Failed to select device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for conversion to complete
        usleep(DELAY_MS * 1000);

        // Read temperature and humidity
        uint16_t temp;
        uint16_t humidity;
        if (ioctl(i2c_fd, I2C_READ, (char *) &TEMP_REG) == -1) {
            handle_error("Failed to read temperature register");
            continue;
        }
        if (ioctl(i2c_fd, I2C_READ, (char *) &HUMIDITY_REG) == -1) {
            handle_error("Failed to read humidity register");
            continue;
        }

        temp = (temp >> 8) * 0.0625 + (temp & 0xFF) * 0.00390625;
        humidity = (humidity >> 8) * 0.0625 + (humidity & 0xFF) * 0.00390625;

        // Print values
        fprintf(stderr, "Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        // Sleep for 5 seconds
        usleep(UPDATE_INTERVAL * 1000);
    }

    // Close I2C file descriptor on exit
    close(i2c_fd);

    return EXIT_SUCCESS;
}

void close_i2c_fd() {
    close(i2c_fd);
}

