#include <errno.h>
#include <stdint.h>

#define SI7051_I2C_ADDR 0x4C
#define SI7051_REG_TEMP 0x00

// Function prototypes
void setup_si7051();
void read_temperature(uint8_t* temperature);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIO for I2C
    int gpio_sda = gpiod_get_index_by_name("GPIO2");
    int gpio_scl = gpiod_get_index_by_name("GPIO3");
    if (gpio_sda == -1 || gpio_scl == -1) {
        perror("Failed to get GPIO indices");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    int i2c_dev = open("/dev/i2c-1", O_RDWR);
    if (i2c_dev == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Setup GPIO pins for I2C
    if (gpiod_direction_output(gpio_sda, 1) != 0 || gpiod_direction_output(gpio_scl, 0) != 0) {
        perror("Failed to configure GPIO pins");
        close(i2c_dev);
        exit(EXIT_FAILURE);
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read temperature every 5 seconds
        struct timespec timeout = { .tv_sec = 5, .tv_nsec = 0 };
        if (nanosleep(&timeout, NULL) == -1) {
            perror("nanosleep error");
            break; // Exit loop on error
        }

        uint8_t temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.1f°C\n", (float)temperature / 16.0);
        } else {
            // Handle I2C communication error
            perror("Error reading temperature");
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to setup the Si7051 sensor
void setup_si7051() {
    uint8_t command[2] = { SI7051_REG_TEMP, 0 };
    if (i2c_smbus_write_i2c_block_data(i2c_dev, SI7051_I2C_ADDR, command, 2) != 2) {
        perror("Failed to write command to Si7051");
        exit(EXIT_FAILURE);
    }
}

// Function to read temperature from Si7051
int read_temperature(uint8_t* temperature) {
    uint8_t response[2];
    if (i2c_smbus_read_i2c_block_data(i2c_dev, SI7051_I2C_ADDR, SI7051_REG_TEMP, response, 2) != 2) {
        perror("Failed to read temperature from Si7051");
        return -1;
    }

    *temperature = response[1];
    return 0;
}

// Signal handler for graceful shutdown
void handle_signal(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Release GPIO pins
    gpiod_set_output_value(gpio_sda, 0);
    gpiod_set_output_value(gpio_scl, 0);

    // Close I2C device
    close(i2c_dev);
}

