#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define MLX90833_I2C_ADDR 0x40 // Melexis MLX90833 I2C address
#define MLX90833_REG_PRESSURE 0x00 // Pressure register address

// Function prototypes
void setup_gpiod();
void setup_i2c();
void read_pressure(uint8_t addr, uint8_t reg);
void handle_signal(int signum);

// Global variables
struct gpiod_dev *i2c_dev;
int i2c_fd;
uint8_t pressure;

// Main function
int main() {
    // Initialize GPIO and I2C
    setup_gpiod();
    setup_i2c();

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read pressure every 500ms
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 500 / 1000;
        ts.tv_nsec += (500 % 1000) * 1000000;

        // Wait for the specified time
        nanosleep(&ts, NULL);

        // Read pressure from the sensor
        read_pressure(MLX90833_I2C_ADDR, MLX90833_REG_PRESSURE);

        // Print pressure and timestamp
        printf("Pressure: %hu (ms: %ld)\n", pressure, (long)clock_gettime(CLOCK_REALTIME, &ts).tv_sec * 1000 + (long)ts.tv_nsec / 1000000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIO
void setup_gpiod() {
    struct gpiod_dev *dev;
    int ret;

    // Find the I2C device
    dev = gpiod_get_device_by_name("i2c-1");
    if (!dev) {
        fprintf(stderr, "Failed to find I2C device.\n");
        exit(EXIT_FAILURE);
    }

    // Open the I2C device
    ret = gpiod_open(dev, GPIOD_OPEN_FLAG_RDWR);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", gpiod_error_string(dev));
        exit(EXIT_FAILURE);
    }

    i2c_dev = dev;
}

// Function to setup I2C
void setup_i2c() {
    int fd;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    i2c_fd = fd;
}

// Function to read pressure from the sensor
void read_pressure(uint8_t addr, uint8_t reg) {
    uint8_t buf[2];
    int ret;

    // Write register address to the sensor
    ret = i2c_smbus_write_byte_data(i2c_fd, addr, reg);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to sensor: %s\n", strerror(errno));
        return;
    }

    // Read pressure data
    ret = i2c_smbus_read_byte_data(i2c_fd, addr);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
        return;
    }

    pressure = buf[0];
}

// Signal handler to clean up resources
void handle_signal(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Close I2C device
    if (i2c_fd > 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    // Close GPIO device
    if (i2c_dev) {
        gpiod_close(i2c_dev);
        i2c_dev = NULL;
    }
}

