#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <stdint.h>

#define I2C_ADDR 0x29 // Assuming the sensor is at address 0x29
#define TDK_ICP10101_REG_TEMP 0x00
#define TDK_ICP10101_REG_PRESSURE 0x01

// Function prototypes
void handleSIGINT(int signum);
void handleSIGTERM(int signum);
void i2cCleanup(void);

int main() {
    // Initialize GPIO and I2C
    int rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_get_name(rc));
        return EXIT_FAILURE;
    }

    struct gpiod_i2c *i2c_dev;
    rc = gpiod_i2c_get_by_name("i2c-1", &i2c_dev);
    if (rc != 0) {
        fprintf(stderr, "Error getting I2C device: %s\n", gpiod_get_name(rc));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Open I2C device
    rc = i2c_dev->open();
    if (rc != 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", i2c_dev->get_name());
        i2cCleanup();
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handleSIGINT);
    signal(SIGTERM, handleSIGTERM);

    // Main loop
    while (1) {
        // ISO 8601 timestamp
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Trigger measurement
        uint8_t command_reg = TDK_ICP10101_REG_TEMP;
        rc = i2c_dev->write(I2C_ADDR, &command_reg, 1);
        if (rc < 0) {
            fprintf(stderr, "Error writing to sensor: %s\n", i2c_dev->get_name());
            continue;
        }

        // Wait 7ms
        usleep(7000);

        // Read temperature and pressure
        uint8_t data[2];
        rc = i2c_dev->read(I2C_ADDR, &data, 2);
        if (rc < 0) {
            fprintf(stderr, "Error reading from sensor: %s\n", i2c_dev->get_name());
            continue;
        }

        // Check for sensor absent condition
        if (data[0] == 0xFF && data[1] == 0xFF) {
            fprintf(stderr, "Sensor absent or failed to respond correctly.\n");
            continue;
        }

        // Convert data to temperature and pressure
        float temperature = (data[0] << 8) | data[1];
        float pressure = (data[0] << 8) | data[1];

        // Print results
        fprintf(stdout, "%s - Temperature: %.2f °C, Pressure: %.6f Pa\n", timestamp_str, temperature / 100.0, pressure / 100.0);

        // Cleanup and close I2C device on exit
        i2cCleanup();
    }

    // Cleanup on SIGINT or SIGTERM
    handleSIGINT(SIGINT);
    handleSIGTERM(SIGTERM);

    return EXIT_SUCCESS;
}

// Signal handlers
void handleSIGINT(int signum) {
    fprintf(stderr, "SIGINT received, terminating...\n");
    i2cCleanup();
    gpiod_exit();
    exit(EXIT_FAILURE);
}

void handleSIGTERM(int signum) {
    fprintf(stderr, "SIGTERM received, terminating...\n");
    i2cCleanup();
    gpiod_exit();
    exit(EXIT_FAILURE);
}

// I2C cleanup function
void i2cCleanup(void) {
    struct gpiod_i2c *i2c_dev = NULL;
    int rc = gpiod_i2c_get_by_name("i2c-1", &i2c_dev);
    if (rc != 0) {
        fprintf(stderr, "Error getting I2C device for cleanup: %s\n", gpiod_get_name(rc));
        return;
    }

    rc = i2c_dev->close();
    if (rc != 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", i2c_dev->get_name());
    }

    gpiod_i2c_put(i2c_dev);
}

