void cleanup();
void sigint_handler(int signum);

int main() {
    // Initialize GPIO
    if (gpiod_open() < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", gpiod_errstr(gpiod_errno()));
        return EXIT_FAILURE;
    }
    gpiod_unexport_all();

    // Open I2C device
    int i2c_fd = -1;
    char dev_name[32];
    snprintf(dev_name, sizeof(dev_name), "/dev/i2c-%d", 1);  // Assuming I2C bus 1
    i2c_fd = open(dev_name, O_RDWR);
    if (i2c_fd == -1) {
        handle_error("open", "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Check if device is ready
    struct gpiod_device *i2c_dev = gpiod_get_device_by_name(dev_name);
    if (!i2c_dev) {
        fprintf(stderr, "Failed to find I2C device: %s\n", gpiod_errstr(gpiod_errno()));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set I2C device parameters
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        handle_error("ioctl(I2C_SLAVE)", "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read pressure
        uint16_t pressure;
        if (ioctl(i2c_fd, I2C_READ, (char *) &SENSOR_REG_PRESSURE, sizeof(uint16_t)) < 0) {
            handle_error("ioctl(I2C_READ)", "Failed to read pressure: %s\n", strerror(errno));
            continue;
        }
        pressure = (uint16_t) (pressure << 8);
        pressure |= (uint16_t) i2c_smbus_read_word_data(i2c_fd, SENSOR_REG_PRESSURE);

        // Print timestamp and pressure
        struct tm tm;
        time_t now = time(NULL);
        localtime_r(&now, &tm);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        printf("Pressure: %hu %s\n", pressure, timestamp);

        // Handle SIGINT/SIGTERM
        if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
            fprintf(stderr, "Failed to install SIGINT/SIGTERM handler: %s\n", strerror(errno));
        } else {
            sa.sa_handler = sigint_handler;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Error handling function
void handle_error(const char *operation, const char *message) {
    fprintf(stderr, "Error during %s: %s\n", operation, message);
}

// Cleanup function
void cleanup() {
    // Close I2C file descriptor
    close(i2c_fd);

    // Unexport GPIO devices
    gpiod_export_all();
}

// SIGINT/SIGTERM handler
void sigint_handler(int signum) {
    // Clean exit by closing I2C file descriptor
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

