#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>
#include <gpiod.h>

#define SENSIRION_I2C_ADDR 0x5A
#define SENSIRION_REG_READ 0x00
#define SENSIRION_REG_PRESSURE_HIGH 0x01
#define SENSIRION_REG_PRESSURE_LOW 0x02
#define SENSIRION_REG_TEMPERATURE 0x03
#define SENSIRION_CRC_POLYNOMIAL 0x07

// Sensor data structure
typedef struct {
    uint16_t pressure_high;
    uint16_t pressure_low;
    uint16_t temperature;
    uint8_t crc;
} SensorData;

// Function prototypes
void i2c_init();
int i2c_write(uint8_t address, uint8_t reg, uint8_t data);
int i2c_read(uint8_t address, uint8_t reg, uint8_t* data, size_t len);
void crc8(uint8_t* data, size_t len, uint8_t init_val, uint8_t poly);
void print_csv_line(const char* timestamp, uint16_t pressure, uint16_t temperature);
void cleanup();
void handle_signal(int signum);

int main() {
    // Initialize GPIO for I2C
    i2c_init();

    // File for logging
    const char* log_file = "pressure_log.txt";
    FILE* log_file_ptr = fopen(log_file, "a+");
    if (log_file_ptr == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Trigger measurement
        uint8_t command = SENSIRION_REG_READ;
        int result = i2c_write(SENSIRION_I2C_ADDR, SENSIRION_REG_READ, command);
        if (result < 0) {
            fprintf(stderr, "Error writing to sensor: %s\n", strerror(errno));
            continue;
        }

        // Wait for 45 ms
        usleep(45000);

        // Read data
        SensorData data;
        int read_result = i2c_read(SENSIRION_I2C_ADDR, SENSIRION_REG_PRESSURE_HIGH, &data.pressure_high, sizeof(data.pressure_high));
        if (read_result < 0) {
            fprintf(stderr, "Error reading pressure high: %s\n", strerror(errno));
            continue;
        }

        read_result = i2c_read(SENSIRION_I2C_ADDR, SENSIRION_REG_PRESSURE_LOW, &data.pressure_low, sizeof(data.pressure_low));
        if (read_result < 0) {
            fprintf(stderr, "Error reading pressure low: %s\n", strerror(errno));
            continue;
        }

        read_result = i2c_read(SENSIRION_I2C_ADDR, SENSIRION_REG_TEMPERATURE, &data.temperature, sizeof(data.temperature));
        if (read_result < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            continue;
        }

        // Calculate CRC
        crc8(data.data, sizeof(data.data), SENSIRION_CRC_INIT_VAL, SENSIRION_CRC_POLYNOMIAL);

        // Validate CRC
        if (data.crc != (uint8_t)(crc8(data.data, sizeof(data.data), SENSIRION_CRC_INIT_VAL, SENSIRION_CRC_POLYNOMIAL) & 0xFF)) {
            fprintf(stderr, "CRC error in data\n");
            continue;
        }

        // Log the data
        time_t now = time(NULL);
        struct tm tm_now;
        localtime_r(&now, &tm_now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_now);

        print_csv_line(timestamp, data.pressure_high, data.pressure_low);
        print_csv_line(timestamp, data.temperature, data.crc);

        // Flush and close log file
        fflush(log_file_ptr);
        fclose(log_file_ptr);
    }

    // Clean up
    cleanup();

    return 0;
}

// I2C initialization function
void i2c_init() {
    // Initialize GPIO for I2C
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(2), GPIOD_DIR_OUT_INIT_LOW);
    gpiod_set_data_direction(GPIO_NUM_TO_DEV(3), GPIOD_DIR_OUT_INIT_LOW);

    // Initialize I2C
    int i2c_dev = gpiod_get_device_by_number(GPIO_NUM_TO_DEV(2));
    if (i2c_dev < 0) {
        perror("Failed to get I2C device");
        exit(EXIT_FAILURE);
    }

    int i2c_master = i2c_new_device(i2c_dev, 100000);
    if (i2c_master < 0) {
        perror("Failed to create I2C master");
        exit(EXIT_FAILURE);
    }

    gpiod_set_function(GPIO_NUM_TO_DEV(2), GPIOD_FUNC_I2C);
    gpiod_set_function(GPIO_NUM_TO_DEV(3), GPIOD_FUNC_I2C);
}

// I2C write function
int i2c_write(uint8_t address, uint8_t reg, uint8_t data) {
    int result = i2c_master_write(i2c_master, address, reg, data);
    if (result < 0) {
        perror("Error writing to I2C");
        return result;
    }
    return 0;
}

// I2C read function
int i2c_read(uint8_t address, uint8_t reg, uint8_t* data, size_t len) {
    int result = i2c_master_read(i2c_master, address, reg, data, len);
    if (result < 0) {
        perror("Error reading from I2C");
        return result;
    }
    return result;
}

// CRC8 calculation function
void crc8(uint8_t* data, size_t len, uint8_t init_val, uint8_t poly) {
    uint8_t crc = init_val;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) == 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
    }
}

// Print CSV line function
void print_csv_line(const char* timestamp, uint16_t pressure, uint16_t temperature) {
    char line[100];
    sprintf(line, "%s,%d,%d", timestamp, pressure, temperature);
    fprintf(log_file_ptr, "%s\n", line);
}

// Cleanup function
void cleanup() {
    // Close log file
    fclose(log_file_ptr);

    // Release I2C resources
    i2c_master_stop(i2c_master);
    i2c_del_device(i2c_master);
    gpiod_set_function(GPIO_NUM_TO_DEV(2), GPIOD_FUNC_NONE);
    gpiod_set_function(GPIO_NUM_TO_DEV(3), GPIOD_FUNC_NONE);
}

// Signal handler function
void handle_signal(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

