#define I2C_ADDR 0x27  // Assuming the HIH6130 is at address 0x27

#define HIH6130_REG_TEMPERATURE  0x00
#define HIH6130_REG_HUMIDITY      0x01

#define FILE_NAME "environmental_data.log"
#define MAX_FILE_SIZE (1024 * 1024)

struct hih6130_data {
    uint16_t temperature;
    uint16_t humidity;
};

int main() {
    // Initialize libgpiod I2C
    int i2c_dev;
    gpiod_i2c_bus *i2c_bus;
    char device_name[GPIOD_NAME_MAX] = "i2c-1";

    if (gpiod_i2c_open(&i2c_bus, device_name) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Open the HIH6130 I2C device
    int rc = gpiod_i2c_transfer(i2c_bus, I2C_ADDR, 0x00, 1, NULL, 0, NULL, 0);
    if (rc != 1) {
        fprintf(stderr, "Failed to communicate with HIH6130: %d\n", rc);
        gpiod_i2c_close(i2c_bus);
        return EXIT_FAILURE;
    }

    // Function to read HIH6130 data
    int read_hih6130(struct hih6130_data *data) {
        int rc = gpiod_i2c_transfer(i2c_bus, I2C_ADDR, HIH6130_REG_TEMPERATURE, 1, data->temperature, 0, NULL, 0);
        if (rc != 1) {
            fprintf(stderr, "Failed to read temperature: %d\n", rc);
            return -1;
        }

        rc = gpiod_i2c_transfer(i2c_bus, I2C_ADDR, HIH6130_REG_HUMIDITY, 1, data->humidity, 0, NULL, 0);
        if (rc != 1) {
            fprintf(stderr, "Failed to read humidity: %d\n", rc);
            return -1;
        }

        return 0;
    }

    // Main loop
    while (1) {
        // Wait for 5 seconds
        struct timespec ts = { .tv_sec = 5, .tv_nsec = 0 };
        if (nanosleep(&ts, NULL) < 0) {
            perror("nanosleep error");
            break; // Exit on error
        }

        // Read sensor data
        struct hih6130_data data;
        if (read_hih6130(&data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break; // Exit on error
        }

        // Format timestamp and log data
        time_t timestamp = time(NULL);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &timestamp);

        FILE *file = fopen(FILE_NAME, "a");
        if (!file) {
            perror("Failed to open file for writing");
            break; // Exit on error
        }

        fprintf(file, "%s, Temperature: %hu°C, Humidity: %hu%%\n", timestamp_str, data.temperature, data.humidity);
        fclose(file);

        // Check file size and truncate if necessary
        struct stat st;
        if (fstat(fileno(file), &st) < 0) {
            perror("fstat error");
            break; // Exit on error
        }

        if (st.st_size > MAX_FILE_SIZE) {
            if (fclose(file) != 0) {
                perror("Failed to close file for truncation");
                break; // Exit on error
            }
            if (unlink(FILE_NAME) < 0) {
                perror("Failed to remove file for truncation");
                break; // Exit on error
            }
            file = fopen(FILE_NAME, "w+"); // Reopen for writing
        }

        // Close I2C device and bus
        gpiod_i2c_close(i2c_bus);
    }

    // Release resources on exit
    gpiod_i2c_bus_free(i2c_bus);

    return EXIT_SUCCESS;
}

