            break; // Exit on error
        }

        // Read sensor data
        struct hih6130_data data;
        if (read_hih6130(&data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break; // Exit on error
        }

        // Format timestamp and log data
        time_t timestamp = time(NULL);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", &timestamp);

        FILE *file = fopen(FILE_NAME, "a");
        if (!file) {
            perror("Failed to open file for writing");
            break; // Exit on error
        }

        fprintf(file, "%s, Temperature: %hu°C, Humidity: %hu%%\n", timestamp_str, data.temperature, data.humidity);
        fclose(file);

        // Check file size and truncate if necessary
        struct stat st;
        if (fstat(fileno(file), &st) < 0) {
            perror("fstat error");
            break; // Exit on error
        }

        if (st.st_size > MAX_FILE_SIZE) {
            if (fclose(file) != 0) {
                perror("Failed to close file for truncation");
                break; // Exit on error
            }
            if (unlink(FILE_NAME) < 0) {
                perror("Failed to remove file for truncation");
                break; // Exit on error
            }
            file = fopen(FILE_NAME, "w+"); // Reopen for writing
        }

        // Close I2C device and bus
        gpiod_i2c_close(i2c_bus);
    }

    // Release resources on exit
    gpiod_i2c_bus_free(i2c_bus);

    return EXIT_SUCCESS;
}
