#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>

#define SENSOR_GPIO 4 // BCM 4
#define SENT_TICKS 3_000 // 3 microseconds per tick
#define SYNCHRONIZATION_TICKS 56
#define MIN_PULSE_WIDTH 12 * SENT_TICKS
#define MAX_PULSE_WIDTH 271 * SENT_TICKS
#define PRESSURE_LOG_FILE "pressure_log.txt"

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO
    int gpio_dev_fd = gpiod_open(SENSOR_GPIO, GPIOD_OPEN_RWD);
    if (gpio_dev_fd == -1) {
        fprintf(stderr, "Error opening GPIO pin %d: %s\n", SENSOR_GPIO, strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    if (gpiod_direction_input(gpio_dev_fd) == -1) {
        fprintf(stderr, "Error setting GPIO pin %d as input: %s\n", SENSOR_GPIO, strerror(errno));
        gpiod_close(gpio_dev_fd);
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!should_exit) {
        uint8_t status_nibble;
        uint8_t data_nibble1;
        uint8_t data_nibble2;
        uint8_t checksum_nibble;

        // Read synchronization pulse
        uint32_t ticks = 0;
        while (ticks < SYNCHRONIZATION_TICKS) {
            if (gpiod_get_value(gpio_dev_fd) == 0) {
                break;
            }
            ticks++;
        }

        // Check if synchronization pulse is valid
        if (ticks != SYNCHRONIZATION_TICKS) {
            fprintf(stderr, "Invalid synchronization pulse length, aborting.\n");
            break;
        }

        // Read data pulses
        uint32_t ticks_status = 0;
        uint32_t ticks_data1 = 0;
        uint32_t ticks_data2 = 0;
        uint32_t ticks_checksum = 0;

        for (int i = 0; i < 4; ++i) {
            if (i == 0) { // Status nibble
                ticks_status = 0;
            } else {
                ticks_data1 = 0;
                ticks_data2 = 0;
                ticks_checksum = 0;
            }

            while (ticks_status < 8 || (i != 0 && (ticks_data1 < 8 || ticks_data2 < 8 || ticks_checksum < 8))) {
                if (gpiod_get_value(gpio_dev_fd) == 0) {
                    ticks_status++;
                    if (i == 0) {
                        status_nibble = ticks_status;
                    } else {
                        ticks_data1++;
                        if (ticks_data1 == 8) {
                            ticks_data1 = 0;
                            ticks_data2++;
                        }
                    }
                    if (i == 3) {
                        ticks_checksum++;
                    }
                } else {
                    break;
                }
            }

            // Check if status nibble is valid
            if (ticks_status != 8 || status_nibble < 0x0 || status_nibble > 0xF) {
                fprintf(stderr, "Invalid status nibble, aborting.\n");
                break;
            }

            // Check if data nibbles are within range
            if (i == 1) {
                if (ticks_data1 < MIN_PULSE_WIDTH / SENT_TICKS || ticks_data1 > MAX_PULSE_WIDTH / SENT_TICKS) {
                    fprintf(stderr, "Invalid data nibble 1 pulse width, aborting.\n");
                    break;
                }
            } else if (i == 2) {
                if (ticks_data2 < MIN_PULSE_WIDTH / SENT_TICKS || ticks_data2 > MAX_PULSE_WIDTH / SENT_TICKS) {
                    fprintf(stderr, "Invalid data nibble 2 pulse width, aborting.\n");
                    break;
                }
            }

            // Check checksum
            if (i == 3) {
                uint8_t calculated_checksum = (status_nibble + data_nibble1 + data_nibble2);
                if (checksum_nibble != calculated_checksum) {
                    fprintf(stderr, "Checksum error, aborting.\n");
                    break;
                }
            }
        }

        // Convert ticks to microseconds
        uint32_t microseconds_status = ticks_status * SENT_TICKS;
        uint32_t microseconds_data1 = ticks_data1 * SENT_TICKS;
        uint32_t microseconds_data2 = ticks_data2 * SENT_TICKS;
        uint32_t microseconds_checksum = ticks_checksum * SENT_TICKS;

        // Calculate pressure
        // Assuming a linear relationship between pulse width and pressure
        // Convert microseconds to pressure in Pascals (Pa)
        float pressure = (microseconds_data1 + microseconds_data2) * 0.000277; // Example conversion factor

        // Format and write to log file
        char timestamp[50];
        time_t now = time(NULL);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        FILE *log_file = fopen(PRESSURE_LOG_FILE, "a+");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", PRESSURE_LOG_FILE);
            fclose(log_file);
            break;
        }

        fprintf(log_file, "%s, Pressure: %.3f Pa\n", timestamp, pressure);
        fclose(log_file);

        // Clean up GPIO
        gpiod_close(gpio_dev_fd);
    }

    // Clean up and exit
    gpiod_release(gpio_dev_fd);
    return EXIT_SUCCESS;
}

