        return -1;
    }
    return 0;
}

// Function to read from I2C device
int i2cRead(uint8_t slave_addr, uint8_t command, uint8_t* data, size_t len) {
    uint8_t buf[3] = { command, 0, 0 }; // Command followed by a repeated start and a stop bit
    write(i2c_fd, buf, 3);

    // Read response
    if (read(i2c_fd, data, len) != len) {
        perror("i2c read failed");
        return -1;
    }

    return len;
}

// Function to validate CRC using CRC-8 algorithm
int validateCrc(uint8_t* data, uint8_t len, uint8_t crc) {
    uint8_t crc_value = crc;

    for (uint8_t i = 0; i < len; i++) {
        crc_value = (crc_value << 1) ^ (data[i] & 0x80 ? 0x07 : 0x00);
        data[i] <<= 1;
        if (data[i]) crc_value ^= 0x07;
    }

    return crc_value == data[len - 1];
}

