#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define TMP117_ADDR 0x48  // Address of TMP117 sensor

// Structure for TMP117 register access
typedef struct {
    uint8_t register_address;
    uint8_t register_data;
} TMP117_REG_ACCESS;

// Function prototypes
void init_gpiod();
void init_i2c();
void read_temp(uint8_t addr, int *temperature);
void write_to_file(const char *filename, uint16_t *buffer, size_t size);
void handle_signal(int signum);

// Circular buffer definition
#define BUFFER_SIZE 100
uint16_t temperature_buffer[BUFFER_SIZE];

int buffer_index = 0;

// Signal handlers
void sigint_handler(int signum) {
    handle_signal(SIGINT, signum);
}
void sigterm_handler(int signum) {
    handle_signal(SIGTERM, signum);
}

// Main function
int main() {
    // Initialize GPIO and I2C
    init_gpiod();
    init_i2c();

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    uint16_t temperature;
    while (1) {
        // Read temperature
        if (read_temp(TMP117_ADDR, &temperature) == 0) {
            // Successfully read temperature
            temperature_buffer[buffer_index++] = temperature;
            if (buffer_index == BUFFER_SIZE) {
                buffer_index = 0; // Wrap around the buffer
            }
        } else {
            // Error reading temperature
            fprintf(stderr, "Error reading temperature from TMP117\n");
            continue;
        }

        // Write buffer to file
        write_to_file("temperature_log.dat", temperature_buffer, BUFFER_SIZE);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Flush buffer and release resources on exit
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

// Function to initialize GPIO
void init_gpiod() {
    int fd;
    if ((fd = open("/dev/gpiom", O_RDWR)) < 0) {
        perror("open /dev/gpiom");
        exit(EXIT_FAILURE);
    }

    // No specific GPIO setup needed for this example
    close(fd);
}

// Function to initialize I2C
void init_i2c() {
    int fd;
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    // Check if I2C device is accessible
    struct i2c_msg msg = {
        .addr = TMP117_ADDR,
        .flags = 0
    };

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to access TMP117\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

// Function to read temperature from TMP117
void read_temp(uint8_t addr, int *temperature) {
    TMP117_REG_ACCESS reg_access = {
        .register_address = 0x05, // Read temperature register
        .register_data = 0
    };

    if (i2c_smbus_read_word_data(addr, &reg_access) < 0) {
        fprintf(stderr, "Error reading from TMP117\n");
        return;
    }

    *temperature = (int)((reg_access.register_data & 0xFF) << 8);
}

// Function to write buffer to file
void write_to_file(const char *filename, uint16_t *buffer, size_t size) {
    int fd = fopen(filename, "wb");
    if (fd == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    for (size_t i = 0; i < size; i++) {
        fwrite(&buffer[i], sizeof(uint16_t), 1, fd);
    }

    fclose(fd);
}

// Function to handle signals
void handle_signal(int signum) {
    // Flush the buffer
    for (int i = 0; i < BUFFER_SIZE; i++) {
        write_to_file("temperature_log.dat", &temperature_buffer[i], 1);
    }

    // Release resources
    init_i2c(); // Close I2C device file
    init_gpiod(); // Close GPIO device file

    // Ensure file is properly closed before exit
    fclose(STDOUT_FILENO); // This is a conceptual step, as stdout is not directly involved in file writing

    exit(EXIT_SUCCESS);
}

