    if (init_i2c()) {
        printf("Failed to initialize I2C.\n");
        return EXIT_FAILURE;
    }

    // File for logging temperature
    int file_fd = open("temperature_log.txt", O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (file_fd == -1) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    struct timeval now;
    struct tm *timeinfo;
    char timestamp[50];

    while (1) {
        // Read current time
        gettimeofday(&now, NULL);

        // Convert time to string
        timeinfo = localtime(&now.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", timeinfo);

        // Read temperature from TMP117
        double temperature = read_temp_from_i2c();

        // Handle negative temperatures correctly
        if (temperature < 0) {
            temperature = -temperature;
        }

        // Write to file
        write_to_file(timestamp, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on SIGINT (Ctrl+C)
    if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
        perror("Failed to ignore SIGINT");
        return EXIT_FAILURE;
    }

    cleanup();

    return EXIT_SUCCESS;
