    if (rc != 2) {
        printf("Error reading from TMP117: %d\n", rc);
        return -1; // Return negative value to indicate error
    }

    // Convert data to temperature
    int temperature = (data[0] << 8) | data[1];
    temperature /= 16.0; // TMP117 returns temperature in 1/16 degrees C

    return temperature;
}

