#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define HAFUHH0025PA3_ADDR 0x29 // Address of the Honeywell HAF Series flow sensor
#define HAFUHH0025PA3_REG_FLOW 0x00 // Register for flow value
#define HAFUHH0025PA3_REG_TEMP 0x01 // Register for temperature value

// Function prototypes
void handle_signal(int signum);
void read_hafuhh0025pa3(uint8_t* data);
void write_to_log_file(const char* message);

// Global variables
FILE* log_file;
gpiod_channel* i2c_channel;
uint8_t last_good_read = 0;

int main() {
    // Initialize GPIO I2C
    if (gpiod_channel_open(&i2c_channel, "i2c0", GPIOD_OPEN_READONLY) < 0) {
        fprintf(stderr, "Failed to open I2C channel: %s\n", gpiod_get_name(i2c_channel));
        return EXIT_FAILURE;
    }

    // Attempt to open the log file for writing
    if ((log_file = fopen("flow_log.txt", "a+")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_channel_close(i2c_channel);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Attempt to read from the sensor
        uint8_t data[4];
        if (gpiod_i2c_read(i2c_channel, HAFUHH0025PA3_ADDR, 4, data) < 0) {
            fprintf(stderr, "Failed to read from HAFUHH0025PA3: %s\n", gpiod_get_name(i2c_channel));
            // Attempt to reinitialize I2C channel
            gpiod_channel_close(i2c_channel);
            gpiod_channel_open(&i2c_channel, "i2c0", GPIOD_OPEN_READONLY);
            continue;
        }

        // Check if it's the first two reads after power-up
        if (last_good_read == 0 || last_good_read == 1) {
            // First two reads may return stale data, discard them
            last_good_read++;
            continue;
        }

        // Extract flow and temperature values
        uint16_t flow_value = (data[0] << 8) | data[1];
        uint16_t temperature_value = (data[2] << 4) | data[3];

        // Convert values to SLPM and °C
        float flow_rate = (float)flow_value / 16384.0; // Assuming 14-bit value is directly proportional to SLPM
        float temperature_celsius = (float)temperature_value / 16.0; // Assuming 12-bit value is directly proportional to °C

        // Timestamp and write to log file
        time_t now = time(NULL);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        write_to_log_file("Flow: %f SLPM, Temp: %f °C at %s\n", flow_rate, temperature_celsius, timestamp);

        // Close resources on exit
        gpiod_channel_close(i2c_channel);
        fclose(log_file);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return EXIT_SUCCESS;
}

// Signal handler to clean up on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Log error message
    fprintf(stderr, "Received signal %d, terminating...\n", signum);

    // Close log file and I2C channel
    gpiod_channel_close(i2c_channel);
    fclose(log_file);

    // Exit the program
    exit(EXIT_FAILURE);
}

// Function to write a message to the log file
void write_to_log_file(const char* message) {
    fprintf(log_file, "%s", message);
    fflush(log_file);
}

