#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_START_SIGNAL_MS 18000
#define DHT11_RESPONSE_LOW_MS 80000
#define DHT11_RESPONSE_HIGH_MS 80000
#define DHT11_DATA_BIT_LOW_MS 50000
#define DHT11_DATA_BIT_HIGH_MS_0 26000
#define DHT11_DATA_BIT_HIGH_MS_1 70000
#define DHT11_MIN_INTERVAL_MS 2000

#define GPIO4_PIN 7

int main() {
    struct gpio_desc *gpio;
    struct gpiod_dir *dir;
    struct gpiod_value *level;
    int ret;
    FILE *file;
    char buffer[256];
    time_t now;
    char timestamp[32];
    int humidity, temperature;
    int error_count = 0;

    // Initialize GPIO
    gpio = gpiod_get_desc_by_name(GPIO4_PIN);
    if (gpio == NULL) {
        fprintf(stderr, "Error: GPIO4 not found\n");
        return EXIT_FAILURE;
    }

    // Set GPIO4 as output for start signal
    dir = gpiod_get_dir(gpio);
    ret = gpiod_set_value(dir, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO4 direction: %d\n", ret);
        gpiod_free(dir);
        return EXIT_FAILURE;
    }

    // Open file for writing
    file = fopen("dht11_readings.txt", "a+");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        gpiod_free(dir);
        return EXIT_FAILURE;
    }

    while (1) {
        // Generate start signal
        ret = gpiod_set_value(gpio, 0); // Pull GPIO4 low
        usleep(DHT11_START_SIGNAL_MS * 1000);
        ret = gpiod_set_value(gpio, 1); // Release GPIO4

        // Wait for response
        if (gpiod_get_value(gpio) != 1) {
            fprintf(file, "Error: Start signal not acknowledged (line stuck high)\n");
            error_count++;
            continue;
        }

        // Wait for response timing
        usleep(DHT11_RESPONSE_LOW_MS * 1000);
        if (gpiod_get_value(gpio) != 0) {
            fprintf(file, "Error: No response low pulse detected (line stuck high)\n");
            error_count++;
            continue;
        }

        usleep(DHT11_RESPONSE_HIGH_MS * 1000);
        if (gpiod_get_value(gpio) != 1) {
            fprintf(file, "Error: No response high pulse detected (line stuck low)\n");
            error_count++;
            continue;
        }

        // Read data bits
        for (int i = 0; i < 40; i++) {
            // Pull GPIO4 low for 50us
            ret = gpiod_set_value(gpio, 0);
            usleep(DHT11_DATA_BIT_LOW_MS * 1000);

            // Check level for data bit
            ret = gpiod_get_value(&level);
            if (level->value == 0) {
                // Data bit is 0
                if (i != 39) {
                    // Write '0' to buffer
                    strcat(buffer, "0");
                }
            } else {
                // Data bit is 1
                if (i != 39) {
                    // Write '1' to buffer
                    strcat(buffer, "1");
                }
            }

            // Pull GPIO4 high for 26-28us (0) or 70us (1)
            ret = gpiod_set_value(gpio, 1);
            usleep(DHT11_DATA_BIT_HIGH_MS_((level->value == 0) ? 0 : 1) * 1000);

            // Check level for correct high period
            if (level->value != 1) {
                fprintf(file, "Error: Incorrect data bit high period detected\n");
                error_count++;
                continue;
            }
        }

        // Verify checksum
        int checksum = 0;
        for (int i = 0; i < 40; i++) {
            checksum ^= buffer[i];
        }

        if (checksum != 0x10) {
            fprintf(file, "Error: Checksum failed\n");
            error_count++;
        } else {
            // Parse humidity and temperature
            humidity = (buffer[0] << 8) | buffer[1];
            temperature = (buffer[2] << 8) | buffer[3];

            // Format timestamp
            now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            // Write successful reading to file
            fprintf(file, "Humidity: %d%%, Temperature: %d°C, Timestamp: %s\n", humidity, temperature, timestamp);
        }

        // Minimum interval between readings
        usleep(DHT11_MIN_INTERVAL_MS * 1000);
    }

    // Clean up GPIO and close file
    gpiod_free(dir);
    fclose(file);

    // Exit with success if no errors
    if (error_count == 0) {
        return EXIT_SUCCESS;
    }

    // Print error count and exit with failure
    fprintf(stderr, "Error count: %d\n", error_count);
    return EXIT_FAILURE;
}

