// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
sht31_t sht31;

// Function to handle signals
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (log_file != NULL) {
            fprintf(log_file, "Closing log file due to signal.\n");
            fclose(log_file);
            log_file = NULL;
        }
        if (i2c_fd != -1) {
            close(i2c_fd);
            i2c_fd = -1;
        }
        gpiod_i2c_stop(gpiod_i2c_get_by_number(1));
        gpiod_i2c_free(gpiod_i2c_get_by_number(1));
        gpiod_i2c_exit();
        exit(0);
    }
}

// Function to write to I2C
int i2c_write(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    struct gpiod_i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .buf = data,
        .len = len,
    };

    ret = gpiod_i2c_transfer(gpiod_i2c_get_by_number(1), &msg, 1);
    if (ret != len) {
        fprintf(stderr, "I2C write failed: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to read from I2C
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    struct gpiod_i2c_msg msg = {
        .addr = addr,
        .flags = GPIOD_I2C_FLAG_READ,
        .buf = data,
        .len = len,
    };

    ret = gpiod_i2c_transfer(gpiod_i2c_get_by_number(1), &msg, 1);
    if (ret != len) {
        fprintf(stderr, "I2C read failed: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to calculate CRC8
int crc8(uint8_t *buf, size_t len, uint8_t init_val) {
    uint8_t crc = init_val;
    for (size_t i = 0; i < len; i++) {
        crc ^= buf[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 1) != 0) {
                crc = (crc >> 1) ^ 0x07;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize the SHT31 sensor
    sht31_init(&sht31, SHT31_ADDR, SHT31_CMD_TEMP, SHT31_CMD_HUMIDITY);

    // Set up I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return EXIT_FAILURE;
    }

    // Set up log file
    char log_path[256];
    snprintf(log_path, sizeof(log_path), "sht31d_data.log");
    log_file = fopen(log_path, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", log_path);
        fclose(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for at least 15 ms after issuing the measurement command
        usleep(15000);

        // Read temperature and humidity
        uint8_t temp[2];
        uint8_t humidity[2];
        int crc_temp, crc_humidity;

        if (i2c_read(SHT31_ADDR, SHT31_CMD_TEMP, temp, 2) != 2 ||
            i2c_read(SHT31_ADDR, SHT31_CMD_HUMIDITY, humidity, 2) != 2) {
            fprintf(log_file, "Failed to read from SHT31 at %s: I2C error.\n",
                    ISO8601_TIME_TO_STRING(time(NULL)));
            continue;
        }

        crc_temp = crc8(temp, 2, SHT31_INIT_VALUE);
        crc_humidity = crc8(humidity, 2, SHT31_INIT_VALUE);

        // Validate CRCs
        if (crc_temp != temp[1] || crc_humidity != humidity[1]) {
            fprintf(log_file, "CRC error for temperature or humidity at %s.\n",
                    ISO8601_TIME_TO_STRING(time(NULL)));
            continue;
        }

        // Format and write to log file
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.1f,%d.%d\n", timestamp, (float)temp[0] / 16384.0, (humidity[0] << 8) | humidity[1]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

// Helper function to convert time to ISO 8601 string
char *ISO8601_TIME_TO_STRING(time_t time) {
    struct tm tm;
    time_t now = time;
    char buffer[32];

    localtime_r(&now, &tm);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &tm);

    return buffer;
}
