    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_errstr(gpiod_errno()));
        return EXIT_FAILURE;
    }

    // Open the GPIO descriptor for the fan
    fan_cdev = gpiod_open(FAN_GPIO, GPIOD_OUT_INIT_HIGH);
    if (!fan_cdev) {
        fprintf(stderr, "Error opening GPIO %u: %s\n", FAN_GPIO, gpiod_errstr(gpiod_errno()));
        gpiod_unexport(fan_cdev);
        return EXIT_FAILURE;
    }

    // Initialize I2C library
    if (i2c_init() < 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", i2c_errstr(i2c_errno()));
        gpiod_unexport(fan_cdev);
        return EXIT_FAILURE;
    }

    // Attempt to read from the LM75B sensor
    while (1) {
        // Read temperature from LM75B
        int result = i2c_smbus_read_i2c_block_data(LM75B_ADDR, 0x00, 3, temperature_samples);
        if (result < 0) {
            fprintf(stderr, "Error reading from LM75B: %s\n", i2c_errstr(i2c_errno()));
            continue; // Retry on next cycle
        }

        // Compute running average
        running_average = (running_average * 59 + temperature_samples[0]) / 60;

        // Check hysteresis thresholds
        if (running_average > HYSTERESIS_ON_THRESHOLD) {
            gpiod_set_value(fan_cdev, 1); // Turn on the fan
        } else if (running_average < HYSTERESIS_OFF_THRESHOLD) {
            gpiod_set_value(fan_cdev, 0); // Turn off the fan
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on SIGINT or SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Stop the fan and clean up
    gpiod_cdev_unexport(fan_cdev);
    i2c_close();

    // Exit the program
    return EXIT_SUCCESS;
}

