#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust for your actual I2C bus path
#define I2C_SENSOR_ADDRESS 0x48 // STTS2004 default address
#define GPIO_PIN 17 // BCM 17 corresponds to physical pin 11
#define THRESHOLD_HIGH 28
#define THRESHOLD_LOW 27

volatile sig_atomic_t should_exit = 0;

void cleanup_io() {
    if (gpio == NULL) return;
    gpio_free_all();
    gpio = NULL;
    close(i2c_fd);
}

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO library
    if ((gpio = pigpio_open()) == NULL) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    // Set up GPIO 17 as output
    if (pigpio_direction(gpio, GPIO_OUTPUT_ON_HIGH) == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", GPIO_PIN, pigpio_error());
        pigpio_close(gpio);
        return EXIT_FAILURE;
    }

    // Set up hysteresis for the LED
    pigpio_write(gpio, GPIO_PIN, 0); // Low initially

    // Initialize I2C library
    if ((i2c_fd = open(I2C_DEVICE_PATH, O_RDWR)) == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        pigpio_close(gpio);
        return EXIT_FAILURE;
    }

    // Check I2C bus for devices
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SENSOR_ADDRESS) == -1) {
        fprintf(stderr, "Failed to access I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        pigpio_close(gpio);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read temperature from STTS2004
        int result = i2c_smbus_read_word_data(i2c_fd, I2C_SENSOR_ADDRESS);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            // Log errno details if I2C read fails repeatedly
            if (errno == ENXIO) {
                fprintf(stderr, "I2C device not found.\n");
            } else {
                fprintf(stderr, "I2C operation failed: %s\n", strerror(errno));
            }
            // Exit cleanly after repeated failures
            if (++i2c_fail_count > 3) {
                fprintf(stderr, "Exiting due to repeated I2C failures.\n");
                should_exit = 1;
            } else {
                // Sleep for a bit before retrying
                sleep(1);
            }
        } else {
            // Convert temperature from 12-bit value to Celsius
            int temperature_celsius = (result * 0.0625);
            printf("Temperature: %.1f°C\n", temperature_celsius);

            // Check hysteresis condition
            if (temperature_celsius > THRESHOLD_HIGH) {
                pigpio_write(gpio, GPIO_PIN, 1); // Turn LED on
            } else if (temperature_celsius < THRESHOLD_LOW) {
                pigpio_write(gpio, GPIO_PIN, 0); // Turn LED off
            }
        }
    }

    // Clean up on SIGINT or SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install signal handlers.\n");
        return EXIT_FAILURE;
    }

    // Handle signals
    while (!should_exit) {
        sleep(1);
    }

    // Release resources
    cleanup_io();

    return EXIT_SUCCESS;
}

// Global variable to track I2C failures
static int i2c_fail_count = 0;

