#define SDP800_CMD_READ_MEASUREMENT 0x00
#define SDP800_CMD_START_MEASUREMENT 0x01
#define SDP800_MEASUREMENT_LENGTH 9
#define SDP800_CRC_POLYNOMIAL 0x07 // x^8 + x^2 + x + 1
#define SDP800_INIT_CRC 0xFF

// Structure to hold measurement data
