#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust for your actual I2C bus path
#define SENSIRION_ST40_ADDR 0x5C // STS40 I2C address
#define SENSIRION_ST40_CMD_REG 0x00 // Command register
#define SENSIRION_ST40_DATA_REG 0x01 // Data register
#define SENSIRION_ST40_CRC_REG 0x02 // CRC register

#define SENSIRION_ST40_CRC_POLYNOMIAL 0x07 // CRC polynomial

// Function prototypes
void handle_error(const char *operation, const char *message);
void read_temperature(uint8_t *data);
void write_crc(uint8_t *data, uint8_t crc);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize GPIO library
    if (pigpioSetup() == -1) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C device
    int i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSIRION_ST40_ADDR) == -1) {
        fprintf(stderr, "Failed to set slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for 5 seconds between readings
        struct timespec ts = { .tv_sec = 5, .tv_nsec = 0 };
        nanosleep(&ts, NULL);

        // Read temperature
        uint8_t data[3];
        read_temperature(data);

        // Verify CRC
        uint8_t crc = write_crc(data, 0); // Initial CRC is 0

        if (data[2] != (crc ^ 0x07)) {
            fprintf(stderr, "CRC error, temperature reading invalid\n");
            continue;
        }

        // Format and write timestamped temperature to log file
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(stderr, "Temperature: %hu°C at %s\n", data[1], timestamp);

        // Write to log file
        FILE *log_file = fopen("temperature_log.txt", "a+");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        } else {
            fprintf(log_file, "%s\n", timestamp);
        }
        fclose(log_file);

        // Cleanup and handle signals
        cleanup();
    }

    return EXIT_SUCCESS;
}

// Function to read temperature from STS40 sensor
void read_temperature(uint8_t *data) {
    // Write command to start conversion
    data[0] = 0x00; // Start conversion command

    // Wait for conversion to complete (10 ms)
    usleep(10000);

    // Read data bytes
    if (ioctl(i2c_fd, I2C_READ, data + 1) == -1) {
        fprintf(stderr, "Failed to read data from STS40: %s\n", strerror(errno));
        return;
    }
}

// Function to calculate and write CRC8
uint8_t write_crc(uint8_t *data, uint8_t crc) {
    // Sensirion ST40 CRC polynomial: x^8 + x^5 + x^4 + 1
    crc ^= data[0];
    for (int i = 1; i < 3; i++) {
        crc ^= data[i];
        crc <<= 1;
        if (crc & 0x100) {
            crc ^= 0x07;
        }
    }

    data[2] = crc; // Write CRC to the buffer

    return crc; // Return the calculated CRC for verification
}

// Cleanup function
void cleanup() {
    // Close I2C device and log file
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handlers
void signal_handler(int signum) {
    // Clean up on SIGINT and SIGTERM
    cleanup();
    exit(0);
}

