#define SENSOR_ADDR 0x5A // SDP810 default I2C address
#define CRC_POLYNOMIAL 0x07 // CRC-8 polynomial
#define CRC_INIT_VALUE 0x00 // Initial value for CRC-8

// Sensor configuration
#define SDP810_REG_PRESSURE 0x00
#define SDP810_REG_TEMPERATURE 0x01
#define SDP810_REG_SCALE_FACTOR 0x02

// File handling
FILE *logFile = NULL;
char logFileName[] = "hvac_pressure_log.txt";

// Sensor communication buffer
uint8_t buffer[9];

// Function prototypes
void init_sensors();
void cleanup();
void read_sensor_data();
void write_sensor_command(uint8_t reg, uint8_t value);
bool validate_crc8(uint8_t *data, uint8_t len, uint8_t crc_init);
void handle_interrupt(int signum);

int main() {
    // Initialize GPIO and I2C
    if (gpiod_init() != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_errstr());
        return EXIT_FAILURE;
    }

    if (i2c_init() != 0) {
        fprintf(stderr, "Error initializing I2C: %s\n", i2c_errstr());
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open log file for writing
    if ((logFile = fopen(logFileName, "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2c_cleanup();
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Main loop
    while (1) {
        // Wait for one second
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        nanosleep(&ts, NULL);

        // Read sensor data
        read_sensor_data();

        // Write data to log file
        if (fwrite(buffer, 9, 1, logFile) != 1) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            fclose(logFile);
            i2c_cleanup();
            gpiod_cleanup();
            return EXIT_FAILURE;
        }

        // Check for interrupt signal
        if (sigpending(&sigset)) {
            handle_interrupt(SIGINT);
        }
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize sensors
void init_sensors() {
    // Initialize I2C device
    if (i2c_open(SENSOR_ADDR) < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", i2c_errstr());
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    i2c_close();

    // Close log file
    fclose(logFile);

    // Cleanup GPIO
    gpiod_cleanup();
}

// Function to read sensor data
void read_sensor_data() {
    // Write command to read pressure
    write_sensor_command(SDP810_REG_PRESSURE, 0x00);

    // Read pressure data
    if (i2c_read(SENSOR_ADDR, SDP810_REG_PRESSURE, buffer, 2) != 2) {
        fprintf(stderr, "Error reading pressure data: %s\n", i2c_errstr());
        return;
    }

    // Validate pressure CRC
    if (!validate_crc8(buffer, 2, CRC_INIT_VALUE)) {
        fprintf(stderr, "CRC error in pressure data\n");
        return;
    }

    // Write command to read temperature
    write_sensor_command(SDP810_REG_TEMPERATURE, 0x00);

    // Read temperature data
    if (i2c_read(SENSOR_ADDR, SDP810_REG_TEMPERATURE, buffer + 2, 1) != 1) {
        fprintf(stderr, "Error reading temperature data: %s\n", i2c_errstr());
        return;
    }

    // Validate temperature CRC
    if (!validate_crc8(buffer + 2, 1, CRC_INIT_VALUE)) {
        fprintf(stderr, "CRC error in temperature data\n");
        return;
    }

    // Write command to read scale factor
    write_sensor_command(SDP810_REG_SCALE_FACTOR, 0x00);

    // Read scale factor data
    if (i2c_read(SENSOR_ADDR, SDP810_REG_SCALE_FACTOR, buffer + 3, 3) != 3) {
        fprintf(stderr, "Error reading scale factor data: %s\n", i2c_errstr());
        return;
    }

    // Validate scale factor CRC
    if (!validate_crc8(buffer + 6, 3, CRC_INIT_VALUE)) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return;
    }

    // Construct and print CSV line
    char csv_line[256];
    sprintf(csv_line, "%s,%u,%u,%u", 
            ctime(&time(NULL)), 
            buffer[0], 
            buffer[1], 
            buffer[2]);

    // Write CSV line to log file
    if (fwrite(csv_line, 256, 1, logFile) != 1) {
        fprintf(stderr, "Error writing CSV line to log file: %s\n", strerror(errno));
        return;
    }
}

// Function to write a command to the sensor
void write_sensor_command(uint8_t reg, uint8_t value) {
    uint8_t command[2] = { reg, value };
    if (i2c_write(SENSOR_ADDR, command, 2) != 2) {
        fprintf(stderr, "Error writing to sensor: %s\n", i2c_errstr());
        return;
    }
}

// Function to validate CRC-8
bool validate_crc8(uint8_t *data, uint8_t len, uint8_t crc_init) {
    uint8_t crc = crc_init;

    for (uint8_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) & 0x80;
        if (crc == 0) {
            return true;
        }
        crc <<= 1;
        if (crc == 0x10) {
            crc ^= CRC_POLYNOMIAL;
        }
    }

    return (crc == 0);
}

// Signal handler for SIGINT (Ctrl+C)
void handle_interrupt(int signum) {
    // Close I2C device
    i2c_close();

    // Flush and close log file
    fflush(logFile);
    fclose(logFile);

    // Call cleanup function
    cleanup();
}

