void i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
void i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len);
int crc8(uint8_t *buf, size_t len, uint8_t crc_init);

int main() {
    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Create a memory-mapped file for logging
    char *log_path = "sdp810_log.txt";
    int log_fd = open(log_path, O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Allocate memory for log entries
    char log_entry[256] = {0};

    // Main loop
    while (1) {
        // Get current timestamp
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Prepare buffer for reading
        uint8_t buffer[9] = {0};
        buffer[0] = 0x00; // Request pressure measurement
        buffer[1] = 0x00; // Start of message

        // Write to SDP810
        i2c_write(SENSIRION_I2C_ADDR, SDP810_REG_PRESSURE, buffer);

        // Read pressure and CRC
        i2c_read(SENSIRION_I2C_ADDR, SDP810_REG_PRESSURE, buffer, 2);

        // Validate CRC
        if (crc8(buffer, 2, CRC_INIT_VALUE) != buffer[2]) {
            snprintf(log_entry, sizeof(log_entry), "Error: CRC failure for pressure reading at %s", timestamp);
            write(log_fd, log_entry, strlen(log_entry));
            continue;
        }

        // Read temperature and CRC
        buffer[0] = 0x01; // Request temperature measurement
        i2c_write(SENSIRION_I2C_ADDR, SDP810_REG_TEMPERATURE, buffer);

        i2c_read(SENSIRION_I2C_ADDR, SDP810_REG_TEMPERATURE, buffer, 2);

        if (crc8(buffer, 2, CRC_INIT_VALUE) != buffer[2]) {
            snprintf(log_entry, sizeof(log_entry), "Error: CRC failure for temperature reading at %s", timestamp);
            write(log_fd, log_entry, strlen(log_entry));
            continue;
