        buffer[0] = 0x02; // Request scale factor measurement
        i2c_write(SENSIRION_I2C_ADDR, SDP810_REG_SCALE_FACTOR, buffer);

        i2c_read(SENSIRION_I2C_ADDR, SDP810_REG_SCALE_FACTOR, buffer, 2);

