        snprintf(log_entry, sizeof(log_entry), "%s,%d,%d", timestamp, buffer[0], buffer[1]);
        write(log_fd, log_entry, strlen(log_entry));

        // Sleep for at least 45 ms
        usleep(45000);
    }

    // Cleanup on SIGINT
    void cleanup(int signum) {
        // Close I2C device
        close(i2c_fd);

        // Close log file
        close(log_fd);

        // Exit the program
        exit(EXIT_SUCCESS);
    }

    // CRC-8 function
    int crc8(uint8_t *buf, size_t len, uint8_t crc_init) {
        uint8_t crc = crc_init;
        for (size_t i = 0; i < len; i++) {
            crc ^= buf[i];
            for (uint8_t j = 8; j; j--) {
                if ((crc & 1) != 0) {
                    crc >>= 1;
                    crc ^= CRC_POLYNOMIAL;
                } else {
                    crc >>= 1;
                }
            }
        }
        return crc;
    }

    return 0;
}

