#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDR 0x29 // Assuming the sensor is at address 0x29
#define PRESSURE_REG 0x00
#define TEMP_REG 0x01
#define CRC_REG 0x02
#define GPIO_NUM 17 // BCM 17 corresponds to physical pin 11

// Sensor data structure
typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint16_t crc;
} SensorData;

// Function prototypes
void i2c_read(uint8_t addr, uint8_t reg, uint8_t count, uint8_t *data);
void handle_signal(int signum);
int setup_i2c();
int setup_gpio();
void toggle_led(bool state);

int main() {
    // Initialize GPIO and I2C
    if ((setup_i2c() < 0) || (setup_gpio() < 0)) {
        perror("Initialization failed");
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Poll sensor once per second
        struct timespec timeout = {1, 0};
        if (nanosleep(&timeout, NULL) == -1) {
            perror("nanosleep error");
            break;
        }

        // Read sensor data
        uint8_t data[6];
        if (i2c_read(I2C_ADDR, PRESSURE_REG, 2, data) < 0) {
            perror("I2C read error");
            continue;
        }

        // Check CRC and handle pressure condition
        if (data[2] != 0x55) {
            perror("CRC check failed");
            continue;
        }

        if (data[0] < 95000) {
            toggle_led(true); // Pressure below threshold, toggle LED to 5 Hz
        } else {
            toggle_led(false); // Normal pressure, toggle LED to 1 Hz
        }

        // Print sensor data
        SensorData sensor_data;
        sensor_data.pressure = (data[0] << 8) | data[1];
        sensor_data.temperature = (data[2] << 8) | data[3];
        printf("Pressure: %d Pa, Temperature: %d°C, CRC: %04x\n",
               sensor_data.pressure, sensor_data.temperature, data[2]);

        // 20 ms delay
        usleep(20000);
    }

    // Clean up on SIGINT
    handle_signal(SIGINT);

    return EXIT_SUCCESS;
}

// Function to read from I2C device
void i2c_read(uint8_t addr, uint8_t reg, uint8_t count, uint8_t *data) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("I2C device open failed");
        return;
    }

    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = count,
        .buf = data
    };

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("I2C_SLAVE ioctl failed");
        close(fd);
        return;
    }

    if (write(fd, &msg, sizeof(msg)) < 0) {
        perror("I2C write failed");
        close(fd);
        return;
    }

    if (read(fd, data, count) != count) {
        perror("I2C read failed");
        close(fd);
        return;
    }

    close(fd);
}

// SIGINT handler
void handle_signal(int signum) {
    // Close I2C file descriptor
    close(open("/dev/i2c-1", O_RDWR));

    // Release GPIO
    pigpiod_close();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to setup I2C
int setup_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("I2C device open failed");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C_SLAVE ioctl failed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to setup GPIO
int setup_gpio() {
    int fd = pigpio_open();
