#include <unistd.h>

#define TMP102_ADDR 0x48  // I2C address of TMP102

// Function prototypes
void handleInterrupt(int signum);
int readTemperature(int i2c_bus);
void writeTemperatureToFile(double temperature);
void cleanup();

// Global variables
int i2c_bus = 1; // I2C bus number
gpiod_i2c_device *i2c_dev;
FILE *temperature_log_file = NULL;

// SIGINT handler
void handleInterrupt(int signum) {
    if (temperature_log_file != NULL) {
        fclose(temperature_log_file);
        temperature_log_file = NULL;
    }
    if (i2c_dev != NULL) {
        gpiod_i2c_device_destroy(i2c_dev);
        i2c_dev = NULL;
    }
    exit(0);
}

int main() {
    // Initialize variables
    char buffer[128];
    struct tm tm;
    time_t now;
    double temperature;

    // Set up signal handler for SIGINT
    signal(SIGINT, handleInterrupt);

    // Attempt to open I2C bus
    if ((i2c_dev = gpiod_i2c_new("i2c-bcm2708.1", GPIOD_I2C_FLAG_NO_WAIT)) == NULL) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpiod_error_string(i2c_dev));
        return EXIT_FAILURE;
    }

    // Attempt to read temperature from TMP102
    while (1) {
        // Read temperature
        if ((errno == 0) && (temperature = readTemperature(i2c_bus)) != -1.0) {
            // Write temperature to CSV file
            writeTemperatureToFile(temperature);
        } else {
            // Error occurred, log it
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        }

        // Sleep for 5 seconds
        sleep(5);

        // Update timestamp
        now = time(NULL);
        localtime_r(&now, &tm);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S,", &tm);

        // Append temperature to CSV file
        if (temperature_log_file == NULL) {
            temperature_log_file = fopen("temperature_log.csv", "a");
            if (temperature_log_file == NULL) {
                fprintf(stderr, "Failed to open temperature_log.csv for appending: %s\n", strerror(errno));
                break; // Exit on critical failure
            }
        }
        fprintf(temperature_log_file, "%s%.2f", buffer, temperature);
        fflush(temperature_log_file);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to read temperature from TMP102
int readTemperature(int i2c_bus) {
    int ret;
    uint8_t address = TMP102_ADDR;
    uint8_t command = 0x00; // Read temperature command

    ret = gpiod_i2c_transfer(i2c_dev, &address, 1, &command, 1, NULL, 0);
    if (ret < 1) {
        fprintf(stderr, "Failed to read temperature from TMP102: %s\n", gpiod_error_string(i2c_dev));
        return -1.0;
    }

    // Convert the 12-bit temperature value to degrees Celsius
    uint16_t raw_temp = (gpiod_i2c_read_byte_data(i2c_dev, address + 0x00)) << 8 |
                        gpiod_i2c_read_byte_data(i2c_dev, address + 0x01);

    return (raw_temp * 0.0625); // TMP102 temperature register is 12-bit, 0.5°C resolution
}

// Function to write temperature to CSV file
void writeTemperatureToFile(double temperature) {
    char formatted_temperature[20];
    sprintf(formatted_temperature, "%.2f", temperature);

    if (temperature_log_file != NULL) {
        fprintf(temperature_log_file, "%s", formatted_temperature);
        fflush(temperature_log_file);
    }
}

// Cleanup function to close resources
void cleanup() {
    if (temperature_log_file != NULL) {
        fclose(temperature_log_file);
        temperature_log_file = NULL;
    }

    if (i2c_dev != NULL) {
        gpiod_i2c_device_destroy(i2c_dev);
        i2c_dev = NULL;
    }
}

