#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/time.h>

#define I2C_BUS_NUM 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x00

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void handle_signal(int signum);
void read_humidity_and_temperature(uint8_t addr);
void cleanup();

// Main function
int main() {
    // Initialize GPIO
    if (gpiod_open(GPIOD_DIR_DEV) < 0) {
        fprintf(stderr, "Error opening GPIO device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    while (!should_exit) {
        // Sleep for 5 seconds
        struct timeval timeout;
        timeout.tv_sec = 5;
        timeout.tv_usec = 0;
        if (select(1, NULL, NULL, NULL, &timeout) < 0) {
            perror("select");
            continue;
        }

        // Poll temperature and humidity
        read_humidity_and_temperature(HDC2010_ADDR);
    }

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Signal handler for Ctrl+C
void handle_signal(int signum) {
    should_exit = 1;
}

// Function to read temperature and humidity from HDC2010
void read_humidity_and_temperature(uint8_t addr) {
    int attempts = 0;
    while (attempts < 5) { // Maximum retry count
        int ret;

        // Open I2C bus
        if ((ret = gpiod_i2c_open(I2C_BUS_NUM)) < 0) {
            fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
            return;
        }

        // Write to MEASUREMENT_CONFIG register to start measurement
        if (gpiod_i2c_write(I2C_BUS_NUM, addr, MEASUREMENT_CONFIG_REG, 0x01) < 0) {
            fprintf(stderr, "Error writing to MEASUREMENT_CONFIG: %s\n", strerror(errno));
            gpiod_i2c_close(I2C_BUS_NUM);
            return;
        }

        // Wait for measurement to complete (bit 0 of MEASUREMENT_CONFIG register clears)
        uint8_t reg_value;
        if (gpiod_i2c_read(I2C_BUS_NUM, addr, MEASUREMENT_CONFIG_REG, &reg_value) < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG: %s\n", strerror(errno));
            gpiod_i2c_close(I2C_BUS_NUM);
            return;
        }

        if (reg_value & 0x01) { // Bit 0 is set, retry
            sleep(100); // Small delay before retrying
            attempts++;
        } else {
            // Measurement complete, read data
            uint16_t humidity = 0;
            uint16_t temperature = 0;

            // Read humidity
            if (gpiod_i2c_read(I2C_BUS_NUM, addr, 0x02, &humidity) < 0) {
                fprintf(stderr, "Error reading humidity: %s\n", strerror(errno));
                gpiod_i2c_close(I2C_BUS_NUM);
                return;
            }

            // Read temperature
            if (gpiod_i2c_read(I2C_BUS_NUM, addr, 0x03, &temperature) < 0) {
                fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
                gpiod_i2c_close(I2C_BUS_NUM);
                return;
            }

            // Output readings
            printf("Humidity: %hu%%, Temperature: %hu°C\n", humidity, temperature);
        }

        // Close I2C bus
        gpiod_i2c_close(I2C_BUS_NUM);
    }
}

// Function to clean up resources
void cleanup() {
    // Close GPIO device
    gpiod_close(GPIOD_DIR_DEV);
}

