#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <errno.h>

#include <gpiod.h>
#include <libgpiod.h>

#define MAX6675_ADDR 0x48 // Default address for MAX6675
#define SPI_PORT 0 // SPI0 on Raspberry Pi
#define CE_PIN 0 // CE0 for SPI0

#define SSR_PIN 17 // GPIO17 for solid-state relay control
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

// Constants for SPI communication
#define MAX6675_CMD_READTEMP 0x03
#define MAX6675_CMD_WRITEADDR 0x01
#define MAX6675_CMD_WRITETEMP 0x02

// PID constants
#define PID_GAIN_P 0.5
#define PID_GAIN_I 0.1
#define PID_GAIN_D 0.05

// PID variables
float setpoint;
float error;
float output;
float integral;
float derivative;
float last_temperature;

// GPIO and SPI handles
gpiod_device *ssr_gpio;
gpiod_cdev *spi_cdev;
uint8_t spi_transfer(uint8_t data);

void setup_resources() {
    // Initialize GPIO for SSR
    ssr_gpio = gpiod_get_device(GPIO_NUM_17);
    if (ssr_gpio == NULL) {
        fprintf(stderr, "Error: Could not get GPIO 17.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI for MAX6675
    spi_cdev = gpiod_get_device(SPI_PORT);
    if (spi_cdev == NULL) {
        fprintf(stderr, "Error: Could not get SPI device.\n");
        exit(EXIT_FAILURE);
    }

    // Set CE pin as output
    if (gpiod_direction_output(spi_cdev, CE_PIN) != 0) {
        fprintf(stderr, "Error: Could not configure CE pin as output.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as output
    if (gpiod_direction_output(ssr_gpio, 1) != 0) {
        fprintf(stderr, "Error: Could not configure GPIO 17 as output.\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_resources() {
    // Release GPIO 17
    gpiod_set_direction(ssr_gpio, GPIO_INPUT);
    gpiod_release_device(ssr_gpio);

    // Release SPI device
    gpiod_release_device(spi_cdev);
}

void read_temperature() {
    uint8_t command = MAX6675_CMD_READTEMP;
    spi_transfer(command);
    uint16_t data = spi_transfer(0x00);
    float temperature = (data & 0x0F) * 0.25 + 273.15; // Convert to Celsius

    printf("Temperature: %.2f C\n", temperature);
    fflush(stdout);

    // Write temperature to log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%f,%d\n", (double)time(NULL), temperature);
    fclose(log_file);
}

void pid_calculation(float setpoint, float temperature) {
    error = setpoint - temperature;
    output = (error + (error * PID_GAIN_P)) + (error * integral) + (error * derivative);
    integral = error;
    derivative = (error - last_error) / 1.0; // 1-second period
    last_error = error;
}

void write_temp_to_max6675(float temperature) {
    uint8_t high_byte = (temperature / 10) >> 4;
    uint8_t low_byte = (temperature % 10) << 4;
    spi_transfer((high_byte | 0x0F) << 4);
    spi_transfer(low_byte);
}

void setup_pid() {
    setpoint = 235.0; // Target reflow temperature in Celsius
    last_temperature = 0.0;
}

void main_loop() {
    setup_resources();
    setup_pid();

    while (1) {
        pid_calculation(setpoint, last_temperature);
        write_temp_to_max6675(last_temperature);
        usleep(100000); // 100 ms delay between readings

        // Handle termination signals
        if (signal(SIGINT) == SIG_DFL) {
            // Restore default signal handler for SIGINT
            signal(SIGINT, SIG_DFL);
            printf("Exiting due to SIGINT.\n");
            cleanup_resources();
            exit(EXIT_SUCCESS);
        }

        if (signal(SIGTERM) == SIG_DFL) {
            // Restore default signal handler for SIGTERM
            signal(SIGTERM, SIG_DFL);
            printf("Exiting due to SIGTERM.\n");
            cleanup_resources();
            exit(EXIT_SUCCESS);
        }
    }
}

uint8_t spi_transfer(uint8_t data) {
    uint8_t tx_byte = data;
    gpiod_set_value(spi_cdev, CE_PIN, 1); // Assert CE
    gpiod_set_value(spi_cdev, GPIO_NUM_CS, 0); // Chip Select low

    // Send data
    uint8_t rx_byte = gpiod_in(spi_cdev, GPIO_NUM_MISO);

    gpiod_set_value(spi_cdev, GPIO_NUM_CS, 1); // Chip Select high

    return rx_byte;
}

int main() {
    setup_resources();
    signal(SIGINT, SIG_DFL); // Catch INT signal
    signal(SIGTERM, SIG_DFL); // Catch TERM signal

    main_loop();

    return 0;
}

