#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <w1.h>
#include <w1_gpio.h>
#include <linux/gpio.h>
#include <linux/pwm.h>

#define TEMP_SENSOR_PATH "/sys/bus/w1/devices/28-0000067e4b6c/w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define RELAY_PIN 0
#define PWM_PIN 0

#define TEMP_SENSOR_DEVICE_PATH "/dev/w1-0"
#define TEMP_SENSOR_READ_INTERVAL 1

// PID constants
#define KP 0.5
#define KI 0.1
#define KD 0.05

// PID output range
#define PID_OUTPUT_MIN 0
#define PID_OUTPUT_MAX 1023

// Log file
#define LOG_FILE_PATH "greenhouse.log"

// Global variables
int relay_fd = -1;
int pwm_fd = -1;
int relay_state = 0;
unsigned int pwm_duty = 0;
float temperature;
float setpoint;
float last_temperature;
float pid_output;
FILE *log_file = NULL;

// PID controller function
float pid_calc(float error) {
    float output = KP * error + KI * (temperature - last_temperature) + KD * (error - last_error);
    if (output > PID_OUTPUT_MAX) output = PID_OUTPUT_MAX;
    if (output < PID_OUTPUT_MIN) output = PID_OUTPUT_MIN;
    return output;
}

// Main function
int main(int argc, char **argv) {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return EXIT_FAILURE;
    }

    setpoint = atof(argv[1]);
    char kp_str[5], ki_str[5];
    strncpy(kp_str, argv[2], 4);
    strncpy(ki_str, argv[3], 4);

    float kp = atof(kp_str);
    float ki = atof(ki_str);

    // Initialize GPIO and PWM
    if ((relay_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open GPIO");
        return EXIT_FAILURE;
    }

    if (gpio_direction_output(relay_fd, RELAY_GPIO, relay_state == 1)) {
        perror("Failed to set relay direction");
        close(relay_fd);
        return EXIT_FAILURE;
    }

    if (pwm_init(PWM_GPIO, PWM_PIN, 1, 1023, 0)) {
        perror("Failed to initialize PWM");
        close(relay_fd);
        return EXIT_FAILURE;
    }

    // Open temperature sensor device
    if ((log_file = fopen(LOG_FILE_PATH, "a")) == NULL) {
        perror("Failed to open log file");
        close(relay_fd);
        pwm_free();
        return EXIT_FAILURE;
    }

    // Read temperature periodically
    while (1) {
        // Read temperature from DS18B20
        char buf[42];
        if (!w1_read_temp(TEMP_SENSOR_DEVICE_PATH, buf)) {
            fprintf(log_file, "Error reading temperature sensor.\n");
            continue;
        }

        // Validate CRC
        if (strncmp(buf + 39, "YES\n", 4) != 0) {
            fprintf(log_file, "Invalid CRC for temperature reading.\n");
            continue;
        }

        // Parse temperature
        temperature = (float)strtof(buf + 26, NULL);

        // Update PID output
        pid_output = pid_calc(temperature - setpoint);

        // Set PWM duty cycle
        pwm_set_value(pwm_fd, (int)(pid_output * 1023.0 / PID_OUTPUT_MAX));

        // Toggle relay based on PID output
        relay_state = pid_output > 0 ? 1 : 0;

        // Log data
        struct tm time_info;
        time(&time_info);
        char log_line[256];
        sprintf(log_line, "%s, Average Temperature: %.1f°C, Setpoint: %.1f°C, PID Output: %d, PWM Duty: %d%%\n",
            ctime(&time_info),
            temperature,
            setpoint,
            (int)pid_output,
            (int)(pid_output * 100.0 / PID_OUTPUT_MAX));
        fprintf(log_file, "%s", log_line);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    signal_handler();

    // Close resources
    fclose(log_file);
    pwm_free();
    gpio_free(relay_fd);
    close(relay_fd);

    return EXIT_SUCCESS;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up
    fclose(log_file);
    pwm_free();
    gpio_free(relay_fd);
    close(relay_fd);

    // Exit the program
    exit(0);
}

