        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    signal_handler();

    // Close resources
    fclose(log_file);
    pwm_free();
    gpio_free(relay_fd);
    close(relay_fd);

    return EXIT_SUCCESS;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Clean up
    fclose(log_file);
    pwm_free();
    gpio_free(relay_fd);
    close(relay_fd);

    // Exit the program
    exit(0);
}
