#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define SENSOR_ADDR 0x5B
#define DEHUMIDIFIER_GPIO 17

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO for dehumidifier relay
    int dehumidifier_fd = gpiod_open(DEHUMIDIFIER_GPIO, GPIOD_OPEN_OUPUT);
    if (dehumidifier_fd == -1) {
        perror("gpiod_open for dehumidifier GPIO");
        return EXIT_FAILURE;
    }

    // Initialize I2C for AHT20 sensor
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        gpiod_close(dehumidifier_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_cbs cbs = {
        .on_event = handle_signal,
    };

    // Set GPIO 17 as output
    if (gpiod_cbs_set(i2c_fd, &cbs, DEHUMIDIFIER_GPIO) < 0) {
        perror("gpiod_cbs_set for dehumidifier GPIO");
        close(i2c_fd);
        gpiod_close(dehumidifier_fd);
        return EXIT_FAILURE;
    }

    // Function to read humidity from AHT20
    int read_humidity(uint8_t addr) {
        uint8_t command = 0x00; // Start measurement command
        uint8_t data[6] = {0};

        // Send command to start measurement
        if (i2c_smbus_write_byte_data(i2c_fd, addr, command) != 0) {
            perror("i2c_smbus_write_byte_data failed");
            return -1;
        }

        // Wait for 80 ms
        usleep(80000);

        // Read 6 bytes of data
        if (i2c_smbus_read_i2c_block_data(i2c_fd, addr, 0x00, data, 6) != 6) {
            perror("i2c_smbus_read_i2c_block_data failed");
            return -1;
        }

        // Check status byte (4th byte)
        if (data[3] != 0x00) { // Calibrated status
            perror("AHT20 status byte not calibrated");
            return -1;
        }

        // Return humidity (last 2 bytes)
        return (data[5] << 8) | data[6];
    }

    // Main loop
    while (!should_exit) {
        // Poll sensor every 5 seconds
        struct timespec ts = {5 * 1000000, 0}; // 5 seconds
        nanosleep(&ts, NULL);

        int humidity = read_humidity(SENSOR_ADDR);

        if (humidity != -1) {
            // Convert humidity to percentage
            float humidity_percent = (float)humidity / 65535.0 * 100;

            // Log to console
            printf("Humidity: %.1f%%\n", humidity_percent);

            // Check humidity threshold for dehumidifier
            if (humidity_percent > 60) {
                gpiod_set_value(dehumidifier_fd, 1); // Activate relay
            } else if (humidity_percent < 55) {
                gpiod_set_value(dehumidifier_fd, 0); // Deactivate relay
            }
        } else {
            // Sensor error or all retries failed
            fprintf(stderr, "Error reading humidity from AHT20 sensor\n");
        }

        // Sleep for 1 second to avoid excessive polling
        usleep(1000000);
    }

    // Clean up on SIGINT or SIGTERM
    if (should_exit) {
        gpiod_set_value(dehumidifier_fd, 0); // Deactivate relay
        close(i2c_fd);
        gpiod_close(dehumidifier_fd);
        printf("Exiting cleanly...\n");
        exit(0);
    }

    return 0;
}

