#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <json/cJSON.h>

#define SENSOR_ADDR 0x40 // HTU21D I2C address
#define SENSOR_REG_HUMIDITY 0x00 // Register for humidity

// GPIO for I2C SDA and SCL (Raspberry Pi Zero W default)
#define I2C_SDA_GPIO_NUM 3
#define I2C_SCL_GPIO_NUM 5

// HTTP API endpoint
#define API_ENDPOINT "http://api.example.com/humidity"

// Syslog identifier
#define LOG_TAG "humidity_sensor"

// JSON object for humidity data
static const char *humidityJSONTemplate = "{\"humidity\": %f}";

void setup_i2c() {
    int sda_fd, scl_fd;
    struct i2c_dev *i2c_dev;

    // Initialize GPIO for I2C
    gpiod_set_data_direction(I2C_SDA_GPIO_NUM, GPIOD_OUT_HIGH);
    gpiod_set_data_direction(I2C_SCL_GPIO_NUM, GPIOD_OUT_HIGH);

    // Open I2C device
    sda_fd = open("/dev/i2c-1", O_RDWR);
    if (sda_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    scl_fd = open("/dev/i2c-1", O_RDWR);
    if (scl_fd == -1) {
        syslog(LOG_ERR, "Failed to open I2C clock line: %s", strerror(errno));
        close(sda_fd);
        exit(EXIT_FAILURE);
    }

    i2c_dev = i2c_dev_open(sda_fd, scl_fd);
    if (!i2c_dev) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", i2c_dev_errstr(i2c_dev));
        close(sda_fd);
        close(scl_fd);
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    i2c_dev_addr_set(i2c_dev, SENSOR_ADDR);

    // Enable I2C clock stretching
    i2c_dev_config(i2c_dev, I2C_DEV_CONFIG_CLOCK_STRETCHING);
}

void read_humidity() {
    int rc;
    uint8_t buffer[2];
    float humidity;

    // Write to humidity register
    buffer[0] = SENSOR_REG_HUMIDITY;
    rc = i2c_master_write(i2c_dev, buffer, 1);
    if (rc != 1) {
        syslog(LOG_ERR, "Failed to write to HTU21D: %d", rc);
        return;
    }

    // Read humidity data
    rc = i2c_master_read(i2c_dev, buffer, 2);
    if (rc != 2) {
        syslog(LOG_ERR, "Failed to read from HTU21D: %d", rc);
        return;
    }

    humidity = (buffer[1] << 8) | buffer[0];
    syslog(LOG_INFO, "Read humidity: %.2f%%", humidity / 100.0f);

    // Convert to JSON and post to API
    cJSON *json = cJSON_CreateFromString(humidityJSONTemplate, humidity);
    if (!json) {
        syslog(LOG_ERR, "Failed to create JSON object");
        return;
    }

    struct sockaddr_in addr;
    int sockfd;
    char buffer[1024];

    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    inet_pton(AF_INET, API_ENDPOINT, &addr.sin_addr);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        cJSON_Delete(json);
        return;
    }

    if (connect(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to %s: %s", API_ENDPOINT, strerror(errno));
        close(sockfd);
        cJSON_Delete(json);
        return;
    }

    if (send(sockfd, json->string ->data, cJSON_PrintLen(json) + 1, 0) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP POST: %s", strerror(errno));
        close(sockfd);
        cJSON_Delete(json);
        return;
    }

    close(sockfd);
    cJSON_Delete(json);
}

void graceful_shutdown() {
    syslog(LOG_INFO, "Gracefully shutting down...");
    // Close I2C resources
    i2c_dev_close(i2c_dev);
    close(I2C_SDA_GPIO_NUM);
    close(I2C_SCL_GPIO_NUM);

    // Close socket resources
    close(sockfd);
}

int main() {
    // Initialize logging
    openlog(LOG_TAG, LOG_PID, LOG_USER);

    // Set signal handlers
    struct sigaction sa;
    sa.sa_handler = graceful_shutdown;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Poll humidity every 60 seconds
        time_t now = time(NULL);
        if ((now - last_poll_time) >= 60) {
            read_humidity();
            last_poll_time = now;
        }

        sleep(60);
    }

    return 0;
}

