code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID 0x55

#define BUS_NUM 1
#define I2C_SLAVE_PATH "/dev/i2c-%i" BUS_NUM

#define PRESSURE_THRESHOLD_HIGH 1020
#define PRESSURE_THRESHOLD_LOW 980

volatile sig_atomic_t sigIntReceived = 0;
volatile sig_atomic_t sigTermReceived = 0;

void handleInterrupt(int signum) {
    sigIntReceived = 1;
    sigTermReceived = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handleInterrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *pressure_log = fopen("pressure_log.txt", "a+");
    if (!pressure_log) {
        perror("Failed to open pressure_log.txt");
        return EXIT_FAILURE;
    }

    int retry_count = 0;
    while (1) {
        // Attempt to open I2C bus and verify BMP280 chip ID
        int i2c_fd = gpiod_i2c_open(BUS_NUM);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", gpiod_error_string(gpiod_error_get()));
            if (retry_count < 3) {
                retry_count++;
                continue;
            } else {
                break;
            }
        }

        // Write to BMP280 register to read chip ID
        uint8_t register_address = 0xF4;
        uint8_t request = 0x2E;
        uint8_t response[2];

        if (gpiod_i2c_transfer(i2c_fd, &register_address, 1, &request, 1, response, 2) != 2) {
            fprintf(stderr, "Failed to read BMP280 chip ID: %s\n", gpiod_error_string(gpiod_error_get()));
            gpiod_i2c_close(i2c_fd);
            break;
        }

        if (response[0] != BMP280_CHIP_ID) {
            fprintf(stderr, "BMP280 chip ID mismatch. Expected 0x55, got 0x%02X\n", response[0]);
            gpiod_i2c_close(i2c_fd);
            break;
        }

        // Close I2C bus after successful verification
        gpiod_i2c_close(i2c_fd);

        // Main loop
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint32_t timestamp = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

        // Trigger conversion and wait for completion
        gpiod_i2c_transfer(i2c_fd, &BMP280_I2C_ADDR, 1, &BMP280_CMD_CONVERSION_START, 1, NULL, 0);
        usleep(10000); // Wait approximately 10 ms

        gpiod_i2c_transfer(i2c_fd, &BMP280_I2C_ADDR, 1, &BMP280_CMD_CONVERSION_READ, 1, &data, 3);
        uint16_t pressure = (data[1] << 8) | data[2];

        // Check pressure thresholds
        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            fprintf(pressure_log, "Pressure: %.3f hPa (timestamp: %lu)\n", pressure / 100.0, timestamp);
        }

        // Sample every 2 seconds
        if ((ts.tv_sec - last_sample_time) % 2 == 0) {
            last_sample_time = ts.tv_sec;
        }

        // Close I2C bus after each loop iteration
        gpiod_i2c_close(i2c_fd);
    }

    // Clean shutdown on SIGINT or SIGTERM
    if (sigIntReceived || sigTermReceived) {
        fprintf(pressure_log, "Shutdown triggered. Closing I2C bus and ending.\n");
        gpiod_i2c_close(-1); // Close I2C bus on exit
    }

    fclose(pressure_log);
    return EXIT_SUCCESS;
}

