#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO22 22
#define GPIO23 23
#define GPIO24 24

#define MOTOR_FORWARD 1
#define MOTOR_STOP 0

// Rain sensor GPIO pin
#define RAIN_SENSOR_GPIO GPIO17

// Motor enable GPIO pin
#define MOTOR_ENABLE_GPIO GPIO22

// Motor IN1 GPIO pin
#define MOTOR_IN1_GPIO GPIO23

// Motor IN2 GPIO pin
#define MOTOR_IN2_GPIO GPIO24

// Function prototypes
void setup_gpios(void);
void handle_rain_sense(void);
void handle_motor_control(int direction, int duration);
void cleanup_gpios(void);
void install_signal_handlers(void);
void log_message(const char *msg, time_t timestamp);
void error_handler(int signum);

int main(void) {
    struct sigaction sa;
    sa.sa_handler = error_handler;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpios();
    while (1) {
        handle_rain_sense();
        usleep(2000000); // Poll every 2 seconds
    }

    cleanup_gpios();
    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    int ret;

    // Open GPIO device
    ret = gpiod_open(&gpiod, "gpiochip0", GPIOD_OPEN_RWS);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Set up GPIO17 as input
    ret = gpiod_direction_input(RAIN_SENSOR_GPIO);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO17 direction: %s\n", gpiod_errstr(ret));
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO22, GPIO23, and GPIO24 as outputs
    ret = gpiod_direction_output(MOTOR_ENABLE_GPIO, 0);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO22 direction: %s\n", gpiod_errstr(ret));
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_output(MOTOR_IN1_GPIO, 1);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO23 direction: %s\n", gpiod_errstr(ret));
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_output(MOTOR_IN2_GPIO, 1);
    if (ret != 0) {
        fprintf(stderr, "Error setting GPIO24 direction: %s\n", gpiod_errstr(ret));
        gpiod_close(&gpiod);
        exit(EXIT_FAILURE);
    }
}

// Function to handle rain sensor and motor control
void handle_rain_sense(void) {
    int value;
    time_t timestamp;

    // Read rain sensor value
    value = gpiod_read(RAIN_SENSOR_GPIO);
    if (value == 0) {
        log_message("Rain detected at: " strptime(&timestamp, "%Y-%m-%d %H:%M:%S", &timestamp), timestamp);
        handle_motor_control(MOTOR_FORWARD, 5);
    } else {
        log_message("No rain detected at: " strptime(&timestamp, "%Y-%m-%d %H:%M:%S", &timestamp), timestamp);
    }
}

// Function to handle motor control
void handle_motor_control(int direction, int duration) {
    int ret;

    // Set motor enable pin high
    gpiod_write(MOTOR_ENABLE_GPIO, 1);

    // Set motor direction pins according to direction
    if (direction == MOTOR_FORWARD) {
        gpiod_write(MOTOR_IN1_GPIO, 1);
        gpiod_write(MOTOR_IN2_GPIO, 1);
    } else {
        gpiod_write(MOTOR_IN1_GPIO, 0);
        gpiod_write(MOTOR_IN2_GPIO, 0);
    }

    // Wait for the motor to run for the specified duration
    usleep(duration * 1000000);

    // Set motor enable pin low to stop the motor
    gpiod_write(MOTOR_ENABLE_GPIO, 0);

    // Reset direction pins to safe state
    gpiod_write(MOTOR_IN1_GPIO, 0);
    gpiod_write(MOTOR_IN2_GPIO, 0);
}

// Function to cleanup GPIO and release resources
void cleanup_gpios(void) {
    gpiod_write(RAIN_SENSOR_GPIO, 0); // Ensure rain sensor is off
    gpiod_close(&gpiod);
}

// Function to install signal handlers
void install_signal_handlers(void) {
    sa.sa_handler = cleanup_gpios;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

// Function to log messages with timestamp
void log_message(const char *msg, time_t timestamp) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timestamp);
    fprintf(stderr, "%s: %s\n", buffer, msg);
}

// Error handler for SIGINT and SIGTERM
void error_handler(int signum) {
    // Safely stop the motor and release GPIOs
    handle_motor_control(MOTOR_STOP, 0);
    cleanup_gpios();
    exit(EXIT_FAILURE);
}

