void install_signal_handlers(void) {
    sa.sa_handler = cleanup_gpios;
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

// Function to log messages with timestamp
void log_message(const char *msg, time_t timestamp) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timestamp);
    fprintf(stderr, "%s: %s\n", buffer, msg);
}

// Error handler for SIGINT and SIGTERM
void error_handler(int signum) {
    // Safely stop the motor and release GPIOs
    handle_motor_control(MOTOR_STOP, 0);
    cleanup_gpios();
    exit(EXIT_FAILURE);
}

