#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <time.h>

#define GPIO_RED   17
#define GPIO_GREEN 22
#define GPIO_BLUE  27

#define PWM_MIN 0
#define PWM_MAX 255

void setup_gpiod(void);
void cleanup_gpiod(void);
void set_pwm_value(gpiod_device *dev, int pin, int value);
void read_cpu_load(void);
void map_load_to_color(int load, unsigned int *r, unsigned int *g, unsigned int *b);
void handle_signal(int signum);
int main(void) {
    struct sigaction sa;
    gpiod_device *rgb_led;
    unsigned int prev_load[3] = {0, 0, 0};
    unsigned int r, g, b;
    int cpu_load[3];
    int i;
    int status;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Attempt to initialize libgpiod
    if ((rgb_led = gpiod_open(GPIO_RED | GPIO_GREEN | GPIO_BLUE, GPIOD_OUT PWM)) == NULL) {
        fprintf(stderr, "Failed to open GPIO pins for PWM.\n");
        exit(1);
    }

    // Set up signal handlers
    sa.sa_handler = NULL; // Reset signal handler to default
    sigaction(SIGINT, NULL, &sa);
    sigaction(SIGTERM, NULL, &sa);

    while (1) {
        // Read CPU load
        if (gpiod_read(rgb_led, GPIO_RED, &prev_load[0]) < 0 || 
            gpiod_read(rgb_led, GPIO_GREEN, &prev_load[1]) < 0 || 
            gpiod_read(rgb_led, GPIO_BLUE, &prev_load[2]) < 0) {
            fprintf(stderr, "Failed to read CPU load.\n");
            break;
        }

        // Calculate current load
        for (i = 0; i < 3; i++) {
            cpu_load[i] = (prev_load[i] - (prev_load[i] >> 1)) * 100;
        }

        // Map load to color
        map_load_to_color(cpu_load[0], &r, &g, &b);

        // Set PWM values
        set_pwm_value(rgb_led, GPIO_RED, PWM_MIN + r);
        set_pwm_value(rgb_led, GPIO_GREEN, PWM_MIN + g);
        set_pwm_value(rgb_led, GPIO_BLUE, PWM_MIN + b);

        // Sleep for 500ms
        usleep(500000);

        // Check for signals
        if (sigpending(&sa.sa_mask) != 0) {
            handle_signal(SIGINT);
            handle_signal(SIGTERM);
        }
    }

    // Clean up
    cleanup_gpiod();

    return 0;
}

// Function to set PWM value on a GPIO pin
void set_pwm_value(gpiod_device *dev, int pin, int value) {
    if (gpiod_set_data(dev, pin, value) < 0) {
        fprintf(stderr, "Error setting PWM value on GPIO pin.\n");
    }
}

// Function to map CPU load to color
void map_load_to_color(int load, unsigned int *r, unsigned int *g, unsigned int *b) {
    if (load <= 50) {
        *r = 0;
        *g = 255;
        *b = 0;
    } else if (load <= 100) {
        *r = 255 - (load * 2);
        *g = 255 - load * 2;
        *b = 0;
    } else {
        *r = 255;
        *g = 0;
        *b = 0;
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Turn off the LED for common anode
    for (int pin = GPIO_RED; pin <= GPIO_BLUE; pin++) {
        gpiod_set_data(NULL, pin, 0);
    }

    // Clean up and exit
    cleanup_gpiod();
    exit(0); // Exit cleanly on signal
}

// Function to initialize libgpiod
void setup_gpiod(void) {
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod.\n");
        exit(1);
    }
}

// Function to cleanup libgpiod
void cleanup_gpiod(void) {
    gpiod_uninit();
}

