#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <json-c/json.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_TEMP_OUT_H 0x88
#define BMP280_REG_PRESSURE_OUT_H 0x86

struct bmp280_data {
    int16_t temp_out_h;
    int16_t pressure_out_h;
};

void i2c_init(void) {
    int fd;
    struct i2c_dev *i2c_dev;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Create I2C device structure
    i2c_dev = i2c_dev_open(fd, I2C_FLAG_NONE);
    if (!i2c_dev) {
        perror("Failed to open I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    i2c_dev_addr_set(i2c_dev, BMP280_I2C_ADDR);
}

void bmp280_read(struct bmp280_data *data) {
    uint8_t cmd[2] = { BMP280_REG_TEMP_OUT_H, 0 };
    uint8_t buf[2];

    // Write command to BMP280
    if (i2c_smbus_write_i2c_block_data(i2c_dev, BMP280_I2C_ADDR, cmd, 2) < 0) {
        perror("Failed to write to BMP280");
        exit(EXIT_FAILURE);
    }

    // Read response
    if (i2c_smbus_read_i2c_block_data(i2c_dev, BMP280_I2C_ADDR, buf, 2) < 0) {
        perror("Failed to read from BMP280");
        exit(EXIT_FAILURE);
    }

    data->temp_out_h = buf[0];
    data->pressure_out_h = buf[1];
}

void cleanup_i2c(void) {
    if (i2c_dev) {
        i2c_dev_close(i2c_dev);
        i2c_dev_destroy(i2c_dev);
    }
    close(fd);
}

void cleanup_udp(void) {
    if (udp_socket) {
        close(udp_socket);
        freeaddrinfo((struct sockaddr *) &server_addr);
    }
}

void cleanup_gpiod(void) {
    if (gpiod_get(&i2c_dev_fd)) {
        gpiod_put(i2c_dev_fd);
    }
}

void handle_signal(int signum) {
    switch (signum) {
        case SIGINT:
        case SIGTERM:
            // Clean up resources
            cleanup_i2c();
            cleanup_udp();
            cleanup_gpiod();
            exit(EXIT_SUCCESS);
            break;
        default:
            // Handle other signals
            perror("Unknown signal");
            exit(EXIT_FAILURE);
    }
}

int main(void) {
    struct bmp280_data data;
    struct addrinfo *server_addr;
    int udp_socket, opt;
    sigset_t sigset;
    int rv;

    // Initialize I2C
    i2c_init();

    // Set signal handlers
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read BMP280 data
        bmp280_read(&data);

        // Format data into JSON
        char json_str[256];
        json_object *root, *temp, *pressure;
        json_error_t error;

        root = json_object_new_object();
        temp = json_object_new_string("temperature");
        pressure = json_object_new_string("pressure");

        json_object_set_int(root, "value", data.temp_out_h);
        json_object_set_int(root, (char *)temp, data.temp_out_h);
        json_object_set_int(root, (char *)pressure, data.pressure_out_h);

        if (json_object_put(root) != 0) {
            fprintf(stderr, "Error serializing JSON: %s\n", json_error_message(&error));
            continue;
        }

        // Convert JSON to string
        if (json_text_pretty_print_to_buffer(json_object_get(root), json_str, sizeof(json_str), -1) != 0) {
            fprintf(stderr, "Error converting JSON to string: %s\n", json_error_message(&error));
            continue;
        }

        // Send JSON via UDP
        server_addr = NULL;
        rv = getaddrinfo("192.168.1.100", "5000", NULL, &server_addr);
        if (rv != 0) {
            perror("Error resolving IP address");
            continue;
        }

        udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
        if (udp_socket == -1) {
            perror("Error creating UDP socket");
            continue;
        }

        // Send UDP packet
        struct sockaddr_in dest_addr = *(struct sockaddr_in *)server_addr;
        sendto(udp_socket, json_str, strlen(json_str), 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));

        freeaddrinfo(server_addr);
    }

    // Clean up resources
    cleanup_i2c();
    cleanup_udp();
    cleanup_gpiod();

    return 0;
}

