#define BUFFER_SIZE 20
#define SPI_CHANNEL 0
#define GPIO_PWM 18
#define GPIO_CE0 8

struct temperature_data {
    int timestamp;
    float temperature;
    float duty_cycle;
};

static struct temperature_data buffer[BUFFER_SIZE];

static int circular_buffer_index = 0;

// Function prototypes
void setup_pwm();
void setup_spi();
void read_temperature();
void update_pwm();
void handle_signal(int signum);
void print_buffer();

int main() {
    // Initialize GPIO and SPI
    setup_pwm();
    setup_spi();

    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    while (1) {
        // Read temperature and update PWM
        read_temperature();
        update_pwm();

        // Handle buffer overflow
        if (circular_buffer_index == BUFFER_SIZE) {
            circular_buffer_index = 0;
