#include <libbmp180.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_OSS 3

volatile int gpiointerrupt = 0;

FILE *altitude_log = NULL;

void setup_bmp180(void) {
    struct bmp180_config config;
    config Resolution = BMP180_OSRR;
    config Oversampling = BMP180_OSS;
    config Measure = BMP180_MEASURINGTEMP | BMP180_MEASUREP;

    if (bmp180_init(BMP180_I2C_ADDR, &config) != BMP180_OK) {
        fprintf(stderr, "Failed to initialize BMP180\n");
        exit(EXIT_FAILURE);
    }
}

void setup_gpiointerrupt() {
    int ret;
    struct gpio_desc *gpion;

    gpion = gpiod_get_desc(GPIO_NUM_2);
    if (gpion == NULL) {
        fprintf(stderr, "Failed to get GPIO 2 descriptor\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_input(gpion);
    if (ret != GPIO_DIR_IN) {
        fprintf(stderr, "Failed to configure GPIO 2 as input\n");
        gpiod_free_desc(gpion);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_enable_pull_up(gpion);
    if (ret != 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO 2\n");
        gpiod_free_desc(gpion);
        exit(EXIT_FAILURE);
    }

    gpiointerrupt_handler = gpiod_get_irq_handler(gpion);
    if (gpiointerrupt_handler == NULL) {
        fprintf(stderr, "Failed to get GPIO 2 interrupt handler\n");
        gpiod_free_desc(gpion);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_SIGINT);
}

void gpiointerrupt_handler(void) {
    gpiointerrupt = 1;
}

void handle_SIGINT(int signum) {
    if (altitude_log != NULL) {
        fclose(altitude_log);
        altitude_log = NULL;
    }
    bmp180_deinit();
    gpiod_free_desc(gpiod_get_desc(GPIO_NUM_2));
    gpiointerrupt_handler = NULL;
}

void toggle_logging() {
    if (altitude_log == NULL) {
        altitude_log = fopen("altitude_log.txt", "a+");
        if (altitude_log == NULL) {
            fprintf(stderr, "Failed to open altitude_log.txt for appending\n");
            exit(EXIT_FAILURE);
        }
    } else {
        fclose(altitude_log);
        altitude_log = NULL;
    }
}

void read_bmp180() {
    struct bmp180_data data;
    if (bmp180_read(BMP180_I2C_ADDR, &data) != BMP180_OK) {
        fprintf(stderr, "Failed to read BMP180 data\n");
        return;
    }

    uint16_t temperature = data.Temp;
    uint16_t pressure = data.Pressure;

    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    char line[256];
    sprintf(line, "%s,%d,%d\n", timestamp, (int)temperature, (int)pressure);

    if (toggle_logging()) {
        fprintf(altitude_log, "%s", line);
    }
}

int main(void) {
    setup_bmp180();
    setup_gpiointerrupt();

    while (1) {
        if (gpiointerrupt) {
            read_bmp180();
            gpiointerrupt = 0;
        }

        usleep(1000000); // 1 second delay
    }

    return 0;
}

