#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>
#include <errno.h>

#define MAX31865_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CE_PIN 8
#define MAX31865_REG_FSTS 0x00
#define MAX31865_REG_TSENS 0x01
#define MAX31865_BIAS_VOLTAGE 2.5

// Function prototypes
void init_spi();
int open_spi_device();
void close_spi_device(int fd);
void write_spi(uint8_t *data, int len, int fd);
void read_spi(uint8_t *data, int len, int fd);
int compute_temperature(uint16_t raw_t);
void log_temperature(double temperature);
void handle_signal(int signum);

int main() {
    srand(time(NULL));

    // Initialize SPI
    init_spi();

    // Open SPI device
    int fd = open_spi_device();
    if (fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set GPIO as CE pin
    gpiod_set_data_direction(GPIO_DIR_OUT, CE_PIN);
    gpiod_write(GPIO_NUM_8, 1);

    // Main loop
    while (1) {
        // Check for signals
        if (waitpid(-1, NULL, WUNTRACED) > 0 && WIFSIGNALED(0)) {
            handle_signal(WTERMSIG);
        }

        // Read temperature every 5 seconds
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        if ((ts.tv_sec % 5) == 0) {
            uint8_t buffer[2];
            read_spi(buffer, 2, fd);

            // Check fault status
            uint8_t fault_status = buffer[0] & 0x0F;
            if (fault_status) {
                fprintf(stderr, "Fault detected: %02X\n", fault_status);
                continue;
            }

            uint16_t raw_t = (buffer[0] << 8) | buffer[1];
            double temperature = compute_temperature(raw_t);

            log_temperature(temperature);

            // Release CE pin
            gpiod_set_data_direction(GPIO_DIR_IN, CE_PIN);
            gpiod_write(GPIO_NUM_8, 0);
        }
    }

    // Close SPI device and release resources
    close_spi_device(fd);
    return 0;
}

// SPI initialization function
void init_spi() {
    int spi_fd[2];
    if (pipe(spi_fd) == -1) {
        perror("Failed to create pipe for SPI");
        exit(EXIT_FAILURE);
    }

    if (gpiod_spi_setup(SPI_SPEED, SPI0, spi_fd[1], 1) == -1) {
        perror("Failed to setup SPI");
        exit(EXIT_FAILURE);
    }

    if (fcntl(spi_fd[0], F_SETFL, O_NONBLOCK) == -1) {
        perror("Failed to set non-blocking mode");
        exit(EXIT_FAILURE);
    }
}

// Open SPI device function
int open_spi_device() {
    char dev_name[10] = {0};
    sprintf(dev_name, "/dev/spidev%s.0", MAX31865_DEVICE);
    int fd = open(dev_name, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

// Close SPI device function
void close_spi_device(int fd) {
    close(fd);
}

// Write to SPI function
void write_spi(uint8_t *data, int len, int fd) {
    if (write(fd, data, len) != len) {
        perror("Failed to write to SPI");
    }
}

// Read from SPI function
void read_spi(uint8_t *data, int len, int fd) {
    if (read(fd, data, len) != len) {
        perror("Failed to read from SPI");
    }
}

// Compute temperature from raw value using Callendar-Van Dusen equation
int compute_temperature(uint16_t raw_t) {
    // Constants for Callendar-Van Dusen equation
    const double A = 3.9083;
    const double B = 227.0;
    const double T0 = 373.15;

    double t = (raw_t * 1.0 / 4095.0) - 273.15;
    double temp = A * (t ** B) + T0;

    return temp;
}

// Log temperature to rtd_log.csv
void log_temperature(double temperature) {
    char timestamp[50];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

    FILE *file = fopen("rtd_log.csv", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s, %f\n", timestamp, temperature);
    fclose(file);
}

// Handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    // Graceful shutdown
    close_spi_device(-1);
    printf("Exiting due to signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

