int open_spi_device() {
    char dev_name[10] = {0};
    sprintf(dev_name, "/dev/spidev%s.0", MAX31865_DEVICE);
    int fd = open(dev_name, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

// Close SPI device function
void close_spi_device(int fd) {
    close(fd);
}

// Write to SPI function
void write_spi(uint8_t *data, int len, int fd) {
    if (write(fd, data, len) != len) {
        perror("Failed to write to SPI");
    }
}

// Read from SPI function
void read_spi(uint8_t *data, int len, int fd) {
    if (read(fd, data, len) != len) {
        perror("Failed to read from SPI");
    }
}

// Compute temperature from raw value using Callendar-Van Dusen equation
int compute_temperature(uint16_t raw_t) {
    // Constants for Callendar-Van Dusen equation
    const double A = 3.9083;
    const double B = 227.0;
    const double T0 = 373.15;

    double t = (raw_t * 1.0 / 4095.0) - 273.15;
    double temp = A * (t ** B) + T0;

    return temp;
}

// Log temperature to rtd_log.csv
void log_temperature(double temperature) {
    char timestamp[50];
    time_t t = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

    FILE *file = fopen("rtd_log.csv", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s, %f\n", timestamp, temperature);
    fclose(file);
}

// Handle signals (SIGINT, SIGTERM)
void handle_signal(int signum) {
    // Graceful shutdown
    close_spi_device(-1);
    printf("Exiting due to signal %d\n", signum);
    exit(EXIT_SUCCESS);
}
