            break;
        }

        // Format timestamp
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

        // Write to log file
        write_log(timestamp, data.temperature, data.humidity, data.pressure);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to initialize BME280 sensor
void bme280_init() {
    int fd;
    gpiod_cdev_t *cdev;
    fd = open(BME280_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open BME280 device");
        exit(EXIT_FAILURE);
    }

    cdev = gpiod_cdev_from_fd(fd);
    if (!cdev) {
        perror("Failed to get cdev");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (gpiod_set_cdev_property(cdev, GPIOD_PROP_I2C_ADDR, &BME280_I2C_ADDR, sizeof(BME280_I2C_ADDR)) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize BME280 sensor
    if (bme280_init_device(BME280_I2C_ADDR) != BME280_OK) {
        fprintf(stderr, "Failed to initialize BME280 sensor\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read data from BME280 sensor
void bme280_read_data(bme280_data_t *data) {
    int ret;

    // Read sensor data
    ret = bme280_read_retry(BME280_TEMPERATURE, &data->temperature, 1);
    if (ret != BME280_OK) {
        fprintf(stderr, "Failed to read temperature: %d\n", ret);
        return;
    }

    ret = bme280_read_retry(BME280_HUMIDITY, &data->humidity, 1);
    if (ret != BME280_OK) {
        fprintf(stderr, "Failed to read humidity: %d\n", ret);
        return;
    }

    ret = bme280_read_retry(BME280_PRESSURE, &data->pressure, 1);
    if (ret != BME280_OK) {
        fprintf(stderr, "Failed to read pressure: %d\n", ret);
        return;
    }
}

// Function to write log entry
void write_log(const char *timestamp, int temperature, int humidity, int pressure) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s, %d, %d, %d\n", timestamp, temperature, humidity, pressure);
    write(log_fd, log_entry, strlen(log_entry));
}

// Function to clean up resources
void cleanup(void) {
    if (log_fd != -1) {
        fclose(log_fd);
        log_fd = -1;
    }

    // Close BME280 device file
    close(BME280_DEVICE_PATH);
    BME280_DEVICE_PATH = -1;

    // Release cdev
    gpiod_cdev_put(cdev);
    cdev = NULL;
}

