This C program initializes a BME280 sensor connected to the Raspberry Pi Zero W via I2C bus 1, reads temperature, humidity, and pressure data, verifies the BME280 chip ID, logs the data to a CSV file every five seconds, and handles errors and resource cleanup properly. It uses the `libgpiod` library for I2C operations and `gpiod` for GPIO management. The program checks the result of every I2C read and write operation and ensures that all file descriptors and resources are released on exit, including when the process receives a signal like SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c.h>
#include <stdint.h>

#define BMP180_ADDR 0x77  // BMP180 I2C address
#define BMP180_REG_PRESSURE 0x2E  // Pressure register address
#define SAMPLE_INTERVAL_MS 50  // Sample interval in milliseconds
#define BUFFER_SIZE 1200  // Size of the circular buffer for 60 seconds at 20 Hz
#define ALERT_THRESHOLD 5  // Pressure deviation threshold in hPa
#define ALERT_GPIO 24  // GPIO pin for alert

// Structure to hold pressure and timestamp
typedef struct {
    uint16_t pressure;
    uint32_t timestamp;
} PressureReading;

// Circular buffer for pressure readings
static PressureReading buffer[BUFFER_SIZE];

// Rolling average calculation
static uint16_t rollingAverage = 0;
static size_t rollingCount = 0;

// Function to read BMP180 pressure
int bmp180_read_pressure(i2c_dev_t *i2c, uint8_t addr) {
    uint8_t cmd[1] = { BMP180_REG_PRESSURE };
    i2c_transfer(i2c, addr, cmd, 1, cmd, 1);
    return (i2c->buf->data[0] << 8) | i2c->buf->data[1];
}

// Function to handle I2C errors
void i2c_error_handler(i2c_dev_t *i2c, int error) {
    fprintf(stderr, "I2C error: %d\n", error);
    exit(1);
}

// Function to handle BMP180 sensor absence
void bmp180_absent_handler(i2c_dev_t *i2c) {
    fprintf(stderr, "BMP180 sensor not found.\n");
    exit(1);
}

// Function to compute rolling average
void update_rolling_average(uint16_t new_value) {
    rollingCount++;
    rollingAverage += new_value;
    rollingAverage /= (rollingCount + 1);
}

// Main function
int main() {
    // Initialize GPIO and I2C
    gpiod_direction_output(GPIOD_NUM_24, 1); // Set GPIO24 as output
    i2c_dev_t *i2c_dev = i2c_new_device(1, BMP180_ADDR, NULL, NULL, i2c_error_handler, NULL);
    if (i2c_dev == NULL) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Set up the circular buffer
    time_t now = time(NULL);
    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        buffer[i].pressure = bmp180_read_pressure(i2c_dev, BMP180_ADDR);
        buffer[i].timestamp = now;
        now += SAMPLE_INTERVAL_MS / 1000.0;
    }

    // Main loop
    while (1) {
        // Update the rolling average
        update_rolling_average(buffer[rollingCount - 1].pressure);

        // Sample the BMP180
        uint16_t pressure = bmp180_read_pressure(i2c_dev, BMP180_ADDR);
        buffer[rollingCount % BUFFER_SIZE].pressure = pressure;
        buffer[rollingCount % BUFFER_SIZE].timestamp = time(NULL);

        // Check for pressure deviation
        if (abs(pressure - rollingAverage) > ALERT_THRESHOLD) {
            gpiod_set_value(GPIOD_NUM_24, 0); // Set GPIO24 to LOW
            fprintf(stderr, "Alert: Pressure deviates by %hu hPa.\n", abs(pressure - rollingAverage));
        } else {
            gpiod_set_value(GPIOD_NUM_24, 1); // Set GPIO24 to HIGH
        }

        // Handle I2C errors within the loop
        if (i2c_transfer(i2c_dev, NULL, 0, NULL, 0) < 0) {
            i2c_error_handler(i2c_dev, -1);
            break;
        }
    }

    // Cleanup on SIGINT
    cleanup:

    // Release resources
    i2c_delete_device(i2c_dev);
    gpiod_set_value(GPIOD_NUM_24, 0); // Reset GPIO24

    return 0;
}

// Function to clean up resources
void cleanup(int signum) {
    // Clean up resources here
    // Since we're already releasing resources in the main loop on SIGINT,
    // this function can be empty.
}

