#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <inttypes.h>
#include <sys/time.h>
#include <libgpiod.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIBTEMP 0x2B
#define BMP180_REG_CALIBPRESS 0x2C
#define BMP180_REG_OSDATA 0xF4
#define BMP180_REG_CONTROL 0x2E

#define BMP180_SAMPLING_RATE 500 /* 500 ms */

volatile uint8_t sample_flag = 0;

struct bmp180_data {
    uint16_t calibTemp;
    uint16_t calibPress;
    uint16_t osData;
};

FILE *bmp180_log_file;

void bmp180_read_calibration(void) {
    struct bmp180_data data;
    int fd;

    /* Open I2C bus 1 */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    /* Write to control register to set ultra low power mode */
    if (write(fd, &BMP180_REG_CONTROL, sizeof(uint8_t)) != 1) {
        perror("Failed to write to BMP180 control register");
        close(fd);
        exit(EXIT_FAILURE);
    }

    /* Read calibration temperature */
    if (write(fd, &BMP180_REG_CALIBTEMP, sizeof(uint16_t)) != 2) {
        perror("Failed to read BMP180 calibration temperature");
        close(fd);
        exit(EXIT_FAILURE);
    }
    data.calibTemp = read(fd, &BMP180_REG_CALIBTEMP, sizeof(uint16_t));

    /* Read calibration pressure */
    if (write(fd, &BMP180_REG_CALIBPRESS, sizeof(uint16_t)) != 2) {
        perror("Failed to read BMP180 calibration pressure");
        close(fd);
        exit(EXIT_FAILURE);
    }
    data.calibPress = read(fd, &BMP180_REG_CALIBPRESS, sizeof(uint16_t));

    /* Read OS data */
    if (write(fd, &BMP180_REG_OSDATA, sizeof(uint8_t)) != 1) {
        perror("Failed to read BMP180 OS data");
        close(fd);
        exit(EXIT_FAILURE);
    }
    data.osData = read(fd, &BMP180_REG_OSDATA, sizeof(uint8_t));

    /* Close I2C bus */
    close(fd);

    /* Check if calibration data is valid */
    if (data.osData != 0x2E) {
        fprintf(stderr, "BMP180 calibration data invalid\n");
        exit(EXIT_FAILURE);
    }

    fprintf(bmp180_log_file, "Calibration:\n");
    fprintf(bmp180_log_file, "Temperature: %hu C\n", data.calibTemp);
    fprintf(bmp180_log_file, "Pressure: %hu Pa\n", data.calibPress);
    fprintf(bmp180_log_file, "OS Data: 0x%02X\n", data.osData);
    fflush(bmp180_log_file);
}

void bmp180_sample(void) {
    struct bmp180_data data;
    int fd;

    /* Open I2C bus 1 */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return;
    }

    /* Write to control register to start measurement */
    if (write(fd, &BMP180_REG_CONTROL, sizeof(uint8_t)) != 1) {
        perror("Failed to write to BMP180 control register");
        close(fd);
        return;
    }

    /* Wait for measurement to complete */
    while (read(fd, &BMP180_REG_OSDATA, sizeof(uint8_t)) != 1) {
        // No-op, just wait
    }

    /* Read temperature and pressure */
    if (read(fd, &data.calibTemp, sizeof(uint16_t)) != 2 ||
        read(fd, &data.calibPress, sizeof(uint16_t)) != 2) {
        perror("Failed to read BMP180 temperature and pressure");
        close(fd);
        return;
    }

    /* Append data to log file */
    fprintf(bmp180_log_file, "Sample:\n");
    fprintf(bmp180_log_file, "Temperature: %hu C\n", data.calibTemp);
    fprintf(bmp180_log_file, "Pressure: %hu Pa\n", data.calibPress);
    fflush(bmp180_log_file);

    /* Close I2C bus */
    close(fd);
}

