#include <errno.h>

#define PWM_GPIO 18 // GPIO18 on Raspberry Pi 3 Model B+
#define PWM_FREQ 25000 // 25 kHz PWM frequency
#define TEMP_MIN 40 // Minimum temperature threshold (40°C)
#define TEMP_MAX 70 // Maximum temperature threshold (70°C)
#define DUTY_MIN 0 // Minimum duty cycle (0%)
#define DUTY_MAX 255 // Maximum duty cycle (100%)

// Function prototypes
void setup_pwm();
void cleanup();
void handle_signal(int signum);
void read_temperature(char *buf, size_t len);
void map_temperature(double temp, int *duty);
void write_log(const char *message);
void pwm_control(int duty);

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Attempt to initialize PWM
    if (gpiod_direction_output(PWM_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing PWM: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    setup_pwm();

    while (1) {
        // Read temperature
        char temp_str[10];
        if (read_temperature(temp_str, sizeof(temp_str)) < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            break;
        }

        double temperature = atof(temp_str);
        int duty_cycle;

        // Map temperature to duty cycle
        map_temperature(temperature, &duty_cycle);

        // Clamp duty cycle
        duty_cycle = (duty_cycle < DUTY_MIN) ? DUTY_MIN : (duty_cycle > DUTY_MAX) ? DUTY_MAX : duty_cycle;

        // Control PWM fan
        pwm_control(duty_cycle);

        // Log every 5 seconds
        if ((time_t)clock() % 5 == 0) {
            write_log("Timestamp: %s Temperature: %f Duty Cycle: %d\n",
                      ctime(&time(NULL)), temperature, duty_cycle);
        }

        // Sleep for a short period to avoid excessive CPU usage
        usleep(10000);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup PWM
void setup_pwm() {
    if (gpiod_set_data_direction(PWM_GPIO, GPIOD_DATA_DIR_OUT) < 0) {
        fprintf(stderr, "Error setting PWM direction: %s\n", strerror(errno));
        return;
    }

    // Configure PWM frequency
    if (gpiod_configPWM(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error configuring PWM frequency: %s\n", strerror(errno));
        return;
    }
}

// Function to cleanup resources
void cleanup() {
    // Stop PWM
    gpiod_stop(PWM_GPIO);

    // Close log file
    if (log_file != NULL) {
        close(log_file);
        log_file = NULL;
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Stop PWM
    gpiod_stop(PWM_GPIO);

    // Close log file
    if (log_file != NULL) {
        close(log_file);
        log_file = NULL;
    }

    // Gracefully exit
    printf("Stopping fan and exiting due to signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

// Function to read temperature from /sys/class/thermal/thermal_zone0/temp
int read_temperature(char *buf, size_t len) {
    FILE *temp_file;
    char temp_str[10];

    temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (temp_file == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    // Read temperature
    if (fscanf(temp_file, "%lf", temp_str) != 1) {
        fclose(temp_file);
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    fclose(temp_file);

    return 0;
}

// Function to map temperature to duty cycle
void map_temperature(double temperature, int *duty_cycle) {
    if (temperature < TEMP_MIN) {
        *duty_cycle = DUTY_MIN;
    } else if (temperature > TEMP_MAX) {
        *duty_cycle = DUTY_MAX;
    } else {
        double normalized_temp = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * (DUTY_MAX - DUTY_MIN) + DUTY_MIN;
        *duty_cycle = (int)normalized_temp;
    }
}

// Function to write to the log file
void write_log(const char *message) {
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;
    char timestamp[50];

    now = time(NULL);
    timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("fan_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

// Function to control PWM duty cycle
void pwm_control(int duty_cycle) {
    if (gpiod_set_value(PWM_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
    }
}

