#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BMP280_ADDR_DEFAULT 0x76
#define BMP280_ADDR_ALTERNATIVE 0x77

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define BMP280_I2C_SLAVE 0x52

#define TEMP_OFFSET 0x00
#define PRESSURE_OFFSET 0x04
#define CTRL_MEAS_REG 0x2E

#define TEMP_FULL_SCALE 16384
#define PRESSURE_FULL_SCALE 16384

void print_weather_data(const char *timestamp, float temperature, float pressure) {
    char buffer[256];
    sprintf(buffer, "%s, Temperature: %.2f °C, Pressure: %.2f hPa", timestamp, temperature, pressure);
    FILE *weather_file = fopen("weather_data.txt", "a+");
    if (!weather_file) {
        fprintf(stderr, "Failed to open weather_data.txt for appending.\n");
        exit(1);
    }
    fputs(buffer, weather_file);
    fclose(weather_file);
}

int main() {
    int i2c_fd;
    struct pigpiod *pi;
    float temperature, pressure;
    char buffer[16];
    int retry_count = 0;

    // Initialize pigpio
    pi = pigpio_open();
    if (!pi) {
        fprintf(stderr, "Failed to open pigpio.\n");
        return 1;
    }
    pigpio_set_mode(pi, PIGPIO_MODEheadless); // Headless mode for simplicity

    // Attempt to open I2C device
    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE_PATH, strerror(errno));
        return 1;
    }

    // Attempt to read device capabilities
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_SLAVE) == -1) {
        fprintf(stderr, "Failed to change I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Attempt to read sensor's address
    if (ioctl(i2c_fd, I2C_FUNCS, &buffer) == -1) {
        fprintf(stderr, "Failed to read I2C device functions: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (buffer[0] != BMP280_ADDR_DEFAULT && buffer[0] != BMP280_ADDR_ALTERNATIVE) {
        fprintf(stderr, "Sensor address not found. Falling back to default address 0x76.\n");
        BMP280_ADDR_DEFAULT = buffer[0];
    }

    // Main loop
    while (1) {
        // Reset and start measurement
        if (write(i2c_fd, &CTRL_MEAS_REG, 1) != 1) {
            fprintf(stderr, "Failed to write to CTRL_MEAS_REG: %s\n", strerror(errno));
            break; // Exit on I/O failure
        }

        // Wait for measurement to complete
        usleep(100000); // 100 ms

        // Read temperature and pressure
        if (read(i2c_fd, &buffer, 5) != 5) {
            fprintf(stderr, "Failed to read BMP280: %s\n", strerror(errno));
            break; // Exit on I/O failure
        }

        // Apply 64-bit compensation
        temperature = (buffer[0] << 16) | buffer[1];
        temperature -= (int16_t)((buffer[2] << 8) | buffer[3]);
        temperature += TEMP_OFFSET;
        temperature /= TEMP_FULL_SCALE * 0.00001;

        pressure = (buffer[4] << 16) | buffer[5];
        pressure -= (int16_t)((buffer[6] << 8) | buffer[7]);
        pressure += PRESSURE_OFFSET;
        pressure /= PRESSURE_FULL_SCALE * 0.00001;

        // Print weather data every 5 seconds
        struct tm tm;
