        if (pi_check_signal(pi, SIGINT) || pi_check_signal(pi, SIGTERM)) {
            printf("Received signal, exiting...\n");
            break;
        }
    }

    // Close I2C file descriptor and exit
    close(i2c_fd);
    pigpio_close(pi);

    return 0;
}
