        .flags = 0,
        .len = sizeof(float)
    };

    ret = i2c_smbus_read_i2c(i2c_fd, &msg);
    if (ret < 0) {
        handle_error("i2c_smbus_read_i2c", strerror(errno));
        return -1;
    }

    memcpy(data, (void *)msg.data, sizeof(float));
    return 0;
}

// Background thread function to monitor temperature and control LED
