    float temp;
    pthread_mutex_lock(&buffer_mutex);

    while (1) {
        temp = i2c_read(&circular_buffer[BUFFER_SIZE - 1]);
        circular_buffer[BUFFER_SIZE - 1] = temp;

        running_average += temp - running_average / 60.0;
        running_average /= 60.0;

        if (temp > 28.0) {
            alert_active = 1;
        } else {
            alert_active = 0;
        }

        pthread_mutex_unlock(&buffer_mutex);

        // Toggle the alert LED
        if (alert_active) {
            gpio_set_value(gpio_dir, ALERT_GPIO, GPIO_HIGH);
        } else {
            gpio_set_value(gpio_dir, ALERT_GPIO, GPIO_LOW);
        }
    }

    return NULL;
}

// Initialize I2C
void initialize_i2c() {
    int fd;
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        return;
    }

    i2c_fd = fd;
}

// Initialize GPIO
void initialize_gpio() {
    gpio_dir = gpiod_get_direction(ALERT_GPIO);
    if (gpio_dir == GPIOD_DIR_NONE) {
        fprintf(stderr, "Failed to get direction for GPIO %d: %s\n", ALERT_GPIO, gpiod_get_name(ALERT_GPIO));
        return;
    }

    gpio_cdev = gpiod_get_cdev(ALERT_GPIO);
    if (gpio_cdev == NULL) {
        fprintf(stderr, "Failed to get GPIO device for %d: %s\n", ALERT_GPIO, gpiod_get_name(ALERT_GPIO));
        return;
    }

    gpio_set_direction(gpio_cdev, gpio_dir);
}

// Cleanup resources
void cleanup_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    gpiod_cdev_unreference(gpio_cdev);
    gpiod_free(gpio_dir);
}

// Handle errors and re-initialize if possible
void handle_error(const char *operation, const char *error) {
    fprintf(stderr, "Error during %s: %s\n", operation, error);
    if (errno == ENXIO) {
        initialize_i2c(); // Attempt to re-initialize I2C
    } else if (errno == ENODEV) {
        initialize_gpio(); // Attempt to re-initialize GPIO
    }
}

