#define GPIO_HEATER 18
#define PWM_FREQ 1000
#define REFERENCE_RESISTOR 430
#define PT100_NOMINAL_RESISTANCE 100
#define MAX31865_MODE 1
#define MAX31865_SPI_SPEED 500000

// PID constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Default configuration
const char *default_config_str = "{\"target\":25,\"Kp\":1.0,\"Ki\":0.1,\"Kd\":0.01}";

// Structure for MAX31865 configuration
struct max31865_config {
    uint32_t spi_speed;
    uint8_t mode;
};

// Function prototypes
void pid_control(void);
void setup_spi_and_max31865(void);
void setup_pwm(void);
void read_temperature(void);
void handle_signal(int signum);
int parse_json_config(const char *config_str, struct max31865_config *cfg, float *target_temp);
void apply_config(struct max31865_config *cfg, float *target_temp);
void heater_failsafe(void);
void cleanup_resources(void);
int main(int argc, char **argv) {
    // Initialize gpiod
    if (gpiod_open(GPIOD_DIR) < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Setup SPI and MAX31865
    setup_spi_and_max31865();

    // Setup PWM
    setup_pwm();

    // Read initial temperature
    read_temperature();

    // Parse configuration
    struct max31865_config cfg;
    float target_temp = 25.0;
    if (parse_json_config(default_config_str, &cfg, &target_temp) != 0) {
        printf("Failed to parse JSON configuration.\n");
        return 1;
    }

    // Apply configuration
    apply_config(&cfg, &target_temp);

    // Main PID loop
    while (1) {
        pid_control();
        usleep(100000); // 100 ms delay
    }

    // Clean up on SIGINT/SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Failsafe on exit
    heater_failsafe();

    // Clean up resources
    cleanup_resources();

    return 0;
}

// PID control function
void pid_control(void) {
    float error = target_temp - read_temperature();
    float output = Kp * error + Ki * (error - previous_error) + Kd * (error - last_error);
    previous_error = error;
    last_error = error;

    // Ensure output is within valid PWM range
    output = fminf(fmaxf(output, 0.0), 1.0);

    // Set PWM duty cycle
    pwm_set_duty(GPIO_HEATER, output * 1000);
}

// Setup SPI and MAX31865
void setup_spi_and_max31865(void) {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return;
    }

    struct spi_ioc_transfer tx[] = {
        SPI_IOC_MESSAGE(1),
        SPI_XFER(TX_MAX31865_COMMAND),
        SPI_XFER(NULL),
    };

    struct spi_ioc_transfer rx[] = {
        SPI_IOC_MESSAGE(1),
        SPI_XFER(RX_MAX31865_DATA),
        SPI_XFER(NULL),
    };

    // Configure SPI
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &MAX31865_SPI_SPEED) < 0) {
        perror("SPI configuration failed");
        close(spi_fd);
        return;
    }

    // Configure MAX31865
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &max31865_config.mode) < 0) {
        perror("MAX31865 mode configuration failed");
        close(spi_fd);
        return;
    }

    // Send command to MAX31865
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), tx) < 0) {
        perror("MAX31865 command failed");
        close(spi_fd);
        return;
    }

    // Read temperature
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), rx) < 0) {
        perror("MAX31865 temperature read failed");
        close(spi_fd);
        return;
    }

    // Close SPI device
    close(spi_fd);
}

// Setup PWM
void setup_pwm(void) {
    int pwm_fd = gpiod_open(GPIO_HEATER, GPIOD_OPEN_MODE_NORMAL);
    if (pwm_fd < 0) {
        perror("gpiod_open for PWM");
        return;
    }

    // Set PWM frequency
    if (gpiod_set_data_direction(pwm_fd, GPIOD_DATA_direction_OUT) < 0) {
        perror("Set PWM direction");
        gpiod_close(pwm_fd);
        return;
    }

    // Set PWM range
    if (gpiod_set_range(pwm_fd, 1000) < 0) {
        perror("Set PWM range");
        gpiod_close(pwm_fd);
        return;
    }

    gpiod_close(pwm_fd);
}

// Read temperature from MAX31865
void read_temperature(void) {
    struct spi_ioc_transfer tx[] = {
        SPI_XFER(TX_MAX31865_COMMAND),
        SPI_XFER(NULL),
    };

    struct spi_ioc_transfer rx[] = {
        SPI_XFER(RX_MAX31865_DATA),
        SPI_XFER(NULL),
    };

    // Send command to MAX31865
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), tx) < 0) {
        perror("MAX31865 temperature read command failed");
        return;
    }

    // Read temperature data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), rx) < 0) {
        perror("MAX31865 temperature read data failed");
        return;
    }

    uint16_t raw_temp = rx[0].rx_buf[0] << 8 | rx[0].rx_buf[1];
    float temp_celsius = (raw_temp - MAX31865_OFFSET) * (1.0 / (REFERENCE_RESISTOR / PT100_NOMINAL_RESISTANCE));
    printf("Temperature: %.1f C\n", temp_celsius);
}

// Handle signals
void handle_signal(int signum) {
    // Turn off the heater
    pwm_set_duty(GPIO_HEATER, 0);

    // Close SPI and release resources
    close(spi_fd);

    // Terminate the driver
    gpiod_stop(GPIOD_DIR);

    // Exit cleanly
    exit(0);
}

// Parse JSON configuration
int parse_json_config(const char *config_str, struct max31865_config *cfg, float *target_temp) {
    json_error_t error;
    json_object *root = json_loads(config_str, 0, &error);

    if (error != JSON_ERROR_NONE) {
        fprintf(stderr, "Failed to parse JSON: %s\n", json_error_msg(&error));
        return 1;
    }

    if (!json_object_get_boolean(root, "mode", cfg->mode)) {
        cfg->mode = MAX31865_MODE;
    }

    if (!json_object_get_int(root, "spi_speed", &cfg->spi_speed)) {
        cfg->spi_speed = MAX31865_SPI_SPEED;
    }

    if (!json_object_get_int(root, "target", target_temp)) {
        *target_temp = 25.0;
    }

    return 0;
}

// Apply configuration
void apply_config(struct max31865_config *cfg, float *target_temp) {
    // Set target temperature
    *target_temp = cfg->target;

    // Configure PID constants
    Kp = cfg->Kp;
    Ki = cfg->Ki;
    Kd = cfg->Kd;
}

// Failsafe to turn off heater and exit
void heater_failsafe(void) {
    // Turn off the heater
    pwm_set_duty(GPIO_HEATER, 0);

    // Log error and exit
    fprintf(stderr, "Heater failsafe: Temperature exceeded 80°C, SPI read failed, or MAX31865 fault detected.\n");
    exit(1);
}

// Cleanup resources
void cleanup_resources(void) {
    // Close SPI device
    close(spi_fd);

    // Stop PWM
    gpiod_stop(GPIOD_DIR);
}

// Entry point of the program
int main(int argc, char **argv) {
    // ... (Main logic as described above)

    return 0;
}
