            uint16_t ac3 = bmp180_calib[6];

            uint16_t temp = (x1 << 11) / (ac1 + (ac2 * (x1 >> 12)));
            uint16_t pressure = ((x2 * 3038) + b3) / (b4 + (b5 * (x2 >> 11)));

            // Check for breach conditions
            if (temp > 30 || pressure < 950) {
                write_to_breach_log(timestamp_str, &now);
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(i2c_fd);
    gpiod_exit();

    return EXIT_SUCCESS;
}

