#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>
#include <stdint.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CALIB 0x1C
#define BMP180_REG_T 0x2E
#define BMP180_REG_P 0x2F
#define BMP180_SAMPLING_DELAY 2

#define BUFFER_SIZE 60
#define THRESHOLD_TEMPERATURE 30

volatile uint32_t timer_expired = 0;

struct bmp180_reading {
    uint32_t timestamp;
    float temperature;
    float pressure;
};

static struct bmp180_reading buffer[BUFFER_SIZE];

static void bmp180_init(void) {
    int i2c_dev;
    struct i2c_msg msg[2];

    // Open I2C device
    i2c_dev = i2c_open(1, I2C_FLAG_NONE);
    if (i2c_dev < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    // Send calibration request
    msg[0].addr = BMP180_ADDR;
    msg[0].len = 1;
    msg[0].buf = (uint8_t *) &BMP180_REG_CALIB;
    msg[1].addr = BMP180_ADDR;
    msg[1].len = 11;
    msg[1].buf = (uint8_t *) NULL; // Buffer for response

    if (i2c_transfer(i2c_dev, msg, 2) != 2) {
        perror("BMP180 calibration read failed");
        i2c_close(i2c_dev);
        exit(EXIT_FAILURE);
    }

    // Initialize BMP180
    if (bmp180_init_read_temp_and_pressure(BMP180_ADDR) != BMP180_OK) {
        perror("BMP180 initialization failed");
        i2c_close(i2c_dev);
        exit(EXIT_FAILURE);
    }
}

static void bmp180_read(float *temperature, float *pressure) {
    struct bmp180_data data;

    // Read temperature
    if (bmp180_read_temperature(BMP180_ADDR, &data) != BMP180_OK) {
        fprintf(stderr, "Failed to read temperature.\n");
        return;
    }
    *temperature = data.temperature;

    // Read pressure
    if (bmp180_read_pressure(BMP180_ADDR, &data) != BMP180_OK) {
        fprintf(stderr, "Failed to read pressure.\n");
        return;
    }
    *pressure = data.pressure;
}

static void timer_callback(void *arg) {
    struct timespec now;
    uint32_t timestamp;

    clock_gettime(CLOCK_REALTIME, &now);
    timestamp = now.tv_sec * 1000000 + now.tv_nsec;

    if (!timer_expired) {
        // Only perform the first reading after initialization
        buffer[buffer_head++] = (struct bmp180_reading) {
            .timestamp = timestamp,
            .temperature = 0.0f,
            .pressure = 0.0f
        };
        buffer_head %= BUFFER_SIZE;
    } else {
        bmp180_read(&buffer[buffer_head].temperature, &buffer[buffer_head].pressure);
        buffer_head++;
        if (buffer_head == BUFFER_SIZE) {
            buffer_head = 0; // Circular buffer
        }
    }

    printf("Temperature: %.1f°C, Pressure: %.1f hPa\n", buffer[buffer_head].temperature, buffer[buffer_head].pressure);
    timer_expired = 1;

    // Check temperature and control fan
    if (buffer[buffer_head].temperature > THRESHOLD_TEMPERATURE) {
        gpiod_set_data_direction(GPIO18, GPIODIRECTION_OUT_HIGH);
        gpiod_write(GPIO18, 1); // Turn fan on
    } else {
        gpiod_set_data_direction(GPIO18, GPIODIRECTION_OUT_LOW);
        gpiod_write(GPIO18, 0); // Turn fan off
    }
}

static void cleanup_resources(void) {
    // Turn off the fan
    gpiod_set_data_direction(GPIO18, GPIODIRECTION_OUT_LOW);
    gpiod_write(GPIO18, 0);

    // Close I2C device
    i2c_close(i2c_dev);
}

// Signal handler for SIGINT and SIGTERM
static void signal_handler(int signum) {
    // Turn off the fan and clean up resources
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    struct timespec timeout;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize BMP180
    bmp180_init();

    // Set up timer
    timer_create(CLOCK_REALTIME, NULL, &timer_expired);
    timer_settime(timer_expired, 0, (struct itimerspec) { .it_interval = {0, 500000}, .it_value = {0, 5000000} }, NULL);

    // Main loop
    while (1) {
        // Wait for timer or signal
        timeout.tv_sec = 0;
        timeout.tv_nsec = 100000000; // 100ms timeout
        if (nanosleep(&timeout, NULL) == -1 && errno == EINTR) {
            continue; // Restart interrupted sleep
        } else if (errno != 0) {
            perror("nanosleep");
            break; // Exit on error
        }

        // Check if it's time to clean up
        if (timer_expired) {
            timer_expired = 0;
            // Handle SIGINT/SIGTERM here
        }
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

