#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <stdint.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_DEBOUNCE_MS 200
#define BMP180_SAMPLING_DELAY_MS 2000

// Function prototypes
void setup_gpios();
void setup_bmp180();
void read_bmp180();
void apply_bosch_compensation(uint16_t temperature, uint16_t pressure_raw);
void toggle_logging(bool enable);
void write_to_log_file(const char *timestamp, double pressure);
void handle_interrupt(int edge, void *data);
void cleanup();

// Global variables
int bmp180_fd;
struct gpiod_dir gpio_dir;
struct gpiod_cbs gpio_cbs;
bool logging_enabled = false;

// Function to setup GPIO
void setup_gpios() {
    int gpio27 = gpiod_get_index_by_name("GPIO27");
    if (gpio27 < 0) {
        fprintf(stderr, "Error: Could not find GPIO27\n");
        exit(EXIT_FAILURE);
    }

    gpio_set_direction(gpio27, GPIO_OUTPUT);
    gpio_set_value(gpio27, 0); // Initial state low

    gpio_cbs.read = handle_interrupt;
    gpio_cbs.write = NULL;
    gpio_cbs.dir = &gpio_dir;

    if (gpiod_cbs_set(gpio27, &gpio_cbs) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO callbacks\n");
        exit(EXIT_FAILURE);
    }
}

// Function to setup BMP180
void setup_bmp180() {
    bmp180_fd = open("/dev/i2c-1", O_RDWR);
    if (bmp180_fd == -1) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg[2];
    msg[0].addr = BMP180_I2C_ADDR;
    msg[0].len = sizeof(uint8_t); // Request device ID
    msg[1].addr = BMP180_I2C_ADDR;
    msg[1].len = 7; // Request register address

    if (i2c_smbus_read_i2c_data(bmp180_fd, &msg[0]) != 7 ||
        i2c_smbus_read_i2c_data(bmp180_fd, &msg[1]) != 0x77) {
        fprintf(stderr, "Error: BMP180 not found or incorrect address\n");
        close(bmp180_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize BMP180
    uint8_t config = 0;
    config |= 0x08; // Set measurement mode to 0x08 (temperature and pressure)
    if (i2c_smbus_write_i2c_data(bmp180_fd, &config, 1) != 1) {
        fprintf(stderr, "Error: Failed to configure BMP180\n");
        close(bmp180_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read BMP180
void read_bmp180() {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(bmp180_fd, BMP180_I2C_ADDR, 0x00, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read BMP180 data\n");
        close(bmp180_fd);
        exit(EXIT_FAILURE);
    }

    uint16_t temperature;
    uint16_t pressure_raw = data[0] | (data[1] << 8);

    // Apply Bosch temperature compensation
    temperature = apply_bosch_compensation(temperature, pressure_raw);

    // Apply Bosch pressure compensation
    pressure_raw = apply_bosch_compensation(temperature, pressure_raw);

    // Log data if logging is enabled
    if (logging_enabled) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        double pressure_in_pascals = pressure_raw / 100.0; // Convert to Pascals

        write_to_log_file(timestamp, pressure_in_pascals);
    }
}

// Function to apply Bosch temperature compensation
uint16_t apply_bosch_compensation(uint16_t temperature, uint16_t pressure_raw) {
    // Bosch temperature compensation formula
    uint16_t temperature_compensated = (pressure_raw * 3038) / (temperature + 258.8);
    return temperature_compensated;
}

// Function to toggle logging
void toggle_logging(bool enable) {
    logging_enabled = enable;
    if (enable) {
        // Set GPIO27 to high for falling edge detection
        gpio_set_value(gpio27, 1);
    } else {
        // Set GPIO27 to low
        gpio_set_value(gpio27, 0);
    }
}

// Function to write to log file
void write_to_log_file(const char *timestamp, double pressure) {
    FILE *log_file = fopen("pressure_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Could not open pressure_log.txt for writing\n");
        return;
    }

    fprintf(log_file, "%s, %f\n", timestamp, pressure);
    fclose(log_file);
}

// Interrupt handler for GPIO27 falling edge
void handle_interrupt(int edge, void *data) {
    if (edge == GPIOD_EDGE_FALLING) {
        toggle_logging(!logging_enabled);
    }
}

// Function to cleanup resources
void cleanup() {
    if (bmp180_fd != -1) {
        close(bmp180_fd);
    }

    gpiod_cbs_free(&gpio_cbs);
    gpiod_remove(gpio27);
}

// Signal handlers
void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    setup_gpios();
    setup_bmp180();

    while (1) {
        read_bmp180();
        usleep(BMP180_SAMPLING_DELAY_MS * 1000);
    }

    return 0;
}

