volatile sig_atomic_t should_exit = 0;

// GPIO configuration for Raspberry Pi Zero W
#define GPIO_RGB_RED 17
#define GPIO_RGB_GREEN 18
#define GPIO_RGB_BLUE 27

// Function prototypes
void setup_gpios();
void cleanup_gpios();
void handle_signal(int signum);

int main() {
    // Initialize GPIO
    setup_gpios();

    // Signal handler registration
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Signal handler registration failed");
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Poll CPU temperature
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (temp_file == NULL) {
            perror("Failed to open temperature file");
            continue; // Skip this update cycle
        }

        // Read temperature
        long temp_c;
        if (fread(&temp_c, sizeof(long), 1, temp_file) != 1 || ferror(temp_file)) {
            fprintf(stderr, "Error reading temperature file\n");
            fclose(temp_file);
            continue; // Skip this update cycle
        }

        // Convert temperature to millidegrees Celsius
        int temp_mdeg = (temp_c * 1000) / 1000; // No conversion needed here

        // Set PWM values based on temperature
        int red_pwm = (temp_mdeg >= 60000) ? 255 : 0;
        int green_pwm = (temp_mdeg >= 40000 && temp_mdeg < 60000) ? 255 : 0;
        int blue_pwm = (temp_mdeg < 40000) ? 255 : 0;

        // Call GPIO API with inverted duty (255 turns off)
        if (gpiod_set_data_direction(GPIO_RGB_RED) < 0 ||
            gpiod_set_data_direction(GPIO_RGB_GREEN) < 0 ||
            gpiod_set_data_direction(GPIO_RGB_BLUE) < 0) {
            perror("Failed to set data direction");
            fclose(temp_file);
            continue; // Skip this update cycle
        }

        if (gpiod_set_value(GPIO_RGB_RED, 255 - red_pwm) < 0 ||
            gpiod_set_value(GPIO_RGB_GREEN, 255 - green_pwm) < 0 ||
            gpiod_set_value(GPIO_RGB_BLUE, 255 - blue_pwm) < 0) {
            perror("Failed to set PWM values");
            fclose(temp_file);
            continue; // Skip this update cycle
        }

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red PWM: %d, Green PWM: %d, Blue PWM: %d\n",
               temp_mdeg, red_pwm, green_pwm, blue_pwm);

        // Close the temperature file
        fclose(temp_file);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up GPIO
    cleanup_gpios();

    // Set should_exit flag to exit the loop
    should_exit = 1;

    // Wait for the main loop to exit gracefully
    while (!should_exit) {}

    return EXIT_SUCCESS;
}

// Function to setup GPIO
void setup_gpios() {
    int red_pwm, green_pwm, blue_pwm;
    gpiod_set_mode(GPIO_RGB_RED, GPIOD_MODE_OUT);
    gpiod_set_mode(GPIO_RGB_GREEN, GPIOD_MODE_OUT);
    gpiod_set_mode(GPIO_RGB_BLUE, GPIOD_MODE_OUT);

    // Set initial PWM values to 0 (off)
    gpiod_set_value(GPIO_RGB_RED, 0);
    gpiod_set_value(GPIO_RGB_GREEN, 0);
    gpiod_set_value(GPIO_RGB_BLUE, 0);
}

// Function to cleanup GPIO
void cleanup_gpios() {
    gpiod_stop(GPIO_RGB_RED);
    gpiod_stop(GPIO_RGB_GREEN);
    gpiod_stop(GPIO_RGB_BLUE);

    gpiod_remove(GPIO_RGB_RED);
    gpiod_remove(GPIO_RGB_GREEN);
    gpiod_remove(GPIO_RGB_BLUE);
}

// Signal handler to gracefully exit
void handle_signal(int signum) {
    should_exit = 1;
}

