#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <curl/curl.h>
#include <gpiod.h>
#include <stdint.h>

#define DHT22_GPIO 4 // BCM 7, physical pin 7
#define DHT22_START_SIGNAL_MS 1
#define DHT22_READ_TIMEOUT_MS 20000

// Constants for DHT22 communication
#define DHT22_DATA_PIN 4
#define DHT22_CHECKSUM_BIT 8

// GPIO descriptor for DHT22
struct gpiod_cdev *dht22_cdev;

// Function prototypes
void setup_dht22();
void read_dht22_data(uint8_t *data);
void validate_dht22_checksum(uint8_t *data);
void send_dht_data_to_server(const uint8_t *data);
void handle_signal(int signum);

int main() {
    // Initialize GPIO
    if (gpiod_cdev_init(DHT22_DATA_PIN, GPIOD_OUT_LOW | GPIOD_IN PullDefault) < 0) {
        perror("gpiod_cdev_init failed");
        return EXIT_FAILURE;
    }
    dht22_cdev = gpiod_cdev_get(DHT22_DATA_PIN);

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        uint8_t data[40];
        int attempts = 0;

        // Attempt to read DHT22 data
        for (attempts = 0; attempts < 3; ++attempts) {
            // Pull GPIO low for start signal
            gpiod_set_value(dht22_cdev, GPIOD_OUT_LOW);
            usleep(DHT22_START_SIGNAL_MS * 1000);

            // Read data
            read_dht22_data(data);
            validate_dht22_checksum(data);

            // Send data to server
            send_dht_data_to_server(data);

            // Reset GPIO to default
            gpiod_set_value(dht22_cdev, GPIOD_OUT_INACTIVE);
            break;
        }

        // Handle errors and cleanup
        if (attempts == 3) {
            fprintf(stderr, "Failed to read DHT22 data after 3 attempts.\n");
            break;
        }

        // Clean up resources
        gpiod_cdev_put(dht22_cdev);
    }

    // Clean up
    gpiod_cdev_destroy(dht22_cdev);

    return EXIT_SUCCESS;
}

// Function to setup DHT22 GPIO
void setup_dht22() {
    // Ensure GPIO is initialized as input
    gpiod_set_direction(dht22_cdev, GPIOD_IN);
}

// Function to read DHT22 data
void read_dht22_data(uint8_t *data) {
    // Pull GPIO low to start communication
    gpiod_set_value(dht22_cdev, GPIOD_OUT_LOW);
    usleep(DHT22_START_SIGNAL_MS * 1000);

    // Wait for the response
    uint32_t timeout = DHT22_READ_TIMEOUT_MS * 1000;
    struct timespec ts = { .tv_sec = timeout / 1000, .tv_nsec = (timeout % 1000) * 1000000 };
    nanosleep(&ts, NULL);

    // Read the data
    uint8_t value = gpiod_get_value(dht22_cdev);
    memcpy(data, &value, 1);

    // Read remaining 39 bits
    for (int i = 1; i < 40; ++i) {
        value = gpiod_get_value(dht22_cdev);
        memcpy(&data[i - 1], &value, 1);
    }
}

// Function to validate DHT22 checksum
void validate_dht22_checksum(uint8_t *data) {
    uint8_t checksum = (data[DHT22_CHECKSUM_BIT - 1] << 7) | data[DHT22_CHECKSUM_BIT];
    if (checksum != (data[0] ^ data[1] ^ data[2] ^ data[3] ^ data[4] ^ data[5] ^ data[6] ^ data[7])) {
        fprintf(stderr, "Checksum mismatch, data invalid.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to send DHT data to server
void send_dht_data_to_server(const uint8_t *data) {
    CURL *curl;
    CURLcode res;

    // Initialize cURL
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Create cURL session
    curl = curl_easy_init();
    if (curl) {
        // Set URL
        char url[] = "http://yourserver.com/api/humidity";
        curl_easy_setopt(curl, CURLOPT_URL, url);

        // Perform the request
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "cURL request failed: %s\n", curl_easy_strerror(res));
            exit(EXIT_FAILURE);
        }

        // Release cURL resources
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize cURL.\n");
        exit(EXIT_FAILURE);
    }
}

// Signal handler to ensure clean exit
void handle_signal(int signum) {
    // Clean up resources
    if (dht22_cdev) {
        gpiod_cdev_put(dht22_cdev);
        dht22_cdev = NULL;
    }

    // Exit the program
    exit(EXIT_FAILURE);
}

