        data[i] = gpiod_get_value(gpiod_dev, gpio_num);
    }

    // Calculate checksum
    uint8_t checksum = 0;
    for (int i = 0; i < DHT22_CHECKSUM_BIT_COUNT; i++) {
        checksum ^= data[i];
    }

    // Check if checksum matches the last byte of the data
    if (data[DHT22_CHECKSUM_BIT_COUNT - 1] != (uint8_t)checksum) {
        return 0; // Invalid checksum
