                        res = curl_easy_perform(curl_instance);
                        if (res == CURLE_OK) {
                            break;
                        }
                    }
                    if (res != CURLE_OK) {
                        fprintf(stderr, "Failed to post data after retries.\n");
                        continue;
                    }
                } else {
                    // Check HTTP response status
                    if (curl_easy_getinfo(curl_instance, CURLINFO_HTTP_CODE) / 100 != 2) {
                        fprintf(stderr, "HTTP error: %d\n", curl_easy_getinfo(curl_instance, CURLINFO_HTTP_CODE));
                        continue;
                    }
                }

                // Successful POST
                fprintf(stderr, "Humidity posted successfully.\n");
            } else {
                fprintf(stderr, "Failed to initialize curl.\n");
            }

            // Graceful shutdown on SIGINT/SIGTERM
            signal_handler();
        } else {
            // Sensor not found or checksum error
            fprintf(stderr, "Failed to read DHT22 data.\n");
            // Retry up to three times with 2-second backoff
            for (int i = 0; i < 3; i++) {
                sleep(2);
                if (read_dht22(gpiod_dev, DHT22_GPIO)) {
                    // Successful read after retry
                    break;
                }
            }
            if (i == 3) {
                fprintf(stderr, "Failed to read DHT22 data after retries.\n");
                continue;
            }
        }

        // Sleep for 10 seconds
        sleep(10);
    }

    // Clean up libcurl
    curl_easy_cleanup(curl_instance);

    // Graceful shutdown on SIGINT/SIGTERM
    signal_handler();

    // Close libgpiod device
    gpiod_cdev_put(gpiod_dev);

    return EXIT_SUCCESS;
}

// Signal handler function
void signal_handler(int signum) {
    // Log the signal received
    syslog(LOG_INFO, "Signal %d received. Shutting down gracefully...", signum);

    // Perform graceful shutdown
    curl_global_cleanup();
    exit(0);
}

