void initializeResources();
void readTemperatureAndFanState();
void applySpeedMapAndWriteState();
void logFanStateChange();
void handleShutdownSignal(int signum);
void cleanupResources();

int main() {
    // Initialize resources
    initializeResources();

    // Main loop
    while (1) {
        readTemperatureAndFanState();
        applySpeedMapAndWriteState();
        sleep(5); // Poll every 5 seconds
    }

    // Clean up on exit
    handleShutdownSignal(SIGINT);
    cleanupResources();

    return 0;
}

// Function: initializeResources
void initializeResources() {
    // Open the log file for appending
    FILE *logFile = fopen(LOG_FILE_PATH, "a+");
    if (logFile == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Open the thermal zone temperature file
    int tempFd = open(TEMP_FILE, O_RDONLY);
    if (tempFd == -1) {
        perror("Failed to open temperature file");
        fclose(logFile);
        exit(EXIT_FAILURE);
    }

    // Open the cooling device file
    int deviceFd = open(COOLING_DEVICE, O_RDONLY);
    if (deviceFd == -1) {
        perror("Failed to open cooling device file");
        close(tempFd);
        fclose(logFile);
        exit(EXIT_FAILURE);
    }

    // Validate max_state of the cooling device
    struct thermal_cooling_device cooling_device;
    if (ioctl(deviceFd, THERMAL_IOCTL_GET_DEVICE, &cooling_device) < 0) {
        perror("Failed to get cooling device info");
        close(tempFd);
        fclose(logFile);
        exit(EXIT_FAILURE);
    }
    if (cooling_device.max_state < 1) {
        fprintf(logFile, "Cooling device does not support fan speed control\n");
        close(tempFd);
        fclose(logFile);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO for fan control (assuming GPIO 18 for example)
    gpiod_set_data_direction(GPIO_NUM_18, GPIO_DIR_OUT);
    gpiod_write(GPIO_NUM_18, 0); // Set fan to off initially

    // Keep file descriptors open for subsequent use
    FD_SET(tempFd, &tempFdSet);
    FD_SET(deviceFd, &deviceFdSet);
}

// Function: readTemperatureAndFanState
void readTemperatureAndFanState() {
    // Read temperature
    char tempBuffer[10];
    if (fgets(tempBuffer, sizeof(tempBuffer), tempFd) == NULL) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }
    int temperature = atoi(tempBuffer);
    if (temperature < 0) {
        fprintf(stderr, "Invalid temperature reading\n");
        return;
    }

    // Read fan state
    char stateBuffer[10];
    if (fgets(stateBuffer, sizeof(stateBuffer), deviceFd) == NULL) {
        fprintf(stderr, "Failed to read fan state\n");
        return;
    }
    int fanState = atoi(stateBuffer);
    if (fanState < 0) {
        fprintf(stderr, "Invalid fan state reading\n");
        return;
    }
}

// Function: applySpeedMapAndWriteState
void applySpeedMapAndWriteState() {
    int currentFanState = gpiod_get_value(GPIO_NUM_18);
    int newFanState = applySpeedMap(temperature);

    // Only write if the state has changed
    if (newFanState != currentFanState) {
        gpiod_write(GPIO_NUM_18, newFanState);
        logFanStateChange(temperature, newFanState);
    }
}

// Function: logFanStateChange
void logFanStateChange(int temperature, int newFanState) {
    time_t now = time(NULL);
    struct tm timeinfo;
    char logMessage[100];

    // Format the log message
    strftime(logMessage, sizeof(logMessage), "%Y-%m-%d %H:%M:%S ", &timeinfo);
    sprintf(logMessage + strlen(logMessage), "Temperature: %dC, Fan State: %d", temperature, newFanState);

    // Write to log file
    if (fwrite(logMessage, sizeof(logMessage), 1, logFile) != 1) {
        perror("Failed to write to log file");
    }
}

// Function: handleShutdownSignal
void handleShutdownSignal(int signum) {
    gpiod_write(GPIO_NUM_18, 0); // Set fan to off
    fprintf(logFile, "Shutdown signal received, setting fan to off\n");
}

// Function: cleanupResources
void cleanupResources() {
    // Close files and GPIO
    close(tempFd);
    close(deviceFd);
    gpiod_set_data_direction(GPIO_NUM_18, GPIO_DATA_DIR_NONE);
    gpiod_cleanup(GPIO_NUM_18);

    // Close log file
    fclose(logFile);
}

// Function: applySpeedMap
int applySpeedMap(int temperature) {
    if (temperature < 45) {
        return 0; // Fan off
    } else if (temperature < 55) {
        return 1; // Fan low speed
    } else if (temperature < 65) {
        return 2; // Fan medium speed
    } else {
        return 3; // Fan high speed
    }
}

