#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/pwm.h>
#include <linux/spi/spidev.h>

#define MAX31855_DEVICE "/dev/spidev0.0"
#define HEATER_GPIO 18
#define PWM_FREQ_HZ 1000
#define PWM_MIN_DUTY 0
#define PWM_MAX_DUTY 100

#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

#define SPI_CLK_GPIO 11
#define SPI_CS_GPIO 8
#define SPI_DO_GPIO 9

#define MAX31855_FFT 4
#define MAX31855_THRESHOLD 100
#define MAX31855_MIN_TEMPERATURE 0

volatile uint32_t pid_output = 0;
uint32_t pwm_duty = 0;
int heater_enabled = 1;

void pid_controller(float current_temp, float target_temp) {
    float error = target_temp - current_temp;
    pid_output = Kp * error + Ki * (error - pid_output) + Kd * (error - previous_error);
    previous_error = error;
}

void setup_pwm() {
    struct pwm_desc *pwm;
    pwm = pwm_lookup(PWM_FREQ_HZ, HEATER_GPIO);
    if (!pwm) {
        fprintf(stderr, "Error: PWM not found for GPIO %u\n", HEATER_GPIO);
        exit(EXIT_FAILURE);
    }
    pwm_set_mode(pwm, PWM_MODE_DUTYCYCLE);
    pwm_set_range(pwm, PWM_MIN_DUTY, PWM_MAX_DUTY);
    pwm_enable(pwm);
}

void setup_spi() {
    int spi_fd;
    struct spi_device *spi;
    spi_fd = open(MAX31855_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Error: Could not open SPI device %s\n", MAX31855_DEVICE);
        exit(EXIT_FAILURE);
    }

    spi = spidev_open(spi_fd, SPI_MODE_0);
    if (spi == NULL) {
        fprintf(stderr, "Error: Could not open SPI device %s\n", MAX31855_DEVICE);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up SPI parameters
    spidev_set_mode(spi, SPI_MODE_0);
    spidev_set_bit_order(spi, MSB_FIRST);
    spidev_set_speed(spi, 500000);

    // Set GPIO pins for SPI
    gpiod_set_data_direction(SPI_CLK_GPIO, GPIOD_DIR_OUT);
    gpiod_set_data_direction(SPI_CS_GPIO, GPIOD_DIR_OUT);
    gpiod_set_data_direction(SPI_DO_GPIO, GPIOD_DIR_IN);

    // Enable GPIO pins
    gpiod_enable_output(SPI_CLK_GPIO);
    gpiod_enable_output(SPI_CS_GPIO);
    gpiod_enable_input(SPI_DO_GPIO);
}

void read_temperature() {
    uint8_t data[MAX31855_FFT];
    int ret;

    ret = spidev_transfer(spi, &data[0], MAX31855_FFT);
    if (ret < 0) {
        fprintf(stderr, "Error reading from MAX31855: %s\n", strerror(errno));
        return;
    }

    // Check MAX31855 fault bits
    uint8_t fault_bits = data[3] & 0x0F;
    if (fault_bits & 0x08) {
        fprintf(stderr, "MAX31855 fault: Short to GND\n");
        heater_enabled = 0;
        return;
    }
    if (fault_bits & 0x10) {
        fprintf(stderr, "MAX31855 fault: Short to VCC\n");
        heater_enabled = 0;
        return;
    }
    if (fault_bits & 0x04) {
        fprintf(stderr, "MAX31855 fault: Open circuit\n");
        heater_enabled = 0;
        return;
    }

    // Convert raw temperature to Celsius
    float temperature_celsius = (data[0] << 8 | data[1]) / 16.0 - 256.0;
    if (temperature_celsius < MAX31855_MIN_TEMPERATURE || temperature_celsius > MAX31855_THRESHOLD) {
        fprintf(stderr, "Temperature out of range: %f°C\n", temperature_celsius);
        heater_enabled = 0;
        return;
    }

    pid_controller(temperature_celsius, 50.0);
    pwm_duty = (pid_output * PWM_MAX_DUTY + PWM_MIN_DUTY) / 100.0;
}

void setup_and_loop() {
    setup_pwm();
    setup_spi();
    while (1) {
        read_temperature();
        // Write to log file
        FILE *log_file = fopen("heater_log.txt", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open log file heater_log.txt\n");
            break;
        }
        fprintf(log_file, "Temperature: %.1f°C, PWM Duty: %u%%, PID Output: %.1f\n",
                temperature_celsius, pwm_duty, pid_output);
        fclose(log_file);
    }

    // Clean up on SIGINT or SIGTERM
    signal(SIGINT, SIG_IGN); // Ignore SIGINT for simplicity
    signal(SIGTERM, sigterm_handler);

    void sigterm_handler(int sig) {
        fprintf(stderr, "Received SIGTERM, shutting down...\n");
        pwm_disable(HEATER_GPIO);
        spidev_close(spi);
        gpiod_cleanup(SPI_CLK_GPIO);
        gpiod_cleanup(SPI_CS_GPIO);
        gpiod_cleanup(SPI_DO_GPIO);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    setup_and_loop();
    return 0;
}

