#include <gpiod.h>

#define GPIO_NUM 18
#define PWM_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70

FILE *fp;
char line[256];
struct gpiod_dir *dir;
struct gpiod_cdev *cdev;
int fd;

void cleanup() {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (cdev != NULL) {
        gpiod_cdev_unlink(cdev);
        cdev = NULL;
    }
    if (fd != -1) {
        close(fd);
        fd = -1;
    }
    if (dir != NULL) {
        gpiod_dir_unlink(dir);
        dir = NULL;
    }
}

int main() {
    // Initialize GPIO
    if ((dir = gpiod_dir_open("/dev/gpiochip0", GPIOD_DIR_RONLY)) == NULL) {
        perror("gpiod_dir_open");
        return EXIT_FAILURE;
    }

    // Open GPIO pin
    if ((cdev = gpiod_cdev_open(dir, GPIO_NUM, GPIOD_CDEV_OPEN_READWRITE)) == NULL) {
        perror("gpiod_cdev_open");
        gpiod_dir_unlink(dir);
        return EXIT_FAILURE;
    }

    // Verify GPIO pin setup
    if (gpiod_cdev_get_data(cdev, GPIO_NUM) != GPIO_NUM) {
        fprintf(stderr, "Error: Incorrect GPIO pin setup\n");
        gpiod_cdev_unlink(cdev);
        gpiod_dir_unlink(dir);
        return EXIT_FAILURE;
    }

    // Initialize PWM output
    if (gpiod_pwm_config(cdev, GPIO_NUM, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to configure PWM frequency\n");
        gpiod_cdev_unlink(cdev);
        gpiod_dir_unlink(dir);
        return EXIT_FAILURE;
    }

    // Open log file for writing
    if ((fp = fopen("cooling_log.csv", "a")) == NULL) {
        perror("fopen");
        cleanup();
