#include <stdbool.h>

#define I2C_BUS_NUM 1
#define SLF3S_ADDR 0x5A
#define MAX_READ_ATTEMPTS 3

// Sensor data and CRC constants
#define DATA_BYTE1 0x00
#define DATA_BYTE2 0x01
#define CRC_BYTE 0x02
#define CRC_CHECKSUM 0x55

// GPIO for interrupt wakeup (optional, depends on your setup)
#define WAKEUP_GPIO 4

// File path for logging
#define LOG_FILE_PATH "flow_log.txt"

// Function prototypes
void setup_i2c(void);
void read_slf3s(uint8_t address, uint8_t* data, int attempts);
bool validate_crc(uint8_t* data, uint8_t crc);
void write_to_log(const char* format, ...);
void handle_signal(int signum);

int main() {
    // Initialize GPIO for wakeup (if used)
    gpiod_set_data_dir(WAKEUP_GPIO, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_direction_output(WAKEUP_GPIO, 1);

    // Setup I2C
    setup_i2c();

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        uint8_t flow1_data[3];
        uint8_t flow2_data[3];

        // Attempt to read from each sensor
        read_slf3s(SLF3S_ADDR, flow1_data, MAX_READ_ATTEMPTS);
        read_slf3S(SLF3S_ADDR, flow2_data, MAX_READ_ATTEMPTS);

        // Check if CRC valid for both sensors
        if (validate_crc(flow1_data, flow1_data[2]) && validate_crc(flow2_data, flow2_data[2])) {
            char timestamp[23];
            time_t rawtime = ts.tv_sec;
            char* time_str = localtime(&rawtime);

            sprintf(timestamp, "%04d-%02d-%02d %02d:%02d:%02d",
                    time_str[0], time_str[1], time_str[2],
                    time_str[3], time_str[4], time_str[5]);

            write_to_log("%s, %hu, %hu", timestamp, flow1_data[0], flow1_data[1]);
            write_to_log("%s, %hu, %hu", timestamp, flow2_data[0], flow2_data[1]);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    int fd;
    struct gpiod_i2c_bus *bus;

    // Open I2C bus
    fd = gpiod_i2c_open(I2C_BUS_NUM);
    if (fd < 0) {
        perror("gpiod_i2c_open");
        exit(EXIT_FAILURE);
    }

    bus = gpiod_i2c_get_bus(fd);
    if (!bus) {
        perror("gpiod_i2c_get_bus");
        exit(EXIT_FAILURE);
    }

    // Enable I2C on the bus
    if (gpiod_i2c_enable(bus) < 0) {
        perror("gpiod_i2c_enable");
        exit(EXIT_FAILURE);
    }

    // Close I2C bus handle
    gpiod_i2c_close(fd);
}

// Function to read from a sensor
void read_slf3s(uint8_t address, uint8_t* data, int attempts) {
    int i;
    for (i = 0; i < attempts; i++) {
        if (gpiod_i2c_read(bus, address, data, sizeof(data)) < 0) {
            // Handle I2C error, retry
            if (i < MAX_READ_ATTEMPTS - 1) {
                // Retry
                continue;
            } else {
                // Failed to read after attempts, log error if needed
                fprintf(stderr, "Failed to read SLF3S sensor after %d attempts\n", attempts);
                return;
            }
        } else {
            // CRC check here before logging
            if (validate_crc(data, data[2])) {
                // Valid reading, log if necessary
                break;
            } else {
                // CRC check failed, retry
                continue;
            }
        }
    }
}

// Function to validate CRC
bool validate_crc(uint8_t* data, uint8_t crc) {
    return (data[2] == crc);
}

// Function to write to log file
void write_to_log(const char* format, ...) {
    char buffer[256];
    va_list args;

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    FILE* log_file = fopen(LOG_FILE_PATH, "a+");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s", buffer);
    fclose(log_file);
}

// Signal handler to perform clean shutdown
void handle_signal(int signum) {
    // Close I2C bus handle (if open)
    if (gpiod_i2c_fd != -1) {
        gpiod_i2c_close(gpiod_i2c_fd);
        gpiod_i2c_fd = -1;
    }

    // Terminate the program
    exit(EXIT_SUCCESS);
}

