#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpiod.h>

#define GPIO_A 17
#define GPIO_B 18

#define PULL_UP 1
#define OPEN_DRAIN 1

// Quadrature state machine constants
#define RESOLUTION 360
#define PULSE_PER_REVOLUTION 4

// GPIO descriptors
struct gpiod_desc gpio_a_desc = {
    .label = "GPIOA",
    .flags = GPIOD_OPEN_DRAIN | GPIOD_PULL_UP,
    .direction = GPIOD_OUT_INIT_LOW,
    .pin = GPIO_A,
};
struct gpiod_desc gpio_b_desc = {
    .label = "GPIOB",
    .flags = GPIOD_OPEN_DRAIN | GPIOD_PULL_UP,
    .direction = GPIOD_OUT_INIT_LOW,
    .pin = GPIO_B,
};

// Quadrature state variables
unsigned int state = 0;
unsigned int last_state = 0;
unsigned int pulses = 0;

// Function prototypes
void setup_gpios(void);
void read_encoder(void);
void handle_position_change(unsigned int new_position);
void cleanup(void);
void signal_handler(int signum);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        read_encoder();
        handle_position_change(pulses / PULSE_PER_REVOLUTION * RESOLUTION);
        // Sleep to avoid excessive CPU usage
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    int ret;

    // Initialize GPIO controller
    ret = gpiod_open(&gpiod_ctx);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO controller: %s\n", gpiod_errstr(gpiod_ctx));
        exit(EXIT_FAILURE);
    }

    // Set up GPIO_A
    ret = gpiod_set_config(gpiod_ctx, &gpio_a_desc);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO_A config: %s\n", gpiod_errstr(gpiod_ctx));
        gpiod_close(&gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO_B
    ret = gpiod_set_config(gpiod_ctx, &gpio_b_desc);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO_B config: %s\n", gpiod_errstr(gpiod_ctx));
        gpiod_close(&gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

// Function to read the encoder
void read_encoder(void) {
    unsigned int a, b;

    // Read GPIO_A and GPIO_B
    ret = gpiod_read(gpiod_ctx, GPIO_A, &a);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO_A: %s\n", gpiod_errstr(gpiod_ctx));
        return;
    }

    ret = gpiod_read(gpiod_ctx, GPIO_B, &b);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO_B: %s\n", gpiod_errstr(gpiod_ctx));
        return;
    }

    // Update state based on quadrature encoding
    if (a != last_a && b != last_b) {
        last_state = a;
        last_b = b;

        // Determine direction and count a pulse
        if (a != b) {
            pulses++;
            state = (state << 1) | (a > b ? 1 : 0);
        } else {
            // Ignore when both are the same (no movement)
            state = last_state;
        }
    }

    // Update last values
    last_a = a;
    last_b = b;
}

// Function to handle position change
void handle_position_change(unsigned int new_position) {
    time_t now;
    struct tm timeinfo;
    FILE *file = fopen("encoder_log.txt", "a+");
    if (!file) {
        fprintf(stderr, "Error opening encoder_log.txt for writing: %s\n", strerror(errno));
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Get current time
    time(&now);
    localtime_r(&now, &timeinfo);

    // Format and write timestamped position to file
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    fprintf(file, "%s: Position: %u degrees\n", timestamp, new_position);

    fclose(file);
}

// Function to clean up resources
void cleanup(void) {
    // Close GPIO context
    gpiod_close(&gpiod_ctx);

    // Close file
    fclose(file);
}

// Signal handler function
void signal_handler(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

