#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>
#include <signal.h>

#define GPIO_NUM 18
#define PULSE_PER_REVOLUTION 1
#define PULL_DOWN 1

// Mutex for thread synchronization
pthread_mutex_t pulse_count_mutex = PTHREAD_MUTEX_INITIALIZER;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_stop();
        fclose(log_file);
        pthread_mutex_destroy(&pulse_count_mutex);
        printf("Graceful shutdown initiated.\n");
    }
}

int main() {
    // Initialize GPIO
    int ret = gpiod_init();
    if (ret != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_errstr(ret));
        return EXIT_FAILURE;
    }

    // Open log file for appending and flushing
    FILE *log_file = fopen("rpm_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_stop();
        return EXIT_FAILURE;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize variables
    long pulse_count = 0;
    time_t current_time;
    double rpm = 0.0;

    // Main loop
    while (1) {
        // Wait for a second
        current_time = time(NULL);
        while (time(NULL) - current_time < 1) {
            usleep(1000);
        }

        // Start counting pulses
        pthread_mutex_lock(&pulse_count_mutex);
        pulse_count = 0;
        gpiod_set_data_direction(GPIO_NUM, GPIOD_DIR_IN);
        gpiod_set_pull_mode(GPIO_NUM, PULL_DOWN);
        gpiod_enable_interrupt(GPIO_NUM);

        // Wait for a rising edge on GPIO18
        while (!gpiod_get_value(GPIO_NUM)) {
            // No pulse detected within the second, log 0.00 RPM
            if (pulse_count == 0) {
                fprintf(log_file, "Timestamp: %s, RPM: 0.00\n", ctime(&current_time));
            }
            usleep(1000);
        }

        pulse_count++;
        // End counting pulses
        gpiod_disable_interrupt(GPIO_NUM);
        gpiod_set_data_direction(GPIO_NUM, GPIOD_DIR_IN);
        gpiod_set_pull_mode(GPIO_NUM, PULL_DOWN);

        // Calculate RPM
        rpm = (double)pulse_count * PULSE_PER_REVOLUTION / 60;

        // Log the RPM
        fprintf(log_file, "Timestamp: %s, RPM: %.2f\n", ctime(&current_time), rpm);

        // Release mutex
        pthread_mutex_unlock(&pulse_count_mutex);
    }

    // Clean up
    fclose(log_file);
    gpiod_stop();

    return EXIT_SUCCESS;
}

