#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <stdint.h>
#include <ctype.h>

#define I2C_BUS_PATH "/dev/i2c-1"
#define SENSOR_ADDR 0x55
#define THRESHOLD_INFRARED 2000
#define LED_GPIO 17

// Constants for I2C communication
#define I2C_SLAVE_ADDRSIZE 1
#define I2C_SLAVE 0x7F

// GPIO definitions
#define GPIO_SET 0x20200040
#define GPIO_CLR 0x20200048
#define GPIO_DIR 0x2020004C

// Function prototypes
void i2c_init();
void i2c_write(uint8_t address, uint8_t data);
void i2c_read(uint8_t address, uint8_t *data, size_t len);
void gpio_init();
void gpio_set(int gpio);
void gpio_clear(int gpio);
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize GPIO and I2C
    gpio_init();
    i2c_init();

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Sample the sensor
        uint8_t infrared_reading;
        i2c_write(SENSOR_ADDR, 0x00); // Start communication
        i2c_write(SENSOR_ADDR, 0x01); // Request reading
        i2c_read(SENSOR_ADDR, 0x00, &infrared_reading, 1); // Read result

        // Check if infrared reading exceeds threshold
        if (infrared_reading > THRESHOLD_INFRARED) {
            gpio_set(LED_GPIO); // Turn on LED
        } else {
            gpio_clear(LED_GPIO); // Turn off LED
        }

        // Log the reading to a CSV file
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "%s,%d\n", timestamp, infrared_reading);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize GPIO
void gpio_init() {
    int fd;
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd == -1) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 as output
    gpio_set(GPIO_DIR, LED_GPIO);
    gpio_set(GPIO_SET, LED_GPIO);

    // Close GPIO file descriptor
    close(fd);
}

// Function to write data to I2C bus
void i2c_write(uint8_t address, uint8_t data) {
    int fd;
    fd = open(I2C_BUS_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = 1,
        .buf = &data
    };

    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRSIZE) < 0) {
        perror("Failed to change I2C address");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

// Function to read data from I2C bus
void i2c_read(uint8_t address, uint8_t *data, size_t len) {
    int fd;
    fd = open(I2C_BUS_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = address,
        .flags = 0,
        .len = len,
        .buf = data
    };

    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRSIZE) < 0) {
        perror("Failed to change I2C address");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to read from I2C bus");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

// Signal handler to clean up resources
void handle_signal(int signum) {
    // Clean up resources on SIGINT and SIGTERM
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup() {
    // Close I2C bus
    close(open(I2C_BUS_PATH, O_RDWR));

    // Release GPIO
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd != -1) {
        gpio_set(GPIO_DIR, LED_GPIO); // Set GPIO17 as input
        gpio_clear(GPIO_SET, LED_GPIO); // Clear LED GPIO
        close(fd);
    }

    // Remove log file if it exists
    const char *logFileName = "adpd144ri_log.txt";
    if (access(logFileName, F_OK) == 0) {
