        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Set AUDIO INPUT GPIO as input
    ret = gpiod_direction_input(AUDIO_INPUT_GPIO);
    if (ret < 0) {
        perror("gpiod_direction_input (AUDIO INPUT GPIO)");
        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }
}

// Function to poll the audio input
