        gpiod_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Assuming the sensor is on the default address for its model
    if (i2c_write(i2c_bus_num, VOC_SENSOR_ADDR, 0) != 0) {
        fprintf(stderr, "Failed to write to VOC sensor address\n");
        gpiod_close(i2c_fd);
        exit(EXIT_FAILURE);
    }
