    if (!tx) {
        return -1;
    }

    tx->dir = GPIOD_DIR_OUT;
    tx->buf = (void *)reg;
    tx->len = 1;

    if (gpiod_transfer(i2c_fd, tx) != 0) {
        gpiod_free_transfer(tx);
        return -1;
    }

    tx->dir = GPIOD_DIR_IN;
    tx->buf = (void *)&data;
    tx->len = 2;

    if (gpiod_transfer(i2c_fd, tx) != 2) {
