void setup_gpiod() {
    int ret;

    // Open GPIO device
    ret = gpiod_open(GPIOD, "r");
    if (ret < 0) {
        fprintf(stderr, "gpiod_open failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request the GPIO pin
    ret = gpiod_request(TOUCH_SENSOR_GPIO, GPIOD_OUT_INPullNone);
    if (ret < 0) {
        fprintf(stderr, "gpiod_request failed: %s\n", strerror(errno));
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    // Set the direction and enable the GPIO pin
    ret = gpiod_direction_output(TOUCH_SENSOR_GPIO, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_direction_output failed: %s\n", strerror(errno));
        gpiod_release(TOUCH_SENSOR_GPIO);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    // Set the initial state to LOW
    ret = gpiod_write(TOUCH_SENSOR_GPIO, 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_write failed: %s\n", strerror(errno));
        gpiod_release(TOUCH_SENSOR_GPIO);
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup gpiod
void cleanup_gpiod() {
    gpiod_release(TOUCH_SENSOR_GPIO);
    gpiod_close(GPIOD);
}

// Function to monitor the touch sensor
void monitor_touch_sensor() {
    int touched = 0;
    struct timespec timeout;
    struct timespec now;
    struct timespec start;

    // Initialize timeout for 5 seconds
    timeout.tv_sec = 5;
    timeout.tv_nsec = 0;

    // Get current time
    clock_gettime(CLOCK_MONOTONIC, &now);

    // Start timer
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        // Read the GPIO pin
        int value = gpiod_read(TOUCH_SENSOR_GPIO);
        if (value == 0) {
            touched = 1;
        }

        // Check if the touch has been detected for more than 5 seconds
        if (touched && (clock_gettime(CLOCK_MONOTONIC, &now) - &start) >= timeout) {
            printf("Intrusion Alert!\n");
            touched = 0; // Reset the touched flag
        }

        // Sleep for 100 ms
        usleep(100000);

        // Check if the sensor read failed
        if (gpiod_read(TOUCH_SENSOR_GPIO) < 0) {
            fprintf(stderr, "Error reading GPIO: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
}

// Signal handler to perform cleanup on SIGINT or SIGTERM
void handle_signal(int signum) {
    printf("Received signal %d, performing cleanup...\n", signum);
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

