#include <sys/stat.h>
#include <stdint.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <signal.h>

#define MIC_GPIO_PIN 17 // BCM 17 for GPIO 17

// ALSA PCM configuration
#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define PCM_FORMAT S16_LE
#define PCM_RATE 44100
#define PCM_CHANNELS 2
#define PCM_BUFFER_SIZE (1024 * PCM_CHANNELS)

// GPIO setup
#define GPIO_INP441_LRC 0x2000000 // GPIO 17

void setup_ALSA() {
    // Open ALSA PCM device
    int pcm_fd = open(PCM_DEVICE, O_RDWR);
    if (pcm_fd == -1) {
        perror("Failed to open ALSA PCM device");
        exit(EXIT_FAILURE);
    }

    // Set ALSA PCM parameters
    struct snd_pcm_hw_params *params;
    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_set_format(params, PCM_FORMAT);
    snd_pcm_hw_params_set_rate_near(params, NULL, &PCM_RATE, NULL);
    snd_pcm_hw_params_set_channels(params, PCM_CHANNELS);
    snd_pcm_hw_params_set_buffer_size_near(params, NULL, &PCM_BUFFER_SIZE);

    if (snd_pcm_hw_params(pcm_fd, params) < 0) {
        perror("Failed to set ALSA PCM parameters");
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    // Prepare for non-blocking I/O
    if (snd_pcm_nonblock(pcm_fd) < 0) {
        perror("Failed to make ALSA PCM non-blocking");
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    // Free ALSA PCM parameters
    snd_pcm_hw_params_free(params);
}

void setup_GPIO() {
    // Open GPIO device
    int gpio_fd = gpiod_open(GPIO_INP441_LRC);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pin as output
    if (gpiod_direction_output(gpio_fd, 1) < 0) {
        perror("Failed to set GPIO pin as output");
        gpiod_close(gpio_fd);
        close(pcm_fd);
        exit(EXIT_FAILURE);
    }

    // Close GPIO device after setup
    gpiod_close(gpio_fd);
}

void cleanup_ALSA() {
    // Close ALSA PCM device
    close(pcm_fd);
}

void cleanup_GPIO() {
    // No need to reopen for cleanup, just ensure it's not in use
    // (since we closed it in setup_GPIO)
}

void handle_signal(int signum) {
    // Handle SIGINT (Ctrl+C) by cleaning up and exiting gracefully
    cleanup_ALSA();
    cleanup_GPIO();
    exit(EXIT_SUCCESS);
}

int main() {
    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    setup_ALSA();
    setup_GPIO();

    uint8_t buffer[PCM_BUFFER_SIZE];
    int bytes_written = 0;

    while (1) {
        // Read from ALSA PCM device
        ssize_t bytes_read = snd_pcm_readi(pcm_fd, buffer, PCM_BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("Error reading from ALSA PCM device");
            break; // Exit loop on read error
        }

        // Write to file
        if (write(STDOUT_FILENO, buffer, bytes_read) != bytes_read) {
            perror("Error writing to file");
            break; // Exit loop on write error
        }

        bytes_written += bytes_read;
    }

    // Clean up on normal exit
    cleanup_ALSA();
    cleanup_GPIO();

    return EXIT_SUCCESS;
}

