#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS_NUM 1
#define OPT3001_ADDR 0x29
#define OPT3001_REG_LUX 0x00

// Constants for ISO 8601 timestamp
#define TIMESTAMP_PREFIX "T"

// GPIO context for I2C bus
struct gpiod_cdev *i2c_bus;

// Function prototypes
void setup_i2c();
void read_lux(uint16_t *lux);
void handle_interrupts(int signum);
void cleanup();

int main() {
    // Initialize GPIO for I2C bus
    if (gpiod_cdev_open(&i2c_bus, I2C_BUS_NUM) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Open file for writing
    int file_fd = open("light_data.txt", O_CREAT | O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (file_fd == -1) {
        perror("Failed to open file");
        gpiod_cdev_close(i2c_bus);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // ISO 8601 timestamp
        time_t now = time(NULL);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Write timestamp to file
        fprintf(file_fd, "%s ", timestamp);

        // Read lux value
        uint16_t lux;
        if (read_lux(&lux) == 0) {
            fprintf(file_fd, "%d ", lux);
        } else {
            fprintf(file_fd, "Error reading lux\n");
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to setup I2C bus
void setup_i2c() {
    if (gpiod_cdev_set_config(i2c_bus, GPIOD_CDEV_CONFIG_SLAVE, I2C_BUS_NUM, 0) < 0) {
        perror("Failed to set I2C bus configuration");
        gpiod_cdev_close(i2c_bus);
        exit(EXIT_FAILURE);
    }
}

// Function to read lux value from OPT3001
void read_lux(uint16_t *lux) {
    uint8_t command[2] = {0x00, 0x00}; // Start conversion command

    // Write command to OPT3001
    if (gpiod_cdev_write(i2c_bus, OPT3001_ADDR, command, sizeof(command)) != sizeof(command)) {
        fprintf(stderr, "Failed to write to OPT3001\n");
        return;
    }

    // Wait for conversion to complete
    usleep(100); // Approximate 100 ms wait

    // Read lux value
    if (gpiod_cdev_read(i2c_bus, OPT3001_ADDR, OPT3001_REG_LUX, lux, sizeof(*lux)) != sizeof(*lux)) {
        fprintf(stderr, "Failed to read lux value from OPT3001\n");
        return;
    }
}

// Signal handler to perform clean shutdown
void handle_interrupts(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close file
    if (file_fd != -1) {
        close(file_fd);
    }

    // Release I2C bus handle
    gpiod_cdev_close(i2c_bus);

    // Release any other resources if necessary
    // Example: free memory allocated with malloc()
}

