#include <string.h>
#include <gpiod.h>

volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO driver
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init() failed: %s\n", gpiod_errstr(ret));
        return EXIT_FAILURE;
    }

    // Open GPIO line 17 (BCM 17, active-low)
    struct gpiod_line *line;
    ret = gpiod_line_open(gpiod_get_line_device(), 17, GPIOD_OPEN_READ);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_open() failed: %s\n", gpiod_errstr(ret));
        gpiod_line_close(line);
        gpiod_uninit();
        return EXIT_FAILURE;
    }

    // Set line 17 as input with pull-up
    ret = gpiod_line_config(line, GPIOD_LINE_CONFIG_INPUT_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_config() failed: %s\n", gpiod_errstr(ret));
        gpiod_line_close(line);
        gpiod_uninit();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read the GPIO line
        int value = gpiod_line_read_value(line);
        if (value == 0) {
            // Flame detected
            char timestamp[21];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(stderr, "%s Flame Detected: YES\n", timestamp);
        } else {
            // No flame detected
            fprintf(stderr, "%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpiod_line_close(line);
    gpiod_uninit();

    return EXIT_SUCCESS;
}

