#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

int main() {
    // Initialize GPIO
    int left_err = gpiod_open_source(GPIOD_SOURCE_GPIO, LEFT_PIN, GPIOD_DIR_OUT_INIT_LOW);
    if (left_err) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", LEFT_PIN, gpiod_get_name(left_err));
        return 1;
    }

    int center_err = gpiod_open_source(GPIOD_SOURCE_GPIO, CENTER_PIN, GPIOD_DIR_OUT_INIT_LOW);
    if (center_err) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", CENTER_PIN, gpiod_get_name(center_err));
        gpiod_close_source(left_err); // Close left pin if center pin open failed
        return 1;
    }

    int right_err = gpiod_open_source(GPIOD_SOURCE_GPIO, RIGHT_PIN, GPIOD_DIR_OUT_INIT_LOW);
    if (right_err) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", RIGHT_PIN, gpiod_get_name(right_err));
        gpiod_close_source(left_err); // Close left pin if center pin open failed
        gpiod_close_source(center_err); // Close center pin if right pin open failed
        return 1;
    }

    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = cleanup;
    sigaction(SIGTERM, &term_handler, NULL);

    // Main loop
    while (1) {
        usleep(50000); // Poll every 50 ms

        // Read GPIO states
        int left_state = gpiod_get_value_input_raw(left_err);
        int center_state = gpiod_get_value_input_raw(center_err);
        int right_state = gpiod_get_value_input_raw(right_err);

        // Print states
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Check for signals
        if (sigpending(&int_handler.sa_mask)) {
            // Handle SIGINT
            printf("SIGINT received, exiting gracefully...\n");
            break;
        }
    }

    // Cleanup on SIGTERM
    void cleanup(int signum) {
        // Release resources
        gpiod_close_source(left_err);
        gpiod_close_source(center_err);
        gpiod_close_source(right_err);

        // Exit with zero status
        exit(0);
    }

    return 0;
}

