    for (int i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; ++i) {
        ret = gpiod_request_line(chip, TOUCH_SENSOR_GPIO_PINS[i]);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", i, gpiod_errstr(gpiod_get_error()));
            gpiod_release_line(chip, TOUCH_SENSOR_GPIO_PINS[i]);
            gpiod_close(chip);
            return;
        }
    }

    // Success, proceed with reading
}

// Function to read TTP226 and print states
void read_ttp226() {
    struct gpiod_line *lines[TOUCH_SENSOR_NUM_CHANNELS];
    int i;

    // Request lines
    for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; ++i) {
        lines[i] = gpiod_request_line(gpiod_chip_get_parent(chip), TOUCH_SENSOR_GPIO_PINS[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error requesting line %d: %s\n", TOUCH_SENSOR_GPIO_PINS[i], gpiod_errstr(gpiod_get_error()));
            for (int j = 0; j < i; ++j) {
                gpiod_release_line(gpiod_chip_get_parent(chip), lines[j]);
            }
            gpiod_close(chip);
            return;
        }
    }

    // Read and print states
    for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; ++i) {
        int state = gpiod_get_value(lines[i]);
        printf("Timestamp: %s, Channel %d: %d\n", ctime(&time(NULL)), i, state ? "1" : "0");
    }

    // Release all lines
    for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; ++i) {
        gpiod_release_line(gpiod_chip_get_parent(chip), lines[i]);
    }
    gpiod_close(chip);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Graceful shutdown
    printf("SIGINT received, shutting down...\n");
    cleanup();
    exit(EXIT_FAILURE);
}

// Cleanup function
void cleanup() {
    // Release chip if it's still open
    if (gpiod_chip_is_open(chip)) {
        gpiod_close(chip);
    }
}

