void setup_gpiod();
void cleanup_gpiod();
void poll_touch_sensors();
void handle_signal(int signum);

int main() {
    // Initialize GPIO context
    setup_gpiod();

    // Install SIGINT handler
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        poll_touch_sensors();
        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup on exit
    cleanup_gpiod();

    return 0;
}

// Function to setup GPIO context for TTP226 sensor
void setup_gpiod() {
    // Open GPIO device
    if ((gpiod_ctx = gpiod_open("/dev/gpiochip0", GPIOD_OPEN_FLAG_NONE)) == NULL) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", gpiod_errstr(gpiod_ctx));
        exit(EXIT_FAILURE);
    }

    // Iterate over the pins and configure them as inputs with bias disabled
    for (int i = 0; i < 8; ++i) {
        const int pin = TOUCH_SENSOR_PIN_BCM[i];
        if (gpiod_request_line(gpiod_ctx, pin, GPIOD_DIR_IN, GPIODedge_NONE, GPIOD_pull_none) < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", pin, gpiod_errstr(gpiod_ctx));
            gpiod_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to cleanup GPIO context and release all resources
void cleanup_gpiod() {
    // Release all requested lines
    for (int i = 0; i < 8; ++i) {
        gpiod_release_line(gpiod_ctx, TOUCH_SENSOR_PIN_BCM[i]);
    }

    // Close the GPIO device
    gpiod_close(gpiod_ctx);
}

// Function to poll the touch sensor and print the results
void poll_touch_sensors() {
    // Get current time in ISO 8601 format
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", localtime(&now));

    // Read the state of each channel
    int states[8];
    for (int i = 0; i < 8; ++i) {
        if (gpiod_get_value(gpiod_ctx, TOUCH_SENSOR_PIN_BCM[i]) == GPIOD_VALUE_HIGH) {
            states[i] = 1;
        } else {
            states[i] = 0;
        }
    }

    // Print the CSV line
    printf("%s,%d,%d,%d,%d,%d,%d,%d\n", timestamp, states[0], states[1], states[2], states[3], states[4], states[5], states[6], states[7]);
}

// SIGINT handler to perform graceful shutdown
void handle_signal(int signum) {
    // Clean up and exit
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

