    for (int i = 0; i < 8; ++i) {
        const int pin = TOUCH_SENSOR_PIN_BCM[i];
        if (gpiod_request_line(gpiod_ctx, pin, GPIOD_DIR_IN, GPIODedge_NONE, GPIOD_pull_none) < 0) {
