#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/signal.h>

#define SI1145_I2C_ADDR 0x29 // Default address for Si1145
#define SI1145_REG_UV_INDEX 0x08
#define SI1145_REG_ALS_VISIBLE 0x09

#define FILE_NAME "uv_als_log.csv"
#define CSV_HEADER "timestamp,uv_index,als_visible"

void i2c_write(int fd, uint8_t addr, uint8_t reg, uint16_t data) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("i2c_write: failed to change slave address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_WRITE, (void *)reg | (data << 8)) < 0) {
        perror("i2c_write: failed to write to register");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, uint8_t addr, uint8_t reg, uint16_t *data) {
    if (ioctl(fd, I2C_READ, (void *)reg) < 0) {
        perror("i2c_read: failed to read from register");
        exit(EXIT_FAILURE);
    }

    *data = (uint16_t)ioctl(fd, I2C_READ, (void *)reg);
}

void print_uv_index_and_als_visible(uint16_t uv_index, uint16_t als_visible) {
    printf("UV Index: %d\n", uv_index);
    printf("Visible Light: %d\n", als_visible);
}

void append_to_csv(const char *timestamp, uint16_t uv_index, uint16_t als_visible) {
    FILE *file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("Could not open CSV file for appending");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fclose(file);
}

int main() {
    // Initialize signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = SIG_IGN;
    sigaction(SIGINT, &int_handler, NULL);
    sigemptyset(&term_handler.sa_mask);
    term_handler.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &term_handler, NULL);

    // Open I2C bus 1
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    uint8_t response;
    i2c_write(fd, SI1145_I2C_ADDR, SI1145_REG_WREV, 0x55);
    i2c_read(fd, SI1145_I2C_ADDR, SI1145_REG_WREV, &response);
    if (response != 0x55) {
        printf("Sensor not responding correctly. Check connections and sensor power.\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Sample the sensor
        uint16_t uv_index, als_visible;
        i2c_write(fd, SI1145_I2C_ADDR, SI1145_REG_UV_INDEX, 0x00);
        i2c_read(fd, SI1145_I2C_ADDR, SI1145_REG_UV_INDEX, &uv_index);
        i2c_write(fd, SI1145_I2C_ADDR, SI1145_REG_ALS_VISIBLE, 0x00);
        i2c_read(fd, SI1145_I2C_ADDR, SI1145_REG_ALS_VISIBLE, &als_visible);

        // Print readings
        print_uv_index_and_als_visible(uv_index, als_visible);

        // Append to CSV
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        append_to_csv(timestamp, uv_index, als_visible);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C file descriptor and exit
    close(fd);
    exit(EXIT_SUCCESS);
}

