    // Setup GPIO 17 as an output
    setup_io();

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Read flow rates
        float flow_rate_1, flow_rate_2;
        read_flow_rate(SENSOR_ADDR, &flow_rate_1);
        read_flow_rate(SENSOR_ADDR + 1, &flow_rate_2);

        // Calculate average flow rate
        float average_flow_rate = (flow_rate_1 + flow_rate_2) / 2.0;

        // Check if average flow rate is below threshold
        if (average_flow_rate < 0.5) {
            handle_alarm(1); // Set GPIO 17 high to trigger alarm
        } else {
            handle_alarm(0); // Set GPIO 17 low to clear alarm
        }

        // Log average flow rate to file every second
        char buffer[100];
        sprintf(buffer, "%f\n", average_flow_rate);
        if (write(1, buffer, strlen(buffer)) != strlen(buffer)) {
            fprintf(stderr, "Error writing to flow_log.txt\n");
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up on exit
    cleanup_io();

    return 0;
}

