    int gpio17;
    gpio17 = gpiod_get("/gpio17", GPIOD_DIR_OUT);
    if (gpio17 < 0) {
        perror("gpiod_get error");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as output
    gpiod_direction_output(gpio17, 1); // High for alarm
}

// Function to cleanup GPIO
void cleanup_io() {
    gpiod_set(gpio17, 0); // Low to clear alarm
    gpiod_release(gpio17);
}

// Function to read flow rate from a sensor
void read_flow_rate(uint8_t addr, float *flow_rate) {
    int i2c_fd;
    struct i2c_msg msg[2];
    int ret;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(EXIT_FAILURE);
    }

    // First message: Start condition and register address
    msg[0].addr = addr;
    msg[0].len = 1;

    // Second message: Read data command
    msg[1].addr = addr;
    msg[1].len = 8; // 8 bytes for SLF3S-0600F flow rate

    // Send I2C messages
    ret = i2c_master_transmit(i2c_fd, msg, 2);
    if (ret < 0) {
        fprintf(stderr, "Error during I2C transmission\n");
        // Log error and skip this sensor's reading
        return;
    }

    // Read response
    ret = i2c_master_recv(i2c_fd, msg, 2, 1000);
    if (ret < 0) {
        fprintf(stderr, "Error during I2C reception\n");
        // Log error and skip this sensor's reading
        return;
    }

    // Check CRC
    uint8_t crc_received = msg[1].data[7];
    uint8_t calculated_crc = crc_ccitt((uint8_t *)msg[1].data, 8, CRC_POLYNOMIAL, INITIAL_CRC_VALUE);
    if (crc_received != calculated_crc) {
        fprintf(stderr, "CRC error, sensor reading invalid\n");
        // Log error and skip this sensor's reading
        return;
    }

    *flow_rate = msg[1].data[0]; // Extract flow rate from response
