#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SDA_PIN 3
#define SCL_PIN 2
#define SENSOR_ADDR 0x1B
#define MODE_REG 0x00
#define ACCEL_X_REG 0x01
#define ACCEL_Y_REG 0x02
#define ACCEL_Z_REG 0x03

#define MAX_ACCEL_READINGS 10
#define CSV_FILE_NAME "fan_health.csv"

void i2c_write(uint8_t device, uint8_t addr, uint8_t reg, uint8_t data) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = 1,
        .buf = &data
    };

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to change I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to write to I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t device, uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = len,
        .buf = data
    };

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to change I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (write(fd, &msg, sizeof(msg)) != sizeof(msg)) {
        perror("Failed to read from I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void set_sensor_mode(uint8_t device) {
    uint8_t mode = 0x00; // Mode 0 for standard operation
    i2c_write(device, SENSOR_ADDR, MODE_REG, mode);
}

void read_accelerations(uint8_t device, uint8_t *accelerations) {
    uint8_t data[3] = {0};
    for (int i = 0; i < MAX_ACCEL_READINGS; ++i) {
        i2c_read(device, SENSOR_ADDR, ACCEL_X_REG, data, sizeof(data));
        accelerations[i] = data[0];
        i2c_read(device, SENSOR_ADDR, ACCEL_Y_REG, data, sizeof(data));
        accelerations[i + MAX_ACCEL_READINGS / 2] = data[0];
        i2c_read(device, SENSOR_ADDR, ACCEL_Z_REG, data, sizeof(data));
        accelerations[i + MAX_ACCEL_READINGS] = data[0];
    }
}

