    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", &ts);

        if (!active) {
            if (retries++ > 10) {
                fprintf(stderr, "Sensor did not become active after 10 retries.\n");
                exit(EXIT_FAILURE);
            }
            continue;
        }

        // Read accelerations
        read_accelerations(I2C_DEVICE_PATH, accelerations);

        // Append to CSV file
        append_to_csv(timestamp, x_value, y_value, z_value);

        usleep(500000); // Wait 500ms

        // Check if sensor is active (assuming some condition based on readings)
        active = check_sensor_active(accelerations);
    }

    return 0;
}

