#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO23 23
#define GPIO24 24
#define GPIO25 25

volatile int sensor1 = 0;
volatile int sensor2 = 0;

int main() {
    // Initialize GPIO
    int rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "gpiod_init() failed: %s\n", gpiod_errstr(rc));
        return EXIT_FAILURE;
    }

    // Set GPIO pins
    rc = gpiod_export GPIO23 GPIOD_OUT_INIT_LOW;
    if (rc != 0) {
        fprintf(stderr, "gpiod_export(GPIO23) failed: %s\n", gpiod_errstr(rc));
        gpiod_unexport(GPIO23);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    rc = gpiod_export GPIO24 GPIOD_OUT_INIT_LOW;
    if (rc != 0) {
        fprintf(stderr, "gpiod_export(GPIO24) failed: %s\n", gpiod_errstr(rc));
        gpiod_unexport(GPIO24);
        gpiod_unexport(GPIO23);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    rc = gpiod_export GPIO25 GPIOD_OUT_INIT_HIGH;
    if (rc != 0) {
        fprintf(stderr, "gpiod_export(GPIO25) failed: %s\n", gpiod_errstr(rc));
        gpiod_unexport(GPIO25);
        gpiod_unexport(GPIO24);
        gpiod_unexport(GPIO23);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    struct sigaction int_handler;
    int_handler.sa_handler = SIG_IGN;
    sigemptyset(&int_handler.sa_mask);
    sigaction(SIGINT, &int_handler, NULL);
    sigaction(SIGTERM, &int_handler, NULL);

    // Main loop
    while (1) {
        // Read sensors
        sensor1 = gpiod_get_value_input_raw(GPIO23);
        sensor2 = gpiod_get_value_input_raw(GPIO24);

        // Check sensor states
        if (sensor1 == 0 || sensor2 == 0) {
            // Turn on LED if any sensor detects an obstacle
            gpiod_set_value(GPIO25, 1);
        } else {
            // Turn off LED if both sensors are clear
            gpiod_set_value(GPIO25, 0);
        }

        // Poll every 100 ms
        usleep(100000);
    }

    // Clean up GPIO resources
    gpiod_unexport(GPIO25);
    gpiod_unexport(GPIO24);
    gpiod_unexport(GPIO23);
    gpiod_exit();

    return EXIT_SUCCESS;
}

