            gpiod_set_value(GPIO25, 1);
        } else {
            // Turn off LED if both sensors are clear
            gpiod_set_value(GPIO25, 0);
        }

        // Poll every 100 ms
        usleep(100000);
    }

    // Clean up GPIO resources
    gpiod_unexport(GPIO25);
    gpiod_unexport(GPIO24);
    gpiod_unexport(GPIO23);
    gpiod_exit();

    return EXIT_SUCCESS;
}
