#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <inttypes.h>
#include <gpiod.h>
#include <csv.h>

#define I2C_BUS_NUM 1
#define TMAG5170_ADDR 0x29
#define TMAG5170_REG_CONTINUOUS_CONVERSION 0x08
#define TMAG5170_REG_X 0x00
#define TMAG5170_REG_Y 0x01
#define TMAG5170_REG_Z 0x02
#define TMAG5170_REG_RANGE 0x0A

#define CSV_FILE_PATH "magnetic_log.csv"
#define CSV_HEADER "Timestamp,X,Y,Z"

void cleanup(void) {
    if (gpiod_i2c_bus_open(I2C_BUS_NUM)) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS_NUM);
        return;
    }

    if (csv_file_exists(CSV_FILE_PATH)) {
        fprintf(stderr, "CSV file already exists: %s\n", CSV_FILE_PATH);
        return;
    }

    // Close I2C handle
    gpiod_i2c_bus_close(I2C_BUS_NUM);

    // Close CSV file
    if (csv_file(CSV_FILE_PATH, "w")) {
        fprintf(stderr, "Failed to open CSV file for writing: %s\n", CSV_FILE_PATH);
        return;
    }
    csv_writef(CSV_FILE_PATH, CSV_HEADER, "\n");

    // Clean up sensor
    if (tmag5170_init()) {
        fprintf(stderr, "Failed to initialize TMAG5170\n");
        return;
    }
    tmag5170_set_range(TMAG5170_REG_RANGE, 50); // 50 mT
    tmag5170_set_continuous_conversion(TMAG5170_REG_CONTINUOUS_CONVERSION, 1);

    while (1) {
        uint8_t x_data, y_data, z_data;
        int ret;

        // Read X, Y, Z data
        ret = tmag5170_read_reg(TMAG5170_REG_X, &x_data);
        if (ret != TMAG5170_OK) {
            fprintf(stderr, "Error reading X data: %d\n", ret);
            continue;
        }

        ret = tmag5170_read_reg(TMAG5170_REG_Y, &y_data);
        if (ret != TMAG5170_OK) {
            fprintf(stderr, "Error reading Y data: %d\n", ret);
            continue;
        }

        ret = tmag5170_read_reg(TMAG5170_REG_Z, &z_data);
        if (ret != TMAG5170_OK) {
            fprintf(stderr, "Error reading Z data: %d\n", ret);
            continue;
        }

        // Format timestamp and data for CSV
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

        char csv_line[256];
        snprintf(csv_line, sizeof(csv_line), "%s,%u,%u,%u", timestamp_str, x_data, y_data, z_data);

        // Write to CSV file
        csv_writef(CSV_FILE_PATH, csv_line, "\n");

        // Sleep for 100ms
        usleep(100000);
    }

    // Sensor cleanup
    tmag5170_deinit();
}

int main(void) {
    // Register SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handlers\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read and process data
        cleanup();
    }

    return EXIT_SUCCESS;
}

