#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>
#include <sys/stat.h>

#define SENSOR_PIN 23
#define ALERT_FILE "flood_log.txt"
#define ALERT_FORMAT "%F %T ALERT: Water detected"

// Function prototypes
void setup_gpiod();
void read_sensor();
void handle_signal(int signum);
void write_alert_to_file(const char *message);
void schedule_reinitialization();

// Global variables
gpiod_device *sensor_device;
int sensor_state;
time_t last_poll_time;
FILE *alert_file;

// Main function
int main(void) {
    // Initialize gpiod
    setup_gpiod();

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Poll the sensor every 2 seconds
        time_t now = time(NULL);
        if ((now - last_poll_time) >= 2) {
            read_sensor();
            last_poll_time = now;
        }

        // Sleep for the remainder of the 2 seconds
        usleep((2000000 - (now - last_poll_time)) * 1000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize gpiod
void setup_gpiod() {
    sensor_device = gpiod_open(GPIO_NUM_TO_NAME(SENSOR_PIN));
    if (sensor_device == NULL) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", SENSOR_PIN);
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_input(sensor_device) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to input\n", SENSOR_PIN);
        exit(EXIT_FAILURE);
    }

    // Check if the driver initialized correctly
    if (gpiod_get_value_input_raw(sensor_device) != 0) {
        fprintf(stderr, "Failed to read GPIO pin %d value\n", SENSOR_PIN);
        exit(EXIT_FAILURE);
    }

    // Open the alert file
    alert_file = fopen(ALERT_FILE, "a+");
    if (alert_file == NULL) {
        perror("Failed to open flood_log.txt");
        exit(EXIT_FAILURE);
    }
}

// Function to read the sensor
void read_sensor() {
    sensor_state = gpiod_get_value_input_raw(sensor_device);

    // Check if the sensor is HIGH
    if (sensor_state) {
        // Write alert to file
        write_alert_to_file(ALERT_FORMAT);

        // Schedule reinitialization after 60 seconds
        schedule_reinitialization();
    } else {
        // Log that no alert was triggered
        fprintf(alert_file, "YYYY-MM-DD HH:MM:SS NO_ALERT: Sensor dry.\n");
    }
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up resources
    cleanup();

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to write an alert to the file
void write_alert_to_file(const char *message) {
    time_t now = time(NULL);
    char buffer[100];
    strftime(buffer, sizeof(buffer), ALERT_FORMAT, localtime(&now));
    fprintf(alert_file, "%s: %s\n", buffer, message);
}

// Function to schedule reinitialization
void schedule_reinitialization() {
    struct timespec timeout;
