static struct gpiod_pad *sensor_pad;
static struct gpiod_input_config *input_config;
static struct gpiod_event_source *event_source;
static volatile uint32_t pulse_count = ATOMIC_VAR_INIT(0);

// Function to initialize GPIO and setup interrupt
int initialize_gpio() {
    int ret;

    // Open GPIO device
    sensor_device = gpiod_get_device_by_name("gpiochip0");
    if (!sensor_device) {
        fprintf(stderr, "Failed to open GPIO device: %s\n", gpiod_error(sensor_device));
        return -1;
    }

    // Get the pad for the sensor pin
    sensor_pad = gpiod_get_pad(sensor_device, SENSOR_PIN);
    if (!sensor_pad) {
        fprintf(stderr, "Failed to get pad for pin %d: %s\n", SENSOR_PIN, gpiod_error(sensor_device));
        gpiod_put_device(sensor_device);
        return -1;
    }

    // Configure the pin as input with internal pull-up
    ret = gpiod_direction_input(sensor_pad);
    if (ret != 0) {
        fprintf(stderr, "Failed to configure pin %d as input: %s\n", SENSOR_PIN, gpiod_error(sensor_pad));
        gpiod_put_pad(sensor_pad);
        gpiod_put_device(sensor_device);
        return -1;
    }

    // Enable internal pull-up resistor
    ret = gpiod_set_pull(sensor_pad, GPIOD_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on pin %d: %s\n", SENSOR_PIN, gpiod_error(sensor_pad));
        gpiod_put_pad(sensor_pad);
        gpiod_put_device(sensor_device);
        return -1;
    }

    // Configure GPIO interrupt
    input_config = gpiod_input_config_new();
    if (!input_config) {
        fprintf(stderr, "Failed to allocate input config: %s\n", gpiod_error(sensor_device));
        gpiod_put_pad(sensor_pad);
        gpiod_put_device(sensor_device);
        return -1;
    }

    input_config->flags = GPIOD_INPUT_CONFIG_FLAG_EDGE_RISING;
    input_config->polling_interval = 0; // Use interrupts

    ret = gpiod_input_config_set(sensor_pad, input_config);
    if (ret != 0) {
        fprintf(stderr, "Failed to set input config on pin %d: %s\n", SENSOR_PIN, gpiod_error(sensor_pad));
        gpiod_input_config_put(input_config);
        gpiod_put_pad(sensor_pad);
        gpiod_put_device(sensor_device);
        return -1;
    }

    // Create event source for interrupts
    event_source = gpiod_event_source_new(sensor_pad, GPIOD_EVENT_RISING);
    if (!event_source) {
        fprintf(stderr, "Failed to create event source: %s\n", gpiod_error(sensor_pad));
        gpiod_input_config_put(input_config);
        gpiod_put_pad(sensor_pad);
        gpiod_put_device(sensor_device);
        return -1;
    }

    return 0;
}

// Function to handle GPIO interrupt
void handle_gpiod_interrupt(void *arg) {
    struct gpiod_event *event = arg;

    // Increment pulse counter atomically
    pulse_count.fetch_add(1, std::memory_order_relaxed);

    // Log the pulse
    struct tm time_info;
    time(&time_info);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time_info);

    char line[256];
    snprintf(line, sizeof(line), "%s %u", timestamp, pulse_count);

    // Write to file and stdout
    FILE *file = fopen("rpm_log.txt", "a+");
    if (!file) {
        fprintf(stderr, "Failed to open rpm_log.txt for writing: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s %u\n", line, pulse_count);
    fflush(file);

    fclose(file);

    // Print to stdout
    printf("%s\n", line);

    // Reset the counter for the next second
    pulse_count = 0;
}

int main() {
    int ret;
    struct sigaction sa;

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    sa.sa_handler = cleanup;
    sa.sa_flags = SA_RESTART;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for one second
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        ret = nanosleep(&ts, NULL);
        if (ret == -1) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            break; // Exit on error
        }

        // Handle GPIO interrupt
        gpiod_event_source_process(event_source);
    }

    // Cleanup
    gpiod_event_source_free(event_source);
    gpiod_input_config_put(input_config);
    gpiod_put_pad(sensor_pad);
    gpiod_put_device(sensor_device);

    return 0;
}

// Function to perform cleanup before exit
void cleanup() {
    // Disable timer and alert callback
    gpiod_event_source_stop(event_source);

    // Close log file
    fclose(file);

    // Call cleanup API
    gpiod_device_cleanup(sensor_device);
}

