#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

#define PULL_UPResistance 1000000  // 1M Ohm pull-up resistor

// Quadrature state machine constants
#define PREV_STATE 0
#define LAST_STATE 1

// Mutex for protecting shared state
pthread_mutex_t stateMutex = PTHREAD_MUTEX_INITIALIZER;

// Condition variable for main thread to wait on
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// GPIO descriptors
gpiod_device_t *sensorA;
gpiod_device_t *sensorB;

// Rotation direction tracking
int lastState = PREV_STATE;
int currentState;

// Function prototypes
void setup_gpios(void);
void handle_quadrature_interrupt(gpiod_event_t *event);
void shutdown_gracefully(void);
void signal_handler(int signum);

int main(void) {
    struct timespec timestamp;
    char buffer[100];
    int fd;

    // Initialize GPIO devices
    setup_gpios();

    // Set up interrupt for Sensor A
    gpiod_set_interrupt(sensorA, GPIOD_INT_EDGE_RISING, handle_quadrature_interrupt);

    // Main loop
    while (1) {
        // Wait for interrupt or signal
        pthread_cond_wait(&cond, &stateMutex);

        // Handle interrupt or signal
        if (gpiod_is_interrupt_active(sensorA)) {
            handle_quadrature_interrupt(NULL);
        } else if (signal_pending(SIGINT) || signal_pending(SIGTERM)) {
            shutdown_gracefully();
        }

        // Log rotation event
        if (currentState != lastState) {
            char timestamp_str[50];
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);

            strftime(timestamp_str, sizeof(timestamp_str), "%F %T.%3ms", timeinfo);
            sprintf(buffer, "%s %d -> %d\n", timestamp_str, lastState, currentState);

            fd = open("rotation_log.txt", O_APPEND | O_WRONLY, 0644);
            if (fd == -1) {
                perror("Failed to open file for writing");
                exit(EXIT_FAILURE);
            }

            write(fd, buffer, strlen(buffer));
            close(fd);
        }

        lastState = currentState;
    }

    return 0;
}

// Function to setup GPIO devices
void setup_gpios(void) {
    sensorA = gpiod_get_device_by_number(SENSOR_A_GPIO);
    if (!sensorA) {
        perror("Failed to get GPIO device for Sensor A");
        exit(EXIT_FAILURE);
    }

    gpiod_set_direction(sensorA, GPIOD_DIR_IN);
    gpiod_set_pull(sensorA, PULL_UPResistance);

    sensorB = gpiod_get_device_by_number(SENSOR_B_GPIO);
    if (!sensorB) {
        perror("Failed to get GPIO device for Sensor B");
        exit(EXIT_FAILURE);
    }

    gpiod_set_direction(sensorB, GPIOD_DIR_IN);
    gpiod_set_pull(sensorB, PULL_UPResistance);
}

// Interrupt handler for Sensor A
void handle_quadrature_interrupt(gpiod_event_t *event) {
    int state = gpiod_get_value(sensorA);

    pthread_mutex_lock(&stateMutex);
    currentState = state;
    pthread_mutex_unlock(&stateMutex);

    // Update the last state based on the current state change
    if (currentState == 1) {
        lastState = LAST_STATE;
    } else {
        lastState = PREV_STATE;
    }
}

// Function to perform graceful shutdown
void shutdown_gracefully(void) {
    pthread_mutex_lock(&stateMutex);
    gpiod_remove_interrupt(sensorA);
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&stateMutex);

    // Close the log file and exit
    close(STDOUT_FILENO); // Simulate closing the log file descriptor
    exit(EXIT_SUCCESS);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    shutdown_gracefully();
}

