#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 18
#define TOUCH_SENSOR_PIN -1
#define LED_PIN 18

volatile sig_atomic_t shutdown_request = 0;

void handle_signal(int signum) {
    shutdown_request = 1;
    syslog(LOG_INFO, "SIGINT or SIGTERM received, initiating shutdown...");
}

int main() {
    // Initialize logging
    openlog("gpio_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Raspberry Pi GPIO monitor starting...");

    // Attempt to open the GPIO chip
    struct gpiod_chip *chip;
    int ret = gpiod_chip_open(&chip, "bcm2835", GPIOD_OPEN_BY_NAME);
    if (ret) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", gpiod_error_string(ret));
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "GPIO chip opened successfully");

    // Request the GPIO lines
    int ret_touch_sensor = gpiod_request_line(chip, TOUCH_SENSOR_GPIO, &TOUCH_SENSOR_PIN, GPIOD_REQUEST_MODE_INPUT);
    int ret_led = gpiod_request_line(chip, LED_GPIO, &LED_PIN, GPIOD_REQUEST_MODE_OUTPUT);

    if (ret_touch_sensor < 0 || ret_led < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines: touch sensor %d, LED %d", TOUCH_SENSOR_GPIO, LED_GPIO);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Requested GPIO lines successfully: touch sensor %d, LED %d", TOUCH_SENSOR_GPIO, LED_GPIO);

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!shutdown_request) {
        // Poll the touch sensor every 50ms
        usleep(50000);
        int touch_status = gpiod_read(chip, TOUCH_SENSOR_PIN);
        if (touch_status) {
            syslog(LOG_INFO, "Touch sensor touched");
            // Turn on the LED
            gpiod_write(chip, LED_PIN, 1);
        } else {
            syslog(LOG_INFO, "Touch sensor not touched");
            // Turn off the LED
            gpiod_write(chip, LED_PIN, 0);
        }
    }

    // Graceful shutdown
    syslog(LOG_INFO, "Shutting down GPIO operations...");
    gpiod_release_line(chip, TOUCH_SENSOR_PIN);
    gpiod_release_line(chip, LED_PIN);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "GPIO monitor shut down successfully");

    return EXIT_SUCCESS;
}

