#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define TOUCH_SENSOR_GPIO 17
#define LED_GPIO 18

volatile int touch_detected = 0;
int debounce_count = 0;

void setup_led() {
    int led_result = gpiod_open(LED_GPIO, GPIOD_OUT_INIT_LOW);
    if (led_result < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d for output\n", LED_GPIO);
        exit(EXIT_FAILURE);
    }
    gpiod_direction_output(LED_GPIO, 0);
}

void setup_touch_sensor() {
    int touch_sensor_result = gpiod_open(TOUCH_SENSOR_GPIO, GPIOD_IN_PUD);
    if (touch_sensor_result < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d for input with pull-up\n", TOUCH_SENSOR_GPIO);
        exit(EXIT_FAILURE);
    }
}

void handle_touch() {
    touch_detected = 1;
    debounce_count = 0;
}

void software_debounce() {
    if (debounce_count++ < 50) {
        return;
    }
    touch_detected = 0;
    debounce_count = 0;
}

void toggle_led() {
    int led_result = gpiod_write(LED_GPIO, touch_detected ? 1 : 0);
    if (led_result < 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", LED_GPIO);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpiod_close(LED_GPIO);
    gpiod_close(TOUCH_SENSOR_GPIO);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    setup_led();
    setup_touch_sensor();

    printf("Touch sensor setup. Waiting for touches...\n");

    while (1) {
        handle_touch();
        software_debounce();
        toggle_led();
    }

    return 0;
}

