#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TOUCH_SENSOR_1 4
#define TOUCH_SENSOR_2 17
#define LED_1 27
#define LED_2 22

#define BUFFER_SIZE 100
#define BUFFER_OVERFLOW 1

volatile sig_atomic_t is_shutting_down = 0;

struct touch_event {
    uint8_t sensor_pin;
    time_t timestamp;
    bool state;
};

static struct touch_event buffer[BUFFER_SIZE];
static size_t buffer_index = 0;

static void touch_sensor_callback(gpiod_cdev *cdev, uint32_t value, void *arg) {
    struct touch_event *event = (struct touch_event *)arg;

    event->sensor_pin = GPIOD_PINNUM_TO_NUM(TOUCH_SENSOR_1);
    event->timestamp = time(NULL);
    event->state = value > 0;

    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
        is_overflowed = 1;
    }

    buffer[buffer_index].sensor_pin = event->sensor_pin;
    buffer[buffer_index].timestamp = event->timestamp;
    buffer[buffer_index].state = event->state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void handle_touch_events() {
    if (buffer_index >= BUFFER_SIZE) {
        is_overflowed = 1;
        return;
    }

    struct touch_event event = buffer[buffer_index];
    printf("Touch event: Sensor %u, timestamp: %lu, state: %d\n",
           event.sensor_pin, event.timestamp, event.state);

    if (event.state) {
        gpiod_set_value(TOUCH_SENSOR_1, 1, NULL); // Turn on LED 1
    } else {
        gpiod_set_value(TOUCH_SENSOR_1, 0, NULL); // Turn off LED 1
    }

    if (event.sensor_pin == TOUCH_SENSOR_2) {
        gpiod_set_value(LED_2, event.state ? 1 : 0, NULL); // Control LED 2 based on sensor 2
    }

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void cleanup_resources() {
    gpiod_cdev_release_all();
    printf("GPIO resources released.\n");
}

static void shutdown_handler(int signum) {
    is_shutting_down = 1;
    handle_touch_events(); // Handle any remaining events
    cleanup_resources(); // Clean up resources
    printf("Shutting down.\n");
}

int main() {
    // Initialize libgpiod
    if (gpiod_cdev_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errmsg());
        return EXIT_FAILURE;
    }

    // Register touch sensor callback
    gpiod_cdev_set_callback(TOUCH_SENSOR_1, touch_sensor_callback, NULL);

    // Register signal handlers
    signal(SIGINT, shutdown_handler);
    signal(SIGTERM, shutdown_handler);

    while (!is_shutting_down) {
        // Poll GPIO and handle touch events
        handle_touch_events();

        // Debounce delay
        usleep(50000); // 50 ms
    }

    // Clean up on SIGINT or SIGTERM
    if (is_shutting_down) {
        shutdown_handler(SIGINT);
    }

    // Print log buffer and overflow count
    printf("Touch log:\n");
    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor %u, timestamp: %lu, state: %d\n", buffer[i].sensor_pin, buffer[i].timestamp, buffer[i].state);
    }
    if (is_overflowed) {
        printf("Overflow occurred.\n");
    }

    // Final cleanup
    cleanup_resources();

    return EXIT_SUCCESS;
}

