#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define RAINDROP_GPIO 17 // GPIO17 on Raspberry Pi 4 Model B (BCM numbering)
#define LOG_FILE_PATH "/var/log/rain_events.log"

// Function prototypes
void setup_gpiod();
void cleanup_gpiod();
void handle_signal(int signum);
void poll_raindrop_sensor();
void write_log_entry(char *message);

int main() {
    // Initialize gpiod
    setup_gpiod();

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        poll_raindrop_sensor();
        usleep(500 * 1000); // Sleep for 500ms
    }

    // Cleanup on exit
    cleanup_gpiod();

    return 0;
}

// Function to setup gpiod
void setup_gpiod() {
    int ret;

    // Initialize gpiod
    ret = gpiod_init();
    if (ret < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Enable internal pull-up resistor on GPIO17
    ret = gpiod_set_pull_up(RAINDROP_GPIO, GPIOD_PULL_UP);
    if (ret < 0) {
        perror("gpiod_set_pull_up");
        exit(EXIT_FAILURE);
    }

    // Open the log file for appending
    char log_file_path[256];
    snprintf(log_file_path, sizeof(log_file_path), LOG_FILE_PATH);
    FILE *log_file = fopen(log_file_path, "a+");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup gpiod and close the log file
void cleanup_gpiod() {
    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Release gpiod resources
    gpiod_exit();
}

// Signal handler to perform graceful shutdown
void handle_signal(int signum) {
    // Clean up and exit
    cleanup_gpiod();
    exit(EXIT_SUCCESS);
}

// Function to poll the raindrop sensor
void poll_raindrop_sensor() {
    int state;
    struct timespec timestamp;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &timestamp);

    // Read the state of the raindrop sensor
    state = gpiod_get_value_input_raw(RAINDROP_GPIO);
    if (state == 0) {
        // LOW indicates rain
        char message[256];
        snprintf(message, sizeof(message), "Rain Detected at %s", ctime(&timestamp.tv_sec));
        write_log_entry(message);
    } else {
        // HIGH indicates no rain
        char message[256];
        snprintf(message, sizeof(message), "No Rain at %s", ctime(&timestamp.tv_sec));
        write_log_entry(message);
    }
}

// Function to write a log entry
void write_log_entry(char *message) {
    // Write to the log file
    if (fwrite(message, 1, strlen(message), log_file) != strlen(message)) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }
}

