#include <signal.h>
#include <gpiod.h>
#include <stdint.h>

#define SI1182_I2C_ADDR 0x40
#define SI1182_REG_HEART_RATE 0x00
#define SI1182_REG_SPO2 0x01

// Function prototypes
void handleInterrupt(int signum);
int openBiometricLogFile(char *filename);
void writeToBiometricLog(char *timestamp, uint16_t heartRate, uint8_t spo2);
void closeBiometricLogFile();
void cleanupI2C();
void readSi1182Data();

int main() {
    // Initialize signal handler for Ctrl+C
    signal(SIGINT, handleInterrupt);

    // Open the biometric log file
    int logFileDescriptor = openBiometricLogFile("biometric_log.txt", O_APPEND | O_WRONLY | O_CREAT, 0644);

    if (logFileDescriptor == -1) {
        perror("Failed to open biometric log file");
        exit(EXIT_FAILURE);
    }

    // Set up I2C communication
    int i2c_fd = gpiod_i2c_open(1, GPIOD_I2C_FLAG_NO_WAIT);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        close(logFileDescriptor);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for timestamp buffer
    char timestamp[50];

    // Main loop
    while (1) {
        // Read current time
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read heart rate and SpO2
        uint16_t heartRate;
        uint8_t spo2;
        if (readSi1182Data(i2c_fd, SI1182_REG_HEART_RATE, &heartRate) != SI1182_OK) {
            fprintf(stderr, "Error reading heart rate: %s\n", gpiod_i2c_get_last_error_str(i2c_fd));
            continue;
        }
        if (readSi1182Data(i2c_fd, SI1182_REG_SPO2, &spo2) != SI1182_OK) {
            fprintf(stderr, "Error reading SpO2: %s\n", gpiod_i2c_get_last_error_str(i2c_fd));
            continue;
        }

        // Write to log file
        writeToBiometricLog(timestamp, heartRate, spo2);
        fflush(logFileDescriptor);

        // Pause for 1 second
        usleep(1000000);

        // Close log file after each write to ensure data is flushed
        closeBiometricLogFile();
    }

    // Cleanup I2C resources
    cleanupI2C();

    // Exit program
    exit(EXIT_SUCCESS);
}

// SIGINT handler
void handleInterrupt(int signum) {
    // Close log file and I2C handle
    closeBiometricLogFile();
    cleanupI2C();

    // Terminate the program
    exit(EXIT_SUCCESS);
}

// Function to open biometric log file
int openBiometricLogFile(char *filename, int flags, mode_t mode) {
    int fd = open(filename, flags, mode);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

// Function to write to biometric log file
void writeToBiometricLog(char *timestamp, uint16_t heartRate, uint8_t spo2) {
    char logLine[256];
    snprintf(logLine, sizeof(logLine), "%s, Heart Rate: %u BPM, SpO2: %u%%", timestamp, heartRate, spo2);
    if (write(logFileDescriptor, logLine, strlen(logLine)) != strlen(logLine)) {
        perror("write to log file failed");
    }
}

// Function to close biometric log file
void closeBiometricLogFile() {
    close(logFileDescriptor);
}

// Function to cleanup I2C resources
void cleanupI2C() {
    gpiod_i2c_close(i2c_fd);
}

// Function to read data from Si1182
int readSi1182Data(int i2c_fd, uint8_t regAddress, uint16_t *data) {
    uint8_t buffer[2];
    int bytesRead = gpiod_i2c_read(i2c_fd, regAddress, buffer, sizeof(buffer));
    if (bytesRead != sizeof(buffer)) {
        return SI1182_ERROR;
    }

    *data = (uint16_t)((buffer[0] << 8) | buffer[1]);
    return SI1182_OK;
}

