#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <libgpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27

#define THRESHOLD_TIME_MS 2000
#define POLL_INTERVAL_MS 100

// GPIO descriptors
struct gpio_desc sensor1_gpio;
struct gpio_desc sensor2_gpio;
struct gpio_desc alarm_gpio;

// Log file descriptor
int log_fd = -1;

// Function prototypes
void setup_gpios(void);
void poll_sensors(void);
void handle_alarm_event(int sensor);
void cleanup(void);
void signal_handler(int signum);

int main(void) {
    // Initialize GPIO descriptors
    setup_gpios();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        poll_sensors();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize GPIO descriptors
void setup_gpios(void) {
    // Initialize GPIO descriptors
    sensor1_gpio = gpiochip_lookup(0);
    sensor2_gpio = gpiochip_lookup(0);
    alarm_gpio = gpiochip_lookup(0);

    // Set GPIO pins as inputs with internal pull-down resistors
    if (gpio_direction_input(sensor1_gpio) != 0) {
        perror("Failed to set sensor1 as input");
        exit(EXIT_FAILURE);
    }
    if (gpio_direction_input(sensor2_gpio) != 0) {
        perror("Failed to set sensor2 as input");
        exit(EXIT_FAILURE);
    }
    if (gpio_direction_output(alarm_gpio, 0) != 0) {
        perror("Failed to set alarm GPIO as output");
        exit(EXIT_FAILURE);
    }

    // Check if GPIO setup was successful
    if (sensor1_gpio == NULL || sensor2_gpio == NULL || alarm_gpio == NULL) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
}

// Function to poll sensors and handle alarm events
void poll_sensors(void) {
    struct timespec start_time;
    struct timespec end_time;
    int sensor1_value, sensor2_value;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &start_time);

    // Poll sensors
    sensor1_value = gpio_read(sensor1_gpio);
    sensor2_value = gpio_read(sensor2_gpio);

    // Check for threshold exceeded
    if (sensor1_value || sensor2_value) {
        handle_alarm_event(sensor1_value);
    }

    // Wait for threshold time
    if (sensor1_value && sensor2_value) {
        if (clock_gettime(CLOCK_REALTIME, &end_time) - &start_time > timespec_sub(&THRESHOLD_TIME_MS, NULL)) {
            // Threshold exceeded for more than 2 seconds
            printf("Alarm triggered for more than 2 seconds.\n");
            // Activate alarm (e.g., toggle GPIO 27)
            gpio_write(alarm_gpio, 1);
        } else {
            // Threshold not exceeded
            printf("Alarm condition not met.\n");
        }
    }

    // Deactivate alarm if both sensors return to LOW
    if (!sensor1_value && !sensor2_value) {
        gpio_write(alarm_gpio, 0);
        printf("Alarm deactivated.\n");
    }

