    if (gpiod_open(gpio_desc, ARRAY_SIZE(gpio_desc)) < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", gpiod_get_name(gpiod_get_device()));
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (i2c_init(I2C_BUS_NUM) < 0) {
