        clock_nanosleep(CLOCK_REALTIME, &ts);

        // Read sensor data
        uint8_t data;
        if (read_sensor_data(CTRL_REG1_ADDR) < 0) {
            // Handle I2C errors
            if (i2c_error_count(I2C_BUS_NUM) > 0) {
                fprintf(stderr, "I2C error detected: retrying...\n");
                continue;
            }
            // Sensor absent or other unrecoverable error
            fprintf(stderr, "Sensor not responding. Exiting.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        uint16_t magnitude = (data & 0x0FFF) * 16; // Extract magnitude from data

