    // Clear power-down bit in CTRL1 register
    uint8_t ctrl_reg1_data;
    if (read_sensor_data(CTRL_REG1_ADDR) < 0) {
        fprintf(stderr, "Error reading CTRL1 register: retrying...\n");
        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (read_sensor_data(CTRL_REG1_ADDR) >= 0) {
                ctrl_reg1_data = read_sensor_data(CTRL_REG1_ADDR);
                ctrl_reg1_data &= ~CTRL1_BIT_POWER_DOWN;
                write_sensor_data(CTRL_REG1_ADDR, ctrl_reg1_data);
                break;
            }
            usleep(100); // Small delay between retries
        }
        if (i == MAX_RETRIES) {
            fprintf(stderr, "Failed to clear power-down bit. Exiting.\n");
            return;
        }
    }

    // Verify sensor presence
    if (read_sensor_data(0x00) != 0x55) {
        fprintf(stderr, "Sensor not responding correctly. Exiting.\n");
        return;
    }
}

