    uint8_t data;
    if (i2c_smbus_read_byte_data(I2C_BUS_NUM, addr) < 0) {
        fprintf(stderr, "Error reading from sensor: retrying...\n");
        for (int i = 0; i < MAX_RETRIES; ++i) {
            if (i2c_smbus_read_byte_data(I2C_BUS_NUM, addr) >= 0) {
                data = i2c_smbus_read_byte_data(I2C_BUS_NUM, addr);
                break;
            }
            usleep(100); // Small delay between retries
        }
        if (i == MAX_RETRIES) {
            fprintf(stderr, "Failed to read from sensor. Exiting.\n");
            return;
        }
    }
    data = (data & 0xF0) | (i2c_smbus_read_word_data(I2C_BUS_NUM, 0x01) >> 4); // Combine data and high byte
}

