    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *file = fopen("seismic_events.log", "a+");
    if (!file) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    fprintf(file, "%s: Magnitude: %d\n", timestamp, magnitude);
    fclose(file);

    // Turn on alert LED for 1 second
    gpiod_set_value(BS(ALERT_GPIO), 1);
    usleep(1000000);
    gpiod_set_value(BS(ALERT_GPIO), 0);
}

