    struct gpiod_pad *pad;

    pad = gpiod_get_by_name("bcm2835-gpio");
    if (!pad) {
        fprintf(stderr, "Failed to get GPIO controller\n");
        return EXIT_FAILURE;
    }

    gpio_in[0].direction = GPIOD_DIR_IN;
    gpio_in[1].direction = GPIOD_DIR_IN;
    gpio_in[2].direction = GPIOD_DIR_IN;
    gpio_in[3].direction = GPIOD_DIR_IN;

    gpio_csn[0].cs = GPIOD_CSN_NONE;
    gpio_csn[1].cs = GPIOD_CSN_NONE;
    gpio_csn[2].cs = GPIOD_CSN_NONE;
    gpio_csn[3].cs = GPIOD_CSN_NONE;

    for (int i = 0; i < 4; i++) {
        ret = gpiod_request_line(pad, gpio_in[i].line);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", gpio_in[i].line);
            gpiod_free(pad);
            return EXIT_FAILURE;
        }

        ret = gpiod_request_csn(pad, gpio_csn[i].cs);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO CS line %d\n", gpio_csn[i].cs);
            gpiod_release_line(pad, gpio_in[i].line);
            gpiod_release_csn(pad, gpio_csn[i].cs);
            gpiod_free(pad);
            return EXIT_FAILURE;
        }

        gpio_in[i].pad = pad;
        gpio_csn[i].pad = pad;
    }

    gpiod_free(pad);

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Poll GPIO inputs
        int in1 = gpiod_read_value(gpio_in[0].pad, gpio_in[0].line);
        int in2 = gpiod_read_value(gpio_in[1].pad, gpio_in[1].line);
        int in3 = gpiod_read_value(gpio_in[2].pad, gpio_in[2].line);
        int in4 = gpiod_read_value(gpio_in[3].pad, gpio_in[3].line);

        if (in1 == 0 || in2 == 0 || in3 == 0 || in4 == 0) {
            // Turn on LED if any sensor detects an obstacle
            gpiod_write_value(gpio_in[0].pad, gpio_num_to_name(GPIO_NUM_LED), 1);
        } else {
            // Turn off LED if no obstacle detected
            gpiod_write_value(gpio_in[0].pad, gpio_num_to_name(GPIO_NUM_LED), 0);
        }

        // Poll GPIO inputs every 50ms without blocking
        usleep(50000);
    }

    // Clean up GPIO resources on exit
    for (int i = 0; i < 4; i++) {
        gpiod_release_line(gpio_in[i].pad, gpio_in[i].line);
        gpiod_release_csn(gpio_csn[i].pad, gpio_csn[i].cs);
    }

    gpiod_free(gpiod_get_by_name("bcm2835-gpio"));

    return EXIT_SUCCESS;
}
