#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"
#define LOG_FACILITY LOG_USER
#define LOG_ID "flame_monitor"

volatile sig_atomic_t shutdown_flag = 0;

struct sensor_data {
    gpiod_line *line;
    int sensor_id;
    int gpio_pin;
};

struct sensor_data sensors[NUM_SENSORS];

void setup_sensors() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].sensor_id = i + 1;
        sensors[i].gpio_pin = (i == 0) ? 2 : (i == 1) ? 3 : (i == 2) ? 4 : (i == 3) ? 17 : 27;

        sensors[i].line = gpiod_line_new(sensors[i].gpio_pin, GPIOD_DIR_IN);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to acquire line for sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);
            exit(EXIT_FAILURE);
        }
    }
}

void handle_signals() {
    struct sigaction sa;

    sa.sa_handler = &shutdown_flag_handler;
    sa.sa_flags = SA_RESTART;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void shutdown_flag_handler() {
    shutdown_flag = 1;
}

void poll_sensors() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_get(sensors[i].line) != 1) {
            // Debounce
            if (gpiod_line_request(sensors[i].line, DEBOUNCE_MS) == 0) {
                if (gpiod_line_get(sensors[i].line) == 0) {
                    char timestamp[32];
                    time_t now = time(NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&now));

                    fprintf(LOG_FILE, "%s - Sensor %d: %d (GPIO %d) - Flame Detected\n", timestamp, sensors[i].sensor_id, sensors[i].sensor_id, sensors[i].gpio_pin);
                    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);

                    // Release the line and close the chip on confirmed detection
                    gpiod_line_release(sensors[i].line);
                    gpiod_line_free(sensors[i].line);
                } else {
                    // Revert if debounce fails
                    gpiod_line_release(sensors[i].line);
                }
            } else {
                syslog(LOG_WARNING, "Debounce failed for sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);
            }
        } else {
            // Normal operation, no change detected
        }
    }
}

void cleanup() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(sensors[i].line);
        gpiod_line_free(sensors[i].line);
    }
    gpiod_line_remove_all();
    closelog();
}

int main() {
    setup_sensors();
    handle_signals();
    while (!shutdown_flag) {
        poll_sensors();
    }
    cleanup();
    return 0;
}

