#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN_MAP {
    [5] = GPIOD_OUT_LOW, [6] = GPIOD_OUT_LOW, [13] = GPIOD_OUT_LOW, [19] = GPIOD_OUT_LOW,
    [26] = GPIOD_OUT_LOW, [12] = GPIOD_OUT_LOW, [16] = GPIOD_OUT_LOW, [20] = GPIOD_OUT_LOW
};

#define TOUCH_SENSOR_NUM_CHANNELS 8

int main(void) {
    struct gpiod_dir *dir;
    struct gpiod_channel *chan;
    int ret, i;
    time_t timestamp;
    const char *pin_name;

    // Initialize GPIO library
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "gpiod_init failed: %s (errno=%d)\n", strerror(errno), errno);
        return EXIT_FAILURE;
    }

    // Open GPIO device
    if ((ret = gpiod_open(GPIOD_DIR_DEV, "r")) != 0) {
        fprintf(stderr, "gpiod_open failed: %s (errno=%d)\n", strerror(errno), errno);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Allocate and initialize channels for each touch sensor pin
    dir = gpiod_alloc_dir(GPIOD_DIR_DEV);
    if (!dir) {
        fprintf(stderr, "gpiod_alloc_dir failed: %s (errno=%d)\n", strerror(errno), errno);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; i++) {
        chan = gpiod_channel_new_from_name(dir, TOUCH_SENSOR_PIN_MAP[i].name);
        if (!chan) {
            fprintf(stderr, "gpiod_channel_new_from_name failed for pin %d: %s (errno=%d)\n",
                    TOUCH_SENSOR_PIN_MAP[i].gpio, TOUCH_SENSOR_PIN_MAP[i].name, errno);
            gpiod_channel_free(chan);
            gpiod_free_dir(dir);
            gpiod_cleanup();
            return EXIT_FAILURE;
        }
        gpiod_channel_set_direction(chan, TOUCH_SENSOR_PIN_MAP[i].mode);
    }

    // Main loop
    while (1) {
        timestamp = time(NULL);
        for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; i++) {
            ret = gpiod_bulk_read(chan[i], 1, NULL, 0);
            if (ret < 0) {
                fprintf(stderr, "gpiod_bulk_read failed for channel %d: %s (errno=%d)\n",
                        i, strerror(errno), errno);
                gpiod_channel_free(chan[i]);
                gpiod_free_dir(dir);
                gpiod_cleanup();
                return EXIT_FAILURE;
            }
            if (ret) {
                // A touch event occurred
                pin_name = TOUCH_SENSOR_PIN_MAP[i].name;
                fprintf(stderr, "ISO-8601 Timestamp: %s, Pin: %s, Touch Detected\n",
                        ctime(&timestamp), pin_name);
            } else {
                // No touch event
                pin_name = TOUCH_SENSOR_PIN_MAP[i].name;
                fprintf(stderr, "ISO-8601 Timestamp: %s, Pin: %s, Touch Released\n",
                        ctime(&timestamp), pin_name);
            }
        }
        usleep(50000); // Poll every 50 ms
    }

    // Clean up resources
    for (i = 0; i < TOUCH_SENSOR_NUM_CHANNELS; i++) {
        gpiod_channel_free(chan[i]);
    }
    gpiod_free_dir(dir);
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

