#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <stdint.h>

#define VEML7700_I2C_ADDR 0x39
#define GPIO18_PIN 18

// Constants for VEML7700 register addresses
#define VEML7700_REG_LUX 0x00
#define VEML7700_REG_CONFIG 0x01

// PWM frequency in Hz
#define PWM_FREQ 1000

// Mapping from lux to PWM duty cycle
int lux_to_pwm(int lux) {
    if (lux < 100) return 255; // 100% brightness
    else if (lux < 500) return 191; // 75% brightness
    else if (lux < 1000) return 128; // 50% brightness
    else return 63; // 25% brightness
}

// Function to initialize GPIO and I2C
int init_resources() {
    // Initialize GPIO
    if (gpiod_open(GPIO18_PIN, GPIO_OUTPUT PWM_OUTPUT, GPIO_ACTIVE_LOW | GPIO_PULSE_MODE) < 0) {
        perror("gpiod_open GPIO18");
        return -1;
    }

    // Initialize I2C
    int i2c_fd = -1;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }

    // Configure I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read lux from VEML7700
int read_lux() {
    uint8_t data[2];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, VEML7700_I2C_ADDR, VEML7700_REG_LUX, data, 2) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        close(i2c_fd);
        return -1;
    }

    int lux = data[0] << 8 | data[1];
    return lux;
}

// Function to write lux to PWM
void set_brightness(int lux) {
    int duty_cycle = lux_to_pwm(lux);
    if (gpiod_set_data(GPIO18_PIN, duty_cycle) < 0) {
        perror("gpiod_set_data");
    }
}

// Function to log data to grow_log.txt
void log_data(const char *timestamp, int lux, int brightness) {
    char log_line[256];
    strftime(log_line, sizeof(log_line), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
    sprintf(log_line + strlen(timestamp), "Lux: %d, Brightness: %d", lux, brightness);
    fprintf("grow_log.txt", "%s\n", log_line);
    fflush("grow_log.txt");
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    // Turn off the LED
    gpiod_set_data(GPIO18_PIN, 0);

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(stderr);

    // Clean exit
    exit(0);
}

int main() {
    // Initialize resources
    if (init_resources() < 0) {
        perror("Initialization failed");
        return 1;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read lux from sensor
        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux: %s\n", strerror(errno));
            continue;
        }

        // Set brightness based on lux
        set_brightness(lux);

        // Log data
        log_data("ISO-8601 Timestamp", lux, lux_to_pwm(lux));

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

