#define ALERT_LED_GPIO 17 // BCM pin 17

// GPIO context for the touch sensor
struct gpio_context touch_sensor_ctx;

// GPIO context for the alert LED
struct gpio_context led_ctx;

// Function to initialize GPIO contexts
int init_gpios() {
    int ret;

    // Initialize touch sensor GPIO context
    ret = gpiochip_request_one(&touch_sensor_ctx.gpio_chip, TOUCH_SENSOR_GPIO_NUMS[0], "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIOs for touch sensor.\n");
        return -1;
    }

    // Initialize LED GPIO context
    ret = gpiochip_request_one(&led_ctx.gpio_chip, &GPIO_NUM_TO_PIN(17), "alert_led");
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO for alert LED.\n");
        gpiochip_free(&touch_sensor_ctx.gpio_chip);
        return -1;
    }

    // Set touch sensor GPIOs as inputs with pull-down resistors
    for (int i = 0; i < ARRAY_SIZE(TOUCH_SENSOR_GPIO_NUMS); ++i) {
        ret = gpiod_direction_input(&touch_sensor_ctx.gpio, TOUCH_SENSOR_GPIO_NUMS[i]);
        if (ret != 0) {
            fprintf(stderr, "Error: Failed to configure GPIO %d as input with pull-down.\n", TOUCH_SENSOR_GPIO_NUMS[i]);
            gpiochip_free(&touch_sensor_ctx.gpio_chip);
            gpiochip_free(&led_ctx.gpio_chip);
            return -1;
        }
    }

    // Set LED GPIO as output
    ret = gpiod_direction_output(&led_ctx.gpio, 1);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO %d as output.\n", ALERT_LED_GPIO);
        gpiochip_free(&touch_sensor_ctx.gpio_chip);
        gpiochip_free(&led_ctx.gpio_chip);
        return -1;
    }

    return 0;
}

// Function to debounce and log touch events
void debounce_and_log_touch(int channel) {
    static int last_read = 0;
    int current_read;

    // Poll the GPIO
    current_read = gpiod_get_value_input(&touch_sensor_ctx.gpio, TOUCH_SENSOR_GPIO_NUMS[channel]);

    // Debounce by checking if the state has changed since the last read
    if (current_read != last_read) {
        last_read = current_read;
        char timestamp[23];
        time_t now = time(NULL);
        struct tm timeinfo;
        char buffer[80];

        // Format timestamp
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(timestamp, "%s - Channel %d Touched", buffer, channel + 1);

        // Write to file
        FILE *touch_log = fopen("touch_log.txt", "a+");
        if (!touch_log) {
            fprintf(stderr, "Error: Failed to open touch log file for appending.\n");
            return;
        }
        fprintf(touch_log, "%s\n", timestamp);
        fclose(touch_log);
    }
}

// Function to handle SIGINT and SIGTERM
void handle_signal(int signum) {
    // Turn off the LED
    gpiod_set_value_output(&led_ctx.gpio, 0);

    // Release GPIO resources
    gpiochip_free(&touch_sensor_ctx.gpio_chip);
    gpiochip_free(&led_ctx.gpio_chip);

    // Exit gracefully
    exit(0);
}

int main() {
    // Initialize GPIO contexts
    if (init_gpios() < 0) {
        return 1;
    }

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Poll touch sensor every 50 ms
        usleep(50000);

        // Check for touch events
        for (int i = 0; i < ARRAY_SIZE(TOUCH_SENSOR_GPIO_NUMS); ++i) {
            debounce_and_log_touch(i);
        }

        // Turn on LED if any channel is touched
        for (int i = 0; i < ARRAY_SIZE(TOUCH_SENSOR_GPIO_NUMS); ++i) {
            if (gpiod_get_value_input(&touch_sensor_ctx.gpio, TOUCH_SENSOR_GPIO_NUMS[i]) == 1) {
                gpiod_set_value_output(&led_ctx.gpio, 1);
                break;
            }
        }
    }

    return 0;
}

