#include <stdint.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x29
#define OPT3001_REG_CONFIG 0x00
#define OPT3001_REG_DATA 0x01

// OPT3001 register definitions
#define OPT3001_REG_CONFIG_REG_CONFIG 0x00
#define OPT3001_REG_DATA_REG_LUX 0x01

// Byte-swapping macros
#define SWAP16(x) (((x) & 0xFF) << 8 | ((x) & 0xFF00) >> 8)

// Function prototypes
void setup_i2c(void);
void cleanup_i2c(void);
void handle_signal(int signum);
int write_reg(uint8_t reg, uint16_t value);
int read_reg(uint8_t reg, uint16_t *value);
void print_light_data(const char *timestamp, uint16_t lux_value);

int main(void) {
    // Initialize I2C
    setup_i2c();

    // SIGINT handler
    signal(SIGINT, handle_signal);

    time_t now = time(NULL);
    FILE *file = fopen("light_data.txt", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file 'light_data.txt' for writing.\n");
        return EXIT_FAILURE;
    }

    while (1) {
        // Write configuration to OPT3001
        uint16_t config_value = SWAP16(OPT3001_REG_CONFIG_REG_CONFIG); // 0x0000
        if (write_reg(OPT3001_REG_CONFIG, &config_value) != 0) {
            fprintf(stderr, "Failed to write configuration to OPT3001.\n");
            continue;
        }

        // Wait at least 100ms before reading data
        usleep(100000);

        // Read data from OPT3001
        uint16_t lux_value;
        if (read_reg(OPT3001_REG_DATA, &lux_value) != 0) {
            fprintf(stderr, "Failed to read data from OPT3001.\n");
            continue;
        }

        // Print and log the data
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        print_light_data(timestamp, lux_value);

        // Flush and close the file
        fflush(file);
        fclose(file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on SIGINT
    cleanup_i2c();

    return EXIT_SUCCESS;
}

// Function to setup I2C
void setup_i2c(void) {
    int fd;
    struct gpiod_dir *dir;
    struct gpiod_cdev *cdev;

    // Open I2C bus
    fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Get the directory entry
    dir = gpiod_dir_open(fd);
    if (!dir) {
        fprintf(stderr, "Failed to get directory entry for I2C bus %d.\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    // Get the character device
    cdev = gpiod_cdev_from_dir(dir);
    if (!cdev) {
        fprintf(stderr, "Failed to get character device for I2C bus %d.\n", I2C_BUS);
        gpiod_dir_close(dir);
        exit(EXIT_FAILURE);
    }

    // Close the directory entry
    gpiod_dir_close(dir);

    // Initialize the I2C device
    if (i2c_smbus_write_byte_data(cdev->dev, OPT3001_ADDR, OPT3001_REG_CONFIG) != 0) {
        fprintf(stderr, "Failed to write to OPT3001 configuration register.\n");
        i2c_dev_close(cdev->dev);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup I2C
void cleanup_i2c(void) {
    if (open("/dev/i2c-" I2C_BUS, O_RDWR) != -1) {
        gpiod_dir_close(gpiod_dir_open(open("/dev/i2c-" I2C_BUS, O_RDWR)));
        i2c_dev_close(open("/dev/i2c-" I2C_BUS, O_RDWR)->dev);
    }
}

// Function to handle SIGINT
void handle_signal(int signum) {
    // Clean up I2C and log file
    cleanup_i2c();
    fclose(stderr);
    exit(EXIT_FAILURE);
}

// Function to write a register value
int write_reg(uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    data[0] = (uint8_t)(SWAP16(*value) & 0xFF);
    data[1] = (uint8_t)((SWAP16(*value) >> 8) & 0xFF);
    return i2c_smbus_write_word_data(open("/dev/i2c-" I2C_BUS, O_RDWR), reg, data);
}

// Function to read a register value
int read_reg(uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    if (i2c_smbus_read_word_data(open("/dev/i2c-" I2C_BUS, O_RDWR), reg, data) != 2) {
        return -1;
    }
    *value = SWAP16(data[0]) | (data[1] << 8);
    return 0;
}

// Function to print light data
void print_light_data(const char *timestamp, uint16_t lux_value) {
    char buffer[256];
    sprintf(buffer, "%s, %5.2f lux", timestamp, lux_value / 100.0);
    fprintf(stdout, "%s\n", buffer);
    fprintf(file, "%s\n", buffer);
}

