#include <sys/stat.h>
#include <sys/types.h>

#define SENSIRION_I2C_ADDR 0x5A // SLF3S-1300F default address
#define SENSIRION_REG_FLOW 0x00 // Flow rate register
#define SENSIRION_REG_CRC 0x01 // CRC register

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define SDA_GPIO 2
#define SCL_GPIO 3

// Flow rate range validation
#define MIN_FLOW_RATE 0
#define MAX_FLOW_RATE 100

// CRC polynomial and initial value for SLF3S-1300F
#define CRC_POLYNOMIAL 0x07
#define CRC_INITIAL_VALUE 0xFF

// Status codes
#define OK 0
#define INVALID 1
#define ERROR 2

// Function prototypes
void i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
uint8_t i2c_read(uint8_t addr, uint8_t reg);
void validate_flow_rate(uint16_t flow_rate);
void write_to_csv(const char *message);
void handle_interrupt(int signum);

int main() {
    // Initialize variables
    int i2c_fd = -1;
    uint8_t flow_rate[2];
    uint8_t crc;
    int csv_fd = -1;
    char buffer[256];
    struct stat stat_buf;
    time_t timestamp;
    FILE *csv_file = NULL;

    // Attempt to open I2C device
    if ((i2c_fd = open(I2C_DEVICE_PATH, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Attempt to open CSV file for writing
    if ((csv_fd = fopen("cooling_log.csv", "a")) == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header only on first run
    if (fstat(csv_fd, &stat_buf) == 0 && stat_buf.st_size == 0) {
        fprintf(csv_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    // Main loop
    while (1) {
        // Attempt to write to flow rate register
        if (i2c_write(SENSIRION_I2C_ADDR, SENSIRION_REG_FLOW, 0) < 0) {
            perror("Failed to write to flow rate register");
            continue;
        }

        // Wait at least 2 ms before reading
        usleep(2000);

        // Read flow rate and CRC
        if (i2c_read(SENSIRION_I2C_ADDR, SENSIRION_REG_FLOW, flow_rate) < 2) {
            perror("Failed to read flow rate and CRC");
            continue;
        }
        if (i2c_read(SENSIRION_I2C_ADDR, SENSIRION_REG_CRC, &crc) < 1) {
            perror("Failed to read CRC");
            continue;
        }

        // Validate flow rate and CRC
        validate_flow_rate(*((uint16_t *)flow_rate));
        if (crc != (uint8_t)(((*((uint16_t *)flow_rate) << 8)) ^ ((uint16_t)CRC_POLYNOMIAL * ((uint16_t)CRC_INITIAL_VALUE ^ *flow_rate)) & 0xFF)) {
            fprintf(csv_file, "%lu,ERROR\n", (long)timestamp);
        } else {
            if (*flow_rate < MIN_FLOW_RATE || *flow_rate > MAX_FLOW_RATE) {
                fprintf(csv_file, "%lu,INVALID,%d\n", (long)timestamp, INVALID);
            } else {
                fprintf(csv_file, "%lu,%lu,%d\n", (long)timestamp, *flow_rate, OK);
            }
        }

        // Close resources on SIGINT
        handle_interrupt(SIGINT);

        // Sleep for 1 second
        sleep(1);
    }

    // Close resources on exit
    close(i2c_fd);
    fclose(csv_file);
    remove("cooling_log.csv"); // Optionally remove the file

    return EXIT_SUCCESS;
}

// Function to write a byte to the specified I2C address and register
void i2c_write(uint8_t addr, uint8_t reg, uint8_t data) {
    int bytes_written;
    if ((bytes_written = write(i2c_fd, &reg, 1)) != 1 || (bytes_written = write(i2c_fd, &data, 1)) != 1) {
        perror("Failed to write to I2C device");
    }
}

// Function to read a byte from the specified I2C address and register
uint8_t i2c_read(uint8_t addr, uint8_t reg) {
    uint8_t data;
    if (read(i2c_fd, &reg, 1) != 1 || (read(i2c_fd, &data, 1) != 1)) {
        perror("Failed to read from I2C device");
        return 0;
    }
    return data;
}

// Validate the flow rate and set status accordingly
void validate_flow_rate(uint16_t flow_rate) {
    if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
        fprintf(stderr, "Flow rate out of range: %hu\n", flow_rate);
        return;
    }
}

// Write a message to the CSV file
void write_to_csv(const char *message) {
    if (csv_file == NULL) {
        return;
    }
    fprintf(csv_file, "%s\n", message);
}

// Handle SIGINT (Ctrl+C) for graceful shutdown
void handle_interrupt(int signum) {
    // Perform cleanup on SIGINT
    close(i2c_fd);
    fclose(csv_file);
    remove("cooling_log.csv");
    exit(EXIT_FAILURE); // Exit with failure to indicate an abnormal termination
}

