void handle_signal(int signum) {
    fprintf(stderr, "Signal %d received, exiting...\n", signum);
    exit(EXIT_FAILURE);
}

// Function to setup the GPIO for the flame sensor
void setup_sensor() {
    // Check if GPIO library is initialized
    if (gpiod_get_version() == NULL) {
        fprintf(stderr, "Failed to initialize libgpiod. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO device
    struct gpiod_device *gpiodev;
    if ((gpiodev = gpiod_get_device(GPIO_NUM)) == NULL) {
        fprintf(stderr, "Failed to open GPIO %d. Exiting...\n", GPIO_NUM);
