    }

    // Request the GPIO line
    if (gpiod_request_line(gpiodev, GPIO_OUTPUT_ONLY | GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request GPIO line. Exiting...\n");
        exit(EXIT_FAILURE);
    }

    // Cleanup GPIO device after use
    gpiod_unreserve_line(gpiodev, GPIO_NUM);
    gpiod_put_device(gpiodev);
}

