        }
        fprintf(file, "%s\n", timestamp);
        fclose(file);
    }
}

// Function to cleanup resources
void cleanup_resources() {
    // Release GPIO line
    gpiod_unreserve_line(gpiodev, GPIO_NUM);
    gpiod_put_device(gpiodev);
}

