#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <sys/signal.h>

#define TOUCH_SENSOR_GPIO 23
#define LED_GPIO 24
#define GPIO_CHIP "/dev/gpiochip4"
#define TOUCH_LOG_FILE "touch_log.txt"

// Function prototypes
void setup_gpios(void);
void cleanup_gpios(void);
void handle_touch_event(gpiod_event_t *event);
void handle_signal(int signum);
void toggle_led(int gpio);
void log_event(char *timestamp, int led_state);

int main(int argc, char *argv[]) {
    // Initialize GPIO chip and lines
    setup_gpios();

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Poll GPIO line events with a timeout
        gpiod_event_t event;
        int ret = gpiod_event_get(GPIOD, GPIO_CHIP, TOUCH_SENSOR_GPIO, GPIOD_EDGE_RISING, 1000, &event);
        if (ret < 0) {
            fprintf(stderr, "Error polling GPIO: %s\n", gpiod_error_string(ret));
            cleanup_gpios();
            exit(EXIT_FAILURE);
        }

        // Handle rising edge event
        handle_touch_event(&event);

        // Check for signals
        if (sigpending(&sa.sa_mask) != 0) {
            handle_signal(SIGINT);
            handle_signal(SIGTERM);
        }
    }

    // Cleanup GPIO resources
    cleanup_gpios();

    return 0;
}

// Function to setup GPIO lines
void setup_gpios(void) {
    int gpio23, gpio24;
    // Open GPIO chip
    int gpiochip_fd = open(GPIO_CHIP, O_RDWR);
    if (gpiochip_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    gpio23 = gpio_request(gpiochip_fd, TOUCH_SENSOR_GPIO);
    if (gpio23 == -1) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", TOUCH_SENSOR_GPIO, strerror(errno));
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    gpio24 = gpio_request(gpiochip_fd, LED_GPIO);
    if (gpio24 == -1) {
        fprintf(stderr, "Error requesting GPIO %d: %s\n", LED_GPIO, strerror(errno));
        gpio_unrequest(gpio23);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Set LED GPIO as output
    int ret = gpio_direction_output(gpiochip_fd, LED_GPIO, 1);
    if (ret != 0) {
        fprintf(stderr, "Error setting LED GPIO as output: %s\n", strerror(ret));
        gpio_unrequest(gpio23);
        gpio_unrequest(gpio24);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Log file setup
    FILE *touch_log_file = fopen(TOUCH_LOG_FILE, "a+");
    if (touch_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_unrequest(gpio23);
        gpio_unrequest(gpio24);
        close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup GPIO lines
void cleanup_gpios(void) {
    gpio_unrequest(gpio23);
    gpio_unrequest(gpio24);
    close(GPIOD);
}

// Function to handle a touch event
void handle_touch_event(gpiod_event_t *event) {
    // Get the current time
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);

    // Format ISO 8601 timestamp
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    // Toggle LED state based on touch event
    int led_state = (event->value == 1) ? 1 : 0;

    // Log the event
    log_event(timestamp, led_state);

    // Toggle the LED
    toggle_led(LED_GPIO);
}

// Function to toggle the LED state
void toggle_led(int gpio) {
    int current_state;
    // Read current state of the LED GPIO
    if (gpio_read(gpiochip_fd, LED_GPIO, &current_state) == 0) {
        // Toggle the state
        int new_state = !current_state;
        if (gpio_write(gpiochip_fd, LED_GPIO, new_state) == 0) {
            // Successfully toggled
        } else {
            fprintf(stderr, "Error toggling LED GPIO: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Error reading LED GPIO: %s\n", strerror(errno));
    }
}

// Function to log an event with timestamp and LED state
void log_event(char *timestamp, int led_state) {
    fprintf(touch_log_file, "%s, LED state: %d\n", timestamp, led_state);
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up and exit
    fclose(touch_log_file);
    cleanup_gpios();
    exit(EXIT_SUCCESS);
}

