#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <libgpiod/gpiod.h>

#define TOUCH_GPIO 4
#define LED_GPIO 17
#define TOUCH_DEBOUNCE_MS 200
#define POLL_INTERVAL_MS 10

FILE *touch_log_file = NULL;
gpiod_device *touch_sensor_device = NULL;
gpiod_channel *touch_sensor_channel = NULL;
gpiod_channel *led_channel = NULL;

void setup_gpios() {
    int rc;

    // Initialize GPIO library
    rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }

    // Open GPIO devices
    touch_sensor_device = gpiod_get_device_by_name("gpiochip0");
    if (!touch_sensor_device) {
        fprintf(stderr, "Error getting GPIO chip: %s\n", gpiod_errstr(gpiod_error()));
        exit(EXIT_FAILURE);
    }

    touch_sensor_channel = gpiod_get_channel(touch_sensor_device, TOUCH_GPIO);
    if (!touch_sensor_channel) {
        fprintf(stderr, "Error getting GPIO channel for touch sensor: %s\n", gpiod_errstr(gpiod_error()));
        exit(EXIT_FAILURE);
    }

    led_channel = gpiod_get_channel(touch_sensor_device, LED_GPIO);
    if (!led_channel) {
        fprintf(stderr, "Error getting GPIO channel for LED: %s\n", gpiod_errstr(gpiod_error()));
        exit(EXIT_FAILURE);
    }

    // Set LED GPIO as output
    rc = gpiod_set_direction(touch_sensor_device, LED_GPIO, GPIOD_OUT_HIGH);
    if (rc != 0) {
        fprintf(stderr, "Error setting LED GPIO direction: %s\n", gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }

    // Set touch sensor GPIO as input
    rc = gpiod_set_direction(touch_sensor_device, TOUCH_GPIO, GPIOD_IN_OPEN_DRAIN);
    if (rc != 0) {
        fprintf(stderr, "Error setting touch sensor GPIO direction: %s\n", gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Turn off the LED
        rc = gpiod_set_value(touch_sensor_device, LED_GPIO, 0);
        if (rc != 0) {
            fprintf(stderr, "Error turning off LED: %s\n", gpiod_errstr(rc));
        }

        // Close the log file
        if (touch_log_file) {
            fclose(touch_log_file);
            touch_log_file = NULL;
        }

        // Clean up GPIO resources
        gpiod_channel_free(touch_sensor_channel);
        gpiod_channel_free(led_channel);
        gpiod_device_free(touch_sensor_device);

        printf("Signal received, shutting down.\n");
        exit(EXIT_SUCCESS);
    }
}

void poll_and_handle_touch() {
    struct timespec timeout;
    struct timespec now;
    time_t timestamp;
    int rc;

    // Initialize timeout
    timeout.tv_sec = 0;
    timeout.tv_nsec = POLL_INTERVAL_MS * 1000000;

    // Get current time
    time(&timestamp);
    now = (struct timespec){ .tv_sec = timestamp, .tv_nsec = 0 };

    // Wait for GPIO4 to go HIGH (rising edge)
    rc = gpiod_channel_poll_for_edge(touch_sensor_channel, GPIOD_EDGE_RISING, &timeout, &now);
    if (rc == -1) {
        fprintf(stderr, "Error polling for touch sensor edge: %s\n", gpiod_errstr(rc));
        return;
    }

    // Software debounce
    if (gpiod_channel_get_value(touch_sensor_channel) == 0) {
        // Debounce logic
        struct timespec debounce_timeout;
        debounce_timeout.tv_sec = TOUCH_DEBOUNCE_MS / 1000;
        debounce_timeout.tv_nsec = 0;

        rc = gpiod_channel_poll_for_value(touch_sensor_channel, GPIOD_VALUE_LOW, &debounce_timeout, NULL);
        if (rc == -1) {
            fprintf(stderr, "Error debouncing touch sensor: %s\n", gpiod_errstr(rc));
            return;
        }

        // Ensure the debounce logic worked
        if (gpiod_channel_get_value(touch_sensor_channel) == 1) {
            // Valid touch detected
            char timestamp_str[50];
            time_t now_timestamp;

            // Get current time
            time(&now_timestamp);
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%3nz", localtime(&now_timestamp));

            // Append to log file
            if (!touch_log_file) {
                fprintf(stderr, "Could not open touch_log.txt for writing.\n");
                return;
            }
            fprintf(touch_log_file, "%s\n", timestamp_str);

            // Toggle the LED
            rc = gpiod_set_value(touch_sensor_device, LED_GPIO, 1 - gpiod_channel_get_value(touch_sensor_channel));
            if (rc != 0) {
                fprintf(stderr, "Error toggling LED: %s\n", gpiod_errstr(rc));
            }
        }
    }
}

int main() {
    setup_gpios();

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        poll_and_handle_touch();
    }

    return 0;
}

