#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <libgpiod/gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

// Constants for GPIO pins
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27

// Sensor identifiers
#define SENSOR_1 1
#define SENSOR_2 2
#define SENSOR_3 3

// GPIO mode constants
#define GPIO_MODE_IN 0x01
#define GPIO_PULL_UP 0x02

// Function prototypes
void setup_gpios(void);
void poll_sensors_and_log(const char *sensor_id);
void handle_signal(int signum);
void cleanup(void);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        poll_sensors_and_log(SENSOR_1);
        poll_sensors_and_log(SENSOR_2);
        poll_sensors_and_log(SENSOR_3);
        usleep(100000); // 100 ms delay
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    // Open GPIO device
    int gpio_dev = open("/dev/gpiomem", O_RDWR);
    if (gpio_dev < 0) {
        fprintf(stderr, "Error opening GPIO device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins
    struct gpiod_dir_config dir_config[3] = {
        GPIOD_DIR_IN | GPIO_PULL_UP,
        GPIOD_DIR_IN | GPIO_PULL_UP,
        GPIOD_DIR_IN | GPIO_PULL_UP
    };

    for (int i = 0; i < 3; ++i) {
        if (gpiod_set_direction(gpio_dev, GPIO4 + i, dir_config[i]) != 0) {
            fprintf(stderr, "Error setting direction for GPIO %d: %s\n", GPIO4 + i, gpiod_get_name(gpio_dev, GPIO4 + i));
            gpiod_close(gpio_dev);
            exit(EXIT_FAILURE);
        }
    }

    gpiod_close(gpio_dev);
}

// Function to poll sensors and log state changes
void poll_sensors_and_log(const char *sensor_id) {
    // Open log file
    int log_fd = open("magnet_log.txt", O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Read initial state without triggering a transition
    unsigned int initial_state = 0;
    if (gpiod_get_value_array(gpio_dev, GPIO4 + SENSOR_ID_TO_GPIO(sensor_id), 1, &initial_state) != 1) {
        fprintf(stderr, "Error reading initial state for sensor %s: %s\n", sensor_id, gpiod_get_name(gpio_dev, GPIO4 + SENSOR_ID_TO_GPIO(sensor_id)));
        close(log_fd);
        exit(EXIT_FAILURE);
    }

    // Log initial state
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
    fprintf(log_fd, "[Initial] Sensor %s: %u\n", sensor_id, initial_state);
    fflush(log_fd);

    // Poll and log state changes
    while (1) {
        unsigned int current_state;
        if (gpiod_get_value(gpio_dev, GPIO4 + SENSOR_ID_TO_GPIO(sensor_id), &current_state) != 1) {
            fprintf(stderr, "Error reading sensor %s: %s\n", sensor_id, gpiod_get_name(gpio_dev, GPIO4 + SENSOR_ID_TO_GPIO(sensor_id)));
            break;
        }

        if (current_state != initial_state) {
            char buffer[256];
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
            fprintf(log_fd, "[%s] Sensor %s: %u -> %u\n", buffer, sensor_id, initial_state, current_state);
            fflush(log_fd);
        }

        usleep(100000); // 100 ms delay
    }

    // Close log file on exit
    close(log_fd);
}

// Signal handler for SIGINT and SIGTERM
void handle_signal(int signum) {
    // Clean shutdown
    poll_sensors_and_log("shutdown");
    gpiod_release(gpio_dev);
    exit(EXIT_SUCCESS);
}

// Function to clean up resources
void cleanup(void) {
    // Close GPIO device if it's still open
    gpiod_release(gpio_dev);
}

// Mapping from sensor ID to GPIO pin
static const int SENSOR_ID_TO_GPIO[3] = {
    GPIO4, GPIO17, GPIO27
};

