        if (current_state != initial_state) {
            char buffer[256];
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&time(NULL)));
            fprintf(log_fd, "[%s] Sensor %s: %u -> %u\n", buffer, sensor_id, initial_state, current_state);
