void write_i2c(uint8_t addr, uint8_t reg, uint8_t value);
int read_i2c(uint8_t addr, uint8_t reg, uint8_t *data, size_t len);
void moving_average(uint16_t *data, size_t size, uint16_t *avg);
void validate_bpm(uint16_t bpm);
void append_to_file(const char *timestamp, uint16_t bpm);
void cleanup();

int main() {
    srand(time(NULL));

    // Initialize gpiod
    init_gpiod();

    // Open the I2C file for writing
    int i2c_fd = open_i2c_file(FILE_PATH, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);

    if (i2c_fd == -1) {
        perror("Failed to open I2C file");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    struct gpiod_i2c_bus *i2c_bus = gpiod_i2c_bus_open(I2C_BUS_NUM);
    if (!i2c_bus) {
        perror("Failed to open I2C bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Expected sensor values
    uint8_t expected_part_id = SI1182_PART_ID;
    uint8_t expected_hw_rev = SI1182_HW_REV;

    // Main loop
    while (1) {
        // Read sensor part ID and hardware revision
        uint8_t part_id;
        uint8_t hw_rev;
        if ((read_i2c(SI1182_ADDR, 0x00, &part_id, 1) < 1) ||
            (read_i2c(SI1182_ADDR, 0x01, &hw_rev, 1) < 1)) {
            fprintf(stderr, "Failed to read sensor ID and revision\n");
            break;
        }

        if (part_id != expected_part_id || hw_rev != expected_hw_rev) {
            fprintf(stderr, "Sensor ID or revision does not match expected values\n");
            break;
        }

        // Read heart rate data
        uint16_t raw_hrt;
        if ((read_i2c(SI1182_ADDR, 0x02, &raw_hrt, 2) < 1) ||
            (raw_hrt > 0xFFFF || raw_hrt < 0)) {
            fprintf(stderr, "Failed to read heart rate data\n");
            continue;
        }

        // Apply moving average filter
        uint16_t avg;
        moving_average(&raw_hrt, BUFFER_SIZE, &avg);

        // Validate BPM
        validate_bpm(avg);

        // Append to file
        char timestamp[21];
