        struct tm *timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S,", timeinfo);
        append_to_file(timestamp, avg);

        // Close I2C file and exit on SIGINT
        if (WIFSIGNALED(getpid(), SIGINT)) {
            fprintf(stderr, "Caught SIGINT, exiting gracefully...\n");
            cleanup();
            exit(EXIT_SUCCESS);
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to initialize gpiod
void init_gpiod() {
    int ret = gpiod_bus_add_driver(&gpiod_i2c_bus_driver);
    if (ret < 0) {
        fprintf(stderr, "Failed to add gpiod_i2c bus driver: %s\n", gpiod_err2str(ret));
        exit(EXIT_FAILURE);
    }
}

// Function to open I2C file for writing
int open_i2c_file(const char *filename, mode_t mode, uint32_t perms) {
    int fd = open(filename, mode, perms);
    if (fd == -1) {
        perror("open");
        return -1;
    }
    return fd;
}

// Function to write to I2C device
void write_i2c(uint8_t addr, uint8_t reg, uint8_t value) {
    int ret = gpiod_i2c_bus_write(gpiod_i2c_bus, addr, reg, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", gpiod_err2str(ret));
    }
}

// Function to read from I2C device
int read_i2c(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = gpiod_i2c_bus_read(gpiod_i2c_bus, addr, reg, data, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C: %s\n", gpiod_err2str(ret));
        return -1;
    }
    return ret;
}

// Function to compute moving average
void moving_average(uint16_t *data, size_t size, uint16_t *avg) {
    uint16_t sum = 0;
    for (size_t i = 0; i < size; ++i) {
        sum += data[i];
    }
    *avg = sum / size;
}

// Function to validate BPM
void validate_bpm(uint16_t bpm) {
    if (bpm < 30 || bpm > 220) {
        fprintf(stderr, "Invalid BPM: %hu\n", bpm);
        return;
    }
}

// Function to clean up resources
void cleanup() {
    // Close I2C file
    close(i2c_fd);

    // Close I2C bus
    gpiod_i2c_bus_close(&gpiod_i2c_bus);

    // Release gpiod resources
    gpiod_bus_remove_driver(&gpiod_i2c_bus_driver);
}

