#define TOUCH_SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define OUTPUT_COUNTER_PINS {17, 18, 19, 20, 21, 22, 23, 24}
#define TOUCH_SENSOR_COUNT 8
#define OUTPUT_COUNTER_BITS 8

FILE *touch_log_file = NULL;
gpiod_device *touch_sensor_device = NULL;
gpiod_array *touch_sensor_array = NULL;
gpiod_array *output_counter_array = NULL;

void initialize_resources() {
    touch_log_file = fopen("touch_log.txt", "a+");
    if (touch_log_file == NULL) {
        fprintf(stderr, "Failed to open touch_log.txt for appending: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    touch_sensor_device = gpiod_get_device_by_name("ttdc,ttdc0");
    if (touch_sensor_device == NULL) {
        fprintf(stderr, "Failed to find TTP226 touch sensor device: %s\n", gpiod_error_str(gpiod_error_get()));
        exit(EXIT_FAILURE);
    }

    touch_sensor_array = gpiod_array_new_from_device(touch_sensor_device, TOUCH_SENSOR_COUNT);
    if (touch_sensor_array == NULL) {
        fprintf(stderr, "Failed to create touch sensor array: %s\n", gpiod_error_str(gpiod_error_get()));
        gpiod_array_free(touch_sensor_array);
        exit(EXIT_FAILURE);
    }

    output_counter_array = gpiod_array_new(TOUCH_SENSOR_COUNT);
    if (output_counter_array == NULL) {
        fprintf(stderr, "Failed to create output counter array: %s\n", gpiod_error_str(gpiod_error_get()));
        gpiod_array_free(output_counter_array);
        gpiod_array_free(touch_sensor_array);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < TOUCH_SENSOR_COUNT; i++) {
        int pin = TOUCH_SENSOR_PINS[i];
        gpiod_array_set_pin(touch_sensor_array, i, pin);
        gpiod_array_set_direction(touch_sensor_array, i, GPIOD_DIR_INPUT);
    }

    for (int i = 0; i < OUTPUT_COUNTER_BITS; i++) {
        int pin = OUTPUT_COUNTER_PINS[i];
        gpiod_array_set_pin(output_counter_array, i, pin);
        gpiod_array_set_direction(output_counter_array, i, GPIOD_DIR_OUTPUT);
    }
}

void cleanup_resources() {
    if (touch_sensor_array != NULL) {
