        return EXIT_FAILURE;
    }

    // Open CSV file for writing
    const char *csv_file_path = "tracking_log.csv";
    int fd = fopen(csv_file_path, "a+");
    if (fd == -1) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Write header if file does not exist
    if (fseek(fd, 0, SEEK_SET) == -1 || fprintf(fd, "timestamp,sensor1,sensor2,sensor3,sensor4\n") == -1) {
        fclose(fd);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    struct timespec timestamp;
    time_t now = time(NULL);
    if (clock_gettime(CLOCK_REALTIME, &timestamp) == -1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        fclose(fd);
        gpiod_exit();
        return EXIT_FAILURE;
    }

