            gpiod_c_read(GPIO18, GPIOD_DIR_IN, buffer + 1, 1) < 0 ||
            gpiod_c_read(GPIO27, GPIOD_DIR_IN, buffer + 2, 1) < 0 ||
            gpiod_c_read(GPIO22, GPIOD_DIR_IN, buffer + 3, 1) < 0) {
            fprintf(stderr, "Error reading sensors: %s\n", gpiod_get_name(gpiod_get_error()));
            continue;
        }

        // Read sensor values
        int sensor1 = buffer[0];
        int sensor2 = buffer[1];
        int sensor3 = buffer[2];
        int sensor4 = buffer[3];

        // Write to CSV file
        if (fprintf(fd, "%ld,%d,%d,%d,%d\n", timestamp.tv_sec, sensor1, sensor2, sensor3, sensor4) == -1) {
            fclose(fd);
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Sleep for 100ms
        usleep(POLL_INTERVAL_MS * 1000);

        // Check for signals
        if (waitpid(-1, NULL, WUNTRACED) == -1) {
            perror("waitpid");
            break; // Exit on receiving SIGINT or SIGTERM
        }
    }

    // Cleanup
    fclose(fd);
    gpiod_exit();

    return EXIT_SUCCESS;
