#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

#define DEBOUNCE_MS 50
#define POLL_MS 100

const char *sensor_names[] = {"Sensor 1", "Sensor 2"};

void setup_gpios(void) {
    int sensor1_fd, sensor2_fd;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open(GPIOD_CHIP_OMRON_D7E_5, GPIOD_OPEN_READONLY);
    if (!chip) {
        fprintf(stderr, "Failed to open Omron D7E-5 chip.\n");
        exit(EXIT_FAILURE);
    }

    sensor1_fd = gpiod_line_request_active_low(chip, SENSOR_1_GPIO, GPIOD_LINE_BIAS_PULLUP);
    if (sensor1_fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input with pull-up.\n", SENSOR_1_GPIO);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor2_fd = gpiod_line_request_active_low(chip, SENSOR_2_GPIO, GPIOD_LINE_BIAS_PULLUP);
    if (sensor2_fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input with pull-up.\n", SENSOR_2_GPIO);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_config(sensor1_fd, GPIOD_LINE_CONFIG_INPUT);
    gpiod_line_config(sensor2_fd, GPIOD_LINE_CONFIG_INPUT);
}

void handle_signals(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        gpiod_line_release(sensor1_fd);
        gpiod_line_release(sensor2_fd);
        gpiod_chip_close(gpiod_chip_get_default());
        close(STDOUT_FILENO);
        close(STDERR_FILENO);
        close(STDIN_FILENO);
        unlink("/var/log/tilt_events.log");
        exit(EXIT_SUCCESS);
    }
}

void poll_sensors_and_log(void) {
    struct timespec timestamp;
    struct stat statbuf;
    char buffer[64];
    int sensor1_value, sensor2_value;

    time(&timestamp);
    stat("/var/log/tilt_events.log", &statbuf);

    sensor1_value = gpiod_read(sensor1_fd, 1);
    sensor2_value = gpiod_read(sensor2_fd, 1);

    if (sensor1_value == 0 || sensor2_value == 0) {
        snprintf(buffer, sizeof(buffer), "%04d-%02d-%02d %02d:%02d:%02d, %s tilted\n",
                 timestamp.tv_year + 1900, timestamp.tv_mon + 1, timestamp.tv_mday,
                 timestamp.tv_hour, timestamp.tv_min, timestamp.tv_sec,
                 sensor_names[sensor1_value == 0 ? 0 : 1]);
        if (write(STDOUT_FILENO, buffer, strlen(buffer)) != strlen(buffer)) {
            perror("Failed to write to log");
            exit(EXIT_FAILURE);
        }
    }

    gpiod_read(sensor1_fd, 1);
    gpiod_read(sensor2_fd, 1);
}

int main(void) {
    setup_gpios();

    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    while (1) {
        poll_sensors_and_log();
        usleep(POLL_MS * 1000); // Wait for 100 ms
    }

    return 0;
}

