#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <libgpiod/gpiod.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LED_GPIO 22

#define SENSOR_1_PIN -1
#define SENSOR_2_PIN -1
#define LED_PIN -1

volatile int led_state = 0;

FILE *log_file = NULL;
char log_filename[] = "obstacle_log.csv";

void setup_gpios() {
    int rc;

    // Initialize GPIO controller
    rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "gpiod_init() failed: %s\n", gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }

    // Open GPIO pins
    rc = gpiod_open(GPIO_NUM_TO_DEV(SENSOR_1_GPIO), GPIOD_OPEN_RWC);
    if (rc != 0) {
        fprintf(stderr, "gpiod_open(GPIO%d) failed: %s\n", SENSOR_1_GPIO, gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }
    gpiod_set_data_direction(SENSOR_1_PIN, GPIOD_DATA_IN);

    rc = gpiod_open(GPIO_NUM_TO_DEV(SENSOR_2_GPIO), GPIOD_OPEN_RWC);
    if (rc != 0) {
        fprintf(stderr, "gpiod_open(GPIO%d) failed: %s\n", SENSOR_2_GPIO, gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }
    gpiod_set_data_direction(SENSOR_2_PIN, GPIOD_DATA_IN);

    rc = gpiod_open(GPIO_NUM_TO_DEV(LED_GPIO), GPIOD_OPEN_OUT_INIT_HIGH);
    if (rc != 0) {
        fprintf(stderr, "gpiod_open(GPIO%d) failed: %s\n", LED_GPIO, gpiod_errstr(rc));
        exit(EXIT_FAILURE);
    }
    gpiod_set_data_direction(LED_PIN, GPIOD_DATA_OUT);

    log_file = fopen(log_filename, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", log_filename);
        exit(EXIT_FAILURE);
    }
}

void read_sensors() {
    int sensor1_value, sensor2_value;

    // Read sensor values
    sensor1_value = gpiod_read(SENSOR_1_PIN);
    sensor2_value = gpiod_read(SENSOR_2_PIN);

    // Treat sensors as active-low
    if (sensor1_value == 0 && sensor2_value == 0) {
        led_state = 1;
    } else {
        led_state = 0;
    }
}

void write_log_entry(char *timestamp, int sensor1, int sensor2, int led_state) {
    char entry[256];
    sprintf(entry, "%s,%d,%d,%d", timestamp, sensor1, sensor2, led_state);
    fprintf(log_file, "%s\n", entry);
    fflush(log_file);
}

void graceful_shutdown() {
    // Turn off the LED
    gpiod_set_value(LED_PIN, 0);

    // Release all line resources
    gpiod_unexport_all();

    // Close the GPIO chip
    gpiod_exit();

    // Close the log file
    fclose(log_file);
}

void poll_and_log() {
    struct timespec ts;
    time_t now = time(NULL);
    ts.tv_sec = now;
    ts.tv_nsec = 0;

    // Poll sensors and log data
    read_sensors();
    write_log_entry((char *)(&ts), sensor1_value, sensor2_value, led_state);

    // Sleep for 100ms
    nanosleep(&ts, NULL);
}

int main() {
    setup_gpios();

    signal(SIGINT, graceful_shutdown);

    while (1) {
        poll_and_log();
    }

    return 0;
}

