#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpiod.h>

#define MIC_GPIO_NUM 4 // GPIO4 (BCM 7, physical pin 7)
#define LED_GPIO_NUM 17 // GPIO17 (BCM 11, physical pin 11)
#define SAMPLE_RATE_HZ 8000 // Desired sampling rate
#define SAMPLE_PERIOD_US 125 // 125 microseconds for 8kHz
#define PEAK_DETECTION_THRESHOLD 100 // Arbitrary threshold for sound peak detection

volatile sig_atomic_t should_exit = 0;

// Function prototypes
void setup_gpios(void);
void poll_mic_and_detect_peaks(void);
void handle_signal(int signum);
void cleanup_and_exit(void);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Main loop
    while (!should_exit) {
        poll_mic_and_detect_peaks();
        usleep(SAMPLE_PERIOD_US * 1000); // Wait for the next sample period
    }

    // Clean up and exit
    cleanup_and_exit();
    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    struct gpiod_dir_config dir_config;
    struct gpiod_set_config set_config;

    // Initialize GPIO for the microphone input
    if (gpiod_direction_input(MIC_GPIO_NUM) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO %d as input.\n", MIC_GPIO_NUM);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for the LED output
    if (gpiod_direction_output(LED_GPIO_NUM, 1) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO %d as output.\n", LED_GPIO_NUM);
        exit(EXIT_FAILURE);
    }

    // Set the LED pin to low initially
    if (gpiod_write(LED_GPIO_NUM, 0) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d.\n", LED_GPIO_NUM);
        exit(EXIT_FAILURE);
    }
}

// Function to poll the microphone and detect peaks
void poll_mic_and_detect_peaks(void) {
    struct timespec timestamp;
    struct timespec curr_time;
    int mic_value;
    int peak_detected = 0;

    // Get current time
    clock_gettime(CLOCK_REALTIME, &curr_time);

    // Poll the microphone GPIO
    mic_value = gpiod_read(MIC_GPIO_NUM);

    // Check if the mic value indicates a sound peak
    if (mic_value && peak_detected < 10) { // Arbitrary threshold for detecting multiple peaks
        peak_detected++;
        // Print millisecond-precision timestamp
        timestamp.tv_sec = curr_time.tv_sec;
        timestamp.tv_nsec = (curr_time.tv_nsec + SAMPLE_PERIOD_US * 1000000L) % 1000000000L;
        printf("Sound peak detected at: %ld.%06ld\n", timestamp.tv_sec, timestamp.tv_nsec / 1000000);

        // Turn on the LED for 100 ms
        if (gpiod_set_value(LED_GPIO_NUM, 1) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d to high.\n", LED_GPIO_NUM);
        } else {
            usleep(100000); // Wait for 100 ms
            if (gpiod_set_value(LED_GPIO_NUM, 0) != 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d to low.\n", LED_GPIO_NUM);
            }
        }
    }

    // Handle SIGINT
    if (should_exit) {
        // Turn off the LED if it was on
        if (gpiod_get_value(LED_GPIO_NUM) == 1) {
            if (gpiod_set_value(LED_GPIO_NUM, 0) != 0) {
                fprintf(stderr, "Error: Failed to set GPIO %d to low.\n", LED_GPIO_NUM);
            }
        }

        // Clean up and exit
        cleanup_and_exit();
        return;
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    should_exit = 1;
}

// Function to clean up and exit
void cleanup_and_exit(void) {
    // Shutdown GPIO operations
    gpiod_unconfig(MIC_GPIO_NUM);
    gpiod_unconfig(LED_GPIO_NUM);

    // Ensure no further execution
    exit(EXIT_SUCCESS);
}

