#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

// GPIO pin numbers for SunFounder 3-Way Tracing Sensor
#define GPIO_LEFT_SENSOR 17
#define GPIO_CENTER_SENSOR 27
#define GPIO_RIGHT_SENSOR 22

// GPIO mode constants
#define GPIO_INPUT 0
#define GPIO_ACTIVE_LOW 1
#define GPIO_PULL_UP 2

// Function prototypes
void setup_gpios(void);
void read_sensors_and_log(void);
void cleanup_resources(void);
void handle_signal(int signum);

int main(void) {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Attempt to set up GPIO pins
    if (setup_gpios()) {
        // Main loop until interrupted
        while (1) {
            read_sensors_and_log();
            usleep(100000); // Sleep for 100 ms
        }
    } else {
        // Clean up and exit on error
        cleanup_resources();
        fprintf(stderr, "Error setting up GPIO pins.\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    struct gpiod_dir gpio_dir[3];
    struct gpiod_set gpio_set[3];

    // Initialize GPIO directories
    for (int i = 0; i < 3; i++) {
        gpio_dir[i].dev = gpiod_get_device(GPIO_PIN_TO_DEV_ID(i));
        if (!gpio_dir[i].dev) {
            fprintf(stderr, "Error getting GPIO device for pin %d\n", GPIO_PIN_TO_NUM(i));
            return 0; // Return on failure
        }

        gpio_set[i].dir = GPIO_INPUT;
        gpio_set[i].flags = GPIO_ACTIVE_LOW | GPIO_PULL_UP;
        if (gpiod_set_value(gpio_dir[i].dev, &gpio_set[i])) {
            fprintf(stderr, "Error setting GPIO %d flags\n", GPIO_PIN_TO_NUM(i));
            return 0; // Return on failure
        }
    }

    // Success
    printf("GPIO pins configured successfully.\n");
}

// Function to read sensors and log the states
void read_sensors_and_log(void) {
    int left_state, center_state, right_state;

    // Read sensor states
    if (gpiod_get_value_array(gpiod_get_device(GPIO_PIN_TO_DEV_ID(GPIO_LEFT_SENSOR)),
                             1, &left_state) < 0) {
        fprintf(stderr, "Error reading left sensor value\n");
        return;
    }

    if (gpiod_get_value_array(gpiod_get_device(GPIO_PIN_TO_DEV_ID(GPIO_CENTER_SENSOR)),
                             1, &center_state) < 0) {
        fprintf(stderr, "Error reading center sensor value\n");
        return;
    }

    if (gpiod_get_value_array(gpiod_get_device(GPIO_PIN_TO_DEV_ID(GPIO_RIGHT_SENSOR)),
                             1, &right_state) < 0) {
        fprintf(stderr, "Error reading right sensor value\n");
        return;
    }

    // Log states to console
    printf("Left sensor: %d, Center sensor: %d, Right sensor: %d\n", left_state, center_state, right_state);
}

// Function to cleanup resources
void cleanup_resources(void) {
    for (int i = 0; i < 3; i++) {
        gpiod_remove(gpio_dir[i].dev);
    }
}

// Signal handler to gracefully exit on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Clean up resources
    cleanup_resources();

    // Exit the program
    exit(EXIT_SUCCESS);
}

