#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS_NUM 1
#define SI1175_ADDR 0x5C
#define SI1175_REG_LSB 0x00
#define SI1175_REG_MSB 0x01

#define INTERVAL_MS 100

// Function prototypes
void setup_i2c(void);
int read_si1175(uint8_t addr, uint8_t reg, uint16_t *data);
void cleanup(void);

int main(void) {
    struct sigaction sa;
    int fd, ret;
    uint16_t raw_reading;
    struct timeval start, diff;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    setup_i2c();

    // Main loop
    while (1) {
        // Start timer
        gettimeofday(&start, NULL);

        // Read sensor data
        ret = read_si1175(SI1175_ADDR, SI1175_REG_LSB, &raw_reading);
        if (ret != 2) {
            fprintf(stderr, "Error reading from SI1175: %d\n", ret);
            continue;
        }

        // Combine LSB and MSB
        raw_reading = (raw_reading << 8) | read_si1175(SI1175_ADDR, SI1175_REG_MSB, NULL);

        // Log reading
        printf("Raw reading: %04X\n", raw_reading);

        // End timer
        gettimeofday(&diff, NULL);
        double elapsed_ms = (double)(diff.tv_sec * 1000 + diff.tv_usec / 1000) - (double)(start.tv_sec * 1000 + start.tv_usec / 1000);
        if (elapsed_ms >= INTERVAL_MS) {
            // Log every 100ms
            printf("Interval: %.1f ms\n", elapsed_ms);
        }

        // Sleep to avoid excessive CPU usage
        usleep(10000);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to setup I2C
void setup_i2c(void) {
    int fd;

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("open /dev/i2c-1");
        exit(EXIT_FAILURE);
    }

    // Check if device is present
    if (gpiod_i2c_read(fd, SI1175_ADDR, 1, NULL) != 1) {
        fprintf(stderr, "SI1175 not found on I2C bus 1\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // No further initialization needed for libgpiod
}

// Function to read from SI1175
int read_si1175(uint8_t addr, uint8_t reg, uint16_t *data) {
    int ret;

    // Write register address
    ret = gpiod_i2c_write(addr, reg, 1, NULL);
    if (ret != 1) {
        return ret;
    }

    // Read data
    ret = gpiod_i2c_read(addr, reg, 2, data);
    if (ret != 2) {
        return ret;
    }

    return 0;
}

// Function to cleanup resources
void cleanup(void) {
    if (fd != -1) {
        close(fd);
        fd = -1;
    }
}

