#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

volatile sig_atomic_t should_exit = 0;

void handle_SIGINT(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize gpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errmsg());
        return EXIT_FAILURE;
    }

    // Register SIGINT handler
    struct sigaction sa;
    sa.sa_handler = handle_SIGINT;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Poll GPIO pins every 100ms
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100000 };
        if (gpiod_poll(&timeout) < 0) {
            fprintf(stderr, "Failed to poll GPIO: %s\n", gpiod_errmsg());
            gpiod_exit();
            return EXIT_FAILURE;
        }

        // Open GPIO devices
        int left_device = gpiod_get_device_by_number(LEFT_PIN);
        int middle_device = gpiod_get_device_by_number(MIDDLE_PIN);
        int right_device = gpiod_get_device_by_number(RIGHT_PIN);

        // Check if devices are present
        if (left_device == -1 || middle_device == -1 || right_device == -1) {
            fprintf(stderr, "One or more GPIO devices not found.\n");
            continue;
        }

        // Request GPIO lines for input
        if (gpiod_request_line(left_device, GPIOD_OUT_INIT_LOW) < 0) {
            fprintf(stderr, "Failed to request left GPIO line: %s\n", gpiod_errmsg());
            gpiod_unrequest_line(left_device, GPIOD_LINE_LEFT);
            gpiod_unrequest_all(left_device);
            gpiod_release_device(left_device);
            continue;
        }
        if (gpiod_request_line(middle_device, GPIOD_OUT_INIT_LOW) < 0) {
            fprintf(stderr, "Failed to request middle GPIO line: %s\n", gpiod_errmsg());
            gpiod_unrequest_line(middle_device, GPIOD_LINE_MIDDLE);
            gpiod_unrequest_all(middle_device);
            gpiod_release_device(middle_device);
            continue;
        }
        if (gpiod_request_line(right_device, GPIOD_OUT_INIT_LOW) < 0) {
            fprintf(stderr, "Failed to request right GPIO line: %s\n", gpiod_errmsg());
            gpiod_unrequest_line(right_device, GPIOD_LINE_RIGHT);
            gpiod_unrequest_all(right_device);
            gpiod_release_device(right_device);
            continue;
        }

        // Read GPIO line values
        int left_value = gpiod_get_value(left_device, GPIOD_LINE_LEFT);
        int middle_value = gpiod_get_value(middle_device, GPIOD_LINE_MIDDLE);
        int right_value = gpiod_get_value(right_device, GPIOD_LINE_RIGHT);

        // Check if reads were successful
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", gpiod_errmsg());
            gpiod_unrequest_line(left_device, GPIOD_LINE_LEFT);
            gpiod_unrequest_line(middle_device, GPIOD_LINE_MIDDLE);
            gpiod_unrequest_line(right_device, GPIOD_LINE_RIGHT);
            gpiod_unrequest_all(left_device);
            gpiod_unrequest_all(middle_device);
            gpiod_unrequest_all(right_device);
            gpiod_release_device(left_device);
            gpiod_release_device(middle_device);
            gpiod_release_device(right_device);
            continue;
        }

        // Log sensor values
        char buffer[256];
        sprintf(buffer, "L:%d M:%d R:%d", left_value, middle_value, right_value);
        printf("%s\n", buffer);

        // Release resources
        gpiod_unrequest_line(left_device, GPIOD_LINE_LEFT);
        gpiod_unrequest_line(middle_device, GPIOD_LINE_MIDDLE);
        gpiod_unrequest_line(right_device, GPIOD_LINE_RIGHT);
        gpiod_unrequest_all(left_device);
        gpiod_unrequest_all(middle_device);
        gpiod_unrequest_all(right_device);
        gpiod_release_device(left_device);
        gpiod_release_device(middle_device);
        gpiod_release_device(right_device);
    }

    // Clean up on exit
    gpiod_exit();

    return EXIT_SUCCESS;
}

