#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod/gpiod.h>

// Define GPIO pins for TTP226 touch sensor
#define GPIO5 5
#define GPIO6 6
#define GPIO13 13
#define GPIO19 19
#define GPIO26 26
#define GPIO12 12
#define GPIO16 16
#define GPIO20 20

// Function prototypes
void handle_signal(int signum);
int open_ttp226();
void read_ttp226();
void close_ttp226();
void free_gpiod_resource(gpiod_resource_t *resource);

// Main function
int main() {
    // Initialize signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Attempt to open the TTP226 chip
    gpiod_resource_t *chip_resource = NULL;
    int ret = open_ttp226(&chip_resource);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to open TTP226 chip.\n");
        exit(1);
    }

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read the TTP226 chip
        read_ttp226();

        // Sleep for 200ms
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 200000000 };
        nanosleep(&ts, NULL);
    }

    // Close and free resources
    close_ttp226(chip_resource);
    free_gpiod_resource(chip_resource);

    return 0;
}

// SIGINT/SIGTERM handler
void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down gracefully...\n", signum);
    // Perform cleanup here if necessary
    close_ttp226(NULL);
    free_gpiod_resource(NULL);
    exit(0);
}

// Function to open the TTP226 chip
int open_ttp226(gpiod_resource_t **chip_resource) {
    int ret;
    *chip_resource = gpiod_chip_open("ttp226", GPIOD_OPEN_READONLY);
    if (*chip_resource == NULL) {
        fprintf(stderr, "Error: Failed to open TTP226 chip.\n");
        return -1;
    }
    ret = gpiod_chip_request_line(*chip_resource, GPIO5, GPIOD_LINE_IN);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to request line GPIO5.\n");
        gpiod_chip_close(*chip_resource);
        *chip_resource = NULL;
        return -1;
    }

    // Repeat for other lines
    // ... (similar code for GPIO6, GPIO13, etc.)

    return 0;
}

// Function to read the TTP226 chip
void read_ttp226() {
    int ret;
    for (int i = 0; i < 8; i++) {
        // Request line for each channel
        ret = gpiod_chip_request_line(gpiod_chip_get_resource(), /* corresponding GPIO */, GPIOD_LINE_IN);
        if (ret != 0) {
            fprintf(stderr, "Error: Failed to request line for channel %d.\n", i + 1);
            exit(1);
        }

        // Read the line value
        int value = gpiod_chip_read(gpiod_chip_get_resource(), /* corresponding GPIO */);
        if (value == 0) {
            printf("[%.3fs] CH%d=%d ", monotonic_time(), i + 1, value);
        } else {
            fprintf(stderr, "Error reading channel %d.\n", i + 1);
            exit(1);
        }

        // Release the line after reading
        gpiod_chip_release_line(gpiod_chip_get_resource(), /* corresponding GPIO */);
    }
}

// Function to close the TTP226 chip
void close_ttp226(gpiod_resource_t *chip_resource) {
    if (chip_resource != NULL) {
        gpiod_chip_close(chip_resource);
        chip_resource = NULL;
    }
}

// Function to free gpiod resources
void free_gpiod_resource(gpiod_resource_t *resource) {
    if (resource != NULL) {
        gpiod_resource_free(resource);
        resource = NULL;
    }
}

// Helper function to get monotonic time
time_t monotonic_time() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (time_t)ts.tv_sec;
}

