#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/syslog.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_NUM_RED   17
#define GPIO_NUM_GREEN 18
#define GPIO_NUM_BLUE  27

#define PWM_FREQ_HZ    1000
#define NUM_STEPS       50
#define INTERPOLATION_TIME_MS 5000

volatile sig_atomic_t should_exit = 0;

void fade_to_random_color(int red_pin, int green_pin, int blue_pin, int steps, int time_ms) {
    int red, green, blue;
    srandomdev((unsigned int)sysconf(_SC_CLK_TCK)); // Seed rand with /dev/urandom

    while (time_ms > 0) {
        red = rand() % 256;
        green = rand() % 256;
        blue = rand() % 256;

        // Clamp values to 0-255
        red = (red < 0) ? 0 : (red > 255) ? 255 : red;
        green = (green < 0) ? 0 : (green > 255) ? 255 : green;
        blue = (blue < 0) ? 0 : (blue > 255) ? 255 : blue;

        // Perform linear interpolation
        int step = steps--;
        red = (red + (green * step) + (blue * (1.0 - step))) / steps;
        green = (green + (blue * step) + (red * (1.0 - step))) / steps;
        blue = (blue + (red * step) + (green * (1.0 - step))) / steps;

        // Set PWM duty cycle
        gpiod_set_data(gpiod_get_device(GPIO_NUM_RED), red, GPIO_DIR_OUT);
        gpiod_set_data(gpiod_get_device(GPIO_NUM_GREEN), green, GPIO_DIR_OUT);
        gpiod_set_data(gpiod_get_device(GPIO_NUM_BLUE), blue, GPIO_DIR_OUT);

        usleep(PWM_FREQ_HZ * 1000); // Wait for 1ms
        time_ms -= 1000 / PWM_FREQ_HZ; // Decrease time by 1ms
    }

    gpiod_set_data(gpiod_get_device(GPIO_NUM_RED), 0, GPIO_DIR_OUT);
    gpiod_set_data(gpiod_get_device(GPIO_NUM_GREEN), 0, GPIO_DIR_OUT);
    gpiod_set_data(gpiod_get_device(GPIO_NUM_BLUE), 0, GPIO_DIR_OUT);
}

int main(void) {
    int red_dev, green_dev, blue_dev;
    int red_err, green_err, blue_err;
    struct syslog_facility syslog_fac;
    syslog_fac.fac = LOG_LOCAL7;

    // Initialize syslog
    openlog("rpi-pwm-fader", LOG_PID | LOG_CONS | LOG_NDELAY, syslog_fac.fac);

    // Initialize GPIO library
    if (gpiod_is_valid()) {
        printf("gpiod initialized successfully.\n");
    } else {
        syslog(LOG_ERR, "Failed to initialize gpiod: %s", gpiod_errstr());
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    red_dev = gpiod_get_device(GPIO_NUM_RED);
    green_dev = gpiod_get_device(GPIO_NUM_GREEN);
    blue_dev = gpiod_get_device(GPIO_NUM_BLUE);

    if (red_dev == GPIOD_DEV_NULL || green_dev == GPIOD_DEV_NULL || blue_dev == GPIOD_DEV_NULL) {
        syslog(LOG_ERR, "Failed to open GPIO pins: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    // Install signal handlers
    struct sigaction int_handler, term_handler;
    int_handler.sa_handler = SIG_IGN;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_flags = 0;
    sigaction(SIGINT, &int_handler, NULL);

    int_handler.sa_handler = handle_graceful_exit;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_flags = 0;
    sigaction(SIGTERM, &int_handler, NULL);

    // Start fading
    fade_to_random_color(GPIO_NUM_RED, GPIO_NUM_GREEN, GPIO_NUM_BLUE, NUM_STEPS, INTERPOLATION_TIME_MS);

    // Main loop
    while (!should_exit) {
        sleep(1);
    }

    // Gracefully exit
    handle_graceful_exit();

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

void handle_graceful_exit() {
    should_exit = 1;
    // Wait for ongoing fade to complete
    usleep(INTERPOLATION_TIME_MS * 1000);

    // Turn off LED
    gpiod_set_data(gpiod_get_device(GPIO_NUM_RED), 0, GPIO_DIR_OUT);
    gpiod_set_data(gpiod_get_device(GPIO_NUM_GREEN), 0, GPIO_DIR_OUT);
    gpiod_set_data(gpiod_get_device(GPIO_NUM_BLUE), 0, GPIO_DIR_OUT);

    // Release GPIO resources
    gpiod_unexport_all();

    // Close syslog
    closelog();
}

