#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define TCS34725_I2C_ADDR 0x40
#define GPIO_RED_PIN 17
#define THRESHOLD_RED 200

// Sensor configuration constants
#define TCS34725_REG_INT_CFG 0x20
#define TCS34725_REG_AEN_CFG 0x21
#define TCS34725_REG_INT_TIME 0x22
#define TCS34725_REG_R_G_B_C 0x23

// Sensor command constants
#define TCS34725_CMD_PON 0x06
#define TCS34725_CMD_AEN 0x0A

// Sensor data register offsets
#define TCS34725_REG_R 0x00
#define TCS34725_REG_G 0x01
#define TCS34725_REG_B 0x02
#define TCS34725_REG_C 0x03

// Function prototypes
void handle_signal(int signum);
void i2c_init();
void gpio_init();
void sensor_power_on();
void sensor_configure();
void read_sensor_data();
void print_sensor_data();
void cleanup();

int main() {
    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C and GPIO
    i2c_init();
    gpio_init();

    // Power on the sensor
    sensor_power_on();

    // Configure the sensor
    sensor_configure();

    // Main loop
    while (1) {
        read_sensor_data();
        print_sensor_data();
        usleep(200000); // 200 ms delay
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up resources on SIGINT and SIGTERM
    cleanup();
    exit(0);
}

// Function to initialize I2C
void i2c_init() {
    int i2c_fd;

    // Open I2C device
    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Check if I2C device is valid
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to initialize GPIO
void gpio_init() {
    pigpio *pi;

    // Initialize pigpio library
    pi = pigpioOpen();
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO 17 as output
    if (pigpioWrite(GPIO_RED_PIN, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RED_PIN);
        pigpioClose(pi);
        exit(EXIT_FAILURE);
    }
}

// Function to power on the sensor
void sensor_power_on() {
    int cmd;
    cmd = TCS34725_CMD_PON;
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to power on sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to configure the sensor
void sensor_configure() {
    int cmd, reg, val;

    // Enable RGBC mode (AEN)
    cmd = TCS34725_CMD_AEN;
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to enable RGBC mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set integration time for approximately 154 ms
    val = 0x3F; // This value approximates 154 ms based on TCS34725 datasheet
    if (write(i2c_fd, &TCS34725_REG_INT_TIME, sizeof(TCS34725_REG_INT_TIME)) != sizeof(TCS34725_REG_INT_TIME) ||
        read(i2c_fd, &reg, sizeof(reg)) != sizeof(reg) ||
        (val != (unsigned char)reg)) {
        perror("Failed to set integration time");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure sensor to output calibrated RGB+C values
    cmd = TCS34725_REG_R_G_B_C;
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to configure data register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read sensor data
void read_sensor_data() {
    int cmd, r, g, b, c;

    // Read sensor data
    cmd = TCS34725_REG_R_G_B_C;
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to read sensor data");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read red, green, blue, and clear values
    if (read(i2c_fd, &r, sizeof(r)) != sizeof(r) ||
        read(i2c_fd, &g, sizeof(g)) != sizeof(g) ||
        read(i2c_fd, &b, sizeof(b)) != sizeof(b) ||
        read(i2c_fd, &c, sizeof(c)) != sizeof(c)) {
        perror("Failed to read sensor data");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check if red value exceeds threshold
    if (r > THRESHOLD_RED) {
        // Set GPIO 17 HIGH
        pigpioWrite(GPIO_RED_PIN, 1);
    } else {
        // Set GPIO 17 LOW
        pigpioWrite(GPIO_RED_PIN, 0);
    }
}

// Function to print sensor data
void print_sensor_data() {
    printf("Red: %d, Green: %d, Blue: %d, Clear: %d\n", r, g, b, c);
}

// Function to clean up resources
void cleanup() {
    // Power off the sensor
    sensor_power_off();

    // Close I2C file descriptor
    close(i2c_fd);

    // Release GPIO line
    pigpioClose(pi);

    // Free resources
    free(pi);
}

// Function to power off the sensor
void sensor_power_off() {
    int cmd;
    cmd = TCS34725_CMD_PON;
    if (write(i2c_fd, &cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to power off sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

