#define BH1750_REG_WR 0x40
#define BH1750_CMD_START 0x80
#define BH1750_CMD_READ_LUX 0x88

// WS2812B timing constants
#define WS2812B_BITTIME 125000 // 1/8000000 seconds per bit
#define WS2812B_RESET_TIME 50_000 // 50 microseconds

// BH1750 lux range and mapping to brightness levels
#define BH1750_MIN_LUX 0
#define BH175O_MAX_LUX 65535
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_MAX 9

volatile uint8_t ws2812b_data[WS2812B_GRB_COUNT * 3]; // 3 bytes per RGB

