int main(void) {
    // Initialize GPIO and signal handlers
    setup_gpios();
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        // Wait for approximately 180 ms
        struct timeval now;
        gettimeofday(&now, NULL);
        usleep((180000 - (now.tv_sec * 1000000 + now.tv_usec))) / 1000;

        // Read lux from BH1750
        bh1750_read_lux();

        // Map lux to brightness and set WS2812B
        ws2812b_set_brightness((uint16_t)(bh1750_read_lux() / 1000));

        // Small delay to avoid rapid color changes
        usleep(5000);
    }

    // Clean up on exit
    cleanup_gpios();

    return 0;
