    uint16_t lux;

    // Write command to read lux
    gpiod_write(BH1750_I2C_ADDR, BH1750_REG_WR, BH1750_CMD_READ_LUX);

    // Wait for the BH1750 to process the command
    usleep(5 * 1000);

    // Read lux value
    lux = gpiod_read(BH1750_I2C_ADDR, BH1750_REG_LUX);

    // Handle potential I2C errors or sensor absence
    if (lux == 0) {
