    uint32_t time = WS2812B_BITTIME * 30; // 30 bits for each RGB value
    uint8_t i;

    // Initialize the WS2812B data with black (off)
    for (i = 0; i < WS2812B_GRB_COUNT * 3; i++) {
        ws2812b_data[i] = 0;
    }

    // Set brightness
    for (i = 0; i < WS2812B_GRB_COUNT; i++) {
        ws2812b_data[i * 3 + 0] = (brightness >>  (i * 5)) & 0x1F;
        ws2812b_data[i * 3 + 1] = (brightness >> ((i * 5) +  5)) & 0x1F;
        ws2812b_data[i * 3 + 2] = (brightness >> ((i * 5) + 10)) & 0x1F;
    }

    // Send data to WS2812B strip using hardware PWM
    gpiod_set_data_direction(WS2812B_GPIO, GPIOD_OUT_HIGH);
    gpiod_write(WS2812B_GPIO, 0); // Start signal
    for (uint32_t t = 0; t < time; t++) {
        gpiod_write(WS2812B_GPIO, ws2812b_data[(t % (WS2812B_GRB_COUNT * 3))]); // Output bits
    }
    gpiod_set_data_direction(WS2812B_GPIO, GPIOD_DATA_DIR_INPUT); // Return to input mode
}

