    // Initialize GPIO for BH1750 I2C
    gpiod_direction_output(BH1750_I2C_SDA, GPIO_ACTIVE_LOW);
    gpiod_direction_output(BH1750_I2C_SCL, GPIO_ACTIVE_LOW);

    // Initialize GPIO for WS2812B
    gpiod_set_mode(WS2812B_GPIO, GPIOD_MODE_OUTPUT);
    gpiod_set_polarity(WS2812B_GPIO, GPIOD_POLARITY_HIGH);
}

// Function to cleanup GPIOs
void cleanup_gpios(void) {
    // Release GPIOs
    gpiod_set_direction(BH1750_I2C_SDA, GPIOD_INPUT);
    gpiod_set_direction(BH1750_I2C_SCL, GPIOD_INPUT);

    // Stop PWM output on WS2812B GPIO
    gpiod_set_mode(WS2812B_GPIO, GPIOD_MODE_INPUT);
}

// Signal handler to clean up and exit on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Clean up GPIOs
    cleanup_gpios();

    // Exit the program
    exit(0);
}

