#define BH1750_ADDR 0x23
#define APA102_CS 0
#define APA102_MOSI 1
#define APA102_MISO 2
#define APA102_SCK 3

#define BH1750_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"

// BH1750 register addresses
#define BH1750_REG_POWER_CTL 0x00
#define BH1750_REG_DATA_H 0x01
#define BH1750_REG_DATA_L 0x02

// APA102 control register
#define APA102_CMD 0x00
#define APA102_DATA 0x01

// BH1750 to APA102 brightness conversion factor
#define BRIGHTNESS_FACTOR 0.1

// APA102 LED frame structure
typedef struct {
    uint32_t res; // Reserved
    uint8_t green; // Green intensity
    uint8_t red; // Red intensity
    uint8_t blue; // Blue intensity
} apa102_led_frame_t;

