void bh1750_init();
void bh1750_read_light();
void apa102_init();
void apa102_write(uint32_t data);
void handle_signal(int signum);

int main() {
    // Signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Initialize BH1750 sensor
    bh1750_init();

    // Initialize APA102 LED strip
    apa102_init();

    // Main loop
    while (1) {
        // Read light level from BH1750
        bh1750_read_light();

        // Calculate brightness for LEDs
        uint16_t brightness = (uint16_t)(BH1750_DATA_H << 8 | BH1750_DATA_L) * BRIGHTNESS_FACTOR;

        // Write brightness to APA102 LEDs
        apa102_write((uint32_t)brightness);

        // Sleep for 120 ms
        usleep(120000);
    }

    // Clean up on exit
    apa102_write(0); // Turn off all LEDs
    close(SPI_DEVICE); // Close SPI device file descriptor
    bh1750_deinit(); // Deinitialize BH1750

    return 0;
}

// Function to initialize BH1750 sensor
void bh1750_init() {
    int fd;
    struct gpiod_dir *dir;
    struct gpiod_cdev *cdev;

    // Open BH1750 I2C device
    fd = open(BH1750_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open BH1750 I2C device");
        exit(EXIT_FAILURE);
    }

    // Get the I2C device directory
    dir = gpiod_get_dir(fd);
    if (!dir) {
        perror("Failed to get BH1750 I2C device directory");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Open the BH1750 device
    cdev = gpiod_open(dir, BH1750_ADDR, GPIOD_OPEN_RWS);
    if (!cdev) {
        gpiod_put_dir(dir);
        perror("Failed to open BH1750 device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set power control register to enable sensor
    if (gpiod_write(cdev, BH1750_REG_POWER_CTL, 0x80) < 0) {
        perror("Failed to set BH1750 power control");
        gpiod_close(cdev);
        gpiod_put_dir(dir);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_close(cdev);
    gpiod_put_dir(dir);
    close(fd);
}

// Function to read light level from BH1750
void bh1750_read_light() {
    int fd;
    struct gpiod_cdev *cdev;
    uint16_t light;

    // Open BH1750 I2C device
    fd = open(BH1750_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open BH1750 I2C device");
        return;
    }

    // Open the BH1750 device
    cdev = gpiod_open(fd, BH1750_ADDR, GPIOD_OPEN_RWS);
    if (!cdev) {
        close(fd);
        perror("Failed to open BH1750 device");
        return;
    }

    // Write command to start conversion
    if (gpiod_write(cdev, BH1750_REG_DATA_H, 0x00) ||
        gpiod_write(cdev, BH1750_REG_DATA_L, 0x00) < 0) {
        perror("Failed to start BH1750 conversion");
        gpiod_close(cdev);
        close(fd);
        return;
    }

    // Wait for conversion to complete
    usleep(10 * 1000); // Approximately 10 ms

    // Read light level data
    if (gpiod_read(cdev, BH1750_REG_DATA_H, &light.h) ||
        gpiod_read(cdev, BH1750_REG_DATA_L, &light.l) < 0) {
        perror("Failed to read BH1750 light level");
        gpiod_close(cdev);
        close(fd);
        return;
    }

    // Convert to brightness value
    uint16_t brightness = (uint16_t)(light.h << 8 | light.l) * BRIGHTNESS_FACTOR;
    // Handle overflow
    if (brightness > 255) {
        brightness = 255;
    }

    gpiod_close(cdev);
    close(fd);
}

// Function to initialize APA102 LED strip
void apa102_init() {
    int fd;
    struct stat stat_buf;
    struct gpiod_cdev *cdev;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Get the SPI device details
    if (fstat(fd, &stat_buf) == -1) {
        perror("Failed to get SPI device details");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Open the SPI device
    cdev = gpiod_open(fd, APA102_CS, GPIOD_OPEN_RWS);
    if (!cdev) {
        close(fd);
        perror("Failed to open APA102 device");
        exit(EXIT_FAILURE);
    }

    // Write command to set clock frequency to 1 MHz
    if (gpiod_write(cdev, APA102_CMD, 0x80 | (1 << 5)) < 0) {
        perror("Failed to set APA102 clock frequency");
        gpiod_close(cdev);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_close(cdev);
    close(fd);
}

// Function to write data to APA102 LED strip
void apa102_write(uint32_t data) {
    int fd;
    struct gpiod_cdev *cdev;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open SPI device");
        return;
    }

    // Open the APA102 device
    cdev = gpiod_open(fd, APA102_CS, GPIOD_OPEN_RWS);
    if (!cdev) {
        close(fd);
        perror("Failed to open APA102 device");
        return;
    }

    // Write data to the LED strip
    if (gpiod_write(cdev, APA102_DATA, data) < 0) {
        perror("Failed to write to APA102");
        gpiod_close(cdev);
        close(fd);
        return;
    }

    gpiod_close(cdev);
    close(fd);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Turn off all LEDs
    apa102_write(0);

    // Close SPI device file descriptor
    close(SPI_DEVICE);

    // Clean up BH1750
    bh1750_deinit();
}

// Function to deinitialize BH1750 sensor
void bh1750_deinit() {
    int fd;
    struct gpiod_dir *dir;
    struct gpiod_cdev *cdev;

    // Open BH1750 I2C device
    fd = open(BH1750_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open BH1750 I2C device");
        return;
    }

    // Get the I2C device directory
    dir = gpiod_get_dir(fd);
    if (!dir) {
        perror("Failed to get BH1750 I2C device directory");
        close(fd);
        return;
    }

    // Close the BH1750 device
    gpiod_close(gpiod_open(dir, BH1750_ADDR, GPIOD_OPEN_RWS));

    // Release the I2C device directory
    gpiod_put_dir(dir);
    close(fd);
}

