        return;
    }

    // Write data to the LED strip
    if (gpiod_write(cdev, APA102_DATA, data) < 0) {
        perror("Failed to write to APA102");
        gpiod_close(cdev);
        close(fd);
        return;
    }

    gpiod_close(cdev);
    close(fd);
