// Function to deinitialize BH1750 sensor
void bh1750_deinit() {
    int fd;
    struct gpiod_dir *dir;
    struct gpiod_cdev *cdev;

    // Open BH1750 I2C device
    fd = open(BH1750_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Failed to open BH1750 I2C device");
        return;
    }

    // Get the I2C device directory
    dir = gpiod_get_dir(fd);
    if (!dir) {
        perror("Failed to get BH1750 I2C device directory");
        close(fd);
        return;
    }

    // Close the BH1750 device
    gpiod_close(gpiod_open(dir, BH1750_ADDR, GPIOD_OPEN_RWS));

    // Release the I2C device directory
    gpiod_put_dir(dir);
    close(fd);
}

