#define VEML7700_ADDR 0x39
#define WS2812B_GPIO 18
#define WS2812B_PIN_NUM 18

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO for WS2812B
    int ws2812b_fd;
    struct gpio_desc *ws2812b_pin;
    ws2812b_pin = gpiod_get_pin_by_number(GPIO_NUM_TO_NAME(WS2812B_PIN_NUM));
    if (ws2812b_pin == NULL) {
        fprintf(stderr, "Error: Could not get GPIO pin %d\n", WS2812B_PIN_NUM);
        return EXIT_FAILURE;
    }
    ws2812b_fd = open(ws2812b_pin->dev_path, O_WRONLY);
    if (ws2812b_fd == -1) {
        fprintf(stderr, "Error: Could not open GPIO pin %d\n", WS2812B_PIN_NUM);
        gpiod_free_pin(ws2812b_pin);
        return EXIT_FAILURE;
    }

    // Initialize I2C for VEML7700
    int i2c_fd;
    struct i2c_dev *i2c_dev;
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    i2c_dev = i2c_new_device(i2c_fd, VEML7700_ADDR);
    if (i2c_dev == NULL) {
        fprintf(stderr, "Error: Could not find VEML7700 at address 0x%02X\n", VEML7700_ADDR);
        close(i2c_fd);
        i2c_free_device(i2c_dev);
        return EXIT_FAILURE;
    }

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!should_exit) {
        // Read lux value from VEML7700
        uint16_t lux;
        i2c_smbus_read_word_data(i2c_dev, 0x05) == 0 || (errno == EAGAIN && --tries > 0) {
            if (tries == 0) {
                fprintf(stderr, "Error: Failed to read from VEML7700 after 3 attempts\n");
                continue;
            }
            usleep(100 * 1000); // 100 ms delay
        }
        lux = (uint16_t)i2c_smbus_read_word_data(i2c_dev, 0x05);

        // Apply gamma correction
        double gamma_corrected_brightness = pow(lux, 0.45); // Example gamma value

        // Print lux and brightness
        printf("Lux: %d, Brightness: %.2f\n", lux, gamma_corrected_brightness);

        // Drive WS2812B LED strip
        int data = gamma_corrected_brightness; // Assuming direct mapping for simplicity
        while (data != 0) {
            // Bit-bang the WS2812B data line
            if (ws2812b_fd >= 0) {
                // Assuming a simple toggle function for demonstration
                gpio_set_value(ws2812b_fd, !gpio_get_value(ws2812b_fd));
                data >>= 1;
            } else {
                // Fall back to threshold-based on/off
                if (gamma_corrected_brightness > 128) {
                    gpio_set_value(ws2812b_fd, 1);
                } else {
                    gpio_set_value(ws2812b_fd, 0);
                }
                break; // No further bits to send
            }
        }

        // 200 ms pause
        usleep(200 * 1000);

        // Close resources on exit signal
        if (should_exit) {
            gpio_set_value(ws2812b_fd, 0); // Turn off LED strip
            close(i2c_fd);
            i2c_free_device(i2c_dev);
            close(ws2812b_fd);
            gpiod_free_pin(ws2812b_pin);
            return EXIT_SUCCESS;
        }
    }

    // Clean up on exit
    gpio_set_value(ws2812b_fd, 0); // Turn off LED strip
    close(i2c_fd);
    i2c_free_device(i2c_dev);
    close(ws2812b_fd);
    gpiod_free_pin(ws2812b_pin);

    return EXIT_SUCCESS;
}

