#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO18 18

#define BLINK_MS 500
#define SELF_TEST_SAMPLES 5
#define FLAME_DETECTED_THRESHOLD 5
#define ERROR_BLINK_MS 100
#define ERROR_Buzzer_PATTERN 3
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600

volatile sig_atomic_t sigIntReceived = 0;

void setup_gpios(void);
void cleanup_gpios(void);
void blink_led(int ms);
void buzzer_signal(int pattern);
void error_handling(int flame_detected);
void main_loop(void);
void handle_signal(int signum);

int main(void) {
    setup_gpios();
    signal(SIGINT, handle_signal);

    // Initial self-test
    blink_led(BLINK_MS);
    printf("Starting self-test...\n");

    for (int i = 0; i < SELF_TEST_SAMPLES; ++i) {
        if (gpiod_read(GPIO4) == 0) {
            error_handling(1);
            break;
        }
        usleep(100000);
    }

    if (i == SELF_TEST_SAMPLES) {
        printf("Self-test passed.\n");
        main_loop();
    } else {
        printf("Flame detected during self-test.\n");
        blink_led(ERROR_BLINK_MS);
        buzzer_signal(ERROR_Buzzer_PATTERN);
        exit(1);
    }

    return 0;
}

void setup_gpios(void) {
    if (gpiod_direction_output(GPIO17, 1) < 0) {
        perror("Failed to set GPIO17 as output");
        exit(1);
    }

    if (gpiod_direction_output(GPIO18, 1) < 0) {
        perror("Failed to set GPIO18 as output");
        exit(1);
    }

    if (gpiod_direction_input(GPIO4) < 0) {
        perror("Failed to set GPIO4 as input");
        exit(1);
    }
}

void cleanup_gpios(void) {
    gpiod_set_value(GPIO17, 0);
    gpiod_set_value(GPIO18, 0);
    gpiod_set_direction(GPIO4, GPIOD_DIR_IN);
}

