#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_REG_LUX 0x00
#define GPIO17_PIN 17

volatile uint16_t lux_readings[60];
volatile uint16_t lux_count = 0;
uint16_t average_lux = 0;
uint16_t frequency = 500; // Hz in darkness
int led_gpio = -1;

void blink_led(uint16_t frequency) {
    static uint32_t last_time = 0;
    uint32_t now = microsecond();
    uint32_t interval = (1000000 / frequency) - 1;

    if (now - last_time >= interval) {
        if (led_gpio != -1) {
            gpio_write(led_gpio, 1);
            usleep(500000); // 0.5ms delay
            gpio_write(led_gpio, 0);
            usleep(500000); // 0.5ms delay
        }
        last_time = now;
    }
}

void handle_sigint(int signum) {
    if (led_gpio != -1) {
        gpio_unexport(led_gpio);
        close(STDIN_FILENO); // Close file descriptor to avoid resource leak
    }
    printf("SIGINT received, cleaning up...\n");
    exit(0);
}

int main() {
    // Initialize GPIO
    int ret = gpiod_open(&gpiodev);
    if (ret < 0) {
        perror("gpiod_open");
        return 1;
    }
    led_gpio = gpiod_get_index_by_name("GPIO17", &gpiodev);
    if (led_gpio == -1) {
        perror("gpiod_get_index_by_name");
        gpiod_close(gpiodev);
        return 1;
    }

    // Initialize I2C
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        gpiod_close(gpiodev);
        return 1;
    }

    struct gpiod_cdev *i2c_dev;
    ret = gpiod_get_cdev_by_name("i2c-1", &i2c_dev);
    if (ret < 0) {
        perror("gpiod_get_cdev_by_name");
        close(i2c_fd);
        gpiod_close(gpiodev);
        return 1;
    }

    // BH1750 initialization
    uint8_t command[2] = {BH1750_I2C_ADDR, BH1750_REG_LUX};
    ret = write(i2c_fd, command, sizeof(command));
    if (ret != sizeof(command)) {
        perror("write to BH1750");
        handle_sigint(SIGINT);
        close(i2c_fd);
        gpiod_close(gpiodev);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t lux;
        ret = read(i2c_fd, &lux, sizeof(lux));
        if (ret != sizeof(lux)) {
            perror("read from BH1750");
            handle_sigint(SIGINT);
            continue; // Skip this reading and try again next iteration
        }

        lux_readings[lux_count++] = lux;
        if (lux_count >= 60) {
            lux_count = 0; // Circular buffer
            average_lux = (uint16_t)((uint32_t)lux_readings[0] * 60 / lux_count);
            frequency = 500 + (1000 - average_lux) * 10; // Adjust frequency based on lux
        }

        blink_led(frequency);

        // Check if we need to exit
        if (signal(SIGINT, handle_sigint) == SIG_ERR) {
            perror("signal(SIGINT)");
            break; // Exit on error setting the signal handler
        }
    }

    // Clean up on exit
    close(i2c_fd);
    gpiod_close(gpiodev);

    return 0;
}

