#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27

#define SEVEN_SEGMENT_PINS { 2, 3, 4, 5, 6, 7, 15 } // a, b, c, d, e, f, dp

int main() {
    // Initialize gpiod library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open GPIO pins
    int gpio17 = gpiod_open(GPIO17, GPIOD_DIR_OUT);
    int gpio18 = gpiod_open(GPIO18, GPIOD_DIR_OUT);
    int gpio27 = gpiod_open(GPIO27, GPIOD_DIR_OUT);

    // Check if GPIO pins opened successfully
    if (gpio17 < 0 || gpio18 < 0 || gpio27 < 0) {
        fprintf(stderr, "Failed to open GPIO pins: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(gpio17);
        gpiod_close(gpio18);
        gpiod_close(gpio27);
        gpiod_uninit();
        return EXIT_FAILURE;
    }

    // Configure GPIO pins as outputs
    if (gpiod_direction_output(gpio17, 1) < 0 ||
        gpiod_direction_output(gpio18, 0) < 0 ||
        gpiod_direction_output(gpio27, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO pins as outputs: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_close(gpio17);
        gpiod_close(gpio18);
        gpiod_close(gpio27);
        gpiod_uninit();
        return EXIT_FAILURE;
    }

    // Function to shift out data to 74HC595
    void shiftOut(uint8_t data) {
        uint8_t bit = data >> i;
        gpiod_write(gpio17, bit ? 1 : 0);
        gpiod_delay_us(5); // Clock high
        gpiod_write(gpio17, 0); // Clock low
        if (i == 7) {
            gpiod_write(gpio27, 1); // Latch high
            gpiod_delay_us(5); // Wait for latch
            gpiod_write(gpio27, 0); // Latch low
        }
        i--;
    }

    // Function to display digit '5' on the seven-segment display
    void displayDigit5() {
        uint8_t data = 0b00111101; // Binary representation of '5'
        shiftOut(data);
    }

    // Blinking function with 500ms on and 500ms off period
    void blinkDigit5() {
        for (;;) {
            displayDigit5();
            sleep(500); // 500ms on
            displayDigit5();
            sleep(500); // 500ms off
        }
    }

    // Main program loop
    blinkDigit5();

    // Cleanup on exit
    gpiod_close(gpio17);
    gpiod_close(gpio18);
    gpiod_close(gpio27);
    gpiod_uninit();

    return EXIT_SUCCESS;
}

