#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

volatile sig_atomic_t should_exit = 0;

void button_fall_edge_callback(struct gpiod_device *dev, void *data)
{
    printf("Button pressed!\n");
    should_exit = 1;
}

int main(void)
{
    // Initialize GPIO chip 0
    struct gpiod_chip *chip;
    int rc = gpiod_chip_open(0, GPIOD_OPEN_READONLY);
    if (rc) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", rc);
        return EXIT_FAILURE;
    }
    chip = gpiod_chip_get_by_name("bcm2835-gpio");
    if (!chip) {
        fprintf(stderr, "Error getting GPIO chip: %s\n", gpiod_error_str(gpiod_get_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED pin as output, initially low
    int rc = gpiod_pin_request(chip, LED_PIN, GPIOD_PIN_OUTPUT);
    if (rc) {
        fprintf(stderr, "Error requesting LED pin: %d\n", rc);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_pin_write(chip, LED_PIN, 0); // Set LED pin low

    // Request button pin as input with pull-up and falling edge detection
    rc = gpiod_pin_request(chip, BUTTON_PIN, GPIOD_PIN_INPUT_PULLUP);
    if (rc) {
        fprintf(stderr, "Error requesting button pin: %d\n", rc);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the falling edge callback
    rc = gpiod_event_request(chip, BUTTON_PIN, GPIOD_EVENT_FALLING, button_fall_edge_callback, NULL);
    if (rc) {
        fprintf(stderr, "Error requesting button pin event: %d\n", rc);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Blink LED
        gpiod_pin_write(chip, LED_PIN, 1); // Turn LED on
        usleep(1000000); // Wait 1 second
        gpiod_pin_write(chip, LED_PIN, 0); // Turn LED off
        usleep(1000000); // Wait 1 second
    }

    // Check for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Graceful termination on button press or Ctrl+C
    while (!should_exit) {
        // Poll for button press
        int rc = gpiod_event_poll(chip, BUTTON_PIN, 1, 1000000);
        if (rc == -1) {
            fprintf(stderr, "Error polling button pin: %d\n", rc);
            break;
        }
        if (rc) {
            printf("Button pressed!\n");
            should_exit = 1;
        }
    }

    // Clean up
    gpiod_pin_unrequest(chip, LED_PIN);
    gpiod_pin_unrequest(chip, BUTTON_PIN);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

