#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22

int main() {
    // Initialize GPIO
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_dir *led_dir;
    struct gpiod_value *led_value;
    struct gpiod_input *button_input;

    // Register signal handlers
    signal(SIGINT, handleInterrupt);
    signal(SIGTERM, handleInterrupt);

    // Attempt to open the GPIO chip
    chip = gpiod_chip_open(GPIOD_CHIPS_DEFAULT_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Could not open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    // Open GPIO lines
    led_dir = gpiod_dir_open(chip, LED_PIN, GPIOD_DIR_OUT_INIT_LOW);
    if (led_dir == NULL) {
        fprintf(stderr, "Error: Could not open GPIO line %d (LED).\n", LED_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_value = gpiod_value_open(led_dir);
    if (led_value == NULL) {
        fprintf(stderr, "Error: Could not open GPIO value for line %d (LED).\n", LED_PIN);
        gpiod_dir_close(led_dir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    button_input = gpiod_input_open(chip, BUTTON_PIN, GPIOD_INPUT_PULLDOWN);
    if (button_input == NULL) {
        fprintf(stderr, "Error: Could not open GPIO line %d (Button).\n", BUTTON_PIN);
        gpiod_value_close(led_value);
        gpiod_dir_close(led_dir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set LED pin direction
    ret = gpiod_dir_set(led_dir, GPIOD_DIR_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error setting LED pin direction: %s\n", gpiod_error_string(ret));
        gpiod_input_close(button_input);
        gpiod_value_close(led_value);
        gpiod_dir_close(led_dir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial LED state to low
    ret = gpiod_value_write(led_value, 0);
    if (ret != 0) {
        fprintf(stderr, "Error writing LED value: %s\n", gpiod_error_string(ret));
        gpiod_dir_close(led_dir);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Check button state
        int button_state = gpiod_input_get(button_input);
        if (button_state) {
            // Button is pressed, blink the LED
            for (int i = 0; i < 10; i++) { // 10 cycles of on/off
                gpiod_value_write(led_value, 1); // Turn LED on
                usleep(500 * 1000); // Wait 500 ms
                gpiod_value_write(led_value, 0); // Turn LED off
                usleep(500 * 1000); // Wait 500 ms
            }
            // Release resources on interrupt
            handleInterrupt();
        } else {
            // Button is not pressed, turn LED off
            gpiod_value_write(led_value, 0);
        }
    }

    // Clean up on normal exit
    gpiod_value_close(led_value);
    gpiod_dir_close(led_dir);
    gpiod_input_close(button_input);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

// Signal handler to release resources on SIGINT or SIGTERM
void handleInterrupt(int signum) {
    fprintf(stderr, "Interrupt received, cleaning up...\n");
    // Directly release resources here as the program is terminating
    gpiod_value_close(led_value);
    gpiod_dir_close(led_dir);
    gpiod_input_close(button_input);
    gpiod_chip_close(chip);
    exit(0);
}

