void cleanup_gpios(void);
void handle_signal(int signum);

int main(void) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Set up GPIO pins
    setup_gpios();

    // Signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Generate random intensities for each color
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        // Set PWM duty cycles for each color
        gpiod_set_data_direction(GPIOD_DIR_OUT);
        gpiod_write(RED_GPIO, red);
        gpiod_write(GREEN_GPIO, green);
        gpiod_write(BLUE_GPIO, blue);

        // Wait for 100ms before changing colors
        struct timespec timeout = { .tv_sec = 0, .tv_nsec = 100000000 };
        clock_nanosleep(CLOCK_REALTIME, &timeout, NULL, NULL);

        // Cleanup GPIO pins
        cleanup_gpios();
    }

    return 0;
}

