#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS_NUM 1
#define LSM303DLHC_ADDR 0x1D
#define GPIO_PIN 17
#define THRESHOLD_G 2.0
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 1024

// Function prototypes
void setup_i2c();
void setup_gpiod();
void read_accelerometer_data(uint8_t *data, int size);
void compute_g_force_magnitude(const uint8_t *data, int size);
void handle_impact(int g_force);
void cleanup();

int main(int argc, char **argv) {
    int fd_i2c, fd_gpiod;
    int g_force_magnitude;
    uint8_t data[BUFFER_SIZE];
    int read_size;
    struct timespec timestamp;
    int threshold = THRESHOLD_G;

    // Check if -t argument is provided to set a custom threshold
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    // Initialize I2C and GPIO
    setup_i2c();
    setup_gpiod();

    // Main loop
    while (1) {
        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &timestamp);

        // Read accelerometer data
        read_size = read(fd_i2c, data, BUFFER_SIZE);
        if (read_size < 0) {
            perror("I2C read error");
            break;
        }

        // Compute G-force magnitude
        compute_g_force_magnitude(data, read_size);

        // Check if G-force exceeds threshold
        if (g_force_magnitude > threshold) {
            handle_impact(g_force_magnitude);
        }

        // Write data to log file
        write_log(timestamp.tv_sec, timestamp.tv_nsec, g_force_magnitude);

        // Sleep to maintain 10 Hz sampling rate
        usleep(SAMPLE_RATE_HZ * 1000);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    int fd;
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msg = {
        .addr = LSM303DLHC_ADDR,
        .flags = 0
    };

    if (ioctl(fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    gpiod_set_flags(GPIO_PIN, GPIOD_OUT_HIGH | GPIOD_OUT_INIT_LOW);
}

// Function to setup GPIO
void setup_gpiod() {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpiod_request(fd, GPIO_PIN) < 0) {
        perror("Failed to request GPIO pin");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(fd, GPIO_PIN, 1);
}

