// Function to initialize the gyroscope
void gyro_init() {
    // No specific initialization needed for this sensor
    // Ensure I2C is ready for use
    if (ioctl(i2c_fd, GPIOD_IOCTL_SLAVE, GY50_I2C_ADDR) == -1) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to calibrate the gyroscope
void gyro_calibrate() {
    int16_t x_val, y_val, z_val;
    for (int i = 0; i < 100; ++i) {
        // Read raw values
        if (ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_XOUT_L, &x_val, sizeof(x_val)) != sizeof(x_val) ||
            ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_YOUT_H, &y_val, sizeof(y_val)) != sizeof(y_val) ||
            ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_ZOUT_L, &z_val, sizeof(z_val)) != sizeof(z_val)) {
            fprintf(stderr, "Failed to read gyro values during calibration: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Calculate offset
        calib_x_off += x_val;
        calib_y_off += y_val;
        calib_z_off += z_val;

        // Average the offsets
        calib_x_off /= 100;
        calib_y_off /= 100;
        calib_z_off /= 100;
    }
}

// Function to read gyro data
void gyro_read() {
    int16_t x_val, y_val, z_val;
    if (ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_XOUT_L, &x_val, sizeof(x_val)) != sizeof(x_val) ||
        ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_YOUT_H, &y_val, sizeof(y_val)) != sizeof(y_val) ||
        ioctl(i2c_fd, GPIOD_IOCTL_READ_REG, (void *)GY50_REG_ZOUT_L, &z_val, sizeof(z_val)) != sizeof(z_val)) {
        fprintf(stderr, "Failed to read gyro values: %s\n", strerror(errno));
        return;
    }

    // Apply calibration offsets
    int16_t x_cal = x_val - calib_x_off;
    int16_t y_cal = y_val - calib_y_off;
    int16_t z_cal = z_val - calib_z_off;

    // Format and log data
    char timestamp[50];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03u", &now);
    char gyro_log_line[256];
    snprintf(gyro_log_line, sizeof(gyro_log_line), "%s,%d,%d,%d\n", timestamp, x_cal, y_cal, z_cal);

    // Append to the log file
    if (write(3, gyro_log_line, strlen(gyro_log_line)) != strlen(gyro_log_line)) {
        fprintf(stderr, "Failed to write to gyro_log.txt: %s\n", strerror(errno));
        return;
    }

    // Check for alert conditions
    if (abs(x_cal) > 50 || abs(y_cal) > 50 || abs(z_cal) > 50) {
        fprintf(stderr, "Alert: Gyro value exceeds 50 dps on axis %s\n", (x_cal > 0 ? "X" : (y_cal > 0 ? "Y" : "Z")));
        gyro_handle_alert();
    }
}

// Function to handle alerts and log them
void gyro_handle_alert() {
    char alert_line[256];
    snprintf(alert_line, sizeof(alert_line), "Alert: Gyro value exceeded 50 dps on axis %s at %s\n",
             (calib_x_off > 0 ? "X" : (calib_y_off > 0 ? "Y" : "Z")), 
             time(NULL));

    // Append alert to the log file
    if (write(3, alert_line, strlen(alert_line)) != strlen(alert_line)) {
        fprintf(stderr, "Failed to write alert to gyro_log.txt: %s\n", strerror(errno));
        return;
    }
}

// Function to close resources and exit on SIGINT or SIGTERM
void sigint_handler(int signum) {
    // Clean up I2C and log file
    gyro_close();

    // Exit with signal number
    exit(signum);
}

// Function to close I2C and log file descriptors
void gyro_close() {
    // Close I2C file descriptor
    if (close(i2c_fd) == -1) {
        fprintf(stderr, "Failed to close I2C file descriptor: %s\n", strerror(errno));
    }

    // Close log file (assuming it was opened earlier)
    if (close(3) == -1) {
        fprintf(stderr, "Failed to close log file descriptor: %s\n", strerror(errno));
    }

    // Close GPIO handle (if needed)
    if (pi != NULL) {
        pigpioClose(pi);
        pi = NULL;
    }
}

