#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define GPIO17_PIN 17

// ADXL345 full scale range and resolution
#define ADXL345_FS_RANGE 2
#define ADXL345_FS_RES 13

// GPIO for LED
#define LED_GPIO 17

// Function prototypes
void setup_adxl345(void);
void read_acceleration_data(uint8_t *data);
void handle_signal(int signum);
void cleanup(void);

int main(void) {
    // Initialize GPIO for LED
    if (gpiod_open(GPIOD, GPIO17_PIN) < 0) {
        perror("gpiod_open failed");
        exit(EXIT_FAILURE);
    }

    // Setup ADXL345
    setup_adxl345();

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (libgpiod_i2c_transfer(gpiod_i2c_get_by_number(I2C_BUS), ADXL345_ADDR, 0x2D, data, 6) != 6) {
            fprintf(stderr, "I2C transfer failed\n");
            continue;
        }

        // Check if device is ADXL345
        if (data[0] != 0x53) {
            fprintf(stderr, "Device is not ADXL345\n");
            continue;
        }

        // Convert data to g units
        float x = (float)data[1] * (ADXL345_FS_RES / (ADXL345_FS_RANGE * 16384.0));
        float y = (float)data[2] * (ADXL345_FS_RES / (ADXL345_FS_RANGE * 16384.0));
        float z = (float)data[3] * (ADXL345_FS_RES / (ADXL345_FS_RANGE * 16384.0));

        // Log data
        char timestamp[50];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%F %T", localtime(&now));
        fprintf(stderr, "%s,%f,%f,%f\n", timestamp, x, y, z);

        // Check for acceleration threshold
        if (sqrt(x * x + y * y + z * z) > 2.0) {
            gpiod_set_value(LED_GPIO, 1); // Turn on LED
        } else {
            gpiod_set_value(LED_GPIO, 0); // Turn off LED
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to setup ADXL345
void setup_adxl345(void) {
    uint8_t config_reg = 0x2D; // Address for configuration register
    libgpiod_i2c_transfer(gpiod_i2c_get_by_number(I2C_BUS), ADXL345_ADDR, config_reg, &config_reg, 1, 100);
    config_reg |= (ADXL345_FS_RANGE << 6); // Set full scale range to ±2g
    libgpiod_i2c_transfer(gpiod_i2c_get_by_number(I2C_BUS), ADXL345_ADDR, config_reg, &config_reg, 1, 100);
}

// Signal handler to perform cleanup
void handle_signal(int signum) {
    // Clean up resources
    gpiod_release(GPIOD, LED_GPIO);
    libgpiod_i2c_release(gpiod_i2c_get_by_number(I2C_BUS));

    // Close log file
    int fd = open("accel_log.txt", O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (fd != -1) {
        fprintf(fd, "Exiting due to signal\n");
        close(fd);
    }

    exit(EXIT_SUCCESS);
}

// Cleanup function
void cleanup(void) {
    // Close log file if it's open
    int fd = open("accel_log.txt", O_WRONLY | O_APPEND);
    if (fd != -1) {
        fprintf(fd, "Exiting normally\n");
        close(fd);
    }

    // Release GPIO
    gpiod_release(GPIOD, LED_GPIO);
}

