#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_BUS 1
#define GY51_ADDR 0x1D

// Constants for LSM303DLHC registers
#define REG_ACCEL_XOUT_H 0x28
#define REG_ACCEL_XOUT_L 0x29
#define REG_ACCEL_YOUT_H 0x2A
#define REG_ACCEL_YOUT_L 0x2B
#define REG_ACCEL_ZOUT_H 0x2C
#define REG_ACCEL_ZOUT_L 0x2D
#define REG_MAG_X_H 0x1D
#define REG_MAG_X_L 0x1E
#define REG_MAG_Y_H 0x1F
#define REG_MAG_Y_L 0x20
#define REG_MAG_Z_H 0x21
#define REG_MAG_Z_L 0x22

// Function prototypes
void setup_gpiod();
void handle_interrupts(int signum);
void read_sensors();
void compute_heading(uint16_t xh, uint16_t xl, uint16_t yh, uint16_t yl, uint16_t zh, uint16_t zl);
void write_to_log_file(const char *data);
void close_resources_and_exit();

// Global variables
int i2c_fd = -1;
gpiod_device_t *i2c_dev;
bool running = true;

// Main function
int main() {
    setup_gpiod();
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    while (running) {
        read_sensors();
        compute_heading((uint16_t) (REG_ACCEL_XOUT_H >> 8), 
                         (uint16_t) (REG_ACCEL_XOUT_L >> 8), 
                         (uint16_t) (REG_ACCEL_YOUT_H >> 8), 
                         (uint16_t) (REG_ACCEL_YOUT_L >> 8), 
                         (uint16_t) (REG_ACCEL_ZOUT_H >> 8), 
                         (uint16_t) (REG_ACCEL_ZOUT_L >> 8), 
                         (uint16_t) (REG_MAG_X_H >> 8), 
                         (uint16_t) (REG_MAG_X_L >> 8), 
                         (uint16_t) (REG_MAG_Y_H >> 8), 
                         (uint16_t) (REG_MAG_Y_L >> 8), 
                         (uint16_t) (REG_MAG_Z_H >> 8), 
                         (uint16_t) (REG_MAG_Z_L >> 8));

        write_to_log_file("timestamp,heading,x_accel,y_accel,z_accel,mag_x,mag_y,mag_z\n");
        fflush(stdout);
    }

    close_resources_and_exit();

    return 0;
}

// Function to setup gpiod
void setup_gpiod() {
    i2c_dev = gpiod_get_device(I2C_BUS);
    if (i2c_dev == NULL) {
        fprintf(stderr, "Failed to get I2C device\n");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        gpiod_device_free(i2c_dev);
        exit(EXIT_FAILURE);
    }

    gpiod_i2c_config(i2c_fd, GPIOD_I2C_SPEED_100KHZ);
}

// Function to handle interrupts (SIGINT, SIGTERM)
void handle_interrupts(int signum) {
    running = false;
    close_resources_and_exit();
}

// Function to read data from the sensor
void read_sensors() {
    uint8_t command[2] = {0x00, 0x00}; // Start condition and register address for reading
    uint8_t data[6]; // Buffer for 6 bytes of sensor data

    if (gpiod_i2c_transfer(i2c_fd, command, 2, data, 6) != 6) {
        fprintf(stderr, "I2C transfer error\n");
        return;
    }

    // Convert raw data to signed integers
    int16_t x_accel = (data[0] << 8) | data[1];
    int16_t y_accel = (data[2] << 8) | data[3];
    int16_t z_accel = (data[4] << 8) | data[5];

    int16_t mag_x = (data[6] << 8) | data[7];
    int16_t mag_y = (data[8] << 8) | data[9];
    int16_t mag_z = (data[10] << 8) | data[11];

    // Compute heading using a simplified algorithm (not precise)
    // This is a placeholder; a more accurate algorithm should be implemented
    int16_t heading = atan2(-mag_y, mag_x) * 180.0 / M_PI;
    heading = (heading + 360) % 360; // Normalize heading to 0-360 degrees
}

// Function to write to the log file
void write_to_log_file(const char *data) {
    FILE *log_file = fopen("compass_log.txt", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s\n", data);
    fclose(log_file);
}

// Function to close resources and exit
void close_resources_and_exit() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        gpiod_device_free(i2c_dev);
    }

    exit(EXIT_SUCCESS);
}

