#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <stdint.h>

#define VL6180X_I2C_ADDR 0x39
#define VL6180X_REG_MEASURE_ID 0x00
#define VL6180X_REG_MEASURE_DATA 0x01

// GPIO for interrupt wake-up (optional, depends on your setup)
#define WAKEUP_GPIO 18

// File descriptor for distance logging
static int fd = -1;

// Function prototypes
void vl6180x_init(void);
int vl6180x_read_distance(uint16_t reg);
void sigint_handler(int signum);

int main(void) {
    // Initialize GPIO for wake-up (if applicable)
    if (gpiod_open(GPIOD_DIR_OUTPUT, WAKEUP_GPIO) < 0) {
        fprintf(stderr, "Error opening GPIO pin %d for wake-up\n", WAKEUP_GPIO);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Attempt to read distance
        int distance;
        if ((distance = vl6180x_read_distance(VL6180X_REG_MEASURE_DATA)) < 0) {
            // Handle I2C errors
            fprintf(stderr, "Error reading from VL6180X: %d\n", distance);
            vl6180x_init(); // Attempt re-initialization
            continue;
        }

        // Check if door is open or closed
        if (distance < 100) {
            fprintf(stderr, "DOOR_OPEN\n");
        } else {
            fprintf(stderr, "DOOR_CLOSED\n");
        }

        // Write to log file
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(fd, "%s %d\n", buffer, distance);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up on SIGINT
    return 0;
}

// VL6180X initialization function
void vl6180x_init(void) {
    int ret;

    // Initialize I2C device
    ret = gpiod_i2c_open(GPIOD_I2C_1, 40000);
    if (ret < 0) {
        fprintf(stderr, "Error opening I2C bus 1: %d\n", ret);
        return;
    }

    // Write to reset register
    ret = gpiod_i2c_write(GPIOD_I2C_1, VL6180X_I2C_ADDR, 0x00, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to reset register: %d\n", ret);
        gpiod_i2c_close(GPIOD_I2C_1);
        return;
    }

    // Write to power-up register
    ret = gpiod_i2c_write(GPIOD_I2C_1, VL6180X_I2C_ADDR, 0x01, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to power-up register: %d\n", ret);
        gpiod_i2c_close(GPIOD_I2C_1);
        return;
    }

    // Wait for sensor to stabilize
    usleep(100000);

    // Set measurement mode
    ret = gpiod_i2c_write(GPIOD_I2C_1, VL6180X_I2C_ADDR, VL6180X_REG_MEASURE_ID, 0x00);
    if (ret < 0) {
        fprintf(stderr, "Error setting measurement mode: %d\n", ret);
        gpiod_i2c_close(GPIOD_I2C_1);
        return;
    }
}

// Read distance from VL6180X
int vl6180x_read_distance(uint16_t reg) {
    int ret;

    // Write to the measurement register
    ret = gpiod_i2c_write(GPIOD_I2C_1, VL6180X_I2C_ADDR, reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to measurement register: %d\n", ret);
        return -1;
    }

    // Read back the data
    uint16_t data;
