#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_BUS_NUM 1
#define IMP23_ADDR 0x40
#define SAMPLE_RATE_HZ 8000
#define SAMPLE_INTERVAL_MS 10
#define SAMPLE_SIZE 2  // Two sensors
#define FILE_NAME "audio_log.dat"

// Function prototypes
void handle_signal(int signum);
void i2c_init();
void i2c_send_read(uint8_t addr, uint8_t reg, uint16_t *data, size_t len);
void read_samples(uint16_t *samples, size_t sample_count);
void compute_tdoa(uint16_t *samples1, uint16_t *samples2, uint16_t *tdoa);
void write_to_file(const char *line);
void cleanup();

// Global variables
gpiod_i2c_client *i2c_client;
uint16_t samples[SAMPLE_SIZE * 1000]; // Buffer for 1000 samples per sensor
uint16_t tdoa[SAMPLE_SIZE];
int file_fd = -1;
int retry_count = 0;

// Main function
int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C
    i2c_init();

    while (1) {
        // Sample sensors
        read_samples(samples, SAMPLE_SIZE);

        // Compute TDOA
        compute_tdoa(samples, samples + SAMPLE_SIZE / 2, tdoa);

        // Write to file
        write_to_file((char *) "sec,%ld,%ld,sensor1=%hu,sensor2=%hu,tdoa=%hu\n",
                      (long) time(NULL) / 1000, (long) time(NULL) % 1000,
                      samples[0], samples[1], tdoa[0]);

        // Check if we need to retry due to sensor absence or I2C error
        if (retry_count++ > 5) {
            fprintf(stderr, "Failed to sample sensors after 5 retries.\n");
            break;
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait for next interval
    }

    // Clean up
    cleanup();

    return 0;
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up on SIGINT
    cleanup();
    exit(0);
}

// Initialize I2C
void i2c_init() {
    int fd;
    struct i2c_dev *i2c_dev;

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Get I2C device structure
    i2c_dev = i2c_get_device(fd, I2C_BUS_NUM);
    if (!i2c_dev) {
        perror("Failed to get I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Allocate and initialize I2C client
    i2c_client = gpiod_i2c_client_alloc();
    if (!i2c_client) {
        perror("Failed to allocate I2C client");
        i2c_dev->release(i2c_dev);
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpiod_i2c_client_set_device(i2c_client, i2c_dev);
    gpiod_i2c_client_set_flags(i2c_client, GPIOD_I2C_CLIENT_FLAG_NO_BLOCKING);
}

// Send read request and handle response
void i2c_send_read(uint8_t addr, uint8_t reg, uint16_t *data, size_t len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = len,
        .buf = data
    };

    int ret = gpiod_i2c_transfer(i2c_client, &msg, 1);
    if (ret != len) {
        fprintf(stderr, "I2C transfer failed: %d bytes received\n", ret);
        // Handle error, possibly retry
    }
}

// Read samples from sensors
void read_samples(uint16_t *samples, size_t sample_count) {
    uint16_t data[2];
    size_t i;

    for (i = 0; i < sample_count; i++) {
        i2c_send_read(IMP23_ADDR, 0x00, data, sizeof(data));
        samples[i * 2] = data[0];
        samples[i * 2 + 1] = data[1];
    }
}

// Compute TDOA from two samples
void compute_tdoa(uint16_t *samples1, uint16_t *samples2, uint16_t *tdoa) {
    int diff;
    diff = samples1[0] - samples2[0];
    tdoa[0] = (diff < 0) ? -(SAMPLE_RATE_HZ * diff / 2) : (SAMPLE_RATE_HZ * diff / 2);
}

// Write to CSV file
void write_to_file(const char *line) {
    if (file_fd == -1) {
        file_fd = fopen(FILE_NAME, "a+");
        if (!file_fd) {
            perror("Failed to open file for writing");
            exit(EXIT_FAILURE);
        }
    }

    if (fwrite(line, 1, strlen(line), file_fd) != strlen(line)) {
        perror("Failed to write to file");
        fclose(file_fd);
        file_fd = -1;
    }
}

// Cleanup function
void cleanup() {
    // Close file
    if (file_fd != -1) {
        fclose(file_fd);
        file_fd = -1;
    }

    // Release I2C client
    gpiod_i2c_client_free(i2c_client);

    // Close I2C bus
    close(fd);
    i2c_dev->release(i2c_dev);
}

