#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <time.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod/spi.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CLOCK_FREQ 1000000
#define SPI_MODE 3
#define SPI_CS_PIN 8
#define ADIS16488A_REG_CMD 0x00
#define ADIS16488A_REG_DATA 0x01

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

volatile sig_atomic_t running = 1;

void cleanup(void) {
    if (spi_fd != -1) {
        gpiod_spi_unexport(spi_fd);
        close(spi_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        remove("imu_data.csv");
    }
}

void handle_signal(int signum) {
    running = 0;
    if (waitpid(-1, NULL, 0) == -1) {
        perror("waitpid");
    }
}

int main(void) {
    struct gpiod_spi_config spi_config;
    int spi_fd;
    int csv_file;
    char buffer[3];
    uint16_t command_word, data_word;
    time_t timestamp;
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Initialize SPI device
    spi_config.speed_hz = SPI_CLOCK_FREQ;
    spi_config.mode = SPI_MODE;
    spi_config.cs_gpio = GPIO_NUM_TO_PIN(SPI_CS_PIN);
    spi_fd = gpiod_spi_open(SPI_DEVICE, &spi_config);

    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Setup atexit handler for cleanup
    atexit(cleanup);

    // Open CSV file for writing
    csv_file = fopen("imu_data.csv", "a+");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpiod_spi_unexport(spi_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Header row
    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    while (running) {
        // Non-blocking delay
        struct timespec timeout = { 0, 10000 }; // 10ms
        while (!running && nanosleep(&timeout, NULL) == 0);

        // Prepare command word
        command_word = (uint16_t)((0 << 15) | (ADIS16488A_REG_CMD << 8) | (ADIS16488A_REG_DATA));

        // Send command and wait for stall time
        gpiod_spi_transfer(spi_fd, &command_word, sizeof(command_word), buffer, 2, 0, 40 * 1000);

        // Read data word
        gpiod_spi_transfer(spi_fd, buffer, 2, &data_word, sizeof(data_word), 0, 0);

        // Convert raw data to physical units
        gyro_x = (data_word & 0x01FF) * GYRO_SENSITIVITY;
        gyro_y = ((data_word & 0x03E0) >> 5) * GYRO_SENSITIVITY;
        gyro_z = ((data_word & 0x07C0) >> 9) * GYRO_SENSITIVITY;

        accel_x = (data_word & 0x01FF) * ACCEL_SENSITIVITY;
        accel_y = ((data_word & 0x03E0) >> 5) * ACCEL_SENSITIVITY;
        accel_z = ((data_word & 0x07C0) >> 9) * ACCEL_SENSITIVITY;

        // Get current timestamp
        timestamp = time(NULL);

        // Write to CSV file
        fprintf(csv_file, "%ld,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Close the SPI device and CSV file on exit
        if (!running) {
            gpiod_spi_unexport(spi_fd);
            close(spi_fd);
            fclose(csv_file);
            remove("imu_data.csv");
        }
    }

    // Handle signals
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to install signal handlers");
    }

    return EXIT_SUCCESS;
}

