        while (!running && nanosleep(&timeout, NULL) == 0);

        // Prepare command word
        command_word = (uint16_t)((0 << 15) | (ADIS16488A_REG_CMD << 8) | (ADIS16488A_REG_DATA));

        // Send command and wait for stall time
        gpiod_spi_transfer(spi_fd, &command_word, sizeof(command_word), buffer, 2, 0, 40 * 1000);

        // Read data word
        gpiod_spi_transfer(spi_fd, buffer, 2, &data_word, sizeof(data_word), 0, 0);

        // Convert raw data to physical units
        gyro_x = (data_word & 0x01FF) * GYRO_SENSITIVITY;
        gyro_y = ((data_word & 0x03E0) >> 5) * GYRO_SENSITIVITY;
        gyro_z = ((data_word & 0x07C0) >> 9) * GYRO_SENSITIVITY;

        accel_x = (data_word & 0x01FF) * ACCEL_SENSITIVITY;
        accel_y = ((data_word & 0x03E0) >> 5) * ACCEL_SENSITIVITY;
        accel_z = ((data_word & 0x07C0) >> 9) * ACCEL_SENSITIVITY;

        // Get current timestamp
        timestamp = time(NULL);

        // Write to CSV file
        fprintf(csv_file, "%ld,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Close the SPI device and CSV file on exit
        if (!running) {
            gpiod_spi_unexport(spi_fd);
            close(spi_fd);
            fclose(csv_file);
            remove("imu_data.csv");
        }
    }

    // Handle signals
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to install signal handlers");
    }

    return EXIT_SUCCESS;
}
