#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <stdint.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8 // BCM GPIO 8
#define SPI_MODE 3
#define MAX_CLOCK_HZ 1000000
#define GYRO_SCALE 0.02
#define ACCEL_SCALE 0.00025

void setup_spi(const int cs_pin) {
    int spi_fd;
    struct spi_device_id ids[] = {
        SPI_DEVICE_ID(SPI_DEVICE, SPI_MODE, CS_PIN),
        { }
    };

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MAX_CLOCK_HZ) < 0) {
        perror("Failed to set SPI max clock speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &cs_pin) < 0) {
        perror("Failed to set chip select pin");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    printf("SPI initialized successfully.\n");
}

void cleanup_spi() {
    close(spi_fd);
    printf("SPI device closed.\n");
}

void read_imu_data() {
    uint16_t address = (uint16_t)(1 << 7) | (uint16_t)GYRO_REG; // Set bit 7 for read
    uint16_t data;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(2), &address) < 0) {
        perror("Failed to send address for read");
        return;
    }

    if (read(spi_fd, &data, 2) != 2) {
        perror("Failed to read data");
        return;
    }

    // Scale and print gyroscope data
    float gyro_x = (data & 0x0000FFFF) * GYRO_SCALE;
    float gyro_y = ((data >> 16) & 0x0000FFFF) * GYRO_SCALE;
    float gyro_z = ((data >> 32) & 0x0000FFFF) * GYRO_SCALE;

    printf("Gyro: X = %.6f dps, Y = %.6f dps, Z = %.6f dps\n", gyro_x, gyro_y, gyro_z);

    // Scale and print accelerometer data
    float accel_x = (data & 0x000000FF) * ACCEL_SCALE;
    float accel_y = ((data >> 8) & 0x000000FF) * ACCEL_SCALE;
    float accel_z = ((data >> 16) & 0x000000FF) * ACCEL_SCALE;

    printf("Accel: X = %.6f g, Y = %.6f g, Z = %.6f g\n", accel_x, accel_y, accel_z);
}

int main() {
    setup_spi(CS_PIN);

    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        read_imu_data();
        usleep(100000); // Sleep for 100 ms
    }

    cleanup_spi();
    return 0;
}

