#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHANNEL 0
#define SPI_SPEED MHZ(1)
#define SPI_MODE 0
#define GPIO8 8

volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO for CE0
    int ret = gpiod_open(GPIOD_DIR_OUTPUT, GPIO8, GPIOD_OPEN_SHARED);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO8: %s\n", gpiod_error_string(ret));
        return EXIT_FAILURE;
    }

    // Initialize SPI
    struct spi_device *spi;
    ret = spi_device_lookup(SPI_CHANNEL, &spi);
    if (ret < 0) {
        fprintf(stderr, "Error looking up SPI device: %s\n", spi_device_error_string(ret));
        gpiod_close(GPIO8);
        return EXIT_FAILURE;
    }

    ret = spi_setup(spi, SPI_SPEED, SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Error setting up SPI: %s\n", spi_error_string(ret));
        spi_device_free(spi);
        gpiod_close(GPIO8);
        return EXIT_FAILURE;
    }

    // Open SPI device
    ret = spi_open(spi);
    if (ret < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", spi_open_error_string(ret));
        spi_device_free(spi);
        gpiod_close(GPIO8);
        return EXIT_FAILURE;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Main loop
    while (!should_exit) {
        // Set CE0 high to select the IMU
        gpiod_set_value(GPIO8, 1);

        // Send read command (register address with bit 15 set)
        uint16_t read_cmd = (uint16_t)(1 << 15) | 0x0000; // Example register address
        ret = spi_transfer(spi, &read_cmd, 2);
        if (ret < 0) {
            fprintf(stderr, "Error during SPI transfer: %s\n", spi_transfer_error_string(ret));
            break;
        }

        // Wait at least 40 µs for the IMU to respond
        usleep(40000);

        // Send dummy value to clock out data
        uint16_t dummy = 0x0000;
        ret = spi_transfer(spi, &dummy, 2);
        if (ret < 0) {
            fprintf(stderr, "Error during dummy transfer: %s\n", spi_transfer_error_string(ret));
            break;
        }

        // Read gyroscope and accelerometer data
        uint16_t data[2];
        ret = spi_transfer(spi, data, 2);
        if (ret < 0) {
            fprintf(stderr, "Error during data transfer: %s\n", spi_transfer_error_string(ret));
            break;
        }

        // Scale and print data
        float gyro_x = (data[0] * 0.05) / 65535.0;
        float gyro_y = (data[1] * 0.05) / 65535.0;
        float gyro_z = (data[2] * 0.05) / 65535.0;

        float accel_x = (data[3] * 0.00025) / 65535.0;
        float accel_y = (data[4] * 0.00025) / 65535.0;
        float accel_z = (data[5] * 0.00025) / 65535.0;

        printf("Gyro: x=%f, y=%f, z=%f\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: x=%f, y=%f, z=%f\n", accel_x, accel_y, accel_z);

        // Set CE0 low to deselect the IMU
        gpiod_set_value(GPIO8, 0);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_close(GPIO8);
    spi_device_free(spi);
    spi_close(spi);

    return EXIT_SUCCESS;
}

// Helper function for SPI transfer
int spi_transfer(struct spi_device *spi, uint16_t *tx_buffer, size_t tx_len) {
    int ret;
    ret = spi_write(spi, tx_buffer, tx_len);
    if (ret < 0) {
        return ret;
    }

    ret = spi_read(spi, rx_buffer, tx_len);
    if (ret < 0) {
        return ret;
    }

    return 0;
}

