#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <inttypes.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE_PATH "/dev/i2c-1" // Adjust for your Raspberry Pi's I2C bus
#define MPU6886_I2C_ADDR 0x68 // Address of TDK MPU-6886

// Structure for MPU-6886 register definitions
typedef struct {
    uint8_t ACCEL_XOUT_H;
    uint8_t ACCEL_XOUT_L;
    uint8_t ACCEL_YOUT_H;
    uint8_t ACCEL_YOUT_L;
    uint8_t ACCEL_ZOUT_H;
    uint8_t ACCEL_ZOUT_L;
    uint8_t TEMP_OUT_H;
    uint8_t TEMP_OUT_L;
    uint8_t GYRO_XOUT_H;
    uint8_t GYRO_XOUT_L;
    uint8_t GYRO_YOUT_H;
    uint8_t GYRO_YOUT_L;
    uint8_t GYRO_ZOUT_H;
    uint8_t GYRO_ZOUT_L;
} mpu6886_data_t;

// Function prototypes
void handle_signal(int signum);
void read_mpu6886_data(int fd);
void cleanup();

int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Initialize GPIO and I2C
    if (gpiod_open(GPIOD_DIR_DEV) < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }
    if (i2c_open(I2C_DEVICE_PATH, I2C_FLAG_RDWR) < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Attempt to read data from the IMU
        for (int i = 0; i < 3; ++i) {
            if (i2c_transfer(i2c_fd, &MPU6886_I2C_ADDR, {I2C_M_RD}, &read_cmd, 1, NULL) < 0) {
                // Check for errors and retry
                if (i < 2) {
                    fprintf(stderr, "Failed to read from IMU, retrying...\n");
                    usleep(10000); // Wait 10ms before retrying
                } else {
                    // Maximum retries exceeded, handle error gracefully
                    fprintf(stderr, "Failed to read from IMU after 3 attempts.\n");
                    break;
                }
            } else {
                read_mpu6886_data(i2c_fd);
                break; // Successfully read data, break out of retry loop
            }
        }

        // Sleep for 50ms to meet the 50ms read interval requirement
        usleep(50000);
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to read data from the MPU-6886
void read_mpu6886_data(int fd) {
    // Send read command to the IMU
    uint8_t read_cmd[] = {0x3B, 0x00}; // Read all registers command

    if (i2c_transfer(fd, &MPU6886_I2C_ADDR, {I2C_M_RD}, read_cmd, sizeof(read_cmd), NULL) < 0) {
        perror("i2c_transfer read command");
        return;
    }

    // Read data from the IMU
    mpu6886_data_t data;
    if (i2c_transfer(fd, &MPU6886_I2C_ADDR, {I2C_M_RD}, &data, sizeof(data), NULL) < 0) {
        perror("i2c_transfer data read");
        return;
    }

    // Print accelerometer and gyroscope values
    printf("Accelerometer:\n");
    printf("  X: %hu %hu\n", data.ACCEL_XOUT_H, data.ACCEL_XOUT_L);
    printf("  Y: %hu %hu\n", data.ACCEL_YOUT_H, data.ACCEL_YOUT_L);
    printf("  Z: %hu %hu\n", data.ACCEL_ZOUT_H, data.ACCEL_ZOUT_L);

    printf("Gyroscope:\n");
    printf("  X: %hu %hu\n", data.GYRO_XOUT_H, data.GYRO_XOUT_L);
    printf("  Y: %hu %hu\n", data.GYRO_YOUT_H, data.GYRO_YOUT_L);
    printf("  Z: %hu %hu\n", data.GYRO_ZOUT_H, data.GYRO_ZOUT_L);

    // Print temperature and other values if needed
    // printf("Temperature: %hu %hu\n", data.TEMP_OUT_H, data.TEMP_OUT_L);
}

// Function to clean up resources
void cleanup() {
    // Close I2C file descriptor
    if (i2c_close(i2c_fd) < 0) {
        perror("i2c_close");
    }

    // Close GPIO device
    gpiod_close(GPIOD_DIR_DEV);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up resources on SIGINT
    cleanup();
    exit(EXIT_SUCCESS);
}

