        .addr = ADXL345_ADDR,
        .flags = I2C_M_WRITE,
        .buf = &data,
        .len = 1
    };

    // Send I2C write request
    int ret = i2c_transfer(i2c_fd, &msg, 1);
    if (ret != 1) {
