        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Perform burst read
        burstReadResult = burstReadIMU(&imuData);

        if (burstReadResult) {
            // Successfully read data, process and write to CSV
            writeToCSV(timestamp, &imuData);
        } else {
            // Handle error
            snprintf(buffer, sizeof(buffer), "Error reading IMU data: %s", strerror(errno));
            fprintf(stderr, "%s\n", buffer);
        }

        // Sleep for 100ms to achieve 10 Hz sampling rate
        usleep(100000);
    }

    // Close resources on exit (Ctrl+C)
    handleInterrupt(SIGINT);

    // Clean up
    closeI2C();

    return 0;
}

// Function to open I2C bus
void openI2C() {
    int i2c_fd;
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    i2cHandle = i2c_fd;
}

// Function to close I2C bus and release resources
void closeI2C() {
    if (i2cHandle != -1) {
        close(i2cHandle);
        i2cHandle = -1;
    }
}

// Function to perform burst read from the IMU
int burstReadIMU(IMUData *data) {
    int bytesWritten;
    struct i2c_msg msg[2];

    // Set up I2C messages
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 2;  // Request 2 bytes (accelerometer X and Y)
    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = 2;  // Request 2 bytes (gyroscope X and Y)

    // Perform the I2C transaction
    bytesWritten = i2c_transfer(i2cHandle, msg, 2);

    if (bytesWritten != 2) {
        fprintf(stderr, "Error during I2C transfer: %d bytes written, expected 2\n", bytesWritten);
        return 0;
    }

    // Read the data from the I2C response buffer
    data->ax = msg[0].buf[0];
    data->ay = msg[0].buf[1];
    data->gx = msg[1].buf[0];
    data->gy = msg[1].buf[1];
    data->az = msg[0].buf[2];
    data->gz = msg[1].buf[2];

    return 1;
}

// Function to write IMU data to CSV file
void writeToCSV(const char *timestamp, const IMUData *imuData) {
    snprintf(csvLine, sizeof(csvLine), "%s,%d,%d,%d,%d,%d\n",
             timestamp,
             imuData->ax,
             imuData->ay,
             imuData->az,
             imuData->gx,
             imuData->gy,
             imuData->gz);

    // Open or create the CSV file
    int fd = fopen("imu_log.csv", "a+");
    if (fd == -1) {
        fprintf(stderr, "Error opening CSV file for writing: %s\n", strerror(errno));
        return;
    }

    // Write the line to the file
    if (fwrite(csvLine, sizeof(csvLine), 1, fd) != 1) {
        fclose(fd);
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    fclose(fd);
}

// Function to handle Ctrl+C (SIGINT)
void handleInterrupt(int signum) {
    // Close I2C handle, terminate libi2c, and close CSV file
    closeI2C();
    // Assuming libi2c is properly initialized and terminated here
    // Close CSV file
    fclose(STDOUT_FILENO);  // Trick to close the file descriptor associated with stdout

    // Exit the program
    exit(EXIT_SUCCESS);
}
