int main() {
    // Initialize GPIO
    int gpio17_fd;
    gpio17_fd = gpiod_open(GPIO17, GPIO_OUTPUT);
    if (gpio17_fd < 0) {
        perror("Failed to open GPIO 17");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    int i2c_fd;
    i2c_fd = i2c_open(I2C_BUS_NUM, I2C_FLAG_NONE);
    if (i2c_fd < 0) {
