    while (1) {
        // Check for signals
        if (waitpid(-1, NULL, WUNTRACED) == -1) {
            perror("waitpid error");
            break;
        }

        // Read ID register to verify sensor
        uint8_t id_reg;
        if (i2c_smbus_read_byte_data(i2c_fd, GY45_ADDR, ID_REG) != 0) {
            fprintf(log_file, "Error reading ID register\n");
            continue;
        }
        if (id_reg != 0x55) {
            fprintf(log_file, "Sensor ID mismatch, terminating\n");
            break;
        }

        // Read acceleration data
        float x_accel, y_accel, z_accel;
        if (i2c_smbus_read_i2c_block_data(i2c_fd, GY45_ADDR, DATA_REG_X, 1, &x_accel) != 1 ||
            i2c_smbus_read_i2c_block_data(i2c_fd, GY45_ADDR, DATA_REG_Y, 1, &y_accel) != 1 ||
            i2c_smbus_read_i2c_block_data(i2c_fd, GY45_ADDR, DATA_REG_Z, 1, &z_accel) != 1) {
            fprintf(log_file, "Error reading acceleration data\n");
            continue;
        }

        // Check for threshold exceeded
        float magnitude = sqrt(x_accel * x_accel + y_accel * y_accel + z_accel * z_accel);
        if (magnitude > THRESHOLD_G) {
            // Turn on LED
            if (gpio_write(gpio17_fd, 1) == -1) {
                fprintf(log_file, "Error writing to GPIO 17\n");
                continue;
            }
            // Wait for 500ms
            usleep(500000);
            // Turn off LED
            if (gpio_write(gpio17_fd, 0) == -1) {
                fprintf(log_file, "Error writing to GPIO 17\n");
            }
        }

        // Log data with timestamp
        struct timeval now;
        gettimeofday(&now, NULL);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
        fprintf(log_file, "Timestamp: %s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", timestamp, x_accel, y_accel, z_accel);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up on exit
    gpio_close(gpio17_fd);
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

