#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <i2c.h>
#include <stdint.h>

#define I2C_ADDR 0x53  // Default address for ADXL345
#define GPIO_INT_PIN 17 // GPIO 17 for INT1

// Constants for ADXL345 register addresses
#define REG_ACCEL_XOUT_H   0x32
#define REG_ACCEL_XOUT_L   0x33
#define REG_ACCEL_YOUT_H   0x34
#define REG_ACCEL_YOUT_L   0x35
#define REG_ACCEL_ZOUT_H   0x36
#define REG_ACCEL_ZOUT_L   0x37

// Function prototypes
void adxl345_init(void);
void setup_freefall_detector(void);
void handle_freefall(int);
void cleanup(void);
void write_to_csv(const char *timestamp, int x, int y, int z);

int main(void) {
    // Initialize ADXL345 and setup free-fall detector
    adxl345_init();
    setup_freefall_detector();

    // Main loop
    while (1) {
        // Poll for GPIO interrupt
        if (gpiod_event_get(GPIOD, GPIO_INT_PIN) != GPIOD_EVENT_NONE) {
            handle_freefall(0); // Handle free-fall event
        }

        // Sleep to avoid excessive CPU usage
        usleep(10000);
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize the ADXL345
void adxl345_init(void) {
    int i2c_fd;
    struct i2c_dev *i2c_dev;
    struct i2c_msg msg;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Get I2C device structure
    i2c_dev = i2c_new_device(i2c_fd, I2C_ADDR);
    if (!i2c_dev) {
        perror("Failed to get I2C device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check if the device responds correctly
    if (i2c_smbus_read_word_data(i2c_dev, 0x00) != 0x53) {
        fprintf(stderr, "Device ID mismatch, expected 0x53\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Place the sensor in standby mode
    msg.addr = I2C_ADDR;
    msg.len = 1;
    msg.buf = &STANDBY_MODE;
    if (i2c_smbus_write_byte_data(i2c_dev, 0x00, STANDBY_MODE) != 0) {
        perror("Failed to set ADXL345 to standby mode");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Close I2C device structure
    i2c_del_device(i2c_dev);
    close(i2c_fd);
}

// Function to setup free-fall detector
void setup_freefall_detector(void) {
    struct gpiod_dir gpio_dir;
    struct gpiod_cbs cbs;
    int ret;

    // Set GPIO 17 as input
    ret = gpiod_direction_input(GPIOD, GPIO_INT_PIN);
    if (ret != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to configure GPIO %d as input\n", GPIO_INT_PIN);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO interrupt callback
    cbs.data = (void *) &handle_freefall;
    cbs.size = sizeof(handle_freefall);
    ret = gpiod_cbs_set(GPIOD, GPIO_INT_PIN, &cbs);
    if (ret != GPIOD_SUCCESS) {
        fprintf(stderr, "Failed to set GPIO interrupt callback\n");
        exit(EXIT_FAILURE);
    }
}

// Function to handle free-fall event
void handle_freefall(int unused) {
    struct timespec ts;
    uint8_t x, y, z;
    char timestamp[50];

    // Get current time
    clock_gettime(CLOCK_REALTIME, &ts);

    // Read acceleration data
    x = i2c_smbus_read_byte_data(i2c_fd, REG_ACCEL_XOUT_H);
    x |= (i2c_smbus_read_byte_data(i2c_fd, REG_ACCEL_XOUT_L) << 8);
    y = i2c_smbus_read_byte_data(i2c_fd, REG_ACCEL_YOUT_H);
