    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Get I2C device structure
    i2c_dev = i2c_new_device(i2c_fd, I2C_ADDR);
    if (!i2c_dev) {
        perror("Failed to get I2C device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
