    if (i2c_smbus_read_word_data(i2c_dev, 0x00) != 0x53) {
        fprintf(stderr, "Device ID mismatch, expected 0x53\n");
        i2c_del_device(i2c_dev);
        close(i2c_fd);
        exit(EXIT_FAILURE);
