                idle = false;
                fprintf(stderr, "Transition to FREEFALL detected.\n");
            }
        } else if (freefall && acceleration_magnitude > IMPACT_THRESHOLD) {
            freefall = false;
            impact = true;
            idle = false;
            fprintf(stderr, "Transition to IMPACT detected.\n");
        }

        // Log data to CSV file
        sprintf(buffer, "%d,%f,%f,%f,%f,%f\n", timestamp, acceleration[0], acceleration[1], acceleration[2], gyroscope[0], gyroscope[1]);
        if (write(1, buffer, strlen(buffer)) != strlen(buffer)) {
            fprintf(stderr, "Error: Failed to write to CSV file.\n");
        }

        // Check for SIGINT or SIGTERM
        if (signal(SIGINT, SIG_IGN) == SIG_ERR ||
            signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error: Failed to ignore SIGINT and SIGTERM.\n");
            break;
        }

        // Clean up on exit
        close(i2c_fd);
        gpiod_free_dir(sda_dir);
        gpiod_free_dir(scl_dir);

        // Exit on SIGINT or SIGTERM
        if (idle && (signal(SIGINT, SIG_DFL) == SIG_DFL ||
                     signal(SIGTERM, SIG_DFL) == SIG_DFL)) {
            break;
        }
    }

    // Close file descriptor on exit
    close(i2c_fd);

    // Free resources
    gpiod_free_dir(sda_dir);
    gpiod_free_dir(scl_dir);

    return EXIT_SUCCESS;
}

