#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <libgpiod.h>

#define GY50_REG_WHO_AM_I 0x0F
#define GY50_REG_X_L 0x21
#define GY50_REG_Y_L 0x22
#define GY50_REG_Z_L 0x23

#define BUS_NUM 1
#define DEVICE_ADDR 0x68

// Function prototypes
void gyro_init(void);
void gyro_read(uint16_t *x, uint16_t *y, uint16_t *z);
void gyro_close(void);
void handle_interrupt(int signum);

int main(void) {
    // Initialize GPIO and I2C
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-" BUS_NUM, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    // Open CSV file for writing
    char filename[256];
    snprintf(filename, sizeof(filename), "gyro_log.csv");
    FILE *csv_file = fopen(filename, "a+");
    if (!csv_file) {
        perror("fopen CSV file");
        fclose(i2c_fd); // Close I2C bus handle
        return EXIT_FAILURE;
    }

    // Header row
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = handle_interrupt;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        uint16_t x, y, z;
        struct timeval tv;

        // Read WHO_AM_I register to verify sensor presence
        if (gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_WHO_AM_I, 1) != 1) {
            fprintf(stderr, "Error reading WHO_AM_I register\n");
            break;
        }
        if (gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_WHO_AM_I, 1) != 0x68) {
            fprintf(stderr, "Expected WHO_AM_I = 0x68, got %02X\n", gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_WHO_AM_I, 1));
            break;
        }

        // Read angular velocity data
        gyro_init();
        gyro_read(&x, &y, &z);
        gettimeofday(&tv, NULL);
        fprintf(csv_file, "%lld,%d,%d,%d\n", (long long)tv.tv_sec * 1000000 + tv.tv_usec, x, y, z);

        usleep(10000); // Sleep for 10ms
    }

    // Clean up
    gyro_close();
    fclose(csv_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

// Function to initialize the gyroscope
void gyro_init(void) {
    // Attempt to write to the gyroscope up to 3 times in case of bus errors
    for (int i = 0; i < 3; ++i) {
        if (gpiod_c_write(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_WHO_AM_I, 1, 0x68) != 1) {
            fprintf(stderr, "Error writing to WHO_AM_I register\n");
            usleep(10000); // Short delay before retry
        } else {
            break;
        }
    }

    if (i == 3) {
        fprintf(stderr, "Failed to initialize gyroscope after 3 attempts\n");
        exit(EXIT_FAILURE);
    }
}

// Function to read angular velocity data
void gyro_read(uint16_t *x, uint16_t *y, uint16_t *z) {
    gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_X_L, 2, x);
    gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_Y_L, 2, y);
    gpiod_c_read(i2c_fd, BUS_NUM, DEVICE_ADDR, GY50_REG_Z_L, 2, z);
}

// Function to close resources and cleanup
void gyro_close(void) {
    gpiod_c_close(i2c_fd);
}

// Signal handler for SIGINT
void handle_interrupt(int signum) {
    fprintf(stderr, "Received SIGINT, terminating gracefully...\n");
    // Perform cleanup here if necessary
    // For simplicity, we just exit
    exit(EXIT_FAILURE);
}

