#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <libgpiod/gpiod.h>

#define GPIO_NUM 17 // GPIO17 on Raspberry Pi Zero W
#define FILE_NAME "flame_events.log"
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t should_exit = 0;

void setup_signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Open the GPIO pin
    struct gpiod_dir *dir;
    struct gpiod_cand *cand;
    int fd;

    cand = gpiod_cand_lookup(GPIO_NUM);
    if (!cand) {
        fprintf(stderr, "Failed to find GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    dir = gpiod_open(cand, GPIOD_OPEN_DIR);
    if (!dir) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_cand_free(cand);
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor
    if (gpiod_set_direction(dir, GPIOD_DIR_INPUT_PULLUP) < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to INPUT_PULLUP: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
        gpiod_close(dir);
        gpiod_cand_free(cand);
        return EXIT_FAILURE;
    }

    // Open the log file in append mode
    int log_fd = open(FILE_NAME, O_APPEND | O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file %s: %s\n", FILE_NAME, strerror(errno));
        gpiod_close(dir);
        gpiod_cand_free(cand);
        return EXIT_FAILURE;
    }

    // SIGINT handler
    signal(SIGINT, setup_signal_handler);

    while (!should_exit) {
        // Poll the GPIO pin
        int value;
        if (gpiod_get_value(dir, &value) < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            continue;
        }

        // Check if flame is detected
        if (value == 0) {
            // Flame detected
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
            fprintf(log_fd, "%s - Flame detected: YES\n", timestamp);
            printf("FLAME DETECTED!\n");
        } else {
            // No flame detected
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
            fprintf(log_fd, "%s - Flame detected: NO\n", timestamp);
        }

        // Sleep for 500ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Close the log file and cleanup resources
    if (log_fd > 0) {
        close(log_fd);
    }
    gpiod_close(dir);
    gpiod_cand_free(cand);

    // Clean up libgpiod
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

