        fprintf(stderr, "Failed to open log file %s: %s\n", FILE_NAME, strerror(errno));
        gpiod_close(dir);
        gpiod_cand_free(cand);
        return EXIT_FAILURE;
    }

    // SIGINT handler
    signal(SIGINT, setup_signal_handler);

    while (!should_exit) {
        // Poll the GPIO pin
        int value;
        if (gpiod_get_value(dir, &value) < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_NUM, gpiod_errstr(gpiod_get_error()));
            continue;
        }

        // Check if flame is detected
        if (value == 0) {
            // Flame detected
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
            fprintf(log_fd, "%s - Flame detected: YES\n", timestamp);
            printf("FLAME DETECTED!\n");
        } else {
            // No flame detected
            char timestamp[50];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S ", localtime(&now));
            fprintf(log_fd, "%s - Flame detected: NO\n", timestamp);
        }

        // Sleep for 500ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Close the log file and cleanup resources
    if (log_fd > 0) {
        close(log_fd);
    }
    gpiod_close(dir);
    gpiod_cand_free(cand);

    // Clean up libgpiod
    gpiod_cleanup();

    return EXIT_SUCCESS;
}
