        if (ioctl(i2c_fd, I2C_READ, (char *) &SENSOR_REG_Y) < 0) {
            perror("Failed to read Y-axis");
            continue;
        }
        data.y = (int) i2c_smbus_read_word_data(i2c_fd, SENSOR_REG_Y);

        if (ioctl(i2c_fd, I2C_READ, (char *) &SENSOR_REG_Z) < 0) {
            perror("Failed to read Z-axis");
            continue;
        }
        data.z = (int) i2c_smbus_read_word_data(i2c_fd, SENSOR_REG_Z);

        // Append data to CSV
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);

        // Close resources on exit
        if (csv_file != NULL) fclose(csv_file);
        if (i2c_fd != -1) close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

