#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO27 27

// Function prototypes
void setup_hall_sensors();
void read_hall_sensors();
void handle_interrupts(int signum);
void cleanup();

int main() {
    // Initialize GPIO
    if (gpiod_open() < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    setup_hall_sensors();

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_interrupts;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        read_hall_sensors();
        usleep(50000); // Sleep for 50 ms
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to setup Hall sensors
void setup_hall_sensors() {
    struct gpiod_chip *chip;
    struct gpiod_pin *pin1, *pin2;

    chip = gpiod_get_chip_by_name("gpiochip-bcm2708");
    if (!chip) {
        perror("gpiod_get_chip_by_name");
        exit(EXIT_FAILURE);
    }

    pin1 = gpiod_get_pin(chip, GPIO17, GPIOD_OUT_INIT_LOW);
    if (!pin1) {
        perror("gpiod_get_pin for GPIO17");
        exit(EXIT_FAILURE);
    }

    gpiod_set_bias(pin1, GPIOD_PIN_BIAS_PULL_UP);
    gpiod_direction_input(pin1);

    pin2 = gpiod_get_pin(chip, GPIO27, GPIOD_OUT_INIT_LOW);
    if (!pin2) {
        perror("gpiod_get_pin for GPIO27");
        exit(EXIT_FAILURE);
    }

    gpiod_set_bias(pin2, GPIOD_PIN_BIAS_PULL_UP);
    gpiod_direction_input(pin2);

    printf("Hall sensors initialized.\n");
}

// Function to read Hall sensors
void read_hall_sensors() {
    int state1, state2;
    struct timespec timestamp;

    // Read states
    state1 = gpiod_read(pin1);
    state2 = gpiod_read(pin2);

    // Get timestamp
    clock_gettime(CLOCK_MONOTONIC, &timestamp);

    // Log states to file
    FILE *file = fopen("conveyor_log.txt", "a+");
    if (!file) {
        perror("fopen conveyor_log.txt");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%ld %d %d\n", timestamp.tv_sec, state1, state2);

    fclose(file);

    // Check for halt condition
    if (state1 && state2) {
        printf("Conveyor halted.\n");
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_interrupts(int signum) {
    printf("Received signal %d, performing graceful shutdown.\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    struct gpiod_pin *pin1, *pin2;

    // Release pins
    pin1 = gpiod_get_pin(gpiod_get_chip_by_name("gpiochip-bcm2708"), GPIO17, GPIOD_OUT_INIT_LOW);
    if (pin1) {
        gpiod_put_pin(pin1);
    }

    pin2 = gpiod_get_pin(gpiod_get_chip_by_name("gpiochip-bcm2708"), GPIO27, GPIOD_OUT_INIT_LOW);
    if (pin2) {
        gpiod_put_pin(pin2);
    }

    // Close GPIO chip
    gpiod_close();
}

