        gpiod_close(GPIOD_DIR_I2C);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Open log file for appending
    char log_file_path[100] = "fall_log.txt";
    int log_file_fd = open(log_file_path, O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (log_file_fd < 0) {
        perror("open log file");
        close(i2c_fd);
        gpiod_close(GPIOD_DIR_I2C);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Check WHO_AM_I register
        uint8_t who_am_i;
        if (i2c_smbus_read_byte_data(i2c_fd, GY45_REG_WHO_AM_I, &who_am_i) < 0) {
            perror("i2c_smbus_read_byte_data");
            continue;
        }
        if (who_am_i != 0x68) {
            fprintf(stderr, "Sensor identity not verified: WHO_AM_I = %02X\n", who_am_i);
            break;
        }

        // Initialize control register
        uint8_t ctrl_reg;
        if (i2c_smbus_read_byte_data(i2c_fd, GY45_REG_CTRL, &ctrl_reg) < 0) {
            perror("i2c_smbus_read_byte_data");
            continue;
        }
        ctrl_reg &= 0xF0; // Clear upper nibble
        ctrl_reg |= 0x0A; // Standby mode, 100 Hz data rate
        if (i2c_smbus_write_byte_data(i2c_fd, GY45_REG_CTRL, ctrl_reg) < 0) {
            perror("i2c_smbus_write_byte_data");
            continue;
        }

        // Read data registers
        uint16_t data[6];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, GY45_REG_DATA_X_L, 2, data, 2) < 0) {
            perror("i2c_smbus_read_i2c_block_data");
            continue;
        }

        // Combine MSB and LSB for each axis
        int x_raw = ((data[0] << 8) | data[1]) >> 4;
        int y_raw = ((data[2] << 8) | data[3]) >> 4;
        int z_raw = ((data[4] << 8) | data[5]) >> 4;

        // Compute absolute tilt
        double tilt_x = (x_raw > 0) ? x_raw : -x_raw;
        double tilt_y = (y_raw > 0) ? y_raw : -y_raw;
        double tilt_z = (z_raw > 0) ? z_raw : -z_raw;

        double magnitude = sqrt(tilt_x * tilt_x + tilt_y * tilt_y + tilt_z * tilt_z);
        double tilt_angle = atan2(magnitude, sqrt(tilt_x * tilt_x + tilt_z * tilt_z)) * 180.0 / M_PI;

        // Check for fall
        if (tilt_angle > FALL_THRESHOLD) {
            char timestamp[50];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &ts);
            fprintf(log_file_fd, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x_raw, y_raw, z_raw);
            fflush(log_file_fd);
        }

        // Close resources on SIGINT or SIGTERM
        handle_interrupts(0);
    }

    // Close resources on normal exit
    close_resources();

    // Close I2C and log file descriptors
    close(i2c_fd);
    close(log_file_fd);
    gpiod_close(GPIOD_DIR_I2C);

    return EXIT_SUCCESS;
}

// Signal handler to close resources
void handle_interrupts(int signum) {
    close(i2c_fd);
    close(log_file_fd);
}

// Function to close I2C and log file descriptors
void close_resources(void) {
    close(i2c_fd);
    close(log_file_fd);
    gpiod_close(GPIOD_DIR_I2C);
}
