    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Attempt to initialize LIS3MDL up to 3 times
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (initialize_lis3mdl()) {
            break;
        } else {
            printf("Failed to initialize LIS3MDL, retrying...\n");
        }
    }

    if (i == MAX_RETRIES) {
        printf("Failed to initialize LIS3MDL after %d attempts.\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        read_magnetic_field();
        write_to_log_file((char *)&(magOffset + (magScale * (uint16_t)(apply_calibration(LIS3MDL_REG_MAG_X)))) 
                         ", " 
                         "(magOffset + (magScale * (uint16_t)(apply_calibration(LIS3MDL_REG_MAG_Y))))," 
                         "(magOffset + (magScale * (uint16_t)(apply_calibration(LIS3MDL_REG_MAG_Z))))\n");
    }

    // Clean up on exit
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Signal handler for SIGINT and SIGTERM
void handle_interrupts(int signum) {
    // Close log file and I2C file descriptor
    close(log_fd);
    close(gpiod_i2c_open(LIS3MDL_I2C_ADDR));
    // Graceful exit
    exit(0);
}

// Reads a single magnetic field sample
void read_magnetic_field(void) {
    uint16_t raw_x, raw_y, raw_z;

    // Read raw values from LIS3MDL
    if (gpiod_i2c_read(gpiod_i2c_open(LIS3MDL_I2C_ADDR), LIS3MDL_REG_MAG_X, 2, &raw_x, NULL) < 0) {
        printf("Error reading MAG_X: %s\n", strerror(errno));
        return;
    }
    if (gpiod_i2c_read(gpiod_i2c_open(LIS3MDL_I2C_ADDR), LIS3MDL_REG_MAG_Y, 2, &raw_y, NULL) < 0) {
        printf("Error reading MAG_Y: %s\n", strerror(errno));
        return;
    }
    if (gpiod_i2c_read(gpiod_i2c_open(LIS3MDL_I2C_ADDR), LIS3MDL_REG_MAG_Z, 2, &raw_z, NULL) < 0) {
        printf("Error reading MAG_Z: %s\n", strerror(errno));
        return;
    }

    // Apply calibration
    apply_calibration(raw_x);
    apply_calibration(raw_y);
    apply_calibration(raw_z);

    // Check for metal detector alert
    float total_magnitude = sqrt((float)(raw_x + raw_y + raw_z));
    if (total_magnitude > 800.0) {
        fprintf(stderr, "Metal detector alert!\n");
    }
}

// Applies the calibration constants to a raw value
void apply_calibration(uint16_t raw_value) {
    uint16_t calibrated_value = (raw_value - magOffset) / magScale;
    return calibrated_value;
}

