void write_to_log_file(const char *data) {
    if (log_fd == -1) {
        log_fd = open("magnetic_log.txt", O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
        if (log_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    if (write(log_fd, data, strlen(data)) != strlen(data)) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
}

// Initializes the LIS3MDL sensor
void initialize_lis3mdl(void) {
    // Open I2C device
    if (gpiod_i2c_open(LIS3MDL_I2C_ADDR) < 0) {
        perror("Failed to open I2C device");
        return;
    }

    // Write calibration constants
    if (gpiod_i2c_write(gpiod_i2c_open(LIS3MDL_I2C_ADDR), MAG_OFFSET, 2) < 0) {
        perror("Failed to write MAG_OFFSET");
        return;
    }
    if (gpiod_i2c_write(gpiod_i2c_open(LIS3MDL_I2C_ADDR), MAG_SCALE, 2) < 0) {
        perror("Failed to write MAG_SCALE");
        return;
    }
    if (gpiod_i2c_write(gpiod_i2c_open(LIS3MDL_I2C_ADDR), MAG_SENSITIVITY, 1) < 0) {
        perror("Failed to write MAG_SENSITIVITY");
        return;
    }

    // Check if initialization was successful
    if (gpiod_i2c_read(gpiod_i2c_open(LIS3MDL_I2C_ADDR), LIS3MDL_REG_ID, 1, NULL) != 0x68) {
        printf("LIS3MDL initialization failed.\n");
        return;
    }
}

// Cleans up resources on exit
void cleanup_resources(void) {
    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    // Close I2C device
    gpiod_i2c_close(gpiod_i2c_open(LIS3MDL_I2C_ADDR));
}

