#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO8 27
#define ADXL354B_RESET_REG 0x00
#define ADXL354B_RUN_BIT 0x01
#define ADXL354B_STABLE_BIT 0x02
#define ADXL354B_PARTID_REG 0x00
#define ADXL354B_X_REG 0x01
#define ADXL354B_Y_REG 0x02
#define ADXL354B_Z_REG 0x03

#define SPI_SPEED_MHZ 1000000
#define SPI_MODE 0
#define SPI_BIT_ORDER MSB_FIRST
#define SPI_READ_BIT 0x80
#define SPI_MULTI_BYTE 0x40

void setup_spi(const char *dev_path, uint32_t speed_mhz) {
    struct spi_device *spi;
    int ret;

    spi = gpiod_spi_open(dev_path, SPI_SPEED_MHZ, SPI_MODE, SPI_BIT_ORDER);
    if (spi == NULL) {
        fprintf(stderr, "Failed to open SPI device: %s\n", dev_path);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_spi_set_mode(spi, SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %d\n", ret);
        gpiod_spi_close(spi);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_spi_set_speed(spi, speed_mhz);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %d\n", ret);
        gpiod_spi_close(spi);
        exit(EXIT_FAILURE);
    }

    gpiod_spi_set_bit_order(spi, SPI_BIT_ORDER);
    gpiod_spi_set_chip_select(spi, GPIO8);
}

void reset_accelerometer(struct spi_device *spi) {
    uint8_t reset_value = 0x01;
    uint8_t power_control_value = 0;

    gpiod_spi_write(spi, ADXL354B_RESET_REG, reset_value);
    usleep(1000);

    power_control_value = gpiod_spi_read(spi, ADXL354B_POWER_CONTROL_REG);
    power_control_value &= ~ADXL354B_RUN_BIT;
    gpiod_spi_write(spi, ADXL354B_POWER_CONTROL_REG, power_control_value);

    while (!gpiod_spi_read(spi, &ADXL354B_STABLE_BIT, 1)) {
        // Wait for STABLE bit to be set
        usleep(100);
    }

    gpiod_spi_write(spi, ADXL354B_POWER_CONTROL_REG, power_control_value | ADXL354B_RUN_BIT);
}

void read_part_id(struct spi_device *spi) {
    uint8_t part_id;

    gpiod_spi_write(spi, ADXL354B_PARTID_REG, 0);
    part_id = gpiod_spi_read(spi, ADXL354B_PARTID_REG, 1);

    if (part_id != 0x55) {
        fprintf(stderr, "Invalid PARTID received: 0x%X\n", part_id);
        exit(EXIT_FAILURE);
    }
}

void read_accelerations(struct spi_device *spi) {
    uint8_t x_data[3], y_data[3], z_data[3];

    gpiod_spi_write(spi, ADXL354B_X_REG, 0x00); // Start X-axis read
    for (int i = 0; i < 3; ++i) {
        x_data[i] = gpiod_spi_read(spi, ADXL354B_X_REG, 1);
    }

    gpiod_spi_write(spi, ADXL354B_Y_REG, 0x00); // Start Y-axis read
    for (int i = 0; i < 3; ++i) {
        y_data[i] = gpiod_spi_read(spi, ADXL354B_Y_REG, 1);
    }

    gpiod_spi_write(spi, ADXL354B_Z_REG, 0x00); // Start Z-axis read
    for (int i = 0; i < 3; ++i) {
        z_data[i] = gpiod_spi_read(spi, ADXL354B_Z_REG, 1);
    }
}

void log_accelerations(const uint8_t *x_data, const uint8_t *y_data, const uint8_t *z_data) {
    char timestamp[50];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen("vibration_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing: vibration_log.txt\n");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp: %s, X: %02X %02X %02X, Y: %02X %02X %02X, Z: %02X %02X %02X\n",
            timestamp, x_data[0], x_data[1], x_data[2], y_data[0], y_data[1], y_data[2], z_data[0], z_data[1], z_data[2]);
    fclose(log_file);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down gracefully...\n");
        close(spi);
        fclose(log_file);
        gpiod_spi_close(spi);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct spi_device *spi;
    FILE *log_file;
    char timestamp[50];
    uint8_t x_data[3], y_data[3], z_data[3];
    int ret;

    setup_spi(SPI_DEVICE, SPI_SPEED_MHZ);

    log_file = fopen("vibration_log.txt", "w+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: vibration_log.txt\n");
        return EXIT_FAILURE;
    }

    reset_accelerometer(spi);

    read_part_id(spi);

    while (1) {
        read_accelerations(spi);
        log_accelerations(x_data, y_data, z_data);
        usleep(100000); // 100 ms interval
    }

    return 0;
}

