#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <gpiod.h>
#include <libgpiod/spi.h>

#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define ADIS16362_ADDR 0x1E

#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025

#define TIMESTAMP_FORMAT "%f"

// Function prototypes
void handle_signal(int signum);
void read_imu_data(uint16_t *gyro_data, uint16_t *accel_data);
void write_to_csv(const char *line);
void cleanup();

int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handle_signal);

    // Initialize gpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errstr());
        return EXIT_FAILURE;
    }

    // Open GPIO CE0 pin
    int gpio_ce0;
    if ((gpio_ce0 = gpiod_get_data(GPIO_CE0, GPIOD_OUT_INIT_LOW)) < 0) {
        fprintf(stderr, "Failed to get GPIO %u: %s\n", GPIO_CE0, gpiod_errstr());
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Open SPI device
    int spi_fd;
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_put_data(gpio_ce0, GPIOD_OUT_HIGH);
        gpiod_put_data(gpio_ce0, GPIOD_OUT_LOW);
        close(gpio_ce0);
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    struct spi_ioc_transfer spi_transfer[] = {
        // ADIS16362 initialization sequence
        {
            .tx_buf = (unsigned long)&ADIS16362_ADDR,
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .mode = SPI_MODE_3,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
        // Send dummy byte
        {
            .tx_buf = (unsigned long)0x00,
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 0,
            .speed_hz = 1000000,
            .mode = SPI_MODE_3,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
    };

    // Write initialization sequence to SPI
    int transfers_sent = 0;
    while (transfers_sent < 2) {
        int ret = spi_write(spi_fd, spi_transfer, 2, 2000);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to SPI: %s\n", strerror(errno));
            close(spi_fd);
            gpiod_put_data(gpio_ce0, GPIOD_OUT_HIGH);
            gpiod_put_data(gpio_ce0, GPIOD_OUT_LOW);
            close(gpio_ce0);
            gpiod_cleanup();
            return EXIT_FAILURE;
        }
        transfers_sent++;
    }

    // Main loop
    while (1) {
        // Read IMU data
        uint16_t gyro_data[2];
        uint16_t accel_data[2];
        read_imu_data(gyro_data, accel_data);

        // Convert raw data to scaled values
        float gyro_x = (float)gyro_data[0] * GYRO_SCALE;
        float gyro_y = (float)gyro_data[1] * GYRO_SCALE;
        float gyro_z = (float)gyro_data[2] * GYRO_SCALE;

        float accel_x = (float)accel_data[0] * ACCEL_SCALE;
        float accel_y = (float)accel_data[1] * ACCEL_SCALE;
        float accel_z = (float)accel_data[2] * ACCEL_SCALE;

        // Format timestamp and data
        char line[256];
        sprintf(line, "%f,%f,%f,%f,%f,%f", 
                (double)time(NULL) * 1e-9, // Convert to seconds.nanoseconds
                gyro_x, gyro_y, gyro_z,
                accel_x, accel_y, accel_z);

        // Write to CSV file
        write_to_csv(line);

        // Insert delay
        usleep(10000); // 10 ms delay
    }

    // Handle SIGINT
    handle_signal(SIGINT);

    // Clean up
    cleanup();

    return EXIT_SUCCESS;
}

// Function to read IMU data
void read_imu_data(uint16_t *gyro_data, uint16_t *accel_data) {
    // SPI transfer setup for reading data
    struct spi_ioc_transfer read_transfer[] = {
        {
            .tx_buf = NULL,
            .rx_buf = gyro_data,
            .len = 2,
            .speed_hz = 1000000,
            .mode = SPI_MODE_3,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
        {
            .tx_buf = NULL,
            .rx_buf = accel_data,
            .len = 2,
            .speed_hz = 1000000,
            .mode = SPI_MODE_3,
            .cs_change = 1,
            .cs_low_for_trans = 1,
        },
    };

    // Perform SPI read
    int ret = spi_read(spi_fd, read_transfer, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read IMU data: %s\n", strerror(errno));
        return;
    }
}

// Function to write to CSV file
void write_to_csv(const char *line) {
    FILE *csv_file = fopen("imu_log.csv", "a+");
    if (!csv_file) {
        fprintf(stderr, "Failed to open or append to CSV file: %s\n", strerror(errno));
        return;
    }

    fprintf(csv_file, "%s\n", line);
    fclose(csv_file);
}

// Cleanup function
void cleanup() {
    // Close SPI device
    close(spi_fd);

    // Close CSV file
    fclose(csv_file);

    // Close GPIO pin
    gpiod_put_data(gpio_ce0, GPIOD_OUT_LOW);

    // Clean up gpiod
    gpiod_cleanup();
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Graceful shutdown
    printf("SIGINT received, shutting down gracefully...\n");
    cleanup();
    exit(EXIT_FAILURE);
}

