#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CLOCK_FREQ_HZ 1000000
#define SPI_MODE_3 3
#define ADIS16266_ADDRESS 0x1A
#define SCALE_FACTOR 0.02

volatile sig_atomic_t should_exit = 0;

void setup_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer xfers[] = {
        // Transfer 1: Set MSB and read 2 bytes
        {
            .tx_buf = &ADIS16266_ADDRESS,
            .tx_len = 1,
            .rx_buf = (void *)(&read_data[0]),
            .rx_len = 2,
            .cs_change = 1,
            .speed_hz = SPI_CLOCK_FREQ_HZ,
            .mode = SPI_MODE_3,
            .delay_usecs = 0
        },
        // Transfer 2: No transfer (dummy, to keep the bus busy)
        {
            .tx_buf = NULL,
            .tx_len = 0,
            .rx_buf = NULL,
            .rx_len = 0,
            .cs_change = 0,
            .speed_hz = SPI_CLOCK_FREQ_HZ,
            .mode = SPI_MODE_3,
            .delay_usecs = 0
        }
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(sizeof(xfers)/sizeof(xfers[0])), xfers) < 0) {
        perror("SPI transfer failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyroscope_data(uint16_t *read_data) {
    setup_spi();

    // Send address with MSB set and read data
    if (spi_write_then_read(spi_fd, &ADIS16266_ADDRESS, 1, read_data, 2) < 0) {
        perror("SPI write/read failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Apply scale factor to convert LSB to degrees/second
    double x_rate = (read_data[0] * SCALE_FACTOR) - (read_data[1] * SCALE_FACTOR);
    double y_rate = (read_data[0] * SCALE_FACTOR) + (read_data[1] * SCALE_FACTOR);
    double z_rate = (read_data[1] * SCALE_FACTOR);

    printf("X rate: %.6f deg/sec, Y rate: %.6f deg/sec, Z rate: %.6f deg/sec\n",
           x_rate, y_rate, z_rate);

    // Clean up and exit on SIGINT
    if (should_exit) {
        close(spi_fd);
        exit(EXIT_SUCCESS);
    }
}

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    struct sigaction sa;
    sigemptyset(&sa.sa_mask);
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        exit(EXIT_FAILURE);
    }

    uint16_t read_data[2];
    while (!should_exit) {
        read_gyroscope_data(read_data);
        usleep(100000); // Sleep for 100 ms
    }

    // Clean up on normal exit
    close(spi_fd);
    return 0;
}

