#include <stdint.h>

#define I2C_ADDR 0x1D  // Address of the LSM6DSR IMU
#define LSM6DSR_REG_ACCEL_XOUT_H 0x28
#define LSM6DSR_REG_ACCEL_XOUT_L 0x29
#define LSM6DSR_REG_ACCEL_YOUT_H 0x2A
#define LSM6DSR_REG_ACCEL_YOUT_L 0x2B
#define LSM6DSR_REG_ACCEL_ZOUT_H 0x2C
#define LSM6DSR_REG_ACCEL_ZOUT_L 0x2D
#define LSM6DSR_REG_GYRO_XOUT_H 0x3B
#define LSM6DSR_REG_GYRO_XOUT_L 0x3C
#define LSM6DSR_REG_GYRO_YOUT_H 0x3D
#define LSM6DSR_REG_GYRO_YOUT_L 0x3E
#define LSM6DSR_REG_GYRO_ZOUT_H 0x3F
#define LSM6DSR_REG_GYRO_ZOUT_L 0x40

void handle_signal(int signum) {
    // Clean shutdown on SIGINT
    printf("Interrupt received, shutting down...\n");
    libgpiod_i2c_stop(gpiod_i2c_get_by_label("i2c-1"));
    libgpiod_i2c_exit();
    exit(0);
}

int main() {
    // Initialize signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Attempt to initialize libgpiod I2C
    struct gpiod_i2c *i2c_dev;
    int ret = libgpiod_i2c_open("i2c-1", GPIOD_I2C_SLAVE, &i2c_dev);
    if (ret != 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", libgpiod_error_string(ret));
        return EXIT_FAILURE;
    }

    // Attempt to open the I2C device
    ret = libgpiod_i2c_transfer(i2c_dev, I2C_ADDR, 0x0D,  // Start + WHO_AM_I command
                                 0, 1,                  // No data to send
                                 NULL, 0,                // No data to receive
                                 2000);                  // Timeout
    if (ret != 1) {
        fprintf(stderr, "Failed to communicate with device: %s\n", libgpiod_error_string(ret));
        libgpiod_i2c_close(i2c_dev);
        return EXIT_FAILURE;
    }

    // Check if WHO_AM_I register value matches expected (0x6A)
    uint16_t who_am_i = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_WHO_AM_I, 0, 2, NULL);
    if (who_am_i != 0x6A) {
        fprintf(stderr, "WHO_AM_I register mismatch: 0x%X\n", who_am_i);
        libgpiod_i2c_close(i2c_dev);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read accelerometer X, Y, Z
        uint16_t accel_xh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_XOUT_H, 0, 2, NULL);
        uint16_t accel_xl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_XOUT_L, 0, 2, NULL);
        uint16_t accel_yh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_YOUT_H, 0, 2, NULL);
        uint16_t accel_yl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_YOUT_L, 0, 2, NULL);
        uint16_t accel_zh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_ZOUT_H, 0, 2, NULL);
        uint16_t accel_zl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_ACCEL_ZOUT_L, 0, 2, NULL);

        // Read gyroscope X, Y, Z
        uint16_t gyro_xh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_XOUT_H, 0, 2, NULL);
        uint16_t gyro_xl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_XOUT_L, 0, 2, NULL);
        uint16_t gyro_yh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_YOUT_H, 0, 2, NULL);
        uint16_t gyro_yl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_YOUT_L, 0, 2, NULL);
        uint16_t gyro_zh = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_ZOUT_H, 0, 2, NULL);
        uint16_t gyro_zl = libgpiod_i2c_read(i2c_dev, I2C_ADDR, LSM6DSR_REG_GYRO_ZOUT_L, 0, 2, NULL);

        // Print values
        printf("Accelerometer: X=%hu Xl=%hu Y=%hu Yl=%hu Z=%hu Zl=%hu\n",
               accel_xh, accel_xl, accel_yh, accel_yl, accel_zh, accel_zl);
        printf("Gyroscope: X=%hu Xl=%hu Y=%hu Yl=%hu Z=%hu Zl=%hu\n",
               gyro_xh, gyro_xl, gyro_yh, gyro_yl, gyro_zh, gyro_zl);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean shutdown on SIGINT
    printf("Interrupt received, shutting down...\n");

    // Close I2C handle and exit
    libgpiod_i2c_close(i2c_dev);
    libgpiod_i2c_exit();
    return EXIT_SUCCESS;
