void setup_gpios() {
    // Set GPIO2 (SDA) and GPIO3 (SCL) as ALT0 (General Purpose Input/Output)
    gpiod_set_function(GPIOD_PIN_2, GPIOD_FUNCTION_ALT0);
    gpiod_set_function(GPIOD_PIN_3, GPIOD_FUNCTION_ALT0);

    // Set GPIO2 (SDA) as output
    gpiod_direction_output(GPIOD_PIN_2, 1);

    // Set GPIO3 (SCL) as output
    gpiod_direction_output(GPIOD_PIN_3, 1);
}

