    uint8_t data[12]; // 12-byte buffer for accelerometer and magnetometer data

    // Read 6 bytes of accelerometer data (14-bit left-aligned)
    if (gpiod_i2c_read(i2c_bus, 0x0D, data, 6) < 0) {
        perror("Failed to read accelerometer data");
        return;
    }

