    SensorData acc_data;
    acc_data.x = (data[0] << 8) | data[1];
    acc_data.y = (data[2] << 8) | data[3];
    acc_data.z = (data[4] << 8) | data[5];

    // Read 6 bytes of magnetometer data (16-bit)
    if (gpiod_i2c_read(i2c_bus, 0x0D, data + 6, 6) < 0) {
        perror("Failed to read magnetometer data");
        return;
    }

    // Extract X, Y, Z values from magnetometer data
    acc_data.x = data[6];
    acc_data.y = data[7];
    acc_data.z = data[8];

