#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_ADDR 0x53  // ADXL345 default address
#define THRESHOLD_DEGREES 30.0
#define SAMPLE_RATE_MS 100

// Structure for ADXL345 register access
typedef struct {
    uint8_t WHO_AM_I;
    uint8_t DATA_FORMAT;
    uint8_t RANGE;
    uint8_t POWER_CTL;
    uint8_t CONFIG;
    uint8_t DATA_X_L;
    uint8_t DATA_X_H;
    uint8_t DATA_Y_L;
    uint8_t DATA_Y_H;
    uint8_t DATA_Z_L;
    uint8_t DATA_Z_H;
} ADXL345_Registers;

// Function prototypes
void adxl345_init(void);
void read_acceleration_data(uint8_t *data);
void calculate_tilt(float *acceleration_data);
void write_tilt_event_to_log(const char *timestamp);
void cleanup_resources(void);

int main(void) {
    // Initialize ADXL345
    adxl345_init();

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        read_acceleration_data(data);

        // Calculate tilt
        float acceleration[3];
        for (int i = 0; i < 3; i++) {
            acceleration[i] = data[i * 2 + 0] * (1 << 8) + data[i * 2 + 1];
        }
        calculate_tilt(acceleration);

        // Check tilt threshold
        if (abs(atan2(acceleration[1], acceleration[0])) > M_PI * THRESHOLD_DEGREES / 180.0) {
            // Write tilt event to log
            const char *timestamp_str = ctime(&time(NULL));
            write_tilt_event_to_log(timestamp_str);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_RATE_MS * 1000);
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to initialize ADXL345
void adxl345_init() {
    int fd;
    struct i2c_dev *i2c_dev;
    char device_name[32];

    // Open I2C device
    snprintf(device_name, sizeof(device_name), "/dev/i2c-%d", I2C_ADDR);
    fd = open(device_name, O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Create I2C device structure
    i2c_dev = i2c_dev_open(fd, I2C_ADDR);
    if (!i2c_dev) {
        perror("Failed to open I2C device");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Write to ADXL345 configuration register
    uint8_t config = 0x18; // 0x18 for +/- 16g range, 400 Hz update rate
    i2c_dev_write(i2c_dev, &config, 1);

    // Close I2C device
    i2c_dev_close(i2c_dev);
    close(fd);
}

// Function to read acceleration data from ADXL345
void read_acceleration_data(uint8_t *data) {
    uint8_t command = 0x32; // Read acceleration data command

    // Write command to ADXL345
    i2c_dev_write(i2c_dev, &command, 1);

    // Read data
    i2c_dev_read(i2c_dev, data, 6);

    // Close I2C device (not strictly necessary here but good practice)
    i2c_dev_close(i2c_dev);
}

// Function to calculate tilt from acceleration data
void calculate_tilt(float *acceleration) {
    float x_accel = acceleration[0];
    float y_accel = acceleration[1];
    float z_accel = acceleration[2];

    // Calculate tilt angle using atan2 for correct quadrant determination
    float tilt_angle = atan2(-y_accel, x_accel);
    tilt_angle = abs(tilt_angle * (180.0 / M_PI)); // Convert to degrees
}

// Function to write a tilt event to the log file
void write_tilt_event_to_log(const char *timestamp) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: Tilt exceeded threshold (%.1f degrees)\n", timestamp, THRESHOLD_DEGREES);

    // Open log file for appending
    int log_fd = open("/var/log/tilt_events.log", O_APPEND | O_WRONLY, 0666);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return;
    }

    // Write log entry
    ssize_t written = write(log_fd, log_entry, strlen(log_entry));
    if (written != strlen(log_entry)) {
        perror("Failed to write to log file");
        close(log_fd);
        return;
    }

    // Close log file
    close(log_fd);
}

// Function to cleanup resources
void cleanup_resources(void) {
    // Close any open file descriptors
    for (int fd = 0; fd < 10; fd++) {
        if (fd != STDIN_FILENO && fd != STDOUT_FILENO && fd != STDERR_FILENO) {
            close(fd);
        }
    }

    // Release I2C device if opened
    i2c_dev_close(NULL);
}

// Error handling for I2C operations
// This is implied in the functions like i2c_dev_write and i2c_dev_read
// which return negative on error and set errno accordingly.

