#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_NUM 17 // BCM 17, physical pin 11
#define THRESHOLD_ARG_NAME "threshold"
#define THRESHOLD_DEFAULT 5

int main(int argc, char **argv) {
    // Check if the argument is provided and is a positive integer
    if (argc < 2 || !(isdigit((unsigned char)*argv[1])) || argv[1][0] != '+' || atoi(argv[1]) <= 0) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold = atoi(argv[1]);
    if (gpiod_check_version(GPIOD_VERSION_1_0) < 0) {
        fprintf(stderr, "Error: gpiod version 1.0 or later required.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    int ret = gpiod_direction_output(GPIOD_NUM, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output.\n", GPIO_NUM);
        return EXIT_FAILURE;
    }

    // Signal handlers
    struct sigaction sigint_action, sigterm_action;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sigint_action, NULL);
    sigemptyset(&sigterm_action.sa_mask);
    sigterm_action.sa_handler = SIG_IGN;
    sigaction(SIGTERM, &sigterm_action, NULL);

    while (1) {
        // Start timestamping
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Monitor GPIO for 5 seconds
        int high_count = 0;
        for (int i = 0; i < 5000000 / 1000; i++) {
            int state = gpiod_get_value_input_raw(GPIO_NUM);
            if (state) {
                high_count++;
            }
