#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/wait.h>

#define BH1750_ADDR 0x23  // Default address for BH1750FVI with ADDR tied to GND

#define I2C_DEVICE_PATH "/dev/i2c-1"
#define FILE_NAME "light_log.txt"

// Function prototypes
void handle_error(const char *operation, int error);
void open_i2c_device();
void write_to_sensor(uint8_t command, uint8_t address);
void read_from_sensor(uint8_t command, uint8_t address, uint16_t *lux_value);
void close_i2c_device();
void write_log(const char *timestamp, double lux_value);

int main() {
    // Initialize variables
    int i2c_fd = -1;
    uint16_t lux_value = 0;
    char buffer[256];
    time_t timestamp;
    struct tm *time_info;
    FILE *file = fopen(FILE_NAME, "a+");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);

    while (1) {
        // Get current time
        time(&timestamp);
        time_info = localtime(&timestamp);

        // Format timestamp
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);

        // Write to log file
        write_log(buffer, 0.0);

        // Read lux value from sensor
        if (read_from_sensor(BH1750_READ_LUX, BH1750_ADDR, &lux_value) == 0) {
            // Handle I2C read error
            handle_error("Read from sensor", -1);
        } else {
            // Write lux value to log file
            write_log(buffer, lux_value);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close resources on exit
    close_i2c_device();
    fclose(file);

    return 0;
}

// Function to handle errors
void handle_error(const char *operation, int error) {
    fprintf(stderr, "Error during %s: %s\n", operation, strerror(error));
    exit(EXIT_FAILURE);
}

// Function to open I2C device
void open_i2c_device() {
    i2c_fd = open(I2C_DEVICE_PATH, O_RDWR);
    if (i2c_fd == -1) {
        handle_error("Open I2C device", errno);
    }
    // Check if device is present
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) == -1) {
        handle_error("Access BH1750 device", -1);
    }
}

// Function to write command to the sensor
void write_to_sensor(uint8_t command, uint8_t address) {
    if (ioctl(i2c_fd, I2C_SLAVE, address) == -1) {
        handle_error("Write to sensor", -1);
    }
    if (write(i2c_fd, &command, 1) != 1) {
        handle_error("Write to sensor", -1);
    }
}

// Function to read data from the sensor
void read_from_sensor(uint8_t command, uint8_t address, uint16_t *lux_value) {
    if (ioctl(i2c_fd, I2C_SLAVE, address) == -1) {
        handle_error("Read from sensor", -1);
    }
    if (read(i2c_fd, lux_value, 2) != 2) {
        handle_error("Read from sensor", -1);
    }
}

// Function to close I2C device
void close_i2c_device() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Function to write log entry
void write_log(const char *timestamp, double lux_value) {
    fprintf(file, "%s, Lux: %.2f\n", timestamp, lux_value);
}

