#define TONE_DURATION 5000

// GPIO context for PWM pin
gpiod_context *pwm_context;

// MPR121 context
libmp121_context *mpr121_ctx;

// File descriptor for frequency log
int frequency_log_fd;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Stop PWM, close resources
    gpiod_stop(pwm_context);
    close(frequency_log_fd);
    libmp121_close(mpr121_ctx);
    gpiod_remove(pwm_context);
    // Clean up
    free(pwm_context);
    free(mpr121_ctx);
    exit(0);
}

// Function to initialize GPIO and MPR121
int init_resources() {
    // Initialize GPIO
    pwm_context = gpiod_get_context(PWM_PIN);
    if (!pwm_context) {
        perror("Failed to get GPIO context");
        return -1;
    }

    // Initialize MPR121
    mpr121_ctx = libmp121_init(I2C_BUS_NUM);
    if (!mpr121_ctx) {
        perror("Failed to initialize MPR121");
        return -1;
    }

    // Configure MPR121 electrodes
    if (libmp121_config_electrodes(mpr121_ctx, 8) < 0) {
        perror("Failed to configure MPR121 electrodes");
        libmp121_close(mpr121_ctx);
        return -1;
    }

    // Soft reset MPR121
    if (libmp121_soft_reset(mpr121_ctx) < 0) {
        perror("Failed to soft reset MPR121");
        libmp121_close(mpr121_ctx);
        return -1;
    }

    // Open frequency log file
    frequency_log_fd = open("frequency_log.txt", O_WRONLY | O_CREAT, 0644);
    if (frequency_log_fd == -1) {
        perror("Failed to open frequency log file");
        libmp121_close(mpr121_ctx);
        gpiod_remove(pwm_context);
        return -1;
    }

    return 0;
}

// Function to handle TCP command
int handle_tcp_command(const char *command) {
    char buffer[256];
    int client_fd;

    // Create socket
    if ((client_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        return -1;
    }

    // Bind to port 12345
    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    if (bind(client_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind to port");
        close(client_fd);
        return -1;
    }

    // Listen for connections
    if (listen(client_fd, 5) < 0) {
        perror("Failed to listen on port");
        close(client_fd);
        return -1;
    }

    // Accept connection
    struct sockaddr_in client_addr;
    socklen_t addr_len = sizeof(client_addr);
    if ((client_fd = accept(client_fd, (struct sockaddr *)&client_addr, &addr_len)) < 0) {
        perror("Failed to accept connection");
        close(client_fd);
        return -1;
    }

    // Read command from client
    if (read(client_fd, command, sizeof(command)) < 0) {
        perror("Failed to read command");
        close(client_fd);
        return -1;
    }

    // Check if command is authenticated
    if (strncmp(command, "MOTION_DETECTED:", 16) != 0 || strcmp(command + 16, SECRET_KEY) != 0) {
