#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <inttypes.h>
#include <poll.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDR 0x1D  // Address of LSM303DLHC
#define I2C_DEVICE "/dev/i2c-1"  // Assuming Raspberry Pi Zero W uses i2c-1
#define MAG_REG_OFFSET 0x14  // Offset to the first data register for Z-axis
#define NUM_SAMPLES 1000  // Number of samples to take
#define PWM_GPIO 17  // BCM GPIO 17
#define PWM_FREQ 1000  // PWM frequency in Hz

// Function prototypes
void setup_pigpio();
void setup_i2c();
void read_magnetometer(uint8_t *data);
void handle_pwm(uint16_t z_magnitude);
void cleanup();
void handle_signal(int signum);

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_pigpio();
    setup_i2c();

    uint8_t data[6];
    uint16_t z_magnitude = 0;

    for (int i = 0; i < NUM_SAMPLES; ++i) {
        if (poll(&read_fd, 1, 100) > 0) {  // Check if I2C operation is ready
            if (ioctl(I2C_DEVICE, I2C_RDWR, (void *) &i2c_cmd) < 0) {
                fprintf(stderr, "I2C error: %s\n", strerror(errno));
                continue;
            }

            if (i2c_transfer(i2c_fd) != 6) {
                fprintf(stderr, "I2C transfer error\n");
                continue;
            }

            read_magnetometer(data);
            z_magnitude = handle_pwm(z_magnitude);
        }

        usleep(100000);  // Sleep for 100 ms between samples
    }

    cleanup();

    return 0;
}

// Function to initialize pigpio for PWM
void setup_pigpio() {
    if (pigpio_init() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    gpio_mode(PWM_GPIO, GPIO_ALT0);  // Set GPIO17 to alternate function
    pigpio_write(PWM_GPIO, 1);  // Enable PWM on GPIO17
    pigpio_set_PWM(PWM_GPIO, PWM_FREQ, 1023);  // Set PWM frequency and duty cycle
}

// Function to initialize I2C
void setup_i2c() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct i2c_msg i2c_cmd = {
        .addr = I2C_ADDR,
        .flags = 0,
        .len = 6,
        .buf = data,
        .buf_len = 6,
    };

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C slave: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read magnetometer data
void read_magnetometer(uint8_t *data) {
    uint16_t z_magnitude_word = (data[MAG_REG_OFFSET] << 8) | data[MAG_REG_OFFSET + 1];

    z_magnitude = (z_magnitude_word >> 8);  // Extract Z-axis magnitude
}

// Function to handle PWM based on Z-axis magnitude
void handle_pwm(uint16_t z_magnitude) {
    int duty_cycle = (z_magnitude / 1023) * 1023;  // Map magnitude to duty cycle
    pigpio_write(PWM_GPIO, duty_cycle);
}

// Function to clean up resources
void cleanup() {
    pigpio_stop(PWM_GPIO);  // Stop PWM
    pigpio_close();  // Close pigpio connection
    close(i2c_fd);  // Close I2C file descriptor
    unlink("magnetometer_log.txt");  // Clean up log file (if created)
}

// Signal handler to clean up on SIGINT or SIGTERM
void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

