#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/wait.h>

#define HMC5883L_I2C_ADDR 0x1E  // Address of HMC5883L

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} HMC5883L_Data;

// Function prototypes
void setup_hmc5883l(void);
void read_magnetometer(HMC5883L_Data *data);
void apply_hard_iron_offsets(HMC5883L_Data *data);
void print_magnetometer_data(const HMC5883L_Data *data);
void handle_signal(int signum);

int main() {
    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO and I2C
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpiod_i2c_new_device(HMC5883L_I2C_ADDR) < 0) {
        fprintf(stderr, "Error creating I2C device: %s\n", strerror(errno));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Setup HMC5883L
    setup_hmc5883l();

    // Main loop
    while (1) {
        // Read magnetometer data
        HMC5883L_Data data;
        read_magnetometer(&data);

        // Apply hard iron offsets
        apply_hard_iron_offsets(&data);

        // Print corrected data every 500ms
        if ((pid_t) getpid() == 1) {
            print_magnetometer_data(&data);
            usleep(500 * 1000); // 500ms delay
        }

        // Check for signals and exit gracefully
        if (wait(NULL) > 0 && WIFSIGNALED((siginfo_t *) &(*(waitstatus_t *) &WEXITSTATUS(waitpid(-1, &w, 0))))) {
            handle_signal(SIGHUP); // Handle signal here
            break;
        }
    }

    // Clean up
    gpiod_i2c_device_remove(gpiod_i2c_device_get_by_index(0));
    gpiod_exit();

    return EXIT_SUCCESS;
}

// Function to initialize HMC5883L
void setup_hmc5883l() {
    gpiod_i2c_write(gpiod_i2c_device_get_by_index(0), (uint8_t *) &HMC5883L_I2C_ADDR, 1);
    gpiod_i2c_write(gpiod_i2c_device_get_by_index(0), (uint8_t *) &0x02, 1); // Set control register to continuous conversion mode
}

// Function to read magnetometer data
void read_magnetometer(HMC5883L_Data *data) {
    uint8_t buffer[6];
    ssize_t bytes_read;

    // Write to register 0x03 to start conversion
    gpiod_i2c_write(gpiod_i2c_device_get_by_index(0), (uint8_t *) &0x03, 1);

    // Wait for conversion to complete
    while (1) {
        bytes_read = gpiod_i2c_read(gpiod_i2c_device_get_by_index(0), buffer, 6);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from HMC5883L: %s\n", strerror(errno));
            break;
        }
        if (bytes_read == 6) {
            break;
        }
    }

    // Read data from registers 0x03 to 0x06
    data->x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->y = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->z = (int16_t)(buffer[4] << 8 | buffer[5]);
}

// Function to apply hard iron offsets
void apply_hard_iron_offsets(HMC5883L_Data *data) {
    static int16_t hard_iron_offsets[3] = {0, 0, 0}; // Initialize with zero offsets

    data->x -= hard_iron_offsets[0];
    data->y -= hard_iron_offsets[1];
    data->z -= hard_iron_offsets[2];
}

// Function to print magnetometer data
void print_magnetometer_data(const HMC5883L_Data *data) {
    printf("X: %d, Y: %d, Z: %d\n", data->x, data->y, data->z);
}

// Signal handler to clean up and exit
void handle_signal(int signum) {
    // Clean up resources
    gpiod_i2c_device_remove(gpiod_i2c_device_get_by_index(0));
    gpiod_exit();

    // Exit the program
    exit(EXIT_FAILURE);
}

