#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <stdint.h>

#define BUFFER_SIZE 64
#define LSB_SENSITIVITY 0.061
#define THRESHOLD_MG 2000
#define CONTROL_REGISTER_WRITE_VALUE 0x00

// Device address and register offsets
#define LSM303D_ADDRESS 0x1D
#define DEVICE_ID_REGISTER 0x0B
#define ACC_X_REG 0x28
#define ACC_Y_REG 0x29
#define ACC_Z_REG 0x2A
#define MAG_X_REG 0x2C
#define MAG_Y_REG 0x2D
#define MAG_Z_REG 0x2E

// Circular buffer structure
typedef struct {
    uint8_t data[BUFFER_SIZE];
    size_t head;
    size_t tail;
} AccelerationBuffer;

// Function prototypes
void setup_lsm303d();
void read_acceleration_data(uint8_t *data);
void handle_interrupt(int signum);
void dump_buffer_to_console();
void cleanup();

int main() {
    // Initialize signal handler for INT1 interrupt
    signal(SIGINT, handle_interrupt);

    // Initialize GPIO for INT1 pin
    gpiod_c_open(&gpiod_device);
    gpiod_set_data_direction(gpiod_device, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_write(gpiod_device, GPIOD_PIN_INT1, 1);

    // Initialize I2C and LSM303D
    if (setup_lsm303d() != 0) {
        fprintf(stderr, "Failed to initialize LSM303D.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[BUFFER_SIZE];
        read_acceleration_data(data);

        // Check for INT1 rising edge
        if (gpiod_get_value_input_raw(gpiod_device, GPIOD_PIN_INT1) == 1) {
            dump_buffer_to_console();
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up on SIGINT
    cleanup();

    return 0;
}

// Function to setup LSM303D
int setup_lsm303d() {
    AccelerationBuffer buffer;
    buffer.head = 0;
    buffer.tail = 0;

    // Open I2C device
    int i2c_fd = gpiod_i2c_open(&gpiod_device, LSM303D_ADDRESS, GPIOD_I2C_MODE_100kHz);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device.\n");
        return -1;
    }

    // Verify device identity register
    uint8_t device_id;
    if (gpiod_i2c_read(i2c_fd, LSM303D_ADDRESS, DEVICE_ID_REGISTER, &device_id, 1) != 1) {
        fprintf(stderr, "Failed to read device identity register.\n");
        gpiod_i2c_close(i2c_fd);
        return -1;
    }

    if (device_id != 0x1D) {
        fprintf(stderr, "Device identity register does not match expected value (0x1D).\n");
        gpiod_i2c_close(i2c_fd);
        return -1;
    }

    // Configure sensitivity and interrupt threshold
    if (gpiod_i2c_write(i2c_fd, LSM303D_ADDRESS, ACC_CTRL_REG, (LSB_SENSITIVITY * THRESHOLD_MG) / 0.061, 1) != 1) {
        fprintf(stderr, "Failed to write to ACC CTRL register.\n");
        gpiod_i2c_close(i2c_fd);
        return -1;
    }

    // Write control register value for disabling the accelerometer
    if (gpiod_i2c_write(i2c_fd, LSM303D_ADDRESS, ACC_CTRL_REG, CONTROL_REGISTER_WRITE_VALUE, 1) != 1) {
        fprintf(stderr, "Failed to write to ACC CTRL register to disable.\n");
        gpiod_i2c_close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read acceleration data
void read_acceleration_data(uint8_t *data) {
    if (gpiod_i2c_read(i2c_fd, LSM303D_ADDRESS, ACC_X_REG, data + buffer.head, 1) != 1) {
        fprintf(stderr, "Failed to read ACC X data.\n");
    }
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;

    if (gpiod_i2c_read(i2c_fd, LSM303D_ADDRESS, ACC_Y_REG, data + buffer.head, 1) != 1) {
        fprintf(stderr, "Failed to read ACC Y data.\n");
    }
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;

    if (gpiod_i2c_read(i2c_fd, LSM303D_ADDRESS, ACC_Z_REG, data + buffer.head, 1) != 1) {
        fprintf(stderr, "Failed to read ACC Z data.\n");
    }
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
}

// Function to handle INT1 interrupt
void handle_interrupt(int signum) {
    // Gracefully exit the program
    printf("Interrupt received, exiting...\n");
    _exit(0);
}

// Function to dump buffer to console
void dump_buffer_to_console() {
    for (size_t i = (buffer.tail - 10) % BUFFER_SIZE; i < buffer.tail; i++) {
        printf("Timestamp: %s, Acceleration: (%.2f, %.2f, %.2f) mg\n",
               ctime(&time(NULL)), 
               (double)(data[i] * LSB_SENSITIVITY) / 1000, 
               (double)(data[i + 1] * LSB_SENSITIVITY) / 1000, 
               (double)(data[i + 2] * LSB_SENSITIVITY) / 1000);
    }
}

// Function to cleanup resources
void cleanup() {
    // Close I2C device
    gpiod_i2c_close(i2c_fd);

    // Close GPIO device
    gpiod_c_close(&gpiod_device);
}

