#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

volatile sig_atomic_t should_exit = 0;

void cleanup_and_exit() {
    gpiod_free_all();
    printf("Exiting cleanly...\n");
    exit(EXIT_SUCCESS);
}

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    // Initialize GPIO library
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        return EXIT_FAILURE;
    }

    // Set GPIO pins LOW before entering the main loop
    if (gpiod_direction_output(GPIOD_BCM, SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", SOLENOID_1_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_1_PIN));
        gpiod_free_all();
        return EXIT_FAILURE;
    }
    if (gpiod_direction_output(GPIOD_BCM, SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", SOLENOID_2_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_2_PIN));
        gpiod_free_all();
        return EXIT_FAILURE;
    }

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_free_all();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Toggle solenoid control between GPIO17 and GPIO27
        if (gpiod_direction_output(GPIOD_BCM, SOLENOID_1_PIN, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", SOLENOID_1_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_1_PIN));
            continue;
        }
        nanosleep(&tv, NULL); // 500ms delay
        if (gpiod_direction_output(GPIOD_BCM, SOLENOID_1_PIN, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", SOLENOID_1_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_1_PIN));
            continue;
        }

        // Now set the other solenoid HIGH
        if (gpiod_direction_output(GPIOD_BCM, SOLENOID_2_PIN, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", SOLENOID_2_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_2_PIN));
            continue;
        }
        nanosleep(&tv, NULL); // 500ms delay
        if (gpiod_direction_output(GPIOD_BCM, SOLENOID_2_PIN, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d LOW: %s\n", SOLENOID_2_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_2_PIN));
            continue;
        }
    }

    // Clean up on SIGINT/SIGTERM
    should_exit = 1;

    // Release both lines by setting them LOW
    if (gpiod_direction_output(GPIOD_BCM, SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW for cleanup: %s\n", SOLENOID_1_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_1_PIN));
    }
    if (gpiod_direction_output(GPIOD_BCM, SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW for cleanup: %s\n", SOLENOID_2_PIN, gpiod_get_name(GPIOD_BCM, SOLENOID_2_PIN));
    }

    // Free all GPIO resources
    gpiod_free_all();

    printf("Exiting due to signal...\n");
    exit(EXIT_SUCCESS);
}

