#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>
#include <fcntl.h>

#define GPIO17 17
#define GPIO27 27

#define SERIAL_PORT0 "/dev/serial0"
#define SERIAL_PORT1 "/dev/serial1"

#define TIMEOUT 5000  // 5 seconds timeout for reads

// Function prototypes
void initialize_libgpiod();
void cleanup_libgpiod();
void handle_signal(int signum);
void check_and_drive_locks(const char *received_code);
void read_from_uart(const char *port, char buffer[7]);

int main() {
    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = handle_signal;
    sigaction(SIGINT, &int_handler, NULL);
    sigaction(SIGTERM, &term_handler, NULL);

    // Initialize libgpiod
    initialize_libgpiod();

    // GPIO setup
    int gpio17_fd = gpio_open(GPIO17, GPIO_OUTPUT_HIGH);
    if (gpio17_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %u\n", GPIO17);
        return EXIT_FAILURE;
    }

    int gpio27_fd = gpio_open(GPIO27, GPIO_OUTPUT_HIGH);
    if (gpio27_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %u\n", GPIO27);
        gpio_close(gpio17_fd);
        return EXIT_FAILURE;
    }

    // UART setup
    int serial0_fd = open(SERIAL_PORT0, O_RDWR | O_NOCTTY);
    if (serial0_fd == -1) {
        fprintf(stderr, "Error: Failed to open %s\n", SERIAL_PORT0);
        gpio_close(gpio17_fd);
        gpio_close(gpio27_fd);
        return EXIT_FAILURE;
    }

    int serial1_fd = open(SERIAL_PORT1, O_RDWR | O_NOCTTY);
    if (serial1_fd == -1) {
        fprintf(stderr, "Error: Failed to open %s\n", SERIAL_PORT1);
        close(serial0_fd);
        gpio_close(gpio17_fd);
        gpio_close(gpio27_fd);
        return EXIT_FAILURE;
    }

    char serial0_buffer[8];
    char serial1_buffer[8];

    // Main loop
    while (1) {
        // Read from UARTs
        read_from_uart(SERIAL_PORT0, serial0_buffer);
        read_from_uart(SERIAL_PORT1, serial1_buffer);

        // Check if both received codes match "123456"
        if (strcmp(serial0_buffer, "123456") == 0 && strcmp(serial1_buffer, "123456") == 0) {
            check_and_drive_locks("123456");
        }

        // Handle timeouts and non-digit characters
        if (timeout_expired(TIMEOUT)) {
            fprintf(stderr, "Timeout on UART read\n");
            break;
        }
    }

    // Clean shutdown
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close resources
    gpio_close(gpio17_fd);
    gpio_close(gpio27_fd);
    close(serial0_fd);
    close(serial1_fd);

    // Cleanup libgpiod
    cleanup_libgpiod();

    return EXIT_SUCCESS;
}

// Utility functions

void read_from_uart(const char *port, char buffer[7]) {
    int fd = open(port, O_RDWR | O_NOCTTY);
    if (fd == -1) {
        fprintf(stderr, "Error: Failed to open %s for reading\n", port);
        return;
    }

    struct termios options;
    tcgetattr(fd, &options);

    // Set baud rate, 8N1
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);

    // Set non-blocking mode
    options.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(fd, TCSANOW, &options);

    // Non-blocking read with timeout
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
    if (bytes_read == -1 && errno == EAGAIN) {
