    // Ensure a clean exit
    exit(EXIT_FAILURE);
}

// Function to handle cleanup and release resources
void cleanup_resources(void) {
    struct gpiod_chip *chip;
    struct gpiod_value *pir_value;
    struct gpiod_value *relay_value;

