    if (gpiod_value_write(relay_value, 1) < 0) {
        syslog(LOG_ERR, "Failed to deactivate relay during cleanup");
        gpiod_chip_close(chip);
        return;
    }

    // Release GPIO lines
    gpiod_chip_close(chip);

    // Close the log
    closelog();

    // Ensure the relay is driven LOW before releasing the line
    relay_value->value = 0; // LOW
    if (gpiod_value_write(relay_value) < 0) {
        syslog(LOG_ERR, "Failed to set relay LOW during cleanup");
    }

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Log the signal received
    syslog(LOG_INFO, "Received signal %d, initiating shutdown", signum);

    // Clean up resources
    cleanup_resources();
}

