#define RELAY_3_GPIO 24
#define RELAY_4_GPIO 25

#define INTERVALS_LENGTH 4
#define INTERVALS {2, 3, 5, 7}

void setup_relay(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_dir_config *direction;
    struct gpiod_value_config *value;

    chip = gpiod_chip_lookup_by_name("bcm2835-gpio");
    if (!chip) {
        fprintf(stderr, "Failed to find BCM2835 GPIO chip.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < INTERVALS_LENGTH; ++i) {
        direction = gpiod_dir_config_new();
        value = gpiod_value_config_new();

        direction->dir = GPIOD_DIR_OUT_INIT_LOW;
        value->value = 1;

        if (gpiod_direction_output(chip, RELAY_1_GPIO + i, direction) < 0) {
            fprintf(stderr, "Error setting GPIO %d to output.\n", RELAY_1_GPIO + i);
            gpiod_value_config_free(value);
            gpiod_dir_config_free(direction);
            continue;
        }

        if (gpiod_write(chip, RELAY_1_GPIO + i, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d.\n", RELAY_1_GPIO + i);
            gpiod_value_config_free(value);
            gpiod_dir_config_free(direction);
            continue;
        }

        gpiod_value_config_free(value);
        gpiod_dir_config_free(direction);
    }
}

void toggle_relay(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_value_config *value;

    chip = gpiod_chip_lookup_by_name("bcm2835-gpio");
    if (!chip) {
        fprintf(stderr, "Failed to find BCM2835 GPIO chip.\n");
        exit(EXIT_FAILURE);
    }

    value = gpiod_value_config_new();
    value->value = !gpiod_read(chip, RELAY_1_GPIO);

    if (gpiod_write(chip, RELAY_1_GPIO, value) < 0) {
        fprintf(stderr, "Error writing to GPIO %d.\n", RELAY_1_GPIO);
        gpiod_value_config_free(value);
        exit(EXIT_FAILURE);
    }

    gpiod_value_config_free(value);
}

void toggle_relay_with_interval(int interval) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    printf("Toggling relay %d with interval %d seconds...\n", interval + 1, interval);

    while (clock_gettime(CLOCK_MONOTONIC, &ts) - ts < interval * 1000) {
        toggle_relay(RELAY_1_GPIO + interval);
        usleep(100000); // Sleep for a bit to avoid excessive CPU usage
    }

    printf("Relay %d toggled.\n", interval + 1);
}

void cleanup_relay(int gpio) {
    struct gpiod_chip *chip;
    struct gpiod_dir_config *direction;
    struct gpiod_value_config *value;

    chip = gpiod_chip_lookup_by_name("bcm2835-gpio");
    if (!chip) {
        fprintf(stderr, "Failed to find BCM2835 GPIO chip.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < INTERVALS_LENGTH; ++i) {
        direction = gpiod_dir_config_new();
        value = gpiod_value_config_new();

        direction->dir = GPIOD_DIR_IN_INIT_LOW;
        value->value = 0;

        if (gpiod_direction_output(chip, RELAY_1_GPIO + i, direction) < 0) {
            fprintf(stderr, "Error setting GPIO %d to input.\n", RELAY_1_GPIO + i);
            gpiod_value_config_free(value);
            gpiod_dir_config_free(direction);
            continue;
        }

        if (gpiod_write(chip, RELAY_1_GPIO + i, value) < 0) {
            fprintf(stderr, "Error writing to GPIO %d.\n", RELAY_1_GPIO + i);
            gpiod_value_config_free(value);
            gpiod_dir_config_free(direction);
            continue;
        }

        gpiod_value_config_free(value);
        gpiod_dir_config_free(direction);
    }
}

int main(int argc, char **argv) {
    signal(SIGINT, SIG_IGN); // Ignore SIGINT
    signal(SIGTERM, cleanup_relay); // Clean up on SIGTERM

    printf("Starting relay control...\n");

    for (int i = 0; i < INTERVALS_LENGTH; ++i) {
        setup_relay(i);
        toggle_relay_with_interval(INTERVALS[i]);
    }

    printf("Exiting...\n");

    return EXIT_SUCCESS;
}

