#define UART_DEV "/dev/serial0"
#define BAUD_RATE 9600
#define GPIO14 14 // BCM
#define GPIO15 15 // BCM

#define COMMAND_LENGTH 9
#define TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_MS 5000

// MH-Z19B command and response structure
typedef struct {
    uint8_t cmd[COMMAND_LENGTH];
    uint8_t response[COMMAND_LENGTH];
} SensorCommandResponse;

// Function prototypes
void initialize_uart_and_gpio();
void send_command(uint8_t* command);
void read_response(uint8_t* response);
void handle_response(uint8_t* response);
void write_to_log_files(const char* message);
void cleanup();

int main() {
    // Initialize global variables
    SensorCommandResponse response;
    char command[COMMAND_LENGTH] = {0};
    uint8_t checksum = 0;
    int fd;
    struct stat st;
    time_t now;
    FILE* log_file = fopen("co2_error.log", "a+");
    FILE* json_log = fopen("co2_log.json", "a+");

    // Initialize GPIO and UART
    initialize_uart_and_gpio();

    while (1) {
        // Prepare command
        strcpy(command, "MH-Z19B\r\n");

        // Send command
        send_command(command);

        // Wait for response
        read_response(response.response);

        // Check response
        handle_response(&response);

        // Sample and log data
        now = time(NULL);
        uint32_t timestamp = (uint32_t)(now * 1000);
        char json_data[] = "{\"timestamp\": \""
            "%"PRIu32", \"ppm\": %u, \"error\": %d}\r\n",
            timestamp, response.response[4], response.response[5] & 0x7F;
        write_to_log_files(json_data);
        fprintf(log_file, "Timestamp: %u, Response: %s\n", timestamp, response.response);

        // Sleep before next reading
        usleep(SAMPLE_INTERVAL_MS * 1000);

        // Check for interrupt signals
        if (signal(SIGINT) == SIG_IGN) {
            signal(SIGINT, SIG_DFL);
        }
        if (signal(SIGTERM) == SIG_IGN) {
            signal(SIGTERM, SIG_DFL);
        }

        // Clean up on SIGINT/SIGTERM
        if (WIFSIGNALED(getpid(), SIGINT)) {
            cleanup();
            exit(0);
        }
        if (WIFSIGNALED(getpid(), SIGTERM)) {
            cleanup();
            exit(0);
        }
    }

    // Clean up resources
    cleanup();

    return 0;
}

// Function to initialize UART and GPIO
void initialize_uart_and_gpio() {
    fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (fd == -1) {
        perror("open UART");
        exit(EXIT_FAILURE);
    }

    struct termios options;
    tcgetattr(fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    tcsetattr(fd, TCSANOW, &options);

    gpio_set_direction(GPIO14, GPIO_OUT);
    gpio_set_direction(GPIO15, GPIO_IN);

    // Ensure TXD and RXD are correctly set
    if (gpio_request(GPIO14, "co2_monitor_tx") == -1) {
        perror("gpio_request for TXD");
        exit(EXIT_FAILURE);
    }
    if (gpio_request(GPIO15, "co2_monitor_rx") == -1) {
        perror("gpio_request for RXD");
        exit(EXIT_FAILURE);
    }
}

// Function to send the command to the sensor
void send_command(uint8_t* command) {
    uint8_t tx_buffer[COMMAND_LENGTH + 1];
    memcpy(tx_buffer, command, COMMAND_LENGTH);
    tx_buffer[COMMAND_LENGTH] = '\r';
    tx_buffer[COMMAND_LENGTH + 1] = '\n';

    if (write(fd, tx_buffer, COMMAND_LENGTH + 2) != COMMAND_LENGTH) {
        perror("UART write failed");
        exit(EXIT_FAILURE);
    }
}

// Function to read the response from the sensor
void read_response(uint8_t* response) {
    uint8_t rx_buffer[COMMAND_LENGTH + 1];
    if (read(fd, rx_buffer, COMMAND_LENGTH + 1) != COMMAND_LENGTH) {
        perror("UART read failed");
        exit(EXIT_FAILURE);
    }

    // Check for valid response length
    if (rx_buffer[COMMAND_LENGTH] != '\n') {
        fprintf(log_file, "Invalid response length, expected 9 bytes\n");
        return;
    }

    // Calculate checksum
    checksum = 0;
    for (int i = 0; i < COMMAND_LENGTH; ++i) {
        checksum += rx_buffer[i];
    }
    checksum &= 0x7F;

    // Compare checksum with received checksum
    if (rx_buffer[COMMAND_LENGTH - 1] != (checksum + 0x80)) {
        fprintf(log_file, "Checksum mismatch, response: %s\n", rx_buffer);
        return;
    }

    // Copy valid response
    memcpy(response.response, rx_buffer, COMMAND_LENGTH);
}

// Function to handle the sensor response
void handle_response(uint8_t* response) {
    // Check if the response is complete and valid
    if (response->response[4] == 0x01 && response->response[5] < 0x80) {
        // No error, process the reading
        // ...
        // Insert logic to process ppm value and write to co2_log.json
    } else {
        // Error, log it
        fprintf(log_file, "Error: Response: %s\n", response->response);
    }
}

// Function to write to log files
void write_to_log_files(const char* message) {
    time_t now = time(NULL);
    struct tm tm_now;
    localtime_r(&now, &tm_now);

    char log_entry[256];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S ", &tm_now);
    strcat(log_entry, message);

    if (flock(log_file, LOCK_EX | LOCK_NB) == 0) {
        fprintf(log_file, "%s\n", log_entry);
        flock(log_file, LOCK_UN);
    } else {
        fprintf(log_file, "Failed to lock file for writing: %s\n", strerror(errno));
    }

    if (flock(json_log, LOCK_EX | LOCK_NB) == 0) {
        fprintf(json_log, "%s\n", log_entry);
        flock(json_log, LOCK_UN);
    } else {
        fprintf(json_log, "Failed to lock file for writing: %s\n", strerror(errno));
    }
}

// Function to clean up resources
void cleanup() {
    // Close UART and release GPIO
    close(fd);
    gpio_free(GPIO14, "co2_monitor_tx");
    gpio_free(GPIO15, "co2_monitor_rx");

    // Close log files
    fclose(log_file);
    fclose(json_log);
}

