#define HMC5883L_ADDR 0x1E  // I2C address of HMC5883L
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define THRESHOLD_DEVIATION 10.0
#define GPIO_PIN 17  // BCM GPIO 17

// Structure for HMC5883L data
typedef struct {
    float x;
    float y;
    float z;
} HMC5883LData;

// Function prototypes
void setup_hmc5883l(void);
void read_hmc5883l_data(const uint8_t addr);
void apply_hard_iron_compensation(float x, float y, float z, float x_offset, float y_offset);
void handle_gpiod_event(gpiod_event_t *event);
void cleanup_resources(void);
void signal_handler(int signum);

