    setup_hmc5883l();
    gpiod_set_mode(GPIO_PIN, GPIOD_OUT_HIGH);

    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    bool running = true;
    struct timespec interval = {100 * 1000, 0};  // 100 ms interval

    while (running) {
        // Wait for the interval
        nanosleep(&interval, NULL);

        // Read HMC5883L data
        read_hmc5883l_data(HMC5883L_ADDR);

        // Apply hard iron compensation
        apply_hard_iron_compensation(hmc_data.x, hmc_data.y, hmc_data.z, 100, -50);

        // Check deviation from target heading
        if (fabs(hmc_data.heading - TARGET_HEADING) > THRESHOLD_DEVIATION) {
            gpiod_set_value(GPIO_PIN, 1);  // Set GPIO high
        } else {
            gpiod_set_value(GPIO_PIN, 0);  // Set GPIO low
        }

        // Check if buffer is full and overwrite the oldest entry
        if (buffer_head >= BUFFER_SIZE) {
            buffer_head = 0;
        }

        // Store the compensated heading in the buffer
        buffer[buffer_head++] = hmc_data.heading;
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to setup HMC5883L
void setup_hmc5883l(void) {
    int fd;
    struct i2c_dev *i2c_dev;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Create I2C device structure
    i2c_dev = i2c_dev_open(fd, I2C_SLAVE);
    if (!i2c_dev) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Enable I2C clock stretching
    i2c_dev->flags |= I2C_FLAG_CLOCK_STRETCH;
}

// Function to read HMC5883L data
void read_hmc5883l_data(const uint8_t addr) {
    uint8_t data[6];
    int ret;

    // Read six bytes of data (X, Y, Z, and two bytes for device ID)
    ret = i2c_smbus_read_i2c_block_data(i2c_dev, addr, 0, data, 6);
    if (ret != 6) {
        fprintf(stderr, "Failed to read from HMC5883L: %d\n", ret);
        return;
    }

    // Convert raw data to magnetic field values
    HMC5883LData hmc_data;
    hmc_data.x = (float)data[0] * 0.795;
    hmc_data.y = (float)data[1] * 0.447;
    hmc_data.z = (float)data[2] * 0.225;
    hmc_data.heading = atan2(hmc_data.y, hmc_data.x) * 180.0 / M_PI;

    // Apply hard iron compensation
    apply_hard_iron_compensation(hmc_data.x, hmc_data.y, hmc_data.z, 100, -50);
}

// Function to apply hard iron compensation
void apply_hard_iron_compensation(float x, float y, float z, float x_offset, float y_offset) {
    x += x_offset;
    y += y_offset;
}

// Function to handle GPIO events
void handle_gpiod_event(gpiod_event_t *event) {
    if (event->flags & GPIOD_ECHANGE) {
        // GPIO value has changed, handle accordingly
        if (event->value) {
            printf("Heading deviation detected, GPIO17 high.\n");
        } else {
            printf("Heading within threshold, GPIO17 low.\n");
        }
    }
}

// Function to cleanup resources
void cleanup_resources(void) {
    if (i2c_dev) {
        i2c_dev_close(i2c_dev);
        i2c_dev_free(i2c_dev);
    }

    gpiod_stop(GPIO_PIN);
    gpiod_remove(GPIO_PIN);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    running = false;
    // Clean up resources immediately
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

// Circular buffer for storing compensated headings
volatile static int buffer_head = 0;
float buffer[BUFFER_SIZE];

// Ensure all variables are declared as volatile to handle concurrent access properly
volatile bool running = true;

