#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define GPIO_RED 17
#define GPIO_GREEN 27
#define GPIO_BLUE 22

#define I2C_DEVICE "/dev/i2c-1"

int main() {
    // Initialize GPIO
    int red_fd, green_fd, blue_fd;
    red_fd = gpiod_open(GPIO_RED, GPIOD_OPEN_OUTPUT);
    green_fd = gpiod_open(GPIO_GREEN, GPIOD_OPEN_OUTPUT);
    blue_fd = gpiod_open(GPIO_BLUE, GPIOD_OPEN_OUTPUT);

    // Initialize I2C
    int i2c_fd;
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // BH1750 initialization
    struct i2c_msg msg = {
        .addr = BH1750_ADDR,
        .flags = 0,
        .len = sizeof(struct bh1750_data)
    };

    struct bh1750_data data;
    int i2c_ret;

    while (1) {
        // Read light level
        i2c_ret = i2c_transfer(i2c_fd, &msg, 1);
        if (i2c_ret != 1) {
            perror("I2C transfer error");
            break;
        }

        data = *(struct bh1750_data *)msg.data;
        int lux = data.lux / 100.0; // Convert to lux

        // Check lux thresholds and control GPIO
        if (lux < 50) {
            gpiod_write(red_fd, 1); // Turn on RED
        } else if (lux >= 50 && lux <= 150) {
            gpiod_write(green_fd, 1); // Turn on GREEN
        } else if (lux >= 150 && lux <= 300) {
            gpiod_write(blue_fd, 1); // Turn on BLUE
        } else {
            gpiod_write(red_fd, 1); // Turn on RED
            gpiod_write(green_fd, 1); // Turn on GREEN
            gpiod_write(blue_fd, 1); // Turn on BLUE
        }

        // Wait for at least 120 ms
        usleep(120000);

        // Log data
        struct tm timeinfo;
        time(&timeinfo);
        char filename[256] = "lighting_log.txt";
        FILE *log_file = fopen(filename, "a+");
        if (!log_file) {
            perror("Failed to open log file");
            break;
        }

        fprintf(log_file, "%s %d %d %d\n",
                ctime(&timeinfo.tm_ptr),
                lux,
                gpiod_get_value_level(red_fd) ? "ON" : "OFF",
                gpiod_get_value_level(green_fd) ? "ON" : "OFF",
                gpiod_get_value_level(blue_fd) ? "ON" : "OFF");
        fclose(log_file);

        // Close resources
        gpiod_close(red_fd);
        gpiod_close(green_fd);
        gpiod_close(blue_fd);
        close(i2c_fd);
    }

    // Cleanup on exit
    if (red_fd) gpiod_close(red_fd);
    if (green_fd) gpiod_close(green_fd);
    if (blue_fd) gpiod_close(blue_fd);
    if (i2c_fd) close(i2c_fd);

    return EXIT_SUCCESS;
}

