    // Initialize GPIO and PWM
    setup_gpios();
    setup_pwm();

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Simulate ultrasonic distance readings
