    gpiod_set_value(GPIO18, 0); // Set low initially

    gpiod_set_mode(GPIO22, GPIO_MODE_OUTPUT);
    gpiod_set_value(GPIO22, 0); // Set low initially

    gpiod_set_mode(GPIO23, GPIO_MODE_OUTPUT);
