        gpiod_pwm_set(gpiod_get_device(GPIO18), duty_cycle_a);
    } else {
        // Backward for Motor A
        gpiod_set_value(GPIO17, 0);
        gpiod_set_value(GPIO22, 0);
        int duty_cycle_a = 255 - (MAX_DISTANCE - distance_a) * 255 / (MAX_DISTANCE - MIN_DISTANCE);
        gpiod_pwm_set(gpiod_get_device(GPIO18), duty_cycle_a);
    }

    if (distance_b < THRESHOLD_DISTANCE) {
        // Forward for Motor B
        gpiod_set_value(GPIO22, 1);
        gpiod_set_value(GPIO23, 1);
        int duty_cycle_b = (distance_b - MIN_DISTANCE) * 255 / (MAX_DISTANCE - MIN_DISTANCE);
        gpiod_pwm_set(gpiod_get_device(GPIO23), duty_cycle_b);
    } else {
        // Backward for Motor B
        gpiod_set_value(GPIO22, 0);
        gpiod_set_value(GPIO23, 0);
        int duty_cycle_b = 255 - (MAX_DISTANCE - distance_b) * 255 / (MAX_DISTANCE - MIN_DISTANCE);
        gpiod_pwm_set(gpiod_get_device(GPIO23), duty_cycle_b);
    }
}

// Signal handler for SIGINT and SIGTERM
void handle_signals(int signum) {
    // Clean up GPIO and PWM
    cleanup_gpios();
    cleanup_pwm();

    // Exit the program
    exit(EXIT_SUCCESS);
}

