#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define STEPS_PER_QUARTER_TURN 512
#define INTER_STEP_DELAY_MS 2
#define GPIO_NUM_IN1 17
#define GPIO_NUM_IN2 18
#define GPIO_NUM_IN3 27
#define GPIO_NUM_IN4 22
#define GPIO_NUM_LOCK_BUTTON 24
#define GPIO_NUM_UNLOCK_BUTTON 23

// Function prototypes
void setup_gpios(void);
void step_motor(int steps, int direction);
void lock_door(void);
void unlock_door(void);
void cleanup_resources(void);
void handle_signal(int signum);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        int button_state;
        // Check lock button
        button_state = gpiod_read(GPIO_NUM_LOCK_BUTTON);
        if (button_state == 0) {
            lock_door();
        }

        // Check unlock button
        button_state = gpiod_read(GPIO_NUM_UNLOCK_BUTTON);
        if (button_state == 0) {
            unlock_door();
        }
    }

    // Clean up on exit
    cleanup_resources();

    return 0;
}

// Function to set up GPIO pins
void setup_gpios(void) {
    int in1 = gpiod_open(GPIO_NUM_IN1, GPIOD_DIR_OUT);
    int in2 = gpiod_open(GPIO_NUM_IN2, GPIOD_DIR_OUT);
    int in3 = gpiod_open(GPIO_NUM_IN3, GPIOD_DIR_OUT);
    int in4 = gpiod_open(GPIO_NUM_IN4, GPIOD_DIR_OUT);
    int lock_button = gpiod_open(GPIO_NUM_LOCK_BUTTON, GPIOD_DIR_IN | GPIOD_PIN_INPUT_PULLUP);
    int unlock_button = gpiod_open(GPIO_NUM_UNLOCK_BUTTON, GPIOD_DIR_IN | GPIOD_PIN_INPUT_PULLUP);

    if (in1 < 0 || in2 < 0 || in3 < 0 || in4 < 0 || lock_button < 0 || unlock_button < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(in1, 1);
    gpiod_direction_output(in2, 0);
    gpiod_direction_output(in3, 0);
    gpiod_direction_output(in4, 1);

    // Set up step sequence
    int steps = STEPS_PER_QUARTER_TURN;
    for (int i = 0; i < steps; i += 4) {
        step_motor(i, 1); // Step forward
        usleep(INTER_STEP_DELAY_MS * 1000);
        step_motor(i, 0); // Step backward
        usleep(INTER_STEP_DELAY_MS * 1000);
    }
}

// Function to step the motor
void step_motor(int steps, int direction) {
    if (direction) {
        gpiod_write(in1, 1);
        gpiod_write(in2, 0);
        gpiod_write(in3, 0);
        gpiod_write(in4, 1);
    } else {
        gpiod_write(in1, 0);
        gpiod_write(in2, 1);
        gpiod_write(in3, 0);
        gpiod_write(in4, 0);
    }
}

// Function to lock the door
void lock_door(void) {
    printf("Locking the door...\n");
}

// Function to unlock the door
void unlock_door(void) {
    printf("Unlocking the door...\n");
}

// Function to clean up resources
void cleanup_resources(void) {
    gpiod_close(in1);
    gpiod_close(in2);
    gpiod_close(in3);
    gpiod_close(in4);
    gpiod_close(lock_button);
    gpiod_close(unlock_button);
}

// Signal handler to cleanly de-energize the motor and release resources
void handle_signal(int signum) {
    // De-energize the motor coils
    gpiod_write(in1, 0);
    gpiod_write(in2, 0);
    gpiod_write(in3, 0);
    gpiod_write(in4, 0);

    // Release all resources
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

