#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_NUMS {4, 17, 27, 22} // BCM GPIO numbers
#define PWM_FREQ 100000 // 100 Hz PWM

// Structure to hold relay information
typedef struct Relay {
    int gpio;
    int state;
} Relay;

// Global variables
Relay relays[NUM_RELAYS];
int current_fade_time = 0; // Time of current fade operation
int prev_fade_time = 0; // Previous fade time for comparison
int fade_direction = 1; // 1 for increasing, -1 for decreasing brightness

// Function prototypes
void setup_relays();
void handle_schedule();
void handle_fade(int relay);
void cleanup();
void signal_handler(int signum);

int main() {
    // Initialize GPIO
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup relays
    setup_relays();

    // Main loop
    while (1) {
        handle_schedule();
        usleep(1000000); // Sleep for 1 second
    }

    // Clean up on exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize relays
void setup_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        int gpio = GPIO_NUMS[i];
        if (gpiod_direction_output(gpio, 0) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d for output: %s\n", gpio, gpiod_errstr(gpiod_get_error()));
            exit(EXIT_FAILURE);
        }

        relays[i].gpio = gpio;
        relays[i].state = (gpiod_get_value(gpio) == 1) ? 1 : 0; // Initialize based on current GPIO state
    }
}

// Function to handle the schedule
void handle_schedule() {
    FILE *schedule_file = fopen("lighting_schedule.txt", "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Failed to open schedule file: %s\n", strerror(errno));
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_file)) {
        char *tokens[] = {nullptr, nullptr, nullptr, nullptr};
        int relay_index = 0;
        if (sscanf(line, "%2d:%2d:%2d,%d,%d;", &tokens[0], &tokens[1], &tokens[2], &relay_index) != 4) {
            continue;
        }

        int hour = atoi(tokens[0]);
        int minute = atoi(tokens[1]);
        int second = atoi(tokens[2]);
        int relay = relay_index;

        // Check if transition is required
        if (relays[relay].state != (hour >= second && minute == 0 && second >= 0)) {
            int fade_time = 1800; // 30 minutes fade time

            // Start fade
            if (fade_direction == 1) {
                prev_fade_time = current_fade_time;
                current_fade_time = second + fade_time;
                handle_fade(relay);
            } else {
                if (current_fade_time > second) {
                    current_fade_time = prev_fade_time - fade_time;
                    handle_fade(relay, -1); // Decrease brightness
                } else {
                    // No need to decrease further, reset fade
                    current_fade_time = 0;
                }
            }
        }
    }

    fclose(schedule_file);
}

// Function to handle fade for a specific relay
void handle_fade(int relay_index, int step) {
    int gpio = GPIO_NUMS[relay_index];
    int duty_cycle = (step * 100) / 100; // 0 to 100 duty cycle

    if (gpiod_set_value(gpio, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set GPIO %d duty cycle: %s\n", gpio, gpiod_errstr(gpiod_get_error()));
        return;
    }

    // Schedule fade completion
    if (current_fade_time == fade_time) {
        fade_direction *= -1; // Reverse direction for next transition
        current_fade_time = 0;
    }
}

// Function to clean up and release resources
void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_set_value(GPIO_NUMS[i], 0); // Turn off relays
    }

    gpiod_uninit(); // Uninitialize GPIO
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Avoid non-reentrant functions like fopen or localtime
    // Simply turn off all relays and exit
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_set_value(GPIO_NUMS[i], 0); // Turn off relays
    }

    exit(EXIT_FAILURE);
}

