void handle_interrupts(int signum);
void measure_distance(uint32_t *distance_us);
void map_distance_to_frequency(uint32_t distance_us, uint32_t *frequency_hz);
void set_pwm_frequency(uint32_t frequency_hz);
void cleanup(void);

int main(void) {
    // Initialize GPIO and signal handler
    setup_gpios();
    signal(SIGINT, handle_interrupts);

    while (!should_exit) {
        // Wait for minimum interval between measurements
        usleep(MIN_MEASUREMENT_INTERVAL_MS * 1000);

        // Measure distance
        uint32_t distance_us;
        if (gpiod_c_read(ECHO_PIN, &distance_us, sizeof(distance_us)) < 0) {
            fprintf(stderr, "Error reading echo pin: %s\n", gpiod_error_string());
            continue;
        }

        // Map distance to frequency
        uint32_t frequency_hz;
        map_distance_to_frequency(distance_us, &frequency_hz);

        // Set PWM frequency
        set_pwm_frequency(frequency_hz);

        // Wait for a short period before next measurement
        usleep(50000); // 50 Hz sampling rate
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup GPIO pins
void setup_gpios(void) {
    int trigger_error, echo_error, pwm_error;

    // Initialize GPIO for trigger and echo pins
    trigger_error = gpiod_c_open(TRIGGER_PIN, GPIOD_OPEN_DUPLEX);
    if (trigger_error) {
