    echo_error = gpiod_c_open(ECHO_PIN, GPIOD_OPEN_DUPLEX);
    if (echo_error) {
        fprintf(stderr, "Error opening echo pin: %s\n", gpiod_error_string());
        gpiod_c_close(TRIGGER_PIN);
        return;
    }

    // Initialize GPIO for PWM buzzer pin
    pwm_error = gpiod_c_open(BUZZER_PIN, GPIOD_OPEN_DUPLEX);
    if (pwm_error) {
        fprintf(stderr, "Error opening PWM pin: %s\n", gpiod_error_string());
        gpiod_c_close(ECHO_PIN);
        gpiod_c_close(TRIGGER_PIN);
        return;
    }

    // Set trigger pin to output
    trigger_error = gpiod_c_direction(TRIGGER_PIN, GPIOD_DIR_OUT);
    if (trigger_error) {
        fprintf(stderr, "Error setting trigger pin direction: %s\n", gpiod_error_string());
        gpiod_c_close(ECHO_PIN);
        gpiod_c_close(TRIGGER_PIN);
        gpiod_c_close(BUZZER_PIN);
        return;
    }

    // Set echo pin to input
    echo_error = gpiod_c_direction(ECHO_PIN, GPIOD_DIR_IN);
    if (echo_error) {
        fprintf(stderr, "Error setting echo pin direction: %s\n", gpiod_error_string());
        gpiod_c_close(TRIGGER_PIN);
        gpiod_c_close(BUZZER_PIN);
        return;
    }

    // Set PWM pin to output
    pwm_error = gpiod_c_direction(BUZZER_PIN, GPIOD_DIR_OUT);
    if (pwm_error) {
        fprintf(stderr, "Error setting PWM pin direction: %s\n", gpiod_error_string());
        gpiod_c_close(ECHO_PIN);
        gpiod_c_close(TRIGGER_PIN);
        return;
    }
}

// Signal handler for SIGINT
void handle_interrupts(int signum) {
    should_exit = 1;
    // Silence the buzzer
    gpiod_c_set_value(BUZZER_PIN, 0);
}

// Measure distance using HC-SR04 and return microseconds
void measure_distance(uint32_t *distance_us) {
    // Issue 10 microsecond trigger pulse
    gpiod_c_set_value(TRIGGER_PIN, 1);
    usleep(TRIGGER_DURATION);
    gpiod_c_set_value(TRIGGER_PIN, 0);

    // Wait for echo signal
    uint32_t start_time = clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_c_read(ECHO_PIN) == 0) {
        // Timeout after 20000 microseconds (20 ms)
        if (clock_gettime(CLOCK_MONOTONIC, &start) - start_time >= (20000 * 1000)) {
            fprintf(stderr, "Timeout waiting for echo signal.\n");
            *distance_us = 0; // Return 0 if timeout
            return;
        }
    }

    // Calculate echo time in microseconds
    uint32_t echo_time = clock_gettime(CLOCK_MONOTONIC, &start) - start;
    *distance_us = echo_time - (20000 * 1000); // Subtract the trigger pulse duration
}

// Map distance to frequency within valid range
void map_distance_to_frequency(uint32_t distance_us, uint32_t *frequency_hz) {
    // Calculate frequency based on distance
    // Assuming a linear mapping for simplicity
    *frequency_hz = (uint32_t)((SPEED_OF_SOUND / (distance_us * 2)) * 1000000); // Hz

    // Clamp frequency to valid range (e.g., 200 Hz to 20 kHz)
    if (*frequency_hz < 200) {
        *frequency_hz = 200;
    } else if (*frequency_hz > 20000) {
        *frequency_hz = 20000;
    }
}

// Set PWM buzzer frequency
void set_pwm_frequency(uint32_t frequency_hz) {
    // Configure PWM frequency
    // Assuming Raspberry Pi Zero W has a default PWM frequency of 19.2 kHz
    // Calculate duty cycle for desired frequency
    uint32_t duty_cycle = (uint32_t)(frequency_hz * 19200 / 10000000);

    // Set duty cycle
    gpiod_c_set_value(BUZZER_PIN, duty_cycle);
}

// Cleanup function to close GPIO resources
void cleanup(void) {
    gpiod_c_close(TRIGGER_PIN);
    gpiod_c_close(ECHO_PIN);
    gpiod_c_close(BUZZER_PIN);
}

