#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// Define the GPIO pins for the RGB LED
#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27

// Function prototypes
void setup_gpios(void);
void cleanup_gpios(void);
void handle_signal(int signum);
void fade_color(double proximity);

int main(void) {
    // Initialize gpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errstr(gpiod_get_error()));
        return EXIT_FAILURE;
    }

    // Register a signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Set up GPIO pins for PWM
    setup_gpios();

    // Main loop
    while (1) {
        fade_color(sin(time(NULL) * 1000.0) / M_PI); // Sine wave function for proximity
        usleep(1000); // 1 ms delay for 1 kHz frequency
    }

    // Cleanup on exit or SIGINT
    cleanup_gpios();

    return EXIT_SUCCESS;
}

// Function to set up GPIO pins for PWM
void setup_gpios(void) {
    struct gpio_desc *red_gpio_desc;
    struct gpio_desc *green_gpio_desc;
    struct gpio_desc *blue_gpio_desc;

    // Open GPIO pins
    red_gpio_desc = gpiod_get_desc_by_number(RED_GPIO);
    green_gpio_desc = gpiod_get_desc_by_number(GREEN_GPIO);
    blue_gpio_desc = gpiod_get_desc_by_number(BLUE_GPIO);

    if (!red_gpio_desc || !green_gpio_desc || !blue_gpio_desc) {
        fprintf(stderr, "Failed to get GPIO descriptors: %s\n", gpiod_errstr(gpiod_get_error()));
        exit(EXIT_FAILURE);
    }

    // Set GPIOs to ALT0 function (GPIO)
    if (gpiod_set_mode(red_gpio_desc, GPIOD_MODE_ALT0) < 0) {
        fprintf(stderr, "Failed to set red GPIO to ALT0: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_mode(green_gpio_desc, GPIOD_MODE_ALT0) < 0) {
        fprintf(stderr, "Failed to set green GPIO to ALT0: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }

    if (gpiod_set_mode(blue_gpio_desc, GPIOD_MODE_ALT0) < 0) {
        fprintf(stderr, "Failed to set blue GPIO to ALT0: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }

    // Initialize PWM channels
    if (gpiod_pwm_init(red_gpio_desc, 1000) < 0) {
        fprintf(stderr, "Failed to initialize red PWM: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }

    if (gpiod_pwm_init(green_gpio_desc, 1000) < 0) {
        fprintf(stderr, "Failed to initialize green PWM: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }

    if (gpiod_pwm_init(blue_gpio_desc, 1000) < 0) {
        fprintf(stderr, "Failed to initialize blue PWM: %s\n", gpiod_errstr(gpiod_get_error()));
        gpiod_release_desc(red_gpio_desc);
        gpiod_release_desc(green_gpio_desc);
        gpiod_release_desc(blue_gpio_desc);
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup GPIO pins and release resources
void cleanup_gpios(void) {
    gpiod_pwm_uninit(gpiod_get_pwm_desc_by_gpio(RED_GPIO));
    gpiod_pwm_uninit(gpiod_get_pwm_desc_by_gpio(GREEN_GPIO));
    gpiod_pwm_uninit(gpiod_get_pwm_desc_by_gpio(BLUE_GPIO));

    gpiod_release_desc(gpiod_get_desc_by_number(RED_GPIO));
    gpiod_release_desc(gpiod_get_desc_by_number(GREEN_GPIO));
    gpiod_release_desc(gpiod_get_desc_by_number(BLUE_GPIO));

    gpiod_exit();
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Turn off the LED and cleanup GPIOs
    fade_color(0.0);
    cleanup_gpios();
    exit(EXIT_FAILURE); // Exit the program
}

// Function to fade the color based on the proximity value
void fade_color(double proximity) {
    // Normalize proximity to range [0.0, 1.0]
    proximity = fminf(proximity, 1.0);

    // Calculate duty cycles for PWM
    uint32_t red_duty = (uint32_t)(proximity * 65535.0);
    uint32_t green_duty = (uint32_t)(proximity * 65535.0);
    uint32_t blue_duty = (uint32_t)(proximity * 65535.0);

    // Set PWM duty cycles
    gpiod_pwm_set(gpiod_get_pwm_desc_by_gpio(RED_GPIO), red_duty);
    gpiod_pwm_set(gpiod_get_pwm_desc_by_gpio(GREEN_GPIO), green_duty);
    gpiod_pwm_set(gpiod_get_pwm_desc_by_gpio(BLUE_GPIO), blue_duty);
}

