// Function to open I2C device
void open_i2c_device(void) {
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Check if device is accessible
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to close I2C device
void close_i2c_device(void) {
    close(fd);
}

// Function to read from MPU6050 register
int read_mpu6050(uint8_t reg, uint8_t *data) {
    reg_cmd.reg = reg;
    reg_cmd.data[0] = (reg >> 4) & 0x0F;
    reg_cmd.data[1] = reg & 0x0F;
    reg_cmd.data[2] = 0x00;
    reg_cmd.data[3] = 0x00;
    reg_cmd.data[4] = 0x00;
    reg_cmd.data[5] = 0x00;

    if (write_mpu6050(reg, reg_cmd.data) < 6) {
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        return -1;
    }

    return 0;
}

// Function to write to MPU6050 register
int write_mpu6050(uint8_t reg, uint8_t data[6]) {
    reg_cmd.reg = reg;
    memcpy(reg_cmd.data, data, 6);

    if (ioctl(fd, I2C_WRITE, reg_cmd.data) < 0) {
        return -1;
    }

    return 0;
}

