    y_val = (int16_t)(data[2] << 8 | data[3]);
    z_val = (int16_t)(data[4] << 8 | data[5]);

    // Convert to degrees per second
    x = (float)x_val / 131.0;
    y = (float)y_val / 131.0;
    z = (float)z_val / 131.0;
}

