    if (fprintf(fd, ",%f,%f,%f", x, y, z) < 0) {
        perror("fprintf to log file");
        exit(EXIT_FAILURE);
    }
}

// Signal handler to catch SIGINT and SIGTERM
void handle_signal(int signum) {
    // Clean up and exit
    close_i2c_device();
    printf("Exiting due to signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

