#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <libgpiod/gpiod.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_NUM 17
#define VIBRATION_THRESHOLD 3
#define DEFAULT_POLL_TIMEOUT 1000

volatile sig_atomic_t sigIntReceived = 0;

// Structure to hold vibration event
typedef struct {
    time_t timestamp;
    int value;
} VibrationEvent;

// Function prototypes
void handleSignal(int signum);
void setupGPIOAndLogging();
void pollForVibrationEvents(int timeout_ms);
void printEarthquakeAlert(VibrationEvent events[5]);
void logVibrationEvent(VibrationEvent event);
void cleanup();

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poll timeout in ms>\n", argv[0]);
        return 1;
    }

    int pollTimeout = atoi(argv[1]);
    if (pollTimeout <= 0) {
        pollTimeout = DEFAULT_POLL_TIMEOUT;
    }

    setupGPIOAndLogging();
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (!sigIntReceived) {
        pollForVibrationEvents(pollTimeout);
    }

    cleanup();

    return 0;
}

// SIGINT/SIGTERM handler
void handleSignal(int signum) {
    sigIntReceived = 1;
}

// Setup GPIO and logging
void setupGPIOAndLogging() {
    int fd;

    // Open GPIO device
    if ((fd = gpiod_open(GPIOD, "r")) < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Open log file for appending
    if ((fd = fopen("vibration_events.log", "a")) == NULL) {
        perror("fopen");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 17 for edge detection
    if (gpiod_set_data_direction(fd, GPIO_NUM, GPIOD_DATA_IN) < 0) {
        perror("gpiod_set_data_direction");
        fclose(fd);
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Setup SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = handleSignal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

// Poll for vibration events
void pollForVibrationEvents(int timeout_ms) {
    struct timespec ts;
    int events[5];
    int count = 0;

    // Convert timeout to timespec
    ts.tv_sec = timeout_ms / 1000;
    ts.tv_nsec = (timeout_ms % 1000) * 1000000;

    while (count < 5 && gpiod_poll_event(fd, GPIO_NUM, GPIOD_EDGE_BOTH, &ts) >= 0) {
        VibrationEvent event = {0};
        event.timestamp = time(NULL);
        event.value = gpiod_get_value(fd, GPIO_NUM);

        logVibrationEvent(event);

        if (++count >= VIBRATION_THRESHOLD) {
            printEarthquakeAlert(events);
        }
    }

    // If no events were detected within timeout, print a message
    if (count == 0) {
        fprintf(stderr, "No vibration events detected within %dms.\n", timeout_ms);
    }
}

// Print "EARTHQUAKE ALERT" and current timestamp for three or more consecutive HIGH events
void printEarthquakeAlert(VibrationEvent events[5]) {
    for (int i = 0; i < 3; ++i) {
        if (events[i].value == 1) {
            printf("EARTHQUAKE ALERT at %s\n", ctime(&events[i].timestamp));
            return; // Exit after printing the first alert
        }
    }

    // If no alert was printed, print a message
    fprintf(stderr, "Three or more consecutive HIGH events not detected.\n");
}

// Log a single vibration event
void logVibrationEvent(VibrationEvent event) {
    char logMessage[256];
    strftime(logMessage, sizeof(logMessage), "%Y-%m-%dT%H:%M:%S.%03fZ ", &event.timestamp);
    sprintf(logMessage + strlen("%Y-%m-%dT%H:%M:%S.%03fZ "), " %d", event.value);

    if (fwrite(logMessage, 1, sizeof(logMessage), fd) != sizeof(logMessage)) {
        perror("fwrite");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    fsync(fd); // Ensure data is written to disk
}

// Cleanup function
void cleanup() {
    gpiod_close(fd);
    fclose(fd);
}

