#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>

#define I2C_ADDR 0x1D  // 7-bit address for LSM303DLHC
#define SDA_GPIO 2     // GPIO2/BCM
#define SCL_GPIO 3     // GPIO3/BCM

// Calibration offsets for LSM303DLHC
#define X_OFFSET 10
#define Y_OFFSET (-5)
#define Z_OFFSET 20

// Compass directions mapping
const char *compass_directions[8] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

// Function prototypes
void setup_lsm303();
void read_magnetic_field();
void handle_compass_direction(int heading);
void handle_interrupts(int signum);
void cleanup();

int main() {
    // Initialize signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Setup LSM303DLHC
    setup_lsm303();

    // Main loop
    while (1) {
        // Read magnetic field
        read_magnetic_field();

        // Handle compass direction
        handle_compass_direction(g_magnetic_field.x);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to initialize the LSM303DLHC
void setup_lsm303() {
    // Open I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        return;
    }

    // GPIO setup for SDA and SCL
    gpiod_set_data_direction(SDA_GPIO, GPIO_OUT);
    gpiod_set_value(SDA_GPIO, 1);

    gpiod_set_data_direction(SCL_GPIO, GPIO_OUT);
    gpiod_set_value(SCL_GPIO, 1);

    // Set SDA and SCL pins as alternate function
    gpiod_set_function(SDA_GPIO, GPIOD_FUNCTION_I2C_SDA);
    gpiod_set_function(SCL_GPIO, GPIOD_FUNCTION_I2C_SCL);

    // Open I2C device with libgpiod
    struct i2c_dev *i2c_dev = i2c_open(i2c_fd, I2C_ADDR);
    if (!i2c_dev) {
        fprintf(stderr, "Error: Failed to open I2C device with libgpiod.\n");
        close(i2c_fd);
        return;
    }

    // Write calibration offsets
    if (i2c_smbus_write_i2c_block_data(i2c_dev, I2C_ADDR, 0x2D, (uint8_t[]) {X_OFFSET, Y_OFFSET, Z_OFFSET}) != 4) {
        fprintf(stderr, "Error: Failed to write calibration offsets.\n");
        i2c_close(i2c_dev);
        close(i2c_fd);
        return;
    }

    // Close libgpiod I2C device
    i2c_close(i2c_dev);
}

// Function to read magnetic field from LSM303DLHC
void read_magnetic_field() {
    // Open I2C device with libgpiod
    struct i2c_dev *i2c_dev = i2c_open("/dev/i2c-1", O_RDWR);
    if (!i2c_dev) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        return;
    }

    // Read magnetic field data
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_dev, I2C_ADDR, 0x3D, data) != 6) {
        fprintf(stderr, "Error: Failed to read magnetic field data.\n");
        i2c_close(i2c_dev);
        return;
    }

    // Convert raw data to calibrated values
    int x_calibrated = data[0] + X_OFFSET;
    int y_calibrated = data[1] + Y_OFFSET;
    int z_calibrated = data[2] + Z_OFFSET;

    // Compute heading in degrees
    double heading = atan2(y_calibrated, x_calibrated) * 180.0 / M_PI;
    heading = fmod(heading, 360.0);

    // Handle compass direction
    handle_compass_direction(heading);

    // Close libgpiod I2C device
    i2c_close(i2c_dev);
}

// Function to handle compass direction
void handle_compass_direction(int heading) {
    // Map heading to compass direction
    int direction_index = (int)floor(heading / 45.0);
    char direction[5];
    strncpy(direction, compass_directions[direction_index], 4);
    direction[4] = '\0';

    // Print compass direction
    printf("Compass direction: %s\n", direction);

    // Print numeric heading
    printf("Heading: %d.0f°\n", direction_index, heading);
}

// Signal handler for SIGINT and SIGTERM
void handle_interrupts(int signum) {
    // Close I2C file descriptor
    close(0);

    // Close CSV file
    if (mag_log_file != NULL) {
        fclose(mag_log_file);
        mag_log_file = NULL;
    }

    // Free resources
    cleanup();
}

// Function to cleanup resources
void cleanup() {
    // Close CSV file if it exists
    if (mag_log_file != NULL) {
        fclose(mag_log_file);
        mag_log_file = NULL;
    }

    // Free resources
    gpiod_set_function(SDA_GPIO, GPIOD_FUNCTION_NONE);
    gpiod_set_function(SCL_GPIO, GPIOD_FUNCTION_NONE);
    gpiod_set_data_direction(SDA_GPIO, GPIO_INPUT);
    gpiod_set_data_direction(SCL_GPIO, GPIO_INPUT);
}

// Open or create CSV file for logging
FILE *mag_log_file = fopen("mag_log.csv", "a+");
if (mag_log_file == NULL) {
    fprintf(stderr, "Error: Failed to open or create CSV file for logging.\n");
    exit(1);
}

// Main program loop
while (1) {
    // Main loop logic
    // ...
}

