        fprintf(stderr, "Error opening GPIO %u for events: %s\n", RELAY_GPIO, gpiod_error_str(gpiod_get_error()));
        gpiod_event_close(touch_sensor);
        return EXIT_FAILURE;
    }

    // Open log file for writing
    if ((relay_log_file = fopen("relay_log.json", "w")) == NULL) {
        fprintf(stderr, "Failed to open relay_log.json for writing: %s\n", strerror(errno));
        gpiod_event_close(touch_sensor);
        gpiod_event_close(relay);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Check debounce condition
        if (time(NULL) - last_touch_time >= TOUCH_DEBOUNCE_MS) {
            // Toggle relay state
            if (last_relay_state == 0) {
                last_relay_state = 1;
                gpiod_set_value_relays(relay, RELAY_GPIO, 1);
                fprintf(relay_log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"ON\"}\n", ctime(&time(NULL)));
            } else {
                last_relay_state = 0;
                gpiod_set_value_relays(relay, RELAY_GPIO, 0);
                fprintf(relay_log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", ctime(&time(NULL)));
            }

            // Update last touch time
            last_touch_time = time(NULL);
        }

        // Handle SIGINT (Ctrl+C)
        if (signal(SIGINT, handle_sigint) == SIG_ERR) {
            fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
            break;
        }

        // Poll for GPIO events
        gpiod_poll(touch_sensor, -1);
    }

    // Cleanup on exit
    handle_sigint(SIGINT);

    // Close log file and release resources
    fclose(relay_log_file);
    gpiod_event_close(touch_sensor);
    gpiod_event_close(relay);

    // Final cleanup
    cleanup();

    return EXIT_SUCCESS;
}

// Function to set up GPIO devices
void setup_gpios(void) {
    struct gpiod_chip *chip;
    int ret;

    // Find the GPIO chip
    chip = gpiod_chips_get_default();
    if (chip == NULL) {
        fprintf(stderr, "Failed to find GPIO chip: %s\n", gpiod_error_str(gpiod_get_error()));
        return;
    }

    // Initialize GPIO descriptors
    touch_sensor = gpiod_get(devchip_to_gpiod_chip(chip, TOUCH_GPIO));
    relay = gpiod_get(devchip_to_gpiod_chip(chip, RELAY_GPIO));

    if (touch_sensor == NULL || relay == NULL) {
        fprintf(stderr, "Failed to get GPIO descriptors: %s\n", gpiod_error_str(gpiod_get_error()));
        gpiod_chips_free(chip);
        return;
    }

    // Set GPIO pins to input and output respectively
    ret = gpiod_set_direction(touch_sensor, GPIOD_DIR_IN);
    if (ret < 0) {
        fprintf(stderr, "Error setting touch GPIO direction: %s\n", gpiod_error_str(gpiod_get_error()));
        gpiod_put(touch_sensor, NULL);
        gpiod_put(relay, NULL);
        return;
    }

    ret = gpiod_set_direction(relay, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay GPIO direction: %s\n", gpiod_error_str(gpiod_get_error()));
        gpiod_put(touch_sensor, NULL);
        gpiod_put(relay, NULL);
        return;
    }

    // Ensure pull-down for touch sensor
    ret = gpiod_set_pull_up_down(touch_sensor, GPIOD_PULLDOWN);
    if (ret < 0) {
        fprintf(stderr, "Error setting touch GPIO pull-up/pull-down: %s\n", gpiod_error_str(gpiod_get_error()));
        gpiod_put(touch_sensor, NULL);
        gpiod_put(relay, NULL);
        return;
    }
}

// GPIO interrupt handler for touch sensor
void touch_detected_handler(struct gpiod_dev *dev, void *arg) {
    // No argument needed for this handler
    int state = gpiod_get_value(dev);

    if (state) {
        // A touch was detected
        last_touch_time = time(NULL);
        last_relay_state = !last_relay_state;
        gpiod_set_value_relays(relay, RELAY_GPIO, last_relay_state);
    }
}

// SIGINT handler
void handle_sigint(int signum) {
    // Force relay OFF
    gpiod_set_value_relays(relay, RELAY_GPIO, 0);

    // Append final OFF entry to the log
    char buffer[256];
    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(relay_log_file, "{\"timestamp\": \"%s\", \"relay_state\": \"OFF\"}\n", timestamp);

    // Close log file and release resources
    fclose(relay_log_file);
    gpiod_event_close(touch_sensor);
    gpiod_event_close(relay);

    // Exit the program
    exit(EXIT_FAILURE);
}

// Cleanup function to release resources
void cleanup(void) {
    // Close log file if it's still open
    if (relay_log_file != NULL) {
        fclose(relay_log_file);
        relay_log_file = NULL;
    }

