        fflush(irrigation_log); // Flush the buffer

        usleep(10000000); // 10 seconds delay
    }

    // Deactivate all relays and clean up
    deactivate_all_relays();

    // Close the log file and exit
    fclose(irrigation_log);
    gpiod_device_unref(gpiod_dev);

    return EXIT_SUCCESS;
}

