        check_gpiod_error("gpiod_direction_output");
    }
}

// Function to deactivate all relays
void deactivate_all_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_direction_output(gpiod_dev, RELAY_PIN_BCM[i], 1) < 0) {
            check_gpiod_error("gpiod_direction_output");
        }
    }
}

