    deactivate_all_relays();
    exit(EXIT_SUCCESS);
}

// Utility function to check and report GPIO and file operations errors
void check_gpiod_error(const char *operation) {
    if (gpiod_get_last_error() != GPIOD_NO_ERROR) {
        fprintf(stderr, "Error during %s operation: %s\n", operation, gpiod_get_error_string(gpiod_get_last_error()));
    }
}

// Utility function to check and report file operations errors
void check_file_operation(const char *operation) {
    if (operation && (ferror(irrigation_log) || feof(irrigation_log))) {
        fprintf(stderr, "Error during %s file operation.\n", operation);
    }
}

