    if (gpio_sda == -1 || gpio_scl == -1) {
        fprintf(stderr, "Error: Could not find GPIO pins for I2C.\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open /dev/i2c-1");
        return 1;
    }

    // Set up I2C device address and control registers
    struct i2c_msg msg[2];
    msg[0].addr = I2C_ADDR;
    msg[0].len = sizeof(uint16_t);
    msg[0].buf = (uint8_t *)&(I2C_SLAVE);

    msg[1].addr = I2C_ADDR;
    msg[1].len = sizeof(uint8_t);
    msg[1].buf = (uint8_t *)&(CTRL_REG1_XM);

