#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_NUM_IN1 4
#define GPIO_NUM_IN2 17
#define GPIO_NUM_IN3 27
#define GPIO_NUM_IN4 22
#define GPIO_NUM_LOCK 24
#define GPIO_NUM_UNLOCK 23

#define STEPS_PER_REVOLUTION 512
#define DELAY_MS 3

volatile int lock_request = 0;
volatile int unlock_request = 0;

void setup_gpios(void) {
    int ret;

    // Initialize GPIOs for L293D IN1-IN4
    ret = gpiod_open(GPIO_NUM_IN1);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", GPIO_NUM_IN1, gpiod_error(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_output(GPIO_NUM_IN1, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to output: %s\n", GPIO_NUM_IN1, gpiod_error(ret));
        gpiod_close(GPIO_NUM_IN1);
        exit(EXIT_FAILURE);
    }

    // Repeat for IN2, IN3, IN4
    ret = gpiod_open(GPIO_NUM_IN2);
    // ... (similar code for IN2, IN3, IN4)

    // Initialize GPIOs for LOCK and UNLOCK buttons with pull-ups
    ret = gpiod_open(GPIO_NUM_LOCK);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", GPIO_NUM_LOCK, gpiod_error(ret));
        exit(EXIT_FAILURE);
    }
    ret = gpiod_set_pull_mode(GPIO_NUM_LOCK, GPIO_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d: %s\n", GPIO_NUM_LOCK, gpiod_error(ret));
        gpiod_close(GPIO_NUM_LOCK);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_get_value(GPIO_NUM_LOCK);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_NUM_LOCK, gpiod_error(ret));
        gpiod_close(GPIO_NUM_LOCK);
        exit(EXIT_FAILURE);
    }
    if (gpiod_get_value(GPIO_NUM_LOCK) == 0) {
        fprintf(stderr, "Button LOCK detected (active-low logic)\n");
        lock_request = 1;
    }

    ret = gpiod_open(GPIO_NUM_UNLOCK);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO %d: %s\n", GPIO_NUM_UNLOCK, gpiod_error(ret));
        exit(EXIT_FAILURE);
    }
    ret = gpiod_set_pull_mode(GPIO_NUM_UNLOCK, GPIO_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d: %s\n", GPIO_NUM_UNLOCK, gpiod_error(ret));
        gpiod_close(GPIO_NUM_UNLOCK);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_get_value(GPIO_NUM_UNLOCK);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_NUM_UNLOCK, gpiod_error(ret));
        gpiod_close(GPIO_NUM_UNLOCK);
        exit(EXIT_FAILURE);
    }
    if (gpiod_get_value(GPIO_NUM_UNLOCK) == 0) {
        fprintf(stderr, "Button UNLOCK detected (active-low logic)\n");
        unlock_request = 1;
    }

    // De-energize all coils after each operation
    gpiod_write(GPIO_NUM_IN1, 0);
    gpiod_write(GPIO_NUM_IN2, 0);
    gpiod_write(GPIO_NUM_IN3, 0);
    gpiod_write(GPIO_NUM_IN4, 0);
}

void handle_lock_request(void) {
    int steps = STEPS_PER_REVOLUTION;
    while (lock_request && steps > 0) {
        // Step the motor clockwise
        gpiod_write(GPIO_NUM_IN1, 1);
        gpiod_write(GPIO_NUM_IN2, 0);
        gpiod_write(GPIO_NUM_IN3, 0);
        gpiod_write(GPIO_NUM_IN4, 0);
        usleep(DELAY_MS * 1000);
        steps--;
        gpiod_write(GPIO_NUM_IN1, 0);

        // Check for button debounce
        if (!gpiod_get_value(GPIO_NUM_LOCK)) {
            lock_request = 0;
        }
    }

    // De-energize all coils after locking
    gpiod_write(GPIO_NUM_IN1, 0);
    gpiod_write(GPIO_NUM_IN2, 0);
    gpiod_write(GPIO_NUM_IN3, 0);
    gpiod_write(GPIO_NUM_IN4, 0);
}

void handle_unlock_request(void) {
    int steps = STEPS_PER_REVOLUTION;
    while (unlock_request && steps > 0) {
        // Step the motor counter-clockwise
        gpiod_write(GPIO_NUM_IN1, 0);
        gpiod_write(GPIO_NUM_IN2, 1);
        gpiod_write(GPIO_NUM_IN3, 0);
        gpiod_write(GPIO_NUM_IN4, 0);
        usleep(DELAY_MS * 1000);
        steps--;
        gpiod_write(GPIO_NUM_IN2, 0);

        // Check for button debounce
        if (!gpiod_get_value(GPIO_NUM_UNLOCK)) {
            unlock_request = 0;
        }
    }

    // De-energize all coils after unlocking
    gpiod_write(GPIO_NUM_IN1, 0);
    gpiod_write(GPIO_NUM_IN2, 0);
    gpiod_write(GPIO_NUM_IN3, 0);
    gpiod_write(GPIO_NUM_IN4, 0);
}

void cleanup(void) {
    // Close all GPIOs
    gpiod_close(GPIO_NUM_IN1);
    // ... (similar for IN2, IN3, IN4)
    gpiod_close(GPIO_NUM_LOCK);
    gpiod_close(GPIO_NUM_UNLOCK);
}

int main(void) {
    signal(SIGINT, SIG_IGN); // Ignore SIGINT to prevent premature exit

    setup_gpios();

    while (1) {
        if (lock_request) {
            handle_lock_request();
        }
        if (unlock_request) {
            handle_unlock_request();
        }
    }

    // Graceful exit on SIGINT
    printf("Received SIGINT, de-energizing coils...\n");
    cleanup();
    printf("Exiting...\n");

    return 0;
}

