void setupRelay(int gpio);
void releaseRelay(int gpio);

int main() {
    // Signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, handleSIGINT);

    // Initialize GPIO for the relay
    setupRelay(RELAY_GPIO_PIN);

    // Main loop
    while (1) {
        // Read distance from VL53L1X
        int fd = openI2CDevice(VL53L1X_I2C_BUS);
        if (fd == -1) {
            fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
            continue;
        }

        char buf[6]; // Assuming the sensor returns distance in a 5-byte format
        ssize_t bytes_read = readI2C(fd, buf, sizeof(buf));
        if (bytes_read < 0) {
