#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <inttypes.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_XOUT_L 0x3C
#define MPU6050_REG_ACCEL_YOUT_H 0x3D
#define MPU6050_REG_ACCEL_YOUT_L 0x3E
#define MPU6050_REG_ACCEL_ZOUT_H 0x3F
#define MPU6050_REG_ACCEL_ZOUT_L 0x40
#define MPU6050_REG_GYRO_XOUT_H 0x1B
#define MPU6050_REG_GYRO_XOUT_L 0x1C
#define MPU6050_REG_GYRO_YOUT_H 0x1D
#define MPU6050_REG_GYRO_YOUT_L 0x1E
#define MPU6050_REG_GYRO_ZOUT_H 0x1F
#define MPU6050_REG_GYRO_ZOUT_L 0x20

// Function prototypes
void setup_gpiod();
void cleanup_gpiod();
void setup_i2c();
void cleanup_i2c();
void handle_signals(int signum);
void read_mpu6050(int fd);

int main() {
    // Signal handlers
    struct sigaction int_handler, term_handler;
    sigemptyset(&int_handler.sa_mask);
    int_handler.sa_handler = handle_signals;
    sigaction(SIGINT, &int_handler, NULL);
    sigaction(SIGTERM, &term_handler, NULL);

    // GPIO setup
    setup_gpiod();

    // I2C setup
    setup_i2c();

    // Main loop
    while (1) {
        read_mpu6050(-1); // Use -1 to indicate continuous reading
    }

    // Clean up resources
    cleanup_gpiod();
    cleanup_i2c();

    return 0;
}

// Function to set up GPIO for I2C
void setup_gpiod() {
    int gpio_sda = gpiod_get_index_by_name("BCM", "GPIO2");
    int gpio_scl = gpiod_get_index_by_name("BCM", "GPIO3");

    if (gpio_sda < 0 || gpio_scl < 0) {
        fprintf(stderr, "Error: Could not find GPIO pins for I2C.\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_output(gpio_sda, 1) < 0 || gpiod_direction_output(gpio_scl, 1) < 0) {
        fprintf(stderr, "Error: Could not configure GPIO pins for I2C.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to clean up GPIO
void cleanup_gpiod() {
    gpiod_set_value(gpio_sda, 0);
    gpiod_set_value(gpio_scl, 0);
}

// Function to set up I2C
void setup_i2c() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.\n");
        exit(EXIT_FAILURE);
    }

    // Check if device is present
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        fprintf(stderr, "Error: Could not access I2C device at address 0x68.\n");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

// Function to clean up I2C
void cleanup_i2c() {
    close(fd);
}

// Signal handler to clean up resources on SIGINT and SIGTERM
void handle_signals(int signum) {
    // Clean up resources
    cleanup_gpiod();
    cleanup_i2c();
    exit(EXIT_SUCCESS);
}

// Function to read data from the MPU6050
void read_mpu6050(int fd) {
    uint8_t data[14]; // Buffer for accelerometer and gyroscope data

    // Read accelerometer data (6 bytes)
    if (ioctl(fd, I2C_READ, (char *) &MPU6050_REG_ACCEL_XOUT_H | (char *) &MPU6050_REG_ACCEL_XOUT_L) < 0) {
        fprintf(stderr, "Error reading accelerometer data.\n");
        return;
    }

    // Read gyroscope data (8 bytes)
    if (ioctl(fd, I2C_READ, (char *) &MPU6050_REG_GYRO_XOUT_H | (char *) &MPU6050_REG_GYRO_XOUT_L | (char *) &MPU6050_REG_GYRO_YOUT_H | (char *) &MPU6050_REG_GYRO_YOUT_L | (char *) &MPU6050_REG_GYRO_ZOUT_H | (char *) &MPU6050_REG_GYRO_ZOUT_L) < 0) {
        fprintf(stderr, "Error reading gyroscope data.\n");
        return;
    }

    // Convert raw data to meaningful values (simplified for demonstration)
    int16_t accel_x = ((data[0] << 8) | data[1]) >> 8;
    int16_t accel_y = ((data[2] << 8) | data[3]) >> 8;
    int16_t accel_z = ((data[4] << 8) | data[5]) >> 8;

    int16_t gyro_x = ((data[6] << 8) | data[7]) >> 8;
    int16_t gyro_y = ((data[8] << 8) | data[9]) >> 8;
    int16_t gyro_z = ((data[10] << 8) | data[11]) >> 8;

    // Print data
    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
    printf("Gyroscope: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);
}

