#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>

#define LOG_FILE_PATH "smart_lighting.log"
#define PWM_FREQ 1000 // 1 kHz
#define RELAY_GPIO_PINS {17, 18, 27, 22} // BCM numbering

// Function prototypes
void setup_relays();
void cleanup();
void step_lighting(int seconds);
void handle_signals(int signum);

int main() {
    // Initialize GPIO
    if (gpiod_init() < 0) {
        perror("gpiod_init");
        exit(EXIT_FAILURE);
    }

    // Open log file for writing
    int log_fd = open(LOG_FILE_PATH, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (log_fd < 0) {
        perror("open(log_file)");
        exit(EXIT_FAILURE);
    }

    // Set signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Step lighting every second for 30 minutes
    time_t start_time = time(NULL);
    time_t end_time = start_time + 30 * 60;
    while (time(NULL) < end_time) {
        step_lighting((int)(time(NULL) - start_time / 60));
    }

    // Cleanup
    cleanup();

    // Close log file
    close(log_fd);

    return 0;
}

// Function to setup relay GPIO pins
void setup_relays() {
    for (int i = 0; i < sizeof(RELAY_GPIO_PINS) / sizeof(RELAY_GPIO_PINS[0]); i++) {
        int gpio = RELAY_GPIO_PINS[i];
        if (gpiod_direction_output(gpio, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to output.\n", gpio);
            exit(EXIT_FAILURE);
        }
    }
}

// Function to cleanup resources
void cleanup() {
    for (int i = 0; i < sizeof(RELAY_GPIO_PINS) / sizeof(RELAY_GPIO_PINS[0]); i++) {
        int gpio = RELAY_GPIO_PINS[i];
        gpiod_set_direction(gpio, GPIO_INPUT);
    }

    gpiod_exit();
}

// Function to step the lighting intensity
void step_lighting(int seconds) {
    struct timespec step_time;
    clock_gettime(CLOCK_REALTIME, &step_time);

    // Calculate the duty cycle based on seconds passed
    int duty_cycle = (int)(255 * (seconds / 1800.0));

    // Ensure duty cycle is within valid range
    duty_cycle = (duty_cycle < 0) ? 0 : (duty_cycle > 255) ? 255 : duty_cycle;

    // Write the duty cycle to each GPIO pin
    for (int i = 0; i < sizeof(RELAY_GPIO_PINS) / sizeof(RELAY_GPIO_PINS[0]); i++) {
        int gpio = RELAY_GPIO_PINS[i];
        if (gpiod_set_value(gpio, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set duty cycle for GPIO %d.\n", gpio);
        }
    }

    // Log the event
    char event_str[256];
    sprintf(event_str, "Step lighting at %d:%02d:%02d - Duty cycle: %d\n",
            (int)(step_time.tv_sec / 3600), (int)(step_time.tv_sec % 3600 / 60),
            (int)step_time.tv_sec % 60, duty_cycle);
    write(log_fd, event_str, strlen(event_str));
}

// Signal handler to gracefully exit on SIGINT or SIGTERM
void handle_signals(int signum) {
    fprintf(stderr, "Received signal %d, exiting gracefully...\n", signum);
    exit(EXIT_SUCCESS);
}

