#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <stdint.h>
#include <stdbool.h>

#define I2C_BUS_NUM 1
#define MPU6050_ADDRESS 0x68
#define GYROSCOPE_REG_ID_X 0x1B
#define GYROSCOPE_REG_ID_Y 0x1C
#define GYROSCOPE_REG_ID_Z 0x1D
#define SAMPLE_RATE_HZ 20
#define BUFFER_SIZE 100
#define THRESHOLD_DEGREES_PER_S 250

volatile uint8_t gpios[3] = {GPIO_NUM_17, GPIO_NUM_2, GPIO_NUM_3};
const char *gpios_names[] = {"LED", "SDA", "SCL"};

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    uint32_t timestamp;
} GyroData;

// Circular buffer for gyroscope data
static GyroData buffer[BUFFER_SIZE];

// Function prototypes
void i2c_init(void);
int i2c_read(uint8_t address, uint8_t reg_id, uint8_t *data);
void led_control(bool on);
void cleanup(void);
void signal_handler(int signum);

int main(void) {
    // Initialize GPIO and I2C
    i2c_init();
    gpiod_direction_output(gpios[0], 1); // LED GPIO high for ON

    // Signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint32_t now = time(NULL);
        uint8_t data[6]; // 3 axes * 2 bytes per axis

        // Attempt to read gyroscope data
        int result = i2c_read(MPU6050_ADDRESS, GYROSCOPE_REG_ID_X, &data[0]);
        if (result != 6) {
            // Handle I2C read error
            printf("I2C read error: %d\n", result);
            break;
        }

        // Parse gyroscope data
        GyroData gyro_data;
        gyro_data.x = (int16_t)data[0];
        gyro_data.y = (int16_t)data[1];
        gyro_data.z = (int16_t)data[2];
        gyro_data.timestamp = now;

        // Check if any axis exceeds threshold
        bool any_axis_exceeds = false;
        if (abs(gyro_data.x) > THRESHOLD_DEGREES_PER_S ||
            abs(gyro_data.y) > THRESHOLD_DEGREES_PER_S ||
            abs(gyro_data.z) > THRESHOLD_DEGREES_PER_S) {
            any_axis_exceeds = true;
        }

        // Control LED based on threshold
        led_control(any_axis_exceeds);

        // Add data to circular buffer
        if (buffer_head >= BUFFER_SIZE) {
            buffer_head = 0; // Wrap around
        }
        buffer[buffer_head].x = gyro_data.x;
        buffer[buffer_head].y = gyro_data.y;
        buffer[buffer_head].z = gyro_data.z;
        buffer[buffer_head].timestamp = now;

        // Check if buffer is full
        if (buffer_head == (BUFFER_SIZE - 1)) {
            buffer_head = 0; // Wrap around
        }
    }

    // Clean up on exit
    cleanup();

    return 0;
}

// Function to initialize I2C
void i2c_init() {
    int ret;
    ret = gpiod_i2c_setup(I2C_BUS_NUM, GPIOD_I2C_MASTER);
    if (ret < 0) {
        printf("Error initializing I2C: %d\n", ret);
        exit(EXIT_FAILURE);
    }
}

// Function to read data from the gyroscope over I2C
int i2c_read(uint8_t address, uint8_t reg_id, uint8_t *data) {
    int ret;
    ret = gpiod_i2c_transfer(I2C_BUS_NUM, address, reg_id, data, 6, 0);
    if (ret != 6) {
        printf("I2C read failed: %d\n", ret);
        // Attempt re-initialization up to 3 times
        for (int i = 0; i < 3; i++) {
            i2c_init();
            i2c_read(address, reg_id, data);
            if (ret == 6) {
                break;
            }
        }
        // If still fails, exit
        exit(EXIT_FAILURE);
    }
    return ret;
}

// Function to control the LED based on the threshold condition
void led_control(bool on) {
    if (on) {
        gpiod_set_value(gpios[0], 1); // Turn LED on
    } else {
        gpiod_set_value(gpios[0], 0); // Turn LED off
    }
}

// Function to perform cleanup
void cleanup(void) {
    // Close I2C handle
    gpiod_i2c_teardown(I2C_BUS_NUM);

    // Set LED GPIO low
    gpiod_set_value(gpios[0], 0);

    // Call library cleanup function
    gpiod_cleanup();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    // Perform clean shutdown
    cleanup();
    exit(EXIT_SUCCESS);
}

