    int x_rate = (data[X_RATE_REG] << 8) | data[X_RATE_REG + 1];
    int y_rate = (data[Y_RATE_REG] << 8) | data[Y_RATE_REG + 1];
    int z_rate = (data[Z_RATE_REG] << 8) | data[Z_RATE_REG + 1];

    // Format data for CSV log entry
    char csv_data[256];
    sprintf(csv_data, "%s,%d,%d,%d", timestamp_str, x_rate, y_rate, z_rate);
    write_to_log_file(timestamp_str, csv_data);
