#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <gpiod.h>
#include <libgpiod.h>

#define BUFFER_SIZE 64
#define THRESHOLD 200
#define SPI_SPEED 3900000
#define GPIO_SPI_CE GPIO_NUM_8
#define GPIO_WARNING_LED GPIO_NUM_17

// Structure to hold MPU-6050 data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    uint32_t timestamp;
} mpu6050_data;

// Circular buffer definition
typedef struct {
    mpu6050_data data[BUFFER_SIZE];
    size_t head;
    size_t tail;
} circular_buffer;

// Function prototypes
void setup_spi();
void setup_led();
void read_mpu6050_data(void);
void process_data(mpu6050_data *data);
void handle_interrupt(int signum);
void cleanup_resources();
void print_buffer(circular_buffer *buffer);

int main() {
    // Initialize circular buffer
    circular_buffer buffer;
    buffer.head = 0;
    buffer.tail = 0;

    // Setup SPI and LED
    setup_spi();
    setup_led();

    // Signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Main loop
    while (1) {
        // Read data from MPU-6050
        read_mpu6050_data();

        // Process data
        process_data(&buffer.data[buffer.tail]);

        // Check for threshold exceeded
        if (buffer.data[buffer.tail].x > THRESHOLD || buffer.data[buffer.tail].y > THRESHOLD || buffer.data[buffer.tail].z > THRESHOLD) {
            blink_led();
        }

        // Handle Ctrl+C
        if (buffer.head == buffer.tail) {
            break;
        }
    }

    // Clean up resources on exit
    cleanup_resources();

    // Print buffer if interrupted
    print_buffer(&buffer);

    return 0;
}

// SPI setup function
void setup_spi() {
    int spi_fd;
    struct spi_device *spi_dev;
    struct spi_message *msg;
    struct spi_transaction *tx;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Create SPI device
    spi_dev = spi_device_new_fd(spi_fd);
    if (!spi_dev) {
        perror("Failed to create SPI device");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up SPI parameters
    msg = spi_message_new();
    tx = spi_transaction_new();
    spi_message_add_tail(tx, msg);

    // Set speed
    spi_set_mode(spi_dev, SPI_MODE_0);
    spi_set_speed(spi_dev, SPI_SPEED);

    // Set CE pin
    gpiod_set_data_direction(GPIO_SPI_CE, GPIOD_OUT_INIT_LOW);
    gpiod_write(GPIO_SPI_CE, 1);

    // Start SPI transfer
    if (spi_transfer(msg) < 0) {
        perror("SPI transfer failed");
        spi_device_free(spi_dev);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Free SPI device
    spi_device_free(spi_dev);
    close(spi_fd);
}

// LED blinking function
void blink_led() {
    int on_duration = 500;
    int off_duration = 500;

    // Toggle LED state
    gpiod_set_value(GPIO_WARNING_LED, (gpiod_get_value(GPIO_WARNING_LED) == 0) ? 1 : 0);
    usleep(on_duration * 1000);
    gpiod_set_value(GPIO_WARNING_LED, (gpiod_get_value(GPIO_WARNING_LED) == 1) ? 0 : 1);
    usleep(off_duration * 1000);
}

// Read data from MPU-6050
void read_mpu6050_data() {
    circular_buffer_data data;
    int ret;

    // Read data from the sensor
    ret = spi_transfer(&data, sizeof(data));
    if (ret < 0) {
        printf("Error reading from MPU-6050\n");
        return;
    }

    // Check for invalid data
    if (data.timestamp == 0 || data.x == 0 || data.y == 0 || data.z == 0) {
        printf("Invalid data received from MPU-6050\n");
        return;
    }

    // Store data in circular buffer
    buffer.data[buffer.tail].x = data.x;
    buffer.data[buffer.tail].y = data.y;
    buffer.data[buffer.tail].z = data.z;
    buffer.data[buffer.tail].timestamp = data.timestamp;
    buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
}

// Process data
void process_data(mpu6050_data *data) {
    if (data->x > THRESHOLD || data->y > THRESHOLD || data->z > THRESHOLD) {
        blink_led();
    }
}

// Handle SIGINT
void handle_interrupt(int signum) {
    printf("SIGINT received, shutting down...\n");
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

// Cleanup resources
void cleanup_resources() {
    // Release GPIO resources
    gpiod_set_data_direction(GPIO_WARNING_LED, GPIOD_DATA_INPUT);
    gpiod_set_value(GPIO_WARNING_LED, 0);

    // Release SPI resources
    close(-1); // Closing the last open file descriptor
}

// Print circular buffer as CSV
void print_buffer(circular_buffer *buffer) {
    FILE *file;
    char csv[256];

    file = fopen("mpu6050_data.csv", "w");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    for (size_t i = 0; i < BUFFER_SIZE; i++) {
        if (buffer->head == i) {
            continue; // Skip empty slots
        }

        snprintf(csv, sizeof(csv), "%u,%d,%d,%d", buffer->data[i].timestamp, buffer->data[i].x, buffer->data[i].y, buffer->data[i].z);
        fprintf(file, "%s", csv);
        fprintf(file, "\n");
    }

    fclose(file);
    printf("MPU-6050 data saved to mpu6050_data.csv\n");
}

// SPI transfer function (helper)
int spi_transfer(struct spi_message *msg) {
    int ntransfers, status;

    ntransfers = spi_transfer(msg);
    if (ntransfers < 0) {
        return ntransfers;
    }

    status = 0;
    for (int i = 0; i < ntransfers; i++) {
        if (spi_message_get_status(msg, i) & SPI_MISO) {
            status = -1;
        }
    }

    return status;
}

