#include <signal.h>

#define SI1145_ADDR 0x29 // 8-bit address for Si1145
#define GPIO17 17 // BCM GPIO 17

// Constants for I2C operations
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_WRITE_BUFFER_SIZE 16
#define I2C_READ_BUFFER_SIZE 8

// Sensor commands and register addresses
#define SI1145_CMD_READ_REG 0x00
#define SI1145_REG_AMBIENT_LIGHT 0x01
#define SI1145_REG_PROXIMITY 0x02

// Function prototypes
void setup_i2c();
void read_sensors();
void handle_proximity_threshold_exceeded();
void handle_signal(int signum);
void cleanup();

int main() {
    // Initialize I2C
    setup_i2c();

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        read_sensors();
        usleep(100000); // Sleep for 100 ms
    }

    // Clean up
    cleanup();

    return 0;
}

// Function to setup I2C communication
void setup_i2c() {
    int i2c_fd;
    struct i2c_msg msg[2];

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Prepare I2C messages
    msg[0].addr = SI1145_ADDR;
    msg[0].len = sizeof(uint8_t); // Command byte
    msg[0].buf = (uint8_t *) &SI1145_CMD_READ_REG;

    msg[1].addr = SI1145_ADDR;
    msg[1].len = SI1145_REG_AMBIENT_LIGHT; // Register address
    msg[1].buf = (uint8_t *) NULL; // No data to read

    // Write command to read registers
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to write address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read ambient light value
    if (read(i2c_fd, msg[1].buf, msg[1].len) != msg[1].len) {
        perror("Failed to read ambient light");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read proximity value
    msg[0].buf = (uint8_t *) &SI1145_REG_PROXIMITY;
    msg[1].len = sizeof(uint16_t); // 16-bit value
    if (read(i2c_fd, msg[1].buf, msg[1].len) != msg[1].len) {
        perror("Failed to read proximity");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Close I2C file descriptor
    close(i2c_fd);
}

// Function to read sensor values
void read_sensors() {
    uint8_t ambient_light;
    uint16_t proximity;

    // Read ambient light
    if (ioctl(I2C_DEVICE, I2C_RDWR, &msg[0]) < 0) {
        perror("Failed to read ambient light");
        return;
    }
    ambient_light = msg[1].buf[0];

    // Read proximity
    if (ioctl(I2C_DEVICE, I2C_RDWR, &msg[0]) < 0) {
        perror("Failed to read proximity");
        return;
    }
    proximity = msg[1].buf[0] | (msg[1].buf[1] << 8);

    // Handle proximity threshold
    handle_proximity_threshold_exceeded(ambient_light, proximity);

    // Append log entry
    char log_entry[256];
    strftime(log_entry, sizeof(log_entry), "%F %T,", localtime(&time(NULL)));
    sprintf(log_entry + strlen("%F %T,"), ",AmbientLight:%04X,Proximity:%04X", ambient_light, proximity);
    FILE *log_file = fopen("biometric_log.txt", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s", log_entry);
    fclose(log_file);

    // Check GPIO17 state
    if (proximity > 100) {
        if (gpio_mode_set(GPIO17, GPIO_MODE_OUTPUT) < 0) {
            perror("Failed to set GPIO17 mode");
            return;
        }
        if (gpio_set(GPIO17) < 0) {
            perror("Failed to set GPIO17 high");
            gpio_mode_set(GPIO17, GPIO_MODE_INPUT); // Reset mode if setting fails
        }
    } else {
        if (gpio_set(GPIO17) < 0) {
            perror("Failed to set GPIO17 low");
            gpio_mode_set(GPIO17, GPIO_MODE_INPUT); // Reset mode if setting fails
        }
    }
}

// Function to handle proximity threshold exceeded
void handle_proximity_threshold_exceeded(uint8_t ambient_light, uint16_t proximity) {
    if (proximity > 100) {
        // Turn on presence LED
        gpio_set(GPIO17);
    } else {
        // Turn off presence LED
        gpio_mode_set(GPIO17, GPIO_MODE_INPUT); // Reset mode
    }
}

// Signal handler to perform cleanup on SIGINT or SIGTERM
void handle_signal(int signum) {
    // Close I2C file descriptor if open
    if (open(I2C_DEVICE, O_RDWR) != -1) {
        close(I2C_DEVICE);
    }

    // Close log file
    fclose(stderr);

    // Turn off presence LED
    if (gpio_set(GPIO17) < 0) {
        perror("Failed to turn off presence LED");
    } else {
        gpio_mode_set(GPIO17, GPIO_MODE_INPUT); // Reset mode
    }

    // Clean up any other resources if necessary
    cleanup();
}

// Function to perform final cleanup
void cleanup() {
    // Release resources if necessary
    // Example: close any other open files, free memory, etc.
}

