#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <stdint.h>
#include <gpiod.h>
#include <libgpiod/gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO8 8
#define CE0 0

#define ADXRS290_REG_X 0x01
#define ADXRS290_REG_Y 0x02

#define CPOL 0
#define CPHA 0

#define MAX_RETRIES 3

// Function prototypes
void setup_spi();
void setup_gpio();
void read_gyro_data(uint16_t *x, uint16_t *y);
void handle_interrupt(int signum);
void cleanup();

int main() {
    // Signal handler for SIGINT
    signal(SIGINT, handle_interrupt);

    // Attempt to open SPI device
    int spi_fd = -1;
    char err_str[100];
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) == -1) {
        sprintf(err_str, "Failed to open SPI device: %s", strerror(errno));
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Setup GPIO for CE0
    setup_gpio();

    // Main loop
    while (1) {
        // Read gyro data
        uint16_t x_rate, y_rate;
        read_gyro_data(&x_rate, &y_rate);

        // Write to CSV file
        char timestamp[23];
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%F %T", timeinfo);
        FILE *file = fopen("gyro_data.csv", "a+");
        if (!file) {
            perror("fopen");
            break; // Exit on file open failure
        }
        fprintf(file, "%s,%d,%d\n", timestamp, (int)x_rate, (int)y_rate);
        fclose(file);

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up on SIGINT
    cleanup();

    return 0;
}

// Function to setup SPI
void setup_spi() {
    int spi_config;
    struct spi_device *spi;

    // Open SPI device
    if ((spi = gpiod_spi_open(SPI_DEVICE, GPIOD_SPI_MODE_0, 1000000)) == NULL) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    spi_config = gpiod_spi_config(spi, CPOL, CPHA);
    if (spi_config < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        gpiod_spi_close(spi);
        exit(EXIT_FAILURE);
    }

    gpiod_spi_config(spi, spi_config);
}

// Function to setup GPIO for CE0
void setup_gpio() {
    int ret;

    // Set GPIO8 as CE0 output
    ret = gpiod_set_data_direction(GPIO8, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO8 direction: %s\n", gpiod_get_name(gpiod_get_device_by_index(0)));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_value(GPIO8, GPIOD_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO8 value: %s\n", gpiod_get_name(gpiod_get_device_by_index(0)));
        exit(EXIT_FAILURE);
    }
}

// Function to read gyro data
void read_gyro_data(uint16_t *x, uint16_t *y) {
    uint8_t cmd[2];
    cmd[0] = ADXRS290_REG_X | 0x80; // Set read bit
    cmd[1] = 0x00; // Dummy byte

    for (int i = 0; i < 3; i++) { // Retry up to 3 times
        int spi_transfer = gpiod_spi_transfer(spi, cmd, 2, NULL, 0);
        if (spi_transfer < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", gpiod_get_name(gpiod_get_device_by_index(0)));
            usleep(10000); // Wait before retrying
            continue;
        }

        // Read response
        uint8_t response = gpiod_spi_transfer(spi, NULL, 1, cmd, 1);
        if (response != 0x01) {
            fprintf(stderr, "Invalid response from gyro: 0x%02X (expected 0x01)\n", response);
            usleep(10000); // Wait before retrying
            continue;
        }

        *x = (uint16_t)response;
        *y = (uint16_t)gpiod_spi_transfer(spi, NULL, 1, cmd, 1); // Read Y-axis
    }

    // Clean up SPI if any error occurred
    if (spi_transfer < 0 || *x == 0 || *y == 0) {
        gpiod_spi_close(spi);
        exit(EXIT_FAILURE);
    }
}

// Signal handler for SIGINT
void handle_interrupt(int signum) {
    // Clean up SPI and file
    gpiod_spi_close(spi);
    fclose("gyro_data.csv");

    // Exit the program
    exit(EXIT_SUCCESS);
}

// Function to cleanup resources
void cleanup() {
    // Close the file
    fclose("gyro_data.csv");

    // Close SPI device
    gpiod_spi_close(spi);

    // Release GPIO
    gpiod_set_data_direction(GPIO8, GPIOD_DIR_INPUT);
    gpiod_set_value(GPIO8, GPIOD_LOW);
}

// Ensure proper compilation with -lgpiod
#define LIBGPIOD "-lgpiod"

// Compile command example:
// gcc -o gyro_reader gyro_reader.c -lgpiod

