#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>

#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define SPI_CLOCK_FREQ 1000000
#define CE_GPIO 8
#define SCLK_GPIO 11
#define MOSI_GPIO 10
#define MISO_GPIO 9
#define WARNING_LED_GPIO 17

#define ADXRS290_REG_ACCEL_XOUT_H 0x01
#define ADXRS290_REG_ACCEL_XOUT_L 0x02

struct gyroscope_data {
    uint16_t high;
    uint16_t low;
    struct timespec timestamp;
};

typedef struct {
    struct gyroscope_data data[BUFFER_SIZE];
    size_t head;
    pthread_mutex_t lock;
} GyroscopeBuffer;

void *gyroscope_thread(void *arg) {
    GyroscopeBuffer *buffer = (GyroscopeBuffer *)arg;
    uint8_t address = (ADXRS290_REG_ACCEL_XOUT_H << 7) | 0x00; // Set MSB for read
    uint8_t spi_transfer[2] = {address, 0};

    while (1) {
        pthread_mutex_lock(&buffer->lock);

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        uint16_t high, low;
        libgpiod_spi_transfer(SPI_CLOCK_FREQ, CE_GPIO, SCLK_GPIO, MOSI_GPIO, MISO_GPIO, spi_transfer, 2);

        high = libgpiod_spi_read(MISO_GPIO);
        low = libgpiod_spi_read(MISO_GPIO);

        buffer->data[buffer->head].high = high;
        buffer->data[buffer->head].low = low;
        buffer->data[buffer->head].timestamp = now;
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;

        pthread_mutex_unlock(&buffer->lock);

        if (high > THRESHOLD || low > THRESHOLD) {
            gpiod_set_value(WARNING_LED_GPIO, 1); // Turn on warning LED
        } else {
            gpiod_set_value(WARNING_LED_GPIO, 0); // Turn off warning LED
        }
    }

    return NULL;
}

int main() {
    int rc;
    struct gpiod_device *ce_gpio_dev;
    struct gpiod_device *spi_miso_dev;
    GyroscopeBuffer buffer;
    pthread_t gyroscope_thread_id;

    // Initialize GPIO for CE0
    rc = gpiod_open(&ce_gpio_dev, GPIO_NUM_8);
    if (rc != 0) {
        fprintf(stderr, "Error opening CE0 GPIO: %s\n", gpiod_error_string(rc));
        return EXIT_FAILURE;
    }
    gpiod_direction_output(ce_gpio_dev, 1); // Set CE0 to high

    // Initialize GPIO for MISO
    rc = gpiod_open(&spi_miso_dev, GPIO_NUM_9);
    if (rc != 0) {
        fprintf(stderr, "Error opening MISO GPIO: %s\n", gpiod_error_string(rc));
        gpiod_close(ce_gpio_dev);
        return EXIT_FAILURE;
    }

    // Initialize the gyroscope buffer
    buffer.head = 0;
    pthread_mutex_init(&buffer.lock, NULL);

    // Start the gyroscope thread
    rc = pthread_create(&gyroscope_thread_id, NULL, gyroscope_thread, &buffer);
    if (rc != 0) {
        fprintf(stderr, "Error creating gyroscope thread: %s\n", strerror(errno));
        gpiod_close(ce_gpio_dev);
        gpiod_close(spi_miso_dev);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Handle signals
        if (signal(SIGINT, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error ignoring SIGINT: %s\n", strerror(errno));
            break;
        }
        if (signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            fprintf(stderr, "Error ignoring SIGTERM: %s\n", strerror(errno));
            break;
        }

        // Do nothing here, the gyroscope thread handles everything

        // Wait for the gyroscope thread to exit
        pthread_join(gyroscope_thread_id, NULL);

        // Clean up
        gpiod_close(ce_gpio_dev);
        gpiod_close(spi_miso_dev);
        pthread_mutex_destroy(&buffer.lock);

        return EXIT_SUCCESS;
    }
}

