#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define TOTAL_LAMPS 3
#define PWM_FREQ_HZ 100
#define MAX_DUTY_CYCLE 255

// Function prototypes
void setup_gpiod();
void fade_lamp(int gpio, int duration);
void handle_signal(int signum);
void cleanup();

int main(int argc, char *argv[]) {
    // Check if the argument count is correct
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Duration in seconds
    int total_duration = atoi(argv[1]);

    // Initialize gpiod
    setup_gpiod();

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize variables
    int lamp_index = 0;
    int duration_per_lamp = total_duration / TOTAL_LAMPS;

    // Start fading the first lamp
    fade_lamp(GPIO_NUM_17, duration_per_lamp);

    // Continue fading the remaining lamps
    while (lamp_index < TOTAL_LAMPS) {
        fade_lamp(GPIO_NUM_18, duration_per_lamp);
        fade_lamp(GPIO_NUM_27, duration_per_lamp);
        lamp_index++;
    }

    // Clean up and exit
    cleanup();

    return EXIT_SUCCESS;
}

// Function to initialize gpiod
void setup_gpiod() {
    int error;

    // Initialize gpiod
    error = gpiod_init();
    if (error) {
        fprintf(stderr, "Failed to initialize gpiod: %s\n", gpiod_errstr(error));
        return;
    }

    // Set the PWM frequency for the GPIO pins
    for (int i = 0; i < TOTAL_LAMPS; i++) {
        int gpio = GPIO_NUM_17 + i;
        error = gpiod_pwm_config(gpio, PWM_FREQ_HZ);
        if (error) {
            fprintf(stderr, "Failed to configure PWM for GPIO %d: %s\n", gpio, gpiod_errstr(error));
            return;
        }
    }
}

// Function to fade a lamp
void fade_lamp(int gpio, int duration) {
    int duty_cycle = 255; // Start at full brightness

    // Fade the lamp
    for (int i = 0; i < duration * 1000; i++) {
        duty_cycle -= 1; // Decrease duty cycle by 1 each iteration

        // Set the duty cycle
        error = gpiod_pwm_set_data(gpio, duty_cycle);
        if (error) {
            fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d: %s\n", gpio, gpiod_errstr(error));
            return;
        }

        // Sleep for a short period to control the fade rate
        usleep(1000);
    }

    // Turn off the lamp
    duty_cycle = 0;
    error = gpiod_pwm_set_data(gpio, duty_cycle);
    if (error) {
        fprintf(stderr, "Failed to set PWM duty cycle to 0 for GPIO %d: %s\n", gpio, gpiod_errstr(error));
    }
}

// Signal handler to turn off all lamps and clean up
void handle_signal(int signum) {
    // Turn off all lamps
    for (int i = 0; i < TOTAL_LAMPS; i++) {
        int gpio = GPIO_NUM_17 + i;
        gpiod_pwm_set_data(gpio, 0);
    }

    // Clean up and exit
    cleanup();
    exit(EXIT_FAILURE);
}

// Function to clean up resources
void cleanup() {
    // Deinitialize gpiod
    gpiod_exit();
}

