// Function prototypes
void init_libgpiod();
void init_i2c();
void debounce_touch(uint8_t electrode);
void toggle_relay();
void cleanup();
void handle_signal(int signum);

int main() {
    srand(time(NULL));

    // Initialize libgpiod
    init_libgpiod();

    // Initialize I2C
    init_i2c();

    FILE *log_file = fopen("touch_relay.log", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    uint8_t electrode = 0;
    while (1) {
        // Read touch status from MPR121
        int ret = i2c_smbus_read_byte_data(TOUCH_CONTROLLER_ADDR, electrode);
        if (ret < 0) {
            fprintf(log_file, "Error reading from MPR121 at %s: %s\n",
                    ctime(&time(NULL)), strerror(errno));
            break;
        }

        // Debounce touch event
        debounce_touch(electrode);

        // Check if electrode 0 is touched
        if (is_touched(electrode)) {
            toggle_relay();
        }

        // Sleep for 10ms
        usleep(10000);
    }

    // Clean up
    cleanup();

    // Handle signals
    while (1) {
        handle_signal(SIGINT);
        handle_signal(SIGTERM);
    }

    return 0;
}

// Function to initialize libgpiod
void init_libgpiod() {
    int gpio17_fd = gpiod_open(GPIO17, GPIOD_OPEN_READ_WRITE);
    if (gpio17_fd < 0) {
        fprintf(log_file, "Failed to open GPIO %d: %s\n", GPIO17, strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(gpio17_fd, 0); // Set GPIO17 to LOW initially
}

// Function to initialize I2C
void init_i2c() {
    int i2c_fd = i2c_open(1, I2C_FLAG_NONE);
    if (i2c_fd < 0) {
        fprintf(log_file, "Failed to open I2C bus 1: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to debounce touch events
void debounce_touch(uint8_t electrode) {
    static uint32_t last_touch_time = 0;
    static bool touched = false;

    uint32_t now = time(NULL);
    if (now - last_touch_time >= 100000) { // 100ms debounce
        touched = true;
        last_touch_time = now;
    }

    if (touched) {
        touched = false;
        printf("Electrode %u touched\n", electrode);
    }
}

// Function to toggle the relay
void toggle_relay() {
    int ret = gpiod_write(gpio17_fd, 1); // Set GPIO17 to HIGH to toggle relay
    if (ret < 0) {
        fprintf(log_file, "Failed to write to GPIO %d: %s\n", GPIO17, strerror(errno));
    } else {
        fprintf(log_file, "Toggled relay at %s\n", ctime(&time(NULL)));
    }
}

// Function to cleanup resources
void cleanup() {
    gpiod_close(gpio17_fd);
    i2c_close(i2c_fd);
}

// Function to handle signals
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

// Helper function to check if electrode is touched
bool is_touched(uint8_t electrode) {
    // Implement logic based on MPR121 data to determine if electrode is touched
    // This is a placeholder; actual logic depends on the MPR121 data format
    return true; // For demonstration, assume electrode 0 is always touched
}

