#define BUZZER_GPIO 18
#define LED_GPIO 23
#define FLAME_SENSOR_GPIO 17

FILE *flame_log_file;
const char *flame_log_filename = "flame_log.txt";

volatile int flame_detected = 0;
unsigned long last_flame_time = 0;

void setup_gpios(void) {
    int error;

    // Initialize GPIO
    error = gpiod_init();
    if (error) {
        fprintf(stderr, "Error initializing GPIO: %d\n", error);
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 as input
    error = gpiod_direction_input(gpiod_get_index_from_name(FLAME_SENSOR_GPIO));
    if (error != 0) {
        fprintf(stderr, "Error setting GPIO %u as input: %d\n", FLAME_SENSOR_GPIO, error);
        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Set GPIO18 as output for buzzer
    error = gpiod_direction_output(gpiod_get_index_from_name(BUZZER_GPIO), 1);
    if (error != 0) {
        fprintf(stderr, "Error setting GPIO %u as output: %d\n", BUZZER_GPIO, error);
        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }

    // Set GPIO23 as output for LED
    error = gpiod_direction_output(gpiod_get_index_from_name(LED_GPIO), 0);
    if (error != 0) {
        fprintf(stderr, "Error setting GPIO %u as output: %d\n", LED_GPIO, error);
        gpiod_cleanup();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpios(void) {
    gpiodcleanup();
}

void handle_signal(int signum) {
    // Handle SIGINT and SIGTERM
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Signal caught, cleaning up...\n");
        cleanup_gpios();
        fclose(flame_log_file);
        exit(EXIT_SUCCESS);
    }
}

void flame_condition_triggered() {
    if (flame_detected) {
        time_t now = time(NULL);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(flame_log_file, "Flame Detected: %s\n", timestamp);
        printf("Flame Detected: %s\n", timestamp);

        // Activate buzzer and LED
        gpiod_write(gpiod_get_index_from_name(BUZZER_GPIO), 1);
        gpiod_write(gpiod_get_index_from_name(LED_GPIO), 1);

        flame_detected = 1;
    }
}

void check_flame_sensor() {
    int value;

    // Read flame sensor
    value = gpiod_read(gpiod_get_index_from_name(FLAME_SENSOR_GPIO));
    if (value == 0) {
        if (flame_detected == 0) {
            flame_condition_triggered();
            flame_detected = 1;
        } else {
            // Three consecutive LOW readings
            last_flame_time = time(NULL);
        }
    } else {
        // Not LOW, reset counter
        flame_detected = 0;
    }

    usleep(50000); // Wait 50 ms
}

int main(void) {
    setup_gpios();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    flame_log_file = fopen(flame_log_filename, "a+");
    if (flame_log_file == NULL) {
        perror("Failed to open flame_log.txt");
        exit(EXIT_FAILURE);
    }

    while (1) {
        check_flame_sensor();
        usleep(100000); // Wait 100 ms
    }

    fclose(flame_log_file);
    return 0;
}

