    // Initialize GPIO and L298N
    if (init_l298n() != 0) {
        fprintf(stderr, "Error initializing L298N driver.\n");
        return 1;
    }

    // Signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    FILE *log_file = fopen(LOG_FILE_PATH, "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Simulate tilt error and distance
        float tilt_error = rand() % 20 - 10; // Random tilt error between -10 and 10 degrees
        float distance = rand() % 400 + 2; // Random distance between 2 and 400 cm

        // Apply obstacle avoidance if too close to an obstacle
        if (distance < 20) {
            obstacle_avoidance(distance);
        }

        // PID control loop
        float motor_a_speed, motor_b_speed;
        pid_control(tilt_error, distance, motor_a_speed, motor_b_speed);

