        write_to_log_file(
            asctime(&time), // Timestamp
            tilt_error,     // Tilt error
            distance,       // Distance
            motor_a_speed,  // Motor A speed
            motor_b_speed   // Motor B speed
        );

        // Sleep to maintain the loop interval
        usleep(PID_LOOP_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    cleanup();

    return 0;
}

// Function to initialize L298N driver
int init_l298n() {
    int ena_fd, enb_fd;
    int rc;

    // Open ENA and ENB GPIO pins for PWM control
    ena_fd = open(GPIO24, O_WRONLY);
    enb_fd = open(GPIO25, O_WRONLY);

    if (ena_fd == -1 || enb_fd == -1) {
        fprintf(stderr, "Error opening GPIO pins for L298N.\n");
        return 1;
    }

    // Initialize L298N driver
    rc = gpiod_open(ENA_GPIO, GPIOD_OPEN_MODE_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error opening L298N GPIO pin ENA.\n");
        close(ena_fd);
        close(enb_fd);
        return 1;
    }

    rc = gpiod_open(ENB_GPIO, GPIOD_OPEN_MODE_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error opening L298N GPIO pin ENB.\n");
        gpiod_close(ENA_GPIO);
        close(ena_fd);
        close(enb_fd);
        return 1;
    }

    // Set ENA and ENB high to enable PWM control
    if (write(ena_fd, &GPIO_ACTIVE_HIGH, 1) != 1 || write(enb_fd, &GPIO_ACTIVE_HIGH, 1) != 1) {
        fprintf(stderr, "Error setting ENA and ENB high.\n");
        gpiod_close(ENA_GPIO);
        gpiod_close(ENB_GPIO);
        close(ena_fd);
        close(enb_fd);
        return 1;
    }

    return 0;
}

