    // Example PID implementation
    float output_a = 0, output_b = 0;

    // Calculate motor speeds based on tilt error and distance
    // This is a simplified example; real PID tuning would be required
    motor_a_speed = (tilt_error * KP + distance * KD) / MOTOR_SPEED_LIMIT;
    motor_b_speed = (tilt_error * KP - distance * KD) / MOTOR_SPEED_LIMIT;

    // Clamp motor speeds to ±255
    if (motor_a_speed > MOTOR_SPEED_LIMIT) {
        motor_a_speed = MOTOR_SPEED_LIMIT;
    } else if (motor_a_speed < -MOTOR_SPEED_LIMIT) {
        motor_a_speed = -MOTOR_SPEED_LIMIT;
    }

    if (motor_b_speed > MOTOR_SPEED_LIMIT) {
        motor_b_speed = MOTOR_SPEED_LIMIT;
    } else if (motor_b_speed < -MOTOR_SPEED_LIMIT) {
        motor_b_speed = -MOTOR_SPEED_LIMIT;
    }
}

// Function for obstacle avoidance
void obstacle_avoidance(float distance) {
    // Reverse both motors at 50% speed if distance is less than 20 cm
    motor_a_speed = -127; // 50% speed
    motor_b_speed = -127; // 50% speed
}

// Function to write to log file
void write_to_log_file(const char *timestamp, float tilt_error, float distance, float motor_a_speed, float motor_b_speed) {
    fprintf(log_file, "%s, %f, %f, %f, %f\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
}

// Function to clean up and close resources
void cleanup() {
    // Close log file
    fclose(log_file);

    // Close GPIO pins
    close(ena_fd);
    close(enb_fd);

    // Close L298N GPIO
    gpiod_close(ENA_GPIO);
    gpiod_close(ENB_GPIO);
}

