#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define TOUCH_GPIO 4 // GPIO 4 for TTP223 sensor input
#define RELAY_GPIO 17 // GPIO 17 for relay output
#define DEBOUNCE_MS 50 // Debounce delay in milliseconds

// Function prototypes
void setup_gpios(void);
void handle_touch(void);
void cleanup(void);
void signal_handler(int signum);

int main(void) {
    // Initialize GPIO
    setup_gpios();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Wait for touch
        handle_touch();
        usleep(DEBOUNCE_MS * 1000); // Debounce delay
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to initialize GPIO
void setup_gpios(void) {
    // Check if GPIO driver is initialized
    if (gpiod_get_version() == NULL) {
        fprintf(stderr, "Error: GPIO driver not initialized.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    if (gpiod_direction_input(TOUCH_GPIO) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO %u as input.\n", TOUCH_GPIO);
        exit(EXIT_FAILURE);
    }

    if (gpiod_direction_output(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO %u as output.\n", RELAY_GPIO);
        exit(EXIT_FAILURE);
    }
}

// Function to handle touch detection
void handle_touch(void) {
    // Read GPIO 4 (TTP223 sensor input)
    int touch_detected = gpiod_read(TOUCH_GPIO);

    // Check if touch detected and debounce delay has passed
    if (touch_detected && (time(NULL) - last_touch_time) >= (DEBOUNCE_MS * 1000)) {
        // Toggle relay output
        int relay_state = !gpiod_get_value(RELAY_GPIO);

        // Set relay state
        if (gpiod_write(RELAY_GPIO, relay_state) != 0) {
            fprintf(stderr, "Error: Failed to set relay state.\n");
        } else {
            printf("Relay toggled.\n");
        }

        // Update last touch time
        last_touch_time = time(NULL);
    }

    // Release resources on abnormal exit
    cleanup();
}

// Function to cleanup GPIO resources
void cleanup(void) {
    // Release GPIO pins
    gpiod_release(TOUCH_GPIO);
    gpiod_release(RELAY_GPIO);

    // Reset signal handlers
    signal(SIGINT, SIG_DFL);
