#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define ALSA_AVAILABLE
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define CHANNELS 1
#define BIT_DEPTH 16
#define RGB_PIN_RED 17
#define RGB_PIN_GREEN 18
#define RGB_PIN_BLUE 27
#define SENSITIVITY_DEFAULT 1.0
#define SENSITIVITY_SCALE_FACTOR 100.0

volatile sig_atomic_t is_sigint = 0;
volatile sig_atomic_t is_sigterm = 0;

void cleanup_and_exit(int sig) {
    gpiod_free_handle(gpiod_get_default_handle());
    alsa_card_free(alsa_get_default_card());
    alsa_pcm_free(alsa_get_default_pcm_handle());
    free((void*)malloc(SAMPLE_RATE * PERIOD_SIZE * CHANNELS * BIT_DEPTH / 8));
    exit(sig);
}

void handle_signal(int signum) {
    is_sigint = signum == SIGINT;
    is_sigterm = signum == SIGTERM;
}

int main(int argc, char **argv) {
    int fd;
    struct gpiod_dir *gpiod_dir;
    struct gpiod_cdev *rgb_cdev;
    uint8_t *buffer;
    int red_pin, green_pin, blue_pin;
    int sensitivity = SENSITIVITY_DEFAULT;

    if (argc > 1) {
        sensitivity = atof(argv[1]) * SENSITIVITY_SCALE_FACTOR;
    }

    if (!gpiod_is_valid()) {
        fprintf(stderr, "Error: GPIOD not available.\n");
        return EXIT_FAILURE;
    }

    gpiod_dir = gpiod_get_dir(gpiod_get_default_handle());
    if (!gpiod_dir) {
        fprintf(stderr, "Error: Failed to get GPIOD directory.\n");
        return EXIT_FAILURE;
    }

    rgb_cdev = gpiod_find_cdev(gpiod_dir, RGB_PIN_RED, GPIOD_DIR_INPUT);
    if (!rgb_cdev) {
        fprintf(stderr, "Error: Could not find GPIO pins for RGB.\n");
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    red_pin = RGB_PIN_RED;
    green_pin = RGB_PIN_GREEN;
    blue_pin = RGB_PIN_BLUE;

    fd = open("/dev/snd/pcmC0D0p", O_RDONLY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error: Could not open ALSA device.\n");
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    alsa_card_t *alsa_card = alsa_card_new(NULL);
    if (!alsa_card) {
        close(fd);
        fprintf(stderr, "Error: Could not initialize ALSA card.\n");
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    alsa_pcm_t *alsa_pcm = alsa_pcm_new(alsa_card, "default", 0, CHANNELS, SAMPLE_RATE, PERIOD_SIZE, ALLOC_NORMAL);
    if (!alsa_pcm) {
        alsa_card_free(alsa_card);
        close(fd);
        fprintf(stderr, "Error: Could not initialize ALSA PCM.\n");
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    buffer = malloc(SAMPLE_RATE * PERIOD_SIZE * CHANNELS * BIT_DEPTH / 8);
    if (!buffer) {
        alsa_pcm_free(alsa_pcm);
        alsa_card_free(alsa_card);
        close(fd);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    alsa_pcm_prepare(alsa_pcm);
    if (alsa_pcm_status(alsa_pcm) == -EPIPE) {
        fprintf(stderr, "Error: ALSA PCM overrun, resuming.\n");
        alsa_pcm_resume(alsa_pcm);
    } else if (alsa_pcm_status(alsa_pcm) == -ESTRPIPE) {
        fprintf(stderr, "Error: ALSA PCM suspended, resuming.\n");
        alsa_pcm_resume(alsa_pcm);
    } else {
        fprintf(stderr, "Error: ALSA PCM preparation failed.\n");
        free(buffer);
        alsa_pcm_free(alsa_pcm);
        alsa_card_free(alsa_card);
        close(fd);
        gpiod_put_dir(gpiod_dir);
        return EXIT_FAILURE;
    }

    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    while (!is_sigint && !is_sigterm) {
        int samples_read = snd_pcm_readi(alsa_pcm, buffer, PERIOD_SIZE * CHANNELS);
        if (samples_read < 0) {
            fprintf(stderr, "Error: ALSA PCM read error.\n");
            alsa_pcm_free(alsa_pcm);
            alsa_card_free(alsa_card);
            close(fd);
            gpiod_put_dir(gpiod_dir);
            cleanup_and_exit(EXIT_FAILURE);
        }

        // Compute RMS amplitude
        float rms = 0.0;
        for (int i = 0; i < samples_read; ++i) {
            rms += (float)buffer[i] * buffer[i];
        }
        rms = sqrt(rms / samples_read);

        // Map RMS to LED color
        uint8_t red = (uint8_t)(255 * (rms * sensitivity));
        uint8_t green = (uint8_t)(255 * (rms * sensitivity));
        uint8_t blue = (uint8_t)(255 * (rms * sensitivity));

        // Update GPIO pins
        gpiod_set_value(gpiod_dir, rgb_cdev, red_pin, red);
        gpiod_set_value(gpiod_dir, rgb_cdev, green_pin, green);
        gpiod_set_value(gpiod_dir, rgb_cdev, blue_pin, blue);

        usleep(10000); // 10ms delay
    }

    // Clean up on signal
    if (is_sigint) {
        fprintf(stderr, "Interrupted: Cleaning up...\n");
        alsa_pcm_free(alsa_pcm);
        alsa_card_free(alsa_card);
        close(fd);
        free(buffer);
        gpiod_put_dir(gpiod_dir);
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (is_sigterm) {
        fprintf(stderr, "Terminated: Cleaning up...\n");
        alsa_pcm_free(alsa_pcm);
        alsa_card_free(alsa_card);
        close(fd);
        free(buffer);
        gpiod_put_dir(gpiod_dir);
        cleanup_and_exit(EXIT_FAILURE);
    }

    return EXIT_SUCCESS;
}

