#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define TCS34725_ADDR 0x20
#define TCS34725_REG_R 0x00
#define TCS34725_REG_G 0x01
#define TCS34725_REG_B 0x02
#define TCS34725_REG_Y 0x03

#define FILE_NAME "color_data.csv"
#define CSV_HEADER "timestamp,C,R,G,B"
#define INTEGRATION_TIME_MS 154
#define SAMPLE_INTERVAL_MS 500

// Function prototypes
void handle_signal(int signum);
void i2c_transaction(gpiod_i2c_handle_t *handle, uint8_t reg, uint8_t *data, size_t len);
void read_sensor(gpiod_i2c_handle_t *handle);
void write_to_csv(gpiod_i2c_handle_t *handle, uint8_t r, uint8_t g, uint8_t b);
void cleanup();

int main() {
    // Initialize GPIO I2C
    gpiod_i2c_handle_t *i2c_handle = gpiod_i2c_open(GPIOD_I2C_1, GPIOD_DIR_INPUT_OUTPUT);
    if (i2c_handle == NULL) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open CSV file for appending
    int csv_file = open(FILE_NAME, O_APPEND | O_WRONLY, S_IRUSR | S_IWUSR);
    if (csv_file == -1) {
        fprintf(stderr, "Failed to open CSV file %s for writing\n", FILE_NAME);
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
    if (fwrite(CSV_HEADER, sizeof(CSV_HEADER), 1, csv_file) != 1) {
        fprintf(stderr, "Failed to write header to CSV file\n");
        close(csv_file);
        gpiod_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read sensor
        read_sensor(i2c_handle);

        // Sample and write to CSV
        uint8_t r, g, b;
        if (i2c_transaction(i2c_handle, TCS34725_REG_R, &r, sizeof(r)) ||
            i2c_transaction(i2c_handle, TCS34725_REG_G, &g, sizeof(g)) ||
            i2c_transaction(i2c_handle, TCS34725_REG_B, &b, sizeof(b))) {
            fprintf(stderr, "Error reading sensor values\n");
            r = 0; g = 0; b = 0;
        }
        write_to_csv(i2c_handle, r, g, b);

        // Sleep for 500ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    cleanup();

    // Close CSV file and I2C handle
    close(csv_file);
    gpiod_i2c_close(i2c_handle);

    return EXIT_SUCCESS;
}

// Function to handle signals
void handle_signal(int signum) {
    // Clean up on SIGINT or SIGTERM
    cleanup();
    exit(EXIT_FAILURE);
}

// Function to perform I2C transaction
void i2c_transaction(gpiod_i2c_handle_t *handle, uint8_t reg, uint8_t *data, size_t len) {
    int ret;
    ret = gpiod_i2c_transfer(handle, reg, data, len, 0, 0);
    if (ret != len) {
        fprintf(stderr, "I2C transfer error\n");
    }
}

// Function to read sensor values
void read_sensor(gpiod_i2c_handle_t *handle) {
    uint8_t r_data[1], g_data[1], b_data[1], y_data[1];
    i2c_transaction(handle, TCS34725_REG_R, r_data, sizeof(r_data));
    i2c_transaction(handle, TCS34725_REG_G, g_data, sizeof(g_data));
    i2c_transaction(handle, TCS34725_REG_B, b_data, sizeof(b_data));
    i2c_transaction(handle, TCS34725_REG_Y, y_data, sizeof(y_data));

    uint8_t r = r_data[0];
    uint8_t g = g_data[0];
    uint8_t b = b_data[0];
    uint8_t y = y_data[0];

    // Log sensor values to CSV
    write_to_csv(handle, r, g, b);
}

// Function to write sensor values to CSV file
void write_to_csv(gpiod_i2c_handle_t *handle, uint8_t r, uint8_t g, uint8_t b) {
    time_t timestamp;
    time(&timestamp);
    char csv_line[100];

    // Format timestamp and sensor values into CSV line
    sprintf(csv_line, "%ld,%d,%d,%d", timestamp, r, g, b);

    // Write to CSV file
    if (fwrite(csv_line, sizeof(csv_line), 1, csv_file) != 1) {
        fprintf(stderr, "Error writing to CSV file\n");
    }
}

// Cleanup function to close resources
void cleanup() {
    // Close I2C handle
    gpiod_i2c_close(i2c_handle);

    // Close CSV file
    close(csv_file);
}

