    struct gpiod_device *dev;
    int ret;

    dev = gpiod_get_device(GPIO_NUM);
    if (dev == NULL) {
        fprintf(stderr, "Failed to get GPIO device\n");
        return;
    }

    ret = gpiod_direction_input(dev);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", GPIO_NUM);
        gpiod_device_put(dev);
        return;
    }

    // Polling for motion detection
    while (1) {
        int value = gpiod_read(dev, GPIO_NUM);
        if (value == 0) {
            motion_detected = true;
            usleep(DEBOUNCE_MS * 1000); // Debounce
