#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS_NUM 1
#define MPU6050_ADDRESS 0x68
#define MAX_RETRIES 3

// Structure for MPU-6050 register access
typedef struct {
    uint8_t reg;
    uint8_t value;
} mpu6050_reg_t;

// Function prototypes
void handle_signal(int signum);
void mpu6050_init(void);
void mpu6050_read_accel_gyro(mpu6050_reg_t *reg, uint8_t *data, size_t len);
void write_to_csv(const char *data, const char *filename);
void cleanup(void);

int main(void) {
    // Signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize MPU-6050
    mpu6050_init();

    // File for logging data
    char filename[100] = "gyro_log.csv";
    FILE *file = fopen(filename, "a+");
    if (file == NULL) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Get current time with millisecond precision
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint64_t timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        // Read data from MPU-6050
        mpu6050_reg_t reg = {0x3B, 0}; // X-axis gyroscope register
        uint8_t data[2] = {0};
        if (mpu6050_read_accel_gyro(&reg, data, sizeof(data)) < 0) {
            // Handle I2C read failure
            if (mpu6050_init() < 0) {
                fprintf(stderr, "Failed to re-initialize MPU-6050 after %d attempts.\n", MAX_RETRIES);
                continue;
            }
            // Retry reading
            mpu6050_read_accel_gyro(&reg, data, sizeof(data));
        }

        // Convert raw data to degrees per second
        float x_degps = (float)data[0] * 131.0 / 2048.0;

        // Write to CSV file
        write_to_csv((const char *)(&timestamp), (const char *)(&x_degps), NULL);

        // Sleep for 10ms
        usleep(10000);
    }

    // Cleanup on SIGINT/SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close file and release resources
    fclose(file);
    cleanup();

    return 0;
}

// Signal handler function
