void mpu6050_init(void) {
    struct gp_i2c_dev *i2c_dev;
    int ret;

    // Open I2C bus 1 with AD0 low
    ret = gp_i2c_open(I2C_BUS_NUM, GPIOD_I2C_FLAG_AD0_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gp_i2c_err2str(ret));
        return;
    }

    // Write to MPU-6050 to wake it up
    uint8_t wake_up_cmd[] = {0x6B, 0x00};
    ret = gp_i2c_transfer(i2c_dev, wake_up_cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to wake up MPU-6050: %s\n", gp_i2c_err2str(ret));
        gp_i2c_close(i2c_dev);
        return;
    }

    // Configure the sensor
    uint8_t config_cmd[] = {0x6B, 0x01, 0x00, 0x00, 0x00, 0x00};
    ret = gp_i2c_transfer(i2c_dev, config_cmd, 6);
    if (ret != 6) {
        fprintf(stderr, "Failed to configure MPU-6050: %s\n", gp_i2c_err2str(ret));
        gp_i2c_close(i2c_dev);
        return;
    }

    gp_i2c_close(i2c_dev);
}

