    int ret = gp_i2c_transfer(i2c_dev, read_cmd, 2, data, len, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read from MPU-6050: %s\n", gp_i2c_err2str(ret));
        return;
    }
}

