#define RELAY_ZONE_1 4
#define RELAY_ZONE_2 17
#define RELAY_ZONE_3 27
#define RELAY_ZONE_4 22

// GPIO context
gpiod_context *gpioc;

// Signal handler for SIGINT
void signal_handler(int signum) {
    // Deactivate all relays
    for (int i = 0; i < 4; ++i) {
        gpiod_set_data_direction(gpioc, RELAY_ZONE_i, GPIOD_DIR_OUT_INIT_LOW);
        gpiod_write(gpioc, RELAY_ZONE_i, 1); // HIGH
    }

    // Close the log file
    fclose(logfile);

    // Release the GPIO context
    gpiod_context_free(gpioc);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO driver
    gpioc = gpiod_get_context();
    if (gpioc == NULL) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        return EXIT_FAILURE;
    }

    // Open the log file
    FILE *logfile = fopen("irrigation_log.txt", "a+");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_context_free(gpioc);
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    // SIGINT signal handler registration
    signal(SIGINT, signal_handler);

    while (1) {
        // Simulate moisture sensor reading
        int moisture = rand() % 100 + 30; // Random value between 30 and 130

        // Check moisture level
        if (moisture < 30) {
            // Dry soil, activate corresponding relay
            for (int i = 0; i < 4; ++i) {
                if (i == RELAY_ZONE_1) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_1, GPIOD_DIR_OUT_INIT_LOW);
                    gpiod_write(gpioc, RELAY_ZONE_1, 0); // LOW
                } else if (i == RELAY_ZONE_2) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_2, GPIOD_DIR_OUT_INIT_LOW);
                    gpiod_write(gpioc, RELAY_ZONE_2, 0); // LOW
                } else if (i == RELAY_ZONE_3) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_3, GPIOD_DIR_OUT_INIT_LOW);
                    gpiod_write(gpioc, RELAY_ZONE_3, 0); // LOW
                } else if (i == RELAY_ZONE_4) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_4, GPIOD_DIR_OUT_INIT_LOW);
                    gpiod_write(gpioc, RELAY_ZONE_4, 0); // LOW
                }
            }

            // Append to log file
            char buffer[256];
            sprintf(buffer, "Moisture: %d, Relay States: %d %d %d %d, Time: %s\n",
                    moisture, (gpiod_get_value(gpioc, RELAY_ZONE_1) == 0), // Relay 1
                    (gpiod_get_value(gpioc, RELAY_ZONE_2) == 0), // Relay 2
                    (gpiod_get_value(gpioc, RELAY_ZONE_3) == 0), // Relay 3
                    (gpiod_get_value(gpioc, RELAY_ZONE_4) == 0), // Relay 4
                    ctime(&time(NULL)));
            fwrite(buffer, sizeof(buffer), 1, logfile);
        } else {
            // Wet soil, deactivate corresponding relay
            for (int i = 0; i < 4; ++i) {
                if (i == RELAY_ZONE_1) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_1, GPIOD_DIR_OUT_INIT_HIGH);
                    gpiod_write(gpioc, RELAY_ZONE_1, 1); // HIGH
                } else if (i == RELAY_ZONE_2) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_2, GPIOD_DIR_OUT_INIT_HIGH);
                    gpiod_write(gpioc, RELAY_ZONE_2, 1); // HIGH
                } else if (i == RELAY_ZONE_3) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_3, GPIOD_DIR_OUT_INIT_HIGH);
                    gpiod_write(gpioc, RELAY_ZONE_3, 1); // HIGH
                } else if (i == RELAY_ZONE_4) {
                    gpiod_set_data_direction(gpioc, RELAY_ZONE_4, GPIOD_DIR_OUT_INIT_HIGH);
                    gpiod_write(gpioc, RELAY_ZONE_4, 1); // HIGH
                }
            }

            // Append to log file
            sprintf(buffer, "Moisture: %d, Relay States: %d %d %d %d, Time: %s\n",
                    moisture, (gpiod_get_value(gpioc, RELAY_ZONE_1) == 1), // Relay 1
                    (gpiod_get_value(gpioc, RELAY_ZONE_2) == 1), // Relay 2
                    (gpiod_get_value(gpioc, RELAY_ZONE_3) == 1), // Relay 3
                    (gpiod_get_value(gpioc, RELAY_ZONE_4) == 1), // Relay 4
                    ctime(&time(NULL)));
            fwrite(buffer, sizeof(buffer), 1, logfile);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the log file on exit
    fclose(logfile);

    // Release the GPIO context
    gpiod_context_free(gpioc);

    return EXIT_SUCCESS;
}

