    // It should lock the mutex and call the appropriate callback functions
    pthread_mutex_lock(&echo_mutex);
    if (gpiod_cdg_has_pending_events(trig_dev)) {
        gpiod_cdg_event_t event;
        while (gpiod_cdg_event_get(trig_dev, &event)) {
