    teardown_gpios(dev);

    // Wait for the interrupt thread to finish
    pthread_join(thd, NULL);

    // Close log file and free resources
    fclose(log_file);
    gpiod_device_unref(dev);

    return 0;
}

// Interrupt handler function
void *interrupt_handler(void *arg) {
    // This function is called by the kernel when interrupts occur
    // It should lock the mutex and call the appropriate callback functions
    pthread_mutex_lock(&echo_mutex);
    if (gpiod_cdg_has_pending_events(trig_dev)) {
        gpiod_cdg_event_t event;
        while (gpiod_cdg_event_get(trig_dev, &event)) {
            if (event.type == GPIOD_CDG_EVENT_RISING) {
                rising_edge_interrupt(event.cdg, NULL);
            }
        }
    }
    pthread_mutex_unlock(&echo_mutex);
    return NULL;
}
