#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define LIS3DH_ADDR 0x1D
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define BUZZER_GPIO 17

// Constants for I2C control
#define I2C_SLAVE 0x7

// Function prototypes
void setup_i2c();
void setup_lis3dh();
void read_acceleration();
void handle_free_fall();
void handle_impact();
void cleanup();
void sigint_handler(int signum);

int main(int argc, char **argv) {
    int i2c_fd;
    int lis3dh_fd;
    int free_fall_detected = 0;
    int impact_detected = 0;
    int buzzer_state = 0;

    // Check command line arguments for override thresholds
    if (argc > 1) {
        if (strcmp(argv[1], "--free-fall-threshold") == 0) {
            FREE_FALL_THRESHOLD = atof(argv[2]);
        } else if (strcmp(argv[1], "--impact-threshold") == 0) {
            IMPACT_THRESHOLD = atof(argv[2]);
        }
    }

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize LIS3DH
    if ((lis3dh_fd = open_lis3dh(i2c_fd, LIS3DH_ADDR)) < 0) {
        perror("Failed to open LIS3DH");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        read_acceleration();
        if (free_fall_detected) {
            handle_free_fall();
            free_fall_detected = 0;
        }
        if (impact_detected) {
            handle_impact();
            impact_detected = 0;
        }
    }

    // Clean up on SIGINT
    cleanup();

    return 0;
}

// Function to setup I2C
void setup_i2c() {
    struct i2c_master_config i2c_config;
    i2c_config.speed = I2C_SPEED_100K;
    i2c_config.address_format = I2C_ADDR_7BIT;

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to setup LIS3DH
void setup_lis3dh() {
    if (lis3dh_open(lis3dh_fd, LIS3DH_ADDRESS, LIS3DH_RATE_800HZ) < 0) {
        perror("Failed to open LIS3DH");
        close(lis3dh_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

// Function to read acceleration data from LIS3DH
void read_acceleration() {
    uint8_t data[6];
    int16_t x, y, z;

    if (lis3dh_read(lis3dh_fd, LIS3DH_REG_ACCEL_XOUT_H, &data[0]) < 0) {
        perror("Failed to read LIS3DH");
        return;
    }

    x = (int16_t)data[0] << 8 | (int16_t)data[1];
    if (lis3dh_read(lis3dh_fd, LIS3DH_REG_ACCEL_YOUT_H, &data[2]) < 0) {
        perror("Failed to read LIS3DH");
        return;
    }
    y = (int16_t)data[2] << 8 | (int16_t)data[3];
    if (lis3dh_read(lis3dh_fd, LIS3DH_REG_ACCEL_ZOUT_H, &data[4]) < 0) {
        perror("Failed to read LIS3DH");
        return;
    }
    z = (int16_t)data[4] << 8 | (int16_t)data[5];

    // Calculate acceleration magnitude
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude < FREE_FALL_THRESHOLD) {
        free_fall_detected = 1;
    } else if (magnitude > IMPACT_THRESHOLD) {
        impact_detected = 1;
    }
}

// Function to handle free fall
void handle_free_fall() {
    if (!buzzer_state) {
        if (gpiod_open(BUZZER_GPIO, GPIOD_OUT_HIGH) < 0) {
            perror("Failed to open GPIO for buzzer");
            return;
        }
        gpiod_write(BUZZER_GPIO, 1); // Activate buzzer
        sleep(1); // Keep buzzer on for 1 second
        gpiod_write(BUZZER_GPIO, 0); // Deactivate buzzer
        gpiod_close(BUZZER_GPIO);
        free_fall_detected = 0;
    }
}

// Function to handle impact
void handle_impact() {
    // No specific action for impact other than logging
    printf("Impact detected\n");
    impact_detected = 0;
}

// Function to cleanup resources
void cleanup() {
    if (lis3dh_fd > 0) {
        lis3dh_close(lis3dh_fd);
        lis3dh_fd = -1;
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handler for SIGINT
void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

