#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_NUM_IN1_M1 GPIO_NUM_4
#define GPIO_NUM_IN2_M1 GPIO_NUM_17
#define GPIO_NUM_IN3_M1 GPIO_NUM_27
#define GPIO_NUM_IN4_M1 GPIO_NUM_22

#define GPIO_NUM_IN1_M2 GPIO_NUM_5
#define GPIO_NUM_IN2_M2 GPIO_NUM_6
#define GPIO_NUM_IN3_M2 GPIO_NUM_13
#define GPIO_NUM_IN4_M2 GPIO_NUM_19

#define STEP_DELAY_US 1000
#define STEPS_PER_REVOLUTION 2048
#define GEAR_RATIO 64

volatile sig_atomic_t should_stop = 0;

void sigint_handler(int signum) {
    should_stop = 1;
}

int main() {
    // Initialize GPIO
    int rc;
    struct gpio_desc *in1_m1 = gpiod_get_desc(GPIO_NUM_IN1_M1);
    struct gpio_desc *in2_m1 = gpiod_get_desc(GPIO_NUM_IN2_M1);
    struct gpio_desc *in3_m1 = gpiod_get_desc(GPIO_NUM_IN3_M1);
    struct gpio_desc *in4_m1 = gpiod_get_desc(GPIO_NUM_IN4_M1);

    int in1_m2 = gpiod_get_desc(GPIO_NUM_IN1_M2);
    int in2_m2 = gpiod_get_desc(GPIO_NUM_IN2_M2);
    int in3_m2 = gpiod_get_desc(GPIO_NUM_IN3_M2);
    int in4_m2 = gpiod_get_desc(GPIO_NUM_IN4_M2);

    if ((rc = gpiod_direction_output(in1_m1, 1)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN1 for Motor 1\n");
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in2_m1, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN2 for Motor 1\n");
        gpiod_set_value(in1_m1, 0);
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in3_m1, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN3 for Motor 1\n");
        gpiod_set_value(in2_m1, 0);
        gpiod_set_value(in3_m1, 0);
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in4_m1, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN4 for Motor 1\n");
        gpiod_set_value(in1_m1, 0);
        gpiod_set_value(in2_m1, 0);
        gpiod_set_value(in3_m1, 0);
        gpiod_set_value(in4_m1, 0);
        return EXIT_FAILURE;
    }

    // Repeat similar steps for Motor 2

    if ((rc = gpiod_direction_output(in1_m2, 1)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN1 for Motor 2\n");
        gpiod_set_value(in1_m1, 0);
        gpiod_set_value(in2_m1, 0);
        gpiod_set_value(in3_m1, 0);
        gpiod_set_value(in4_m1, 0);
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in2_m2, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN2 for Motor 2\n");
        gpiod_set_value(in1_m2, 0);
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in3_m2, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN3 for Motor 2\n");
        gpiod_set_value(in1_m2, 0);
        return EXIT_FAILURE;
    }
    if ((rc = gpiod_direction_output(in4_m2, 0)) != 0) {
        fprintf(stderr, "Error: Failed to configure IN4 for Motor 2\n");
        gpiod_set_value(in1_m2, 0);
        gpiod_set_value(in2_m2, 0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_stop) {
        // Calculate steps for 50mm square
        double distance = 50.0 * 1000.0 / (GEAR_RATIO * STEPS_PER_REVOLUTION); // 50mm to steps
        int steps = (int)round(distance);

        // Drive the motors
        for (int i = 0; i < steps; i++) {
            gpiod_set_value(in1_m1, 1);
            gpiod_set_value(in2_m1, 0);
            gpiod_set_value(in3_m1, 1);
            gpiod_set_value(in4_m1, 0);
            usleep(STEP_DELAY_US);

            gpiod_set_value(in1_m1, 0);
            gpiod_set_value(in2_m1, 1);
            gpiod_set_value(in3_m1, 0);
            gpiod_set_value(in4_m1, 0);
            usleep(STEP_DELAY_US);

            gpiod_set_value(in1_m1, 0);
            gpiod_set_value(in2_m1, 0);
            gpiod_set_value(in3_m1, 1);
            gpiod_set_value(in4_m1, 0);
            usleep(STEP_DELAY_US);

            gpiod_set_value(in1_m1, 0);
            gpiod_set_value(in2_m1, 1);
            gpiod_set_value(in3_m1, 0);
            gpiod_set_value(in4_m1, 0);
            usleep(STEP_DELAY_US);
        }

        // Motor 2 similar sequence

        // Check for SIGINT
        if (should_stop) {
            break;
        }
    }

    // Stop motors and release GPIO
    for (int i = 0; i < 2; i++) {
        gpiod_set_value(in1_m[i], 0);
        gpiod_set_value(in2_m[i], 0);
        gpiod_set_value(in3_m[i], 0);
        gpiod_set_value(in4_m[i], 0);
    }

    // Clean up GPIO descriptors
    for (int i = 0; i < 2; i++) {
        gpiod_free_desc(in1_m[i]);
        gpiod_free_desc(in2_m[i]);
        gpiod_free_desc(in3_m[i]);
        gpiod_free_desc(in4_m[i]);
    }

    return EXIT_SUCCESS;
}

