#define LIS3DH_ADDR_DEFAULT "0x1D" // Default I2C address, can be overridden with -a option
#define LIS3DH_THRESHOLD_DEFAULT 2.0 // Default threshold in g, can be overridden with -t option
#define LIS3DH_HIGH_RES_MODE 0x08 // High-resolution mode (12-bit, 100 Hz)
#define LIS3DH_RANGE_2G 0x00 // ±2 g range

// Function prototypes
void handle_SIGINT(int signum);
int main(int argc, char **argv);
