void log_high_acceleration(const struct lis3dh_data *data);
void cleanup();

// Global variables
struct lis3dh lis3dh;
int i2c_fd = -1;
int address = LIS3DH_ADDR_DEFAULT;
double threshold = LIS3DH_THRESHOLD_DEFAULT;
bool initialized = false;

// SIGINT handler
void handle_SIGINT(int signum) {
    printf("SIGINT received, terminating gracefully...\n");
    cleanup();
    exit(0);
}

// Main function
int main(int argc, char **argv) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            address = argv[i + 1];
            if (strlen(address) != 2 || !isxdigit(address[0]) || !isxdigit(address[1])) {
                fprintf(stderr, "Invalid I2C address specified. Defaulting to 0x1D\n");
                address = LIS3DH_ADDR_DEFAULT;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            threshold = atof(argv[i + 1]);
            if (threshold <= 0) {
                fprintf(stderr, "Threshold must be greater than 0\n");
                threshold = LIS3DH_THRESHOLD_DEFAULT;
            }
        }
    }

    // Initialize libgpiod and open I2C bus
    if (gpiod_is_valid()) {
        i2c_fd = gpiod_i2c_open(address, GPIOD_I2C_SPEED_100KHZ);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus\n");
            return 1;
        }

        // Initialize LIS3DH
        if (!lis3dh_init(i2c_fd)) {
            fprintf(stderr, "Failed to initialize LIS3DH\n");
            gpiod_i2c_close(i2c_fd);
            return 1;
        }

        // Configure LIS3DH
        write_reg(LIS3DH_REG_CONFIG, LIS3DH_HIGH_RES_MODE | LIS3DH_RANGE_2G);

        // Start reading acceleration
        while (1) {
            read_acceleration(&lis3dh);
            usleep(100000); // 100 ms interval
        }
    } else {
        fprintf(stderr, "libgpiod not available. Exiting...\n");
        return 1;
    }

    return 0;
}

// Function to write a register value
void write_reg(uint8_t reg, uint8_t value) {
    if (gpiod_i2c_write(i2c_fd, &reg, 1) < 0 || gpiod_i2c_write(i2c_fd, &value, 1) < 0) {
        fprintf(stderr, "Error writing to LIS3DH\n");
        cleanup();
        return;
    }
}

// Function to read acceleration data
void read_acceleration(struct lis3dh_data *data) {
    if (lis3dh_read(i2c_fd, data) < 0) {
        // Handle read error by returning zeros
        memset(data, 0, sizeof(struct lis3dh_data));
        return;
    }
}

// Function to log high acceleration
void log_high_acceleration(const struct lis3dh_data *data) {
    double x_accel = data->acceleration.x;
    double y_accel = data->acceleration.y;
    double z_accel = data->acceleration.z;

    if (x_accel > threshold || y_accel > threshold || z_accel > threshold) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "Timestamp: %s, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
                 ctime(&tv.tv_sec), x_accel, y_accel, z_accel);
        FILE *log_file = fopen("/var/log/high_acceleration.log", "a+");
        if (log_file) {
            fprintf(log_file, "%s", log_entry);
            fclose(log_file);
        } else {
            fprintf(stderr, "Failed to open log file for writing\n");
        }

        // Trigger shutdown
        system("sudo shutdown -h now");
    }
}

// Function to cleanup and close resources
