    srand(time(NULL)); // Seed random number generator for simplicity

    // Initialize GPIO and I2C
    setup_io();

    while (1) {
        // Read magnetic field
        read_magnetic_field();

        // Handle relay based on magnetic field reading
        handle_relay(read_magnetic_field() > THRESHOLD);

        // Append to log
        append_to_log(time(NULL) ISO8601 " - Magnetic field: %.2f mT\n",
                      read_magnetic_field());

        // Check for errors
        handle_errors(0); // Assuming no error initially

        // Sleep for 100 ms
        usleep(100000);
    }

    // Cleanup on SIGINT
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);

    return 0;
