#include <libuv.h>
#include <uv.h>

#define RELAY_GPIO 18
#define RELAY_NAME "KY-019"

FILE *log_file = NULL;
uv_loop_t *loop = NULL;
uv_tcp_t *server_socket = NULL;
char buffer[256];

void gpio_setup() {
    struct gpiod_device *relay_dev;
    int ret;

    // Initialize libgpiod
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    // Open the relay GPIO
    relay_dev = gpiod_get_device_by_number(RELAY_GPIO);
    if (!relay_dev) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", RELAY_GPIO, gpiod_errstr(gpiod_get_last_error()));
        exit(EXIT_FAILURE);
    }

    // Set the GPIO mode to output
    ret = gpiod_set_direction(relay_dev, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction: %s\n", RELAY_GPIO, gpiod_errstr(ret));
        gpiod_device_put(relay_dev);
        exit(EXIT_FAILURE);
    }

    // Turn off the relay initially
    ret = gpiod_write(relay_dev, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to GPIO %d: %s\n", RELAY_GPIO, gpiod_errstr(ret));
        gpiod_device_put(relay_dev);
        exit(EXIT_FAILURE);
    }

    printf("Relay GPIO %d initialized successfully\n", RELAY_GPIO);
}

void handle_signal(int signum) {
    // Graceful shutdown
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    if (server_socket) {
        uv_tcp_close(uv_tcp_handle(server_socket), NULL);
        server_socket = NULL;
    }

    if (loop) {
        uv_loop_stop(loop);
        uv_loop_close(loop);
        loop = NULL;
    }

    // Turn off the relay
    gpio_setup();
    gpiod_write(gpiod_get_device_by_number(RELAY_GPIO), 0);

    printf("Shutting down...\n");
    exit(EXIT_SUCCESS);
}

void setup_tcp_server() {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);

    // Initialize libuv
    uv_loop_t *loop = uv_default_loop();
    if (!loop) {
        fprintf(stderr, "Failed to initialize libuv\n");
        exit(EXIT_FAILURE);
    }

    // Create TCP server socket
    server_socket = uv_tcp_init(loop, NULL);
    if (!server_socket) {
        fprintf(stderr, "Failed to create TCP server socket\n");
        uv_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    // Bind and listen on port 5000
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(5000);

    if (uv_tcp_bind(server_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Failed to bind TCP socket\n");
        uv_tcp_close(uv_tcp_handle(server_socket), NULL);
        server_socket = NULL;
        uv_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    if (uv_tcp_listen(server_socket, 128) < 0) {
        fprintf(stderr, "Failed to listen on TCP port 5000\n");
        uv_tcp_close(uv_tcp_handle(server_socket), NULL);
        server_socket = NULL;
        uv_loop_close(loop);
        exit(EXIT_FAILURE);
    }

    printf("TCP server listening on port 5000\n");

    // Accept new connections
    uv_tcp_t *client_socket = NULL;
    uv_stream_t *stream = uv_tcp_handle(server_socket);

    uv_stream_set_read_start_cb(stream, on_accept);

    // Start the event loop
    uv_run(loop, UV_RUN_DEFAULT);
}

void on_accept(uv_stream_t *stream, int status) {
    if (status != UV_ACCEPT) {
        fprintf(stderr, "Accept error: %s\n", uv_strerror(status));
        return;
    }

    // Allocate memory for client address
    struct sockaddr_in client_addr;
    socklen_t client_addrlen = sizeof(client_addr);

    // Accept the connection
    if (uv_tcp_accept(server_socket, &client_socket, (struct sockaddr *)&client_addr, &client_addrlen) < 0) {
        fprintf(stderr, "Failed to accept TCP connection\n");
        uv_tcp_close(uv_tcp_handle(client_socket), NULL);
        client_socket = NULL;
        return;
    }

    // Create a new client socket for reading
    uv_tcp_t *client_readable = uv_tcp_init(loop, NULL);
    if (!client_readable) {
        fprintf(stderr, "Failed to create client readable socket\n");
        uv_tcp_close(uv_tcp_handle(client_socket), NULL);
        uv_tcp_close(uv_tcp_handle(client_readable), NULL);
        client_socket = NULL;
        client_readable = NULL;
        return;
    }

    // Set the client socket to readable mode
    if (uv_tcp_set_readable(client_readable, uv_tcp_handle(client_socket)) < 0) {
        fprintf(stderr, "Failed to set client socket to readable\n");
        uv_tcp_close(uv_tcp_handle(client_readable), NULL);
        uv_tcp_close(uv_tcp_handle(client_socket), NULL);
        client_socket = NULL;
        client_readable = NULL;
        return;
    }

    // Set the read callback
    uv_read_start(client_readable, on_client_read, NULL);

    // Log the connection
    fprintf(log_file, "Connection from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
    fflush(log_file);
}

void on_client_read(uv_stream_t *stream, int status, int events, const uv_buf_t *bufs, int nbufs) {
    if (status != UV_READABLE) {
        fprintf(stderr, "Read error: %s\n", uv_strerror(status));
        return;
    }

    if (nbufs == 0) {
        // No data to read
        return;
    }

    // Read data from the client
    char *data = malloc(bufs[0].base.size);
    ssize_t bytes_read = read(uv_tcp_handle(client_readable)->handle, data, bufs[0].base.size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from client socket: %s\n", strerror(errno));
        free(data);
        return;
    }
    data[bytes_read] = 0; // Null-terminate the string

    // Process the command
    if (strcasecmp(data, "ON") == 0) {
        gpio_control_on();
    } else if (strcasecmp(data, "OFF") == 0) {
        gpio_control_off();
    } else {
        fprintf(log_file, "Invalid command received: %s\n", data);
        fflush(log_file);
    }

    // Free the data buffer
    free(data);

    // Continue reading
    uv_read_start(client_readable, on_client_read, NULL);
}

void gpio_control_on() {
    int ret = gpiod_write(gpiod_get_device_by_number(RELAY_GPIO), 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to turn relay ON: %s\n", gpiod_errstr(ret));
        return;
    }

    fprintf(log_file, "Relay turned ON at %s\n", ctime(&time(NULL)));
    fflush(log_file);
}

void gpio_control_off() {
    int ret = gpiod_write(gpiod_get_device_by_number(RELAY_GPIO), 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to turn relay OFF: %s\n", gpiod_errstr(ret));
        return;
    }

    fprintf(log_file, "Relay turned OFF at %s\n", ctime(&time(NULL)));
    fflush(log_file);
}

int main() {
    // Initialize logging
    log_file = fopen("relay_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open relay_log.txt for writing\n");
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    gpio_setup();

    // Set up the TCP server
    setup_tcp_server();

    // Main loop
    uv_run(loop, UV_RUN_DEFAULT);

    // Clean up on exit
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    return EXIT_SUCCESS;
}

