void read_sensors_and_control_relay() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Read from sensors
    ssize_t sensor1_bytes = libgpiod_i2c_transfer(sensor1_fd, NULL, 0, NULL, 3, NULL);
    if (sensor1_bytes < 3 || libgpiod_i2c_is_error(sensor1_fd)) {
        fprintf(stderr, "Error reading from sensor 1: %s\n", libgpiod_i2c_get_error_string(sensor1_fd));
        return;
    }

    uint8_t sensor1_data[3];
    if (libgpiod_i2c_read(sensor1_fd, sensor1_data, 3) != 3) {
        fprintf(stderr, "Error reading from sensor 1: %s\n", libgpiod_i2c_get_error_string(sensor1_fd));
        return;
    }

    // Validate CRC for sensor 1
    uint8_t crc = sensor1_data[2];
    crc = (crc << 1) ^ (0x07 & (crc >> 7));
    if (crc != sensor1_data[0]) {
        fprintf(stderr, "CRC error for sensor 1\n");
        return;
    }

    // Read from sensor 2
    ssize_t sensor2_bytes = libgpiod_i2c_transfer(sensor2_fd, NULL, 0, NULL, 3, NULL);
    if (sensor2_bytes < 3 || libgpiod_i2c_is_error(sensor2_fd)) {
        fprintf(stderr, "Error reading from sensor 2: %s\n", libgpiod_i2c_get_error_string(sensor2_fd));
        return;
    }

    uint8_t sensor2_data[3];
    if (libgpiod_i2c_read(sensor2_fd, sensor2_data, 3) != 3) {
        fprintf(stderr, "Error reading from sensor 2: %s\n", libgpiod_i2c_get_error_string(sensor2_fd));
        return;
    }

    // Validate CRC for sensor 2
    crc = sensor2_data[2];
    crc = (crc << 1) ^ (0x07 & (crc >> 7));
    if (crc != sensor2_data[0]) {
        fprintf(stderr, "CRC error for sensor 2\n");
        return;
    }

    // Check flow rates
    float sensor1_flow_rate = (float)sensor1_data[1] / 256.0; // Assuming 8-bit value representing flow rate
    float sensor2_flow_rate = (float)sensor2_data[1] / 256.0;

    if (sensor1_flow_rate < FLOW_THRESHOLD || sensor2_flow_rate < FLOW_THRESHOLD) {
        // Energize relay if either sensor reports flow below threshold
        if (gpiod_set_value(GPIOD_NUM_RELAY_GPIO, 1) != 0) {
            fprintf(stderr, "Error setting relay to energized\n");
        } else {
            fprintf(stderr, "Relay energized due to low flow\n");
        }
    } else {
        // De-energize relay if both sensors are at or above threshold
        if (gpiod_set_value(GPIOD_NUM_RELAY_GPIO, 0) != 0) {
            fprintf(stderr, "Error setting relay to de-energized\n");
        } else {
            fprintf(stderr, "Relay de-energized as both flows are at or above %f ml/min\n", FLOW_THRESHOLD);
        }
    }

    // Write flow rates to log file
    char flow_log_path[] = "flow_log.txt";
    FILE *flow_log = fopen(flow_log_path, "a+");
    if (flow_log == NULL) {
        perror("Failed to open flow log file");
        return;
    }

    fprintf(flow_log, "%s %f %f\n", ts.tv_sec, sensor1_flow_rate, sensor2_flow_rate);
    fclose(flow_log);

    // Flush log file buffer
    fflush(flow_log);
}

// Function to handle SIGINT and SIGTERM
void shutdown_handler(int signum) {
    fprintf(stderr, "Shutting down due to signal %d\n", signum);

    // De-energize relay
    if (gpiod_set_value(GPIOD_NUM_RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error de-energizing relay on shutdown\n");
    } else {
        fprintf(stderr, "Relay de-energized on shutdown\n");
    }

    // Close I2C handles
    libgpiod_i2c_close(sensor1_fd);
    libgpiod_i2c_close(sensor2_fd);

    // Call cleanup function
    libgpiod_i2c_cleanup();

    // Exit program
    exit(EXIT_SUCCESS);
}

