#include <gpiod.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define ENA_GPIO 22
#define IN1_GPIO 23
#define IN2_GPIO 24

#define DRY_THRESHOLD 3
#define MOTOR_ON_TIME 5000

// Initialize gpiod and pigpio libraries
int gpiod_init(void);
int pigpio_init(void);

// Function prototypes
void handle_signal(int signum);
void rain_sensor_polling(void);
void start_motor(void);
void stop_motor(void);
void cleanup_resources(void);
void log_event(int level, const char *msg);

int main(void) {
    // Initialize gpiod and pigpio
    if ((gpiod_init() != 0) || (pigpio_init() != 0)) {
        syslog(LOG_ERR, "Failed to initialize GPIO and pigpio");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        rain_sensor_polling();
        usleep(200000); // Poll every 200ms
    }

    // Clean up on exit
    cleanup_resources();

    return EXIT_SUCCESS;
}

// Function to initialize gpiod
int gpiod_init(void) {
    int ret;
    struct gpio_desc *rain_sensor_desc;
    struct gpio_desc *ena_desc, *in1_desc, *in2_desc;

    // Initialize gpiod
    ret = gpiod_init();
    if (ret != 0) {
        syslog(LOG_ERR, "gpiod_init failed");
        return -1;
    }

    // Configure GPIO pins
    rain_sensor_desc = gpiod_get_desc(RAIN_SENSOR_GPIO, GPIO_IN);
    if (IS_ERR(rain_sensor_desc)) {
        syslog(LOG_ERR, "Failed to get rain sensor GPIO descriptor");
        return -1;
    }
    gpiod_set_direction(rain_sensor_desc, GPIO_INPUT);
    gpiod_set_pull_up(rain_sensor_desc, GPIO_PULL_UP);

    ena_desc = gpiod_get_desc(ENA_GPIO, GPIO_OUT);
    if (IS_ERR(ena_desc)) {
        syslog(LOG_ERR, "Failed to get ENA GPIO descriptor");
        gpiod_free_desc(rain_sensor_desc);
        return -1;
    }
    gpiod_set_direction(ena_desc, GPIO_OUT);

    in1_desc = gpiod_get_desc(IN1_GPIO, GPIO_OUT);
    if (IS_ERR(in1_desc)) {
        syslog(LOG_ERR, "Failed to get IN1 GPIO descriptor");
        gpiod_free_desc(ena_desc);
        gpiod_free_desc(rain_sensor_desc);
        return -1;
    }
    gpiod_set_direction(in1_desc, GPIO_OUT);

    in2_desc = gpiod_get_desc(IN2_GPIO, GPIO_OUT);
    if (IS_ERR(in2_desc)) {
        syslog(LOG_ERR, "Failed to get IN2 GPIO descriptor");
        gpiod_free_desc(in1_desc);
        gpiod_free_desc(ena_desc);
        gpiod_free_desc(rain_sensor_desc);
        return -1;
    }
