#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

volatile int lock_pressed = 0;
volatile int unlock_pressed = 0;

void setup_gpios() {
    int rc;

    // Initialize GPIO
    gpiod_init();

    // Enable internal pull-ups for lock and unlock buttons
    rc = gpiod_set_pull_up_down(SERVO_PIN, GPIOD_PULLUP);
    if (rc != 0) {
        fprintf(stderr, "Error enabling pull-up on servo pin: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    rc = gpiod_set_direction(LOCK_BUTTON_PIN, GPIOD_OUT_INIT_LOW);
    if (rc != 0) {
        fprintf(stderr, "Error setting direction for lock button pin: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    rc = gpiod_set_direction(UNLOCK_BUTTON_PIN, GPIOD_OUT_INIT_LOW);
    if (rc != 0) {
        fprintf(stderr, "Error setting direction for unlock button pin: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    // Enable internal pull-ups for lock and unlock buttons
    rc = gpiod_set_pull_up_down(LOCK_BUTTON_PIN, GPIOD_PULLUP);
    if (rc != 0) {
        fprintf(stderr, "Error enabling pull-up for lock button pin: %d\n", rc);
        exit(EXIT_FAILURE);
    }

    rc = gpiod_set_pull_up_down(UNLOCK_BUTTON_PIN, GPIOD_PULLUP);
    if (rc != 0) {
        fprintf(stderr, "Error enabling pull-up for unlock button pin: %d\n", rc);
        exit(EXIT_FAILURE);
    }
}

void handle_interrupts(int signum) {
    // Stop the servo by sending a pulse width of 0
    gpiod_set_value(SERVO_PIN, 0);
    printf("Interrupt received, stopping servo...\n");

    // Final API call to ensure everything is properly released
    int lock_api_return = gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 0, 0);
    int unlock_api_return = gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 1000, 0);

    if (lock_api_return != 0 || unlock_api_return != 0) {
        fprintf(stderr, "Error in final API calls: lock=%d, unlock=%d\n", lock_api_return, unlock_api_return);
        exit(EXIT_FAILURE);
    }

    // Clean up and exit
    gpiod_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    setup_gpios();

    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    printf("Lock and Unlock Servo System Started...\n");

    while (1) {
        // Poll lock button
        if (gpiod_get_value_data(LOCK_BUTTON_PIN) == 0) {
            lock_pressed = 1;
            printf("Lock button pressed, sending lock command...\n");
            gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 2000, 0);
            if (gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 0, 0) != 0) {
                fprintf(stderr, "Error sending lock pulse: %d\n", gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 0, 0));
                break;
            }
        }

        // Poll unlock button
        if (gpiod_get_value_data(UNLOCK_BUTTON_PIN) == 0) {
            unlock_pressed = 1;
            printf("Unlock button pressed, sending unlock command...\n");
            gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 1000, 0);
            if (gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 0, 0) != 0) {
                fprintf(stderr, "Error sending unlock pulse: %d\n", gpiod_call(SERVO_PIN, GPIOD_OUT_HIGH, 0, 0));
                break;
            }
        }

        // Debounce: Wait for button release and a short delay
        usleep(50); // Small delay to debounce

        // Check if both buttons are released
        if (!lock_pressed && !unlock_pressed) {
            printf("Both buttons released, sleeping...\n");
            usleep(100000); // Sleep for 100ms to reduce CPU usage
        }
    }

    printf("Exiting...\n");

    return 0;
}

