#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define PIR_GPIO 4
#define FLOODLIGHT_GPIO 17
#define PIR_PIN 7
#define FLOODLIGHT_PIN 11
#define POLL_INTERVAL_MS 100
#define LOG_FILE_NAME "security_log.txt"

// Function prototypes
void handle_signal(int signum);
void setup_gpiod();
void monitor_motion();
void activate_floodlight();
void deactivate_floodlight(int duration_seconds);
void append_log_entry(char *timestamp, char *message);

// Global variables
gpiod_device *pir_sensor;
gpiod_device *floodlight;
FILE *log_file;
int pir_rising_count = 0;
int floodlight_duration = 0;

// SIGINT/SIGTERM handler
void handle_signal(int signum) {
    if (pir_sensor) {
        deactivate_floodlight(floodlight_duration);
        gpiod_device_free(pir_sensor);
        gpiod_device_free(floodlight);
    }
    printf("Caught signal, shutting down...\n");
    exit(0);
}

// Main function
int main() {
    // Initialize gpiod library
    setup_gpiod();

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Attempt to open the log file
    if ((log_file = fopen(LOG_FILE_NAME, "a")) == NULL) {
        printf("Failed to open log file. Turning off floodlight and exiting.\n");
        deactivate_floodlight(0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        monitor_motion();
        activate_floodlight();
        sleep(POLL_INTERVAL_MS);
        floodlight_duration = 60; // Reset duration for each activation
    }

    // Close log file and clean up
    fclose(log_file);
    if (pir_sensor) {
        gpiod_device_free(pir_sensor);
    }
    if (floodlight) {
        gpiod_device_free(floodlight);
    }

    return EXIT_SUCCESS;
}

// Setup gpiod library
void setup_gpiod() {
    if (gpiod_is_valid()) {
        printf("gpiod library initialized successfully.\n");
    } else {
        printf("Failed to initialize gpiod library. Exiting.\n");
        return;
    }

    pir_sensor = gpiod_lookup_device(PIR_GPIO);
    if (pir_sensor == NULL) {
        printf("Failed to find PIR sensor on GPIO %d. Exiting.\n", PIR_GPIO);
        return;
    }

    floodlight = gpiod_lookup_device(FLOODLIGHT_GPIO);
    if (floodlight == NULL) {
        printf("Failed to find floodlight on GPIO %d. Exiting.\n", FLOODLIGHT_GPIO);
        gpiod_device_free(pir_sensor);
        return;
    }
}

// Monitor motion
void monitor_motion() {
    struct timespec timestamp;
    time_t now = time(NULL);
    if (clock_gettime(CLOCK_REALTIME, &timestamp) == 0) {
        char timestamp_str[50];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%fZ", &now);
        fprintf(log_file, "PIR detected: %s\n", timestamp_str);
        if (gpiod_get_value_level(pir_sensor) == GPIOD_LEVEL_HIGH) {
            pir_rising_count++;
        }
    } else {
        perror("clock_gettime");
        return;
    }
}

// Activate floodlight
void activate_floodlight() {
    if (gpiod_direction_output(floodlight, FLOODLIGHT_GPIO, 1) != 0) {
        printf("Failed to set floodlight GPIO high. Turning off floodlight and exiting.\n");
        deactivate_floodlight(0);
        return;
    }
}

// Deactivate floodlight
void deactivate_floodlight(int duration_seconds) {
    if (gpiod_direction_output(floodlight, FLOODLIGHT_GPIO, 0) != 0) {
        printf("Failed to set floodlight GPIO low. Duration: %d seconds\n", duration_seconds);
        return;
    }
    floodlight_duration = duration_seconds;
}

// Append log entry
void append_log_entry(char *timestamp, char *message) {
    if (fprintf(log_file, "%s - %s\n", timestamp, message) != 0) {
        printf("Failed to write to log file. Turning off floodlight and exiting.\n");
        deactivate_floodlight(0);
        return;
    }
}

