#include <netinet/in.h>
#include <pthread.h>
#include <gpiod.h>
#include <stdio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_CMD "servo"
#define PIR_CMD "pir"
#define PORT 5000
#define LOG_FILE "security.log"
#define LOG_USER "raspi_security"

// Function prototypes
void setup_GPIOs();
void handle_GPIO_events();
void handle_servo_command(char *data, int length);
void handle_PIR_command();
void graceful_shutdown();
void log_event(const char *msg, ...);
void cleanup_resources();

// Global variables
gpiod_device *servo_device;
gpiod_device *pir_device;
int servo_pin;
int pir_pin;
int socket;
pthread_t logging_thread;

// Main function
int main() {
    // Initialize GPIO devices
    setup_GPIOs();

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = graceful_shutdown;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Create socket for TCP listening
    socket = socket(AF_INET, SOCK_STREAM, 0);
    if (socket == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(PORT);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(socket, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(socket, 5) == -1) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Start logging thread
    pthread_create(&logging_thread, NULL, (void *)log_thread_entry, NULL);

    // Server loop
    while (1) {
        int clientfd = accept(socket, (struct sockaddr *)&addr, (socklen_t*)&sizeof(addr));
        if (clientfd == -1) {
            perror("accept");
            continue;
        }

        pthread_t client_thread;
        pthread_create(&client_thread, NULL, (void *)handle_client, (void *)clientfd);

        // Close client socket after thread creation to prevent resource leaks
        close(clientfd);
    }

    // Wait for the logging thread to finish
    pthread_join(logging_thread, NULL);

    // Clean up resources
    cleanup_resources();

    return 0;
}

// Function to handle client connections
void *handle_client(void *clientfd_arg) {
    int clientfd = *(int *)clientfd_arg;
    char buffer[256];
    char command[10];

    // Receive command from client
    if (read(clientfd, command, sizeof(command)) == -1) {
        perror("read");
        return;
    }

    // Parse command
    if (sscanf(command, "%s %c", buffer, &command[4]) != 1) {
        fprintf(stderr, "Invalid command format: %s\n", command);
        return;
    }

    if (strcmp(command, SERVO_CMD) == 0) {
        handle_servo_command(buffer, strlen(buffer));
    } else if (strcmp(command, PIR_CMD) == 0) {
        handle_PIR_command();
    } else {
        fprintf(stderr, "Unknown command: %s\n", command);
    }

    // Close client socket
    close(clientfd);

    return NULL;
}

// Function to handle servo command
void handle_servo_command(char *data, int length) {
    double angle = atof(data);
    if (gpiod_set_data(servo_device, SERVO_PIN, angle * 20000) < 0) {
        log_event("Error setting servo angle: %s", gpiod_get_name(servo_device));
        return;
    }

    // Generate PWM signal
    // This is a simplified example; actual servo control may require more precise timing
    while (1) {
        usleep(20000); // 50 Hz
        gpiod_set_value(servo_device, SERVO_PIN, 20000); // 1 ms pulse
        usleep(200000); // 2 ms off
    }
}

// Function to handle PIR command
void handle_PIR_command() {
    int value = gpiod_read(spir_device, pir_pin);
    if (value == 0) {
        log_event("PIR:0");
    } else {
        log_event("PIR:1");
    }
}

// Logging thread function
void *log_thread_entry(void *arg) {
    while (1) {
        char msg[256];
        time_t now = time(NULL);
        struct tm timeinfo;
        localtime_r(&now, &timeinfo);
        strftime(msg, sizeof(msg), "%Y-%m-%d %H:%M:%S %f [PID %d] ", &timeinfo, NULL, getpid());

        // Read from the log file
        FILE *log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            log_event("Failed to open log file for writing.", NULL);
            continue;
        }
        fprintf(log_file, "%s", msg);
        fclose(log_file);

        // Read from syslog
        char syslog_msg[1024];
        ssize_t syslog_len = syslog(LOG_USER, "%s", msg);
        if (syslog_len < 0) {
            log_event("Failed to write to syslog.", NULL);
            continue;
        }
        syslog_msg[syslog_len] = '\0';
        log_event("Syslog message: %s", syslog_msg);

        // Sleep for a short period to avoid flooding
        usleep(100000);
    }
    return NULL;
}

// Setup GPIO devices
void setup_GPIOs() {
    servo_device = gpiod_get_device(SERVO_PIN);
    if (!servo_device) {
        log_event("Failed to initialize servo GPIO.", NULL);
        exit(EXIT_FAILURE);
    }

    pir_device = gpiod_get_device(pir_pin);
    if (!pir_device) {
        log_event("Failed to initialize PIR GPIO.", NULL);
        exit(EXIT_FAILURE);
    }
}

// Graceful shutdown function
void graceful_shutdown() {
    // Stop servo PWM generation
    gpiod_set_data(servo_device, SERVO_PIN, 0);

    // Close socket
    close(socket);

    // Close log file
    fclose(log_file);

    // Release GPIO resources
    gpiod_device_unref(servo_device);
    gpiod_device_unref(pir_device);

    // Exit with 0 status
    exit(EXIT_SUCCESS);
}

// Cleanup resources function
void cleanup_resources() {
    // Close log file if it exists
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Join logging thread
    pthread_join(logging_thread, NULL);
}

// Helper function to log events with variadic arguments
void log_event(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsprintf(msg, fmt, args);
    va_end(args);
    // Log to syslog and file
    syslog(LOG_USER, "%s", msg);
    fprintf(log_file, "%s", msg);
}

// Ensure the code compiles cleanly with -Wall -Wextra
// Include <stdarg.h> for variadic functions
#include <stdarg.h>

// SIGINT and SIGTERM signal handlers are already set up in main()

