void cleanup_gpiod();
void read_light_value(uint16_t* lux);
void handle_light_level(uint16_t lux);
void handle_error(const char* operation, int rc);
void write_to_log(const char* message);
void retry_after_delay(int delay_ms);

int main() {
    // Initialize GPIO
    initialize_gpiod();

    uint16_t lux;
    int i2c_fd;
    int retry_count = 0;
    int delay_ms = 120;

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open log file for appending
    const char* log_file_path = "grow_log.txt";
    int log_fd = open(log_file_path, O_APPEND | O_WRONLY);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for 2 seconds
        struct timeval now;
        gettimeofday(&now, NULL);
        int64_t wait_duration = (int64_t)(2 * 1000 * 1000) - (int64_t)(now.tv_sec * 1000 * 1000 + now.tv_usec);
        if (wait_duration < 0) {
            wait_duration += 1000 * 1000; // Wrap around
        }
        usleep(wait_duration);

        // Read light value
        if (retry_count > 0) {
            // Retry after delay
            retry_after_delay(delay_ms);
            retry_count--;
        } else {
            read_light_value(&lux);
        }

        // Handle light level
        handle_light_level(lux);

        // Write to log
        write_to_log("Lux: %hu, Time: %s\n", lux, ctime(&now.tv_sec));

        // Close resources on exit
        cleanup_gpiod();
        close(i2c_fd);
        close(log_fd);
    }

    return EXIT_SUCCESS;
}

// Function to initialize GPIO
void initialize_gpiod() {
    gpiod_set_config(GROW_LIGHT_GPIO, GPIOD_DIR_OUT_INIT_LOW);
    gpiod_direction_output(GROW_LIGHT_GPIO, 1); // Activate relay
}

// Function to cleanup GPIO
void cleanup_gpiod() {
    gpiod_set_config(GROW_LIGHT_GPIO, GPIOD_DIR_INPUT); // Deactivate relay
}

// Function to read light value from BH1750
void read_light_value(uint16_t* lux) {
    int rc;
    struct i2c_msg msg[2];
    msg[0].addr = BH1750_ADDR;
    msg[0].len = sizeof(msg[0].data);
    msg[0].buf = (uint8_t *)(&lux);

    msg[1].addr = BH1750_ADDR;
    msg[1].len = 2; // Request 2 bytes of data
    msg[1].buf = NULL; // No data to send

    rc = i2c_transfer(i2c_fd, msg, 2);
    if (rc != 2) {
        handle_error("i2c_transfer", rc);
    }
}

// Function to handle light level and control relay
void handle_light_level(uint16_t lux) {
    if (lux < 150) {
        // Activate grow light
        gpiod_set_value(GROW_LIGHT_GPIO, 1);
    } else {
        // Deactivate grow light
        gpiod_set_value(GROW_LIGHT_GPIO, 0);
    }
}

// Function to handle errors and retry after delay
void handle_error(const char* operation, int rc) {
    fprintf(stderr, "Error during %s: %s\n", operation, strerror(rc));
    retry_after_delay(delay_ms);
}

// Function to write to the log file
void write_to_log(const char* message) {
    char buffer[256];
    sprintf(buffer, "%s", message);
    write(log_fd, buffer, strlen(buffer));
}

// Function to retry after a delay
void retry_after_delay(int delay_ms) {
    usleep(delay_ms * 1000);
}

