#include <sys/wait.h>
#include <time.h>
#include <gpiod.h>
#include <hx711.h>

#define GPIO23 16
#define GPIO24 18
#define GPIO25 22

#define TARE_READINGS 10
#define MEASUREMENT_READINGS 5
#define THRESHOLD_WEIGHT 1000
#define SCALE_FACTOR_DEFAULT 1.0
#define MAX_RETRIES 3

// HX711 configuration
#define HX711_CHANNEL_A 1

// GPIO setup
static const struct gpio_desc *gpiod_hx711_dout = NULL;
static const struct gpio_desc *gpiod_hx711_sck = NULL;
static const struct gpio_desc *gpiod_solenoid = NULL;

// HX711 instance
hx711_t hx711;

// Global variables
unsigned long tare_weight = 0;
unsigned long measurement_weight;
double scale_factor = SCALE_FACTOR_DEFAULT;
int solenoid_active = 0;
int threshold_set = 0;
int retry_count = 0;

// Function prototypes
void setup_hardware();
void tare();
void measure_weight();
void activate_solenoid();
void handle_signal(int signum);
void cleanup();

int main(int argc, char **argv) {
    // Initialize GPIO descriptors
    gpiod_hx711_dout = gpiod_get_desc(GPIO23);
    gpiod_hx711_sck = gpiod_get_desc(GPIO24);
    gpiod_solenoid = gpiod_get_desc(GPIO25);

    if (gpiod_hx711_dout == NULL || gpiod_hx711_sck == NULL || gpiod_solenoid == NULL) {
        fprintf(stderr, "Failed to initialize GPIO pins.\n");
        return EXIT_FAILURE;
    }

    // Initialize HX711
    if (hx711_init(gpiod_hx711_dout, gpiod_hx711_sck) < 0) {
        fprintf(stderr, "Failed to initialize HX711.\n");
        return EXIT_FAILURE;
    }

    // Setup GPIO for solenoid
    if (gpio_direction_output(gpiod_solenoid, 1) < 0) {
        fprintf(stderr, "Failed to configure GPIO25 as output for solenoid.\n");
        return EXIT_FAILURE;
    }

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--scale") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Missing scale factor value.\n");
                return EXIT_FAILURE;
            }
            scale_factor = atof(argv[i + 1]);
        } else if (strcmp(argv[i], "--threshold") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Missing threshold value.\n");
                return EXIT_FAILURE;
            }
            THRESHOLD_WEIGHT = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--duration") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Missing duration value.\n");
                return EXIT_FAILURE;
            }
            int duration_ms = atoi(argv[i + 1]);
            usleep(duration_ms * 1000);
        } else if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [options]\n", argv[0]);
            printf("Options:\n");
            printf("  --scale <factor>  Scale factor for weight measurement\n");
            printf("  --threshold <grams>  Weight threshold for activating solenoid\n");
            printf("  --duration <ms>  Duration to keep solenoid active\n");
            return EXIT_SUCCESS;
        } else {
            fprintf(stderr, "Unknown argument: %s\n", argv[i]);
            return EXIT_FAILURE;
        }
    }

    // Setup tare
    tare();

    // Main loop
    while (1) {
        measure_weight();
        if (measurement_weight > THRESHOLD_WEIGHT) {
            activate_solenoid();
        }
        usleep(500 * 1000); // Poll every 500ms
    }

    return 0;
}

// Function to setup hardware
void setup_hardware() {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID, LOG_USER);

    // Verify GPIO setup
    if (gpio_direction_input(gpiod_solenoid) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO25 as input for error detection.\n");
        return;
    }

    // Initialize HX711 for tare reading
    hx711_reset();
    for (int i = 0; i < TARE_READINGS; i++) {
        if (hx711_read_24bit() < 0) {
            syslog(LOG_ERR, "Failed to read tare weight.\n");
            return;
        }
        tare_weight += hx711_read_24bit();
    }
    tare_weight /= TARE_READINGS;

    // Print initial tare weight
    syslog(LOG_INFO, "Initial tare weight: %lu grams\n", tare_weight);
}

// Function to perform tare operation
void tare() {
    // Set HX711 to Channel A gain 128
    hx711_config(HX711_CHANNEL_A, 128);

    // Wait for DOUT to go LOW
    while (gpio_get_value(gpiod_hx711_dout) != 0) {
        usleep(1000);
        if (retry_count++ >= MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to wait for DOUT to go LOW after multiple attempts.\n");
            return;
        }
    }

    // Read 24-bit two's complement value
    if (hx711_read_24bit() < 0) {
        syslog(LOG_ERR, "Failed to read 24-bit value for tare.\n");
        return;
    }

    // Apply Channel A gain 128
    tare_weight = (tare_weight - hx711_read_24bit()) * 128;
    syslog(LOG_INFO, "Tare weight: %lu grams\n", tare_weight);
}

// Function to measure weight
void measure_weight() {
    measurement_weight = 0;

    for (int i = 0; i < MEASUREMENT_READINGS; i++) {
        if (hx711_read_24bit() < 0) {
            syslog(LOG_ERR, "Failed to read weight measurement.\n");
            return;
        }
        measurement_weight += hx711_read_24bit();
    }

    measurement_weight /= MEASUREMENT_READINGS;
    if (scale_factor != 1.0) {
        measurement_weight *= scale_factor;
    }

    syslog(LOG_INFO, "Measured weight: %lu grams\n", measurement_weight);
}

// Function to activate solenoid
void activate_solenoid() {
    solenoid_active = 1;
    usleep(200 * 1000); // Activate for 200ms
    solenoid_active = 0;
    syslog(LOG_INFO, "Solenoid activated for %d ms\n", usleep(200 * 1000));
}

// Handle signals to perform graceful shutdown
void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup();
        _exit(EXIT_SUCCESS);
    }
}

// Function to cleanup resources
void cleanup() {
    // Deactivate solenoid
    gpio_set_value(gpiod_solenoid, 0);

    // Release GPIO descriptors
    gpiod_hx711_dout = NULL;
    gpiod_hx711_sck = NULL;
    gpiod_solenoid = NULL;

    // Close syslog
    closelog();

    // Shutdown HX711
    hx711_shutdown();
}

// Main program entry point
int main(int argc, char **argv) {
    // ... (rest of the code as provided above)

    return 0;
}

