#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define SERVO_1_GPIO 7
#define SERVO_2_GPIO 8
#define SERVO_3_GPIO 9
#define SERVO_4_GPIO 10
#define SERVO_5_GPIO 11

int main() {
    // Initialize gpiod library
    int rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "gpiod_init() failed: %s\n", gpiod_errmsg());
        return EXIT_FAILURE;
    }

    // Open GPIO pins in PWM mode
    struct gpiod_pwm *servo_pwm[5];
    int i;

    for (i = 0; i < 5; i++) {
        rc = gpiod_pwm_open(gpiod_get_device_by_name("bcm2835-gpio"), SERVO_i_GPIO, GPIOD_PINMODE_PWM, &servo_pwm[i]);
        if (rc != 0) {
            fprintf(stderr, "Failed to open GPIO %d for PWM: %s\n", SERVO_i_GPIO, gpiod_errmsg());
            gpiod_pwm_close(servo_pwm[i]);
            gpiod_uninit();
            return EXIT_FAILURE;
        }
    }

    // Set PWM duty cycles for each servo
    for (i = 0; i < 5; i++) {
        rc = gpiod_pwm_set_duty_cycle(servo_pwm[i], 1000); // 1000 us for Servo 1
        if (rc != 0) {
            fprintf(stderr, "Failed to set duty cycle for Servo %d: %s\n", i + 1, gpiod_errmsg());
            gpiod_pwm_close(servo_pwm[i]);
            gpiod_uninit();
            return EXIT_FAILURE;
        }

        // Wait for 3 seconds
        sleep(3);

        // Move to next position
        if (i < 4) {
            rc = gpiod_pwm_set_duty_cycle(servo_pwm[i], (i + 1) * 500); // 1500 us for Servo 2, 2000 us for Servo 3, 500 us for Servo 4, 2500 us for Servo 5
            if (rc != 0) {
                fprintf(stderr, "Failed to set duty cycle for Servo %d: %s\n", i + 1, gpiod_errmsg());
                gpiod_pwm_close(servo_pwm[i]);
                gpiod_uninit();
                return EXIT_FAILURE;
            }
        }
    }

    // Stop PWM and close GPIOs
    for (i = 0; i < 5; i++) {
        rc = gpiod_pwm_stop(servo_pwm[i]);
        if (rc != 0) {
            fprintf(stderr, "Failed to stop PWM for Servo %d: %s\n", i + 1, gpiod_errmsg());
            gpiod_pwm_close(servo_pwm[i]);
        }
        gpiod_pwm_close(servo_pwm[i]);
    }

    // Clean up and exit
    gpiod_uninit();
    return EXIT_SUCCESS;
}

