#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>
#include <gpiod.h>
#include <atomic>

#define PI 3.14159265358979323846
#define PWM_FREQ 10000
#define PWM_MIN 0
#define PWM_MAX 255
#define TICKS_PER_REVOLUTION 64
#define TARGET_RPM 50
#define STALL_TIMEOUT_MS 2000

// GPIO Pin Definitions
#define MOTOR_A_PWM   GPIOD_NUM_17
#define MOTOR_A_DIR    GPIOD_NUM_18
#define MOTOR_B_PWM   GPIOD_NUM_22
#define MOTOR_B_DIR    GPIOD_NUM_23
#define ENCODER_A_A    GPIOD_NUM_4
#define ENCODER_A_B    GPIOD_NUM_5
#define ENCODER_B_A    GPIOD_NUM_6
#define ENCODER_B_B    GPIOD_NUM_12

// Encoder Ticks Counters
volatile uint32_t encoder_a_ticks = 0;
volatile uint32_t encoder_b_ticks = 0;

// Motor Control Variables
bool motor_a_forward = false;
bool motor_b_forward = false;

// PI Controller Variables
float kp = 0.1; // Proportional Gain
float ki = 0.05; // Integral Gain
float kd = 0.0; // Derivative Gain
float error_a = 0.0;
float error_b = 0.0;
float prev_error_a = 0.0;
float prev_error_b = 0.0;
float integral_a = 0.0;
float integral_b = 0.0;
float derivative_a = 0.0;
float derivative_b = 0.0;

// Anti-Windup Variables
int duty_cycle_a = 0;
int duty_cycle_b = 0;

// Encoder Stall Detection
bool encoder_stall_a = false;
bool encoder_stall_b = false;

// Global State
bool running = true;
bool stopped = false;

// Signal Handler for SIGINT
void signal_handler(int signum) {
    stopped = true;
    gpiod_stop(MOTOR_A_PWM);
    gpiod_stop(MOTOR_A_DIR);
    gpiod_stop(MOTOR_B_PWM);
    gpiod_stop(MOTOR_B_DIR);
    gpiod_unexport_all();
    printf("Stopping motors and releasing resources...\n");
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpiod_export(MOTOR_A_PWM, GPIOD_DIR_OUT_PP) ||
        gpiod_export(MOTOR_A_DIR, GPIOD_DIR_IN) ||
        gpiod_export(MOTOR_B_PWM, GPIOD_DIR_OUT_PP) ||
        gpiod_export(MOTOR_B_DIR, GPIOD_DIR_IN) ||
        gpiod_export(ENCODER_A_A, GPIOD_DIR_IN) ||
        gpiod_export(ENCODER_A_B, GPIOD_DIR_IN) ||
        gpiod_export(ENCODER_B_A, GPIOD_DIR_IN) ||
        gpiod_export(ENCODER_B_B, GPIOD_DIR_IN)) {
        fprintf(stderr, "Error initializing GPIO\n");
        return EXIT_FAILURE;
    }

    // Initialize Encoder Ticks Counters
    encoder_a_ticks = atomic_init(&encoder_a_ticks, 0);
    encoder_b_ticks = atomic_init(&encoder_b_ticks, 0);

    // Set up Signal Handler
    signal(SIGINT, signal_handler);

    // Main Loop
    while (running) {
        // Update Encoder Ticks
        uint32_t new_encoder_a_ticks = atomic_load(&encoder_a_ticks);
        uint32_t new_encoder_b_ticks = atomic_load(&encoder_b_ticks);

        if (new_encoder_a_ticks == encoder_a_ticks) {
            encoder_stall_a = true;
        } else {
            encoder_stall_a = false;
        }

        if (new_encoder_b_ticks == encoder_b_ticks) {
            encoder_stall_b = true;
        } else {
            encoder_stall_b = false;
        }

        // Check for Encoder Stall
        if (encoder_stall_a && (time(NULL) - last_stall_check_a > STALL_TIMEOUT_MS)) {
            printf("Encoder A stall detected.\n");
            encoder_stall_a = false;
        }
        if (encoder_stall_b && (time(NULL) - last_stall_check_b > STALL_TIMEOUT_MS)) {
            printf("Encoder B stall detected.\n");
            encoder_stall_b = false;
        }

        last_stall_check_a = time(NULL);
        last_stall_check_b = time(NULL);

        // PI Control Loop
        error_a = TARGET_RPM - (PWM_FREQ / TICKS_PER_REVOLUTION * new_encoder_a_ticks);
        error_b = TARGET_RPM - (PWM_FREQ / TICKS_PER_REVOLUTION * new_encoder_b_ticks);

        derivative_a = (error_a - prev_error_a) / (double)PWM_FREQ;
        derivative_b = (error_b - prev_error_b) / (double)PWM_FREQ;

        integral_a += (error_a * (double)PWM_FREQ);
        integral_b += (error_b * (double)PWM_FREQ);

        prev_error_a = error_a;
        prev_error_b = error_b;

        duty_cycle_a = (int)(kp * error_a + ki * integral_a + kd * derivative_a);
        duty_cycle_b = (int)(kp * error_b + ki * integral_b + kd * derivative_b);

        // Clamp Duty Cycles
        duty_cycle_a = clamp_duty_cycle(duty_cycle_a, PWM_MIN, PWM_MAX);
        duty_cycle_b = clamp_duty_cycle(duty_cycle_b, PWM_MIN, PWM_MAX);

        // Update Motor Directions and PWM
        if (motor_a_forward) {
            gpiod_set_value(MOTOR_A_PWM, duty_cycle_a);
            gpiod_set_value(MOTOR_A_DIR, 1); // High for forward
        } else {
            gpiod_set_value(MOTOR_A_PWM, 0);
            gpiod_set_value(MOTOR_A_DIR, 0); // Low for reverse
        }

        if (motor_b_forward) {
            gpiod_set_value(MOTOR_B_PWM, duty_cycle_b);
            gpiod_set_value(MOTOR_B_DIR, 1); // High for forward
        } else {
            gpiod_set_value(MOTOR_B_PWM, 0);
            gpiod_set_value(MOTOR_B_DIR, 0); // Low for reverse
        }

        // Print Motor Status
        printf("Motor A: RPM %d, Duty Cycle %d\n", (int)(TARGET_RPM * TICKS_PER_REVOLUTION / PWM_FREQ * new_encoder_a_ticks), duty_cycle_a);
        printf("Motor B: RPM %d, Duty Cycle %d\n", (int)(TARGET_RPM * TICKS_PER_REVOLUTION / PWM_FREQ * new_encoder_b_ticks), duty_cycle_b);

        // Sleep for 100ms
        usleep(100000);

        // Check for SIGINT
        if (stopped) {
            break;
        }
    }

    // Stop Motors and Release Resources
    gpiod_stop(MOTOR_A_PWM);
    gpiod_stop(MOTOR_A_DIR);
    gpiod_stop(MOTOR_B_PWM);
    gpiod_stop(MOTOR_B_DIR);
    gpiod_unexport_all();

    printf("Exiting...\n");

    return EXIT_SUCCESS;
}

// Clamp Duty Cycle Function
int clamp_duty_cycle(int duty_cycle, int min, int max) {
    return (duty_cycle < min) ? min : (duty_cycle > max) ? max : duty_cycle;
}

