#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define DUSK_THRESHOLD 50
#define DAWN_THRESHOLD 200
#define Hysteresis 10

FILE *logFile;
struct gpiod_dir *relayDir;
int relayPin;
int i2cDev = 1;
unsigned int lux;
int luxReadFailCount = 0;

void setupResources() {
    // Initialize GPIO for relay control
    relayDir = gpiod_get_dir(gpiod_get_device(GPIOD_ID_BCM));
    if (relayDir == NULL) {
        fprintf(stderr, "Error: Could not get GPIO directory\n");
        exit(EXIT_FAILURE);
    }
    relayPin = gpiod_get_pin_by_name(relayDir, "GPIO17");
    if (relayPin == GPIOD_PIN_NONE) {
        fprintf(stderr, "Error: GPIO17 not found\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    int i2cFile = open("/dev/i2c-1", O_RDWR);
    if (i2cFile == -1) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        exit(EXIT_FAILURE);
    }

    // Open log file for writing
    logFile = fopen("chicken_coop_log.txt", "a+");
    if (logFile == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        exit(EXIT_FAILURE);
    }
}

void cleanupResources() {
    // Close I2C device
    if (i2cFile != -1) {
        close(i2cFile);
    }

    // Close log file
    if (logFile != NULL) {
        fclose(logFile);
    }

    // Release GPIO pin
    gpiod_put_pin(relayPin, GPIOD_PIN_STATE_LOW);
    gpiod_put_dir(relayDir, NULL);
}

void readLux() {
    int i2cResult;
    struct i2c_msg msg = {
        .addr = BH1750_ADDR,
        .flags = 0,
        .len = sizeof(lux)
    };

    // Wait for at least 180ms after sending mode command
    usleep(180000);

    i2cResult = i2c_transfer(i2cFile, &msg, 1);
    if (i2cResult < 1) {
        luxReadFailCount++;
        fprintf(logFile, "Error reading lux: %d\n", i2cResult);
        return;
    }

    lux = msg.len == sizeof(lux) ? msg.data[0] : 0;
    if (luxReadFailCount > 5) {
        fprintf(logFile, "Lux sensor failed to respond after multiple attempts.\n");
        lux = 0;
        luxReadFailCount = 0;
    }
}

void controlRelay() {
    int luxValue;
    char relayState;

    // Read lux value
    readLux();

    // Check relay state
    if (gpiod_get_value_relaxed(relayPin) == GPIOD_PIN_STATE_HIGH) {
        relayState = 'ON';
    } else {
        relayState = 'OFF';
    }

    // Log current state
    time_t now = time(NULL);
    char timestamp[21];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(logFile, "%s: Lux = %d, Relay = %c\n", timestamp, lux, relayState);

    // Control relay based on lux value
    if (lux < DUSK_THRESHOLD) {
        if (relayState != 'ON') {
            // Activate relay if lux falls below threshold
            gpiod_set_value(relayPin, GPIOD_PIN_STATE_HIGH);
            fprintf(logFile, "Activating relay at dusk (Lux: %d)\n", lux);
        }
    } else if (lux > DAWN_THRESHOLD + Hysteresis) {
        if (relayState == 'ON') {
            // Deactivate relay at dawn with hysteresis
            gpiod_set_value(relayPin, GPIOD_PIN_STATE_LOW);
            fprintf(logFile, "Deactivating relay at dawn (Lux: %d)\n", lux);
        }
    }
}

int main() {
    setupResources();

    // Signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = cleanupResources;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        controlRelay();
        usleep(5000000); // Poll every 5 seconds
    }

    return 0;
}

