#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_GPIO 4
#define RELAY_GPIO 17
#define TOUCH_PIN 7
#define RELAY_PIN 11

#define TOUCH_DEBOUNCE_MS 50
#define SLEEP_MS 10

volatile int touch_state = 0;
volatile int relay_state = 0;

void setup_gpios() {
    int ret;

    // Initialize GPIOs
    ret = gpiod_open(GPIOD, "r");
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_input(TOUCH_GPIO);
    if (ret != 0) {
        fprintf(stderr, "Error setting %u as input: %s\n", TOUCH_PIN, gpiod_errstr(ret));
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_direction_output(RELAY_GPIO, 1); // HIGH for ON
    if (ret != 0) {
        fprintf(stderr, "Error setting %u as output: %s\n", RELAY_PIN, gpiod_errstr(ret));
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }

    // Configure GPIO 17 for 5V relay
    ret = gpiod_set_value(RELAY_GPIO, 1); // Turn relay ON
    if (ret != 0) {
        fprintf(stderr, "Error setting relay ON: %s\n", gpiod_errstr(ret));
        gpiod_set_value(RELAY_GPIO, 0); // Turn relay OFF as a safety measure
        gpiod_close(GPIOD);
        exit(EXIT_FAILURE);
    }
}

void handle_touch() {
    int ret;
    struct gpiod_value value;

    // Read touch sensor
    ret = gpiod_get_value_single(TOUCH_GPIO, &value);
    if (ret != 0) {
        fprintf(stderr, "Error reading touch sensor: %s\n", gpiod_errstr(ret));
        return;
    }

    if (value.value == 1) {
        touch_state = 1;
        printf("Touched at: %Y\n", time(NULL));
    }

    // Debounce and wait for touch release
    if (touch_state && (millis() - last_touch_time) >= TOUCH_DEBOUNCE_MS) {
        last_touch_time = millis();
        if (gpiod_get_value_single(TOUCH_GPIO, &value) == 0) {
            printf("Released touch at: %Y\n", time(NULL));
            toggle_relay();
        }
    }
}

void toggle_relay() {
    int ret;
    if (relay_state == 1) {
        ret = gpiod_set_value(RELAY_GPIO, 0); // Turn relay OFF
        if (ret != 0) {
            fprintf(stderr, "Error turning relay OFF: %s\n", gpiod_errstr(ret));
        }
        relay_state = 0;
        printf("Relay OFF at: %Y\n", time(NULL));
    } else {
        ret = gpiod_set_value(RELAY_GPIO, 1); // Turn relay ON
        if (ret != 0) {
            fprintf(stderr, "Error turning relay ON: %s\n", gpiod_errstr(ret));
        }
        relay_state = 1;
        printf("Relay ON at: %Y\n", time(NULL));
    }
}

void cleanup() {
    gpiod_close(GPIOD);
    printf("Exiting cleanly...\n");
}

int main() {
    struct timespec timeout;
    sigset_t sigset;
    int ret;

    // Setup GPIOs
    setup_gpios();

    // Initialize signal handling
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Main loop
    while (1) {
        // Sleep and handle interrupts
        timeout.tv_sec = 0;
        timeout.tv_nsec = SLEEP_MS * 1000000;
        ret = nanosleep(&timeout, NULL);

        handle_touch();

        // Check for SIGINT
        if (sigismember(&sigset, SIGINT)) {
            printf("Received SIGINT, turning relay OFF and exiting...\n");
            toggle_relay();
            cleanup();
            exit(EXIT_SUCCESS);
        }
    }

    return 0;
}

