#define WATER_FLOW_THRESHOLD 5.0
#define HYSTERESIS 0.5
#define DEBOUNCE_MS 1000

// Mutex for protecting the shared pulse counter
pthread_mutex_t flow_sensor_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initialize_gpiod();
void setup_water_flow_sensor();
void setup_solenooid_valve();
void read_water_flow();
void handle_solenoid_state_change(int state);
void cleanup_resources();
void log_event(const char *event, double lpm, int state);
void sigint_handler(int signum);
void sigterm_handler(int signum);

int main() {
    srand(time(NULL));

    // Initialize GPIO library
    initialize_gpiod();

    // Setup water flow sensor
    setup_water_flow_sensor();

    // Setup solenoid valve
    setup_solenooid_valve();

    // Main loop
    while (1) {
        // Debounce water flow sensor
        pthread_mutex_lock(&flow_sensor_mutex);
        int pulse_count = read_water_flow();
        pthread_mutex_unlock(&flow_sensor_mutex);

        double lpm = (pulse_count * 1000.0) / 60.0; // Convert pulses per second to LPM

        // Check if flow exceeds threshold
        if (lpm > WATER_FLOW_THRESHOLD) {
            handle_solenoid_state_change(0); // Close solenoid
        } else if (lpm < WATER_FLOW_THRESHOLD - HYSTERESIS) {
            handle_solenoid_state_change(1); // Open solenoid
        }

        // Log events
        log_event("Water Flow", lpm, (int) (lpm > WATER_FLOW_THRESHOLD - HYSTERESIS));

        // Sleep for 1 second
        usleep(DEBOUNCE_MS * 1000000);
    }

    // Cleanup resources on exit
    cleanup_resources();

    return 0;
}

// Function to initialize the GPIO library
void initialize_gpiod() {
    int ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "gpiod_init failed: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

// Function to setup water flow sensor on GPIO 17
void setup_water_flow_sensor() {
    int ret = gpiod_direction_input(GPIO_WATER_FLOW);
    if (ret < 0) {
        fprintf(stderr, "gpiod_direction_input for water flow sensor failed: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

// Function to setup solenoid valve on GPIO 27
void setup_solenooid_valve() {
    int ret = gpiod_direction_output(GPIO_SOLENOID, 0); // Set to LOW (closed)
    if (ret < 0) {
        fprintf(stderr, "gpiod_direction_output for solenoid valve failed: %s\n", gpiod_errstr(ret));
        exit(EXIT_FAILURE);
    }
}

// Function to read water flow pulses
int read_water_flow() {
    int ret = gpiod_read(GPIO_WATER_FLOW);
    if (ret < 0) {
        fprintf(stderr, "gpiod_read for water flow sensor failed: %s\n", gpiod_errstr(ret));
        return 0; // Return 0 if reading fails
    }
    return ret; // Return actual pulse count
}

// Function to handle solenoid state change
void handle_solenoid_state_change(int state) {
    int ret = gpiod_write(GPIO_SOLENOID, state ? 0 : 1); // Set to HIGH (open) if flow below threshold, LOW (closed) otherwise
    if (ret < 0) {
        fprintf(stderr, "gpiod_write for solenoid valve failed: %s\n", gpiod_errstr(ret));
    }
}

// Function to cleanup resources
void cleanup_resources() {
    gpiod_cleanup();
    pthread_mutex_destroy(&flow_sensor_mutex);
    // No file handling here as the log file setup is assumed to be handled elsewhere
}

// Function to log events with timestamp
void log_event(const char *event, double lpm, int state) {
    char log_entry[256];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", timeinfo);

    sprintf(log_entry + strlen(log_entry), "Event: %s, LPM: %.1f, State: %d", event, lpm, state);

    FILE *file = fopen("water_flow.log", "a+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s\n", log_entry);
    fclose(file);
}

// SIGINT and SIGTERM handlers
void sigint_handler(int signum) {
    log_event("SIGINT received", 0.0, 1); // Log event and return solenoid to safe state
    handle_solenoid_state_change(1); // Open solenoid
    fclose(FILE* log_file_ptr = fopen("water_flow.log", "a+")); // Close log file
    pthread_mutex_destroy(&flow_sensor_mutex); // Destroy mutex
    exit(EXIT_FAILURE); // Exit program
}

void sigterm_handler(int signum) {
    sigint_handler(signum); // Forward to SIGINT handler
}

