#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/time.h>
#include <gpiod.h>
#include <hx711.h>

#define DATA_GPIO 23
#define SCK_GPIO 24
#define SERVO_PWM_GPIO 18

// Constants for GPIO setup
#define DATA_GPIO_NUM 23
#define SCK_GPIO_NUM 24
#define SERVO_PWM_GPIO_NUM 18

// HX711 configuration
#define HX711_ADDR 0x40
#define HX711_GAIN 128

// GPIO setup
gpiod_channel_t hx711_data_channel;
gpiod_channel_t hx711_clock_channel;
gpiod_channel_t servo_pwm_channel;

// TCP server setup
int server_fd = -1;
struct sockaddr_in server_addr;
socklen_t addrlen = sizeof(server_addr);

// HX711 instance
hx711_t hx711;

// Calibration factor from config.ini (default if not found)
double calibration_factor = 0.0;
char config_file_path[256] = "/path/to/config.ini";

// Dispensing log
FILE *dispensing_log = NULL;

// Signal handlers
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Clean shutdown of GPIO, sockets, and HX711
        // ...
        close(server_fd);
        gpiod_channel_unexport(&hx711_data_channel);
        gpiod_channel_unexport(&hx711_clock_channel);
        gpiod_channel_unexport(&servo_pwm_channel);
        fclose(dispensing_log);
        exit(0);
    }
}

int main() {
    // Initialize GPIO channels
    if (gpiod_channel_request(DATA_GPIO_NUM, GPIOD_OUT_INIT_LOW) < 0 ||
        gpiod_channel_request(SCK_GPIO_NUM, GPIOD_OUT_INIT_LOW) < 0 ||
        gpiod_channel_request(SERVO_PWM_GPIO_NUM, GPIOD_OUT_INIT_HIGH) < 0) {
        perror("Failed to request GPIO channels");
        return 1;
    }

    hx711_data_channel = gpiod_channel_get(DATA_GPIO_NUM);
    hx711_clock_channel = gpiod_channel_get(SCK_GPIO_NUM);
    servo_pwm_channel = gpiod_channel_get(SERVO_PWM_GPIO_NUM);

    // Initialize HX711
    if (hx711_init(HX711_ADDR, HX711_GAIN) < 0) {
        perror("HX711 initialization failed");
        return 1;
    }

    // Set up TCP server
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("Listen failed");
        close(server_fd);
        return 1;
    }

    // Signal handler setup
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Dispensing loop
    while (1) {
        // Accept new connection
        int client_fd = accept(server_fd, (struct sockaddr *)&server_addr, &addrlen);
        if (client_fd == -1) {
            perror("Accept failed");
            continue;
        }

        // Initialize structures for reading and writing
        hx711_read_config(hx711, HX711_CONFIG_READ_24);
        hx711_write_config(hx711, HX711_CONFIG_READ_24);

        // Dispense loop for each client
        char buffer[256];
        ssize_t bytes_read;
        while ((bytes_read = recv(client_fd, buffer, sizeof(buffer), 0)) > 0) {
            struct tm tm_now;
            time(&tm_now);

            // Parse target weight from client
            double target_weight = atof(buffer);

            // Open config.ini for calibration factor
            FILE *config_file = fopen(config_file_path, "r");
            if (config_file == NULL) {
                fprintf(stderr, "Failed to open config.ini for calibration factor.\n");
                continue;
            }

            // Read calibration factor
            if (fscanf(config_file, "%lf", &calibration_factor) != 1) {
                fprintf(stderr, "Failed to read calibration factor from config.ini.\n");
                fclose(config_file);
                continue;
            }
            fclose(config_file);

            // Start dispensing and wait for stabilization
            hx711_start(hx711);
            sleep(1);

            // Read actual weight
            double actual_weight = hx711_get_weight(hx711);

            // Append dispensing event to log
            fprintf(dispensing_log, "{\"date\": \"%s\", \"time\": %s, \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": null}\n",
                    ctime(&tm_now.time), // Format date and time
                    ctime(&tm_now.time), // Repeat for simplicity
                    target_weight,
                    actual_weight);

            // Map target weight to servo PWM range
            // Assuming a linear mapping for simplicity
            double mapped_pwm = (target_weight - calibration_factor * actual_weight) * 2000.0 / 1000.0;

            // Send actual weight back to client
            sprintf(buffer, "Actual weight: %.2f\n", actual_weight);
            if (send(client_fd, buffer, strlen(buffer), 0) < 0) {
                perror("Send failed");
                close(client_fd);
                continue;
            }

            // Stop HX711 and clean up
            hx711_stop(hx711);
            hx711_deinit(hx711);

            // Close client connection
            close(client_fd);

            // Handle cleanup and logging
            // ...
        }

        // Handle server shutdown
        // ...
    }

    // Clean up on exit
    // ...
    return 0;
}

