#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TOUCH_GPIO 4
#define RELAY_GPIO 17
#define DEBOUNCE_MS 50

// Function prototypes
void setup_gpios(void);
void handle_touch_event(struct gpiod_device *touch_dev);
void handle_relay_state_change(int state);
void cleanup_gpios(void);
void sigint_handler(int signum);
void sigterm_handler(int signum);

int main(int argc, char **argv) {
    // Check if -d option is provided
    if (argc > 1 && argv[1][0] == '-') {
        char *debounce_str = argv[1] + 1;
        if (strcmp(debounce_str, "d") == 0) {
            DEBOUNCE_MS = atoi(debounce_str + 1);
            if (DEBOUNCE_MS <= 0) {
                fprintf(stderr, "Invalid debounce time. Defaulting to 50ms.\n");
                DEBOUNCE_MS = 50;
            }
        } else {
            fprintf(stderr, "Unknown option: %s\n", argv[1]);
            return 1;
        }
    }

    // Initialize GPIO and setup touch sensor GPIO
    setup_gpios();

    // Main loop
    while (1) {
        // Poll touch sensor GPIO
        if (gpiod_event_get(&touch_dev, TOUCH_GPIO, GPIOD_EVENT_RISING) != 0) {
            perror("gpiod_event_get");
            continue;
        }

        // Debounce logic
        struct timespec timestamp;
        clock_gettime(CLOCK_REALTIME, &timestamp);
        long diff = timestamp.tv_sec * 1000000 + timestamp.tv_nsec - (clock_gettime(CLOCK_REALTIME, &timestamp) - (timestamp.tv_sec * 1000000 + timestamp.tv_nsec)).tv_nsec;

        if (diff >= DEBOUNCE_MS) {
            handle_touch_event(touch_dev);
        }

