#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define SERVO_FREQ_HZ 50
#define SERVO_PERIOD_MS (1000 / SERVO_FREQ_HZ)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define STEP_ANGLE 10
#define MIN_ANGLE 0
#define MAX_ANGLE 180

void setup_gpiod();
void cleanup_gpiod();
void set_servo_angle(int angle);
void handle_keys(int fd);
void handle_signal(int signum);

int main() {
    int angle = 90;
    int prev_angle = 90;
    int key;
    struct termios old_tio;

    // Setup GPIO
    setup_gpiod();

    // Set initial servo angle
    set_servo_angle(angle);

    // Prepare for raw keyboard input
    tcgetattr(STDIN_FILENO, &old_tio);
    struct termios new_tio = old_tio;
    new_tio.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_tio);

    signal(SIGINT, handle_signal);

    while (1) {
        // Read keypress
        key = read(STDIN_FILENO, &key, 1);

        if (key == 'q' || key == 'Q') {
            // Quit on 'q'
            break;
        }

        if (key == '+' || key == '-') {
            // Adjust angle
            int new_angle = prev_angle + (key == '+' ? STEP_ANGLE : -STEP_ANGLE);
            new_angle = MIN_ANGLE <= new_angle && new_angle <= MAX_ANGLE ? new_angle : (new_angle < MIN_ANGLE ? MIN_ANGLE : MAX_ANGLE);
            set_servo_angle(new_angle);
            printf("Angle: %d°\n", new_angle);
        }

        prev_angle = angle;
    }

    // Cleanup GPIO
    cleanup_gpiod();

    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &old_tio);

    return 0;
}

void setup_gpiod() {
    gpiod_driver_t *driver;
    int ret;

    // Open GPIO driver
    driver = gpiod_open(GPIOD, GPIOD_DIR_OUT_INIT_HIGH);
    if (driver == NULL) {
        fprintf(stderr, "Failed to open GPIO driver: %s\n", gpiod_error_string(driver));
        exit(EXIT_FAILURE);
    }

    // Set pin direction and configure PWM
    ret = gpiod_set_data_direction(driver, SERVO_PIN, GPIOD_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pin direction: %s\n", gpiod_error_string(driver));
        gpiod_close(driver);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_configPWM(driver, SERVO_PIN, SERVO_FREQ_HZ);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure PWM: %s\n", gpiod_error_string(driver));
        gpiod_close(driver);
        exit(EXIT_FAILURE);
    }

    // Start PWM on the pin
    ret = gpiod_pwm_start(driver, SERVO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to start PWM: %s\n", gpiod_error_string(driver));
        gpiod_close(driver);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpiod() {
    gpiod_stopPWM(GPIOD, SERVO_PIN);
    gpiod_close(GPIOD);
}

void set_servo_angle(int angle) {
    int pulse_width = (angle * 1000) / MAX_ANGLE * SERVO_MAX_PULSE_WIDTH + SERVO_MIN_PULSE_WIDTH;
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d, clamping to %d-%d\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        pulse_width = (pulse_width < SERVO_MIN_PULSE_WIDTH ? SERVO_MIN_PULSE_WIDTH : SERVO_MAX_PULSE_WIDTH);
    }

    // Set the pulse width using gpiod API
    int ret = gpiod_pwm_set_value(GPIOD, SERVO_PIN, pulse_width);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM value: %s\n", gpiod_error_string(GPIOD));
        exit(EXIT_FAILURE);
    }
}

void handle_keys(int fd) {
    char key;

    while (1) {
        // Read a keypress
        read(fd, &key, 1);

        // Check for special keys
        if (key == 'q' || key == 'Q') {
            // Quit on 'q'
            break;
        }

        // Handle '+' and '-' keys
        if (key == '+' || key == '-') {
            set_servo_angle(angle + (key == '+' ? STEP_ANGLE : -STEP_ANGLE));
            printf("Angle: %d°\n", angle);
        }
    }
}

void handle_signal(int signum) {
    // Stop PWM and gracefully exit
    gpiod_stopPWM(GPIOD, SERVO_PIN);
    printf("PWM stopped due to signal.\n");
    exit(EXIT_SUCCESS);
}

