#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <sys/stat.h>

#define GPIO_NUM 17
#define DEBOUNCE_MS 2
#define INTERVAL_MS 5000

// Function prototypes
void setup_gpiod();
void handle_interrupts(int signum);
void compute_rpm();
void write_rpm_to_log();
void cleanup();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_interrupts);
    signal(SIGTERM, handle_interrupts);

    // Setup GPIO
    setup_gpiod();

    // Main loop
    while (1) {
        compute_rpm();
        write_rpm_to_log();
        usleep(INTERVAL_MS * 1000); // Wait for 5 seconds
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

// Function to initialize libgpiod
void setup_gpiod() {
    int ret;

    // Open GPIO device
    gpiod_open(&gpiod, GPIO_NUM, GPIOD_OPEN_RWS);

    // Enable GPIO 17 with internal pull-up
    ret = gpiod_set_data_direction(gpiod, GPIO_NUM, GPIOD_IN);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction: %s\n", gpiod_error_string(gpiod));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_pull_up(gpiod, GPIO_NUM, GPIOD_PULLUP);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up: %s\n", gpiod_error_string(gpiod));
        exit(EXIT_FAILURE);
    }

    // Enable edge detection on rising edge
    ret = gpiod_set_mode(gpiod, GPIO_NUM, GPIOD_MODE_EDGE_RISING);
    if (ret < 0) {
        fprintf(stderr, "Error setting mode: %s\n", gpiod_error_string(gpiod));
        exit(EXIT_FAILURE);
    }

    // Set debounce window
    ret = gpiod_set_debounce(gpiod, GPIO_NUM, DEBOUNCE_MS);
    if (ret < 0) {
        fprintf(stderr, "Error setting debounce: %s\n", gpiod_error_string(gpiod));
        exit(EXIT_FAILURE);
    }
}

// Signal handler to stop the main loop and clean up
void handle_interrupts(int signum) {
    // Stop the main loop
    printf("Interrupt received, stopping...\n");

    // Release GPIO line
    gpiod_set_direction(gpiod, GPIO_NUM, GPIOD_OUTPUT);

    // Close the GPIO device
    gpiod_close(gpiod);

    // Clean up log file
    unlink("motor_rpm.log");

    // Exit cleanly
    exit(EXIT_SUCCESS);
}

// Function to compute RPM from pulses
void compute_rpm() {
    static struct timespec last_time;
    static uint32_t pulses = 0;

    // Get current monotonic time
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    // Read GPIO 17 value
    int value = gpiod_get_value(gpiod, GPIO_NUM);

    // Check for rising edge
    if (value == 1) {
        pulses++;

        // Debounce
        if (pulses > 0 && (clock_gettime(CLOCK_MONOTONIC, &last_time) - last_time) > (DEBOUNCE_MS * 1000000)) {
            pulses = 0; // Reset debounce counter
        }
    }

    // Compute RPM
    double rpm = (pulses * 60) / (DEBOUNCE_MS * 1000000.0);

    // Format and write to log file
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%3NZ", localtime(&last_time.tv_sec));
    char line[256];
    snprintf(line, sizeof(line), "%s,%f\n", timestamp, rpm * 100.0);

    // Write to log file
    FILE *log_file = fopen("motor_rpm.log", "a+");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fwrite(line, sizeof(char), strlen(line), log_file);
    fclose(log_file);

    // Print to stdout
    printf("RPM: %.2f\n", rpm);
}

// Function to write RPM to log file
void write_rpm_to_log() {
    // Format and write to log file
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%3NZ", localtime(time(NULL)));
    char line[256];
    snprintf(line, sizeof(line), "%s,%f\n", timestamp, (double)g_rpm / 100.0);

    // Write to log file
    FILE *log_file = fopen("motor_rpm.log", "a+");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fwrite(line, sizeof(char), strlen(line), log_file);
    fclose(log_file);
}

// Function to clean up resources
void cleanup() {
    // Close log file
    fclose(log_file);

    // Close GPIO device
    gpiod_close(gpiod);
}

// Global variable to store the current RPM
double g_rpm = 0.0;

// Log file pointer
FILE *log_file = NULL;

