        fprintf(stderr, "Error configuring GPIO %u interrupt: %s\n", GPIO_FLOW, gpiod_errstr(err));
        exit(EXIT_FAILURE);
    }
}

void initialize_pwm(uint32_t frequency) {
    uint32_t period = 1000000 / frequency;
    uint32_t duty_cycle = (uint32_t)(kp * target_flow);

    // Set PWM parameters
    gpiod_set_value(GPIO_PWM_0, duty_cycle);
    gpiod_set_freq(GPIO_PWM_0, frequency);
}

void handle_interrupt(void *arg) {
    flow_count++;
    timestamp.tv_sec = time(NULL);
    timestamp.tv_nsec = 0;
    struct timespec curr_time;
    clock_gettime(CLOCK_REALTIME, &curr_time);

    double elapsed_seconds = (curr_time.tv_sec - last_flow_time.tv_sec) + (curr_time.tv_nsec - last_flow_time.tv_nsec) / 1000000000.0;
    double flow_rate = (double)flow_count / elapsed_seconds;

    if (flow_rate > TARGET_FLOW_MAX || flow_rate < TARGET_FLOW_MIN) {
        flow_rate = fminf(TARGET_FLOW_MAX, fmaxf(TARGET_FLOW_MIN, flow_rate));
    }

    printf("Timestamp: %ld, Flow Rate: %.2f L/min, Valve Position: %u\n", timestamp.tv_sec, flow_rate, gpiod_get_value(GPIO_PWM_0));

    // Update flow log
    if (flow_log_fd != -1) {
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timestamp);
        fprintf(flow_log_fd, "%s,%f,%u\n", buffer, flow_rate, gpiod_get_value(GPIO_PWM_0));
    }

    last_flow_time = curr_time;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate_LPM>\n", argv[0]);
        return EXIT_FAILURE;
    }

    target_flow = atof(argv[1]);

    if (target_flow < TARGET_FLOW_MIN || target_flow > TARGET_FLOW_MAX) {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    setup_gpios();

    flow_log_fd = open("flow_log.csv", O_WRONLY | O_CREAT, 0666);
    if (flow_log_fd == -1) {
        perror("Failed to open flow_log.csv");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    struct sigaction sa = { .sa_handler = SIG_DFL, .sa_flags = 0 };
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        initialize_pwm(PWM_FREQ_HZ);
        usleep(100000); // Sleep for 100ms
    }

    // Graceful shutdown on SIGINT/SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Set PWM duty cycle to zero
    gpiod_set_value(GPIO_PWM_0, 0);
    // Drive GPIO_EN_DIR low
    gpiod_set_value(GPIO_EN_DIR, 0);

    // Close flow log file
    close(flow_log_fd);

    // Cleanly terminate libgpiod
    gpiod_exit();

    return EXIT_SUCCESS;
}

void sig_handler(int signum) {
    gpiod_set_value(GPIO_PWM_0, 0); // Set PWM duty cycle to zero
    gpiod_set_value(GPIO_EN_DIR, 0); // Drive GPIO_EN_DIR low
    close(flow_log_fd); // Close flow log file
    gpiod_exit(); // Cleanly terminate libgpiod
    exit(EXIT_SUCCESS); // Exit the program
}
