    if (log_fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_resources() {
    gpiod_output_free(lock1_control);
    gpiod_output_free(lock2_control);
    gpio_free(pin_button);

    if (log_fd != -1) {
        close(log_fd);
    }

    gpiod_spi_message_free(message);
    spi_transfer_free(tx);
    spi_transfer_free(rx);
    spi_device_free(spi_device);
}

void sigint_handler(int signum) {
    cleanup_resources();
    exit(EXIT_FAILURE);
}

