#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>

#define MPR121_ADDR 0x5C
#define RELAY_GPIO 17 // BCM 17

// Constants for MPR121 configuration
#define TOUCH_THRESHOLD 5
#define RELEASE_THRESHOLD 5
#define FILTERING_ENABLE 0x01
#define RUN_MODE 0x02

// GPIO pin for relay control
static const struct gpio_desc *relay_gpio;

// Function prototypes
void setup_mpr121(const struct i2c_dev *i2c_dev);
void read_mpr121_status(const struct i2c_dev *i2c_dev);
void handle_touch(const struct mpr121_data *mpr121_data, int electrode);
void handle_no_touch(const struct mpr121_data *mpr121_data);
void toggle_relay(const struct mpr121_data *mpr121_data);
void append_to_log(const char *message);
void cleanup();

// Main function
int main(void) {
    // Initialize GPIO for relay control
    relay_gpio = gpiod_get_lookup_by_name("gpio17");
    if (!relay_gpio) {
        fprintf(stderr, "Error: Could not find GPIO 17.\n");
        return EXIT_FAILURE;
    }

    // Signal handler for SIGINT (Ctrl-C)
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize I2C device
    const struct i2c_dev *i2c_dev = i2c_dev_open(1, 0);
    if (!i2c_dev) {
        fprintf(stderr, "Error: Failed to open I2C bus 1.\n");
        return EXIT_FAILURE;
    }

    // Setup MPR121
    setup_mpr121(i2c_dev);

    // Main loop
    while (1) {
        read_mpr121_status(i2c_dev);

        // Check for touched electrodes
        for (int i = 0; i < 12; ++i) {
            if (mpr121_data->touches[i] > TOUCH_THRESHOLD) {
                handle_touch(mpr121_data, i);
            }
        }

        // Check for no touched electrodes
        if (mpr121_data->touches_count == 0) {
            handle_no_touch(mpr121_data);
        }

        // Toggle relay based on touch status
        toggle_relay(mpr121_data);

        // Append relay state to log file
        append_to_log("Relay state: Touched\n");

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup
    cleanup();

    // Close I2C device
    i2c_dev_close(i2c_dev);

    return EXIT_SUCCESS;
}

// Function to setup MPR121
void setup_mpr121(const struct i2c_dev *i2c_dev) {
    // Perform soft reset
    if (i2c_smbus_write_byte_data(i2c_dev, MPR121_ADDR, 0x0F) != 0) {
        fprintf(stderr, "Error: Failed to perform soft reset on MPR121.\n");
        return;
    }

    // Configure filtering and run mode
    if (i2c_smbus_write_byte_data(i2c_dev, MPR121_ADDR, FILTERING_ENABLE | RUN_MODE) != 0) {
        fprintf(stderr, "Error: Failed to configure MPR121.\n");
        return;
    }
}

// Function to read MPR121 status
void read_mpr121_status(const struct i2c_dev *i2c_dev) {
    if (i2c_smbus_read_byte_data(i2c_dev, MPR121_ADDR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to read MPR121 status.\n");
        return;
    }

    // Check if MPR121 is present
    if (mpr121_data->version != 0x01) {
        fprintf(stderr, "Error: MPR121 version not supported.\n");
        return;
    }
}

// Function to handle touched electrode
void handle_touch(const struct mpr121_data *mpr121_data, int electrode) {
    // Toggle relay HIGH
    if (gpiod_set_value(relay_gpio, 1) < 0) {
        fprintf(stderr, "Error: Failed to set relay HIGH.\n");
        return;
    }

    // Append to log
    append_to_log("Relay state: Touched, electrode " INT_TO_STR(electrode) "\n");
}

// Function to handle no touched electrodes
void handle_no_touch(const struct mpr121_data *mpr121_data) {
    // Toggle relay LOW
    if (gpiod_set_value(relay_gpio, 0) < 0) {
        fprintf(stderr, "Error: Failed to set relay LOW.\n");
        return;
    }

    // Append to log
    append_to_log("Relay state: Not touched\n");
}

// Function to toggle relay based on touch status
void toggle_relay(const struct mpr121_data *mpr121_data) {
    if (mpr121_data->touches_count > 0) {
        handle_touch(mpr121_data, 0); // Assuming electrode 0 is the first one
    } else {
        handle_no_touch(mpr121_data);
    }
}

// Function to append to log file
void append_to_log(const char *message) {
    FILE *log_file = fopen("relay_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file for appending.\n");
        return;
    }

    fprintf(log_file, "%s", message);
    fclose(log_file);
}

// Function to cleanup resources
void cleanup() {
    // Close relay GPIO
    gpiod_set_value_relaxed(relay_gpio, 0);

    // Close I2C device
    i2c_dev_close(i2c_dev);
}

// Helper function to convert integer to string
char *INT_TO_STR(int num) {
    static char buffer[10];
    sprintf(buffer, "%d", num);
    return buffer;
}

// SIGINT signal handler
void sigint_handler(int signum) {
    // Clean up and exit
    cleanup();
    exit(EXIT_FAILURE);
}

