#define RELAY_OFF_PIN 0

FILE *logFile = NULL;
char logFileName[] = "valve_log.txt";

volatile sig_atomic_t shouldExit = 0;

void setup_gpios(void) {
    struct gpiod_dir *dir;
    struct gpiod_cdev *cdev;
    int ret;

    // Initialize GPIO library
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error initializing GPIO: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    // Open GPIO controllers
    dir = gpiod_get_dir();
    for (cdev = gpiod_cdev_first(dir); cdev; cdev = gpiod_cdev_next(cdev)) {
        if (cdev->dev.of_node->label == "bcm2835-gpio") {
            break;
        }
    }
    if (!cdev) {
        fprintf(stderr, "Failed to find BCM2835 GPIO controller.\n");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins for the relays
    ret = gpiod_cdev_open(cdev);
    if (ret < 0) {
        fprintf(stderr, "Error opening GPIO controller: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins for Valve 1 and Valve 2
    ret = gpiod_set_data_dir(cdev, VALVE_1_GPIO, GPIOD_OUT_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to output: %d\n", VALVE_1_GPIO, ret);
        exit(EXIT_FAILURE);
    }
    gpiod_write(cdev, VALVE_1_GPIO, RELAY_ON_PIN);

    ret = gpiod_set_data_dir(cdev, VALVE_2_GPIO, GPIOD_OUT_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to output: %d\n", VALVE_2_GPIO, ret);
        exit(EXIT_FAILURE);
    }
    gpiod_write(cdev, VALVE_2_GPIO, RELAY_ON_PIN);

    // Close GPIO controller
    gpiod_cdev_close(cdev);
}

void cleanup_gpios(void) {
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }

    // Close GPIO controller
    struct gpiod_cdev *cdev = gpiod_cdev_first(gpiod_get_dir());
    while (cdev) {
        if (cdev->dev.of_node->label == "bcm2835-gpio") {
            gpiod_cdev_close(cdev);
            break;
        }
        cdev = gpiod_cdev_next(cdev);
    }

    gpiod_exit();
}

void handle_signal(int signum) {
    shouldExit = 1;
}

int main(void) {
    setup_gpios();

    while (!shouldExit) {
        // Schedule for Valve 1
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[50];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", &ts);

        fprintf(logFile, "Activating Valve 1 at %s\n", timestamp);
        usleep(500000); // 500 ms
        gpiod_write(gpiod_cdev_get(cdev), VALVE_1_GPIO, RELAY_OFF_PIN);

        // Pause for 5 seconds
        sleep(5);

        // Schedule for Valve 2
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", &ts);
        fprintf(logFile, "Activating Valve 2 at %s\n", timestamp);
        usleep(1000000); // 1000 ms
        gpiod_write(gpiod_cdev_get(cdev), VALVE_2_GPIO, RELAY_OFF_PIN);

        // Pause for 10 seconds
        sleep(10);
    }

    cleanup_gpios();
    return 0;
}

