#include <errno.h>

#define I2C_ADDR 0x5A // MPR121 I2C address
#define RELAY_GPIO 17 // GPIO17 for relay control (BCM mode)
#define TOUCH_ELECTRODES 12

// MPR121 configuration constants
#define TOUCH_THRESHOLD 10
#define RELEASE_THRESHOLD 5
#define FILTER_ENABLE 1
#define CHARGE_TIME 50
#define CURRENT 50

// GPIO numbers for MPR121 SDA and SCL
#define MPR121_SDA_GPIO 2
#define MPR121_SCL_GPIO 3

// Function prototypes
void setup_mpr121(const int *gpio_pins);
void configure_mpr121(const int touch_threshold, const int release_threshold, const int filter_enable, const uint16_t charge_time, const int current);
void monitor_touches(void);
void handle_signal(int signum);

int main(void) {
    // Initialize GPIO
    int gpio17_fd = -1;
    if ((gpio17_fd = gpiod_open(GPIOD_DIR_OUT, RELAY_GPIO, GPIOD_OPEN_OWNED)) < 0) {
        perror("gpiod_open for GPIO17");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    int i2c_fd = -1;
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open I2C bus");
        close(gpio17_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO17 as output
    if (gpiod_direction_output(gpio17_fd, 1) < 0) {
        perror("gpiod_direction_output for GPIO17");
        close(i2c_fd);
        close(gpio17_fd);
        return EXIT_FAILURE;
    }

    // Setup MPR121
    setup_mpr121(&MPR121_SDA_GPIO, &MPR121_SCL_GPIO);

    // Configure MPR121
    configure_mpr121(TOUCH_THRESHOLD, RELEASE_THRESHOLD, FILTER_ENABLE, CHARGE_TIME, CURRENT);

    // Start monitoring touches
    monitor_touches();

    // Handle signals
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        usleep(100000); // 100 ms delay
    }

    // Clean up on exit
    close(i2c_fd);
    close(gpio17_fd);

    return EXIT_SUCCESS;
}

// Function to setup MPR121 on the I2C bus
void setup_mpr121(const int *gpio_pins) {
    struct gpiod_dir_config sda_config, scl_config;
    sda_config.direction = GPIOD_DIR_OUT_INIT_LOW;
    scl_config.direction = GPIOD_DIR_OUT_INIT_LOW;

    if (gpiod_direction_output(gpio_pins[0], 0) < 0 || gpiod_direction_output(gpio_pins[1], 0) < 0) {
        fprintf(stderr, "Error setting GPIO pins for I2C lines to output.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C device
    if (i2c_smbus_write_byte_data(i2c_fd, I2C_ADDR, 0x0D) < 0) {
        perror("Error writing to MPR121 to enter stop mode");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins as I2C SDA and SCL
    if (gpiod_set_value(gpio_pins[0], 1) || gpiod_set_value(gpio_pins[1], 1)) {
        fprintf(stderr, "Error setting GPIO pins for I2C lines high.\n");
        exit(EXIT_FAILURE);
    }
}

// Function to configure MPR121
void configure_mpr121(const int touch_threshold, const int release_threshold, const int filter_enable, const uint16_t charge_time, const int current) {
    uint8_t config_data[] = {
        0x00, // Start configuration
        (filter_enable ? 0x01 : 0x00), // Filter enable
        (charge_time & 0xFF), // Charge time
        (current & 0x0F), // Electrode current
        (touch_threshold & 0x0F), // Touch threshold
        (release_threshold & 0x0F), // Release threshold
        0x00 // End configuration
    };

    if (i2c_smbus_write_i2c_block_data(i2c_fd, I2C_ADDR, 0x14, 8, config_data) < 0) {
        perror("Error writing to MPR121 to configure settings");
        exit(EXIT_FAILURE);
    }
}

// Function to monitor touches and toggle GPIO17
void monitor_touches(void) {
    uint8_t touch_status;
    if (i2c_smbus_read_byte_data(i2c_fd, I2C_ADDR, 0x0B) < 0) {
        perror("Error reading touch status from MPR121");
        return;
    }

    touch_status = i2c_smbus_read_byte_data(i2c_fd, I2C_ADDR, 0x0B);

    if (touch_status > 0) {
        // Toggle GPIO17 (BCM mode, active high)
        if (gpiod_set_value(gpio17_fd, 0) < 0) {
            perror("Error toggling GPIO17");
        } else {
            printf("Relay toggled due to touch.\n");
        }
    }

    usleep(100000); // 100 ms delay
}

// Signal handler to perform graceful shutdown
void handle_signal(int signum) {
    // Close I2C and GPIO resources
    close(i2c_fd);
    close(gpio17_fd);

    // Exit the program
    exit(EXIT_SUCCESS);
}

