#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <signal.h>

#include <libgpiod/gpiod.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define LOG_FILE_PATH "door_events.log"

// Constants for GPIO operations
#define PIR_PIN 0x03 // BCM 17
#define RELAY_PIN 0x02 // BCM 18
#define PULL_DOWN 0x01

// GPIO context for PIR sensor
gpiod_context *pir_context;
gpiod_cdev *pir_device;

// GPIO context for relay
gpiod_context *relay_context;
gpiod_cdev *relay_device;

// File descriptor for log file
int log_fd;

// Function prototypes
void initialize_pir();
void initialize_relay();
void cleanup();
void motion_detected(gpiod_cdev *dev);
void door_unlocked();
void rate_limited();
void handle_signal(int signum);

int main() {
    // Initialize GPIO contexts and devices
    initialize_pir();
    initialize_relay();

    // Open log file for writing
    log_fd = open(LOG_FILE_PATH, O_WRONLY | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        exit(1);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        // Poll PIR sensor
        if (gpiod_c_read(pir_device, PIR_PIN, GPIOD_INPUT) == GPIOD_INPUT_LOW) {
            motion_detected(pir_device);
        }

        // Poll relay status
        if (gpiod_c_read(relay_device, RELAY_PIN, GPIOD_OUTPUT) == GPIOD_OUTPUT_LOW) {
            door_unlocked();
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up on normal termination or SIGINT
    cleanup();

    return 0;
}

// Function to initialize PIR GPIO
void initialize_pir() {
    pir_context = gpiod_get_context_by_name("BCM", "gpio17");
    if (!pir_context) {
        fprintf(stderr, "Error: PIR GPIO initialization failed\n");
        exit(1);
    }

    pir_device = gpiod_open(pir_context, PIR_PIN, GPIOD_IN Pull_DOWN);
    if (!pir_device) {
        fprintf(stderr, "Error: PIR GPIO open failed\n");
        gpiod_close(pir_context);
        exit(1);
    }
}

// Function to initialize relay GPIO
void initialize_relay() {
    relay_context = gpiod_get_context_by_name("BCM", "gpio18");
    if (!relay_context) {
        fprintf(stderr, "Error: Relay GPIO initialization failed\n");
        exit(1);
    }

    relay_device = gpiod_open(relay_context, RELAY_PIN, GPIOD_OUT_INIT_LOW);
    if (!relay_device) {
        fprintf(stderr, "Error: Relay GPIO open failed\n");
        gpiod_close(relay_context);
        exit(1);
    }
}

// Function to cleanup GPIO and log file
void cleanup() {
    // Close log file
    close(log_fd);

    // Release GPIO devices
    gpiod_close(pir_device);
    gpiod_close(relay_device);

    // Release GPIO contexts
    gpiod_put_context(pir_context);
    gpiod_put_context(relay_context);
}

// Callback for motion detection
void motion_detected(gpiod_cdev *dev) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    // Write timestamp to log file
    char timestamp[23];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &ts);
    write(log_fd, timestamp, strlen(timestamp));

    // Unlock the door strike
    door_unlocked();

    // Implement rate limiting
    time_t now = time(NULL);
    if (now >= ts.tv_sec + 2) {
        rate_limited();
    }
}

// Function to unlock the door strike
void door_unlocked() {
    // Activate relay for 500 ms
    struct timespec duration = { .tv_sec = 0, .tv_nsec = 500000000 };
    gpiod_c_set_value(relay_device, RELAY_PIN, GPIOD_OUTPUT_HIGH, &duration);
    sleep(0.5); // Wait for 500 ms
    gpiod_c_set_value(relay_device, RELAY_PIN, GPIOD_OUTPUT_LOW, NULL);
}

// Function to handle rate-limited events
void rate_limited() {
    // Write timestamp to log file
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", NULL);
    write(log_fd, timestamp, strlen(timestamp));

    // Reset rate limit
    time_t now = time(NULL);
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    // Clean up and exit
    cleanup();
    exit(0);
}

