    gpiod_c_set_value(relay_device, RELAY_PIN, GPIOD_OUTPUT_HIGH, &duration);
    sleep(0.5); // Wait for 500 ms
    gpiod_c_set_value(relay_device, RELAY_PIN, GPIOD_OUTPUT_LOW, NULL);
