#include <sys/mman.h>
#include <gpiod.h>

#define HX711_DATA_GPIO 4
#define HX711_CLOCK_GPIO 17
#define LOCK_GPIO 27

#define SCALE_DEFAULT 1.0
#define OFFSET_DEFAULT 0.0

#define CALIBRATION_FILE_PATH "calibration.txt"
#define WEIGHT_THRESHOLD_KG 10.0

volatile sig_atomic_t sigIntReceived = 0;

// Structure to hold HX711 calibration data
typedef struct {
    double scale_factor;
    double offset;
} HX711Calibration;

// Function prototypes
void initialize_gpiod();
void cleanup_gpiod();
void read_hx711(void);
void engage_lock(double weight);
void handle_signal(int signum);
void write_calibration_to_file(HX711Calibration calibration);
void read_calibration_from_file(HX711Calibration *calibration);
void startup_calibration(double *reading, int samples);
void log_weight(double weight, const char *timestamp);

int main() {
    // Initialize GPIO
    initialize_gpiod();

    // Load calibration data
    HX711Calibration calibration;
    read_calibration_from_file(&calibration);

    // Startup calibration
    double startup_reading[100];
    startup_calibration(startup_reading, 100);

    double offset_calculated = 0.0;
    for (int i = 0; i < 100; ++i) {
        offset_calculated += startup_reading[i];
    }
    offset_calculated /= 100.0;
    calibration.offset = offset_calculated;

    // Main loop
    while (1) {
        double weight = read_hx711();

        // Check for signal
        if (sigIntReceived) {
            cleanup_gpiod();
            break;
        }

        // Engage lock if weight exceeds threshold
        if (weight > WEIGHT_THRESHOLD_KG) {
            engage_lock(weight);
        }

        // Log weight
        log_weight(weight, "Weight: " __TIME__);

        // Write calibration back to file if updated
        if (calibration.offset != OFFSET_DEFAULT) {
            write_calibration_to_file(calibration);
        }

        usleep(500 * 1000); // Sleep for 500 ms
    }

    // Clean up on exit
    cleanup_gpiod();

    return 0;
}

// Function to initialize GPIO
void initialize_gpiod() {
    int error;

    // Initialize GPIO driver
    gpiod_init();

    // Open GPIO pins
    int hx711_data_fd = open("/dev/gpio4", O_RDWR);
    int hx711_clock_fd = open("/dev/gpio17", O_RDWR);
    int lock_fd = open("/dev/gpio27", O_RDWR);

    if (hx711_data_fd == -1 || hx711_clock_fd == -1 || lock_fd == -1) {
        perror("Failed to open GPIO pins");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO pins
    gpiod_set_data_direction(hx711_data_fd, GPIO_DIR_IN);
    gpiod_set_data_direction(hx711_clock_fd, GPIO_DIR_IN);
    gpiod_set_direction(lock_fd, GPIO_DIR_OUT);

    // Set initial state (input for HX711, output for lock)
    gpiod_write(hx711_data_fd, 0);
    gpiod_write(hx711_clock_fd, 0);
    gpiod_write(lock_fd, 0); // Low state

    error = gpiod_get_value(hx711_data_fd);
    if (error) {
        perror("Failed to read initial state from HX711 data pin");
        exit(EXIT_FAILURE);
    }

    error = gpiod_get_value(hx711_clock_fd);
    if (error) {
        perror("Failed to read initial state from HX711 clock pin");
        exit(EXIT_FAILURE);
    }

    // Set lock pin to high state
    gpiod_write(lock_fd, 1);
}

// Function to cleanup GPIO
void cleanup_gpiod() {
    // Close GPIO file descriptors
    close(hx711_data_fd);
    close(hx711_clock_fd);
    close(lock_fd);

    // Uninitialize GPIO driver
    gpiod_uninit();
}

// Function to read HX711
double read_hx711() {
    double weight = 0.0;
    int hx711_data, hx711_clock;

    // Read data and clock from HX711
    hx711_data = gpiod_read(hx711_data_fd);
    hx711_clock = gpiod_read(hx711_clock_fd);

    // Perform HX711 read
    if (hx711_data && hx711_clock) {
        weight = hx711_read(hx711_data, hx711_clock);
    }

    return weight;
}

// Function to engage the lock
void engage_lock(double weight) {
    if (weight > WEIGHT_THRESHOLD_KG) {
        gpiod_write(lock_fd, 1); // Set GPIO27 high to engage lock
    } else {
        gpiod_write(lock_fd, 0); // Set GPIO27 low to disengage lock
    }
}

// Signal handler for SIGINT
void handle_signal(int signum) {
    sigIntReceived = 1;
}

// Function to write calibration to file
void write_calibration_to_file(HX711Calibration calibration) {
    FILE *file = fopen(CALIBRATION_FILE_PATH, "w");

    if (file == NULL) {
        perror("Failed to open calibration file for writing");
        return;
    }

    fprintf(file, "scale_factor=%f\n", calibration.scale_factor);
    fprintf(file, "offset=%f\n", calibration.offset);

    fclose(file);
}

// Function to read calibration from file
void read_calibration_from_file(HX711Calibration *calibration) {
    FILE *file = fopen(CALIBRATION_FILE_PATH, "r");

    if (file == NULL) {
        // Fall back to default calibration
        calibration->scale_factor = SCALE_DEFAULT;
        calibration->offset = OFFSET_DEFAULT;
        return;
    }

    // Read scale factor
    if (fscanf(file, "scale_factor=%f", &calibration->scale_factor) != 1) {
        fclose(file);
        return;
    }

    // Read offset
    if (fscanf(file, "offset=%f", &calibration->offset) != 1) {
        fclose(file);
        return;
    }

    fclose(file);
}

// Startup calibration function
void startup_calibration(double *reading, int samples) {
    // Perform averaging
    for (int i = 0; i < samples; ++i) {
        reading[i] = 0.0;
    }

    for (int i = 0; i < samples; ++i) {
        reading[i] += *reading;
    }

    for (int i = 0; i < samples; ++i) {
        reading[i] /= samples;
    }
}

// Function to log weight with timestamp
void log_weight(double weight, const char *timestamp) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: Weight: %.2f kg\n", buffer, weight);
}

