            check_rain_sensor();
            last_rain_check = time(NULL);
        }

        // Check for SIGINT or SIGTERM
        if (wait(NULL) > 0) {
            // Graceful shutdown
            cleanup_gpios();
            exit(0);
        }
    }

    return 0;
