    // Reserve GPIO pins for exclusive use
    rc = gpiod_request(RAIN_SENSOR_PIN, GPIOD_REQUEST_EXCLUSIVE);
    if (rc != 0) {
        fprintf(stderr, "Error reserving GPIO %d: %s\n", RAIN_SENSOR_PIN, gpiod_get_name(rc));
        exit(1);
    }

    rc = gpiod_request(MOTOR_DRIVER_IN1_PIN, GPIOD_REQUEST_EXCLUSIVE);
    if (rc != 0) {
        fprintf(stderr, "Error reserving GPIO %d: %s\n", MOTOR_DRIVER_IN1_PIN, gpiod_get_name(rc));
        gpiod_release(RAIN_SENSOR_PIN);
        exit(1);
    }

    rc = gpiod_request(MOTOR_DRIVER_IN2_PIN, GPIOD_REQUEST_EXCLUSIVE);
    if (rc != 0) {
        fprintf(stderr, "Error reserving GPIO %d: %s\n", MOTOR_DRIVER_IN2_PIN, gpiod_get_name(rc));
        gpiod_release(MOTOR_DRIVER_IN1_PIN);
        exit(1);
    }

    rc = gpiod_request(PWM_ENABLE_PIN, GPIOD_REQUEST_EXCLUSIVE);
    if (rc != 0) {
        fprintf(stderr, "Error reserving GPIO %d: %s\n", PWM_ENABLE_PIN, gpiod_get_name(rc));
        gpiod_release(MOTOR_DRIVER_IN2_PIN);
        gpiod_release(MOTOR_DRIVER_IN1_PIN);
        exit(1);
    }

    // Set up GPIO pins for motor control
    gpiod_set_data_dir(MOTOR_DRIVER_IN1_PIN, MOTOR_ON_HIGH);
    gpiod_set_data_dir(MOTOR_DRIVER_IN2_PIN, MOTOR_ON_LOW);

    // Set up PWM on PWM_ENABLE_GPIO
    gpiod_set pwm_config_t pwm_config = {
