        gpiod_set_data(MOTOR_DRIVER_IN1_PIN, MOTOR_ON_HIGH);
        gpiod_set_data(MOTOR_DRIVER_IN2_PIN, MOTOR_ON_LOW);
        gpiod_enable_pwm(PWM_ENABLE_PIN);
    } else {
        gpiod_set_data(MOTOR_DRIVER_IN1_PIN, 0);
        gpiod_set_data(MOTOR_DRIVER_IN2_PIN, 0);
        gpiod_disable_pwm(PWM_ENABLE_PIN);
    }

    // Wait for the motor to operate for 5 seconds
    usleep(MOTOR_ON_DURATION * 1000);
