#define GPIO_NUM_DT 23 // GPIO 23 for HX711 Data line (DT)
#define GPIO_NUM_SCK 24 // GPIO 24 for HX711 Clock line (SCK)
#define GPIO_NUM_LOCK 17 // GPIO 17 for Solenoid Lock

#define HX711_ADDR 0x40 // Default I2C address of HX711
#define HX711_DATA_PIN 0 // GPIO pin connected to HX711 Data line (DT)
#define HX711_CLOCK_PIN 1 // GPIO pin connected to HX711 Clock line (SCK)

#define STOCK_THRESHOLD 100 // Minimum weight threshold in grams

// Function prototypes
void setup_hardware(void);
void read_weight(uint16_t* weight);
void activate_lock(void);
void cleanup_resources(void);
void handle_signal(int signum);
void log_event(const char* message, time_t timestamp);

int main(void) {
    // Initialize global variables
    uint16_t weight;
    time_t current_time;
    int fd;
    char buffer[1024];

    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Setup hardware
    setup_hardware();

    while (1) {
        // Get current time
        current_time = time(NULL);

        // Read weight
        if (read_weight(&weight)) {
            log_event("Failed to read weight.", current_time);
            continue;
        }

        // Check if weight is below threshold
        if (weight < STOCK_THRESHOLD) {
            log_event("Weight below threshold, activating lock.", current_time);
            activate_lock();
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup resources
    cleanup_resources();

    return 0;
}

// Function to setup hardware
void setup_hardware(void) {
    // Initialize GPIO pins
    gpio_mode_set(GPIO_NUM_DT, GPIO_MODE_INPUT);
    gpio_set_direction(GPIO_NUM_DT, GPIO_IN);

    gpio_mode_set(GPIO_NUM_SCK, GPIO_MODE_OUTPUT);
    gpio_set_direction(GPIO_NUM_SCK, GPIO_OUT);

    // Initialize HX711
    hx711_init(HX711_ADDR);

    // Set data and clock pins
    hx711_set_data_pin(HX711_DATA_PIN);
    hx711_set_clock_pin(HX711_CLOCK_PIN);
}

// Function to read weight from HX711
int read_weight(uint16_t* weight) {
    int16_t data = hx711_read_data();
    if (data == 0) {
        // HX711 read timeout
        log_event("HX711 read timeout.", time(NULL));
        return 1;
    }

    // Convert 16-bit data to weight
    *weight = (data * 1.11714135) / 4096.0; // Calibration factor for 10kg load cell

    return 0;
}

// Function to activate the solenoid lock
void activate_lock(void) {
    gpio_set_level(GPIO_NUM_LOCK, 1); // Activate GPIO 17 (High)
    sleep(5); // Wait for 5 seconds
    gpio_set_level(GPIO_NUM_LOCK, 0); // Deactivate GPIO 17 (Low)
}

// Function to cleanup resources
void cleanup_resources(void) {
    // Release GPIO pins
    gpio_free(GPIO_NUM_DT);
    gpio_free(GPIO_NUM_SCK);
    gpio_free(GPIO_NUM_LOCK);

    // Close file descriptor if it exists
    if (fd != -1) {
        close(fd);
    }
}

// Signal handler function
void handle_signal(int signum) {
    // Clean up and exit on SIGINT or SIGTERM
    cleanup_resources();
    exit(0);
}

// Function to log an event with timestamp
void log_event(const char* message, time_t timestamp) {
    char formatted_time[50];
    strftime(formatted_time, sizeof(formatted_time), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));

    // Open or create stock_events.txt file
    fd = open("stock_events.txt", O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        log_event("Failed to open or create stock_events.txt file.", timestamp);
        return;
    }

    // Write the event to the file
    fprintf(fd, "%s: %s\n", formatted_time, message);
    fclose(fd);
}

