#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <libgpiod/gpiod.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

#define GPIO16 27 // BCM 27
#define GPIO20 31 // BCM 31

#define SENSOR_PIN 16
#define RELAY_PIN 20

#define FILE_NAME "relay_events.log"
#define BUFFER_SIZE 1024

// Function prototypes
void initialize_libgpiod();
void cleanup_resources();
void toggle_relay(bool state);
void read_ir_sensor(bool *obstacle_detected);
void handle_signal(int signum);

int main() {
    // Initialize libgpiod
    initialize_libgpiod();

    // Set up GPIO pins
    struct gpiod_dir gpio_dir;
    struct gpiod_cand gpio_cand;
    int ret;

    // Initialize GPIO16 as input
    ret = gpiod_cand_lookup(GPIO16, &gpio_cand);
    if (ret < 0) {
        fprintf(stderr, "Error: GPIO %d not found\n", GPIO16);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_direction(gpio_cand.dev, GPIO16, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "Error: Line request failed for GPIO %d\n", GPIO16);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO20 as output
    ret = gpiod_cand_lookup(GPIO20, &gpio_cand);
    if (ret < 0) {
        fprintf(stderr, "Error: GPIO %d not found\n", GPIO20);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_set_direction(gpio_cand.dev, GPIO20, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "Error: Line request failed for GPIO %d\n", GPIO20);
        exit(EXIT_FAILURE);
    }

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        bool obstacle_detected;
        read_ir_sensor(&obstacle_detected);

        if (obstacle_detected) {
            toggle_relay(false); // Obstacle detected, toggle relay OFF
        } else {
            toggle_relay(true); // No obstacle, toggle relay ON
        }

        // Log event
        char buffer[BUFFER_SIZE];
        time_t now = time(NULL);
        struct tm tm_now;
        char timestamp[50];

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        sprintf(buffer, "%s: Relay state changed to %s\n", timestamp, (obstacle_detected ? "OFF" : "ON"));

        FILE *file = fopen(FILE_NAME, "a");
        if (!file) {
            fprintf(stderr, "Error: Unable to open file %s for writing\n", FILE_NAME);
            exit(EXIT_FAILURE);
        }

        fwrite(buffer, sizeof(buffer), 1, file);
        fclose(file);
    }

    // Cleanup GPIO resources
    cleanup_resources();

    return 0;
}

// Function to initialize libgpiod
void initialize_libgpiod() {
    int ret;

    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }
}

// Function to cleanup GPIO resources
void cleanup_resources() {
    struct gpiod_dir gpio_dir;
    struct gpiod_cand gpio_cand;

    // Cleanup GPIO16
    ret = gpiod_cand_lookup(GPIO16, &gpio_cand);
    if (ret < 0) {
        fprintf(stderr, "Error: GPIO %d not found\n", GPIO16);
        return;
    }

    ret = gpiod_set_direction(gpio_cand.dev, GPIO16, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "Error: Line request failed for GPIO %d\n", GPIO16);
        return;
    }

    ret = gpiod_cleanup(gpio_cand.dev, GPIO16);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to cleanup GPIO %d\n", GPIO16);
    }

    // Cleanup GPIO20
    ret = gpiod_cand_lookup(GPIO20, &gpio_cand);
    if (ret < 0) {
        fprintf(stderr, "Error: GPIO %d not found\n", GPIO20);
        return;
    }

    ret = gpiod_set_direction(gpio_cand.dev, GPIO20, &gpio_dir);
    if (ret < 0) {
        fprintf(stderr, "Error: Line request failed for GPIO %d\n", GPIO20);
        return;
    }

    ret = gpiod_cleanup(gpio_cand.dev, GPIO20);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to cleanup GPIO %d\n", GPIO20);
    }
}

// Function to toggle the relay
void toggle_relay(bool state) {
    struct gpiod_value value;
    int ret;

    ret = gpiod_get_value(gpio_cand.dev, GPIO20, &value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d value\n", GPIO20);
        return;
    }

    if (state) {
        // Set GPIO20 to HIGH (ON)
        value.value = 1;
    } else {
        // Set GPIO20 to LOW (OFF)
        value.value = 0;
    }

    ret = gpiod_set_value(gpio_cand.dev, GPIO20, &value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d value\n", GPIO20);
    }
}

// Function to read the IR sensor
void read_ir_sensor(bool *obstacle_detected) {
    int ret;
    struct gpiod_value value;

    ret = gpiod_get_value(gpio_cand.dev, SENSOR_PIN, &value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d value\n", SENSOR_PIN);
        *obstacle_detected = false; // Assume no obstacle detected if reading fails
        return;
    }

    *obstacle_detected = value.value == 0; // Active-low sensor, LOW indicates obstacle
}

// Signal handler to clean up resources on SIGINT or SIGTERM
void handle_signal(int signum) {
    cleanup_resources();
    exit(EXIT_SUCCESS);
}

