const char *motion_log_message_format = "%F %T";

void setup_pir_sensor(gpiod_device *pir_device) {
    if (gpiod_is_valid_pin(pir_device, PIR_GPIO)) {
        gpiod_direction_input(pir_device, PIR_GPIO);
        printf("PIR sensor on GPIO %d initialized.\n", PIR_GPIO);
    } else {
        fprintf(stderr, "Error: PIR sensor pin not found or invalid.\n");
        exit(EXIT_FAILURE);
    }
}

void setup_buzzer(gpiod_device *buzzer_device) {
    if (gpiod_is_valid_pin(buzzer_device, BUZZER_GPIO)) {
        gpiod_direction_output(buzzer_device, BUZZER_GPIO, 1);
        printf("Buzzer on GPIO %d initialized.\n", BUZZER_GPIO);
    } else {
        fprintf(stderr, "Error: Buzzer pin not found or invalid.\n");
        exit(EXIT_FAILURE);
    }
}

void activate_buzzer(gpiod_device *buzzer_device) {
    if (gpiod_write(buzzer_device, BUZZER_GPIO, 1) == 0) {
        printf("Buzzer activated.\n");
        usleep(2000000); // 2 seconds
        gpiod_write(buzzer_device, BUZZER_GPIO, 0);
        printf("Buzzer deactivated.\n");
    } else {
        fprintf(stderr, "Error activating buzzer.\n");
        exit(EXIT_FAILURE);
    }
}

void log_motion_detection(gpiod_device *pir_device) {
    time_t timestamp;
    struct tm timeinfo;
    char log_message[50];

    time(&timestamp);
    localtime_r(&timestamp, &timeinfo);

    strftime(log_message, sizeof(log_message), motion_log_message_format, &timeinfo);
    fprintf(motion_log_file, "%s\n", log_message);

    if (ferror(motion_log_file)) {
        fprintf(stderr, "Error writing to motion log file.\n");
        fclose(motion_log_file);
        motion_log_file = NULL;
    }
}

void cleanup_resources() {
    if (motion_log_file != NULL) {
        fclose(motion_log_file);
        motion_log_file = NULL;
    }

    gpiod_unexport_all();
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        cleanup_resources();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    gpiod_device *pir_device;
    gpiod_device *buzzer_device;
    motion_log_file = fopen(MOTION_LOG_FILE, "a");

    if (motion_log_file == NULL) {
        fprintf(stderr, "Error opening motion log file.\n");
        return EXIT_FAILURE;
    }

    setup_pir_sensor(&pir_device);
    setup_buzzer(&buzzer_device);

    while (1) {
        if (gpiod_read(pir_device, PIR_GPIO) == 1) {
            log_motion_detection(pir_device);
            activate_buzzer(&buzzer_device);
        }
    }

    return 0;
}

