#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <stdint.h>

#define GPIO_NUM_18 18
#define GPIO_ACTIVE_LOW 0

volatile sig_atomic_t should_exit = 0;

void setup_gpio(int gpio_num, int direction, int value) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd == -1) {
        perror("open /dev/gpiochip0");
        exit(EXIT_FAILURE);
    }

    struct gpio_desc *gpio_desc = gpio_request(fd, gpio_num);
    if (!gpio_desc) {
        fprintf(stderr, "Failed to request GPIO %d\n", gpio_num);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (direction == GPIO_ACTIVE_LOW) {
        gpio_direction_output(gpio_desc, GPIO_ACTIVE_LOW);
    } else {
        gpio_direction_output(gpio_desc, GPIO_ACTIVE_HIGH);
    }

    if (value) {
        gpio_set_value(gpio_desc, GPIO_ACTIVE_HIGH);
    } else {
        gpio_set_value(gpio_desc, GPIO_ACTIVE_LOW);
    }

    gpio_free(gpio_desc);
    close(fd);
}

void teardown_gpio() {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd == -1) {
        perror("open /dev/gpiochip0");
        exit(EXIT_FAILURE);
    }

    gpio_free_all(fd);
    close(fd);
}

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    setup_gpio(GPIO_NUM_18, GPIO_ACTIVE_LOW, 0);

    int fd = open("watering.conf", O_RDONLY);
    if (fd == -1) {
        perror("open watering.conf");
        exit(EXIT_FAILURE);
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("read from watering.conf");
        close(fd);
        exit(EXIT_FAILURE);
    }
    buffer[bytes_read] = '\0';

    if (sscanf(buffer, "duration=%d", &watering_duration) != 1) {
        fprintf(stderr, "Invalid format in watering.conf\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (watering_duration < 1 || watering_duration > 3600) {
        fprintf(stderr, "Invalid duration value in watering.conf (must be 1-3600 seconds)\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);

    printf("Starting watering for %d seconds\n", watering_duration);

    struct itimerval timer;
    timer.it_interval.tv_sec = 0;
    timer.it_interval.tv_usec = 100000; // 0.1 seconds
    timer.it_value.tv_sec = watering_duration;
    timer.it_value.tv_usec = 0;

    if (setitimer(ITIMER_REAL, &timer, NULL) == -1) {
        perror("setitimer");
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        usleep(10000); // Poll every 10ms
        if (should_exit) {
            teardown_gpio();
            printf("Watering stopped due to signal\n");
            break;
        }
    }

    teardown_gpio();
    printf("Watering stopped\n");

    return 0;
}

