#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_NUM_LEFT_SENSOR 4
#define GPIO_NUM_MIDDLE_SENSOR 17
#define GPIO_NUM_RIGHT_SENSOR 27
#define GPIO_NUM_LEFT_MOTOR_PWM 22
#define GPIO_NUM_RIGHT_MOTOR_PWM 23
#define GPIO_NUM_BASE_SPEED_PWM 24
#define GPIO_NUM_MAX_SPEED_PWM 25

#define PWM_FREQ_HZ 1000
#define SAMPLING_INTERVAL_MS 10
#define BASE_SPEED 150
#define MAX_SPEED 255

FILE *logFile = NULL;
gpiod_device *gpiod;
int left_motor_speed = 0;
int right_motor_speed = 0;

void setup_gpiod() {
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIOD: %s\n", gpiod_errstr(gpiod));
        exit(EXIT_FAILURE);
    }

    gpiod = gpiod_get_device_by_name("bcm2835-gpio");
    if (!gpiod) {
        fprintf(stderr, "Failed to get GPIO device: %s\n", gpiod_errstr(gpiod));
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_LEFT_SENSOR, GPIOD_OUT_INIT_LOW) < 0) {
        fprintf(stderr, "Failed to request GPIO %u: %s\n", GPIO_NUM_LEFT_SENSOR, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_MIDDLE_SENSOR, GPIOD_OUT_INIT_LOW) < 0) {
        fprintf(stderr, "Failed to request GPIO %u: %s\n", GPIO_NUM_MIDDLE_SENSOR, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_RIGHT_SENSOR, GPIOD_OUT_INIT_LOW) < 0) {
        fprintf(stderr, "Failed to request GPIO %u: %s\n", GPIO_NUM_RIGHT_SENSOR, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_LEFT_MOTOR_PWM, GPIOD_OUT_MODE_PWM) < 0) {
        fprintf(stderr, "Failed to request GPIO %u for PWM: %s\n", GPIO_NUM_LEFT_MOTOR_PWM, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_RIGHT_MOTOR_PWM, GPIOD_OUT_MODE_PWM) < 0) {
        fprintf(stderr, "Failed to request GPIO %u for PWM: %s\n", GPIO_NUM_RIGHT_MOTOR_PWM, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_BASE_SPEED_PWM, GPIOD_OUT_MODE_PWM) < 0) {
        fprintf(stderr, "Failed to request GPIO %u for PWM: %s\n", GPIO_NUM_BASE_SPEED_PWM, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }

    if (gpiod_request_pin(gpiod, GPIO_NUM_MAX_SPEED_PWM, GPIOD_OUT_MODE_PWM) < 0) {
        fprintf(stderr, "Failed to request GPIO %u for PWM: %s\n", GPIO_NUM_MAX_SPEED_PWM, gpiod_errstr(gpiod));
        gpiod_put_device(gpiod);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (logFile) {
        fclose(logFile);
        logFile = NULL;
    }

    gpiod_put_device(gpiod);
    gpiod_uninit();
}

void handle_SIGINT(int signum) {
    printf("SIGINT received, stopping motors and exiting...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

void read_sensors() {
    int left_sensor = gpiod_get_value(gpiod, GPIO_NUM_LEFT_SENSOR);
    int middle_sensor = gpiod_get_value(gpiod, GPIO_NUM_MIDDLE_SENSOR);
    int right_sensor = gpiod_get_value(gpiod, GPIO_NUM_RIGHT_SENSOR);

    if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
        printf("All sensors are high, stopping motors.\n");
        left_motor_speed = 0;
        right_motor_speed = 0;
    } else if (middle_sensor == 0) {
        printf("Middle sensor is low, driving straight at base speed.\n");
        left_motor_speed = BASE_SPEED;
        right_motor_speed = BASE_SPEED;
    } else if (left_sensor == 0) {
        printf("Left sensor is low, turning right by halving left motor speed.\n");
        left_motor_speed = BASE_SPEED / 2;
        right_motor_speed = BASE_SPEED;
    } else if (right_sensor == 0) {
        printf("Right sensor is low, turning left by halving right motor speed.\n");
        left_motor_speed = BASE_SPEED;
        right_motor_speed = BASE_SPEED / 2;
    }
}

void set_motor_speeds(int left_speed, int right_speed) {
    int duty_cycle_left = (int)(left_speed * (PWM_FREQ_HZ / MAX_SPEED));
    int duty_cycle_right = (int)(right_speed * (PWM_FREQ_HZ / MAX_SPEED));

    gpiod_set_value(gpiod, GPIO_NUM_LEFT_MOTOR_PWM, duty_cycle_left);
    gpiod_set_value(gpiod, GPIO_NUM_RIGHT_MOTOR_PWM, duty_cycle_right);
}

void main_loop() {
    struct timespec ts;
    time_t rawtime;
    char buffer[50];

    while (1) {
        // Read sensors
        read_sensors();

        // Set motor speeds
        set_motor_speeds(left_motor_speed, right_motor_speed);

        // Log data
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S.%03zu", localtime(&rawtime));
        fprintf(logFile, "Timestamp: %s\nLeft Sensor: %d\nMiddle Sensor: %d\nRight Sensor: %d\nLeft Motor Speed: %d\nRight Motor Speed: %d\n\n", buffer, left_sensor, middle_sensor, right_sensor, left_motor_speed, right_motor_speed);

        // Wait for next sampling interval
        ts.tv_sec = rawtime + SAMPLING_INTERVAL_MS / 1000;
        ts.tv_nsec = (SAMPLING_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }
}

int main() {
    setup_gpiod();
    signal(SIGINT, handle_SIGINT);

    logFile = fopen("trace_log.txt", "a+");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, &main_loop, NULL) != 0) {
        fprintf(stderr, "Failed to create thread: %s\n", strerror(errno));
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Wait for the thread to complete
    pthread_join(thread, NULL);

    cleanup();

    return 0;
}

