#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define RELAY_PIN 24 // BCM 24 corresponds to GPIO23

// BH1750 register addresses
#define BH1750_REG_LUX 0x00

// I2C device file descriptor
int i2c_fd = -1;

// BH1750 sensor structure
struct bme280_reg {
    uint8_t reg;
    uint8_t data[1];
};

// Function prototypes
void open_i2c();
void close_i2c();
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data);
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data);
void handle_i2c_error(const char *operation);
void setup_relay(int gpio);
void release_relay();
void log_timestamp(char *msg);
void log_lux(int lux);
void log_relay_state();

int main() {
    // Initialize GPIO library
    if (pigpioSetup(0) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpioError());
        return EXIT_FAILURE;
    }

    // Open I2C device
    open_i2c();

    // Initialize variables
    int lux;
    uint8_t data[1];
    struct timespec ts;
    pid_t pid = getpid();

    // Main loop
    while (1) {
        // Read lux value from BH1750
        if (i2c_read(BH1750_ADDR, BH1750_REG_LUX, data) < 0) {
            handle_i2c_error("Read lux");
            continue;
        }

        lux = data[0];

        // Check lux value and control relay
        if (lux < 150) {
            setup_relay(RELAY_GPIO);
            log_lux(lux);
        } else {
            release_relay();
        }

        // Log timestamp and relay state
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        log_timestamp("Lux: %d, Relay: %d\n", lux, pigpioDigitalRead(RELAY_GPIO));

        // Delay for 180 ms
        usleep(180000);
    }

    // Clean up on SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN; // Ignore SIGINT
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Close I2C and release resources
    close_i2c();
    release_relay();
    pigpioTerminate();

    return EXIT_SUCCESS;
}

// Function to open I2C device
void open_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Map the I2C device file to memory for direct access
    void *mem = mmap(NULL, sizeof(struct i2c_dev), PROT_WRITE | PROT_READ, MAP_SHARED, i2c_fd, 0);
    if (mem == MAP_FAILED) {
        perror("mmap");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Store the pointer for direct I2C operations
    struct i2c_dev *i2c_dev = (struct i2c_dev *)mem;
}

// Function to close I2C device and release resources
void close_i2c() {
    munmap(mem, sizeof(struct i2c_dev));
    close(i2c_fd);
}

// I2C write function
int i2c_write(uint8_t addr, uint8_t reg, uint8_t data) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = 1,
        .buf = (unsigned char *)data
    };

    int rc = i2c_smbus_write_i2c_block_data(i2c_dev, reg, &msg, 1);
    if (rc < 0) {
        handle_i2c_error("Write to BH1750");
        return rc;
    }

    return 0;
}

// I2C read function
int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .len = 1,
        .buf = data
    };

    int rc = i2c_smbus_read_i2c_block_data(i2c_dev, reg, &msg, 1);
    if (rc < 0) {
        handle_i2c_error("Read from BH1750");
        return rc;
    }

    return 0;
}

// Handle I2C errors
void handle_i2c_error(const char *operation) {
    fprintf(stderr, "Error during %s operation: %s\n", operation, strerror(errno));
}

// Setup relay
void setup_relay(int gpio) {
    if (pigpioOpen() < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpioError());
        return;
    }

    if (pigpioDirectionSet(RELAY_GPIO, pigpioOutput) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output: %s\n", RELAY_GPIO, pigpioError());
        pigpioClose();
        return;
    }

    if (pigpioWrite(RELAY_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to turn on GPIO %d: %s\n", RELAY_GPIO, pigpioError());
        pigpioClose();
        return;
    }
}

// Release relay
void release_relay() {
    if (pigpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to turn off GPIO %d: %s\n", RELAY_GPIO, pigpioError());
        pigpioClose();
    }
}

// Log timestamp
void log_timestamp(char *msg) {
    struct tm tm;
    time(&tm);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(stderr, "%s: %s\n", timestamp, msg);
}

// Log lux value
void log_lux(int lux) {
    log_timestamp("Lux: %d", lux);
}

// Log relay state
void log_relay_state() {
    log_timestamp("Relay: %d", pigpioDigitalRead(RELAY_GPIO));
}

