#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

volatile sig_atomic_t sigint_received = 0;

void handle_signal(int signum) {
    sigint_received = 1;
}

int main() {
    // Initialize gpiod
    int rc = gpiod_init();
    if (rc != 0) {
        fprintf(stderr, "gpiod initialization failed: %s\n", gpiod_errstr(rc));
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    struct gpiod_dir *lock_button_dir = gpiod_get_direction(SERVO_PIN);
    struct gpiod_dir *unlock_button_dir = gpiod_get_direction(LOCK_BUTTON_PIN);
    struct gpiod_dir *servo_pwm_dir = gpiod_get_direction(UNLOCK_BUTTON_PIN);

    if (!lock_button_dir || !unlock_button_dir || !servo_pwm_dir) {
        fprintf(stderr, "Failed to get GPIO direction for pins.\n");
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Set pins to input with pull-up enabled
    rc = gpiod_set_mode(lock_button_dir, GPIOD_MODE_INPUT | GPIOD_PULLUP);
    rc = gpiod_set_mode(unlock_button_dir, GPIOD_MODE_INPUT | GPIOD_PULLUP);
    rc = gpiod_set_mode(servo_pwm_dir, GPIOD_MODE_OUTPUT);

    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO modes: %s\n", gpiod_errstr(rc));
        gpiod_cleanup();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, handle_signal);

    // Main loop
    while (!sigint_received) {
        // Debounce button presses
        struct gpiod_value lock_button_value;
        struct gpiod_value unlock_button_value;
        int lock_button_state, unlock_button_state;

        lock_button_state = unlock_button_state = 0;

        // Lock button debounce
        for (int i = 0; i < 10; ++i) {
            if (gpiod_get_value(lock_button_dir, &lock_button_value) && lock_button_value.value == 0) {
                lock_button_state = 1;
                break;
            }
            usleep(100000);
        }

        // Unlock button debounce
        for (int i = 0; i < 10; ++i) {
            if (gpiod_get_value(unlock_button_dir, &unlock_button_value) && unlock_button_value.value == 0) {
                unlock_button_state = 1;
                break;
            }
            usleep(100000);
        }

        if (lock_button_state) {
            // Set servo to 1000 µs (0°)
            rc = gpiod_set_value(servo_pwm_dir, 1000);
            if (rc != 0) {
                fprintf(stderr, "Failed to set servo pulse width: %s\n", gpiod_errstr(rc));
            } else {
                printf("Lock button pressed, setting servo to 0°.\n");
            }
        } else if (unlock_button_state) {
            // Set servo to 2000 µs (180°)
            rc = gpiod_set_value(servo_pwm_dir, 2000);
            if (rc != 0) {
                fprintf(stderr, "Failed to set servo pulse width: %s\n", gpiod_errstr(rc));
            } else {
                printf("Unlock button pressed, setting servo to 180°.\n");
            }
        }

        // Release resources on SIGINT
        if (sigint_received) {
            gpiod_cleanup();
            return EXIT_FAILURE;
        }
    }

    // Clean up GPIO resources
    gpiod_cleanup();

    return EXIT_SUCCESS;
}

