#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod/gpiod.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO27 27

// Function prototypes
void setup_hardware(void);
void teardown_hardware(void);
void handle_signal(int signum);

int main(void) {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIO pins
    setup_hardware();

    // Main loop
    while (1) {
        // Pulse motor 1 (GPIO 17) for 200 ms
        gpiod_set_value(GPIO17, GPIOD_VALUE_HIGH);
        usleep(200000);
        gpiod_set_value(GPIO17, GPIOD_VALUE_LOW);

        // Pulse motor 2 (GPIO 27) for 300 ms
        gpiod_set_value(GPIO27, GPIOD_VALUE_HIGH);
        usleep(300000);
        gpiod_set_value(GPIO27, GPIOD_VALUE_LOW);
    }

    // Tear down GPIO pins
    teardown_hardware();

    return 0;
}

// Function to setup the GPIO pins
void setup_hardware(void) {
    // Check if GPIO library is initialized
    if (gpiod_is_valid(GPIO17) == 0 || gpiod_is_valid(GPIO27) == 0) {
        fprintf(stderr, "Error: Invalid GPIO pins\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO device
    int gpio_dev = gpiod_open("/dev/gpiom", "r+");
    if (gpio_dev < 0) {
        fprintf(stderr, "Error: Failed to open GPIO device\n");
        exit(EXIT_FAILURE);
    }

    // Register GPIO pins
    if (gpiod_request_gpio(GPIO17) < 0 || gpiod_request_gpio(GPIO27) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO pins\n");
        gpiod_close(gpio_dev);
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins to output mode
    if (gpiod_direction_output(GPIO17, 1) < 0 || gpiod_direction_output(GPIO27, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO pins to output mode\n");
        gpiod_unrequest_gpio(GPIO17);
        gpiod_unrequest_gpio(GPIO27);
        gpiod_close(gpio_dev);
        exit(EXIT_FAILURE);
    }

    gpiod_close(gpio_dev);
