#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17 // BCM 17
#define ALARM_LED_GPIO 27  // BCM 27
#define SOUND_SENSOR_PIN 0  // GPIO 17
#define ALARM_LED_PIN 2     // GPIO 27

#define SOUND_ALERT_TOPIC "SOUND_ALERTS"

// Direct GPIO access without a library
#define BCM_GPIO_BASE 0x3F00
#define GPIO_SET_BITMASK (1 << SOUND_SENSOR_PIN)
#define GPIO_CLR_BITMASK (1 << SOUND_SENSOR_PIN)

#define ALARM_DURATION_MS 1000

// ZeroMQ context and socket
zmq_context *context = NULL;
zmq_socket *sound_sensor_socket = NULL;
zmq_socket *alarm_node_socket = NULL;

void setup_gpio(void) {
    // Set GPIO pins to output for LED and sound sensor control
    uint32_t gpiomode = GPIO_SET_BITMASK;
    write BCM_GPIO_BASE, gpiomode, GPIO_SET_REG_OFFSET + SOUND_SENSOR_PIN;
    write BCM_GPIO_BASE, ~gpiomode, GPIO_SET_REG_OFFSET + ALARM_LED_PIN;

    // Set alarm LED pin to low (off)
    write BCM_GPIO_BASE, GPIO_CLR_BITMASK, GPIO_SET_REG_OFFSET + ALARM_LED_PIN;
}

void cleanup_gpio(void) {
    // Set GPIO pins to input for sound sensor (not strictly necessary but good practice)
    uint32_t gpiomode = GPIO_SET_BITMASK;
    write BCM_GPIO_BASE, gpiomode, GPIO_SET_REG_OFFSET + SOUND_SENSOR_PIN;
    write BCM_GPIO_BASE, ~gpiomode, GPIO_SET_REG_OFFSET + SOUND_SENSOR_PIN;

    // Set alarm LED pin to high (on)
    write BCM_GPIO_BASE, GPIO_SET_BITMASK, GPIO_SET_REG_OFFSET + ALARM_LED_PIN;
}

void sound_sensor_mode(int argc, char **argv) {
    if (argc != 2 || strcmp(argv[1], "sound_sensor") != 0) {
        fprintf(stderr, "Usage: %s sound_sensor\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        exit(EXIT_FAILURE);
    }

    sound_sensor_socket = zmq_socket(context, ZMQ_PUB);
    if (!sound_sensor_socket) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    // Subscribe to the topic for alarm_node mode
    alarm_node_socket = zmq_socket(context, ZMQ_SUB);
    if (!alarm_node_socket) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        zmq_close(sound_sensor_socket);
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    // Subscribe to the topic
    zmq_setsockopt(alarm_node_socket, ZMQ_SUBSCRIBE, SOUND_ALERT_TOPIC, strlen(SOUND_ALERT_TOPIC));

    // Main loop
    while (1) {
        uint8_t sound_detected = !read BCM_GPIO_BASE + GPIO_CLR_REG_OFFSET + SOUND_SENSOR_PIN; // Active-low

        if (sound_detected) {
            char msg[256];
            sprintf(msg, "SOUND_ALERT");
            zmq_msg_t msg;
            zmq_msg_init_size(&msg, sizeof(msg));
            zmq_msg_send(sound_sensor_socket, msg, 0);
            zmq_msg_close(&msg);
        }
    }

    // Clean up
    cleanup_gpio();
    zmq_close(sound_sensor_socket);
    zmq_ctx_destroy(context);
}

void alarm_node_mode(int argc, char **argv) {
    if (argc != 2 || strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Usage: %s alarm_node\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        exit(EXIT_FAILURE);
    }

    alarm_node_socket = zmq_socket(context, ZMQ_SUB);
    if (!alarm_node_socket) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    // Subscribe to the topic
    zmq_setsockopt(alarm_node_socket, ZMQ_SUBSCRIBE, SOUND_ALERT_TOPIC, strlen(SOUND_ALERT_TOPIC));

    // Main loop
    while (1) {
        zmq_msg_t msg;
        zmq_msg_init(&msg);
        if (zmq_msg_recv(alarm_node_socket, &msg, 0) == -1) {
            fprintf(stderr, "Error receiving message on ZeroMQ socket\n");
            break;
        }

        // Handle received message
        if (zmq_msg_size(&msg) > 0) {
            char alert;
            memcpy(&alert, zmq_msg_data(&msg), 1);
            if (alert == 'S') {
                // Light the alarm LED for 1 second
                write BCM_GPIO_BASE, GPIO_SET_BITMASK, GPIO_SET_REG_OFFSET + ALARM_LED_PIN;
                usleep(ALARM_DURATION_MS * 1000);
                write BCM_GPIO_BASE, GPIO_CLR_BITMASK, GPIO_SET_REG_OFFSET + ALARM_LED_PIN;
            }
        }

        zmq_msg_close(&msg);
    }

    // Clean up
    cleanup_gpio();
    zmq_close(alarm_node_socket);
    zmq_ctx_destroy(context);
}

void handle_signals(int signum) {
    // Handle SIGINT and SIGTERM
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Shutting down...\n");
        cleanup_gpio();
        if (context) {
            zmq_ctx_destroy(context);
        }
        exit(EXIT_SUCCESS);
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        sound_sensor_mode(argc, argv);
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        alarm_node_mode(argc, argv);
    } else {
        fprintf(stderr, "Invalid mode specified\n");
        return EXIT_FAILURE;
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signals;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    return EXIT_SUCCESS;
}

