Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <mosquitto.h>
#include <syslog.h>
#include <json.h>

#define GPIO_NUM 17
#define TSOP38238_PIN GPIO_NUM

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

#define PULSE_HEADER 560
#define LOGIC_1_SPACE 1690
#define LOGIC_0_SPACE 560
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE LOGIC_0_SPACE
#define NEC_FRAME_SIZE 32

struct pulse {
    uint32_t timestamp;
    uint32_t duration;
};

struct nec_frame {
    uint8_t address;
    uint8_t command;
    uint8_t extension;
    uint16_t data;
};

static void gpio_falling_edge_callback(struct gpio_desc *gpio, int edge, void *data)
{
    struct pulse buffer[NEC_FRAME_SIZE];
    int i;
    struct nec_frame frame;

    // Check if the falling edge is on the correct GPIO pin
    if (gpio->number != GPIO_NUM) {
        syslog(LOG_ERR, "Incorrect GPIO pin for IR receiver");
        return;
    }

    // Clear the buffer
    for (i = 0; i < NEC_FRAME_SIZE; ++i) {
        buffer[i].timestamp = 0;
        buffer[i].duration = 0;
    }

    // Capture pulse timings
    for (i = 0; i < NEC_FRAME_SIZE; ++i) {
        buffer[i].timestamp = microsecond_to_time_t(microseconds());
        if (edge == GPIO_FALLING) {
            buffer[i].duration = microseconds() - buffer[i].timestamp;
        }
    }

    // Decode NEC frame
    frame.address = (buffer[0].duration == LOGIC_1_SPACE);
    frame.command = (buffer[1].duration == LOGIC_1_SPACE) ? 1 : 0;
    frame.extension = (buffer[2].duration == LOGIC_1_SPACE) ? 1 : 0;
    frame.data = (buffer[3] && buffer[3].duration == LOGIC_1_SPACE) ? (buffer[3].duration / LOGIC_1_SPACE) : 0;

    // Validate NEC checksum
    uint8_t checksum = 0;
    for (int j = 0; j < 12; ++j) {
        checksum ^= (frame.address | frame.command | frame.extension | frame.data >> (7 - j));
    }
    if (checksum != frame.address) {
        syslog(LOG_ERR, "NEC checksum failed");
        return;
    }

    // Publish to MQTT
    mosquitto_pub(NULL, MQTT_TOPIC, 0, (void *)&frame, 0);
}

int main(void)
{
    struct gpio_desc *gpio;
    struct gpiod_chip *chip;
    int rc;
    mosquitto_context *ctx;
    mosquitto_client *mqtt_client;
    sigset_t sigset;
    int sigint_received = 0;

    // Initialize libgpiod
    rc = gpiod_chip_open(&chip, GPIOD_CHIP_RASPBERRY_PI_3BPlus);
    if (rc != 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open GPIO 17
    rc = gpiod_get gpio, chip, GPIO_NUM;
    if (rc != 0) {
        syslog(LOG_ERR, "Failed to get GPIO 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO 17 as input and enable interrupts
    rc = gpiod_direction_input(gpio);
    if (rc != 0) {
        syslog(LOG_ERR, "Failed to set GPIO 17 as input");
        gpiod_release(gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Register the callback
    rc = gpiod_event_callback_set(gpio, gpio_falling_edge_callback, NULL);
    if (rc != 0) {
        syslog(LOG_ERR, "Failed to set GPIO falling edge callback");
        gpiod_release(gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize libmosquitto
    ctx = mosquitto_new(NULL, 0);
    if (ctx == NULL) {
        syslog(LOG_ERR, "Failed to initialize MQTT client");
        gpiod_release(gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    mqtt_client = mosquitto_connect(ctx, MQTT_BROKER, MQTT_PORT, 60);
    if (mqtt_client == NULL) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_free(ctx);
        gpiod_release(gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    sigprocmask(SIG_BLOCK, &sigset, NULL);

    // Main loop
    while (!sigint_received) {
        // Poll for signals
        if (sigpending(&sigset) != 0) {
            sigint_received = 1;
            break;
        }

        // Poll MQTT for new messages (simplified for demonstration)
        mosquitto_loop(0, ctx);
    }

    // Clean up resources
    mosquitto_disconnect(mqtt_client, 0);
    mosquitto_free(ctx);

    gpiod_event_callback_unset(gpio, gpio_falling_edge_callback);
    gpiod_release(gpio);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Shutting down...");
    exit(EXIT_SUCCESS);
}

// Helper function to convert microseconds to time_t
time_t microseconds_to_time_t(uint32_t microseconds)
{
    return (time_t)(microseconds / 1000);
}
