#include <sys/types.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define AWM7300V_I2C_ADDR 0x20 // Sensor address
#define AWM7300V_REG_FLOW 0x00 // Flow rate register

