// Function prototypes
void sigint_handler(int signum);
int open_i2c_device(const char *i2c_device);
void close_i2c_device(int fd);
int read_from_awm7300v(int fd, uint8_t reg, uint16_t *value);
void convert_flow_to_slpm(uint16_t flow_value, float *slpm);

int main() {
    // Initialize GPIO for SIGINT handling
    int gpio_fd = gpiod_open(GPIOD_ID_RASPBERRY_PI_0, "in");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C device
    int i2c_fd = open_i2c_device("/dev/i2c-1");
    if (i2c_fd < 0) {
        if (errno == ENXIO) {
            printf("AWM7300V sensor not found.\n");
            return 1;
        } else {
            perror("Failed to open I2C device");
            return 1;
        }
    }

    // Main loop
    while (1) {
        uint16_t flow_value;
        struct stat statbuf;
        time_t now = time(NULL);
        float slpm;

        // Attempt to read flow value up to 3 times on failure
        for (int attempts = 3; attempts > 0; --attempts) {
            if (read_from_awm7300v(i2c_fd, AWM7300V_REG_FLOW, &flow_value) < 0) {
                if (attempts > 1) {
                    // Delay before retrying
                    usleep(100000);
                } else {
                    // Last attempt failed, exit the loop
                    break;
                }
            } else {
                break; // Success
            }
        }

        if (attempts == 0) {
            // Handle error
            printf("Failed to read from AWM7300V sensor.\n");
            continue;
        }

        // Convert flow value to SLPM
        convert_flow_to_slpm(flow_value, &slpm);

        // Log the flow rate
        char buffer[100];
        sprintf(buffer, "%s %f SLPM\n", ctime(&now), slpm);
        if (stat("airflow_log.txt", &statbuf) == 0) {
            if (write(1, buffer, strlen(buffer)) != strlen(buffer)) {
                perror("Failed to write to airflow_log.txt");
                break; // Exit loop on write failure
            }
        } else {
            perror("airflow_log.txt not found");
            break; // Exit loop on file not found
        }

        // Close I2C device and GPIO on exit
        close_i2c_device(i2c_fd);
        gpiod_close(gpio_fd);
    }

    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    // Close I2C file descriptor and flush/close log file
    close_i2c_device(-1);
    if (access("airflow_log.txt", F_OK) != -1) {
        fclose(stdout); // Ensure log file is properly closed
        remove("airflow_log.txt"); // Optionally remove the file
    }
    exit(0); // Exit cleanly
}

// Function to open I2C device
int open_i2c_device(const char *i2c_device) {
    int fd;
    if ((fd = open(i2c_device, O_RDWR)) < 0) {
        perror("open");
        return fd;
    }
    if (ioctl(fd, I2C_SLAVE, AWM7300V_I2C_ADDR) < 0) {
        perror("ioctl");
        return -1;
    }
    return fd;
}

// Function to close I2C device
void close_i2c_device(int fd) {
    close(fd);
}

// Function to read from AWM7300V sensor
int read_from_awm7300v(int fd, uint8_t reg, uint16_t *value) {
    int bytes_read;
    if ((bytes_read = i2c_smbus_read_word_data(fd, reg)) < 0) {
        perror("i2c_smbus_read_word_data");
        return bytes_read;
    }
    *value = (bytes_read == 2) ? (bytes_read[1] << 8) | bytes_read[0] : 0;
    return bytes_read;
}

// Function to convert flow value to SLPM
void convert_flow_to_slpm(uint16_t flow_value, float *slpm) {
    *slpm = (float)flow_value / 1024.0; // Assuming 1024 SLPM per 14-bit value
}

