#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <net/if.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define BH1750_ADDR 0x23
#define BH1750_REG_LUX 0x00

// Function prototypes
void handle_signal(int signum);
int i2c_write(uint8_t *buf, size_t len);
int i2c_read(uint8_t *buf, size_t len);
double bh1750_to_lux(uint16_t raw);

int main() {
    // Signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    int i2c_fd = -1;
    char dev_name[10] = "/dev/i2c-1";
    i2c_fd = open(dev_name, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize UDP socket
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set socket options
    int optval = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &optval, sizeof(optval));

    // Bind to a specific address (with TTL of 1)
    struct sockaddr_in broadcast_addr;
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = htonl(INADDR_BROADCAST);
    broadcast_addr.sin_port = htons(5000);
    if (bind(sockfd, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) == -1) {
        perror("Failed to bind UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint8_t buf[2];
        int bytes_read = 0;

        // Write to BH1750 to read lux
        buf[0] = BH1750_ADDR;
        buf[1] = BH1750_REG_LUX;
        if (i2c_write(buf, 2) < 2) {
            perror("Failed to write to BH1750");
            sleep(1); // Retry after 1 second
            continue;
        }

        // Read lux value from BH1750
        bytes_read = i2c_read(buf, 2);
        if (bytes_read != 2) {
            perror("Failed to read from BH1750");
            continue;
        }

        uint16_t raw_lux = (buf[0] << 8) | buf[1];
        double lux = bh1750_to_lux(raw_lux);

        // Broadcast the lux value
        char lux_str[20];
        sprintf(lux_str, "%f", lux);
        if (sendto(sockfd, lux_str, strlen(lux_str), 0, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on SIGINT or SIGTERM
    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    // Close I2C and UDP socket
    close(i2c_fd);
    close(sockfd);

    return 0;
}

// Function to handle signals
void handle_signal(int signum) {
    // Close resources on SIGINT or SIGTERM
    close(i2c_fd);
    close(sockfd);
    exit(EXIT_SUCCESS);
}

// Function to write to I2C device
int i2c_write(uint8_t *buf, size_t len) {
    int ret;
    ret = ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR);
    if (ret < 0) {
        perror("Failed to change I2C slave address");
        return ret;
    }

    ret = write(i2c_fd, buf, len);
    if (ret != len) {
        perror("Failed to write to I2C device");
        return ret;
    }

    return len;
}

// Function to read from I2C device
int i2c_read(uint8_t *buf, size_t len) {
    int ret;
    ret = ioctl(i2c_fd, I2C_RDWR, (char *) &BH1750_ADDR | I2C_M_RD);
    if (ret < 0) {
        perror("Failed to start I2C transaction");
        return ret;
    }

    ret = read(i2c_fd, buf, len);
    if (ret != len) {
        perror("Failed to read from I2C device");
        return ret;
    }

    return ret;
}

// Convert raw lux value to floating-point lux
double bh1750_to_lux(uint16_t raw) {
    // Assuming BH1750 returns lux directly in its raw value
    // This function should be adjusted based on the actual sensor's datasheet
    return raw / 16384.0; // Example conversion factor
}

