    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = htonl(INADDR_BROADCAST);
    broadcast_addr.sin_port = htons(5000);
    if (bind(sockfd, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) == -1) {
