void read_sensors_and_log(void);
void handle_signals(int signum);
void cleanup_resources(void);

int main(void) {
    struct gpiod_dir *dir;
    int left_sensor, middle_sensor, right_sensor;
    int uart_fd = -1;
    sigset_t sigset;
    char buffer[256];

    // Initialize GPIO directory
    if ((dir = gpiod_dir_open()) == NULL) {
        fprintf(stderr, "Failed to open GPIO directory: %s\n", gpiod_error_string());
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    if (gpiod_set_direction(dir, SENSOR_LEFT_GPIO, GPIOD_IN_PULL_UP) ||
        gpiod_set_direction(dir, SENSOR_MIDDLE_GPIO, GPIOD_IN_PULL_UP) ||
        gpiod_set_direction(dir, SENSOR_RIGHT_GPIO, GPIOD_IN_PULL_UP)) {
        fprintf(stderr, "Failed to set GPIO directions: %s\n", gpiod_error_string());
        gpiod_dir_close(dir);
        return 1;
    }

    // Setup signal handlers
    sigemptyset(&sigset);
    sigaddset(&sigset, SIGINT);
    sigaddset(&sigset, SIGTERM);
    if (sigaction(SIGINT, &handle_signals, NULL) == -1 ||
        sigaction(SIGTERM, &handle_signals, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpiod_dir_close(dir);
        return 1;
    }

    // Main loop
    while (1) {
        read_sensors_and_log();
        usleep(100000); // 100 ms delay
    }

    // Clean up resources
    cleanup_resources();

    return 0;
}

void setup_gpios(void) {
    // Open UART device
    if ((uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK)) < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", strerror(errno));
        return;
    }

    // Configure UART settings
    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~(CSIZE | PARENB | CSTOPB | CSIZE);
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS; // No flow control
    options.c_lflag &= ~(ICANON | ECHO); // No canonical mode, no echo

    tcsetattr(uart_fd, TCSANOW, &options);

    // Write emergency stop message
    if (write(uart_fd, "EMERGENCY STOP!\n", 13) != 13) {
        fprintf(stderr, "Failed to write to UART: %s\n", strerror(errno));
    }
}

void read_sensors_and_log(void) {
    left_sensor = gpiod_read(dir, SENSOR_LEFT_GPIO);
    middle_sensor = gpiod_read(dir, SENSOR_MIDDLE_GPIO);
    right_sensor = gpiod_read(dir, SENSOR_RIGHT_GPIO);

    if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
        // Write emergency stop message to UART
        write(UART_FD, "EMERGENCY STOP!\n", 13);
    } else {
        // Log sensor states
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
        printf("Timestamp: %s, Left: %d, Middle: %d, Right: %d\n", timestamp, left_sensor, middle_sensor, right_sensor);
    }
}

void handle_signals(int signum) {
    // Close UART
    if (uart_fd > 0) {
        close(uart_fd);
        uart_fd = -1;
    }

    // Release GPIO resources
    gpiod_dir_close(dir);

    // Terminate the program
    exit(0); // SIGINT should exit gracefully, SIGTERM can exit immediately
}

void cleanup_resources(void) {
    // Close UART if still open
    if (uart_fd > -1) {
        close(uart_fd);
        uart_fd = -1;
    }

    // Release GPIO resources
    gpiod_dir_close(dir);
}

